-- >>> BEGIN 20260426103109_16f8c3dc-186f-4ba9-ae10-6c73dfc69ee9.sql >>>
-- Helpers semânticos de RBAC.
-- Toda função é STABLE + SECURITY DEFINER + search_path fixo, alinhada com
-- as funções existentes (`is_supervisor_or_above`, `is_dev`).
-- Servem como fonte única de verdade para futuras policies de telemetria,
-- logs e conexões — proibindo regressão para `has_role(...,'admin')`.

-- 1) Auditoria interna (apenas dev)
CREATE OR REPLACE FUNCTION public.can_view_audit_logs(_user_id uuid DEFAULT auth.uid())
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT public.is_dev(_user_id)
$$;

COMMENT ON FUNCTION public.can_view_audit_logs(uuid) IS
  'Permite leitura de logs de auditoria interna (admin_audit_log). Restrito ao papel dev.';

-- 2) Telemetria, logs operacionais e quotas (supervisor+)
CREATE OR REPLACE FUNCTION public.can_view_telemetry(_user_id uuid DEFAULT auth.uid())
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT public.is_supervisor_or_above(_user_id)
$$;

COMMENT ON FUNCTION public.can_view_telemetry(uuid) IS
  'Permite leitura de telemetria, logs de IA, quotas e logs de detecção de bots. Inclui dev, supervisor, admin (legado) e manager (legado).';

-- 3) Leitura de conexões / credenciais (supervisor+)
CREATE OR REPLACE FUNCTION public.can_view_connections(_user_id uuid DEFAULT auth.uid())
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT public.is_supervisor_or_above(_user_id)
$$;

COMMENT ON FUNCTION public.can_view_connections(uuid) IS
  'Permite leitura de credenciais de integração, webhooks e controle de IP. Inclui dev, supervisor, admin (legado) e manager (legado).';

-- 4) Gestão de conexões / credenciais (supervisor+)
CREATE OR REPLACE FUNCTION public.can_manage_connections(_user_id uuid DEFAULT auth.uid())
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT public.is_supervisor_or_above(_user_id)
$$;

COMMENT ON FUNCTION public.can_manage_connections(uuid) IS
  'Permite criar/alterar/excluir credenciais de integração, webhooks e controle de IP. Mesma alçada que can_view_connections.';

-- Concede execução para roles autenticadas (default seria public, mas
-- explicitar evita surpresas com revogações futuras).
GRANT EXECUTE ON FUNCTION public.can_view_audit_logs(uuid)   TO authenticated, anon;
GRANT EXECUTE ON FUNCTION public.can_view_telemetry(uuid)    TO authenticated, anon;
GRANT EXECUTE ON FUNCTION public.can_view_connections(uuid)  TO authenticated, anon;
GRANT EXECUTE ON FUNCTION public.can_manage_connections(uuid) TO authenticated, anon;
-- <<< END 20260426103109_16f8c3dc-186f-4ba9-ae10-6c73dfc69ee9.sql <<<

-- >>> BEGIN 20260426105906_62ebcccd-ed69-4434-ace9-d9860e805dcc.sql >>>
-- ============================================================
-- Hardening: rotas técnicas (telemetria/segurança) → only dev
-- Alinha RLS com o RBAC do frontend (devOnly).
-- Edge functions usam service_role e continuam funcionando.
-- ============================================================

-- optimization_queue: era admin → dev
DROP POLICY IF EXISTS "Admins manage optimization queue" ON public.optimization_queue;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'optimization_queue' AND policyname = 'Devs manage optimization queue') THEN
    CREATE POLICY "Devs manage optimization queue"
      ON public.optimization_queue
      FOR ALL
      TO authenticated
      USING (public.is_dev(auth.uid()))
      WITH CHECK (public.is_dev(auth.uid()));
  END IF;
END $$;

-- bot_detection_log: SELECT era admin → dev (INSERT continua service_role)
DROP POLICY IF EXISTS "Admins can read bot log" ON public.bot_detection_log;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'bot_detection_log' AND policyname = 'Devs can read bot log') THEN
    CREATE POLICY "Devs can read bot log"
      ON public.bot_detection_log
      FOR SELECT
      TO authenticated
      USING (public.is_dev(auth.uid()));
  END IF;
END $$;

-- ip_access_control: ALL era admin → dev (service_role policy permanece)
DROP POLICY IF EXISTS "Admins can manage ip_access_control" ON public.ip_access_control;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'ip_access_control' AND policyname = 'Devs can manage ip_access_control') THEN
    CREATE POLICY "Devs can manage ip_access_control"
      ON public.ip_access_control
      FOR ALL
      TO authenticated
      USING (public.is_dev(auth.uid()))
      WITH CHECK (public.is_dev(auth.uid()));
  END IF;
END $$;

-- request_rate_limits: SELECT era admin → dev
DROP POLICY IF EXISTS "Admins can read rate limits" ON public.request_rate_limits;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'request_rate_limits' AND policyname = 'Devs can read rate limits') THEN
    CREATE POLICY "Devs can read rate limits"
      ON public.request_rate_limits
      FOR SELECT
      TO authenticated
      USING (public.is_dev(auth.uid()));
  END IF;
END $$;
-- <<< END 20260426105906_62ebcccd-ed69-4434-ace9-d9860e805dcc.sql <<<

-- >>> BEGIN 20260426110946_54885e21-b0d8-4667-acbd-4f5a63e7215c.sql >>>
-- RPC para registrar tentativas de acesso negado em admin_audit_log (server-side)
-- Security definer para escrever na tabela mesmo com RLS restritiva.
-- Limita: o caller só pode registrar uma tentativa em nome de SI MESMO.

CREATE OR REPLACE FUNCTION public.log_access_denied(
  _blocked_path text,
  _required_role text,
  _user_role text DEFAULT NULL,
  _reason text DEFAULT 'route_blocked'
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL THEN
    -- Não autenticado: ignora silenciosamente (não polui o log)
    RETURN;
  END IF;

  IF _required_role NOT IN ('dev','admin','supervisor') THEN
    RAISE EXCEPTION 'invalid required_role: %', _required_role;
  END IF;

  INSERT INTO public.admin_audit_log (
    user_id,
    action,
    resource_type,
    resource_id,
    status,
    source,
    started_at,
    finished_at,
    duration_ms,
    request_id,
    payload_summary,
    details
  ) VALUES (
    _uid,
    'route.access_denied',
    'route',
    _blocked_path,
    'denied',
    'frontend-guard',
    now(),
    now(),
    0,
    gen_random_uuid()::text,
    jsonb_build_object('blocked_path', _blocked_path),
    jsonb_build_object(
      'reason', _reason,
      'blocked_path', _blocked_path,
      'required_role', _required_role,
      'user_role', _user_role
    )
  );
END;
$$;

REVOKE ALL ON FUNCTION public.log_access_denied(text, text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.log_access_denied(text, text, text, text) TO authenticated;

COMMENT ON FUNCTION public.log_access_denied IS
'Registra tentativa de acesso negado a rota técnica em admin_audit_log. Chamado pelo frontend quando guardas (DevRoute/AdminRoute) bloqueiam navegação. O caller só registra em nome do próprio auth.uid().';

-- <<< END 20260426110946_54885e21-b0d8-4667-acbd-4f5a63e7215c.sql <<<

-- >>> BEGIN 20260426113207_3a3869cb-cb8b-4085-b0e1-5c5351380daa.sql >>>
-- =========================================================================
-- record_dev_route_telemetry: telemetria de UX para tela de bloqueio /dev
-- =========================================================================
-- Estratégia:
--  - Reusa admin_audit_log (não cria tabela nova) com action='route.ux_event',
--    source='dev-route-ui', resource_type='route', resource_id=<path>.
--  - Whitelist de event_type: previne logs arbitrários do cliente.
--  - Sanitização: clamp em duration_ms (0..3600000), limita tamanho de path
--    e role, ignora qualquer payload do cliente além do que a função monta.
--  - Rate limit: máx 30 eventos/minuto/usuário (defesa contra spam).
--  - SECURITY DEFINER + RLS de SELECT já restringe leitura a is_dev().

CREATE OR REPLACE FUNCTION public.record_dev_route_telemetry(
  _event_type    text,
  _blocked_path  text,
  _user_role     text DEFAULT NULL,
  _duration_ms   integer DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  _uid uuid := auth.uid();
  _safe_path text;
  _safe_role text;
  _safe_duration integer;
  _recent_count integer;
  _allowed_events constant text[] := ARRAY[
    'view',           -- usuário viu a tela 403
    'back',           -- clicou em "Voltar" (history -1)
    'retry',          -- clicou em "Tentar novamente" (mesmo path)
    'fallback',       -- foi para área segura (Início/Usuários/Catálogo)
    'request_access', -- clicou em "Solicitar acesso a Dev"
    'copy_link',      -- copiou o link da rota bloqueada
    'mail',           -- abriu cliente de e-mail
    'abandon'         -- saiu/fechou a aba (best-effort beacon)
  ];
BEGIN
  -- 1) Anônimo: ignora silenciosamente (não polui audit log).
  IF _uid IS NULL THEN
    RETURN;
  END IF;

  -- 2) Whitelist de event_type (defense-in-depth).
  IF NOT (_event_type = ANY (_allowed_events)) THEN
    RAISE EXCEPTION 'invalid event_type: %', _event_type
      USING ERRCODE = '22023';
  END IF;

  -- 3) Sanitização (sem PII):
  --    - path: trim + corta em 200 chars (rotas internas são curtas).
  --    - role: corta em 32 chars; só aceita papéis conhecidos.
  --    - duration_ms: clamp em [0, 3_600_000] (1h).
  _safe_path := substring(coalesce(_blocked_path, '') from 1 for 200);
  IF length(_safe_path) = 0 THEN
    RAISE EXCEPTION 'blocked_path required' USING ERRCODE = '22023';
  END IF;

  _safe_role := substring(coalesce(_user_role, '') from 1 for 32);
  IF _safe_role NOT IN ('dev','admin','supervisor','agente','agent','vendedor','') THEN
    _safe_role := 'unknown';
  END IF;
  IF length(_safe_role) = 0 THEN
    _safe_role := NULL;
  END IF;

  IF _duration_ms IS NULL THEN
    _safe_duration := NULL;
  ELSIF _duration_ms < 0 THEN
    _safe_duration := 0;
  ELSIF _duration_ms > 3600000 THEN
    _safe_duration := 3600000;
  ELSE
    _safe_duration := _duration_ms;
  END IF;

  -- 4) Rate limit por usuário: 30 eventos/min.
  --    Usa o mesmo log para evitar tabela auxiliar.
  SELECT count(*) INTO _recent_count
  FROM public.admin_audit_log
  WHERE user_id = _uid
    AND action  = 'route.ux_event'
    AND source  = 'dev-route-ui'
    AND created_at > now() - interval '1 minute';

  IF _recent_count >= 30 THEN
    -- Excede orçamento: descarta silenciosamente para não amplificar abuso.
    RETURN;
  END IF;

  -- 5) Insere o evento. payload_summary intencionalmente mínimo (sem
  --    user_agent/IP/email — esses campos só são preenchidos por edge
  --    functions com service role e contexto de request).
  INSERT INTO public.admin_audit_log (
    user_id,
    action,
    resource_type,
    resource_id,
    status,
    source,
    started_at,
    finished_at,
    duration_ms,
    request_id,
    payload_summary,
    details
  ) VALUES (
    _uid,
    'route.ux_event',
    'route',
    _safe_path,
    CASE WHEN _event_type IN ('view','abandon','copy_link','mail') THEN 'denied'
         WHEN _event_type IN ('back','retry','fallback')           THEN 'partial'
         WHEN _event_type = 'request_access'                       THEN 'success'
         ELSE 'denied' END,
    'dev-route-ui',
    now(),
    now(),
    _safe_duration,
    gen_random_uuid()::text,
    jsonb_build_object(
      'event_type',   _event_type,
      'blocked_path', _safe_path
    ),
    jsonb_build_object(
      'event_type',   _event_type,
      'blocked_path', _safe_path,
      'user_role',    _safe_role,
      'duration_ms',  _safe_duration
    )
  );
END;
$$;

-- Apenas usuários autenticados podem invocar (anônimos são ignorados de qualquer forma).
REVOKE ALL ON FUNCTION public.record_dev_route_telemetry(text, text, text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_dev_route_telemetry(text, text, text, integer)
  TO authenticated;

COMMENT ON FUNCTION public.record_dev_route_telemetry(text, text, text, integer) IS
  'Telemetria de UX da tela DevRoute (403). Whitelist de event_type, sem PII, rate-limited (30/min/user).';
