-- >>> BEGIN 20260511200038_create_painel_cotacoes_schema.sql >>>
-- ============================================================
--  Painel de Cotação Multi-Transportadora — Schema inicial
--  Onda 2 antecipada: persistência + auth + RLS
-- ============================================================
--
-- Nota de sincronização (2026-05-12, T19 redeploy Fase 1):
-- Esta migration foi aplicada diretamente no banco produção via
-- MCP `apply_migration` em 2026-05-11 e ficou órfã no repo.
-- Conteúdo aqui é cópia fiel do que vive em `supabase_migrations.schema_migrations`
-- para reduzir o desync repo↔DB flagado pela auditoria (PR #154).
-- ============================================================

create table if not exists public.cotacoes (
  id                       uuid primary key default gen_random_uuid(),
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),

  -- quem cotou (FK pra auth.users)
  user_id                  uuid not null references auth.users(id) on delete restrict,
  responsavel_nome         text not null,    -- snapshot do nome (não muda se user mudar metadata)
  responsavel_role         text,             -- snapshot da role (admin/cotacao)

  -- cotação escolhida
  transportadora_escolhida text not null,
  numero_cotacao           text,
  preco_total              numeric(12,2) not null,
  prazo_dias               int not null,

  -- contexto completo
  remetente                jsonb not null,   -- {nome, cnpj, cep}
  destinatario             jsonb not null,   -- {nome, cnpj, cep, cidade, uf}
  carga                    jsonb not null,   -- {caixas[], pesoTotal, qtdVolumes, valorNF}
  todas_cotacoes           jsonb,            -- snapshot dos 6 ramos pra auditoria

  -- workflow
  status                   text not null default 'cotado'
    check (status in ('cotado','contratado','cancelado')),
  origem                   text not null default 'PORTAL',
  observacoes              text
);

-- Trigger: atualiza updated_at automaticamente
create or replace function public.tg_set_updated_at()
returns trigger language plpgsql as $fn$
begin
  new.updated_at = now();
  return new;
end;
$fn$;

drop trigger if exists trg_cotacoes_updated_at on public.cotacoes;
create trigger trg_cotacoes_updated_at
  before update on public.cotacoes
  for each row execute function public.tg_set_updated_at();

-- Indexes
create index if not exists idx_cotacoes_created_at on public.cotacoes(created_at desc);
create index if not exists idx_cotacoes_user_id    on public.cotacoes(user_id);
create index if not exists idx_cotacoes_status     on public.cotacoes(status);
create index if not exists idx_cotacoes_transp     on public.cotacoes(transportadora_escolhida);

-- ============================================================
--  RLS — Row Level Security
--  Política: transparência interna (todos autenticados veem tudo)
--           mas só admin pode UPDATE/DELETE alheio.
-- ============================================================

alter table public.cotacoes enable row level security;

-- Helper: ver role do user logado
create or replace function public.current_user_role()
returns text language sql stable as $fn$
  select coalesce(
    (auth.jwt() -> 'user_metadata' ->> 'role'),
    'cotacao'
  );
$fn$;

-- SELECT: qualquer autenticado vê tudo (transparência interna)
drop policy if exists "cotacoes_select_authenticated" on public.cotacoes;
create policy "cotacoes_select_authenticated"
  on public.cotacoes for select
  to authenticated
  using (true);

-- INSERT: autenticado pode inserir, user_id deve = auth.uid()
drop policy if exists "cotacoes_insert_self" on public.cotacoes;
create policy "cotacoes_insert_self"
  on public.cotacoes for insert
  to authenticated
  with check (user_id = auth.uid());

-- UPDATE: dono ou admin
drop policy if exists "cotacoes_update_owner_or_admin" on public.cotacoes;
create policy "cotacoes_update_owner_or_admin"
  on public.cotacoes for update
  to authenticated
  using (user_id = auth.uid() or public.current_user_role() = 'admin')
  with check (user_id = auth.uid() or public.current_user_role() = 'admin');

-- DELETE: NINGUÉM (nem admin) — auditoria
-- (sem policy = bloqueado por RLS)

comment on table public.cotacoes is
  'Cotações de frete realizadas via painel log.atomicabr.com.br. Auditoria — não deletar.';

-- <<< END 20260511200038_create_painel_cotacoes_schema.sql <<<

-- >>> BEGIN 20260511200050_fix_handle_new_user_profiles_id.sql >>>
-- Fix handle_new_user() to explicitly set profiles.id = NEW.id
-- This ensures the NOT NULL constraint on profiles.id is satisfied on a clean DB
-- (profiles.id was created without DEFAULT in the first migration).
CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $$
BEGIN
  INSERT INTO public.profiles (id, user_id, email, full_name)
  VALUES (
    NEW.id,
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', '')
  )
  ON CONFLICT (id) DO UPDATE SET
    user_id = EXCLUDED.user_id,
    email   = COALESCE(EXCLUDED.email, public.profiles.email),
    full_name = COALESCE(EXCLUDED.full_name, public.profiles.full_name);

  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, 'vendedor')
  ON CONFLICT (user_id, role) DO NOTHING;

  RETURN NEW;
END;
$$;

-- <<< END 20260511200050_fix_handle_new_user_profiles_id.sql <<<

-- >>> BEGIN 20260511200056_create_painel_users.sql >>>
-- ============================================================
--  Criar usuários do painel de cotação (Gap A — sincronizado em 2026-05-12)
--
--  ORIGEM: migration aplicada via MCP em 2026-05-11 (sem arquivo .sql no repo).
--  SQL recuperado de supabase_migrations.schema_migrations.statements[].
--
--  SEGURANÇA: versão original usava senha padrão fixada em texto.
--  Esta versão commita com senha ALEATÓRIA (inloggável sem reset).
--  Para definir senhas reais, use o Supabase Dashboard:
--    Authentication > Users > Reset Password
--  Ou via CLI: supabase auth admin update-user <user_id> --password <nova>
--
--  IDEMPOTÊNCIA: cada INSERT é guardado por "IF NOT EXISTS" — re-execução
--  segura em ambientes de dev/staging.
-- ============================================================

DO $$
DECLARE
  v_user_id  uuid;
  v_email    text;
  v_nome     text;
  v_role     text;
  v_users    record;
BEGIN
  FOR v_users IN
    SELECT * FROM (VALUES
      ('joaquim@promobrindes.com.br',   'Joaquim (Pink)', 'admin'),
      ('tiago@promobrindes.com.br',     'Tiago',          'cotacao'),
      ('marcus@promobrindes.com.br',    'Marcus',         'cotacao'),
      ('gabryelly@promobrindes.com.br', 'Gabryelly',      'cotacao')
    ) AS t(email, nome, role)
  LOOP
    v_email := v_users.email;
    v_nome  := v_users.nome;
    v_role  := v_users.role;

    -- Pula se já existe (idempotência)
    IF EXISTS (SELECT 1 FROM auth.users WHERE email = v_email) THEN
      RAISE NOTICE 'Usuário % já existe, pulando.', v_email;
      CONTINUE;
    END IF;

    v_user_id := gen_random_uuid();

    -- 1) Cria entrada em auth.users com senha ALEATÓRIA (bcrypt de UUID).
    --    Senha não pode ser derivada nem por força bruta — reset obrigatório.
    INSERT INTO auth.users (
      instance_id, id, aud, role, email,
      encrypted_password, email_confirmed_at,
      raw_user_meta_data, raw_app_meta_data,
      created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change
    ) VALUES (
      '00000000-0000-0000-0000-000000000000'::uuid,
      v_user_id,
      'authenticated', 'authenticated',
      v_email,
      crypt(gen_random_uuid()::text, gen_salt('bf')),   -- senha aleatória — requer reset
      now(),
      jsonb_build_object(
        'nome',           v_nome,
        'role',           v_role,
        'email_verified', true,
        'app',            'painel-cotacoes'
      ),
      jsonb_build_object(
        'provider',  'email',
        'providers', jsonb_build_array('email')
      ),
      now(), now(),
      '', '', '', ''
    );

    -- 2) Cria identity (provider email) — necessário para login funcionar
    INSERT INTO auth.identities (
      id, user_id, identity_data, provider, provider_id,
      last_sign_in_at, created_at, updated_at
    ) VALUES (
      gen_random_uuid(),
      v_user_id,
      jsonb_build_object(
        'sub',            v_user_id::text,
        'email',          v_email,
        'email_verified', true
      ),
      'email',
      v_email,
      now(), now(), now()
    );

    RAISE NOTICE 'Usuário % criado (id=%). ATENÇÃO: senha aleatória — use Dashboard para redefinir.', v_email, v_user_id;
  END LOOP;
END $$;

-- <<< END 20260511200056_create_painel_users.sql <<<

