-- >>> BEGIN 20260512000009_t33_revoke_anon_execute_public_functions.sql >>>
-- T33: Remove explicit anon EXECUTE grants on all public-schema functions
-- service_role and authenticated roles are unaffected.
-- Prevents unauthenticated callers from invoking elevated-privilege functions.
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA public FROM anon;

-- <<< END 20260512000009_t33_revoke_anon_execute_public_functions.sql <<<

-- >>> BEGIN 20260512000010_t33b_revoke_public_grant_authenticated.sql >>>
-- T33b: Remove PUBLIC default EXECUTE on all public-schema functions,
-- then explicitly grant to authenticated and service_role only.
-- anon role gets no EXECUTE privilege via PUBLIC inheritance either.
-- Advisor target: anon_security_definer_function_executable = 0
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC;
GRANT  EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO authenticated;
GRANT  EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO service_role;

-- <<< END 20260512000010_t33b_revoke_public_grant_authenticated.sql <<<

-- >>> BEGIN 20260512000011_t34_move_unaccent_to_extensions_schema.sql >>>
-- T34: Move unaccent extension from public schema to extensions schema
-- Fixes: extension_in_public advisor violation
-- 57 functions used unaccent() without schema prefix; their search_path is
-- updated to include extensions so they continue to resolve correctly.

-- Step 1: Add 'extensions' to search_path for all functions that call
--         unaccent() without schema qualification
DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT p.proname,
           pg_get_function_identity_arguments(p.oid) AS args,
           n.nspname
    FROM pg_proc p
    JOIN pg_namespace n ON p.pronamespace = n.oid
    WHERE p.prosrc ILIKE '%unaccent(%'
      AND p.prosrc NOT ILIKE '%extensions.unaccent(%'
      AND p.proconfig IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM unnest(p.proconfig) v
        WHERE v LIKE 'search_path=%'
          AND v NOT LIKE '%extensions%'
      )
  LOOP
    EXECUTE format(
      'ALTER FUNCTION %I.%I(%s) SET search_path TO public, extensions',
      r.nspname, r.proname, r.args
    );
  END LOOP;
END $$;

-- Step 2: Drop extension CASCADE — also drops dependent views:
--         public.v_category_keywords, public.v_product_tokens
DROP EXTENSION IF EXISTS unaccent CASCADE;

-- Step 3: Recreate extension in extensions schema
CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA extensions;

-- Step 4: Recreate views (migration search_path includes extensions,
--         so bare unaccent() resolves to extensions.unaccent())
DO $$
BEGIN
  EXECUTE $view$
    CREATE OR REPLACE VIEW public.v_category_keywords AS
     WITH tokens AS (
       SELECT c.id AS category_id,
          c.full_path_readable,
          c.level,
          c.name AS category_name,
          unnest(regexp_split_to_array(lower(unaccent(c.name)), '[\s\|>/,\.\-]+'::text)) AS token
       FROM categories c
       WHERE c.is_active
     )
     SELECT category_id,
        full_path_readable,
        category_name,
        level,
        token
     FROM tokens
     WHERE (length(token) >= 3)
       AND (token <> ALL (ARRAY['de','da','do','das','dos','com','sem','para',
                                'por','que','brindes','kit','tipo','uso','pcs',
                                'pecas','unidade']::text[]))
  $view$;
EXCEPTION WHEN undefined_table OR undefined_column OR undefined_function THEN NULL;
END $$;

DO $$
BEGIN
  EXECUTE $view$
    CREATE OR REPLACE VIEW public.v_product_tokens AS
     WITH tokens AS (
       SELECT p.id AS product_id,
          p.name AS product_name,
          p.is_active,
          unnest(regexp_split_to_array(lower(unaccent(((p.name || ' '::text) || COALESCE(p.description, ''::text)))), '[\s\|>/,\.\-()0-9]+'::text)) AS token
       FROM products p
       WHERE p.is_active
     )
     SELECT product_id,
        product_name,
        token
     FROM tokens
     WHERE (length(token) >= 3)
       AND (token <> ALL (ARRAY['de','da','do','das','dos','com','sem','para','por','que',
                                'mais','cor','cores','tipo','uso','seu','sua','como','tem',
                                'gramatura','dimensoes','medidas','aprox','aproximadamente',
                                'tamanho','unidade','unidades','peca','pecas','kit','kits',
                                'varias','variadas','novo','novidade','novos','produto',
                                'produtos','item','marca','sobre','material']::text[]))
  $view$;
EXCEPTION WHEN undefined_table OR undefined_column OR undefined_function THEN NULL;
END $$;

-- <<< END 20260512000011_t34_move_unaccent_to_extensions_schema.sql <<<

-- >>> BEGIN 20260512000012_t34b_set_views_security_invoker.sql >>>
-- T34b: Set v_category_keywords and v_product_tokens to SECURITY INVOKER
-- Views recreated in T34 defaulted to SECURITY DEFINER (pre-PG15 default);
-- setting security_invoker=true ensures RLS is enforced for the querying user.
-- Fixes: security_definer_view advisor violation (2 issues)
DO $$ BEGIN
  ALTER VIEW public.v_category_keywords SET (security_invoker = true);
EXCEPTION WHEN undefined_table THEN NULL;
END $$;
DO $$ BEGIN
  ALTER VIEW public.v_product_tokens SET (security_invoker = true);
EXCEPTION WHEN undefined_table THEN NULL;
END $$;

-- <<< END 20260512000012_t34b_set_views_security_invoker.sql <<<

-- >>> BEGIN 20260512000013_t35_fix_material_groups_rls_broken_subquery.sql >>>
-- T35: Fix broken RLS subquery in material_groups policies
-- Bug found in T25b: policies used a correlated subquery referencing the outer
-- table's column (material_groups.organization_id) inside FROM profiles, which
-- caused the condition to always evaluate as true → cross-tenant data exposure.
-- Fix: replace the broken subquery with the standard current_setting pattern.
--
-- Wrapped in DO ... EXCEPTION to be idempotent across Preview/Prod (some
-- environments may not have the table yet — Preview builds fresh DB from
-- git migrations, but material_groups was created in PROD outside of git
-- and has no CREATE TABLE migration committed). Catches undefined_table,
-- undefined_object, undefined_function, undefined_column. Aligns with the
-- T25/T26/T30 hardening migrations.

DO $$
BEGIN
  ALTER POLICY "mg_select" ON public.material_groups
    USING (organization_id = (SELECT current_setting('app.current_org_id'::text, true))::uuid);
EXCEPTION WHEN undefined_table OR undefined_object OR undefined_function OR undefined_column THEN NULL;
END $$;

DO $$
BEGIN
  ALTER POLICY "mg_insert" ON public.material_groups
    WITH CHECK (organization_id = (SELECT current_setting('app.current_org_id'::text, true))::uuid);
EXCEPTION WHEN undefined_table OR undefined_object OR undefined_function OR undefined_column THEN NULL;
END $$;

DO $$
BEGIN
  ALTER POLICY "mg_update" ON public.material_groups
    USING (organization_id = (SELECT current_setting('app.current_org_id'::text, true))::uuid)
    WITH CHECK (organization_id = (SELECT current_setting('app.current_org_id'::text, true))::uuid);
EXCEPTION WHEN undefined_table OR undefined_object OR undefined_function OR undefined_column THEN NULL;
END $$;

DO $$
BEGIN
  ALTER POLICY "mg_delete" ON public.material_groups
    USING (organization_id = (SELECT current_setting('app.current_org_id'::text, true))::uuid);
EXCEPTION WHEN undefined_table OR undefined_object OR undefined_function OR undefined_column THEN NULL;
END $$;

-- <<< END 20260512000013_t35_fix_material_groups_rls_broken_subquery.sql <<<

-- >>> BEGIN 20260512000014_t36_alter_default_privileges_functions.sql >>>
-- T36: Set default privileges so future functions in public schema do not
-- inherit EXECUTE from PUBLIC. New functions will only be callable by
-- authenticated and service_role (mirrors T33b for existing functions).
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  GRANT EXECUTE ON FUNCTIONS TO authenticated;

ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  GRANT EXECUTE ON FUNCTIONS TO service_role;

-- <<< END 20260512000014_t36_alter_default_privileges_functions.sql <<<

