            WHEN v_name ~ 'METAL|ALUMINIO|INOX' THEN 'metal'
            WHEN v_name ~ 'VIDRO|GLASS' THEN 'vidro'
            WHEN v_name ~ 'ACRILICO|ACRYLIC' THEN 'acrilico'
