INSERT INTO public.user_organizations (user_id, organization_id, role)
SELECT
  u.id,
  o.id,
  (CASE WHEN u.email = 'cad01@promobrindes.com.br' THEN 'admin' ELSE 'member' END)::org_role
FROM auth.users u
