-- LOTE F 1/4
ALTER TABLE public.bot_detection_log ADD COLUMN IF NOT EXISTS blocked boolean NOT NULL DEFAULT false;

CREATE OR REPLACE FUNCTION public.record_public_token_failure(_resource_type text, _resource_id text, _attempted_token text, _ip text, _ua text, _reason text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE _recent_failures int;
BEGIN
  INSERT INTO public.public_token_failures (resource_type,resource_id,attempted_token,ip_address,user_agent,reason)
  VALUES (_resource_type,_resource_id,_attempted_token,_ip,_ua,_reason);
  IF _resource_id IS NULL THEN RETURN; END IF;
  SELECT count(*) INTO _recent_failures FROM public.public_token_failures
  WHERE resource_type=_resource_type AND resource_id=_resource_id AND created_at > now()-interval '1 hour';
  IF _recent_failures >= 5 THEN
    IF _resource_type='quote' THEN
      UPDATE public.quote_approval_tokens SET status='expired',updated_at=now() WHERE quote_id=_resource_id AND status='active';
    ELSIF _resource_type='kit' THEN
      UPDATE public.kit_share_tokens SET status='expired',updated_at=now() WHERE kit_id::text=_resource_id AND status='active';
    END IF;
  END IF;
END; $$;
REVOKE EXECUTE ON FUNCTION public.record_public_token_failure(text,text,text,text,text,text) FROM PUBLIC, anon, authenticated;

-- <<< END 20260522114546_lote_f_01_bot_detection_log_blocked_e_record_failure.sql <<<

-- >>> BEGIN 20260522114608_lote_f_02_funcoes_cleanup_periodico.sql >>>
-- LOTE F 2/4 - cleanup functions
CREATE OR REPLACE FUNCTION public.cleanup_security_logs()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
DECLARE _tf int:=0; _bl int:=0; _al int:=0; _ip int:=0;
BEGIN
  WITH d AS (DELETE FROM public.public_token_failures WHERE created_at < now()-interval '90 days' RETURNING 1) SELECT count(*) INTO _tf FROM d;
  WITH d AS (DELETE FROM public.bot_detection_log WHERE created_at < now()-interval '90 days' RETURNING 1) SELECT count(*) INTO _bl FROM d;
  WITH d AS (DELETE FROM public.admin_audit_log WHERE created_at < now()-interval '365 days' RETURNING 1) SELECT count(*) INTO _al FROM d;
  WITH d AS (DELETE FROM public.ip_access_control WHERE expires_at IS NOT NULL AND expires_at < now()-interval '30 days' RETURNING 1) SELECT count(*) INTO _ip FROM d;
  RETURN jsonb_build_object('ok',true,'ran_at',now(),'public_token_failures_deleted',_tf,'bot_detection_log_deleted',_bl,'admin_audit_log_deleted',_al,'ip_access_control_expired_deleted',_ip);
END; $$;
REVOKE EXECUTE ON FUNCTION public.cleanup_security_logs() FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.purge_expired_security_data()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  PERFORM public.purge_expired_step_up_artifacts(60,60);
  DELETE FROM public.login_attempts WHERE created_at < now()-interval '90 days';
END; $$;
REVOKE EXECUTE ON FUNCTION public.purge_expired_security_data() FROM PUBLIC, anon, authenticated;

