-- >>> BEGIN 20260524135957_fix_user_organizations_rls_infinite_recursion.sql >>>
-- ============================================================================
-- FIX: infinite recursion in policy for relation "user_organizations"
-- ============================================================================
-- Causa: a policy uo_select_members faz EXISTS SELECT em user_organizations
-- DENTRO da própria policy de user_organizations, criando loop infinito.
-- Mesma situação para as funções helper que faziam SELECT em
-- user_organizations sem SECURITY DEFINER.
--
-- Sintoma: GET /rest/v1/quotes retornava 500 (e qualquer query que use
-- user_is_org_member ou is_org_owner_or_admin acabava recursando).
--
-- Solução:
-- 1) Tornar as funções helper SECURITY DEFINER (bypass RLS apenas para
--    a checagem de membership — funções continuam STABLE e read-only).
-- 2) Reescrever a policy uo_select_members usando user_is_org_member,
--    evitando subquery direta na própria tabela.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1) SECURITY DEFINER nas funções helper que tocam user_organizations
-- ----------------------------------------------------------------------------
-- Essas funções já têm:
--   - LANGUAGE sql / plpgsql (não dinâmico)
--   - STABLE (sem efeitos colaterais)
--   - SET search_path TO 'public' (proteção contra path injection)
--   - Apenas SELECT (read-only)
-- Logo, SECURITY DEFINER é seguro aqui e resolve o loop de RLS.

ALTER FUNCTION public.user_is_org_member(uuid) SECURITY DEFINER;
ALTER FUNCTION public.is_org_owner_or_admin(uuid) SECURITY DEFINER;
ALTER FUNCTION public.is_org_member(uuid, uuid) SECURITY DEFINER;

-- ----------------------------------------------------------------------------
-- 2) Reescrever a policy uo_select_members removendo a auto-referência
-- ----------------------------------------------------------------------------
-- A policy antiga fazia:
--   EXISTS (SELECT 1 FROM user_organizations uo2 WHERE ...)
-- Isso disparava RLS recursivo. Agora usamos user_is_org_member que,
-- com SECURITY DEFINER, faz a checagem sem disparar RLS.

DROP POLICY IF EXISTS uo_select_members ON public.user_organizations;

CREATE POLICY uo_select_members ON public.user_organizations
  FOR SELECT
  USING (public.user_is_org_member(organization_id));

-- ----------------------------------------------------------------------------
-- 3) Comentários para auditoria futura
-- ----------------------------------------------------------------------------
COMMENT ON FUNCTION public.user_is_org_member(uuid) IS
  'SECURITY DEFINER necessário para evitar recursão de RLS quando '
  'usada em policies de user_organizations. Read-only, STABLE, '
  'search_path fixo. Continua usando auth.uid() do JWT do request.';

COMMENT ON FUNCTION public.is_org_owner_or_admin(uuid) IS
  'SECURITY DEFINER necessário para evitar recursão de RLS quando '
  'usada em policies de user_organizations. Read-only, STABLE.';

COMMENT ON FUNCTION public.is_org_member(uuid, uuid) IS
  'SECURITY DEFINER por consistência com user_is_org_member. '
  'Read-only, STABLE.';

-- <<< END 20260524135957_fix_user_organizations_rls_infinite_recursion.sql <<<

-- >>> BEGIN 20260524202319_add_product_webhook_nonces.sql >>>
CREATE TABLE IF NOT EXISTS public.webhook_request_nonces (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  source TEXT NOT NULL,
  nonce TEXT NOT NULL,
  request_timestamp TIMESTAMPTZ NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(source, nonce)
);

CREATE INDEX IF NOT EXISTS idx_webhook_request_nonces_expires_at
  ON public.webhook_request_nonces(expires_at);

ALTER TABLE public.webhook_request_nonces ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.webhook_request_nonces FROM anon, authenticated;
GRANT SELECT, INSERT, DELETE ON TABLE public.webhook_request_nonces TO service_role;

DROP POLICY IF EXISTS "service_role_manage_webhook_request_nonces"
  ON public.webhook_request_nonces;
CREATE POLICY "service_role_manage_webhook_request_nonces"
  ON public.webhook_request_nonces
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

CREATE OR REPLACE FUNCTION public.cleanup_expired_webhook_request_nonces()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM public.webhook_request_nonces
  WHERE expires_at < now();

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;

REVOKE ALL ON FUNCTION public.cleanup_expired_webhook_request_nonces() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.cleanup_expired_webhook_request_nonces() TO service_role;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'cleanup-product-webhook-nonces-hourly') THEN
    PERFORM cron.unschedule('cleanup-product-webhook-nonces-hourly');
  END IF;

  PERFORM cron.schedule(
    'cleanup-product-webhook-nonces-hourly',
    '17 * * * *',
    $cron$ SELECT public.cleanup_expired_webhook_request_nonces(); $cron$
  );
END;
$$;

-- <<< END 20260524202319_add_product_webhook_nonces.sql <<<

-- >>> BEGIN 20260524202328_products_external_id_and_unique_keys.sql >>>
-- Define consistent unique keys for the product webhook upsert strategy.
-- Rule:
-- 1) external_id is the preferred identity when provided.
-- 2) sku is the fallback identity when external_id is null.
--
-- Context / drift fix:
-- The product-webhook edge function upserts with onConflict:'external_id'
-- and onConflict:'sku', and the generated TS types declare products.external_id.
-- However the column was absent in production (earlier ADD COLUMN migrations
-- were recorded as applied but did not persist), which broke the external_id
-- upsert path. This migration restores the column and the unique key it needs.
-- The sku side is already covered by the existing unique index products_sku_key,
-- so we do not create a duplicate index for it.

ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS external_id TEXT;

-- Partial unique index: enforces uniqueness only for rows that carry an
-- external_id, allowing the sku-only fallback path to coexist.
CREATE UNIQUE INDEX IF NOT EXISTS ux_products_external_id_not_null
  ON public.products (external_id)
  WHERE external_id IS NOT NULL;

-- <<< END 20260524202328_products_external_id_and_unique_keys.sql <<<

-- >>> BEGIN 20260524202338_fix_purge_expired_security_data_signature.sql >>>
-- Fix broken security purge cron (job: purge-expired-security, every 15 min).
--
-- purge_expired_security_data() called purge_expired_step_up_artifacts(60, 60),
-- but that function exists only with a zero-argument signature. The call aborted
-- on the first statement (96 failures/24h, 0 successes), so expired step-up
-- artifacts were never purged and old login_attempts were never cleaned.
--
-- Fix: call the existing zero-argument signature.

CREATE OR REPLACE FUNCTION public.purge_expired_security_data()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- Limpa artefatos de step-up via helper existente (assinatura sem argumentos)
  PERFORM public.purge_expired_step_up_artifacts();

  -- Limpa tentativas de login antigas (90 dias)
  DELETE FROM public.login_attempts WHERE created_at < now() - interval '90 days';
END;
$function$;

-- <<< END 20260524202338_fix_purge_expired_security_data_signature.sql <<<

-- >>> BEGIN 20260524204127_colapso_p0_fix_cron_security_purge_20260524.sql >>>
-- =============================================================
-- P0.1 — Forçar invalidação de plan cache do cron worker
-- Bug: cron job "purge-expired-security" chama `purge_expired_step_up_artifacts(60, 60)`,
-- assinatura que NÃO EXISTE no banco (a função real é sem args).
-- O def atual de purge_expired_security_data já está correto, mas o plan cache do
-- pg_cron worker ficou "zumbi". DROP + CREATE força replan.
-- =============================================================
DROP FUNCTION IF EXISTS public.purge_expired_security_data();

CREATE OR REPLACE FUNCTION public.purge_expired_security_data()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_purged_step_up integer;
  v_purged_logins  integer;
BEGIN
  v_purged_step_up := public.purge_expired_step_up_artifacts();

  DELETE FROM public.login_attempts
   WHERE created_at < now() - interval '90 days';
  GET DIAGNOSTICS v_purged_logins = ROW_COUNT;

  -- Telemetria leve em audit_log para diagnóstico futuro
  PERFORM 1; -- placeholder; o ROW_COUNT serve aos logs do cron
END;
$function$;

COMMENT ON FUNCTION public.purge_expired_security_data() IS
'Limpeza periódica de artefatos de segurança. Recriada em 2026-05-24 para invalidar plan cache do pg_cron worker que chamava assinatura inexistente (60, 60).';

-- <<< END 20260524204127_colapso_p0_fix_cron_security_purge_20260524.sql <<<

-- >>> BEGIN 20260524204148_colapso_p0_kill_switch_table_20260524.sql >>>
-- =============================================================
-- P0.2 — Tabela de kill-switches para parar tráfego em edge functions
-- legadas (ex.: external-db-bridge — Caminho B já migrou para PostgREST nativo,
-- mas a edge function continua sendo chamada por clientes legados, em LOOP,
-- gerando 30-50 invocações/segundo e saturando o pool de conexões).
--
-- Edge functions devem checar esta tabela no início e retornar 410 Gone
-- se estiverem desabilitadas. A leitura é pública (anon/authenticated)
-- pois a checagem precisa ocorrer cedo na request, sem JWT validado ainda.
-- =============================================================
CREATE TABLE IF NOT EXISTS public.system_kill_switches (
  switch_name        text PRIMARY KEY,
  enabled            boolean NOT NULL DEFAULT true,
  reason             text,
  legacy_message     text,
  updated_at         timestamptz NOT NULL DEFAULT now(),
  updated_by         uuid REFERENCES auth.users(id) ON DELETE SET NULL
);

ALTER TABLE public.system_kill_switches ENABLE ROW LEVEL SECURITY;

-- Leitura pública (para edge functions checarem rapidamente)
DROP POLICY IF EXISTS "kill_switches_read_all" ON public.system_kill_switches;
CREATE POLICY "kill_switches_read_all"
  ON public.system_kill_switches
  FOR SELECT
  USING (true);

-- Escrita apenas admins
DROP POLICY IF EXISTS "kill_switches_write_admin" ON public.system_kill_switches;
CREATE POLICY "kill_switches_write_admin"
  ON public.system_kill_switches
  FOR ALL
  USING (public.is_admin_or_above((SELECT auth.uid())))
  WITH CHECK (public.is_admin_or_above((SELECT auth.uid())));

GRANT SELECT ON public.system_kill_switches TO anon, authenticated, service_role;
GRANT ALL ON public.system_kill_switches TO postgres;

-- Pré-popular com o switch para external-db-bridge (DESABILITADO por padrão)
INSERT INTO public.system_kill_switches (switch_name, enabled, reason, legacy_message)
VALUES (
  'edge_external_db_bridge',
  false,  -- DESABILITADO: força front-ends legados a migrar para PostgREST nativo (Caminho B)
  'Substituída pelo Caminho B: PostgREST nativo. PRs #230-232 do antigo repo Promo_Gifts.',
  'A função external-db-bridge foi descontinuada. Use chamadas REST nativas em /rest/v1/.'
)
ON CONFLICT (switch_name) DO NOTHING;

COMMENT ON TABLE public.system_kill_switches IS
'Switches para desligar features/edge-functions legadas a quente. Edge functions devem checar esta tabela antes de processar.';

