-- >>> BEGIN 20260524204159_colapso_p0_fix_profiles_select_policy_20260524.sql >>>
-- =============================================================
-- P0.3 — Corrigir policy profiles_select
-- Problema: policy `profiles_select` chama is_admin_or_above((SELECT auth.uid()))
-- mas anon NÃO TEM EXECUTE em is_admin_or_above → SELECT anônimo falha com
-- "permission denied for function is_admin_or_above" (confirmado pelo smoke test).
-- Correção: restringir policy a authenticated apenas (anon não tem nada a fazer
-- em profiles), aproveitando para nivelar a regra a só usuários logados.
-- =============================================================
DROP POLICY IF EXISTS "profiles_select" ON public.profiles;

CREATE POLICY "profiles_select"
  ON public.profiles
  FOR SELECT
  TO authenticated
  USING (
    ((SELECT auth.uid()) = id)
    OR public.is_admin_or_above((SELECT auth.uid()))
  );

-- <<< END 20260524204159_colapso_p0_fix_profiles_select_policy_20260524.sql <<<

-- >>> BEGIN 20260524204210_colapso_p0_rotacionar_cron_job_run_details_20260524.sql >>>
-- =============================================================
-- P0.4 — Rotacionar cron.job_run_details (33 MB / 91k linhas)
-- Mantém apenas últimos 14 dias. Cria job de manutenção semanal.
-- =============================================================
DELETE FROM cron.job_run_details
 WHERE start_time < now() - interval '14 days';

-- Schedulando rotação semanal (domingo 04:00)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname='cron_job_run_details_purge_weekly') THEN
    PERFORM cron.schedule(
      'cron_job_run_details_purge_weekly',
      '0 4 * * 0',
      $cmd$ DELETE FROM cron.job_run_details WHERE start_time < now() - interval '14 days' $cmd$
    );
  END IF;
END$$;

-- <<< END 20260524204210_colapso_p0_rotacionar_cron_job_run_details_20260524.sql <<<

