-- >>> BEGIN 20260524210300_kill_switches_fk_index_and_policy_consolidation.sql >>>
-- system_kill_switches: índice de FK ausente + consolidação de policies (colapso 2026-05-24, fase E).
--
-- Advisors:
--   * performance/unindexed_foreign_keys → system_kill_switches.updated_by sem índice.
--   * performance/multiple_permissive_policies (6x, SELECT) → `kill_switches_read_all`
--     (FOR SELECT, public, true) coexiste com `kill_switches_write_admin` (FOR ALL),
--     cujo USING `is_admin_or_above(...)` também é avaliado em SELECT.
--
-- Risco real além do advisor: a edge `_shared/kill_switch.ts` lê esta tabela com a
-- chave anon. Como `anon` NÃO tem EXECUTE em is_admin_or_above, avaliar essa policy
-- num SELECT anônimo pode falhar com "permission denied" — e, sendo fail-open, o
-- kill-switch nunca detectaria o estado OFF (mesmo bug da policy profiles_select).
--
-- Correção: a policy de admin passa a valer só para escrita (INSERT/UPDATE/DELETE)
-- e só para `authenticated`. O SELECT público (read_all) continua como única policy
-- de leitura. service_role escreve via BYPASSRLS, sem depender destas policies.

-- 1) Índice de FK
CREATE INDEX IF NOT EXISTS idx_system_kill_switches_updated_by
  ON public.system_kill_switches (updated_by);

-- 2) Consolidação de policies (DROP IF EXISTS antes de cada CREATE p/ replay
--    idempotente: em prod as policies admin já existem)
DROP POLICY IF EXISTS kill_switches_write_admin ON public.system_kill_switches;

DROP POLICY IF EXISTS kill_switches_insert_admin ON public.system_kill_switches;
CREATE POLICY kill_switches_insert_admin
  ON public.system_kill_switches FOR INSERT TO authenticated
  WITH CHECK (public.is_admin_or_above((SELECT auth.uid())));

DROP POLICY IF EXISTS kill_switches_update_admin ON public.system_kill_switches;
CREATE POLICY kill_switches_update_admin
  ON public.system_kill_switches FOR UPDATE TO authenticated
  USING (public.is_admin_or_above((SELECT auth.uid())))
  WITH CHECK (public.is_admin_or_above((SELECT auth.uid())));

DROP POLICY IF EXISTS kill_switches_delete_admin ON public.system_kill_switches;
CREATE POLICY kill_switches_delete_admin
  ON public.system_kill_switches FOR DELETE TO authenticated
  USING (public.is_admin_or_above((SELECT auth.uid())));

-- <<< END 20260524210300_kill_switches_fk_index_and_policy_consolidation.sql <<<

-- >>> BEGIN 20260524210352_colapso_p1_revoke_anon_sensitive_tables.sql >>>
-- =============================================================
-- FASE 2 — REVOKE SELECT FROM anon em tabelas sensíveis
-- Contexto: análise forense do colapso 2026-05-24 revelou 35 tabelas
-- contendo credenciais/tokens/logs de auth expostas via GraphQL/PostgREST
-- para anon. RLS protege os dados, mas o REVOKE é defesa em profundidade
-- e remove a tabela da introspection schema do PostgREST.
-- (Guarda IF EXISTS: a lista inclui tabelas de outros projetos; só atua nas presentes.)
-- =============================================================

DO $$
DECLARE
  tbl text;
  sensitive_tables text[] := ARRAY[
    'admissao_tokens',
    'audit_log',
    'audit_logs',
    'auditoria',
    'auditoria_contratual',
    'auditoria_logs',
    'auth_gov_br_sessions',
    'blocked_ips',
    'ferias_audit_log',
    'folha_auditoria',
    'folha_eventos_auditoria',
    'geo_blocked_attempts',
    'govbr_auth_state',
    'login_attempts',
    'login_rate_limits',
    'password_history',
    'password_policies',
    'password_reset_config',
    'password_reset_requests',
    'ponto_auditoria',
    'ponto_auditoria_fraude',
    'provisao_auditoria',
    'rate_limit_config',
    'rate_limit_logs',
    'rate_limits',
    'security_alerts',
    'trilha_auditoria_ponto',
    'user_mfa',
    'user_sessions',
    'verification_tokens',
    'webauthn_credentials',
    'webhook_logs',
    'webhooks',
    'webhooks_config',
    'webhooks_logs'
  ];
BEGIN
  FOREACH tbl IN ARRAY sensitive_tables LOOP
    -- Só REVOKE se a tabela existe (defensive)
    IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname='public' AND tablename=tbl) THEN
      EXECUTE format('REVOKE SELECT, INSERT, UPDATE, DELETE ON public.%I FROM anon', tbl);
      RAISE NOTICE 'REVOKE anon ON public.%', tbl;
    END IF;
  END LOOP;
END $$;

-- Verificação pós-aplicação
SELECT
  schemaname, tablename,
  has_table_privilege('anon', schemaname||'.'||tablename, 'SELECT') AS anon_still_has_select
FROM pg_tables
WHERE schemaname = 'public'
  AND tablename IN ('password_reset_requests','user_mfa','webauthn_credentials','rate_limits','audit_log');

-- <<< END 20260524210352_colapso_p1_revoke_anon_sensitive_tables.sql <<<

-- >>> BEGIN 20260524210400_optimize_fn_run_schema_drift_check_hold.sql >>>
-- Reduz o tempo que fn_run_schema_drift_check() segura uma conexão (colapso 2026-05-24, fase E).
--
-- A função NÃO é lenta por query interna — ela dispara um fetch HTTP para o Lovable
-- (fn_trigger_schema_drift_fetch) e faz POLLING em net._http_response com pg_sleep,
-- segurando 1 conexão do worker pg_cron por até 30s (job diário 02:00 UTC).
--
-- Não é causa do colapso (1 conexão, 1x/dia), mas reduzimos o pior-caso de retenção
-- de 30s → 15s (30 tentativas × 500ms). O endpoint do Lovable responde em poucos
-- segundos; se estourar, a função grava timeout de forma graciosa e o próximo ciclo
-- diário tenta de novo.
--
-- FOLLOW-UP recomendado (fora deste lote, exige novos objetos): migrar para padrão
-- ASSÍNCRONO — fn_run_schema_drift_check só dispara o fetch e retorna; um cron leve
-- separado varre net._http_response e finaliza via fn_compute_and_record_drift,
-- eliminando 100% da retenção de conexão. Ver docs/RUNBOOK_COLAPSO_2026-05-24.md.

CREATE OR REPLACE FUNCTION public.fn_run_schema_drift_check()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_request_id   bigint;
  v_response     jsonb;
  v_lovable_sigs jsonb;
  v_log_id       uuid;
  v_attempts     int := 0;
  v_max_attempts int := 30;   -- 30 × 500ms = 15s (era 30s)
  v_sleep_sec    numeric := 0.5;
  v_status_code  int;
BEGIN
  -- Dispara fetch
  v_request_id := public.fn_trigger_schema_drift_fetch();

  -- Polling pelo resultado (500ms)
  LOOP
    v_attempts := v_attempts + 1;
    PERFORM pg_sleep(v_sleep_sec);

    SELECT status_code, content::jsonb
      INTO v_status_code, v_response
      FROM net._http_response
      WHERE id = v_request_id;

    EXIT WHEN v_status_code IS NOT NULL;

    IF v_attempts >= v_max_attempts THEN
      -- Timeout: grava erro com sinal claro de oportunidade de async
      v_log_id := public.record_schema_drift_result(jsonb_build_object(
        'has_drift', false,
        'tables_oficial', 0,
        'tables_lovable', 0,
        'only_oficial', '[]'::jsonb,
        'only_lovable', '[]'::jsonb,
        'schema_diff', '{}'::jsonb,
        'error_message', format('Timeout 15s (request_id=%s, %s tentativas de 500ms). Considere migrar para padrão async (trigger + finalize separado).', v_request_id, v_attempts)
      ));
      RETURN jsonb_build_object('ok', false, 'error', 'timeout', 'log_id', v_log_id);
    END IF;
  END LOOP;

  -- Validar resposta
  IF v_status_code != 200 THEN
    v_log_id := public.record_schema_drift_result(jsonb_build_object(
      'has_drift', false,
      'tables_oficial', 0,
      'tables_lovable', 0,
      'only_oficial', '[]'::jsonb,
      'only_lovable', '[]'::jsonb,
      'schema_diff', '{}'::jsonb,
      'error_message', format('Lovable retornou HTTP %s: %s', v_status_code, v_response::text)
    ));
    RETURN jsonb_build_object('ok', false, 'error', 'http_'||v_status_code, 'log_id', v_log_id);
  END IF;

  -- Computa diff e grava
  v_lovable_sigs := v_response;
  v_log_id := public.fn_compute_and_record_drift(v_lovable_sigs);

  RETURN jsonb_build_object('ok', true, 'log_id', v_log_id, 'request_id', v_request_id);
END;
$function$;

-- <<< END 20260524210400_optimize_fn_run_schema_drift_check_hold.sql <<<

