-- >>> BEGIN 20260524213151_colapso_fase3_hardening_kill_switches_writes.sql >>>
-- =============================================================
-- HARDENING — defesa em profundidade na public.system_kill_switches
--
-- Cenário atual:
--   - RLS ativo com policy admin-only para INSERT/UPDATE/DELETE → OK
--   - GRANT INSERT/UPDATE/DELETE para anon e authenticated → redundante
--     mas representa risco se RLS for desabilitada por engano.
--
-- Ação: REVOKE de writes para anon e authenticated; preserva SELECT
-- (necessário para o kill-switch-client.ts ler o estado).
-- service_role e postgres preservam todos os privilégios (admin path).
-- =============================================================

REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER
  ON public.system_kill_switches FROM anon;

REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER
  ON public.system_kill_switches FROM authenticated;

-- authenticated mantém SELECT (necessário para front-end checks pós-login)
GRANT SELECT ON public.system_kill_switches TO authenticated;
GRANT SELECT ON public.system_kill_switches TO anon;

-- Verificação rápida
SELECT
  grantee,
  string_agg(privilege_type, ', ' ORDER BY privilege_type) AS privs
FROM information_schema.table_privileges
WHERE table_schema = 'public'
  AND table_name = 'system_kill_switches'
  AND grantee IN ('anon','authenticated')
GROUP BY grantee
ORDER BY grantee;

-- <<< END 20260524213151_colapso_fase3_hardening_kill_switches_writes.sql <<<

-- >>> BEGIN 20260524213303_colapso_fase3_drop_redundant_duplicates.sql >>>
-- =============================================================
-- FASE 3 — Drop de 5 índices duplicados/redundantes
-- Critério: existe outro índice cobrindo a mesma coluna/predicate,
-- e o índice candidato tem menos scans (ou 0).
-- =============================================================

-- 1) idx_categories_slug_active (1 scan) — uq_categories_slug (UNIQUE) cobre
DROP INDEX IF EXISTS public.idx_categories_slug_active;

-- 2) idx_products_is_active (6 scans) — idx_products_active (parcial WHERE is_active=true) é melhor
DROP INDEX IF EXISTS public.idx_products_is_active;

-- 3) idx_pkg_compat_recommended (0 scans) — idx_pkg_compat_product (511 scans) cobre
DROP INDEX IF EXISTS public.idx_pkg_compat_recommended;

-- 4) idx_efi_errors (0 scans) — idx_efi_invoked_at já indexa invoked_at DESC
DROP INDEX IF EXISTS public.idx_efi_errors;

-- 5) idx_pfo_product_id (1 scan) — product_price_freshness_overrides_product_id_key (UNIQUE) cobre
DROP INDEX IF EXISTS public.idx_pfo_product_id;

-- <<< END 20260524213303_colapso_fase3_drop_redundant_duplicates.sql <<<

-- >>> BEGIN 20260524213813_colapso_fase3_kill_switch_telemetry.sql >>>
-- =============================================================
-- TELEMETRIA — registro de hits do kill-switch (front + back)
--
-- Permite responder perguntas como:
--   - Quantas chamadas ao external-db-bridge foram bloqueadas?
--   - De quais origens (componentes/páginas) vinham as chamadas?
--   - Em que momento posso desligar o switch sem quebrar UX?
--
-- Tabela enxuta: sem PII, retention curta (rotação semanal).
-- =============================================================

CREATE TABLE IF NOT EXISTS public.kill_switch_hits (
  id         bigserial PRIMARY KEY,
  switch_name text NOT NULL,
  source     text NOT NULL CHECK (source IN ('front', 'back')),
  operation  text,                     -- 'select', 'rpc:fn_x', 'invoke', etc.
  target     text,                     -- nome da tabela/rpc alvo
  origin     text,                     -- URL/rota do front (sem query string)
  user_role  text DEFAULT 'anon',      -- 'anon', 'authenticated', 'admin'
  occurred_at timestamptz NOT NULL DEFAULT now()
);

-- Índice para consultas agregadas por janela
CREATE INDEX IF NOT EXISTS idx_kill_switch_hits_occurred_at
  ON public.kill_switch_hits (occurred_at DESC);

CREATE INDEX IF NOT EXISTS idx_kill_switch_hits_switch_source
  ON public.kill_switch_hits (switch_name, source, occurred_at DESC);

-- RLS: anon e authenticated podem INSERT (telemetria), só admin lê
ALTER TABLE public.kill_switch_hits ENABLE ROW LEVEL SECURITY;

CREATE POLICY kill_switch_hits_insert_all
  ON public.kill_switch_hits FOR INSERT
  TO anon, authenticated, service_role
  WITH CHECK (true);

CREATE POLICY kill_switch_hits_read_admin
  ON public.kill_switch_hits FOR SELECT
  TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())));

CREATE POLICY kill_switch_hits_delete_admin
  ON public.kill_switch_hits FOR DELETE
  TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())));

-- GRANT mínimo (RLS faz o resto)
GRANT INSERT ON public.kill_switch_hits TO anon;
GRANT INSERT ON public.kill_switch_hits TO authenticated;
GRANT SELECT, DELETE ON public.kill_switch_hits TO authenticated;
GRANT USAGE, SELECT ON SEQUENCE public.kill_switch_hits_id_seq TO anon, authenticated;

-- View de resumo para o admin dashboard (joins prontos)
CREATE OR REPLACE VIEW public.v_kill_switch_hits_summary AS
SELECT
  switch_name,
  source,
  operation,
  target,
  count(*)                                              AS hits,
  count(*) FILTER (WHERE occurred_at > now() - interval '1 hour')  AS hits_1h,
  count(*) FILTER (WHERE occurred_at > now() - interval '24 hours') AS hits_24h,
  count(*) FILTER (WHERE occurred_at > now() - interval '7 days')   AS hits_7d,
  max(occurred_at)                                      AS last_hit
FROM public.kill_switch_hits
WHERE occurred_at > now() - interval '30 days'
GROUP BY switch_name, source, operation, target;

GRANT SELECT ON public.v_kill_switch_hits_summary TO authenticated;

COMMENT ON TABLE public.kill_switch_hits IS
'Telemetria de hits do kill-switch (front-end e back-end). Sem PII.
Permite decidir quando é seguro desligar definitivamente uma função descontinuada.
Rotação semanal via cron — ver kill_switch_hits_purge_weekly.';

-- Rotação semanal (mantém últimos 30d, mesma janela da view)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'kill_switch_hits_purge_weekly') THEN
    PERFORM cron.schedule(
      'kill_switch_hits_purge_weekly',
      '0 4 * * 0',  -- domingo 04h UTC
      $cron$
        DELETE FROM public.kill_switch_hits
        WHERE occurred_at < now() - interval '30 days';
      $cron$
    );
  END IF;
END $$;

-- <<< END 20260524213813_colapso_fase3_kill_switch_telemetry.sql <<<

-- >>> BEGIN 20260524213821_colapso_fase3_idx_products_is_active_not_deleted_name.sql >>>
-- Partial index for public product listing queries.
-- Replay-safe: only create it when the clean schema includes all referenced
-- public.products columns.

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'products'
      AND column_name = 'name'
  ) AND EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'products'
      AND column_name = 'is_active'
  ) AND EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'products'
      AND column_name = 'is_deleted'
  ) THEN
    CREATE INDEX IF NOT EXISTS idx_products_is_active_not_deleted_name
      ON public.products (name)
      WHERE is_active = true AND is_deleted = false;

    COMMENT ON INDEX public.idx_products_is_active_not_deleted_name IS
      'Partial index for public listing queries: is_active=true, is_deleted=false, ordered by name.';
  ELSE
    RAISE NOTICE '[colapso_fase3] Skipped idx_products_is_active_not_deleted_name: required columns are missing';
  END IF;
END $$;

-- <<< END 20260524213821_colapso_fase3_idx_products_is_active_not_deleted_name.sql <<<

-- >>> BEGIN 20260524214000_revoke_unsafe_secdef_grants.sql >>>
-- =============================================================================
-- Migration: hardening de SECURITY DEFINER functions expostas
-- =============================================================================
-- Bug P1-01/P1-02 da auditoria 24/05/2026.
--
-- Funções SECDEF executam com privilégios do owner (geralmente postgres ou
-- supabase_admin), bypassando RLS. EXECUTE GRANT a anon/authenticated permite
-- que qualquer requisição (mesmo sem login) dispare a função — útil pra alguns
-- casos (rate-limit pre-auth, quote-by-token, RLS check helpers), perigoso
-- para outros (cleanup, schema introspection, purge).
--
-- Triagem das 16 SECDEF expostas:
--
-- MANTÉM exposição (uso legítimo):
--   • can_access_quote (auth): valida acesso a cotação específica
--   • is_admin_or_above, is_coord_or_above, is_org_member, is_org_owner_or_admin,
--     org_has_any_members, user_is_org_member (auth): helpers usados em RLS
--     policies — devem ser executáveis pelo próprio usuário durante eval
--   • check_login_rate_limit (anon+auth): roda ANTES do login → precisa anon
--   • get_quote_token_by_value, submit_quote_response (anon): fluxo de
--     cotação por token público (sem login)
--   • start_step_up_challenge, verify_step_up_password (auth): MFA flow
--
-- REVOGADO de anon/authenticated (esta migration):
--   1. cleanup_expired_webhook_request_nonces — manutenção, só cron/service
--   2. purge_expired_security_data — manutenção destrutiva, só cron
--   3. expire_stale_password_reset_requests — manutenção, só cron
--   4. get_public_schema_signatures — introspecção, atacante mapearia schema
-- =============================================================================

REVOKE EXECUTE ON FUNCTION public.cleanup_expired_webhook_request_nonces()
  FROM anon, authenticated, PUBLIC;

DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT oid::regprocedure AS sig FROM pg_proc
           WHERE proname = 'purge_expired_security_data'
             AND pronamespace = 'public'::regnamespace
  LOOP
    EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM anon, authenticated, PUBLIC', r.sig);
  END LOOP;
END $$;

REVOKE EXECUTE ON FUNCTION public.expire_stale_password_reset_requests()
  FROM anon, authenticated, PUBLIC;

DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT oid::regprocedure AS sig FROM pg_proc
           WHERE proname = 'get_public_schema_signatures'
             AND pronamespace = 'public'::regnamespace
  LOOP
    EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM anon, authenticated, PUBLIC', r.sig);
  END LOOP;
END $$;

-- Validação: as 4 acima devem mostrar APENAS service_role após esta migration.
-- =============================================================================

-- <<< END 20260524214000_revoke_unsafe_secdef_grants.sql <<<

-- >>> BEGIN 20260524214603_colapso_fase4_drop_remaining_unused_indexes.sql >>>
-- =============================================================
-- DROP DOS ÍNDICES NÃO USADOS RESTANTES (fase 4)
--
-- Critério: idx_scan = 0 + tabela com writes frequentes + NÃO PK/UNIQUE
-- Ganho: ~1MB de espaço + UPDATEs ainda mais rápidos
-- =============================================================

-- product_commemorative_dates (232kB cada — total ~700KB)
DROP INDEX IF EXISTS public.idx_prod_comm_active;
DROP INDEX IF EXISTS public.idx_product_commemorative_dates_category_id;
DROP INDEX IF EXISTS public.idx_prod_comm_date;
DROP INDEX IF EXISTS public.idx_prod_comm_featured;

-- products (resto que sobrou)
DROP INDEX IF EXISTS public.idx_products_bitrix_images_synced_at;
DROP INDEX IF EXISTS public.idx_products_packing_classification;
DROP INDEX IF EXISTS public.idx_products_ai_version;
DROP INDEX IF EXISTS public.products_gtin_idx;
DROP INDEX IF EXISTS public.products_ean_idx;

-- suppliers
DROP INDEX IF EXISTS public.idx_suppliers_sync_enabled;

-- variant_supplier_sources
DROP INDEX IF EXISTS public.idx_vss_removed;

-- Reporta tamanho liberado
SELECT
  count(*) AS indices_droppados_total,
  pg_size_pretty(sum(pg_relation_size(c.oid))) AS espaco_total_indices_remanescentes
FROM pg_stat_user_indexes ui
JOIN pg_class c ON c.oid = ui.indexrelid
WHERE ui.schemaname = 'public';

-- <<< END 20260524214603_colapso_fase4_drop_remaining_unused_indexes.sql <<<

-- >>> BEGIN 20260524214725_colapso_fase4_fix_kill_switch_hits_security_advisors.sql >>>
-- =============================================================
-- FIX dos 2 advisors introduzidos pelos migrations de telemetria:
--
-- 1) ERROR: v_kill_switch_hits_summary com SECURITY DEFINER
--    → Recriar como SECURITY INVOKER (default seguro)
--
-- 2) WARN: kill_switch_hits_insert_all com WITH CHECK (true)
--    → Adicionar validação que limita o que pode ser inserido
-- =============================================================

-- ============ FIX 1: SECURITY INVOKER na view ============
DROP VIEW IF EXISTS public.v_kill_switch_hits_summary;

CREATE VIEW public.v_kill_switch_hits_summary
WITH (security_invoker = on) AS
SELECT
  switch_name,
  source,
  operation,
  target,
  count(*)                                              AS hits,
  count(*) FILTER (WHERE occurred_at > now() - interval '1 hour')  AS hits_1h,
  count(*) FILTER (WHERE occurred_at > now() - interval '24 hours') AS hits_24h,
  count(*) FILTER (WHERE occurred_at > now() - interval '7 days')   AS hits_7d,
  max(occurred_at)                                      AS last_hit
FROM public.kill_switch_hits
WHERE occurred_at > now() - interval '30 days'
GROUP BY switch_name, source, operation, target;

GRANT SELECT ON public.v_kill_switch_hits_summary TO authenticated;

COMMENT ON VIEW public.v_kill_switch_hits_summary IS
'Resumo de kill_switch_hits. SECURITY INVOKER: respeita RLS do caller.';

-- ============ FIX 2: WITH CHECK validado ============
DROP POLICY IF EXISTS kill_switch_hits_insert_all ON public.kill_switch_hits;

CREATE POLICY kill_switch_hits_insert_validated
  ON public.kill_switch_hits FOR INSERT
  TO anon, authenticated, service_role
  WITH CHECK (
    -- Switch_name não pode ser vazio nem desconhecido
    switch_name IS NOT NULL
    AND length(switch_name) BETWEEN 3 AND 100
    -- Source obrigatório e enum-like (check constraint já garante front|back)
    AND source IS NOT NULL
    -- occurred_at não pode ser no futuro (defesa contra clock drift / abuse)
    AND occurred_at <= now() + interval '5 minutes'
    -- E não pode ser muito antigo (defesa contra spam retroativo)
    AND occurred_at >= now() - interval '1 hour'
    -- Origin tem limite de tamanho (defesa anti-bloat)
    AND (origin IS NULL OR length(origin) <= 500)
    -- Operation/target idem
    AND (operation IS NULL OR length(operation) <= 200)
    AND (target IS NULL OR length(target) <= 200)
  );

COMMENT ON POLICY kill_switch_hits_insert_validated ON public.kill_switch_hits IS
'INSERT permitido com validações: tamanhos limitados, occurred_at no janela ±1h, switch_name não vazio.
Previne abuso/spam por clientes anônimos.';

-- <<< END 20260524214725_colapso_fase4_fix_kill_switch_hits_security_advisors.sql <<<

-- >>> BEGIN 20260524214802_colapso_fase4_revoke_kill_switch_views_from_anon.sql >>>
-- View v_kill_switch_hits_summary herda GRANT SELECT TO anon via default privs.
-- Revogar explicitamente para que não apareça no GraphQL schema do anon.
REVOKE SELECT ON public.v_kill_switch_hits_summary FROM anon;

-- Verificar
SELECT
  has_table_privilege('anon', 'public.v_kill_switch_hits_summary', 'SELECT') AS anon_select_view,
  has_table_privilege('authenticated', 'public.v_kill_switch_hits_summary', 'SELECT') AS auth_select_view;

-- <<< END 20260524214802_colapso_fase4_revoke_kill_switch_views_from_anon.sql <<<

-- >>> BEGIN 20260524214900_colapso_fase4_add_missing_fk_indexes.sql >>>
-- Additional indexes for foreign-key columns reported by the performance advisor.
-- Replay-safe: clean schemas can omit some legacy tables or columns.

DO $$
DECLARE
  v_index record;
BEGIN
  FOR v_index IN
    SELECT *
    FROM (
      VALUES
        ('idx_collection_products_product_id_fk', 'collection_products', 'product_id'),
        ('idx_frontend_telemetry_user_id', 'frontend_telemetry', 'user_id'),
        ('idx_product_commemorative_dates_category_id_fk', 'product_commemorative_dates', 'category_id'),
        ('idx_product_commemorative_dates_commemorative_date_id', 'product_commemorative_dates', 'commemorative_date_id'),
        ('idx_product_kit_components_component_product_id', 'product_kit_components', 'component_product_id'),
        ('idx_product_kit_components_secondary_material_type_id', 'product_kit_components', 'secondary_material_type_id'),
        ('idx_product_relationships_related_product_id', 'product_relationships', 'related_product_id'),
        ('idx_product_variants_size_id', 'product_variants', 'size_id'),
        ('idx_supplier_import_batches_supplier_id', 'supplier_import_batches', 'supplier_id'),
        ('idx_variant_supplier_sources_supplier_id_fk', 'variant_supplier_sources', 'supplier_id'),
        ('idx_variant_supplier_sources_supplier_branch_id', 'variant_supplier_sources', 'supplier_branch_id')
    ) AS indexes(index_name, table_name, column_name)
  LOOP
    IF to_regclass(format('public.%I', v_index.table_name)) IS NULL THEN
      RAISE NOTICE '[colapso_fase4_add_missing_fk_indexes] Skipped %.%: table does not exist',
        v_index.table_name,
        v_index.column_name;
    ELSIF NOT EXISTS (
      SELECT 1
      FROM information_schema.columns
      WHERE table_schema = 'public'
        AND table_name = v_index.table_name
        AND column_name = v_index.column_name
    ) THEN
      RAISE NOTICE '[colapso_fase4_add_missing_fk_indexes] Skipped %.%: column does not exist',
        v_index.table_name,
        v_index.column_name;
    ELSE
      EXECUTE format(
        'CREATE INDEX IF NOT EXISTS %I ON public.%I (%I)',
        v_index.index_name,
        v_index.table_name,
        v_index.column_name
      );
    END IF;
  END LOOP;
END $$;

-- <<< END 20260524214900_colapso_fase4_add_missing_fk_indexes.sql <<<

-- >>> BEGIN 20260524220000_perf_add_missing_fk_indexes.sql >>>
-- Performance: índices faltantes em foreign keys (auditoria MCP — advisor de performance).
--
-- O advisor `unindexed_foreign_keys` apontou 2 FKs sem índice de cobertura, o que
-- degrada JOINs e operações de CASCADE/checagem de FK:
--   - collection_products.product_id (FK collection_products_product_id_fkey1):
--     o índice composto existente (collection_id, product_id) lidera por
--     collection_id e NÃO cobre buscas só por product_id.
--   - system_kill_switches.updated_by (FK system_kill_switches_updated_by_fkey):
--     sem índice algum além da PK em switch_name.
--
-- Os 532 avisos `unused_index` foram deliberadamente IGNORADOS: o sinal do advisor
-- baseia-se em estatísticas de uso recentes (reset de stats) e remover índices é
-- arriscado (pode degradar planos de consultas pouco frequentes mas importantes).
-- Os 6 `multiple_permissive_policies` são todos em system_kill_switches (tabela
-- minúscula, ganho de performance desprezível) e mexer em política de kill switch
-- é sensível em segurança — fora de escopo.

CREATE INDEX IF NOT EXISTS idx_collection_products_product_id
  ON public.collection_products (product_id);

CREATE INDEX IF NOT EXISTS idx_system_kill_switches_updated_by
  ON public.system_kill_switches (updated_by);

-- <<< END 20260524220000_perf_add_missing_fk_indexes.sql <<<

-- >>> BEGIN 20260524220102_restore_user_2fa_settings.sql >>>
-- =============================================================
-- Restaura a tabela public.user_2fa_settings consumida por
-- src/hooks/auth/use2FA.ts. A tabela nunca existiu no banco
-- (o hook usava o cliente sem tipos), quebrando 2FA em runtime
-- ("column is_enabled does not exist").
-- Idempotente. RLS: dono gerencia o próprio registro; admin+ gerencia todos.
-- =============================================================

create table if not exists public.user_2fa_settings (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users (id) on delete cascade,
  is_enabled  boolean not null default false,
  totp_secret text,
  backup_codes text[],
  enabled_at  timestamptz,
  created_at  timestamptz not null default now(),
  constraint user_2fa_settings_user_id_key unique (user_id)
);

create index if not exists idx_user_2fa_settings_user_id
  on public.user_2fa_settings (user_id);

alter table public.user_2fa_settings enable row level security;

revoke all on table public.user_2fa_settings from anon;
grant select, insert, update, delete on table public.user_2fa_settings to authenticated;

drop policy if exists "user_2fa_select_own_or_admin" on public.user_2fa_settings;
create policy "user_2fa_select_own_or_admin" on public.user_2fa_settings
  for select to authenticated
  using (user_id = auth.uid() or public.is_admin_or_above(auth.uid()));

drop policy if exists "user_2fa_insert_own_or_admin" on public.user_2fa_settings;
create policy "user_2fa_insert_own_or_admin" on public.user_2fa_settings
  for insert to authenticated
  with check (user_id = auth.uid() or public.is_admin_or_above(auth.uid()));

drop policy if exists "user_2fa_update_own_or_admin" on public.user_2fa_settings;
create policy "user_2fa_update_own_or_admin" on public.user_2fa_settings
  for update to authenticated
  using (user_id = auth.uid() or public.is_admin_or_above(auth.uid()))
  with check (user_id = auth.uid() or public.is_admin_or_above(auth.uid()));

drop policy if exists "user_2fa_delete_own_or_admin" on public.user_2fa_settings;
create policy "user_2fa_delete_own_or_admin" on public.user_2fa_settings
  for delete to authenticated
  using (user_id = auth.uid() or public.is_admin_or_above(auth.uid()));

comment on table public.user_2fa_settings is
  'Configurações de 2FA (TOTP) por usuário. Consumida por src/hooks/auth/use2FA.ts.';

-- <<< END 20260524220102_restore_user_2fa_settings.sql <<<

