-- >>> BEGIN 20260525005350_colapso_fase5_smoke_tests_mensal_history_v2.sql >>>
-- ================================================================
-- SMOKE TESTS MENSAIS — v2 (SECURITY INVOKER porque fn_run_smoke_tests
-- interna usa RESET role que não funciona em SECURITY DEFINER)
-- ================================================================

CREATE TABLE IF NOT EXISTS public.smoke_tests_runs (
  id           bigserial PRIMARY KEY,
  ran_at       timestamptz NOT NULL DEFAULT now(),
  test_name    text NOT NULL,
  test_category text,
  result       text NOT NULL,
  details      text,
  duration_ms  numeric
);

DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='smoke_tests_runs' AND column_name IN ('ran_at')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_smoke_tests_runs_ran_at
  ON public.smoke_tests_runs (ran_at DESC);
  END IF;
END $$;

DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='smoke_tests_runs' AND column_name IN ('test_name','result','ran_at')) = 3 THEN
    CREATE INDEX IF NOT EXISTS idx_smoke_tests_runs_test_result
  ON public.smoke_tests_runs (test_name, result, ran_at DESC);
  END IF;
END $$;

ALTER TABLE public.smoke_tests_runs ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS smoke_tests_runs_read_admin ON public.smoke_tests_runs;
CREATE POLICY smoke_tests_runs_read_admin
  ON public.smoke_tests_runs FOR SELECT
  TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())));

GRANT SELECT ON public.smoke_tests_runs TO authenticated;
REVOKE ALL ON public.smoke_tests_runs FROM anon;
GRANT USAGE, SELECT ON SEQUENCE public.smoke_tests_runs_id_seq TO authenticated;

-- Replay-safe: em preview-branch a função pode existir como RETURNS void
-- (snapshot de produção onde 20260525063000 já foi aplicada).
-- DROP garante que CREATE OR REPLACE não falhe por mudança de tipo de retorno.
DROP FUNCTION IF EXISTS public.fn_run_and_persist_smoke_tests();

-- Wrapper SECURITY INVOKER (default)
CREATE OR REPLACE FUNCTION public.fn_run_and_persist_smoke_tests()
RETURNS TABLE(
  ran_at timestamptz,
  total_tests int,
  passed int,
  failed int,
  warned int,
  failed_tests text[]
)
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_catalog
AS $$
DECLARE
  v_ran_at timestamptz := now();
  v_total int := 0;
  v_passed int := 0;
  v_failed int := 0;
  v_warned int := 0;
  v_failed_tests text[] := ARRAY[]::text[];
  r RECORD;
BEGIN
  FOR r IN SELECT * FROM public.fn_run_smoke_tests() LOOP
    v_total := v_total + 1;
    
    INSERT INTO public.smoke_tests_runs (
      ran_at, test_name, test_category, result, details, duration_ms
    ) VALUES (
      v_ran_at, r.test_name, r.test_category, r.result, r.details, r.duration_ms
    );
    
    IF upper(r.result) = 'PASS' THEN v_passed := v_passed + 1;
    ELSIF upper(r.result) = 'FAIL' THEN 
      v_failed := v_failed + 1;
      v_failed_tests := array_append(v_failed_tests, r.test_name);
    ELSIF upper(r.result) IN ('WARN','WARNING') THEN v_warned := v_warned + 1;
    END IF;
  END LOOP;
  
  RETURN QUERY SELECT v_ran_at, v_total, v_passed, v_failed, v_warned, v_failed_tests;
END;
$$;

COMMENT ON FUNCTION public.fn_run_and_persist_smoke_tests() IS
'Wrapper SECURITY INVOKER. Roda fn_run_smoke_tests(), persiste em smoke_tests_runs e retorna sumário.
Cron mensal + execução manual via dashboard admin.';

-- Grant para admin/postgres executar
GRANT EXECUTE ON FUNCTION public.fn_run_and_persist_smoke_tests() TO postgres;
GRANT EXECUTE ON FUNCTION public.fn_run_and_persist_smoke_tests() TO authenticated;

-- Views
-- Replay-safe: DROP antes de CREATE OR REPLACE evita 42P16 ("cannot change
-- data type of view column") quando o snapshot do preview tem essas views
-- com tipos de coluna diferentes (ex.: count(*)::integer vs count(*) bigint
-- da migration 20260525063000).
DROP VIEW IF EXISTS public.v_smoke_tests_latest_run;
CREATE OR REPLACE VIEW public.v_smoke_tests_latest_run
WITH (security_invoker = on) AS
WITH latest AS (
  SELECT max(ran_at) AS ran_at FROM public.smoke_tests_runs
)
SELECT
  r.ran_at, r.test_name, r.test_category, r.result, r.details, r.duration_ms
FROM public.smoke_tests_runs r
JOIN latest l ON r.ran_at = l.ran_at
ORDER BY
  CASE upper(r.result)
    WHEN 'FAIL' THEN 1 WHEN 'WARN' THEN 2 WHEN 'PASS' THEN 3 ELSE 4
  END, r.test_name;

GRANT SELECT ON public.v_smoke_tests_latest_run TO authenticated;
REVOKE SELECT ON public.v_smoke_tests_latest_run FROM anon;

DROP VIEW IF EXISTS public.v_smoke_tests_trend;
CREATE OR REPLACE VIEW public.v_smoke_tests_trend
WITH (security_invoker = on) AS
SELECT
  ran_at,
  count(*) AS total,
  count(*) FILTER (WHERE upper(result) = 'PASS')         AS passed,
  count(*) FILTER (WHERE upper(result) = 'FAIL')         AS failed,
  count(*) FILTER (WHERE upper(result) IN ('WARN','WARNING')) AS warned,
  round(avg(duration_ms)::numeric, 1)                    AS avg_duration_ms
FROM public.smoke_tests_runs
GROUP BY ran_at
ORDER BY ran_at DESC
LIMIT 12;

GRANT SELECT ON public.v_smoke_tests_trend TO authenticated;
REVOKE SELECT ON public.v_smoke_tests_trend FROM anon;

-- Cron mensal (dia 1, 03h UTC — domingo madrugada se cair, sem impacto)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'smoke_tests_monthly') THEN
    PERFORM cron.schedule(
      'smoke_tests_monthly',
      '0 3 1 * *',
      $cron$ SELECT public.fn_run_and_persist_smoke_tests(); $cron$
    );
  END IF;
END $$;

-- Rotação: manter últimas 24 execuções (~2 anos)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'smoke_tests_runs_purge') THEN
    PERFORM cron.schedule(
      'smoke_tests_runs_purge',
      '0 4 1 * *',
      $cron$
        DELETE FROM public.smoke_tests_runs 
        WHERE ran_at < (
          SELECT min(ran_at) FROM (
            SELECT DISTINCT ran_at FROM public.smoke_tests_runs 
            ORDER BY ran_at DESC LIMIT 24
          ) keep
        );
      $cron$
    );
  END IF;
END $$;

-- <<< END 20260525005350_colapso_fase5_smoke_tests_mensal_history_v2.sql <<<

-- >>> BEGIN 20260525005426_colapso_fase5_smoke_tests_fix_emoji_parser.sql >>>
-- ================================================================
-- FIX: fn_run_smoke_tests retorna result com emoji prefix
-- ("✅ PASS", "❌ FAIL", "⚠️ WARN"). Ajustar parser para usar LIKE.
-- ================================================================

-- Replay-safe: DROP antes de recriar para evitar 42P13 se o tipo de retorno diferir.
DROP FUNCTION IF EXISTS public.fn_run_and_persist_smoke_tests();

CREATE OR REPLACE FUNCTION public.fn_run_and_persist_smoke_tests()
RETURNS TABLE(
  ran_at timestamptz,
  total_tests int,
  passed int,
  failed int,
  warned int,
  failed_tests text[]
)
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_catalog
AS $$
DECLARE
  v_ran_at timestamptz := now();
  v_total int := 0;
  v_passed int := 0;
  v_failed int := 0;
  v_warned int := 0;
  v_failed_tests text[] := ARRAY[]::text[];
  r RECORD;
BEGIN
  FOR r IN SELECT * FROM public.fn_run_smoke_tests() LOOP
    v_total := v_total + 1;
    
    INSERT INTO public.smoke_tests_runs (
      ran_at, test_name, test_category, result, details, duration_ms
    ) VALUES (
      v_ran_at, r.test_name, r.test_category, r.result, r.details, r.duration_ms
    );
    
    -- Match com emoji prefix (✅ PASS, ❌ FAIL, ⚠️ WARN)
    IF r.result ILIKE '%PASS%' THEN 
      v_passed := v_passed + 1;
    ELSIF r.result ILIKE '%FAIL%' THEN 
      v_failed := v_failed + 1;
      v_failed_tests := array_append(v_failed_tests, r.test_name);
    ELSIF r.result ILIKE '%WARN%' THEN 
      v_warned := v_warned + 1;
    END IF;
  END LOOP;
  
  RETURN QUERY SELECT v_ran_at, v_total, v_passed, v_failed, v_warned, v_failed_tests;
END;
$$;

-- View latest_run ajustar ordenação para emoji prefix
-- Replay-safe: DROP antes evita 42P16 se o snapshot do preview já tiver a view
-- com tipos de coluna diferentes (ex.: count(*)::integer da migration 063000).
DROP VIEW IF EXISTS public.v_smoke_tests_latest_run;
CREATE OR REPLACE VIEW public.v_smoke_tests_latest_run
WITH (security_invoker = on) AS
WITH latest AS (
  SELECT max(ran_at) AS ran_at FROM public.smoke_tests_runs
)
SELECT
  r.ran_at, r.test_name, r.test_category, r.result, r.details, r.duration_ms
FROM public.smoke_tests_runs r
JOIN latest l ON r.ran_at = l.ran_at
ORDER BY
  CASE
    WHEN r.result ILIKE '%FAIL%' THEN 1
    WHEN r.result ILIKE '%WARN%' THEN 2
    WHEN r.result ILIKE '%PASS%' THEN 3
    ELSE 4
  END,
  r.test_name;

-- View trend ajustar
DROP VIEW IF EXISTS public.v_smoke_tests_trend;
CREATE OR REPLACE VIEW public.v_smoke_tests_trend
WITH (security_invoker = on) AS
SELECT
  ran_at,
  count(*) AS total,
  count(*) FILTER (WHERE result ILIKE '%PASS%') AS passed,
  count(*) FILTER (WHERE result ILIKE '%FAIL%') AS failed,
  count(*) FILTER (WHERE result ILIKE '%WARN%') AS warned,
  round(avg(duration_ms)::numeric, 1) AS avg_duration_ms
FROM public.smoke_tests_runs
GROUP BY ran_at
ORDER BY ran_at DESC
LIMIT 12;

-- <<< END 20260525005426_colapso_fase5_smoke_tests_fix_emoji_parser.sql <<<

-- >>> BEGIN 20260525005954_colapso_fase5_kill_switch_rollout_gradual.sql >>>
-- ================================================================
-- ROLLOUT GRADUAL DO KILL-SWITCH (A/B controlado)
-- 
-- Permite desligar o switch progressivamente: 5% → 25% → 50% → 100%
-- usando hash determinístico do user_id/session_id como bucket.
-- 
-- Estratégia:
--   1. Coluna rollout_percentage em system_kill_switches (0-100)
--   2. Função fn_should_apply_kill_switch(switch_name, bucket_key) → boolean
--      Retorna TRUE se a chave cai dentro do bucket de rollout (kill aplicado)
--   3. View v_kill_switch_with_rollout para o front consultar
-- ===============================================================

-- 1) Adicionar coluna de rollout
ALTER TABLE public.system_kill_switches
  ADD COLUMN IF NOT EXISTS rollout_percentage smallint NOT NULL DEFAULT 100
    CHECK (rollout_percentage BETWEEN 0 AND 100);

COMMENT ON COLUMN public.system_kill_switches.rollout_percentage IS
'Porcentagem de tráfego (0-100) que recebe o kill-switch quando enabled=false.
100 = todos os clientes (default). 5 = apenas 5% (canary).
Útil para A/B testing antes de desligar definitivamente.';

-- 2) Função pura de roteamento — determinística por hash do bucket_key
CREATE OR REPLACE FUNCTION public.fn_should_apply_kill_switch(
  p_switch_name text,
  p_bucket_key text
) RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public, pg_catalog
AS $$
DECLARE
  v_enabled boolean;
  v_rollout smallint;
  v_bucket int;
BEGIN
  -- Lê estado do switch (RLS aplicável: anon tem SELECT)
  SELECT enabled, rollout_percentage 
    INTO v_enabled, v_rollout
  FROM public.system_kill_switches
  WHERE switch_name = p_switch_name;
  
  -- Switch não cadastrado = não aplicar (fail-open)
  IF NOT FOUND THEN RETURN false; END IF;
  
  -- Switch ATIVO (enabled=true) = nunca aplicar kill, independente de rollout
  IF v_enabled THEN RETURN false; END IF;
  
  -- Switch OFF (enabled=false): aplicar kill conforme rollout %
  IF v_rollout >= 100 THEN RETURN true; END IF;
  IF v_rollout <= 0 THEN RETURN false; END IF;
  
  -- Hash determinístico → bucket 0-99
  -- Mesmo bucket_key sempre cai no mesmo bucket (estabilidade entre reloads)
  v_bucket := abs(hashtext(coalesce(p_bucket_key, 'anonymous')) % 100);
  RETURN v_bucket < v_rollout;
END;
$$;

COMMENT ON FUNCTION public.fn_should_apply_kill_switch IS
'Decide se o kill-switch deve ser APLICADO (= bloquear chamada) para um bucket.
Determinístico por bucket_key (mesma chave sempre cai no mesmo grupo).
Lógica:
  enabled=true                  → false (nunca bloqueia)
  enabled=false, rollout=100    → true  (sempre bloqueia)
  enabled=false, rollout=0      → false (nunca bloqueia — pré-rollout)
  enabled=false, rollout=X%     → true se hashtext(bucket_key) % 100 < X
Bucket_key sugerido: auth.uid() para logged-in; localStorage uuid para anon.';

GRANT EXECUTE ON FUNCTION public.fn_should_apply_kill_switch TO anon;
GRANT EXECUTE ON FUNCTION public.fn_should_apply_kill_switch TO authenticated;

-- 3) Validar: switch atual está enabled=true, então sempre retorna false
SELECT 
  public.fn_should_apply_kill_switch('edge_external_db_bridge', 'test-user-1') AS rollout_test_1,
  public.fn_should_apply_kill_switch('edge_external_db_bridge', 'test-user-2') AS rollout_test_2,
  public.fn_should_apply_kill_switch('non_existent_switch', 'anyone') AS unknown_switch;

-- <<< END 20260525005954_colapso_fase5_kill_switch_rollout_gradual.sql <<<

-- >>> BEGIN 20260525020848_restore_set_quote_number_trigger.sql >>>
-- Restore the BEFORE INSERT trigger that auto-generates public.quotes.quote_number.
--
-- Context: quote_number is NOT NULL with no column default. Number generation is
-- handled by the public.generate_quote_number() trigger function (still present),
-- which sets NEW.quote_number when it is NULL or ''. The `set_quote_number` trigger
-- that invokes it was lost during the migration-replay drift cleanup, while the
-- function survived. Without the trigger, every INSERT into public.quotes from the
-- app (quoteService.createQuote, the Flow assistant, and the Kit Builder) fails with
-- "null value in column \"quote_number\" violates not-null constraint", so no quote
-- can be created. This restores the trigger as defined in migration
-- 20260219133353 to fix quote creation.

DROP TRIGGER IF EXISTS set_quote_number ON public.quotes;

CREATE TRIGGER set_quote_number
  BEFORE INSERT ON public.quotes
  FOR EACH ROW
  WHEN (NEW.quote_number IS NULL OR NEW.quote_number = '')
  EXECUTE FUNCTION public.generate_quote_number();

-- <<< END 20260525020848_restore_set_quote_number_trigger.sql <<<

-- >>> BEGIN 20260525021830_restore_set_quote_number_trigger.sql >>>
-- Restore the BEFORE INSERT trigger that auto-generates public.quotes.quote_number.
-- The trigger was lost during the migration-replay drift cleanup while
-- public.generate_quote_number() survived. Without it, quote_number (NOT NULL,
-- no default) is never populated and every quote INSERT from the app fails.
DROP TRIGGER IF EXISTS set_quote_number ON public.quotes;

CREATE TRIGGER set_quote_number
  BEFORE INSERT ON public.quotes
  FOR EACH ROW
  WHEN (NEW.quote_number IS NULL OR NEW.quote_number = '')
  EXECUTE FUNCTION public.generate_quote_number();

-- <<< END 20260525021830_restore_set_quote_number_trigger.sql <<<

-- >>> BEGIN 20260525063000_restore_smoke_test_observability_contract.sql >>>
-- Restore the smoke-test observability contract consumed by useSmokeTests.
-- The frontend reads v_smoke_tests_latest_run/v_smoke_tests_trend and triggers
-- fn_run_and_persist_smoke_tests(); keep all objects replay-safe.

CREATE TABLE IF NOT EXISTS public.smoke_test_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ran_at timestamptz NOT NULL DEFAULT now(),
  test_name text NOT NULL,
  test_category text,
  result text NOT NULL,
  details text,
  duration_ms numeric
);

DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='smoke_test_runs' AND column_name IN ('ran_at')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_smoke_test_runs_ran_at
  ON public.smoke_test_runs (ran_at DESC);
  END IF;
END $$;

DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='smoke_test_runs' AND column_name IN ('test_name','ran_at')) = 2 THEN
    CREATE INDEX IF NOT EXISTS idx_smoke_test_runs_name_ran_at
  ON public.smoke_test_runs (test_name, ran_at DESC);
  END IF;
END $$;

ALTER TABLE public.smoke_test_runs ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.smoke_test_runs FROM anon;
GRANT SELECT, INSERT ON TABLE public.smoke_test_runs TO authenticated;

DROP POLICY IF EXISTS smoke_test_runs_select_admin ON public.smoke_test_runs;
CREATE POLICY smoke_test_runs_select_admin
  ON public.smoke_test_runs FOR SELECT
  TO authenticated
  USING (public.is_admin_or_above((SELECT auth.uid())));

DROP POLICY IF EXISTS smoke_test_runs_insert_admin ON public.smoke_test_runs;
CREATE POLICY smoke_test_runs_insert_admin
  ON public.smoke_test_runs FOR INSERT
  TO authenticated
  WITH CHECK (public.is_admin_or_above((SELECT auth.uid())));

-- Replay-safe: em preview-branches a função pode já existir como RETURNS TABLE
-- (criada por 20260525005350/005426); CREATE OR REPLACE não muda o tipo de
-- retorno → ERROR 42P13. DROP antes garante recriação como RETURNS void.
-- Sem dependentes de schema em produção (verificado via pg_depend).
DROP FUNCTION IF EXISTS public.fn_run_and_persist_smoke_tests();
CREATE OR REPLACE FUNCTION public.fn_run_and_persist_smoke_tests()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_ran_at timestamptz := now();
BEGIN
  IF NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  INSERT INTO public.smoke_test_runs (
    ran_at,
    test_name,
    test_category,
    result,
    details,
    duration_ms
  )
  SELECT
    v_ran_at,
    test_name,
    test_category,
    result,
    details,
    duration_ms
  FROM public.fn_run_smoke_tests();
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_run_and_persist_smoke_tests() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_run_and_persist_smoke_tests() TO authenticated;

-- DROP+CREATE (não OR REPLACE): em prod a view já existe com colunas count(*)
-- em bigint; CREATE OR REPLACE não pode mudar o tipo p/ integer. DROP recria
-- limpo (nada depende destas views — verificado em pg_depend).
DROP VIEW IF EXISTS public.v_smoke_tests_latest_run;
CREATE VIEW public.v_smoke_tests_latest_run
WITH (security_invoker = on) AS
SELECT
  ran_at,
  test_name,
  test_category,
  result,
  details,
  duration_ms
FROM public.smoke_test_runs
WHERE ran_at = (SELECT max(ran_at) FROM public.smoke_test_runs)
ORDER BY
  CASE
    WHEN result LIKE '%FAIL%' THEN 0
    WHEN result LIKE '%WARN%' THEN 1
    ELSE 2
  END,
  test_name;

DROP VIEW IF EXISTS public.v_smoke_tests_trend;
CREATE VIEW public.v_smoke_tests_trend
WITH (security_invoker = on) AS
SELECT
  ran_at,
  count(*)::integer AS total,
  count(*) FILTER (WHERE result LIKE '%PASS%')::integer AS passed,
  count(*) FILTER (WHERE result LIKE '%FAIL%')::integer AS failed,
  count(*) FILTER (WHERE result LIKE '%WARN%')::integer AS warned,
  avg(duration_ms) AS avg_duration_ms
FROM public.smoke_test_runs
GROUP BY ran_at
ORDER BY ran_at DESC
LIMIT 12;

GRANT SELECT ON public.v_smoke_tests_latest_run TO authenticated;
GRANT SELECT ON public.v_smoke_tests_trend TO authenticated;
REVOKE SELECT ON public.v_smoke_tests_latest_run FROM anon;
REVOKE SELECT ON public.v_smoke_tests_trend FROM anon;

COMMENT ON TABLE public.smoke_test_runs IS
  'Persisted smoke-test results used by the admin observability dashboard.';
COMMENT ON VIEW public.v_smoke_tests_latest_run IS
  'Latest persisted smoke-test execution, ordered by severity.';
COMMENT ON VIEW public.v_smoke_tests_trend IS
  'Last 12 persisted smoke-test executions with aggregate counts.';

-- <<< END 20260525063000_restore_smoke_test_observability_contract.sql <<<

-- >>> BEGIN 20260525113000_runtime_edge_function_base_url.sql >>>
-- ============================================================================
-- Runtime-configured Edge Function base URL for SQL callers (cron/triggers/RPC)
-- ----------------------------------------------------------------------------
-- Objetivo:
-- - Remover dependência de URLs hardcoded em migrations históricas.
-- - Permitir promoção dev/stage/prod sem editar migration antiga.
-- - Centralizar resolução da base URL em runtime por GUC + Vault.
--
-- Precedência de resolução:
-- 1) current_setting('app.edge_functions_base_url', true)
-- 2) vault secret EDGE_FUNCTIONS_BASE_URL
-- 3) erro explícito (fail-closed)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_edge_functions_base_url()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, vault, pg_temp
AS $function$
DECLARE
  _cfg text;
  _vault text;
BEGIN
  _cfg := NULLIF(current_setting('app.edge_functions_base_url', true), '');

  IF _cfg IS NOT NULL THEN
    IF _cfg ~ '^https://[a-z0-9-]+\.supabase\.co$' THEN
      RETURN _cfg;
    END IF;

    RAISE EXCEPTION 'app.edge_functions_base_url invalido: %', _cfg
      USING ERRCODE = '22023';
  END IF;

  SELECT decrypted_secret INTO _vault
  FROM vault.decrypted_secrets
  WHERE name = 'EDGE_FUNCTIONS_BASE_URL'
  LIMIT 1;

  IF _vault IS NOT NULL THEN
    IF _vault ~ '^https://[a-z0-9-]+\.supabase\.co$' THEN
      RETURN _vault;
    END IF;

    RAISE EXCEPTION 'Secret EDGE_FUNCTIONS_BASE_URL invalido no vault: %', _vault
      USING ERRCODE = '22023';
  END IF;

  RAISE EXCEPTION 'Base URL das Edge Functions nao configurada. Defina app.edge_functions_base_url ou secret EDGE_FUNCTIONS_BASE_URL.'
    USING ERRCODE = 'no_data_found';
END;
$function$;

REVOKE ALL ON FUNCTION public.get_edge_functions_base_url() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_edge_functions_base_url() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_edge_functions_base_url() TO service_role;
GRANT EXECUTE ON FUNCTION public.get_edge_functions_base_url() TO postgres;

COMMENT ON FUNCTION public.get_edge_functions_base_url() IS
  'Resolve base URL das Edge Functions via current_setting(app.edge_functions_base_url) e fallback para vault EDGE_FUNCTIONS_BASE_URL.';

-- Recria trigger caller com URL dinâmica.
CREATE OR REPLACE FUNCTION public.dispatch_quote_webhook_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $function$
DECLARE
  _event text;
  _payload jsonb;
  _project_url text;
  _dispatcher_secret text;
BEGIN
  _project_url := public.get_edge_functions_base_url();

  IF TG_TABLE_NAME = 'quotes' THEN
    IF TG_OP = 'INSERT' THEN _event := 'quote.created';
    ELSIF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN _event := 'quote.' || NEW.status;
    ELSE RETURN NEW; END IF;
    _payload := jsonb_build_object('id', NEW.id, 'quote_number', NEW.quote_number, 'status', NEW.status,
      'client_name', NEW.client_name, 'client_email', NEW.client_email, 'total', NEW.total,
      'seller_id', NEW.seller_id, 'updated_at', NEW.updated_at);
  ELSIF TG_TABLE_NAME = 'orders' THEN
    IF TG_OP = 'INSERT' THEN _event := 'order.created'; ELSE RETURN NEW; END IF;
    _payload := jsonb_build_object('id', NEW.id, 'order_number', NEW.order_number, 'status', NEW.status,
      'client_name', NEW.client_name, 'total', NEW.total, 'seller_id', NEW.seller_id);
  ELSIF TG_TABLE_NAME = 'discount_approval_requests' THEN
    IF TG_OP = 'INSERT' THEN _event := 'discount.requested';
    ELSIF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status AND NEW.status IN ('approved','rejected') THEN _event := 'discount.' || NEW.status;
    ELSE RETURN NEW; END IF;
    _payload := jsonb_build_object('id', NEW.id, 'quote_id', NEW.quote_id,
      'requested_discount_percent', NEW.requested_discount_percent, 'status', NEW.status, 'seller_id', NEW.seller_id);
  ELSE RETURN NEW; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.outbound_webhooks WHERE active = true AND _event = ANY(events)) THEN
    RETURN NEW;
  END IF;

  BEGIN
    _dispatcher_secret := public.get_edge_function_secret('WEBHOOK_DISPATCHER_SECRET');
  EXCEPTION WHEN OTHERS THEN
    _dispatcher_secret := NULL;
  END;

  PERFORM extensions.http_post(
    url := _project_url || '/functions/v1/webhook-dispatcher',
    body := jsonb_build_object('event', _event, 'payload', _payload)::text,
    params := '{}'::jsonb,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-dispatcher-secret', COALESCE(_dispatcher_secret, '')
    ),
    timeout_milliseconds := 5000
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$function$;

-- Recria RPC caller com URL dinâmica.
CREATE OR REPLACE FUNCTION public.retry_failed_webhook_deliveries()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_supabase_url text;
  v_service_key text;
  v_dispatcher_secret text;
  v_retried int := 0;
  v_skipped int := 0;
  rec record;
  v_max_attempts int;
BEGIN
  v_supabase_url := public.get_edge_functions_base_url();

  BEGIN
    v_service_key := current_setting('app.supabase_service_role_key', true);
  EXCEPTION WHEN OTHERS THEN
    v_service_key := NULL;
  END;

  BEGIN
    v_dispatcher_secret := public.get_edge_function_secret('WEBHOOK_DISPATCHER_SECRET');
  EXCEPTION WHEN OTHERS THEN
    v_dispatcher_secret := NULL;
  END;

  IF v_dispatcher_secret IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'WEBHOOK_DISPATCHER_SECRET not configured in vault');
  END IF;

  FOR rec IN
    WITH latest AS (
      SELECT DISTINCT ON (d.webhook_id, d.event, d.payload_hash)
        d.id, d.webhook_id, d.event, d.payload, d.attempt, d.success
      FROM public.webhook_deliveries d
      WHERE d.delivered_at > now() - interval '1 hour'
      ORDER BY d.webhook_id, d.event, d.payload_hash, d.attempt DESC
    )
    SELECT l.*, w.active, w.retry_policy
    FROM latest l
    JOIN public.outbound_webhooks w ON w.id = l.webhook_id
    WHERE l.success = false AND w.active = true
  LOOP
    v_max_attempts := COALESCE((rec.retry_policy->>'max_attempts')::int, 3);

    IF rec.attempt >= v_max_attempts THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    PERFORM net.http_post(
      url := v_supabase_url || '/functions/v1/webhook-dispatcher',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-dispatcher-secret', v_dispatcher_secret,
        'Authorization', COALESCE('Bearer ' || v_service_key, '')
      ),
      body := jsonb_build_object('event', rec.event, 'payload', rec.payload)
    );
    v_retried := v_retried + 1;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'retried', v_retried, 'skipped_max_attempts', v_skipped, 'ran_at', now());
END;
$function$;

-- Reschedule cron callers com URL dinâmica.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'connections-auto-test') THEN
    PERFORM cron.unschedule('connections-auto-test');
  END IF;
END $$;

SELECT cron.schedule(
  'connections-auto-test',
  '*/15 * * * *',
  $cron$
  SELECT net.http_post(
    url := public.get_edge_functions_base_url() || '/functions/v1/connections-auto-test',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', public.get_edge_function_secret('CONNECTIONS_AUTO_TEST_SECRET')
    ),
    body := '{"trigger":"cron"}'::jsonb,
    timeout_milliseconds := 30000
  ) AS request_id;
  $cron$
);

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'external-db-bridge-keepalive') THEN
    PERFORM cron.unschedule('external-db-bridge-keepalive');

    PERFORM cron.schedule(
      'external-db-bridge-keepalive',
      '*/4 * * * *',
      $cron$
      SELECT net.http_post(
        url := public.get_edge_functions_base_url() || '/functions/v1/external-db-bridge',
        headers := jsonb_build_object('Content-Type', 'application/json'),
        body := '{"operation":"ping"}'::jsonb,
        timeout_milliseconds := 5000
      ) AS request_id;
      $cron$
    );
  END IF;
END $$;

-- Validação operacional: endpoint esperado por ambiente sem editar migration histórica.
CREATE OR REPLACE FUNCTION public.validate_edge_functions_base_url(_environment text)
RETURNS TABLE(ok boolean, resolved_url text, expected_pattern text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  _url text;
  _pattern text;
BEGIN
  _url := public.get_edge_functions_base_url();

  _pattern := CASE lower(coalesce(_environment, ''))
    WHEN 'prod' THEN '^https://pqpdolkaeqlyzpdpbizo\.supabase\.co$'
    WHEN 'stage' THEN '^https://[a-z0-9-]+\.supabase\.co$'
    WHEN 'dev' THEN '^https://[a-z0-9-]+\.supabase\.co$'
    ELSE '^https://[a-z0-9-]+\.supabase\.co$'
  END;

  RETURN QUERY SELECT (_url ~ _pattern), _url, _pattern;
END;
$function$;

