-- >>> BEGIN 20260526141615_52d285ed-e141-4437-9a13-0fec9285c93c.sql >>>
-- ============================================================
-- Migration: webhook_inbound idempotency support (SAFE/IDEMPOTENT)
-- ============================================================
-- Notas:
--   • contract_version já existe NOT NULL no banco — NÃO tocar. A versão
--     anterior do Lovable tentava ADD COLUMN IF NOT EXISTS TEXT (nullable),
--     o que seria silenciosamente no-op por causa do IF NOT EXISTS, mas
--     induzia em erro. Removido.
--   • idempotency_key é nullable: webhooks sem chave continuam funcionando
--     (fallback usa hash da assinatura HMAC dentro da edge function).
--   • Index único parcial (endpoint_id, idempotency_key) garante atomicidade.
--   • REVOKE/GRANT explícitos: nenhuma leitura/escrita por anon/authenticated
--     no path crítico (já era política existente; mantido).
-- ============================================================

ALTER TABLE public.inbound_webhook_events
  ADD COLUMN IF NOT EXISTS idempotency_key TEXT;

DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='inbound_webhook_events' AND column_name IN ('endpoint_id','idempotency_key')) = 2 THEN
    CREATE UNIQUE INDEX IF NOT EXISTS idx_webhook_idempotency
  ON public.inbound_webhook_events (endpoint_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;
  END IF;
END $$;

-- <<< END 20260526141615_52d285ed-e141-4437-9a13-0fec9285c93c.sql <<<

-- >>> BEGIN 20260526141659_5cd6e346-f106-4e21-b2b7-171d86b581b6.sql >>>
-- ============================================================
-- Migration: increment_webhook_stats RPC
-- ============================================================
-- Atualização atômica de last_received_at / total_received / total_invalid
-- no endpoint, evitando race condition do UPDATE direto anterior.
-- Chamada APENAS via service_role (RPC) a partir de webhook-inbound.
-- ============================================================

CREATE OR REPLACE FUNCTION public.increment_webhook_stats(
  p_endpoint_id UUID,
  p_is_invalid  BOOLEAN
) RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE public.inbound_webhook_endpoints
  SET
    last_received_at = NOW(),
    total_received   = COALESCE(total_received, 0) + 1,
    total_invalid    = COALESCE(total_invalid,  0) + CASE WHEN p_is_invalid THEN 1 ELSE 0 END
  WHERE id = p_endpoint_id;
END;
$$;

REVOKE ALL ON FUNCTION public.increment_webhook_stats(UUID, BOOLEAN) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.increment_webhook_stats(UUID, BOOLEAN) TO service_role, postgres;

-- <<< END 20260526141659_5cd6e346-f106-4e21-b2b7-171d86b581b6.sql <<<

