-- >>> BEGIN 20260526220005_fix_005_user_roles_privilege_escalation.sql >>>
-- =============================================================================
-- FIX-005: user_roles — Prevent privilege escalation (manager -> dev)
-- Bug: is_admin_or_above() includes 'manager', allowing them to grant 'dev' role
-- Applied: 2026-05-26
-- =============================================================================

DROP POLICY IF EXISTS "Admins insert roles" ON public.user_roles;
DROP POLICY IF EXISTS "Admins update roles" ON public.user_roles;
DROP POLICY IF EXISTS "Admins delete roles" ON public.user_roles;

CREATE POLICY user_roles_insert_guarded
  ON public.user_roles FOR INSERT TO authenticated
  WITH CHECK (
    CASE
      WHEN role = 'dev'::app_role
        THEN is_dev((SELECT auth.uid()))
      ELSE (
        EXISTS (
          SELECT 1 FROM public.user_roles ur
          WHERE ur.user_id = (SELECT auth.uid())
            AND ur.role IN ('dev', 'supervisor', 'admin')
        )
      )
    END
  );

CREATE POLICY user_roles_update_guarded
  ON public.user_roles FOR UPDATE TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())))
  WITH CHECK (
    CASE
      WHEN role = 'dev'::app_role
        THEN is_dev((SELECT auth.uid()))
      ELSE (
        EXISTS (
          SELECT 1 FROM public.user_roles ur
          WHERE ur.user_id = (SELECT auth.uid())
            AND ur.role IN ('dev', 'supervisor', 'admin')
        )
      )
    END
  );

CREATE POLICY user_roles_delete_guarded
  ON public.user_roles FOR DELETE TO authenticated
  USING (
    CASE
      WHEN role = 'dev'::app_role
        THEN is_dev((SELECT auth.uid()))
      ELSE is_admin_or_above((SELECT auth.uid()))
    END
  );

-- <<< END 20260526220005_fix_005_user_roles_privilege_escalation.sql <<<

-- >>> BEGIN 20260527121746_4e6187e6-a340-4b6a-8caa-71fd82f4044c.sql >>>
CREATE TABLE IF NOT EXISTS public.system_error_logs (
    id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID,
    function_name TEXT NOT NULL,
    error_message TEXT NOT NULL,
    stack_trace TEXT,
    metadata JSONB DEFAULT '{}'::jsonb,
    severity TEXT DEFAULT 'error',
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

-- Use GRANT to set permissions
GRANT INSERT ON public.system_error_logs TO authenticated;
GRANT SELECT ON public.system_error_logs TO authenticated;
GRANT ALL ON public.system_error_logs TO service_role;

-- Enable RLS
ALTER TABLE public.system_error_logs ENABLE ROW LEVEL SECURITY;

-- Create policies
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'system_error_logs' AND policyname = 'Users can insert their own error logs'
  ) THEN
    CREATE POLICY "Users can insert their own error logs" 
ON public.system_error_logs 
FOR INSERT 
WITH CHECK (auth.uid() = user_id OR user_id IS NULL);
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'system_error_logs' AND policyname = 'Users can view their own error logs'
  ) THEN
    CREATE POLICY "Users can view their own error logs" 
ON public.system_error_logs 
FOR SELECT 
USING (auth.uid() = user_id);
  END IF;
END $$;

-- Index for performance
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='system_error_logs' AND column_name IN ('user_id')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_system_error_logs_user_id ON public.system_error_logs(user_id);
  END IF;
END $$;
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='system_error_logs' AND column_name IN ('function_name')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_system_error_logs_function_name ON public.system_error_logs(function_name);
  END IF;
END $$;
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='system_error_logs' AND column_name IN ('created_at')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_system_error_logs_created_at ON public.system_error_logs(created_at);
  END IF;
END $$;
-- <<< END 20260527121746_4e6187e6-a340-4b6a-8caa-71fd82f4044c.sql <<<

-- >>> BEGIN 20260527143139_482b086d-660c-4025-91c5-619a87933d31.sql >>>
-- 1. Atualizar o nome da única organização existente no banco para Promo Brindes
UPDATE public.organizations 
SET name = 'Promo Brindes', slug = 'promo-brindes'
WHERE id = '35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5';

-- 2. Criar função para atribuição automática de organização
-- Isso garante que novos usuários sempre pertençam à Promo Brindes,
-- mantendo as políticas de RLS funcionando sem alterações manuais.
CREATE OR REPLACE FUNCTION public.auto_assign_user_to_promo_brindes()
RETURNS TRIGGER AS $$
BEGIN
  -- Guard: em preview snapshots sem a organização Promo Brindes, viramos no-op
  -- para evitar FK violation em todo INSERT em profiles.
  IF EXISTS (
    SELECT 1 FROM public.organizations
    WHERE id = '35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5'
  ) THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES ('35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5', NEW.user_id, 'member')
    ON CONFLICT (organization_id, user_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 3. Trigger na tabela profiles
-- Sempre que um perfil for criado, vinculamos o usuário à organização.
DROP TRIGGER IF EXISTS trg_auto_assign_promo_brindes ON public.profiles;
CREATE TRIGGER trg_auto_assign_promo_brindes
  AFTER INSERT ON public.profiles
  FOR EACH ROW
  EXECUTE FUNCTION public.auto_assign_user_to_promo_brindes();

-- 4. Sincronizar perfis existentes que possam estar órfãos de organização
-- Guard: a organização 'Promo Brindes' pode não existir em preview snapshots
-- (organization criada manualmente em produção); evitamos FK violation.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.organizations
    WHERE id = '35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5'
  ) THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    SELECT '35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5', user_id, 'member'
    FROM public.profiles
    ON CONFLICT (organization_id, user_id) DO NOTHING;
  ELSE
    RAISE NOTICE 'Organização Promo Brindes não existe — sync de profiles pulado';
  END IF;
END $$;

-- <<< END 20260527143139_482b086d-660c-4025-91c5-619a87933d31.sql <<<

