-- >>> BEGIN 20260604000001_fix_security_definer_search_path.sql >>>
-- Migration: Fix SECURITY DEFINER functions missing SET search_path
-- Issue: soft_delete_record, restore_record e permanent_delete_record foram criados
-- sem SET search_path, tornando-os vulneráveis a search_path injection se o schema
-- for comprometido (um atacante poderia criar funções shadow em outros schemas).
-- Todos os SECURITY DEFINER devem ter search_path fixo como defesa em profundidade.
-- CI Gate: check:security-definer-acl verifica esta propriedade em todos os deploys.

CREATE OR REPLACE FUNCTION public.soft_delete_record(
    p_table_name TEXT,
    p_record_id UUID
) RETURNS BOOLEAN AS $$
DECLARE
    v_sql TEXT;
    v_rows_affected INT;
BEGIN
    IF p_table_name NOT IN ('products', 'clients', 'suppliers', 'quotes', 'orders', 'collections', 'categories') THEN
        RAISE EXCEPTION 'Invalid table name: %', p_table_name;
    END IF;

    v_sql := format(
        'UPDATE public.%I SET deleted_at = NOW() WHERE id = $1 AND deleted_at IS NULL',
        p_table_name
    );

    EXECUTE v_sql USING p_record_id;
    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;

    RETURN v_rows_affected > 0;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';

COMMENT ON FUNCTION public.soft_delete_record IS 'Marca um registro como deletado (soft delete). SECURITY DEFINER com search_path fixo.';

CREATE OR REPLACE FUNCTION public.restore_record(
    p_table_name TEXT,
    p_record_id UUID
) RETURNS BOOLEAN AS $$
DECLARE
    v_sql TEXT;
    v_rows_affected INT;
BEGIN
    IF p_table_name NOT IN ('products', 'clients', 'suppliers', 'quotes', 'orders', 'collections', 'categories') THEN
        RAISE EXCEPTION 'Invalid table name: %', p_table_name;
    END IF;

    v_sql := format(
        'UPDATE public.%I SET deleted_at = NULL WHERE id = $1 AND deleted_at IS NOT NULL',
        p_table_name
    );

    EXECUTE v_sql USING p_record_id;
    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;

    RETURN v_rows_affected > 0;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';

COMMENT ON FUNCTION public.restore_record IS 'Restaura um registro deletado. SECURITY DEFINER com search_path fixo.';

CREATE OR REPLACE FUNCTION public.permanent_delete_record(
    p_table_name TEXT,
    p_record_id UUID
) RETURNS BOOLEAN AS $$
DECLARE
    v_sql TEXT;
    v_rows_affected INT;
BEGIN
    IF p_table_name NOT IN ('products', 'clients', 'suppliers', 'quotes', 'orders', 'collections', 'categories') THEN
        RAISE EXCEPTION 'Invalid table name: %', p_table_name;
    END IF;

    v_sql := format(
        'DELETE FROM public.%I WHERE id = $1 AND deleted_at IS NOT NULL',
        p_table_name
    );

    EXECUTE v_sql USING p_record_id;
    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;

    RETURN v_rows_affected > 0;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';

COMMENT ON FUNCTION public.permanent_delete_record IS 'Deleta permanentemente um registro soft-deleted. SECURITY DEFINER com search_path fixo.';

-- Restrict EXECUTE to service_role only.
-- By default, PUBLIC (including anon/authenticated) can call any function; these
-- SECURITY DEFINER functions must not be callable by end users via PostgREST.
REVOKE EXECUTE ON FUNCTION public.soft_delete_record(TEXT, UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.soft_delete_record(TEXT, UUID) TO service_role;

REVOKE EXECUTE ON FUNCTION public.restore_record(TEXT, UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.restore_record(TEXT, UUID) TO service_role;

REVOKE EXECUTE ON FUNCTION public.permanent_delete_record(TEXT, UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.permanent_delete_record(TEXT, UUID) TO service_role;

-- <<< END 20260604000001_fix_security_definer_search_path.sql <<<

-- >>> BEGIN 20260604000002_webhook_idempotency.sql >>>
-- Migration: Webhook Idempotency Key
-- Problema: webhook_deliveries não tinha mecanismo de deduplicação.
-- Um mesmo evento entregue duas vezes era processado duas vezes (double-charge,
-- double-order, registros duplicados).
-- Fix: adiciona coluna idempotency_key com constraint UNIQUE por (webhook_id + payload_hash)
-- e função check_and_lock_delivery() que faz SELECT ... FOR UPDATE + INSERT
-- em transação atômica, prevenindo race conditions em entrega concorrente.

-- 1. Adicionar coluna idempotency_key na tabela webhook_deliveries
-- NULL when payload_hash is absent — unique constraint does not fire for NULLs,
-- so webhooks without a hash are never incorrectly blocked.
ALTER TABLE public.webhook_deliveries
  ADD COLUMN IF NOT EXISTS idempotency_key TEXT GENERATED ALWAYS AS (
    webhook_id::text || ':' || payload_hash
  ) STORED;

-- 2a. Lock the table to serialise all three steps (DELETE + CREATE INDEX) against
-- concurrent webhook inserts. SHARE ROW EXCLUSIVE MODE blocks INSERT/UPDATE/DELETE
-- for the lifetime of this transaction, so no new duplicate can slip in between
-- the cleanup and the moment the unique index becomes active.
LOCK TABLE public.webhook_deliveries IN SHARE ROW EXCLUSIVE MODE;

-- 2b. Remover duplicatas históricas antes de criar o índice único.
-- Uses ctid (physical tuple position) as the stable tiebreaker — rows with a
-- smaller ctid were inserted earlier, approximating "oldest delivery" for
-- pre-existing rows where id is a random UUID and carries no time ordering.
WITH ranked AS (
  SELECT id,
         ROW_NUMBER() OVER (
           PARTITION BY webhook_id, payload_hash
           ORDER BY ctid
         ) AS rn
  FROM public.webhook_deliveries
  WHERE status_code BETWEEN 200 AND 299
    AND payload_hash IS NOT NULL
)
DELETE FROM public.webhook_deliveries
WHERE id IN (SELECT id FROM ranked WHERE rn > 1);

-- 2c. Índice para acesso eficiente por idempotency_key.
-- Não usamos UNIQUE aqui — o check de deduplicação com janela de tempo é feito
-- em check_webhook_dedup(); um índice UNIQUE impediria replay legítimo após o
-- vencimento da janela (ex.: retry após 10 min com window de 5 min).
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_idempotency
  ON public.webhook_deliveries (idempotency_key)
  WHERE status_code BETWEEN 200 AND 299;

-- 3. Adicionar coluna attempted_at para controlar janela de deduplicação
ALTER TABLE public.webhook_deliveries
  ADD COLUMN IF NOT EXISTS attempted_at TIMESTAMPTZ DEFAULT NOW();

-- 4. Função atômica: verifica entrega recente antes de permitir nova.
-- Usa pg_advisory_xact_lock para serializar verificações concorrentes do mesmo
-- webhook+hash, eliminando a race condition check-then-act.
-- Quando payload_hash é NULL, retorna TRUE imediatamente (sem hash = sem dedup).
CREATE OR REPLACE FUNCTION public.check_webhook_dedup(
  p_webhook_id UUID,
  p_payload_hash TEXT,
  p_dedup_window_seconds INT DEFAULT 300
) RETURNS BOOLEAN AS $$
DECLARE
  v_recent_count INT;
  v_lock_key BIGINT;
BEGIN
  -- Without a hash we cannot deduplicate; allow delivery
  IF p_payload_hash IS NULL THEN
    RETURN TRUE;
  END IF;

  -- Serialise concurrent checks for the same webhook + payload combination.
  -- hashtextextended returns 64-bit, avoiding the collision contention of hashtext (32-bit).
  v_lock_key := hashtextextended(p_webhook_id::text || ':' || p_payload_hash, 0);
  PERFORM pg_advisory_xact_lock(v_lock_key);

  SELECT COUNT(*)
    INTO v_recent_count
    FROM public.webhook_deliveries
   WHERE webhook_id = p_webhook_id
     AND payload_hash = p_payload_hash
     AND status_code BETWEEN 200 AND 299
     AND attempted_at > NOW() - (p_dedup_window_seconds || ' seconds')::INTERVAL;

  RETURN v_recent_count = 0; -- TRUE = pode entregar; FALSE = duplicata detectada
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';

COMMENT ON FUNCTION public.check_webhook_dedup IS
  'Retorna TRUE se a entrega pode prosseguir (sem duplicata na janela). '
  'Adquire advisory lock transacional para serializar chamadas concorrentes. '
  'Deve ser chamada dentro de uma transação antes do INSERT em webhook_deliveries.';

-- Restringir EXECUTE ao service_role para evitar que clientes comuns possam
-- sondar existência de entregas de outros webhooks via PostgREST.
REVOKE EXECUTE ON FUNCTION public.check_webhook_dedup FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.check_webhook_dedup TO service_role;

-- 5. Adicionar coluna replay_of para rastrear re-entregas explícitas
ALTER TABLE public.webhook_deliveries
  ADD COLUMN IF NOT EXISTS replay_of UUID REFERENCES public.webhook_deliveries(id) ON DELETE SET NULL;

-- Índice FK para replay_of
CREATE INDEX IF NOT EXISTS idx_webhook_deliveries_replay_of
  ON public.webhook_deliveries (replay_of)
  WHERE replay_of IS NOT NULL;

-- <<< END 20260604000002_webhook_idempotency.sql <<<

-- >>> BEGIN 20260604000003_add_compound_indexes_performance.sql >>>
-- Migration: Compound indexes for critical query patterns
-- Problema: consultas de catálogo (90% do tráfego) fazem full table scan
-- porque os índices existentes são single-column e não cobrem os filtros compostos
-- mais frequentes: (is_active + category_id), (is_active + price), (supplier_id + is_active).
-- Referência: AUDIT_REPORT_20260602.md § Performance P1

-- 1. Consultas por categoria ativa (useProductsByCategory, useCatalogState)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_products_active_category
  ON public.products (is_active, category_id)
  WHERE is_active = true AND deleted_at IS NULL;

-- 2. Consultas por fornecedor ativo (filtro de fornecedor no catálogo)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_products_active_supplier
  ON public.products (is_active, supplier_id)
  WHERE is_active = true AND deleted_at IS NULL;

-- 3. Consultas por faixa de preço (filtro de preço no catálogo)
-- The catalog price column is sale_price (not a generic 'price'); base_price is deprecated.
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_products_active_price
  ON public.products (is_active, sale_price)
  WHERE is_active = true AND deleted_at IS NULL;

-- 4. Ordenação por data de criação (grid "mais recentes")
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_products_active_created_desc
  ON public.products (is_active, created_at DESC)
  WHERE is_active = true AND deleted_at IS NULL;

-- 5. Filtro de soft-delete em catálogo (todos os SELECTs de produto)
-- deleted_at não é incluído nas colunas: o predicado WHERE deleted_at IS NULL
-- já o fixa em NULL, tornando-o constante e sem benefício como coluna indexada.
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_products_not_deleted_active
  ON public.products (is_active)
  WHERE deleted_at IS NULL;

-- 6. quotes por status + usuário (dashboard de orçamentos)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_quotes_user_status
  ON public.quotes (created_by, status)
  WHERE deleted_at IS NULL;

-- 7. quotes por organização + status (visão de gestor)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_quotes_org_status
  ON public.quotes (organization_id, status)
  WHERE deleted_at IS NULL;

-- 8. stock_snapshots: acesso por variante + fornecedor (estoque em tempo real)
-- No deleted_at column on stock_snapshots — purged by captured_at, not soft-deleted.
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_stock_snapshots_variant_supplier
  ON public.stock_snapshots (variant_id, supplier_id);

-- 9. order_items por pedido (join crítico em tela de pedido)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_order_items_order_id
  ON public.order_items (order_id);

-- 10. color_variations por grupo — já coberto por idx_color_variations_color_group_id
-- criado em 20260602_001_add_fk_indexes_critical.sql; índice redundante removido.

-- <<< END 20260604000003_add_compound_indexes_performance.sql <<<

-- >>> BEGIN 20260604000004_process_queue_atomic_cleanup.sql >>>
-- Migration: process_queue atomic cleanup function
-- Problema: edge function process-queue fazia cleanup e fetch em operações separadas.
-- Se o cleanup era bem-sucedido mas o fetch falhava, notificações eram perdidas.
-- Fix: função SQL SECURITY DEFINER que faz cleanup + fetch em transação única,
-- retornando as notificações não lidas ANTES de limpá-las.
-- A edge function passa a chamar um único RPC em vez de dois comandos separados.

CREATE OR REPLACE FUNCTION public.process_notifications_queue(
  p_limit INT DEFAULT 500
)
RETURNS TABLE (
  id UUID,
  user_id UUID,
  title TEXT,
  message TEXT,
  type TEXT,
  category TEXT,
  created_at TIMESTAMPTZ
) AS $$
BEGIN
  -- 1. Atomically claim and return unread notifications.
  -- FOR UPDATE SKIP LOCKED ensures concurrent callers skip rows already claimed
  -- by a peer, preventing duplicate dispatch across parallel edge function invocations.
  RETURN QUERY
    WITH claimed AS (
      SELECT wn.id
      FROM public.workspace_notifications wn
      WHERE wn.is_read = false
      ORDER BY wn.created_at ASC
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
    )
    UPDATE public.workspace_notifications wn
    SET is_read = true
    FROM claimed
    WHERE wn.id = claimed.id
    RETURNING wn.id, wn.user_id, wn.title, wn.message, wn.type, wn.category, wn.created_at;

  -- 2. Limpa notificações LIDAS antigas APÓS ter retornado as atuais.
  -- Only deletes is_read=true rows so unread notifications older than 90 days
  -- (e.g. inactive users) are never silently discarded before processing.
  -- workspace_notifications has no updated_at column; use created_at only.
  DELETE FROM public.workspace_notifications
  WHERE is_read = true
    AND created_at < NOW() - INTERVAL '90 days';

END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';

COMMENT ON FUNCTION public.process_notifications_queue IS
  'Retorna notificações não lidas e limpa antigas em transação única. '
  'Deve ser chamada apenas pela edge function process-queue via service_role.';

-- A função lê workspace_notifications sem filtro por user_id (processamento de fila
-- global). Revogar acesso público para impedir que clientes leiam notificações de
-- outros usuários via PostgREST.
REVOKE EXECUTE ON FUNCTION public.process_notifications_queue FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.process_notifications_queue TO service_role;

-- <<< END 20260604000004_process_queue_atomic_cleanup.sql <<<

-- >>> BEGIN 20260604000005_admin_rls_kit_write_policies.sql >>>
-- Migration: Admin RLS write policies for kit_component_print_areas and kit_component_media
-- Problema: external-db-bridge usava service_role, contornando RLS.
-- Após a migração para REST nativo (user JWT), apenas SELECT estava coberto.
-- kit_component_print_areas: tinha INSERT/UPDATE para admin mas faltava DELETE.
-- kit_component_media: não tinha nenhuma policy de escrita para admin.
-- Fix: adiciona políticas idempotentes de INSERT/UPDATE/DELETE para admin.

DO $$
BEGIN
  -- -------------------------------------------------------------------------
  -- kit_component_print_areas: admin DELETE (INSERT/UPDATE já existem)
  -- -------------------------------------------------------------------------
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'kit_component_print_areas'
      AND policyname = 'kcpa_admin_delete'
  ) THEN
    IF EXISTS (
      SELECT 1 FROM information_schema.tables
      WHERE table_schema = 'public' AND table_name = 'kit_component_print_areas'
    ) THEN
      CREATE POLICY "kcpa_admin_delete"
        ON public.kit_component_print_areas FOR DELETE
        TO authenticated
        USING (is_admin_or_above((SELECT auth.uid())));
      RAISE NOTICE 'Created policy kcpa_admin_delete on kit_component_print_areas';
    ELSE
      RAISE NOTICE 'Table kit_component_print_areas not found — skipping kcpa_admin_delete';
    END IF;
  END IF;

  -- -------------------------------------------------------------------------
  -- kit_component_media: INSERT, UPDATE, DELETE para admin
  -- -------------------------------------------------------------------------
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'kit_component_media'
      AND policyname = 'kcm_admin_insert'
  ) THEN
    IF EXISTS (
      SELECT 1 FROM information_schema.tables
      WHERE table_schema = 'public' AND table_name = 'kit_component_media'
    ) THEN
      CREATE POLICY "kcm_admin_insert"
        ON public.kit_component_media FOR INSERT
        TO authenticated
        WITH CHECK (is_admin_or_above((SELECT auth.uid())));
      RAISE NOTICE 'Created policy kcm_admin_insert on kit_component_media';
    ELSE
      RAISE NOTICE 'Table kit_component_media not found — skipping kcm_admin_insert';
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'kit_component_media'
      AND policyname = 'kcm_admin_update'
  ) THEN
    IF EXISTS (
      SELECT 1 FROM information_schema.tables
      WHERE table_schema = 'public' AND table_name = 'kit_component_media'
    ) THEN
      CREATE POLICY "kcm_admin_update"
        ON public.kit_component_media FOR UPDATE
        TO authenticated
        USING (is_admin_or_above((SELECT auth.uid())))
        WITH CHECK (is_admin_or_above((SELECT auth.uid())));
      RAISE NOTICE 'Created policy kcm_admin_update on kit_component_media';
    ELSE
      RAISE NOTICE 'Table kit_component_media not found — skipping kcm_admin_update';
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'kit_component_media'
      AND policyname = 'kcm_admin_delete'
  ) THEN
    IF EXISTS (
      SELECT 1 FROM information_schema.tables
      WHERE table_schema = 'public' AND table_name = 'kit_component_media'
    ) THEN
      CREATE POLICY "kcm_admin_delete"
        ON public.kit_component_media FOR DELETE
        TO authenticated
        USING (is_admin_or_above((SELECT auth.uid())));
      RAISE NOTICE 'Created policy kcm_admin_delete on kit_component_media';
    ELSE
      RAISE NOTICE 'Table kit_component_media not found — skipping kcm_admin_delete';
    END IF;
  END IF;
END $$;

-- <<< END 20260604000005_admin_rls_kit_write_policies.sql <<<

-- >>> BEGIN 20260604000006_notification_queue_dispatch_state.sql >>>
-- Migration: separate notification dispatch state from user read-state
-- Problem (cubic P1): process_notifications_queue() set is_read=true during
-- atomic claim, conflating queue processing state with user-facing read state.
-- Consequence: if dispatch failed after claim (e.g., push notification error,
-- edge function crash) the notification was silently lost — is_read=true
-- prevented re-queuing but the user never received the notification.
--
-- Fix: add dispatched_at column as the queue's ownership marker.
-- Queue predicate changes from is_read=false → dispatched_at IS NULL.
-- is_read remains user-only (set by UI when user dismisses the notification).

-- 1. Add dispatched_at to workspace_notifications
ALTER TABLE public.workspace_notifications
  ADD COLUMN IF NOT EXISTS dispatched_at TIMESTAMPTZ;

-- 2. Backfill: rows already marked is_read=true were processed by the old
-- queue function; mark them as dispatched so they are not re-queued.
UPDATE public.workspace_notifications
SET dispatched_at = NOW()
WHERE is_read = true
  AND dispatched_at IS NULL;

-- 3. Efficient index for queue scans (only unprocessed rows)
CREATE INDEX IF NOT EXISTS idx_workspace_notifications_undispatched
  ON public.workspace_notifications (created_at ASC)
  WHERE dispatched_at IS NULL;

-- 4. Replace function: claim by dispatched_at IS NULL, set dispatched_at=NOW()
CREATE OR REPLACE FUNCTION public.process_notifications_queue(
  p_limit INT DEFAULT 500
)
RETURNS TABLE (
  id UUID,
  user_id UUID,
  title TEXT,
  message TEXT,
  type TEXT,
  category TEXT,
  created_at TIMESTAMPTZ
) AS $$
BEGIN
  -- Atomically claim undispatched notifications.
  -- dispatched_at IS NULL = not yet sent by any queue worker.
  -- FOR UPDATE SKIP LOCKED ensures concurrent callers get disjoint batches.
  -- is_read is NOT touched here — it is updated by the UI when the user
  -- reads/dismisses the notification.
  RETURN QUERY
    WITH claimed AS (
      SELECT wn.id
      FROM public.workspace_notifications wn
      WHERE wn.dispatched_at IS NULL
      ORDER BY wn.created_at ASC
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
    )
    UPDATE public.workspace_notifications wn
    SET dispatched_at = NOW()
    FROM claimed
    WHERE wn.id = claimed.id
    RETURNING wn.id, wn.user_id, wn.title, wn.message, wn.type, wn.category, wn.created_at;

  -- Purge old dispatched notifications.
  -- Only rows with dispatched_at IS NOT NULL are deleted, so undispatched
  -- notifications (e.g., for inactive users) are never silently discarded.
  DELETE FROM public.workspace_notifications
  WHERE dispatched_at IS NOT NULL
    AND created_at < NOW() - INTERVAL '90 days';

END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';

COMMENT ON FUNCTION public.process_notifications_queue IS
  'Retorna notificações não despachadas e as marca com dispatched_at=NOW() em '
  'transação única (FOR UPDATE SKIP LOCKED). dispatched_at rastreia o estado de '
  'processamento da fila; is_read permanece exclusivo para o usuário. '
  'Deve ser chamada apenas pela edge function process-queue via service_role.';

REVOKE EXECUTE ON FUNCTION public.process_notifications_queue FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.process_notifications_queue TO service_role;

-- <<< END 20260604000006_notification_queue_dispatch_state.sql <<<

-- >>> BEGIN 20260604000007_kit_dml_grants.sql >>>
-- Migration: GRANT INSERT/UPDATE/DELETE on kit tables to authenticated role.
-- RLS policies alone are necessary but not sufficient for PostgREST DML —
-- the authenticated role also needs table-level privileges. Without these
-- grants, write operations fail at the privilege layer before RLS is checked.
--
-- ENABLE ROW LEVEL SECURITY is added defensively: these tables were created
-- outside migrations (via Lovable/Supabase UI) and may or may not have RLS
-- enabled. Without RLS active, the admin-only write policies are ignored and
-- any authenticated user can mutate rows. ALTER TABLE ... ENABLE ROW LEVEL
-- SECURITY is idempotent — safe to run even if already enabled.

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'kit_component_print_areas'
  ) THEN
    ALTER TABLE public.kit_component_print_areas ENABLE ROW LEVEL SECURITY;
    GRANT INSERT, UPDATE, DELETE ON public.kit_component_print_areas TO authenticated;
    RAISE NOTICE 'Enabled RLS and granted DML on kit_component_print_areas to authenticated';
  END IF;

  IF EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'kit_component_media'
  ) THEN
    ALTER TABLE public.kit_component_media ENABLE ROW LEVEL SECURITY;
    GRANT INSERT, UPDATE, DELETE ON public.kit_component_media TO authenticated;
    RAISE NOTICE 'Enabled RLS and granted DML on kit_component_media to authenticated';
  END IF;

  IF EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = 'product_kit_components'
  ) THEN
    -- product_kit_components already has ENABLE ROW LEVEL SECURITY from
    -- migration 20250103070000_complete_catalog_structure.sql; re-enabling is a no-op.
    ALTER TABLE public.product_kit_components ENABLE ROW LEVEL SECURITY;
    GRANT INSERT, UPDATE, DELETE ON public.product_kit_components TO authenticated;
    RAISE NOTICE 'Enabled RLS and granted DML on product_kit_components to authenticated';
  END IF;
END $$;

-- <<< END 20260604000007_kit_dml_grants.sql <<<

-- >>> BEGIN 20260604000008_notification_queue_lease.sql >>>
-- Migration: notification queue lease model for retry-safe delivery.
-- Problem (Codex P1): migration 000006 set dispatched_at=NOW() during the atomic
-- claim, before the edge function had confirmed successful delivery. If the edge
-- function crashes or times out after the claim, those rows have dispatched_at set
-- and are never re-queued, reproducing the notification-loss mode the previous
-- migration intended to fix.
--
-- Fix: introduce a two-phase claim/confirm pattern.
--   Phase 1 — claim: set dispatch_claim_expires_at = NOW() + 15 min (lease).
--             dispatched_at is NOT set here.
--   Phase 2 — confirm: edge function calls confirm_notifications_dispatched(ids)
--             after successful delivery; only then is dispatched_at set.
--   Recovery: if the edge function crashes, the lease expires after 15 minutes
--             and the notification becomes available for re-claim.
--
-- dispatched_at semantics are unchanged for external consumers:
--   NULL  = not yet confirmed delivered
--   NOT NULL = confirmed delivered (cleanup-eligible after 90 days)

ALTER TABLE public.workspace_notifications
  ADD COLUMN IF NOT EXISTS dispatch_claim_expires_at TIMESTAMPTZ;

-- idx_workspace_notifications_undispatched (created_at ASC, WHERE dispatched_at IS NULL)
-- was already created by migration 000006 — no duplicate index needed here.

-- Replace process_notifications_queue: set lease only (not dispatched_at).
CREATE OR REPLACE FUNCTION public.process_notifications_queue(
  p_limit INT DEFAULT 500
)
RETURNS TABLE (
  id UUID,
  user_id UUID,
  title TEXT,
  message TEXT,
  type TEXT,
  category TEXT,
  created_at TIMESTAMPTZ
) AS $$
BEGIN
  -- Atomically claim notifications that are:
  --   a) not yet confirmed delivered (dispatched_at IS NULL), AND
  --   b) either never claimed or whose claim lease has expired.
  -- Sets a 15-minute lease; does NOT set dispatched_at.
  -- dispatched_at is set only by confirm_notifications_dispatched() after delivery.
  RETURN QUERY
    WITH claimed AS (
      SELECT wn.id
      FROM public.workspace_notifications wn
      WHERE wn.dispatched_at IS NULL
        AND (
          wn.dispatch_claim_expires_at IS NULL
          OR wn.dispatch_claim_expires_at < NOW()
        )
      ORDER BY wn.created_at ASC
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
    )
    UPDATE public.workspace_notifications wn
    SET dispatch_claim_expires_at = NOW() + INTERVAL '15 minutes'
    FROM claimed
    WHERE wn.id = claimed.id
    RETURNING wn.id, wn.user_id, wn.title, wn.message, wn.type, wn.category, wn.created_at;

  -- Purge confirmed-delivered notifications older than 90 days.
  -- Rows with dispatched_at IS NULL are never deleted here.
  -- Guard is_read = true so unread notifications (inactive users, etc.)
  -- are never silently discarded before the user has seen them.
  DELETE FROM public.workspace_notifications
  WHERE dispatched_at IS NOT NULL
    AND is_read = true
    AND created_at < NOW() - INTERVAL '90 days';
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';

-- New function: called by the edge function after successful delivery to
-- permanently mark notifications as dispatched (clearing the lease).
CREATE OR REPLACE FUNCTION public.confirm_notifications_dispatched(
  p_ids UUID[]
)
RETURNS INT AS $$
DECLARE
  v_count INT;
BEGIN
  UPDATE public.workspace_notifications
  SET dispatched_at = NOW(),
      dispatch_claim_expires_at = NULL
  WHERE id = ANY(p_ids)
    AND dispatched_at IS NULL
    AND dispatch_claim_expires_at IS NOT NULL
    AND dispatch_claim_expires_at > NOW();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';

REVOKE EXECUTE ON FUNCTION public.process_notifications_queue FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.process_notifications_queue TO service_role;

REVOKE EXECUTE ON FUNCTION public.confirm_notifications_dispatched FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.confirm_notifications_dispatched TO service_role;

COMMENT ON FUNCTION public.process_notifications_queue IS
  'Claims undispatched notifications with a 15-minute lease (dispatch_claim_expires_at). '
  'Does NOT set dispatched_at — call confirm_notifications_dispatched() after delivery. '
  'Expired leases are automatically re-claimable, enabling at-least-once delivery.';

COMMENT ON FUNCTION public.confirm_notifications_dispatched IS
  'Marks notifications as permanently dispatched after successful delivery. '
  'Only confirms rows with an active (non-expired) lease to prevent accidentally '
  'dispatching unclaimed rows. Must be called by process-queue with IDs from '
  'process_notifications_queue(). Idempotent — already-confirmed rows are silently skipped.';

-- <<< END 20260604000008_notification_queue_lease.sql <<<

-- >>> BEGIN 20260604000009_webhook_delivery_claim.sql >>>
-- Migration: atomic webhook delivery claim to eliminate dedup race condition.
--
-- Root cause (Codex P1): check_webhook_dedup acquires pg_advisory_xact_lock but
-- the lock is transaction-scoped — it is released when the RPC call returns,
-- before the edge function inserts a delivery row. Two concurrent dispatcher
-- invocations for the same webhook+payload can both pass the check before either
-- writes a row, causing both to POST externally (double-charge, double-order).
--
-- Fix: introduce a webhook_delivery_locks table with a PRIMARY KEY on
-- (webhook_id, payload_hash). claim_webhook_delivery() does an atomic
-- INSERT ... ON CONFLICT DO NOTHING — the unique constraint guarantees only
-- one concurrent invocation can insert the lock row; the other gets 0 rows and
-- returns FALSE. release_webhook_delivery_lock() removes the lock after the
-- full retry cycle so future retries are not blocked by a stale lock.
--
-- Crash recovery: if the edge function crashes before calling release, the lock
-- row has a claimed_at timestamp; claim_webhook_delivery() deletes any lock
-- older than 15 minutes, after which the delivery is eligible to be retried.

CREATE TABLE IF NOT EXISTS public.webhook_delivery_locks (
  webhook_id    UUID         NOT NULL REFERENCES public.outbound_webhooks(id) ON DELETE CASCADE,
  payload_hash  TEXT         NOT NULL,
  claimed_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  PRIMARY KEY (webhook_id, payload_hash)
);

CREATE INDEX IF NOT EXISTS idx_webhook_delivery_locks_claimed_at
  ON public.webhook_delivery_locks (claimed_at);

-- claim_webhook_delivery: atomically checks for a recent successful delivery or
-- an in-flight lock, then inserts the lock row. Returns TRUE when the caller
-- should proceed with delivery, FALSE when it should skip.
CREATE OR REPLACE FUNCTION public.claim_webhook_delivery(
  p_webhook_id           UUID,
  p_payload_hash         TEXT,
  p_dedup_window_seconds INT DEFAULT 300
) RETURNS BOOLEAN AS $$
DECLARE
  v_recent_count INT;
  v_rows_inserted INT;
BEGIN
  IF p_payload_hash IS NULL THEN
    RETURN TRUE; -- no hash → no dedup, always allow
  END IF;

  -- Expire stale locks (handles edge-function crashes before release was called).
  DELETE FROM public.webhook_delivery_locks
  WHERE webhook_id    = p_webhook_id
    AND payload_hash  = p_payload_hash
    AND claimed_at    < NOW() - INTERVAL '15 minutes';

  -- Check for a recent successful delivery within the dedup window.
  SELECT COUNT(*)
    INTO v_recent_count
    FROM public.webhook_deliveries
   WHERE webhook_id   = p_webhook_id
     AND payload_hash = p_payload_hash
     AND status_code  BETWEEN 200 AND 299
     AND attempted_at > NOW() - (p_dedup_window_seconds || ' seconds')::INTERVAL;

  IF v_recent_count > 0 THEN
    RETURN FALSE; -- duplicate: recent successful delivery exists
  END IF;

  -- Atomically acquire the delivery lock.
  -- ON CONFLICT DO NOTHING means a concurrent claim for the same key yields 0
  -- inserted rows (ROW_COUNT = 0) without error — the caller skips delivery.
  INSERT INTO public.webhook_delivery_locks (webhook_id, payload_hash)
  VALUES (p_webhook_id, p_payload_hash)
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_rows_inserted = ROW_COUNT;
  RETURN v_rows_inserted > 0; -- TRUE = lock acquired; FALSE = already claimed
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';

-- release_webhook_delivery_lock: called after the full delivery retry cycle
-- (success or final failure) so that future retries are not blocked by the lock.
-- Idempotent — safe to call even if the lock was already expired and deleted.
CREATE OR REPLACE FUNCTION public.release_webhook_delivery_lock(
  p_webhook_id  UUID,
  p_payload_hash TEXT
) RETURNS VOID AS $$
BEGIN
  DELETE FROM public.webhook_delivery_locks
  WHERE webhook_id   = p_webhook_id
    AND payload_hash = p_payload_hash;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = 'public';

REVOKE EXECUTE ON FUNCTION public.claim_webhook_delivery FROM PUBLIC;
GRANT  EXECUTE ON FUNCTION public.claim_webhook_delivery TO service_role;

REVOKE EXECUTE ON FUNCTION public.release_webhook_delivery_lock FROM PUBLIC;
GRANT  EXECUTE ON FUNCTION public.release_webhook_delivery_lock TO service_role;

COMMENT ON TABLE public.webhook_delivery_locks IS
  'In-flight delivery claim table. A row exists for the duration of a single '
  'delivery attempt cycle (all retries). Rows older than 15 minutes are '
  'automatically expired by claim_webhook_delivery() to handle edge-function '
  'crashes that skip the release call.';

COMMENT ON FUNCTION public.claim_webhook_delivery IS
  'Atomic check-and-claim for webhook deduplication. Deletes stale locks, checks '
  'for recent successful deliveries, then inserts a lock row via INSERT ... ON '
  'CONFLICT DO NOTHING. Returns TRUE if the lock was acquired (proceed), FALSE if '
  'a duplicate or in-flight claim was detected (skip). Must be paired with '
  'release_webhook_delivery_lock() after the delivery attempt cycle.';

COMMENT ON FUNCTION public.release_webhook_delivery_lock IS
  'Releases a delivery lock after the full retry cycle. Idempotent. Must be called '
  'after claim_webhook_delivery() returns TRUE, regardless of delivery outcome, so '
  'that failed deliveries can be retried by subsequent dispatcher invocations.';

-- <<< END 20260604000009_webhook_delivery_claim.sql <<<

-- >>> BEGIN 20260604002342_silver_13_extrator_cor_titulo_somarcas.sql >>>

-- ════════════════════════════════════════════════════════════════
-- EXTRATOR de cor a partir do título (Só Marcas e fornecedores sem
-- campo de cor). Acha o 1º token de cor do vocabulário e normaliza
-- para a forma canônica (gênero masculino) que casa color_variations.
-- Retorna NULL quando o título não contém cor (kits/peças) — correto.
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_extract_color_from_title(p_titulo text)
RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
  v_tok text;
  v_up  text;
BEGIN
  IF p_titulo IS NULL OR TRIM(p_titulo)='' THEN RETURN NULL; END IF;
  v_up := UPPER(p_titulo);

  SELECT m[1] INTO v_tok FROM regexp_matches(v_up,
    '\y(PRET[AO]|BRANC[AO]|AZUL|VERMELH[AO]|VERDE|CINZA|AMAREL[AO]|ROSA|ROX[AO]|LARANJA|BEGE|MARROM|DOURAD[AO]|PRATEAD[AO]|PRATA|NATURAL|BAMBU|MADEIRA|INOX|VINHO|CAQUI|NUDE|TURQUESA|LIL[AÁ]S|FUM[EÊ]|TRANSPARENTE|GRAFITE|CHUMBO|CORAL|MOSTARDA)\y'
  ) m LIMIT 1;

  IF v_tok IS NULL THEN RETURN NULL; END IF;

  -- normaliza gênero/variação → nome canônico (Title Case) de color_variations
  RETURN CASE
    WHEN v_tok LIKE 'PRET%'   THEN 'Preto'
    WHEN v_tok LIKE 'BRANC%'  THEN 'Branco'
    WHEN v_tok LIKE 'VERMELH%' THEN 'Vermelho'
    WHEN v_tok LIKE 'AMAREL%' THEN 'Amarelo'
    WHEN v_tok LIKE 'ROX%'    THEN 'Roxo'
    WHEN v_tok LIKE 'DOURAD%' THEN 'Dourado'
    WHEN v_tok LIKE 'PRATEAD%' THEN 'Prata'
    WHEN v_tok='AZUL'       THEN 'Azul'
    WHEN v_tok='VERDE'      THEN 'Verde'
    WHEN v_tok='CINZA'      THEN 'Cinza'
    WHEN v_tok='ROSA'       THEN 'Rosa'
    WHEN v_tok='LARANJA'    THEN 'Laranja'
    WHEN v_tok='BEGE'       THEN 'Bege'
    WHEN v_tok='MARROM'     THEN 'Marrom'
    WHEN v_tok='PRATA'      THEN 'Prata'
    WHEN v_tok='NATURAL'    THEN 'Natural'
    WHEN v_tok='BAMBU'      THEN 'Bambu'
    WHEN v_tok='MADEIRA'    THEN 'Madeira'
    WHEN v_tok='INOX'       THEN 'Inox'
    WHEN v_tok='VINHO'      THEN 'Vinho'
    WHEN v_tok='CAQUI'      THEN 'Caqui'
    WHEN v_tok='NUDE'       THEN 'Nude'
    WHEN v_tok='TURQUESA'   THEN 'Turquesa'
    WHEN v_tok LIKE 'LIL%'  THEN 'Lilás'
    WHEN v_tok LIKE 'FUM%'  THEN 'Fumê'
    WHEN v_tok='TRANSPARENTE' THEN 'Transparente'
    WHEN v_tok='GRAFITE'    THEN 'Grafite'
    WHEN v_tok='CHUMBO'     THEN 'Chumbo'
    WHEN v_tok='CORAL'      THEN 'Coral'
    WHEN v_tok='MOSTARDA'   THEN 'Mostarda'
    ELSE initcap(v_tok)
  END;
END;
$$;

COMMENT ON FUNCTION public.fn_extract_color_from_title IS
  'Extrai cor do título (vocabulário + normalização de gênero) p/ fornecedores sem campo de cor (Só Marcas). NULL quando não há cor.';

-- <<< END 20260604002342_silver_13_extrator_cor_titulo_somarcas.sql <<<

-- >>> BEGIN 20260604002410_silver_08g_variante_somarcas_cor_titulo.sql >>>

CREATE OR REPLACE FUNCTION public.fn_standardize_variant(p_raw_id uuid)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE
  r public.supplier_products_raw%ROWTYPE;
  v_parent text; v_code text; v_apiid text; v_cname text; v_chex text;
  v_col RECORD; v_sku text; v_supplier_sku text; v_stock integer; v_cost numeric; v_var_id uuid;
  v_fname text; v_fcode text; v_fhex text; v_canonical_id uuid;
  v_SPOT uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ  uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM   uuid := '841cd690-210a-422a-908c-7676828db272';
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id=p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','raw_nao_encontrado'); END IF;
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  IF r.supplier_id=v_SPOT THEN
    v_code:=r.raw_data->>'ColorCode'; v_cname:=r.raw_data->>'ColorName'; v_chex:=r.raw_data->>'ColorHex';
    v_supplier_sku:=r.raw_data->>'Sku'; v_stock:=public.fn_safe_int(r.raw_data->>'StockQuantity');
    v_cost:=public.fn_safe_num(r.raw_data->>'Price1'); v_sku:=r.supplier_reference;
  ELSIF r.supplier_id=v_XBZ THEN
    v_apiid:=r.raw_data->>'CorWebPrincipalId'; v_cname:=r.raw_data->>'CorWebPrincipal';
    v_supplier_sku:=r.raw_data->>'CodigoComposto'; v_stock:=public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel');
    v_sku:='XBZ-'||r.supplier_reference;
  ELSIF r.supplier_id=v_ASIA THEN
    v_cname:=r.raw_data->>'var_cor_nome'; v_chex:=r.raw_data->>'var_cor_hex';
    v_supplier_sku:=COALESCE(r.raw_data->>'var_referencia', r.supplier_reference);
    v_stock:=public.fn_safe_int(r.raw_data->>'var_estoque'); v_sku:='ASIA-'||r.supplier_reference;
  ELSIF r.supplier_id=v_SM THEN
    -- Só Marcas: sem campo de cor. Extrai do título; hex da rede de produtos_similares.
    v_cname:=public.fn_extract_color_from_title(r.raw_data->>'titulo');
    v_chex := (SELECT split_part(item,'|',2)
               FROM unnest(string_to_array(r.raw_data->>'produtos_similares', ';')) item
               WHERE split_part(item,'|',1)=r.supplier_reference
                 AND split_part(item,'|',2) ~* '^#[0-9a-f]{6}$' LIMIT 1);
    v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque');
    v_cost:=public.fn_safe_num(r.raw_data->>'preco_sem_gravacao_sem_impostos');
    v_sku:=r.supplier_reference;
  ELSE
    v_cname:=r.raw_data->>'cor'; v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque'); v_cost:=public.fn_safe_num(r.raw_data->>'preco_base');
    v_sku:=r.supplier_reference;
  END IF;

  -- resolução do fornecedor (descritivos). Para SM não há catálogo, usa o extraído.
  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id, v_code, v_apiid, v_cname, v_chex);
  v_fname := COALESCE(v_col.color_name, v_cname);
  v_fcode := COALESCE(v_col.color_code, v_code);
  v_fhex  := COALESCE(v_col.color_hex,  v_chex);
  v_canonical_id := public.fn_match_canonical_color(v_fname, v_fhex);

  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id, supplier_id, parent_reference, variant_reference,
    sku, supplier_sku, color_name, color_code, color_hex, color_id,
    stock_quantity, cost_price, is_active, status
  ) VALUES (
    r.id, r.supplier_id, v_parent, r.supplier_reference, v_sku, v_supplier_sku,
    v_fname, v_fcode, v_fhex, v_canonical_id,
    v_stock, v_cost, true, 'standardized'::public.produtos_padronizacao_status
  )
  ON CONFLICT (supplier_id, variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, parent_reference=EXCLUDED.parent_reference, sku=EXCLUDED.sku, supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name, color_code=EXCLUDED.color_code, color_hex=EXCLUDED.color_hex, color_id=EXCLUDED.color_id,
    stock_quantity=EXCLUDED.stock_quantity, cost_price=EXCLUDED.cost_price, status=EXCLUDED.status, updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object('success',true,'variante_id',v_var_id,'parent',v_parent,
                            'cor',v_fname,'hex',v_fhex,'color_id_canonico',v_canonical_id);
END;
$$;

-- <<< END 20260604002410_silver_08g_variante_somarcas_cor_titulo.sql <<<

-- >>> BEGIN 20260604003839_silver_14_orquestrador_promocao_lote.sql >>>

-- ════════════════════════════════════════════════════════════════
-- ORQUESTRADOR DE PROMOÇÃO EM LOTE (silver → gold), por fornecedor.
-- Promove pais 'standardized' e suas variantes, na ordem correta
-- (pai antes das variantes). NULL-safe e idempotente (herdado das
-- funções fn_promote_padronizacao / fn_promote_variants_of_parent).
-- NÃO executa nada até ser chamado. p_limit permite lotes pequenos.
-- Cada pai em sub-bloco: erro num pai não aborta o lote inteiro.
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_promote_supplier(p_supplier_id uuid, p_limit integer DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE
  v_par RECORD;
  v_prom jsonb; v_vres jsonb;
  v_pais int := 0; v_novos int := 0; v_var int := 0; v_erros int := 0;
  v_t0 timestamptz := clock_timestamp();
  v_err_amostra jsonb := '[]'::jsonb;
BEGIN
  PERFORM set_config('app.write_source','pipeline', true);

  FOR v_par IN
    SELECT id, supplier_reference
    FROM public.produtos_padronizacao
    WHERE supplier_id = p_supplier_id AND status = 'standardized'
    ORDER BY supplier_reference
    LIMIT p_limit
  LOOP
    BEGIN
      v_prom := public.fn_promote_padronizacao(v_par.id);
      IF COALESCE((v_prom->>'success')::boolean, false) THEN
        v_pais := v_pais + 1;
        IF COALESCE((v_prom->>'created')::boolean, false) THEN v_novos := v_novos + 1; END IF;
        v_vres := public.fn_promote_variants_of_parent(p_supplier_id, v_par.supplier_reference);
        v_var := v_var + COALESCE((v_vres->>'variantes_promovidas')::int, 0);
      ELSE
        v_erros := v_erros + 1;
        IF jsonb_array_length(v_err_amostra) < 10 THEN
          v_err_amostra := v_err_amostra || jsonb_build_object('ref', v_par.supplier_reference, 'erro', v_prom->>'error');
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra || jsonb_build_object('ref', v_par.supplier_reference, 'erro', SQLERRM);
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'supplier_id', p_supplier_id,
    'pais_promovidos', v_pais, 'pais_novos', v_novos, 'variantes_promovidas', v_var,
    'erros', v_erros, 'amostra_erros', v_err_amostra,
    'segundos', round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1));
END;
$$;

COMMENT ON FUNCTION public.fn_promote_supplier IS
  'Orquestrador de promoção em lote silver→gold por fornecedor. NULL-safe, idempotente. ESCREVE no gold quando chamado.';

-- <<< END 20260604003839_silver_14_orquestrador_promocao_lote.sql <<<

