-- >>> BEGIN 20260604171814_motor_v2_create_fn_process_raw_v2.sql >>>
CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(
    p_supplier_id uuid,
    p_batch_size  integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_org_id            uuid;
    v_parent_key_source text;
    v_name_template     text;
    v_sku_prefix        text;
    v_prep              jsonb;
    v_parent            record;
    v_row               record;
    v_map               record;
    v_product_id        uuid;
    v_variant_id        uuid;
    v_vss_id            uuid;
    v_val               text;
    v_tv                text;
    v_parts             text[];
    v_vfields           jsonb;
    v_ssfields          jsonb;
    v_name              text;
    v_attrs             jsonb;
    v_sku               text;
    v_k                 text;
    v_v                 text;
    v_parents           integer := 0;
    v_variants          integer := 0;
    v_errors            jsonb := '[]'::jsonb;
BEGIN
    -- Segurança: bloqueia chamada direta por não-admin
    IF auth.uid() IS NOT NULL AND NOT is_admin_or_above((SELECT auth.uid())) THEN
        RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
    END IF;

    SELECT organization_id INTO v_org_id FROM suppliers WHERE id = p_supplier_id;

    SELECT parent_key_source, variant_name_template, sku_prefix
      INTO v_parent_key_source, v_name_template, v_sku_prefix
      FROM supplier_settings
     WHERE supplier_id = p_supplier_id;

    IF v_parent_key_source IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error', 'supplier_settings.parent_key_source ausente para o fornecedor '||p_supplier_id);
    END IF;
    v_name_template := COALESCE(v_name_template, '{product_name}');

    -- Itera grupos-pai entre as linhas ainda não processadas
    FOR v_parent IN
        SELECT DISTINCT raw_data->>v_parent_key_source AS pkey
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id
           AND processed = false
           AND NULLIF(raw_data->>v_parent_key_source,'') IS NOT NULL
         LIMIT p_batch_size
    LOOP
      BEGIN
        -- 1) Produto: achar ou criar por (supplier_id, supplier_reference = chave do pai)
        SELECT id INTO v_product_id
          FROM products
         WHERE supplier_id = p_supplier_id AND supplier_reference = v_parent.pkey;

        IF v_product_id IS NULL THEN
            INSERT INTO products (organization_id, supplier_id, supplier_reference, sku, name,
                                  active, is_active, sync_status, created_at, updated_at)
            VALUES (v_org_id, p_supplier_id, v_parent.pkey,
                    COALESCE(v_sku_prefix,'')||v_parent.pkey,
                    'Produto '||v_parent.pkey, true, true, 'processing', now(), now())
            RETURNING id INTO v_product_id;
        END IF;

        -- Linha representativa do grupo (campos de produto são constantes no grupo)
        SELECT raw_data INTO v_prep
          FROM supplier_products_raw
         WHERE supplier_id=p_supplier_id AND processed=false
           AND raw_data->>v_parent_key_source = v_parent.pkey
         ORDER BY imported_at NULLS LAST
         LIMIT 1;

        -- 2) Campos de produto (mappings target_table='products')
        v_parts := ARRAY[]::text[];
        FOR v_map IN
            SELECT * FROM supplier_field_mappings
             WHERE supplier_id=p_supplier_id AND target_table='products' AND is_active=true
             ORDER BY priority
        LOOP
            v_val := CASE WHEN v_map.source_path IS NOT NULL
                          THEN v_prep #>> string_to_array(v_map.source_path,'.')
                          ELSE v_prep ->> v_map.source_field END;
            CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
            v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                       v_map.source_unit, v_map.target_unit, p_supplier_id);
            IF v_tv IS NOT NULL THEN
                v_parts := array_append(v_parts, format('%I = %L', v_map.target_field, v_tv));
            END IF;
        END LOOP;

        IF array_length(v_parts,1) > 0 THEN
            EXECUTE format(
              'UPDATE products SET %s, updated_at=now(), sync_status=''synced'', last_sync_at=now(), last_sync_supplier_id=%L WHERE id=%L',
              array_to_string(v_parts,', '), p_supplier_id, v_product_id);
        END IF;

        UPDATE products
           SET dimensions_display = fn_format_dimensions_display(length_cm, width_cm, height_cm)
         WHERE id = v_product_id AND length_cm IS NOT NULL;

        -- 3) Variantes: cada linha raw não processada do grupo
        FOR v_row IN
            SELECT * FROM supplier_products_raw
             WHERE supplier_id=p_supplier_id AND processed=false
               AND raw_data->>v_parent_key_source = v_parent.pkey
        LOOP
          BEGIN
            -- 3a) Campos de variante (target_table='product_variants')
            v_vfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id=p_supplier_id AND target_table='product_variants' AND is_active=true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path,'.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_vfields := v_vfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            -- 3b) Nome via template + attributes de cor
            v_name := replace(v_name_template, '{product_name}',
                              COALESCE((SELECT name FROM products WHERE id=v_product_id),''));
            v_name := replace(v_name, '{color_name}', COALESCE(v_vfields->>'color_name',''));
            v_name := btrim(regexp_replace(v_name, '\s*[|-]\s*$', ''));  -- separador solto se cor vazia
            v_attrs := jsonb_build_object('codigo_cor', COALESCE(v_vfields->>'color_code',''),
                                          'cor',        COALESCE(v_vfields->>'color_name',''));
            v_sku := COALESCE(v_vfields->>'sku', NULLIF(v_row.supplier_sku,''), v_row.supplier_reference);

            -- 3c) Upsert da variante (sku é unique)
            INSERT INTO product_variants (product_id, sku, supplier_sku, name,
                                          color_code, color_name, color_hex, attributes, is_active, created_at, updated_at)
            VALUES (v_product_id, v_sku, v_row.supplier_sku, v_name,
                    v_vfields->>'color_code', v_vfields->>'color_name', v_vfields->>'color_hex',
                    v_attrs, true, now(), now())
            ON CONFLICT (sku) DO UPDATE SET
                name=EXCLUDED.name, color_code=EXCLUDED.color_code, color_name=EXCLUDED.color_name,
                color_hex=EXCLUDED.color_hex, attributes=EXCLUDED.attributes,
                supplier_sku=EXCLUDED.supplier_sku, updated_at=now()
            RETURNING id INTO v_variant_id;

            -- 3d) Demais campos de variante (capacity_ml, size_code, …) via UPDATE dinâmico
            v_parts := ARRAY[]::text[];
            FOR v_k, v_v IN
                SELECT key, value FROM jsonb_each_text(
                    v_vfields - 'sku' - 'color_code' - 'color_name' - 'color_hex')
            LOOP
                v_parts := array_append(v_parts, format('%I = %L', v_k, v_v));
            END LOOP;
            IF array_length(v_parts,1) > 0 THEN
                EXECUTE format('UPDATE product_variants SET %s, updated_at=now() WHERE id=%L',
                               array_to_string(v_parts,', '), v_variant_id);
            END IF;

            -- 3e) variant_supplier_sources: custo/estoque (target_table='variant_supplier_sources')
            v_ssfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id=p_supplier_id AND target_table='variant_supplier_sources' AND is_active=true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path,'.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_ssfields := v_ssfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            SELECT id INTO v_vss_id FROM variant_supplier_sources
             WHERE variant_id=v_variant_id AND supplier_id=p_supplier_id;
            IF v_vss_id IS NULL THEN
                INSERT INTO variant_supplier_sources (organization_id, variant_id, supplier_id, supplier_sku,
                                                      cost_price, quantity, source, is_preferred, is_active, updated_at)
                VALUES (v_org_id, v_variant_id, p_supplier_id, v_row.supplier_sku,
                        NULLIF(v_ssfields->>'cost_price','')::numeric,
                        COALESCE(NULLIF(v_ssfields->>'quantity','')::integer, 0),
                        'raw_v2', true, true, now());
            ELSE
                UPDATE variant_supplier_sources SET
                    cost_price   = COALESCE(NULLIF(v_ssfields->>'cost_price','')::numeric, cost_price),
                    quantity     = COALESCE(NULLIF(v_ssfields->>'quantity','')::integer, quantity),
                    supplier_sku = v_row.supplier_sku,
                    updated_at   = now()
                WHERE id=v_vss_id;
            END IF;

            -- 3f) Marca a linha raw como processada
            UPDATE supplier_products_raw
               SET processed=true, processed_at=now(), product_id=v_product_id, variant_id=v_variant_id
             WHERE id=v_row.id;
            v_variants := v_variants + 1;

          EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || jsonb_build_object('raw_id', v_row.id, 'stage','variant', 'error', SQLERRM);
          END;
        END LOOP;

        v_parents := v_parents + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_object('parent_key', v_parent.pkey, 'stage','parent', 'error', SQLERRM);
      END;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true, 'supplier_id', p_supplier_id,
        'parents_processed', v_parents, 'variants_processed', v_variants,
        'errors', v_errors);
END;
$function$;
-- <<< END 20260604171814_motor_v2_create_fn_process_raw_v2.sql <<<

-- >>> BEGIN 20260604172240_motor_v2_parity_harness.sql >>>
-- Harness de paridade: roda fn_process_raw_v2 numa amostra e REVERTE tudo (savepoint).
-- Não persiste nada no gold. Retorna before/after pra comparação campo-a-campo.
CREATE OR REPLACE FUNCTION public.fn_dryrun_raw_v2(p_supplier_id uuid, p_parents integer DEFAULT 3)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_pkey_field text;
  v_keys       text[];
  v_before     jsonb;
  v_after      jsonb;
  v_engine     jsonb;
  v_out        jsonb;
BEGIN
  SELECT parent_key_source INTO v_pkey_field FROM supplier_settings WHERE supplier_id=p_supplier_id;
  IF v_pkey_field IS NULL THEN
     RETURN jsonb_build_object('error','sem parent_key_source configurado');
  END IF;

  -- amostra: parents com mais de uma linha raw (testa o agrupamento 1:N)
  SELECT array_agg(pkey) INTO v_keys FROM (
     SELECT raw_data->>v_pkey_field AS pkey
       FROM supplier_products_raw
      WHERE supplier_id=p_supplier_id AND NULLIF(raw_data->>v_pkey_field,'') IS NOT NULL
      GROUP BY raw_data->>v_pkey_field
      HAVING count(*) > 1
      ORDER BY count(*) DESC
      LIMIT p_parents
  ) t;

  -- BEFORE: gold atual desses parents
  SELECT jsonb_agg(jsonb_build_object(
            'ref', p.supplier_reference, 'name', p.name,
            'box_h_cm', p.box_height_cm,
            'variantes', (SELECT jsonb_agg(jsonb_build_object('sku',x.sku,'name',x.name,'cor',x.color_name,'attrs',x.attributes))
                          FROM (SELECT sku,name,color_name,attributes FROM product_variants
                                 WHERE product_id=p.id ORDER BY sku LIMIT 5) x)))
    INTO v_before
    FROM products p
   WHERE p.supplier_id=p_supplier_id AND p.supplier_reference = ANY(v_keys);

  BEGIN
     -- desmarca a amostra p/ o motor pegar
     UPDATE supplier_products_raw SET processed=false
      WHERE supplier_id=p_supplier_id AND raw_data->>v_pkey_field = ANY(v_keys);

     v_engine := fn_process_raw_v2(p_supplier_id, p_parents + 10);

     SELECT jsonb_agg(jsonb_build_object(
               'ref', p.supplier_reference, 'name', p.name,
               'box_h_cm', p.box_height_cm,
               'variantes', (SELECT jsonb_agg(jsonb_build_object('sku',x.sku,'name',x.name,'cor',x.color_name,'attrs',x.attributes))
                             FROM (SELECT sku,name,color_name,attributes FROM product_variants
                                    WHERE product_id=p.id ORDER BY sku LIMIT 5) x)))
       INTO v_after
       FROM products p
      WHERE p.supplier_id=p_supplier_id AND p.supplier_reference = ANY(v_keys);

     v_out := jsonb_build_object('keys',to_jsonb(v_keys),'engine',v_engine,'before',v_before,'after',v_after);
     RAISE EXCEPTION 'DRYRUN_ROLLBACK';
  EXCEPTION WHEN OTHERS THEN
     IF SQLERRM <> 'DRYRUN_ROLLBACK' THEN
        v_out := jsonb_build_object('keys',to_jsonb(v_keys),'erro_motor',SQLERRM,'before',v_before);
     END IF;
  END;

  RETURN v_out;
END $function$;
-- <<< END 20260604172240_motor_v2_parity_harness.sql <<<

-- >>> BEGIN 20260604173140_motor_v2_variant_identity_supplier_sku.sql >>>
CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(
    p_supplier_id uuid,
    p_batch_size  integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_org_id            uuid;
    v_parent_key_source text;
    v_name_template     text;
    v_sku_prefix        text;
    v_prep              jsonb;
    v_parent            record;
    v_row               record;
    v_map               record;
    v_product_id        uuid;
    v_variant_id        uuid;
    v_vss_id            uuid;
    v_val               text;
    v_tv                text;
    v_parts             text[];
    v_vfields           jsonb;
    v_ssfields          jsonb;
    v_name              text;
    v_attrs             jsonb;
    v_sku               text;
    v_sup_sku           text;
    v_k                 text;
    v_v                 text;
    v_parents           integer := 0;
    v_variants          integer := 0;
    v_errors            jsonb := '[]'::jsonb;
BEGIN
    IF auth.uid() IS NOT NULL AND NOT is_admin_or_above((SELECT auth.uid())) THEN
        RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
    END IF;

    SELECT organization_id INTO v_org_id FROM suppliers WHERE id = p_supplier_id;

    SELECT parent_key_source, variant_name_template, sku_prefix
      INTO v_parent_key_source, v_name_template, v_sku_prefix
      FROM supplier_settings WHERE supplier_id = p_supplier_id;

    IF v_parent_key_source IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error', 'supplier_settings.parent_key_source ausente para o fornecedor '||p_supplier_id);
    END IF;
    v_name_template := COALESCE(v_name_template, '{product_name}');

    FOR v_parent IN
        SELECT DISTINCT raw_data->>v_parent_key_source AS pkey
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id AND processed = false
           AND NULLIF(raw_data->>v_parent_key_source,'') IS NOT NULL
         LIMIT p_batch_size
    LOOP
      BEGIN
        -- 1) Produto: achar ou criar por (supplier_id, supplier_reference = chave do pai)
        SELECT id INTO v_product_id
          FROM products
         WHERE supplier_id = p_supplier_id AND supplier_reference = v_parent.pkey;

        IF v_product_id IS NULL THEN
            INSERT INTO products (organization_id, supplier_id, supplier_reference, sku, name,
                                  active, is_active, sync_status, created_at, updated_at)
            VALUES (v_org_id, p_supplier_id, v_parent.pkey,
                    COALESCE(v_sku_prefix,'')||v_parent.pkey,
                    'Produto '||v_parent.pkey, true, true, 'processing', now(), now())
            RETURNING id INTO v_product_id;
        END IF;

        SELECT raw_data INTO v_prep
          FROM supplier_products_raw
         WHERE supplier_id=p_supplier_id AND processed=false
           AND raw_data->>v_parent_key_source = v_parent.pkey
         ORDER BY imported_at NULLS LAST LIMIT 1;

        -- 2) Campos de produto
        v_parts := ARRAY[]::text[];
        FOR v_map IN
            SELECT * FROM supplier_field_mappings
             WHERE supplier_id=p_supplier_id AND target_table='products' AND is_active=true
             ORDER BY priority
        LOOP
            v_val := CASE WHEN v_map.source_path IS NOT NULL
                          THEN v_prep #>> string_to_array(v_map.source_path,'.')
                          ELSE v_prep ->> v_map.source_field END;
            CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
            v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                       v_map.source_unit, v_map.target_unit, p_supplier_id);
            IF v_tv IS NOT NULL THEN
                v_parts := array_append(v_parts, format('%I = %L', v_map.target_field, v_tv));
            END IF;
        END LOOP;

        IF array_length(v_parts,1) > 0 THEN
            EXECUTE format(
              'UPDATE products SET %s, updated_at=now(), sync_status=''synced'', last_sync_at=now(), last_sync_supplier_id=%L WHERE id=%L',
              array_to_string(v_parts,', '), p_supplier_id, v_product_id);
        END IF;

        UPDATE products
           SET dimensions_display = fn_format_dimensions_display(length_cm, width_cm, height_cm)
         WHERE id = v_product_id AND length_cm IS NOT NULL;

        -- 3) Variantes
        FOR v_row IN
            SELECT * FROM supplier_products_raw
             WHERE supplier_id=p_supplier_id AND processed=false
               AND raw_data->>v_parent_key_source = v_parent.pkey
        LOOP
          BEGIN
            v_vfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id=p_supplier_id AND target_table='product_variants' AND is_active=true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path,'.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_vfields := v_vfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            -- Nome via template + attributes de cor
            v_name := replace(v_name_template, '{product_name}',
                              COALESCE((SELECT name FROM products WHERE id=v_product_id),''));
            v_name := replace(v_name, '{color_name}', COALESCE(v_vfields->>'color_name',''));
            v_name := btrim(regexp_replace(v_name, '\s*[|-]\s*$', ''));
            v_attrs := jsonb_build_object('codigo_cor', COALESCE(v_vfields->>'color_code',''),
                                          'cor',        COALESCE(v_vfields->>'color_name',''));

            -- IDENTIDADE = supplier_sku (chave estável do fornecedor); preserva o SKU público existente
            v_sup_sku := NULLIF(v_row.supplier_sku, '');
            v_variant_id := NULL;
            IF v_sup_sku IS NOT NULL THEN
                SELECT id INTO v_variant_id FROM product_variants
                 WHERE product_id = v_product_id AND supplier_sku = v_sup_sku;
            END IF;

            IF v_variant_id IS NULL THEN
                -- Variante nova: SKU público = mapping 'sku' (se houver) > supplier_sku > supplier_reference
                v_sku := COALESCE(v_vfields->>'sku', v_sup_sku, v_row.supplier_reference);
                INSERT INTO product_variants (product_id, sku, supplier_sku, name,
                                              color_code, color_name, color_hex, attributes, is_active, created_at, updated_at)
                VALUES (v_product_id, v_sku, v_sup_sku, v_name,
                        v_vfields->>'color_code', v_vfields->>'color_name', v_vfields->>'color_hex',
                        v_attrs, true, now(), now())
                ON CONFLICT (sku) DO UPDATE SET
                    supplier_sku=EXCLUDED.supplier_sku, name=EXCLUDED.name, color_code=EXCLUDED.color_code,
                    color_name=EXCLUDED.color_name, color_hex=EXCLUDED.color_hex, attributes=EXCLUDED.attributes,
                    updated_at=now()
                RETURNING id INTO v_variant_id;
            ELSE
                -- Variante existente: preserva o SKU público do gold, atualiza o resto
                UPDATE product_variants SET
                    name=v_name, color_code=v_vfields->>'color_code', color_name=v_vfields->>'color_name',
                    color_hex=v_vfields->>'color_hex', attributes=v_attrs, updated_at=now()
                WHERE id=v_variant_id;
            END IF;

            -- Demais campos de variante (size_code, capacity_ml, …) via UPDATE dinâmico
            v_parts := ARRAY[]::text[];
            FOR v_k, v_v IN
                SELECT key, value FROM jsonb_each_text(
                    v_vfields - 'sku' - 'supplier_sku' - 'color_code' - 'color_name' - 'color_hex')
            LOOP
                v_parts := array_append(v_parts, format('%I = %L', v_k, v_v));
            END LOOP;
            IF array_length(v_parts,1) > 0 THEN
                EXECUTE format('UPDATE product_variants SET %s, updated_at=now() WHERE id=%L',
                               array_to_string(v_parts,', '), v_variant_id);
            END IF;

            -- variant_supplier_sources (custo/estoque)
            v_ssfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id=p_supplier_id AND target_table='variant_supplier_sources' AND is_active=true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path,'.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_ssfields := v_ssfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            IF v_ssfields <> '{}'::jsonb THEN
                SELECT id INTO v_vss_id FROM variant_supplier_sources
                 WHERE variant_id=v_variant_id AND supplier_id=p_supplier_id;
                IF v_vss_id IS NULL THEN
                    INSERT INTO variant_supplier_sources (organization_id, variant_id, supplier_id, supplier_sku,
                                                          cost_price, quantity, source, is_preferred, is_active, updated_at)
                    VALUES (v_org_id, v_variant_id, p_supplier_id, v_sup_sku,
                            NULLIF(v_ssfields->>'cost_price','')::numeric,
                            COALESCE(NULLIF(v_ssfields->>'quantity','')::integer, 0),
                            'raw_v2', true, true, now());
                ELSE
                    UPDATE variant_supplier_sources SET
                        cost_price = COALESCE(NULLIF(v_ssfields->>'cost_price','')::numeric, cost_price),
                        quantity   = COALESCE(NULLIF(v_ssfields->>'quantity','')::integer, quantity),
                        updated_at = now()
                    WHERE id=v_vss_id;
                END IF;
            END IF;

            UPDATE supplier_products_raw
               SET processed=true, processed_at=now(), product_id=v_product_id, variant_id=v_variant_id
             WHERE id=v_row.id;
            v_variants := v_variants + 1;

          EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || jsonb_build_object('raw_id', v_row.id, 'stage','variant', 'error', SQLERRM);
          END;
        END LOOP;

        v_parents := v_parents + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_object('parent_key', v_parent.pkey, 'stage','parent', 'error', SQLERRM);
      END;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true, 'supplier_id', p_supplier_id,
        'parents_processed', v_parents, 'variants_processed', v_variants, 'errors', v_errors);
END;
$function$;
-- <<< END 20260604173140_motor_v2_variant_identity_supplier_sku.sql <<<

-- >>> BEGIN 20260604173153_spot_activate_variant_mappings_and_template.sql >>>
-- Ativa só as regras de variante de coluna REAL (cor + size + capacity).
-- web_sku / length_cm / width_cm continuam inativas (colunas fantasma na variante).
UPDATE supplier_field_mappings
   SET is_active = true, updated_at = now()
 WHERE supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
   AND target_table = 'product_variants'
   AND target_field IN ('color_code','color_name','color_hex','size_code','capacity_ml');

-- Nome da variante no Spot = nome do produto (sem sufixo de cor), como no gold.
UPDATE supplier_settings
   SET variant_name_template = '{product_name}', updated_at = now()
 WHERE supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
-- <<< END 20260604173153_spot_activate_variant_mappings_and_template.sql <<<

-- >>> BEGIN 20260604173213_motor_v2_parity_harness_v2.sql >>>
CREATE OR REPLACE FUNCTION public.fn_dryrun_raw_v2(p_supplier_id uuid, p_parents integer DEFAULT 3)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_pkey_field text;
  v_keys       text[];
  v_before     jsonb;
  v_after      jsonb;
  v_engine     jsonb;
  v_out        jsonb;
BEGIN
  SELECT parent_key_source INTO v_pkey_field FROM supplier_settings WHERE supplier_id=p_supplier_id;
  IF v_pkey_field IS NULL THEN RETURN jsonb_build_object('error','sem parent_key_source'); END IF;

  SELECT array_agg(pkey) INTO v_keys FROM (
     SELECT raw_data->>v_pkey_field AS pkey
       FROM supplier_products_raw
      WHERE supplier_id=p_supplier_id AND NULLIF(raw_data->>v_pkey_field,'') IS NOT NULL
      GROUP BY raw_data->>v_pkey_field HAVING count(*) > 1
      ORDER BY count(*) DESC LIMIT p_parents
  ) t;

  SELECT jsonb_object_agg(ref, jsonb_build_object('name',name,'n_variantes',n,'amostra',amostra)) INTO v_before
  FROM (
     SELECT p.supplier_reference ref, p.name,
            (SELECT count(*) FROM product_variants v WHERE v.product_id=p.id) n,
            (SELECT jsonb_agg(jsonb_build_object('sku',x.sku,'sup_sku',x.supplier_sku,'cor',x.color_name,'attrs',x.attributes))
               FROM (SELECT sku,supplier_sku,color_name,attributes FROM product_variants
                      WHERE product_id=p.id ORDER BY sku LIMIT 3) x) amostra
       FROM products p WHERE p.supplier_id=p_supplier_id AND p.supplier_reference=ANY(v_keys)
  ) q;

  BEGIN
     UPDATE supplier_products_raw SET processed=false
      WHERE supplier_id=p_supplier_id AND raw_data->>v_pkey_field = ANY(v_keys);

     v_engine := fn_process_raw_v2(p_supplier_id, p_parents + 10);

     SELECT jsonb_object_agg(ref, jsonb_build_object('name',name,'n_variantes',n,'amostra',amostra)) INTO v_after
     FROM (
        SELECT p.supplier_reference ref, p.name,
               (SELECT count(*) FROM product_variants v WHERE v.product_id=p.id) n,
               (SELECT jsonb_agg(jsonb_build_object('sku',x.sku,'sup_sku',x.supplier_sku,'cor',x.color_name,'attrs',x.attributes))
                  FROM (SELECT sku,supplier_sku,color_name,attributes FROM product_variants
                         WHERE product_id=p.id ORDER BY sku LIMIT 3) x) amostra
          FROM products p WHERE p.supplier_id=p_supplier_id AND p.supplier_reference=ANY(v_keys)
     ) q;

     v_out := jsonb_build_object('keys',to_jsonb(v_keys),'engine',v_engine,'before',v_before,'after',v_after);
     RAISE EXCEPTION 'DRYRUN_ROLLBACK';
  EXCEPTION WHEN OTHERS THEN
     IF SQLERRM <> 'DRYRUN_ROLLBACK' THEN
        v_out := jsonb_build_object('keys',to_jsonb(v_keys),'erro_motor',SQLERRM,'before',v_before);
     END IF;
  END;
  RETURN v_out;
END $function$;
-- <<< END 20260604173213_motor_v2_parity_harness_v2.sql <<<

-- >>> BEGIN 20260604174303_motor_v2_respect_locks_and_write_source.sql >>>
CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(
    p_supplier_id uuid,
    p_batch_size  integer DEFAULT 100,
    p_bulk_mode   boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_org_id            uuid;
    v_parent_key_source text;
    v_name_template     text;
    v_sku_prefix        text;
    v_prep              jsonb;
    v_parent            record;
    v_row               record;
    v_map               record;
    v_product_id        uuid;
    v_variant_id        uuid;
    v_vss_id            uuid;
    v_locked            text[];
    v_val               text;
    v_tv                text;
    v_parts             text[];
    v_vfields           jsonb;
    v_ssfields          jsonb;
    v_name              text;
    v_attrs             jsonb;
    v_sku               text;
    v_sup_sku           text;
    v_k                 text;
    v_v                 text;
    v_parents           integer := 0;
    v_variants          integer := 0;
    v_errors            jsonb := '[]'::jsonb;
BEGIN
    IF auth.uid() IS NOT NULL AND NOT is_admin_or_above((SELECT auth.uid())) THEN
        RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
    END IF;

    -- Escrita identificada como pipeline (evita auto-lock no trg_aa_capture_manual_edits)
    PERFORM set_config('app.write_source', 'pipeline', true);
    -- Suprime triggers pesados de enriquecimento durante processamento em massa
    PERFORM set_config('app.bulk_import_mode', p_bulk_mode::text, true);

    SELECT organization_id INTO v_org_id FROM suppliers WHERE id = p_supplier_id;

    SELECT parent_key_source, variant_name_template, sku_prefix
      INTO v_parent_key_source, v_name_template, v_sku_prefix
      FROM supplier_settings WHERE supplier_id = p_supplier_id;

    IF v_parent_key_source IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error', 'supplier_settings.parent_key_source ausente para o fornecedor '||p_supplier_id);
    END IF;
    v_name_template := COALESCE(v_name_template, '{product_name}');

    FOR v_parent IN
        SELECT DISTINCT raw_data->>v_parent_key_source AS pkey
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id AND processed = false
           AND NULLIF(raw_data->>v_parent_key_source,'') IS NOT NULL
         LIMIT p_batch_size
    LOOP
      BEGIN
        -- 1) Produto: achar ou criar por (supplier_id, supplier_reference = chave do pai)
        SELECT id INTO v_product_id
          FROM products
         WHERE supplier_id = p_supplier_id AND supplier_reference = v_parent.pkey;

        IF v_product_id IS NULL THEN
            INSERT INTO products (organization_id, supplier_id, supplier_reference, sku, name,
                                  active, is_active, sync_status, created_at, updated_at)
            VALUES (v_org_id, p_supplier_id, v_parent.pkey,
                    COALESCE(v_sku_prefix,'')||v_parent.pkey,
                    'Produto '||v_parent.pkey, true, true, 'processing', now(), now())
            RETURNING id INTO v_product_id;
        END IF;

        -- Campos travados pela curadoria humana (não sobrescrever)
        SELECT COALESCE(locked_fields, '{}'::text[]) INTO v_locked
          FROM products WHERE id = v_product_id;

        SELECT raw_data INTO v_prep
          FROM supplier_products_raw
         WHERE supplier_id=p_supplier_id AND processed=false
           AND raw_data->>v_parent_key_source = v_parent.pkey
         ORDER BY imported_at NULLS LAST LIMIT 1;

        -- 2) Campos de produto (pulando os travados)
        v_parts := ARRAY[]::text[];
        FOR v_map IN
            SELECT * FROM supplier_field_mappings
             WHERE supplier_id=p_supplier_id AND target_table='products' AND is_active=true
             ORDER BY priority
        LOOP
            CONTINUE WHEN v_map.target_field = ANY(v_locked);
            v_val := CASE WHEN v_map.source_path IS NOT NULL
                          THEN v_prep #>> string_to_array(v_map.source_path,'.')
                          ELSE v_prep ->> v_map.source_field END;
            CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
            v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                       v_map.source_unit, v_map.target_unit, p_supplier_id);
            IF v_tv IS NOT NULL THEN
                v_parts := array_append(v_parts, format('%I = %L', v_map.target_field, v_tv));
            END IF;
        END LOOP;

        IF array_length(v_parts,1) > 0 THEN
            EXECUTE format(
              'UPDATE products SET %s, updated_at=now(), sync_status=''synced'', last_sync_at=now(), last_sync_supplier_id=%L WHERE id=%L',
              array_to_string(v_parts,', '), p_supplier_id, v_product_id);
        END IF;

        UPDATE products
           SET dimensions_display = fn_format_dimensions_display(length_cm, width_cm, height_cm)
         WHERE id = v_product_id AND length_cm IS NOT NULL
           AND NOT ('dimensions_display' = ANY(v_locked));

        -- 3) Variantes
        FOR v_row IN
            SELECT * FROM supplier_products_raw
             WHERE supplier_id=p_supplier_id AND processed=false
               AND raw_data->>v_parent_key_source = v_parent.pkey
        LOOP
          BEGIN
            v_vfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id=p_supplier_id AND target_table='product_variants' AND is_active=true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path,'.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_vfields := v_vfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            v_name := replace(v_name_template, '{product_name}',
                              COALESCE((SELECT name FROM products WHERE id=v_product_id),''));
            v_name := replace(v_name, '{color_name}', COALESCE(v_vfields->>'color_name',''));
            v_name := btrim(regexp_replace(v_name, '\s*[|-]\s*$', ''));
            v_attrs := jsonb_build_object('codigo_cor', COALESCE(v_vfields->>'color_code',''),
                                          'cor',        COALESCE(v_vfields->>'color_name',''));

            v_sup_sku := NULLIF(v_row.supplier_sku, '');
            v_variant_id := NULL;
            IF v_sup_sku IS NOT NULL THEN
                SELECT id INTO v_variant_id FROM product_variants
                 WHERE product_id = v_product_id AND supplier_sku = v_sup_sku;
            END IF;

            IF v_variant_id IS NULL THEN
                v_sku := COALESCE(v_vfields->>'sku', v_sup_sku, v_row.supplier_reference);
                INSERT INTO product_variants (product_id, sku, supplier_sku, name,
                                              color_code, color_name, color_hex, attributes, is_active, created_at, updated_at)
                VALUES (v_product_id, v_sku, v_sup_sku, v_name,
                        v_vfields->>'color_code', v_vfields->>'color_name', v_vfields->>'color_hex',
                        v_attrs, true, now(), now())
                ON CONFLICT (sku) DO UPDATE SET
                    supplier_sku=EXCLUDED.supplier_sku, name=EXCLUDED.name, color_code=EXCLUDED.color_code,
                    color_name=EXCLUDED.color_name, color_hex=EXCLUDED.color_hex, attributes=EXCLUDED.attributes,
                    updated_at=now()
                RETURNING id INTO v_variant_id;
            ELSE
                UPDATE product_variants SET
                    name=v_name, color_code=v_vfields->>'color_code', color_name=v_vfields->>'color_name',
                    color_hex=v_vfields->>'color_hex', attributes=v_attrs, updated_at=now()
                WHERE id=v_variant_id;
            END IF;

            v_parts := ARRAY[]::text[];
            FOR v_k, v_v IN
                SELECT key, value FROM jsonb_each_text(
                    v_vfields - 'sku' - 'supplier_sku' - 'color_code' - 'color_name' - 'color_hex')
            LOOP
                v_parts := array_append(v_parts, format('%I = %L', v_k, v_v));
            END LOOP;
            IF array_length(v_parts,1) > 0 THEN
                EXECUTE format('UPDATE product_variants SET %s, updated_at=now() WHERE id=%L',
                               array_to_string(v_parts,', '), v_variant_id);
            END IF;

            v_ssfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id=p_supplier_id AND target_table='variant_supplier_sources' AND is_active=true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path,'.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_ssfields := v_ssfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            IF v_ssfields <> '{}'::jsonb THEN
                SELECT id INTO v_vss_id FROM variant_supplier_sources
                 WHERE variant_id=v_variant_id AND supplier_id=p_supplier_id;
                IF v_vss_id IS NULL THEN
                    INSERT INTO variant_supplier_sources (organization_id, variant_id, supplier_id, supplier_sku,
                                                          cost_price, quantity, source, is_preferred, is_active, updated_at)
                    VALUES (v_org_id, v_variant_id, p_supplier_id, v_sup_sku,
                            NULLIF(v_ssfields->>'cost_price','')::numeric,
                            COALESCE(NULLIF(v_ssfields->>'quantity','')::integer, 0),
                            'raw_v2', true, true, now());
                ELSE
                    UPDATE variant_supplier_sources SET
                        cost_price = COALESCE(NULLIF(v_ssfields->>'cost_price','')::numeric, cost_price),
                        quantity   = COALESCE(NULLIF(v_ssfields->>'quantity','')::integer, quantity),
                        updated_at = now()
                    WHERE id=v_vss_id;
                END IF;
            END IF;

            UPDATE supplier_products_raw
               SET processed=true, processed_at=now(), product_id=v_product_id, variant_id=v_variant_id
             WHERE id=v_row.id;
            v_variants := v_variants + 1;

          EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || jsonb_build_object('raw_id', v_row.id, 'stage','variant', 'error', SQLERRM);
          END;
        END LOOP;

        v_parents := v_parents + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_object('parent_key', v_parent.pkey, 'stage','parent', 'error', SQLERRM);
      END;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true, 'supplier_id', p_supplier_id, 'bulk_mode', p_bulk_mode,
        'parents_processed', v_parents, 'variants_processed', v_variants, 'errors', v_errors);
END;
$function$;
-- <<< END 20260604174303_motor_v2_respect_locks_and_write_source.sql <<<

-- >>> BEGIN 20260604174339_motor_v2_parity_harness_v3.sql >>>
CREATE OR REPLACE FUNCTION public.fn_dryrun_raw_v2(p_supplier_id uuid, p_parents integer DEFAULT 3)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_pkey_field text;
  v_keys       text[];
  v_before     jsonb;
  v_after      jsonb;
  v_engine     jsonb;
  v_out        jsonb;
BEGIN
  SELECT parent_key_source INTO v_pkey_field FROM supplier_settings WHERE supplier_id=p_supplier_id;
  IF v_pkey_field IS NULL THEN RETURN jsonb_build_object('error','sem parent_key_source'); END IF;

  SELECT array_agg(pkey) INTO v_keys FROM (
     SELECT raw_data->>v_pkey_field AS pkey
       FROM supplier_products_raw
      WHERE supplier_id=p_supplier_id AND NULLIF(raw_data->>v_pkey_field,'') IS NOT NULL
      GROUP BY raw_data->>v_pkey_field HAVING count(*) > 1
      ORDER BY count(*) DESC LIMIT p_parents
  ) t;

  SELECT jsonb_object_agg(ref, jsonb_build_object(
            'name',name,'brand',brand,'origin',origin,'box_w',box_w,'box_q',box_q,
            'pack_class',pack_class,'main_cat',main_cat,'is_active',is_active,
            'n_locked',n_locked,'attrs_prod',attrs_prod,'n_variantes',nv,'amostra',amostra)) INTO v_before
  FROM (
     SELECT p.supplier_reference ref, p.name, p.brand, p.origin_country origin,
            p.box_weight_kg box_w, p.box_quantity box_q, p.packing_classification pack_class,
            p.main_category_id main_cat, p.is_active,
            COALESCE(array_length(p.locked_fields,1),0) n_locked, p.attributes attrs_prod,
            (SELECT count(*) FROM product_variants v WHERE v.product_id=p.id) nv,
            (SELECT jsonb_agg(jsonb_build_object('sku',x.sku,'sup_sku',x.supplier_sku,'cor',x.color_name,'attrs',x.attributes))
               FROM (SELECT sku,supplier_sku,color_name,attributes FROM product_variants
                      WHERE product_id=p.id ORDER BY sku LIMIT 2) x) amostra
       FROM products p WHERE p.supplier_id=p_supplier_id AND p.supplier_reference=ANY(v_keys)
  ) q;

  BEGIN
     UPDATE supplier_products_raw SET processed=false
      WHERE supplier_id=p_supplier_id AND raw_data->>v_pkey_field = ANY(v_keys);

     v_engine := fn_process_raw_v2(p_supplier_id, p_parents + 10);

     SELECT jsonb_object_agg(ref, jsonb_build_object(
               'name',name,'brand',brand,'origin',origin,'box_w',box_w,'box_q',box_q,
               'pack_class',pack_class,'main_cat',main_cat,'is_active',is_active,
               'n_locked',n_locked,'attrs_prod',attrs_prod,'n_variantes',nv,'amostra',amostra)) INTO v_after
     FROM (
        SELECT p.supplier_reference ref, p.name, p.brand, p.origin_country origin,
               p.box_weight_kg box_w, p.box_quantity box_q, p.packing_classification pack_class,
               p.main_category_id main_cat, p.is_active,
               COALESCE(array_length(p.locked_fields,1),0) n_locked, p.attributes attrs_prod,
               (SELECT count(*) FROM product_variants v WHERE v.product_id=p.id) nv,
               (SELECT jsonb_agg(jsonb_build_object('sku',x.sku,'sup_sku',x.supplier_sku,'cor',x.color_name,'attrs',x.attributes))
                  FROM (SELECT sku,supplier_sku,color_name,attributes FROM product_variants
                         WHERE product_id=p.id ORDER BY sku LIMIT 2) x) amostra
          FROM products p WHERE p.supplier_id=p_supplier_id AND p.supplier_reference=ANY(v_keys)
     ) q;

     v_out := jsonb_build_object('keys',to_jsonb(v_keys),'engine',v_engine,'before',v_before,'after',v_after);
     RAISE EXCEPTION 'DRYRUN_ROLLBACK';
  EXCEPTION WHEN OTHERS THEN
     IF SQLERRM <> 'DRYRUN_ROLLBACK' THEN
        v_out := jsonb_build_object('keys',to_jsonb(v_keys),'erro_motor',SQLERRM,'before',v_before);
     END IF;
  END;
  RETURN v_out;
END $function$;
-- <<< END 20260604174339_motor_v2_parity_harness_v3.sql <<<

-- >>> BEGIN 20260604174413_motor_v2_parity_harness_v3b.sql >>>
CREATE OR REPLACE FUNCTION public.fn_dryrun_raw_v2(p_supplier_id uuid, p_parents integer DEFAULT 3)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_pkey_field text;
  v_keys       text[];
  v_before     jsonb;
  v_after      jsonb;
  v_engine     jsonb;
  v_out        jsonb;
BEGIN
  SELECT parent_key_source INTO v_pkey_field FROM supplier_settings WHERE supplier_id=p_supplier_id;
  IF v_pkey_field IS NULL THEN RETURN jsonb_build_object('error','sem parent_key_source'); END IF;

  SELECT array_agg(pkey) INTO v_keys FROM (
     SELECT raw_data->>v_pkey_field AS pkey
       FROM supplier_products_raw
      WHERE supplier_id=p_supplier_id AND NULLIF(raw_data->>v_pkey_field,'') IS NOT NULL
      GROUP BY raw_data->>v_pkey_field HAVING count(*) > 1
      ORDER BY count(*) DESC LIMIT p_parents
  ) t;

  SELECT jsonb_object_agg(ref, jsonb_build_object(
            'name',name,'brand',brand,'origin',origin,'box_w',box_w,'box_q',box_q,
            'pack_class',pack_class,'main_cat',main_cat,'is_active',is_active,
            'n_locked',n_locked,'n_variantes',nv,'amostra',amostra)) INTO v_before
  FROM (
     SELECT p.supplier_reference ref, p.name, p.brand, p.origin_country origin,
            p.box_weight_kg box_w, p.box_quantity box_q, p.packing_classification pack_class,
            p.main_category_id main_cat, p.is_active,
            COALESCE(array_length(p.locked_fields,1),0) n_locked,
            (SELECT count(*) FROM product_variants v WHERE v.product_id=p.id) nv,
            (SELECT jsonb_agg(jsonb_build_object('sku',x.sku,'sup_sku',x.supplier_sku,'cor',x.color_name,'attrs',x.attributes))
               FROM (SELECT sku,supplier_sku,color_name,attributes FROM product_variants
                      WHERE product_id=p.id ORDER BY sku LIMIT 2) x) amostra
       FROM products p WHERE p.supplier_id=p_supplier_id AND p.supplier_reference=ANY(v_keys)
  ) q;

  BEGIN
     UPDATE supplier_products_raw SET processed=false
      WHERE supplier_id=p_supplier_id AND raw_data->>v_pkey_field = ANY(v_keys);

     v_engine := fn_process_raw_v2(p_supplier_id, p_parents + 10);

     SELECT jsonb_object_agg(ref, jsonb_build_object(
               'name',name,'brand',brand,'origin',origin,'box_w',box_w,'box_q',box_q,
               'pack_class',pack_class,'main_cat',main_cat,'is_active',is_active,
               'n_locked',n_locked,'n_variantes',nv,'amostra',amostra)) INTO v_after
     FROM (
        SELECT p.supplier_reference ref, p.name, p.brand, p.origin_country origin,
               p.box_weight_kg box_w, p.box_quantity box_q, p.packing_classification pack_class,
               p.main_category_id main_cat, p.is_active,
               COALESCE(array_length(p.locked_fields,1),0) n_locked,
               (SELECT count(*) FROM product_variants v WHERE v.product_id=p.id) nv,
               (SELECT jsonb_agg(jsonb_build_object('sku',x.sku,'sup_sku',x.supplier_sku,'cor',x.color_name,'attrs',x.attributes))
                  FROM (SELECT sku,supplier_sku,color_name,attributes FROM product_variants
                         WHERE product_id=p.id ORDER BY sku LIMIT 2) x) amostra
          FROM products p WHERE p.supplier_id=p_supplier_id AND p.supplier_reference=ANY(v_keys)
     ) q;

     v_out := jsonb_build_object('keys',to_jsonb(v_keys),'engine',v_engine,'before',v_before,'after',v_after);
     RAISE EXCEPTION 'DRYRUN_ROLLBACK';
  EXCEPTION WHEN OTHERS THEN
     IF SQLERRM <> 'DRYRUN_ROLLBACK' THEN
        v_out := jsonb_build_object('keys',to_jsonb(v_keys),'erro_motor',SQLERRM,'before',v_before);
     END IF;
  END;
  RETURN v_out;
END $function$;
-- <<< END 20260604174413_motor_v2_parity_harness_v3b.sql <<<

