-- >>> BEGIN 20260604233004_spr_maintenance_and_history_retention.sql >>>
-- P3: manutenção e retenção.

-- 1) fillfactor + autovacuum mais agressivo. Como muitos UPDATEs tocam colunas
--    indexadas, deixar folga na página favorece HOT-updates e reduz bloat de índice.
ALTER TABLE public.supplier_products_raw
  SET (fillfactor = 90,
       autovacuum_vacuum_scale_factor = 0.05,
       autovacuum_analyze_scale_factor = 0.02);

ALTER TABLE public.supplier_products_raw_history
  SET (autovacuum_vacuum_scale_factor = 0.1);

-- 2) Retenção do histórico (cresce a cada mudança de content_hash, sem limite).
--    Mantém 90 dias.
CREATE OR REPLACE FUNCTION public.fn_purge_spr_history(p_keep_days integer DEFAULT 90)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE v_deleted integer;
BEGIN
  DELETE FROM public.supplier_products_raw_history
   WHERE captured_at < now() - make_interval(days => p_keep_days);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END $$;

-- Agenda diária da retenção (03:30).
SELECT cron.schedule('purge-spr-history-daily', '30 3 * * *',
  $$SELECT public.fn_purge_spr_history(90);$$);

-- 3) Inclui as tabelas raw + history no VACUUM ANALYZE semanal existente (jobid/nome
--    'vacuum-analyze-weekly'). Reaproveita o mesmo job por nome (idempotente).
SELECT cron.schedule('vacuum-analyze-weekly', '0 2 * * 6', $$
    VACUUM ANALYZE public.product_images;
    VACUUM ANALYZE public.product_relationships;
    VACUUM ANALYZE public.products;
    VACUUM ANALYZE public.product_variants;
    VACUUM ANALYZE public.supplier_import_batches;
    VACUUM ANALYZE public.product_category_assignments;
    VACUUM ANALYZE public.admin_audit_log;
    VACUUM ANALYZE public.frontend_telemetry;
    VACUUM ANALYZE public.supplier_products_raw;
    VACUUM ANALYZE public.supplier_products_raw_history;
    $$);

-- <<< END 20260604233004_spr_maintenance_and_history_retention.sql <<<

-- >>> BEGIN 20260604233005_spr_cutover_status_part1.sql >>>
-- CUTOVER (parte 1/2): tornar `status` (enum) a fonte única da verdade.
-- Reescreve views/funções/triggers para não dependerem mais do booleano `processed`
-- nem do `raw_hash` legado. A coluna física só é removida na parte 2/2.
-- Semântica preservada: processed = (status = 'processed') com 0 divergências hoje.

-- 1) Views: troca predicados processed=true/false por status (preservando contrato e
--    a opção security_invoker). Feito via pg_get_viewdef+regex para não transcrever as
--    views grandes (ex.: v_system_health_dashboard) à mão.
DO $vw$
DECLARE r record; v_new text;
BEGIN
  FOR r IN
    SELECT viewname FROM pg_views
     WHERE schemaname = 'public'
       AND viewname IN ('v_system_alerts','v_system_health_dashboard',
                        'vw_asia_products_by_category','vw_asia_products_pending',
                        'vw_asia_products_stats','vw_somarcas_pending','vw_somarcas_stats',
                        'vw_somarcas_sync_status','vw_xbz_products_stats')
  LOOP
    v_new := pg_get_viewdef(('public.'||r.viewname)::regclass, true);
    -- processed = true  -> status = 'processed'
    v_new := regexp_replace(v_new,
      '([a-z0-9_]+\.)?\mprocessed\M\s*=\s*true',
      '\1status = ''processed''::supplier_raw_status', 'gi');
    -- processed = false OR processed IS NULL  -> status <> 'processed'
    v_new := regexp_replace(v_new,
      '([a-z0-9_]+\.)?\mprocessed\M\s*=\s*false\s+OR\s+([a-z0-9_]+\.)?\mprocessed\M\s+IS\s+NULL',
      '\1status <> ''processed''::supplier_raw_status', 'gi');
    -- processed = false  -> status <> 'processed'
    v_new := regexp_replace(v_new,
      '([a-z0-9_]+\.)?\mprocessed\M\s*=\s*false',
      '\1status <> ''processed''::supplier_raw_status', 'gi');

    EXECUTE 'CREATE OR REPLACE VIEW public.'||quote_ident(r.viewname)||' AS '||v_new;
    EXECUTE 'ALTER VIEW public.'||quote_ident(r.viewname)||' SET (security_invoker = on)';
  END LOOP;

  IF EXISTS (
    SELECT 1 FROM pg_views
     WHERE schemaname='public'
       AND viewname IN ('v_system_alerts','v_system_health_dashboard',
                        'vw_asia_products_by_category','vw_asia_products_pending',
                        'vw_asia_products_stats','vw_somarcas_pending','vw_somarcas_stats',
                        'vw_somarcas_sync_status','vw_xbz_products_stats')
       AND (definition ~* '\mprocessed\M\s*=' OR definition ~* '\mprocessed\M\s+IS\s+NULL')
  ) THEN
    RAISE EXCEPTION 'Cutover abortado: ainda há view referenciando a coluna processed';
  END IF;
END $vw$;

-- 2) Funções diagnósticas/de fila: troca de processed por status (swap pontual via
--    pg_get_functiondef+regex, preservando corpo, SECURITY e search_path).
DO $fns$
DECLARE v_src text;
BEGIN
  -- fn_dryrun_raw_v2: UPDATE ... SET processed=false  -> SET status='pending'
  v_src := pg_get_functiondef('public.fn_dryrun_raw_v2(uuid,integer)'::regprocedure);
  v_src := regexp_replace(v_src, '\mprocessed\M\s*=\s*false',
                          'status=''pending''::supplier_raw_status', 'gi');
  EXECUTE v_src;

  -- fn_process_all_staged_products: WHERE processed = FALSE -> status <> 'processed'
  v_src := pg_get_functiondef('public.fn_process_all_staged_products(uuid,integer)'::regprocedure);
  v_src := regexp_replace(v_src, '\mprocessed\M\s*=\s*false',
                          'status <> ''processed''::supplier_raw_status', 'gi');
  EXECUTE v_src;
END $fns$;

-- 3) Funções de ingestão: removem raw_hash e processed; detecção de mudança passa a
--    usar content_hash (hash "limpo", calculado pelo trigger ignorando campos voláteis).
CREATE OR REPLACE FUNCTION public.fn_stage_product(
  p_batch_id uuid, p_supplier_id uuid, p_supplier_reference text, p_raw_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $fn$
DECLARE
  v_staging_id UUID;
BEGIN
  SELECT id INTO v_staging_id
    FROM supplier_products_raw
   WHERE import_batch_id = p_batch_id AND supplier_reference = p_supplier_reference;

  IF v_staging_id IS NOT NULL THEN
    UPDATE supplier_products_raw
       SET raw_data = p_raw_data, updated_at = NOW()
     WHERE id = v_staging_id;
  ELSE
    INSERT INTO supplier_products_raw (
      import_batch_id, supplier_id, supplier_reference, raw_data,
      imported_at, created_at, updated_at)
    VALUES (
      p_batch_id, p_supplier_id, p_supplier_reference, p_raw_data,
      NOW(), NOW(), NOW())
    RETURNING id INTO v_staging_id;
  END IF;

  RETURN v_staging_id;
END $fn$;

CREATE OR REPLACE FUNCTION public.insert_supplier_product_raw(
  p_supplier_id uuid, p_supplier_reference text, p_raw_data jsonb,
  p_import_batch_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $fn$
DECLARE v_id UUID;
BEGIN
  INSERT INTO supplier_products_raw (
    id, supplier_id, supplier_reference, raw_data, import_batch_id,
    imported_at, created_at, updated_at)
  VALUES (
    gen_random_uuid(), p_supplier_id, p_supplier_reference, p_raw_data, p_import_batch_id,
    NOW(), NOW(), NOW())
  ON CONFLICT (supplier_id, supplier_reference) DO UPDATE SET
    raw_data        = EXCLUDED.raw_data,
    import_batch_id = EXCLUDED.import_batch_id,
    imported_at     = NOW(),
    -- content_hash é recalculado pelo trigger BEFORE; reabre p/ reprocesso só se mudou.
    status          = CASE
                        WHEN supplier_products_raw.content_hash IS DISTINCT FROM EXCLUDED.content_hash
                        THEN 'pending'::supplier_raw_status
                        ELSE supplier_products_raw.status
                      END,
    updated_at      = NOW()
  RETURNING id INTO v_id;
  RETURN v_id;
END $fn$;

-- 4) Consolida os 4 triggers BEFORE (normalize + initial_state + sync_status +
--    set_updated_at) num único. images_processed vira espelho UNIDIRECIONAL de
--    images_status (corrige o drift histórico e elimina o "reverse bridge").
CREATE OR REPLACE FUNCTION public.fn_spr_before_write()
RETURNS trigger
LANGUAGE plpgsql
AS $fn$
DECLARE v_clean jsonb;
BEGIN
  -- normalize: source_channel e imported_at a partir de metacampos do payload
  IF NEW.raw_data ? '_source' AND COALESCE(NEW.source_channel,'') IN ('','n8n','legacy') THEN
    NEW.source_channel := NEW.raw_data->>'_source';
  END IF;
  IF NEW.raw_data ? '_imported_at' AND NEW.imported_at IS NULL THEN
    BEGIN NEW.imported_at := (NEW.raw_data->>'_imported_at')::timestamptz;
    EXCEPTION WHEN others THEN NULL; END;
  END IF;

  -- remove metacampos voláteis e calcula content_hash "limpo"
  v_clean := NEW.raw_data - '_source' - '_api_fields_count' - '_imported_at';
  NEW.raw_data     := v_clean;
  NEW.content_hash := md5(v_clean::text);

  IF TG_OP = 'INSERT' THEN
    NEW.imported_at := COALESCE(NEW.imported_at, now());
    IF NEW.process_errors IS NOT NULL AND NEW.last_error IS NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;
  ELSE -- UPDATE
    NEW.updated_at := now();
    IF NEW.process_errors IS DISTINCT FROM OLD.process_errors AND NEW.process_errors IS NOT NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;
    IF NEW.status = 'processed' AND NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed_at := COALESCE(NEW.processed_at, now());
    END IF;
  END IF;

  -- espelho unidirecional (fonte da verdade = images_status)
  NEW.images_processed := (NEW.images_status = 'processed');

  RETURN NEW;
END $fn$;

DROP TRIGGER IF EXISTS trg_aa_spr_normalize   ON public.supplier_products_raw;
DROP TRIGGER IF EXISTS trg_set_initial_state  ON public.supplier_products_raw;
DROP TRIGGER IF EXISTS trg_zz_sync_raw_status ON public.supplier_products_raw;
DROP TRIGGER IF EXISTS set_updated_at_trigger ON public.supplier_products_raw;

CREATE TRIGGER trg_spr_before_write
  BEFORE INSERT OR UPDATE ON public.supplier_products_raw
  FOR EACH ROW EXECUTE FUNCTION public.fn_spr_before_write();

-- funções dos triggers antigos: exclusivas desta tabela, agora órfãs.
DROP FUNCTION IF EXISTS public.fn_spr_normalize();
DROP FUNCTION IF EXISTS public.fn_set_initial_processed_state();
DROP FUNCTION IF EXISTS public.fn_sync_raw_status();
-- set_updated_at NÃO é removida: compartilhada por 65 tabelas.

-- <<< END 20260604233005_spr_cutover_status_part1.sql <<<

-- >>> BEGIN 20260604233006_spr_cutover_status_part2.sql >>>
-- CUTOVER (parte 2/2): reescreve o restante do motor para `status`, reconcilia a
-- janela de transição, recria o índice de fila, faz o backfill de imagens e remove
-- fisicamente as colunas legadas. Tudo atômico.
-- Funções que ainda liam/escreviam `processed` (descobertas na verificação pós-parte1):
--   fn_process_raw_v2 (motor), fn_process_staged_product, fn_finish_import_batch,
--   process_supplier_products_batch.

-- 0) Duas views remanescentes que dependiam de `processed` (ambas contêm processed_at,
--    por isso escaparam do filtro inicial). vw_asia_products_errors expõe `processed`
--    como coluna de saída -> preserva contrato com (status='processed') AS processed.
CREATE OR REPLACE VIEW public.vw_asia_products_errors AS
 SELECT supplier_reference,
    raw_data ->> 'nome'::text AS nome_produto,
    process_errors,
    (status = 'processed'::supplier_raw_status) AS processed,
    processed_at,
    created_at
   FROM supplier_products_raw spr
  WHERE supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'::uuid AND process_errors IS NOT NULL
  ORDER BY updated_at DESC;
ALTER VIEW public.vw_asia_products_errors SET (security_invoker = on);

CREATE OR REPLACE VIEW public.vw_supplier_products_raw_status AS
 SELECT s.id AS supplier_id,
    s.name AS supplier_name,
    count(*) AS total_produtos,
    count(*) FILTER (WHERE spr.status = 'processed'::supplier_raw_status) AS processados,
    count(*) FILTER (WHERE spr.status <> 'processed'::supplier_raw_status) AS pendentes,
    count(*) FILTER (WHERE spr.process_errors IS NOT NULL) AS com_erro,
    round(count(*) FILTER (WHERE spr.status = 'processed'::supplier_raw_status)::numeric * 100.0 / NULLIF(count(*), 0)::numeric, 2) AS taxa_sucesso_pct,
    min(spr.imported_at) AS primeira_importacao,
    max(spr.imported_at) AS ultima_importacao,
    avg(EXTRACT(epoch FROM spr.processed_at - spr.imported_at)) AS tempo_medio_processamento_seg
   FROM supplier_products_raw spr
     JOIN suppliers s ON s.id = spr.supplier_id
  GROUP BY s.id, s.name
  ORDER BY (count(*)) DESC;
ALTER VIEW public.vw_supplier_products_raw_status SET (security_invoker = on);

-- 1) Swap por regex nas 3 funções cujos usos de `processed` são todos = TRUE/FALSE
--    sem ambiguidade SET/WHERE (no motor os '=false' são todos WHERE; o único '=true'
--    é o SET final de conclusão).
DO $f$
DECLARE r record; v_src text;
BEGIN
  FOR r IN
    SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname='public'
       AND p.proname IN ('fn_process_raw_v2','fn_process_staged_product','fn_finish_import_batch')
  LOOP
    v_src := pg_get_functiondef(r.oid);
    v_src := regexp_replace(v_src, '([a-z0-9_]+\.)?\mprocessed\M\s*=\s*true',
                            '\1status = ''processed''::supplier_raw_status', 'gi');
    v_src := regexp_replace(v_src, '([a-z0-9_]+\.)?\mprocessed\M\s*=\s*false',
                            '\1status <> ''processed''::supplier_raw_status', 'gi');
    EXECUTE v_src;
  END LOOP;
END $f$;

-- 2) process_supplier_products_batch: reescrita explícita (mistura SET/WHERE com
--    'processed = FALSE'). Sucesso -> status 'processed'; falha -> status 'failed'
--    (continua sendo re-tentado pois a fila usa status <> 'processed').
CREATE OR REPLACE FUNCTION public.process_supplier_products_batch(p_supplier_id uuid, p_limit integer DEFAULT 100)
 RETURNS TABLE(staging_id uuid, supplier_reference text, success boolean, product_id uuid, variants_created integer, error_message text, processed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_raw RECORD;
    v_result JSONB;
BEGIN
    FOR v_raw IN
        SELECT *
        FROM supplier_products_raw
        WHERE supplier_id = p_supplier_id
        AND status <> 'processed'::supplier_raw_status
        ORDER BY imported_at ASC
        LIMIT p_limit
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            v_result := process_supplier_product(
                v_raw.supplier_id,
                v_raw.raw_data,
                v_raw.supplier_reference
            );

            IF (v_result->>'success')::BOOLEAN THEN
                UPDATE supplier_products_raw
                SET
                    status = 'processed'::supplier_raw_status,
                    processed_at = NOW(),
                    product_id = (v_result->>'product_id')::UUID,
                    process_errors = NULL,
                    updated_at = NOW()
                WHERE id = v_raw.id;

                staging_id := v_raw.id;
                supplier_reference := v_raw.supplier_reference;
                success := TRUE;
                product_id := (v_result->>'product_id')::UUID;
                variants_created := (v_result->>'variants_created')::INTEGER;
                error_message := NULL;
                processed_at := NOW();
                RETURN NEXT;
            ELSE
                UPDATE supplier_products_raw
                SET
                    status = 'failed'::supplier_raw_status,
                    process_errors = v_result->'errors',
                    updated_at = NOW()
                WHERE id = v_raw.id;

                staging_id := v_raw.id;
                supplier_reference := v_raw.supplier_reference;
                success := FALSE;
                product_id := NULL;
                variants_created := 0;
                error_message := (v_result->'errors'->>0);
                processed_at := NOW();
                RETURN NEXT;
            END IF;

        EXCEPTION WHEN OTHERS THEN
            UPDATE supplier_products_raw
            SET
                status = 'failed'::supplier_raw_status,
                process_errors = jsonb_build_object(
                    'fatal_error', SQLERRM,
                    'timestamp', NOW()
                ),
                updated_at = NOW()
            WHERE id = v_raw.id;

            staging_id := v_raw.id;
            supplier_reference := v_raw.supplier_reference;
            success := FALSE;
            product_id := NULL;
            variants_created := 0;
            error_message := SQLERRM;
            processed_at := NOW();
            RETURN NEXT;
        END;
    END LOOP;

    RETURN;
END;
$function$;

-- 3) Guarda: nenhuma das funções tocadas pode mais referenciar a coluna processed.
DO $g$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
     WHERE n.nspname='public'
       AND p.proname IN ('fn_process_raw_v2','fn_process_staged_product','fn_finish_import_batch',
                         'process_supplier_products_batch','fn_dryrun_raw_v2',
                         'fn_process_all_staged_products','fn_stage_product','insert_supplier_product_raw')
       AND (p.prosrc ~* '\mprocessed\M\s*=' OR p.prosrc ~* '\mprocessed\M\s+IS\s+NULL')
  ) THEN
    RAISE EXCEPTION 'Cutover abortado: ainda ha funcao referenciando a coluna processed';
  END IF;
END $g$;

-- 4) Reconcilia a janela de transição (motor pode ter marcado processed=true sem a
--    ponte). Alinha status a partir do booleano antes de removê-lo.
UPDATE public.supplier_products_raw
   SET status = 'processed'::supplier_raw_status
 WHERE processed = true AND status <> 'processed'::supplier_raw_status;

-- 5) Backfill final de images_processed (drift histórico). O trigger BEFORE recomputa
--    images_processed a partir de images_status, sem clobber do enum.
UPDATE public.supplier_products_raw
   SET images_status = images_status
 WHERE images_processed IS DISTINCT FROM (images_status = 'processed');

-- 6) Remove colunas legadas (idx_spr_processed cai junto com a coluna).
ALTER TABLE public.supplier_products_raw DROP COLUMN processed;
ALTER TABLE public.supplier_products_raw DROP COLUMN raw_hash;

-- 7) Índice de fila equivalente ao antigo idx_spr_processed (WHERE processed=false),
--    agora sobre o enum. Como quase tudo fica 'processed', o conjunto pendente é
--    pequeno -> índice parcial enxuto e ideal para o motor.
CREATE INDEX IF NOT EXISTS idx_spr_unprocessed
  ON public.supplier_products_raw (supplier_id, imported_at)
  WHERE status <> 'processed'::supplier_raw_status;

-- <<< END 20260604233006_spr_cutover_status_part2.sql <<<

-- >>> BEGIN 20260604233007_spr_before_write_search_path.sql >>>
-- Higiene de segurança: fixa search_path da trigger-function consolidada
-- (evita o lint function_search_path_mutable).
ALTER FUNCTION public.fn_spr_before_write() SET search_path TO 'public';

-- <<< END 20260604233007_spr_before_write_search_path.sql <<<

-- >>> BEGIN 20260604234507_fix_fn_process_raw_v2_status_column.sql >>>
-- ============================================================
-- MIGRAÇÃO: 20260604234500_fix_fn_process_raw_v2_status_column.sql
-- DATA:     2026-06-04
-- MOTIVO:   🔴 REGRESSÃO CRÍTICA EM PRODUÇÃO.
--           A migration out-of-band `20260604232944_upgrade_fn_process_raw_v2_
--           fix_race_condition_and_counters` (presente no banco, AUSENTE do repo)
--           recriou `fn_process_raw_v2` a partir de uma base escrita contra o
--           schema ANTIGO (coluna booleana `processed`), porém foi aplicada DEPOIS
--           do cutover `spr_cutover_status_part2` que SUBSTITUIU `processed` pela
--           coluna `status supplier_raw_status`. Resultado: a função passou a
--           referenciar uma coluna inexistente e o cron `process-pending-products`
--           (jobid 1, */5) falha a cada execução desde 2026-06-04 23:30 com
--           «column "processed" does not exist». O pipeline SPOT ficou PARADO.
--           A mesma regressão ainda removeu o tratamento dos placeholders
--           `{size_code}`/`{capacity_ml}` do template de nome de variante.
-- SOLUÇÃO:
--   Recria `fn_process_raw_v2` mantendo as melhorias legítimas da 232944
--   (early-return anti-zumbi por contagem de pendentes, FOR UPDATE SKIP LOCKED,
--   source='raw_v2' também no UPDATE de variant_supplier_sources) e:
--     1) troca todos os usos da coluna removida `processed` por `status`
--        (`<> 'processed'` na leitura de pendentes; `= 'processed'` ao concluir);
--     2) restaura a substituição completa do template de nome de variante
--        ({product_name} | {color_name} | {size_code} | {capacity_ml}) com colapso
--        de separadores vazios — paridade com a legada process_spot_products +
--        clean_spot_name;
--     3) reintroduz pg_try_advisory_xact_lock por fornecedor (anti-race definitivo,
--        evita batch vazio sob concorrência de cron).
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(p_supplier_id uuid, p_batch_size integer DEFAULT 100, p_bulk_mode boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_org_id            uuid;
    v_parent_key_source text;
    v_name_template     text;
    v_sku_prefix        text;
    v_prep              jsonb;
    v_parent            record;
    v_row               record;
    v_map               record;
    v_product_id        uuid;
    v_variant_id        uuid;
    v_vss_id            uuid;
    v_locked            text[];
    v_val               text;
    v_tv                text;
    v_parts             text[];
    v_vfields           jsonb;
    v_ssfields          jsonb;
    v_name              text;
    v_attrs             jsonb;
    v_sku               text;
    v_sup_sku           text;
    v_k                 text;
    v_v                 text;
    v_parents           integer := 0;
    v_variants          integer := 0;
    v_errors            jsonb := '[]'::jsonb;
    v_batch_id          uuid := gen_random_uuid();
    v_started           timestamptz := now();
    v_perr              integer := 0;
    v_verr              integer := 0;
    v_batch_open        boolean := false;
    v_pending_count     integer := 0;
BEGIN
    IF auth.uid() IS NOT NULL AND NOT is_admin_or_above((SELECT auth.uid())) THEN
        RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
    END IF;

    -- GUARDA DE CONCORRÊNCIA: evita execuções simultâneas para o mesmo fornecedor.
    -- O perdedor sai sem criar batch nem trabalho.
    IF NOT pg_try_advisory_xact_lock(hashtextextended('fn_process_raw_v2:'||p_supplier_id::text, 0)) THEN
        RETURN jsonb_build_object('success', true, 'skipped', 'lock_contention',
            'supplier_id', p_supplier_id, 'parents_processed', 0, 'variants_processed', 0);
    END IF;

    PERFORM set_config('app.write_source', 'pipeline', true);
    PERFORM set_config('app.bulk_import_mode', p_bulk_mode::text, true);

    SELECT organization_id INTO v_org_id FROM suppliers WHERE id = p_supplier_id;

    SELECT parent_key_source, variant_name_template, sku_prefix
      INTO v_parent_key_source, v_name_template, v_sku_prefix
      FROM supplier_settings WHERE supplier_id = p_supplier_id;

    IF v_parent_key_source IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error', 'supplier_settings.parent_key_source ausente para o fornecedor '||p_supplier_id);
    END IF;
    v_name_template := COALESCE(v_name_template, '{product_name}');

    -- Conta pendentes ANTES de abrir batch (anti-zumbi): só abre batch se houver trabalho real.
    SELECT COUNT(DISTINCT raw_data->>v_parent_key_source)
      INTO v_pending_count
      FROM supplier_products_raw
     WHERE supplier_id = p_supplier_id AND status <> 'processed'::supplier_raw_status
       AND NULLIF(raw_data->>v_parent_key_source, '') IS NOT NULL;

    IF v_pending_count > 0 THEN
        INSERT INTO supplier_import_batches (id, supplier_id, started_at, status)
        VALUES (v_batch_id, p_supplier_id, v_started, 'processing');
        v_batch_open := true;
    ELSE
        RETURN jsonb_build_object(
            'success', true, 'supplier_id', p_supplier_id,
            'batch_id', NULL, 'parents_processed', 0, 'variants_processed', 0,
            'message', 'Nenhuma linha pendente encontrada');
    END IF;

    FOR v_parent IN
        SELECT DISTINCT raw_data->>v_parent_key_source AS pkey
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id AND status <> 'processed'::supplier_raw_status
           AND NULLIF(raw_data->>v_parent_key_source, '') IS NOT NULL
         LIMIT p_batch_size
    LOOP
      BEGIN
        -- 1) Produto: achar ou criar por (supplier_id, supplier_reference = chave do pai)
        SELECT id INTO v_product_id
          FROM products
         WHERE supplier_id = p_supplier_id AND supplier_reference = v_parent.pkey;

        IF v_product_id IS NULL THEN
            INSERT INTO products (organization_id, supplier_id, supplier_reference, sku, name,
                                  active, is_active, sync_status, created_at, updated_at)
            VALUES (v_org_id, p_supplier_id, v_parent.pkey,
                    COALESCE(v_sku_prefix, '') || v_parent.pkey,
                    'Produto ' || v_parent.pkey, true, true, 'processing', now(), now())
            RETURNING id INTO v_product_id;
        END IF;

        -- Campos travados pela curadoria humana (não sobrescrever)
        SELECT COALESCE(locked_fields, '{}'::text[]) INTO v_locked
          FROM products WHERE id = v_product_id;

        -- Usa a linha MAIS RECENTE do pai
        SELECT raw_data INTO v_prep
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id AND status <> 'processed'::supplier_raw_status
           AND raw_data->>v_parent_key_source = v_parent.pkey
         ORDER BY imported_at DESC NULLS LAST LIMIT 1;

        -- 2) Campos de produto (pulando os travados)
        v_parts := ARRAY[]::text[];
        FOR v_map IN
            SELECT * FROM supplier_field_mappings
             WHERE supplier_id = p_supplier_id AND target_table = 'products' AND is_active = true
             ORDER BY priority
        LOOP
            CONTINUE WHEN v_map.target_field = ANY(v_locked);
            v_val := CASE WHEN v_map.source_path IS NOT NULL
                          THEN v_prep #>> string_to_array(v_map.source_path, '.')
                          ELSE v_prep ->> v_map.source_field END;
            CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
            v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                       v_map.source_unit, v_map.target_unit, p_supplier_id);
            IF v_tv IS NOT NULL THEN
                v_parts := array_append(v_parts, format('%I = %L', v_map.target_field, v_tv));
            END IF;
        END LOOP;

        IF array_length(v_parts, 1) > 0 THEN
            EXECUTE format(
              'UPDATE products SET %s, updated_at=now(), sync_status=''synced'', last_sync_at=now(), last_sync_supplier_id=%L WHERE id=%L',
              array_to_string(v_parts, ', '), p_supplier_id, v_product_id);
        END IF;

        UPDATE products
           SET dimensions_display = fn_format_dimensions_display(length_cm, width_cm, height_cm)
         WHERE id = v_product_id AND length_cm IS NOT NULL
           AND NOT ('dimensions_display' = ANY(v_locked));

        -- 3) Variantes — FOR UPDATE SKIP LOCKED para evitar race condition
        FOR v_row IN
            SELECT * FROM supplier_products_raw
             WHERE supplier_id = p_supplier_id AND status <> 'processed'::supplier_raw_status
               AND raw_data->>v_parent_key_source = v_parent.pkey
             FOR UPDATE SKIP LOCKED
        LOOP
          BEGIN
            v_vfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id = p_supplier_id AND target_table = 'product_variants' AND is_active = true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path, '.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_vfields := v_vfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            -- Nome da variante por template (paridade: resolve TODOS os placeholders)
            v_name := replace(v_name_template, '{product_name}',
                              COALESCE((SELECT name FROM products WHERE id = v_product_id), ''));
            v_name := replace(v_name, '{color_name}',  COALESCE(v_vfields->>'color_name', ''));
            v_name := replace(v_name, '{size_code}',   COALESCE(v_vfields->>'size_code', ''));
            v_name := replace(v_name, '{capacity_ml}', COALESCE(v_vfields->>'capacity_ml', ''));
            v_name := regexp_replace(v_name, '\s*\|\s*\|\s*', ' | ', 'g');  -- colapsa separadores vazios
            v_name := btrim(regexp_replace(v_name, '\s*[|]\s*$', ''));       -- remove separador final
            v_attrs := jsonb_build_object(
                'codigo_cor', COALESCE(v_vfields->>'color_code', ''),
                'cor',        COALESCE(v_vfields->>'color_name', '')
            );

            v_sup_sku := NULLIF(v_row.supplier_sku, '');
            v_variant_id := NULL;
            IF v_sup_sku IS NOT NULL THEN
                SELECT id INTO v_variant_id FROM product_variants
                 WHERE product_id = v_product_id AND supplier_sku = v_sup_sku;
            END IF;

            IF v_variant_id IS NULL THEN
                v_sku := COALESCE(v_vfields->>'sku', v_sup_sku, v_row.supplier_reference);
                INSERT INTO product_variants (product_id, sku, supplier_sku, name,
                                              color_code, color_name, color_hex, attributes, is_active, created_at, updated_at)
                VALUES (v_product_id, v_sku, v_sup_sku, v_name,
                        v_vfields->>'color_code', v_vfields->>'color_name', v_vfields->>'color_hex',
                        v_attrs, true, now(), now())
                ON CONFLICT (sku) DO UPDATE SET
                    supplier_sku = EXCLUDED.supplier_sku, name = EXCLUDED.name, color_code = EXCLUDED.color_code,
                    color_name = EXCLUDED.color_name, color_hex = EXCLUDED.color_hex, attributes = EXCLUDED.attributes,
                    updated_at = now()
                RETURNING id INTO v_variant_id;
            ELSE
                UPDATE product_variants SET
                    name = v_name, color_code = v_vfields->>'color_code', color_name = v_vfields->>'color_name',
                    color_hex = v_vfields->>'color_hex', attributes = v_attrs, updated_at = now()
                WHERE id = v_variant_id;
            END IF;

            -- Campos extras de variante (que não são os hardcoded acima)
            v_parts := ARRAY[]::text[];
            FOR v_k, v_v IN
                SELECT key, value FROM jsonb_each_text(
                    v_vfields - 'sku' - 'supplier_sku' - 'color_code' - 'color_name' - 'color_hex')
            LOOP
                v_parts := array_append(v_parts, format('%I = %L', v_k, v_v));
            END LOOP;
            IF array_length(v_parts, 1) > 0 THEN
                EXECUTE format('UPDATE product_variants SET %s, updated_at=now() WHERE id=%L',
                               array_to_string(v_parts, ', '), v_variant_id);
            END IF;

            -- variant_supplier_sources
            v_ssfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id = p_supplier_id AND target_table = 'variant_supplier_sources' AND is_active = true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path, '.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_ssfields := v_ssfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            IF v_ssfields <> '{}'::jsonb THEN
                SELECT id INTO v_vss_id FROM variant_supplier_sources
                 WHERE variant_id = v_variant_id AND supplier_id = p_supplier_id;
                IF v_vss_id IS NULL THEN
                    INSERT INTO variant_supplier_sources (organization_id, variant_id, supplier_id, supplier_sku,
                                                          cost_price, quantity, source, is_preferred, is_active, updated_at)
                    VALUES (v_org_id, v_variant_id, p_supplier_id, v_sup_sku,
                            NULLIF(v_ssfields->>'cost_price', '')::numeric,
                            COALESCE(NULLIF(v_ssfields->>'quantity', '')::integer, 0),
                            'raw_v2', true, true, now());
                ELSE
                    UPDATE variant_supplier_sources SET
                        cost_price = COALESCE(NULLIF(v_ssfields->>'cost_price', '')::numeric, cost_price),
                        quantity   = COALESCE(NULLIF(v_ssfields->>'quantity', '')::integer, quantity),
                        source     = 'raw_v2',
                        updated_at = now()
                    WHERE id = v_vss_id;
                END IF;
            END IF;

            -- Carimba raw como processado (coluna `status`, não a removida `processed`)
            UPDATE supplier_products_raw
               SET status = 'processed'::supplier_raw_status, processed_at = now(),
                   product_id = v_product_id, variant_id = v_variant_id,
                   import_batch_id = CASE WHEN v_batch_open THEN v_batch_id ELSE NULL END,
                   process_errors = NULL
             WHERE id = v_row.id;
            v_variants := v_variants + 1;

          EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || jsonb_build_object('raw_id', v_row.id, 'stage', 'variant', 'error', SQLERRM);
            v_verr := v_verr + 1;
            UPDATE supplier_products_raw
               SET process_errors = jsonb_build_object('error', SQLERRM, 'stage', 'variant', 'timestamp', now())
             WHERE id = v_row.id;
          END;
        END LOOP;

        v_parents := v_parents + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_object('parent_key', v_parent.pkey, 'stage', 'parent', 'error', SQLERRM);
        v_perr := v_perr + 1;
        UPDATE supplier_products_raw
           SET process_errors = jsonb_build_object('error', SQLERRM, 'stage', 'parent', 'timestamp', now())
         WHERE supplier_id = p_supplier_id AND status <> 'processed'::supplier_raw_status
           AND raw_data->>v_parent_key_source = v_parent.pkey;
      END;
    END LOOP;

    -- Finaliza o batch com contadores reais
    IF v_batch_open THEN
        UPDATE supplier_import_batches
           SET finished_at = now(), status = 'completed',
               products_imported = v_parents, variants_imported = v_variants,
               products_errors = v_perr, variants_errors = v_verr, error_log = v_errors
         WHERE id = v_batch_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true, 'supplier_id', p_supplier_id, 'bulk_mode', p_bulk_mode,
        'batch_id', CASE WHEN v_batch_open THEN v_batch_id ELSE NULL END,
        'parents_processed', v_parents, 'variants_processed', v_variants,
        'products_errors', v_perr, 'variants_errors', v_verr, 'errors', v_errors);
END;
$function$;

COMMENT ON FUNCTION public.fn_process_raw_v2(uuid, integer, boolean) IS
    'v2.2 2026-06-04: corrige regressão da 232944 (coluna removida `processed` -> `status`); restaura template de nome completo ({size_code}/{capacity_ml} + colapso de separadores) e advisory lock anti-race. Mantém anti-zumbi (early-return) e FOR UPDATE SKIP LOCKED.';

-- <<< END 20260604234507_fix_fn_process_raw_v2_status_column.sql <<<

-- >>> BEGIN 20260604234647_restore_fn_clean_spot_name_branch_in_apply_transform.sql >>>
-- ============================================================
-- MIGRAÇÃO: 20260604234600_restore_fn_clean_spot_name_branch.sql
-- DATA:     2026-06-04
-- MOTIVO:   🟠 REGRESSÃO de paridade. A migration out-of-band
--           `20260604232837_upgrade_fn_apply_transform_add_missing_transforms`
--           (presente no banco, AUSENTE do repo) recriou `fn_apply_transform`
--           (6-arg) e, ao fazê-lo, REMOVEU do CASE 'custom' o branch
--           `fn_clean_spot_name` que havia sido adicionado em
--           `fix_spot_name_cleaning` (DB 20260604214100). Restaram apenas
--           `fn_parse_capacity_ml` e `fn_convert_box_dimension_to_cm`.
--           Consequência: o mapping products.name (transform_type='custom',
--           function='fn_clean_spot_name') deixou de limpar o nome — produtos/
--           variantes novos nasceriam com o texto CRU do fornecedor (caixa alta,
--           espaços múltiplos), divergindo do acervo (sentence-case). Isto reverte
--           a correção do GAP-1 da auditoria de paridade process_spot_products.
--           Comprovado por teste E2E: Name '  CANECA   de   PORCELANA   BRANCA  '
--           gerava produto 'CANECA   de   PORCELANA   BRANCA' (sem limpeza).
-- SOLUÇÃO:  Recria `fn_apply_transform` preservando TODAS as transforms da 232837
--           (direct, multiply, divide, convert_unit, lookup, custom, prefix, suffix,
--           uppercase, lowercase, trim, replace, regex_extract) e RE-ADICIONA o
--           branch custom `fn_clean_spot_name`.
--           Pós-fix E2E: nome -> 'Caneca de porcelana branca'.
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_apply_transform(
    p_value text,
    p_transform_type character varying,
    p_transform_config jsonb,
    p_source_unit character varying,
    p_target_unit character varying,
    p_supplier_id uuid
)
RETURNS text
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $function$
DECLARE
    v_result TEXT;
    v_numeric DECIMAL;
    v_multiplier DECIMAL;
    v_function_name VARCHAR;
    v_pattern TEXT;
    v_group INTEGER;
    v_matches TEXT[];
BEGIN
    IF p_value IS NULL OR TRIM(p_value) = '' THEN
        RETURN NULL;
    END IF;

    CASE p_transform_type

        WHEN 'direct' THEN
            v_result := p_value;

        WHEN 'multiply' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_multiplier := COALESCE(
                    (p_transform_config->>'multiplier')::DECIMAL,
                    (p_transform_config->>'factor')::DECIMAL
                );
                v_result := TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM ROUND(v_numeric * v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'divide' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_multiplier := COALESCE(
                    (p_transform_config->>'divisor')::DECIMAL,
                    (p_transform_config->>'factor')::DECIMAL
                );
                IF v_multiplier != 0 THEN
                    v_result := TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM ROUND(v_numeric / v_multiplier, 4)::TEXT));
                ELSE
                    v_result := p_value;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'convert_unit' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_result := fn_convert_unit(v_numeric, p_source_unit, p_target_unit, p_supplier_id)::TEXT;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'lookup' THEN
            v_result := fn_map_value(
                p_supplier_id,
                p_transform_config->>'lookup_type',
                p_value
            );

        WHEN 'custom' THEN
            BEGIN
                v_function_name := p_transform_config->>'function';
                CASE v_function_name
                    WHEN 'fn_parse_capacity_ml' THEN
                        v_result := fn_parse_capacity_ml(p_value)::TEXT;
                    WHEN 'fn_convert_box_dimension_to_cm' THEN
                        v_result := fn_convert_box_dimension_to_cm(p_value)::TEXT;
                    WHEN 'fn_clean_spot_name' THEN
                        v_result := fn_clean_spot_name(p_value);
                    ELSE
                        v_result := p_value;
                END CASE;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'prefix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'prefix' IS NOT NULL THEN
                v_result := (p_transform_config->>'prefix') || p_value;
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'suffix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'suffix' IS NOT NULL THEN
                v_result := p_value || (p_transform_config->>'suffix');
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'uppercase' THEN
            v_result := UPPER(p_value);

        WHEN 'lowercase' THEN
            v_result := LOWER(p_value);

        WHEN 'trim' THEN
            v_result := BTRIM(p_value);

        WHEN 'replace' THEN
            IF p_transform_config IS NOT NULL THEN
                v_result := REPLACE(
                    p_value,
                    COALESCE(p_transform_config->>'find', ''),
                    COALESCE(p_transform_config->>'replace', '')
                );
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group THEN
                    v_result := v_matches[v_group];
                ELSE
                    v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        ELSE
            v_result := p_value;

    END CASE;

    RETURN v_result;
END;
$function$;

