-- >>> BEGIN 20260604235853_spr_drop_unused_partial_indexes.sql >>>
-- Limpeza final de índices de supplier_products_raw (pós-cutover status).
-- Remove índices sem consumidor de leitura: a fila quente do motor usa
-- idx_spr_unprocessed (WHERE status <> 'processed'); estes tinham 0 scans e
-- nenhuma query que os use como caminho de leitura (os matches de
-- status='pending'/'failed' em funções/views são writes SET ou agregações
-- full-scan de dashboard, que não usam índice parcial).
--   - idx_spr_content_hash (4 MB): nada faz WHERE content_hash = ...; a detecção
--     de mudança em insert_supplier_product_raw usa o índice único de
--     (supplier_id, supplier_reference) no ON CONFLICT, não lookup por hash.
--   - idx_spr_queue (status='pending'): redundante com idx_spr_unprocessed.
--   - idx_spr_images_queue / idx_spr_failed: sem consumidor de leitura.
-- Resultado: 13 -> 8 índices; ~12 MB -> ~6,7 MB de índices.
DROP INDEX IF EXISTS public.idx_spr_content_hash;
DROP INDEX IF EXISTS public.idx_spr_queue;
DROP INDEX IF EXISTS public.idx_spr_images_queue;
DROP INDEX IF EXISTS public.idx_spr_failed;

-- <<< END 20260604235853_spr_drop_unused_partial_indexes.sql <<<

-- >>> BEGIN 20260605000239_fix_raw_v2_product_type_mapping_parity.sql >>>
-- CRÍTICO: restaura paridade com process_spot_products (legada gravava product_type='product').
-- O mapping Type->products.product_type (transform 'direct', ativo) injeta as CATEGORIAS da
-- SPOT (SUCO, Escrita, Tecnologia, ...) na coluna product_type, que tem
-- CHECK (product_type IN (product|packaging|accessory|kit|component)). Isso aborta o UPDATE
-- do produto; como INSERT e UPDATE correm no mesmo bloco BEGIN/EXCEPTION por parent, o rollback
-- ao savepoint desfaz o INSERT -> o produto nunca é criado e a raw fica 'pending' (retry
-- infinito), enquanto fn_process_raw_v2 retorna success:true. Blast radius medido: 1200/1200
-- ProdReferences (100%). Ref.: docs/AUDITORIA_GAPS_CRITICOS_fn_process_raw_v2_2026-06-04.md
--
-- Desativando o mapping, product_type cai no default da coluna ('product') = comportamento legado.
UPDATE public.supplier_field_mappings
   SET is_active = false, updated_at = now()
 WHERE supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'::uuid
   AND target_table = 'products' AND target_field = 'product_type' AND is_active = true;

-- <<< END 20260605000239_fix_raw_v2_product_type_mapping_parity.sql <<<

-- >>> BEGIN 20260605000347_raw_v2_transform_maxlength_and_spot_overflow_caps.sql >>>
-- Overflow de campos texto da SPOT SEM alterar colunas (short_description e ncm_code são
-- referenciados por public.v_products_public e analytics.mv_product_cards; um ALTER TYPE exigiria
-- recriar esses objetos). Em vez disso, fn_apply_transform passa a truncar o resultado quando
-- transform_config.max_length está presente. Aditivo e opt-in: nenhum mapping existente usa
-- max_length, logo é backward-compatible para todos os fornecedores.
-- Dados reais: ShortDescription chega a 969 (col varchar(500)); Taric chega a 11 (col varchar(10)).
-- Ref.: docs/AUDITORIA_GAPS_CRITICOS_fn_process_raw_v2_2026-06-04.md

CREATE OR REPLACE FUNCTION public.fn_apply_transform(p_value text, p_transform_type character varying, p_transform_config jsonb, p_source_unit character varying, p_target_unit character varying, p_supplier_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    v_result TEXT;
    v_numeric DECIMAL;
    v_multiplier DECIMAL;
    v_function_name VARCHAR;
    v_pattern TEXT;
    v_group INTEGER;
    v_matches TEXT[];
    v_max_length INTEGER;
BEGIN
    IF p_value IS NULL OR TRIM(p_value) = '' THEN
        RETURN NULL;
    END IF;

    CASE p_transform_type

        WHEN 'direct' THEN
            v_result := p_value;

        WHEN 'multiply' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_multiplier := COALESCE(
                    (p_transform_config->>'multiplier')::DECIMAL,
                    (p_transform_config->>'factor')::DECIMAL
                );
                v_result := TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM ROUND(v_numeric * v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'divide' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_multiplier := COALESCE(
                    (p_transform_config->>'divisor')::DECIMAL,
                    (p_transform_config->>'factor')::DECIMAL
                );
                IF v_multiplier != 0 THEN
                    v_result := TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM ROUND(v_numeric / v_multiplier, 4)::TEXT));
                ELSE
                    v_result := p_value;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'convert_unit' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_result := fn_convert_unit(v_numeric, p_source_unit, p_target_unit, p_supplier_id)::TEXT;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'lookup' THEN
            v_result := fn_map_value(
                p_supplier_id,
                p_transform_config->>'lookup_type',
                p_value
            );

        WHEN 'custom' THEN
            BEGIN
                v_function_name := p_transform_config->>'function';
                CASE v_function_name
                    WHEN 'fn_parse_capacity_ml' THEN
                        v_result := fn_parse_capacity_ml(p_value)::TEXT;
                    WHEN 'fn_convert_box_dimension_to_cm' THEN
                        v_result := fn_convert_box_dimension_to_cm(p_value)::TEXT;
                    WHEN 'fn_clean_spot_name' THEN
                        v_result := fn_clean_spot_name(p_value);
                    ELSE
                        v_result := p_value;
                END CASE;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'prefix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'prefix' IS NOT NULL THEN
                v_result := (p_transform_config->>'prefix') || p_value;
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'suffix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'suffix' IS NOT NULL THEN
                v_result := p_value || (p_transform_config->>'suffix');
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'uppercase' THEN
            v_result := UPPER(p_value);

        WHEN 'lowercase' THEN
            v_result := LOWER(p_value);

        WHEN 'trim' THEN
            v_result := BTRIM(p_value);

        WHEN 'replace' THEN
            IF p_transform_config IS NOT NULL THEN
                v_result := REPLACE(
                    p_value,
                    COALESCE(p_transform_config->>'find', ''),
                    COALESCE(p_transform_config->>'replace', '')
                );
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group THEN
                    v_result := v_matches[v_group];
                ELSE
                    v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        ELSE
            v_result := p_value;

    END CASE;

    -- Aditivo: trunca para caber na coluna de destino quando configurado.
    IF v_result IS NOT NULL AND p_transform_config IS NOT NULL
       AND (p_transform_config->>'max_length') IS NOT NULL THEN
        v_max_length := (p_transform_config->>'max_length')::INTEGER;
        IF v_max_length > 0 AND length(v_result) > v_max_length THEN
            v_result := left(v_result, v_max_length);
        END IF;
    END IF;

    RETURN v_result;
END;
$function$;

-- Caps para os dois campos que estouram com dados reais da SPOT.
