-- CRITICAL FIX: fn_process_raw_v2 v2.2 — migra de processed (bool) para status (enum)
-- Status enum: pending, processing, processed, failed, skipped, quarantined
CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(
    p_supplier_id uuid,
    p_batch_size integer DEFAULT 100,
    p_bulk_mode boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_org_id            uuid;
    v_parent_key_source text;
    v_name_template     text;
    v_sku_prefix        text;
    v_prep              jsonb;
    v_parent            record;
    v_row               record;
    v_map               record;
    v_product_id        uuid;
    v_variant_id        uuid;
    v_vss_id            uuid;
    v_locked            text[];
    v_val               text;
    v_tv                text;
    v_parts             text[];
    v_vfields           jsonb;
    v_ssfields          jsonb;
    v_name              text;
    v_attrs             jsonb;
    v_sku               text;
    v_sup_sku           text;
    v_k                 text;
    v_v                 text;
    v_parents           integer := 0;
    v_variants          integer := 0;
    v_errors            jsonb := '[]'::jsonb;
    v_batch_id          uuid := gen_random_uuid();
    v_started           timestamptz := now();
    v_perr              integer := 0;
    v_verr              integer := 0;
    v_batch_open        boolean := false;
    v_pending_count     integer := 0;
BEGIN
    IF auth.uid() IS NOT NULL AND NOT is_admin_or_above((SELECT auth.uid())) THEN
        RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
    END IF;

    PERFORM set_config('app.write_source', 'pipeline', true);
    PERFORM set_config('app.bulk_import_mode', p_bulk_mode::text, true);

    SELECT organization_id INTO v_org_id FROM suppliers WHERE id = p_supplier_id;

    SELECT parent_key_source, variant_name_template, sku_prefix
      INTO v_parent_key_source, v_name_template, v_sku_prefix
      FROM supplier_settings WHERE supplier_id = p_supplier_id;

    IF v_parent_key_source IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error', 'supplier_settings.parent_key_source ausente para o fornecedor '||p_supplier_id);
    END IF;
    v_name_template := COALESCE(v_name_template, '{product_name}');

    -- Contar pendentes (status = 'pending') — anti-zumbi
    SELECT COUNT(DISTINCT raw_data->>v_parent_key_source)
      INTO v_pending_count
      FROM supplier_products_raw
     WHERE supplier_id = p_supplier_id
       AND status = 'pending'
       AND NULLIF(raw_data->>v_parent_key_source, '') IS NOT NULL;

    IF v_pending_count = 0 THEN
        RETURN jsonb_build_object(
            'success', true, 'supplier_id', p_supplier_id,
            'batch_id', NULL, 'parents_processed', 0, 'variants_processed', 0,
            'message', 'Nenhuma linha pendente encontrada');
    END IF;

    INSERT INTO supplier_import_batches (id, supplier_id, started_at, status)
    VALUES (v_batch_id, p_supplier_id, v_started, 'processing');
    v_batch_open := true;

    FOR v_parent IN
        SELECT DISTINCT raw_data->>v_parent_key_source AS pkey
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id
           AND status = 'pending'
           AND NULLIF(raw_data->>v_parent_key_source, '') IS NOT NULL
         LIMIT p_batch_size
    LOOP
      BEGIN
        -- 1) Produto: achar ou criar
        SELECT id INTO v_product_id
          FROM products
         WHERE supplier_id = p_supplier_id AND supplier_reference = v_parent.pkey;

        IF v_product_id IS NULL THEN
            INSERT INTO products (organization_id, supplier_id, supplier_reference, sku, name,
                                  active, is_active, sync_status, created_at, updated_at)
            VALUES (v_org_id, p_supplier_id, v_parent.pkey,
                    COALESCE(v_sku_prefix, '') || v_parent.pkey,
                    'Produto ' || v_parent.pkey, true, true, 'processing', now(), now())
            RETURNING id INTO v_product_id;
        END IF;

        SELECT COALESCE(locked_fields, '{}'::text[]) INTO v_locked
          FROM products WHERE id = v_product_id;

        -- Linha mais recente do pai para campos de produto
        SELECT raw_data INTO v_prep
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id
           AND status = 'pending'
           AND raw_data->>v_parent_key_source = v_parent.pkey
         ORDER BY imported_at DESC NULLS LAST LIMIT 1;

        -- 2) Atualizar campos de produto (respeitando locked_fields)
        v_parts := ARRAY[]::text[];
        FOR v_map IN
            SELECT * FROM supplier_field_mappings
             WHERE supplier_id = p_supplier_id AND target_table = 'products' AND is_active = true
             ORDER BY priority
        LOOP
            CONTINUE WHEN v_map.target_field = ANY(v_locked);
            v_val := CASE WHEN v_map.source_path IS NOT NULL
                          THEN v_prep #>> string_to_array(v_map.source_path, '.')
                          ELSE v_prep ->> v_map.source_field END;
            CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
            v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                       v_map.source_unit, v_map.target_unit, p_supplier_id);
            IF v_tv IS NOT NULL THEN
                v_parts := array_append(v_parts, format('%I = %L', v_map.target_field, v_tv));
            END IF;
        END LOOP;

        IF array_length(v_parts, 1) > 0 THEN
            EXECUTE format(
              'UPDATE products SET %s, updated_at=now(), sync_status=''synced'', last_sync_at=now(), last_sync_supplier_id=%L WHERE id=%L',
              array_to_string(v_parts, ', '), p_supplier_id, v_product_id);
        END IF;

        UPDATE products
           SET dimensions_display = fn_format_dimensions_display(length_cm, width_cm, height_cm)
         WHERE id = v_product_id AND length_cm IS NOT NULL
           AND NOT ('dimensions_display' = ANY(v_locked));

        -- 3) Variantes — FOR UPDATE SKIP LOCKED
        FOR v_row IN
            SELECT * FROM supplier_products_raw
             WHERE supplier_id = p_supplier_id
               AND status = 'pending'
               AND raw_data->>v_parent_key_source = v_parent.pkey
             FOR UPDATE SKIP LOCKED
        LOOP
          BEGIN
            -- Marcar como processing
            UPDATE supplier_products_raw SET status = 'processing' WHERE id = v_row.id;

            v_vfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id = p_supplier_id AND target_table = 'product_variants' AND is_active = true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path, '.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_vfields := v_vfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            v_name := replace(v_name_template, '{product_name}',
                              COALESCE((SELECT name FROM products WHERE id = v_product_id), ''));
            v_name := replace(v_name, '{color_name}', COALESCE(v_vfields->>'color_name', ''));
            v_name := btrim(regexp_replace(v_name, '\s*[|-]\s*$', ''));
            v_attrs := jsonb_build_object(
                'codigo_cor', COALESCE(v_vfields->>'color_code', ''),
                'cor',        COALESCE(v_vfields->>'color_name', '')
            );

            v_sup_sku := NULLIF(v_row.supplier_sku, '');
            v_variant_id := NULL;
            IF v_sup_sku IS NOT NULL THEN
                SELECT id INTO v_variant_id FROM product_variants
                 WHERE product_id = v_product_id AND supplier_sku = v_sup_sku;
            END IF;

            IF v_variant_id IS NULL THEN
                v_sku := COALESCE(v_vfields->>'sku', v_sup_sku, v_row.supplier_reference);
                INSERT INTO product_variants (product_id, sku, supplier_sku, name,
                                              color_code, color_name, color_hex, attributes, is_active, created_at, updated_at)
                VALUES (v_product_id, v_sku, v_sup_sku, v_name,
                        v_vfields->>'color_code', v_vfields->>'color_name', v_vfields->>'color_hex',
                        v_attrs, true, now(), now())
                ON CONFLICT (sku) DO UPDATE SET
                    supplier_sku = EXCLUDED.supplier_sku, name = EXCLUDED.name, color_code = EXCLUDED.color_code,
                    color_name = EXCLUDED.color_name, color_hex = EXCLUDED.color_hex, attributes = EXCLUDED.attributes,
                    updated_at = now()
                RETURNING id INTO v_variant_id;
            ELSE
                UPDATE product_variants SET
                    name = v_name, color_code = v_vfields->>'color_code', color_name = v_vfields->>'color_name',
                    color_hex = v_vfields->>'color_hex', attributes = v_attrs, updated_at = now()
                WHERE id = v_variant_id;
            END IF;

            -- Campos extras de variante
            v_parts := ARRAY[]::text[];
            FOR v_k, v_v IN
                SELECT key, value FROM jsonb_each_text(
                    v_vfields - 'sku' - 'supplier_sku' - 'color_code' - 'color_name' - 'color_hex')
            LOOP
                v_parts := array_append(v_parts, format('%I = %L', v_k, v_v));
            END LOOP;
            IF array_length(v_parts, 1) > 0 THEN
                EXECUTE format('UPDATE product_variants SET %s, updated_at=now() WHERE id=%L',
                               array_to_string(v_parts, ', '), v_variant_id);
            END IF;

            -- variant_supplier_sources
            v_ssfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id = p_supplier_id AND target_table = 'variant_supplier_sources' AND is_active = true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path, '.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_ssfields := v_ssfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            IF v_ssfields <> '{}'::jsonb THEN
                SELECT id INTO v_vss_id FROM variant_supplier_sources
                 WHERE variant_id = v_variant_id AND supplier_id = p_supplier_id;
                IF v_vss_id IS NULL THEN
                    INSERT INTO variant_supplier_sources (organization_id, variant_id, supplier_id, supplier_sku,
                                                          cost_price, quantity, source, is_preferred, is_active, updated_at)
                    VALUES (v_org_id, v_variant_id, p_supplier_id, v_sup_sku,
                            NULLIF(v_ssfields->>'cost_price', '')::numeric,
                            COALESCE(NULLIF(v_ssfields->>'quantity', '')::integer, 0),
                            'raw_v2', true, true, now());
                ELSE
                    UPDATE variant_supplier_sources SET
                        cost_price = COALESCE(NULLIF(v_ssfields->>'cost_price', '')::numeric, cost_price),
                        quantity   = COALESCE(NULLIF(v_ssfields->>'quantity', '')::integer, quantity),
                        source     = 'raw_v2',
                        updated_at = now()
                    WHERE id = v_vss_id;
                END IF;
            END IF;

            -- Sucesso: marcar como processed
            UPDATE supplier_products_raw
               SET status = 'processed', processed_at = now(),
                   product_id = v_product_id, variant_id = v_variant_id,
                   import_batch_id = v_batch_id,
                   process_errors = NULL, last_error = NULL, attempts = COALESCE(attempts, 0) + 1
             WHERE id = v_row.id;
            v_variants := v_variants + 1;

          EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || jsonb_build_object('raw_id', v_row.id, 'stage', 'variant', 'error', SQLERRM);
            v_verr := v_verr + 1;
            UPDATE supplier_products_raw
               SET status = 'failed',
                   process_errors = jsonb_build_object('error', SQLERRM, 'stage', 'variant', 'timestamp', now()),
                   last_error = jsonb_build_object('error', SQLERRM, 'at', now()),
                   attempts = COALESCE(attempts, 0) + 1
             WHERE id = v_row.id;
          END;
        END LOOP;

        v_parents := v_parents + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_object('parent_key', v_parent.pkey, 'stage', 'parent', 'error', SQLERRM);
        v_perr := v_perr + 1;
        UPDATE supplier_products_raw
           SET status = 'failed',
               process_errors = jsonb_build_object('error', SQLERRM, 'stage', 'parent', 'timestamp', now()),
               last_error = jsonb_build_object('error', SQLERRM, 'at', now()),
               attempts = COALESCE(attempts, 0) + 1
         WHERE supplier_id = p_supplier_id
           AND status IN ('pending', 'processing')
           AND raw_data->>v_parent_key_source = v_parent.pkey;
      END;
    END LOOP;

    -- Finaliza batch
    IF v_batch_open THEN
        UPDATE supplier_import_batches
           SET finished_at = now(), status = 'completed',
               products_imported = v_parents, variants_imported = v_variants,
               products_errors = v_perr, variants_errors = v_verr, error_log = v_errors
         WHERE id = v_batch_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true, 'supplier_id', p_supplier_id, 'bulk_mode', p_bulk_mode,
        'batch_id', v_batch_id,
        'parents_processed', v_parents, 'variants_processed', v_variants,
        'products_errors', v_perr, 'variants_errors', v_verr, 'errors', v_errors);
END;
$function$;

COMMENT ON FUNCTION public.fn_process_raw_v2(uuid, integer, boolean) IS
'Pipeline raw→products v2.2 — usa status enum (pending/processing/processed/failed) em vez de bool processed. FOR UPDATE SKIP LOCKED. Anti-zumbi. Popula attempts/last_error.';

-- <<< END 20260605002243_fix_fn_process_raw_v2_use_status_enum.sql <<<

-- >>> BEGIN 20260605002302_fix_process_supplier_products_batch_use_status_enum.sql >>>

-- Fix process_supplier_products_batch para usar status enum
CREATE OR REPLACE FUNCTION public.process_supplier_products_batch(
    p_supplier_id uuid,
    p_limit integer DEFAULT 100
)
RETURNS TABLE(
    staging_id uuid,
    supplier_reference text,
    success boolean,
    product_id uuid,
    variants_created integer,
    error_message text,
    processed_at timestamp with time zone
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_raw RECORD;
    v_result JSONB;
BEGIN
    FOR v_raw IN 
        SELECT *
        FROM supplier_products_raw 
        WHERE supplier_id = p_supplier_id 
        AND status = 'pending'
        ORDER BY imported_at ASC
        LIMIT p_limit
        FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            -- Marcar como processing
            UPDATE supplier_products_raw SET status = 'processing' WHERE id = v_raw.id;

            v_result := process_supplier_product(
                v_raw.supplier_id,
                v_raw.raw_data,
                v_raw.supplier_reference
            );
            
            IF (v_result->>'success')::BOOLEAN THEN
                UPDATE supplier_products_raw 
                SET 
                    status = 'processed',
                    processed_at = NOW(),
                    product_id = (v_result->>'product_id')::UUID,
                    process_errors = NULL,
                    updated_at = NOW()
                WHERE id = v_raw.id;
                
                staging_id := v_raw.id;
                supplier_reference := v_raw.supplier_reference;
                success := TRUE;
                product_id := (v_result->>'product_id')::UUID;
                variants_created := (v_result->>'variants_created')::INTEGER;
                error_message := NULL;
                processed_at := NOW();
                RETURN NEXT;
            ELSE
                UPDATE supplier_products_raw 
                SET 
                    status = 'failed',
                    process_errors = v_result->'errors',
                    updated_at = NOW()
                WHERE id = v_raw.id;
                
                staging_id := v_raw.id;
                supplier_reference := v_raw.supplier_reference;
                success := FALSE;
                product_id := NULL;
                variants_created := 0;
                error_message := (v_result->'errors'->>0);
                processed_at := NOW();
                RETURN NEXT;
            END IF;
            
        EXCEPTION WHEN OTHERS THEN
            UPDATE supplier_products_raw 
            SET 
                status = 'failed',
                process_errors = jsonb_build_object(
                    'fatal_error', SQLERRM,
                    'timestamp', NOW()
                ),
                updated_at = NOW()
            WHERE id = v_raw.id;
            
            staging_id := v_raw.id;
            supplier_reference := v_raw.supplier_reference;
            success := FALSE;
            product_id := NULL;
            variants_created := 0;
            error_message := SQLERRM;
            processed_at := NOW();
            RETURN NEXT;
        END;
    END LOOP;
    
    RETURN;
END;
$function$;

COMMENT ON FUNCTION public.process_supplier_products_batch(uuid, integer) IS
'Wrapper batch legado — atualizado para usar status enum (pending/processed/failed) em vez de bool processed.';

-- <<< END 20260605002302_fix_process_supplier_products_batch_use_status_enum.sql <<<

-- >>> BEGIN 20260605002334_fix_fn_process_raw_v2_integer_cast_and_failed_status.sql >>>

CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(p_supplier_id uuid, p_batch_size integer DEFAULT 100, p_bulk_mode boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_org_id            uuid;
    v_parent_key_source text;
    v_name_template     text;
    v_sku_prefix        text;
    v_prep              jsonb;
    v_parent            record;
    v_row               record;
    v_map               record;
    v_product_id        uuid;
    v_variant_id        uuid;
    v_vss_id            uuid;
    v_locked            text[];
    v_val               text;
    v_tv                text;
    v_parts             text[];
    v_vfields           jsonb;
    v_ssfields          jsonb;
    v_name              text;
    v_attrs             jsonb;
    v_sku               text;
    v_sup_sku           text;
    v_k                 text;
    v_v                 text;
    v_parents           integer := 0;
    v_variants          integer := 0;
    v_errors            jsonb := '[]'::jsonb;
    v_batch_id          uuid := gen_random_uuid();
    v_started           timestamptz := now();
    v_perr              integer := 0;
    v_verr              integer := 0;
    v_batch_open        boolean := false;
    v_pending_count     integer := 0;
    -- ═══ BUG-1 FIX: integer column lookup ═══
    v_int_cols_products  text[];
    v_int_cols_variants  text[];
BEGIN
    IF auth.uid() IS NOT NULL AND NOT is_admin_or_above((SELECT auth.uid())) THEN
        RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
    END IF;

    IF NOT pg_try_advisory_xact_lock(hashtextextended('fn_process_raw_v2:'||p_supplier_id::text, 0)) THEN
        RETURN jsonb_build_object('success', true, 'skipped', 'lock_contention',
            'supplier_id', p_supplier_id, 'parents_processed', 0, 'variants_processed', 0);
    END IF;

    PERFORM set_config('app.write_source', 'pipeline', true);
    PERFORM set_config('app.bulk_import_mode', p_bulk_mode::text, true);

    SELECT organization_id INTO v_org_id FROM suppliers WHERE id = p_supplier_id;

    SELECT parent_key_source, variant_name_template, sku_prefix
      INTO v_parent_key_source, v_name_template, v_sku_prefix
      FROM supplier_settings WHERE supplier_id = p_supplier_id;

    IF v_parent_key_source IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error', 'supplier_settings.parent_key_source ausente para o fornecedor '||p_supplier_id);
    END IF;
    v_name_template := COALESCE(v_name_template, '{product_name}');

    -- ═══ BUG-1 FIX: Pre-build integer column lists for safe casting ═══
    SELECT COALESCE(array_agg(column_name), '{}') INTO v_int_cols_products
      FROM information_schema.columns
     WHERE table_schema = 'public' AND table_name = 'products'
       AND data_type IN ('integer', 'smallint', 'bigint');

    SELECT COALESCE(array_agg(column_name), '{}') INTO v_int_cols_variants
      FROM information_schema.columns
     WHERE table_schema = 'public' AND table_name = 'product_variants'
       AND data_type IN ('integer', 'smallint', 'bigint');

    SELECT COUNT(DISTINCT raw_data->>v_parent_key_source)
      INTO v_pending_count
      FROM supplier_products_raw
     WHERE supplier_id = p_supplier_id AND status <> 'processed'::supplier_raw_status
       AND NULLIF(raw_data->>v_parent_key_source, '') IS NOT NULL;

    IF v_pending_count > 0 THEN
        INSERT INTO supplier_import_batches (id, supplier_id, started_at, status)
        VALUES (v_batch_id, p_supplier_id, v_started, 'processing');
        v_batch_open := true;
    ELSE
        RETURN jsonb_build_object(
            'success', true, 'supplier_id', p_supplier_id,
            'batch_id', NULL, 'parents_processed', 0, 'variants_processed', 0,
            'message', 'Nenhuma linha pendente encontrada');
    END IF;

    FOR v_parent IN
        SELECT DISTINCT raw_data->>v_parent_key_source AS pkey
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id AND status <> 'processed'::supplier_raw_status
           AND NULLIF(raw_data->>v_parent_key_source, '') IS NOT NULL
         LIMIT p_batch_size
    LOOP
      BEGIN
        SELECT id INTO v_product_id
          FROM products
         WHERE supplier_id = p_supplier_id AND supplier_reference = v_parent.pkey;

        IF v_product_id IS NULL THEN
            INSERT INTO products (organization_id, supplier_id, supplier_reference, sku, name,
                                  active, is_active, sync_status, created_at, updated_at)
            VALUES (v_org_id, p_supplier_id, v_parent.pkey,
                    COALESCE(v_sku_prefix, '') || v_parent.pkey,
                    'Produto ' || v_parent.pkey, true, true, 'processing', now(), now())
            RETURNING id INTO v_product_id;
        END IF;

        SELECT COALESCE(locked_fields, '{}'::text[]) INTO v_locked
          FROM products WHERE id = v_product_id;

        SELECT raw_data INTO v_prep
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id AND status <> 'processed'::supplier_raw_status
           AND raw_data->>v_parent_key_source = v_parent.pkey
         ORDER BY imported_at DESC NULLS LAST LIMIT 1;

        v_parts := ARRAY[]::text[];
        FOR v_map IN
            SELECT * FROM supplier_field_mappings
             WHERE supplier_id = p_supplier_id AND target_table = 'products' AND is_active = true
             ORDER BY priority
        LOOP
            CONTINUE WHEN v_map.target_field = ANY(v_locked);
            v_val := CASE WHEN v_map.source_path IS NOT NULL
                          THEN v_prep #>> string_to_array(v_map.source_path, '.')
                          ELSE v_prep ->> v_map.source_field END;
            CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
            v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                       v_map.source_unit, v_map.target_unit, p_supplier_id);
            IF v_tv IS NOT NULL THEN
                -- ═══ BUG-1 FIX: safe cast for integer columns ═══
                IF v_map.target_field = ANY(v_int_cols_products) THEN
                    v_parts := array_append(v_parts, format('%I = ROUND(%L::numeric)', v_map.target_field, v_tv));
                ELSE
                    v_parts := array_append(v_parts, format('%I = %L', v_map.target_field, v_tv));
                END IF;
            END IF;
        END LOOP;

        IF array_length(v_parts, 1) > 0 THEN
            EXECUTE format(
              'UPDATE products SET %s, updated_at=now(), sync_status=''synced'', last_sync_at=now(), last_sync_supplier_id=%L WHERE id=%L',
              array_to_string(v_parts, ', '), p_supplier_id, v_product_id);
        END IF;

        UPDATE products
           SET dimensions_display = fn_format_dimensions_display(length_cm, width_cm, height_cm)
         WHERE id = v_product_id AND length_cm IS NOT NULL
           AND NOT ('dimensions_display' = ANY(v_locked));

        FOR v_row IN
            SELECT * FROM supplier_products_raw
             WHERE supplier_id = p_supplier_id AND status <> 'processed'::supplier_raw_status
               AND raw_data->>v_parent_key_source = v_parent.pkey
             FOR UPDATE SKIP LOCKED
        LOOP
          BEGIN
            v_vfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id = p_supplier_id AND target_table = 'product_variants' AND is_active = true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path, '.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_vfields := v_vfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            v_name := replace(v_name_template, '{product_name}',
                              COALESCE((SELECT name FROM products WHERE id = v_product_id), ''));
            v_name := replace(v_name, '{color_name}',  COALESCE(v_vfields->>'color_name', ''));
            v_name := replace(v_name, '{size_code}',   COALESCE(v_vfields->>'size_code', ''));
            v_name := replace(v_name, '{capacity_ml}', COALESCE(v_vfields->>'capacity_ml', ''));
            v_name := regexp_replace(v_name, '\s*\|\s*\|\s*', ' | ', 'g');
            v_name := btrim(regexp_replace(v_name, '\s*[|]\s*$', ''));
            v_attrs := jsonb_build_object(
                'codigo_cor', COALESCE(v_vfields->>'color_code', ''),
                'cor',        COALESCE(v_vfields->>'color_name', '')
            );

            v_sup_sku := NULLIF(v_row.supplier_sku, '');
            v_variant_id := NULL;
            IF v_sup_sku IS NOT NULL THEN
                SELECT id INTO v_variant_id FROM product_variants
                 WHERE product_id = v_product_id AND supplier_sku = v_sup_sku;
            END IF;

            IF v_variant_id IS NULL THEN
                v_sku := COALESCE(v_vfields->>'sku', v_sup_sku, v_row.supplier_reference);
                INSERT INTO product_variants (product_id, sku, supplier_sku, name,
                                              color_code, color_name, color_hex, attributes, is_active, created_at, updated_at)
                VALUES (v_product_id, v_sku, v_sup_sku, v_name,
                        v_vfields->>'color_code', v_vfields->>'color_name', v_vfields->>'color_hex',
                        v_attrs, true, now(), now())
                ON CONFLICT (sku) DO UPDATE SET
                    supplier_sku = EXCLUDED.supplier_sku, name = EXCLUDED.name, color_code = EXCLUDED.color_code,
                    color_name = EXCLUDED.color_name, color_hex = EXCLUDED.color_hex, attributes = EXCLUDED.attributes,
                    updated_at = now()
                RETURNING id INTO v_variant_id;
            ELSE
                UPDATE product_variants SET
                    name = v_name, color_code = v_vfields->>'color_code', color_name = v_vfields->>'color_name',
                    color_hex = v_vfields->>'color_hex', attributes = v_attrs, updated_at = now()
                WHERE id = v_variant_id;
            END IF;

            -- ═══ BUG-1 FIX: safe cast for integer variant columns ═══
            v_parts := ARRAY[]::text[];
            FOR v_k, v_v IN
                SELECT key, value FROM jsonb_each_text(
                    v_vfields - 'sku' - 'supplier_sku' - 'color_code' - 'color_name' - 'color_hex')
            LOOP
                IF v_k = ANY(v_int_cols_variants) THEN
                    v_parts := array_append(v_parts, format('%I = ROUND(%L::numeric)', v_k, v_v));
                ELSE
                    v_parts := array_append(v_parts, format('%I = %L', v_k, v_v));
                END IF;
            END LOOP;
            IF array_length(v_parts, 1) > 0 THEN
                EXECUTE format('UPDATE product_variants SET %s, updated_at=now() WHERE id=%L',
                               array_to_string(v_parts, ', '), v_variant_id);
            END IF;

            v_ssfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id = p_supplier_id AND target_table = 'variant_supplier_sources' AND is_active = true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path, '.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_ssfields := v_ssfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            IF v_ssfields <> '{}'::jsonb THEN
                SELECT id INTO v_vss_id FROM variant_supplier_sources
                 WHERE variant_id = v_variant_id AND supplier_id = p_supplier_id;
                IF v_vss_id IS NULL THEN
                    -- ═══ BUG-1 FIX: safe cast for quantity (integer) ═══
                    INSERT INTO variant_supplier_sources (organization_id, variant_id, supplier_id, supplier_sku,
                                                          cost_price, quantity, source, is_preferred, is_active, updated_at)
                    VALUES (v_org_id, v_variant_id, p_supplier_id, v_sup_sku,
                            NULLIF(v_ssfields->>'cost_price', '')::numeric,
                            COALESCE(ROUND(NULLIF(v_ssfields->>'quantity', '')::numeric), 0)::integer,
                            'raw_v2', true, true, now());
                ELSE
                    UPDATE variant_supplier_sources SET
                        cost_price = COALESCE(NULLIF(v_ssfields->>'cost_price', '')::numeric, cost_price),
                        quantity   = COALESCE(ROUND(NULLIF(v_ssfields->>'quantity', '')::numeric)::integer, quantity),
                        source     = 'raw_v2',
                        updated_at = now()
                    WHERE id = v_vss_id;
                END IF;
            END IF;

            UPDATE supplier_products_raw
               SET status = 'processed'::supplier_raw_status, processed_at = now(),
                   product_id = v_product_id, variant_id = v_variant_id,
                   import_batch_id = CASE WHEN v_batch_open THEN v_batch_id ELSE NULL END,
                   process_errors = NULL
             WHERE id = v_row.id;
            v_variants := v_variants + 1;

          EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || jsonb_build_object('raw_id', v_row.id, 'stage', 'variant', 'error', SQLERRM);
            v_verr := v_verr + 1;
            -- ═══ BUG-3 FIX: mark as failed to prevent infinite retry ═══
            UPDATE supplier_products_raw
               SET status = 'failed'::supplier_raw_status,
                   process_errors = jsonb_build_object('error', SQLERRM, 'stage', 'variant', 'timestamp', now())
             WHERE id = v_row.id;
          END;
        END LOOP;

        v_parents := v_parents + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_object('parent_key', v_parent.pkey, 'stage', 'parent', 'error', SQLERRM);
        v_perr := v_perr + 1;
        -- ═══ BUG-3 FIX: mark as failed to prevent infinite retry ═══
        UPDATE supplier_products_raw
           SET status = 'failed'::supplier_raw_status,
               process_errors = jsonb_build_object('error', SQLERRM, 'stage', 'parent', 'timestamp', now())
         WHERE supplier_id = p_supplier_id AND status <> 'processed'::supplier_raw_status
           AND raw_data->>v_parent_key_source = v_parent.pkey;
      END;
    END LOOP;

    IF v_batch_open THEN
        UPDATE supplier_import_batches
           SET finished_at = now(), status = 'completed',
               products_imported = v_parents, variants_imported = v_variants,
               products_errors = v_perr, variants_errors = v_verr, error_log = v_errors
         WHERE id = v_batch_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true, 'supplier_id', p_supplier_id, 'bulk_mode', p_bulk_mode,
        'batch_id', CASE WHEN v_batch_open THEN v_batch_id ELSE NULL END,
        'parents_processed', v_parents, 'variants_processed', v_variants,
        'products_errors', v_perr, 'variants_errors', v_verr, 'errors', v_errors);
END;
$function$;

-- <<< END 20260605002334_fix_fn_process_raw_v2_integer_cast_and_failed_status.sql <<<

-- >>> BEGIN 20260605002346_fix_trigger_limpar_nome_capitalize_after_strip.sql >>>

-- BUG-2 FIX: Re-capitalize first letter after limpar_nome_produto_spot strips the prefix
CREATE OR REPLACE FUNCTION public.trigger_limpar_nome_produto()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $$
DECLARE
    v_spot_supplier_id UUID := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
    v_result text;
BEGIN
    IF NEW.supplier_id = v_spot_supplier_id THEN
        v_result := limpar_nome_produto_spot(NEW.name);
        -- Re-capitalize first letter after prefix stripping
        IF v_result IS NOT NULL AND v_result <> '' THEN
            v_result := UPPER(LEFT(v_result, 1)) || SUBSTR(v_result, 2);
        END IF;
        NEW.name := v_result;
    END IF;
    
    RETURN NEW;
END;
$$;

-- <<< END 20260605002346_fix_trigger_limpar_nome_capitalize_after_strip.sql <<<

-- >>> BEGIN 20260605002357_backfill_locked_fields_brand_manual_edits.sql >>>

-- BUG-4 FIX: Protect manually-edited brand from being overwritten by pipeline
-- Identifies products where stored brand differs from raw data brand
-- and adds 'brand' to locked_fields

-- First, temporarily allow pipeline context for this migration
SELECT set_config('app.write_source', 'migration', true);

UPDATE products p
SET locked_fields = array_append(COALESCE(p.locked_fields, '{}'), 'brand')
WHERE p.supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
  AND p.brand IS NOT NULL
  AND p.brand <> ''
  AND NOT ('brand' = ANY(COALESCE(p.locked_fields, '{}')))
  AND EXISTS (
      SELECT 1 FROM supplier_products_raw spr
      WHERE spr.supplier_id = p.supplier_id
        AND spr.raw_data->>'ProdReference' = p.supplier_reference
        AND spr.raw_data->>'Brand' IS NOT NULL
        AND spr.raw_data->>'Brand' <> p.brand
      LIMIT 1
  );

-- <<< END 20260605002357_backfill_locked_fields_brand_manual_edits.sql <<<

-- >>> BEGIN 20260605004956_harden_raw_sibling_tables_rls_grants.sql >>>
-- Replica o endurecimento P4 de supplier_products_raw nas tabelas raw/staging irmãs.
-- (As irmãs NÃO têm o anti-pattern de estado duplo: já usam `status` único, sem
--  `processed`/`raw_hash`, e estão vazias — então o cutover pesado não se aplica.
--  O que se aplica é a correção de segurança de grants/RLS.)

-- 1) supplier_products_raw_history: estava com RLS DESLIGADO e `anon` com
--    INSERT/SELECT/UPDATE/DELETE/TRUNCATE/REFERENCES (rls_disabled_in_public) —
--    anon podia ler/apagar/truncar todo o histórico de payloads via API.
--    É escrita apenas pelo trigger fn_spr_history, cuja sessão (service_role/owner
--    via SECURITY DEFINER) ignora RLS. Liga RLS + policies + remove o anon.
ALTER TABLE public.supplier_products_raw_history ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.supplier_products_raw_history FROM anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES ON public.supplier_products_raw_history FROM authenticated;

DROP POLICY IF EXISTS hist_all_service ON public.supplier_products_raw_history;
CREATE POLICY hist_all_service ON public.supplier_products_raw_history
  FOR ALL TO service_role USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS hist_select_admin ON public.supplier_products_raw_history;
CREATE POLICY hist_select_admin ON public.supplier_products_raw_history
  FOR SELECT TO authenticated USING (is_admin_or_above((SELECT auth.uid())));

-- 2) Staging irmãs: remove o GRANT latente de escrita do anon (RLS já gate; anon
--    nunca escreve staging interno). authenticated mantido p/ não quebrar tooling admin.
REVOKE INSERT, UPDATE, REFERENCES ON public.import_staging_images   FROM anon;
REVOKE INSERT, UPDATE, REFERENCES ON public.color_analysis_staging  FROM anon;
REVOKE INSERT, UPDATE, REFERENCES ON public.xbz_gallery_staging     FROM anon;
REVOKE INSERT, UPDATE, REFERENCES ON public.scraper_images_staging  FROM anon;
REVOKE INSERT, UPDATE, REFERENCES ON public.sm_images_staging       FROM anon;
REVOKE INSERT, UPDATE, REFERENCES ON public._asia_api_staging       FROM anon;

-- <<< END 20260605004956_harden_raw_sibling_tables_rls_grants.sql <<<

-- >>> BEGIN 20260605010642_20260605130000_spr2_fix_motor_quarantine_terminal.sql >>>

-- ============================================================================
-- supplier_products_raw — HOTFIX: Fase 3 (Motor quarentena terminal)
-- ----------------------------------------------------------------------------
-- A Fase 3 original falhou silenciosamente: fn_process_raw_v2 ainda usa
-- `status <> 'processed'` (inclui 'quarantined'), então linhas quarentenadas
-- são reprocessadas indefinidamente, anulando o poison-pill implementado na
-- Fase 1. Esta migração re-aplica a substituição do predicado de fila.
-- ============================================================================

DO $migrate$
DECLARE
  v_def    text;
  v_before text := 'status <> ''processed''::supplier_raw_status';
  v_after  text := 'status NOT IN (''processed''::supplier_raw_status, ''quarantined''::supplier_raw_status)';
  v_count  int;
BEGIN
  v_def := pg_get_functiondef('public.fn_process_raw_v2(uuid, integer, boolean)'::regprocedure);

  v_count := (length(v_def) - length(replace(v_def, v_before, ''))) / length(v_before);
  IF v_count < 1 THEN
    RAISE EXCEPTION 'Predicado de fila não encontrado em fn_process_raw_v2 (achados=%); abortando.', v_count;
  END IF;
  RAISE NOTICE 'fn_process_raw_v2: substituindo % ocorrência(s) do predicado de fila.', v_count;

  v_def := replace(v_def, v_before, v_after);
  EXECUTE v_def;
END
$migrate$;

-- <<< END 20260605010642_20260605130000_spr2_fix_motor_quarantine_terminal.sql <<<

-- >>> BEGIN 20260605010707_20260605130100_spr2_fix_idx_unprocessed_predicate.sql >>>

-- ============================================================================
-- supplier_products_raw — HOTFIX: idx_spr_unprocessed predicate
-- ----------------------------------------------------------------------------
-- O predicado do índice era `status <> 'processed'` (inclui quarantined), mas
-- o motor usa `status NOT IN ('processed','quarantined')`. O PostgreSQL pode
-- usar o índice mesmo assim (predicado da query implica o do índice), porém
-- visita linhas quarentenadas desnecessariamente. Alinhando o predicado.
-- ============================================================================

DROP INDEX IF EXISTS public.idx_spr_unprocessed;

CREATE INDEX idx_spr_unprocessed
  ON public.supplier_products_raw (supplier_id, imported_at)
  WHERE status NOT IN ('processed'::supplier_raw_status, 'quarantined'::supplier_raw_status);

-- <<< END 20260605010707_20260605130100_spr2_fix_idx_unprocessed_predicate.sql <<<

-- >>> BEGIN 20260605011404_fix_fn_process_raw_v2_exclude_failed_from_selection.sql >>>

-- BUG-3b FIX: Exclude 'failed' and 'quarantined' from selection
-- so that rows permanently broken don't loop forever.
-- Only 'pending' and 'processing' (in-flight recovery) are eligible.

CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(p_supplier_id uuid, p_batch_size integer DEFAULT 100, p_bulk_mode boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_org_id            uuid;
    v_parent_key_source text;
    v_name_template     text;
    v_sku_prefix        text;
    v_prep              jsonb;
    v_parent            record;
    v_row               record;
    v_map               record;
    v_product_id        uuid;
    v_variant_id        uuid;
    v_vss_id            uuid;
    v_locked            text[];
    v_val               text;
    v_tv                text;
    v_parts             text[];
    v_vfields           jsonb;
    v_ssfields          jsonb;
    v_name              text;
    v_attrs             jsonb;
    v_sku               text;
    v_sup_sku           text;
    v_k                 text;
    v_v                 text;
    v_parents           integer := 0;
    v_variants          integer := 0;
    v_errors            jsonb := '[]'::jsonb;
    v_batch_id          uuid := gen_random_uuid();
    v_started           timestamptz := now();
    v_perr              integer := 0;
    v_verr              integer := 0;
    v_batch_open        boolean := false;
    v_pending_count     integer := 0;
    v_int_cols_products  text[];
    v_int_cols_variants  text[];
    -- BUG-3b: statuses elegíveis (não inclui 'failed','quarantined','processed','skipped')
    v_eligible_statuses supplier_raw_status[] :=
        ARRAY['pending','processing']::supplier_raw_status[];
BEGIN
    IF auth.uid() IS NOT NULL AND NOT is_admin_or_above((SELECT auth.uid())) THEN
        RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
    END IF;

    IF NOT pg_try_advisory_xact_lock(hashtextextended('fn_process_raw_v2:'||p_supplier_id::text, 0)) THEN
        RETURN jsonb_build_object('success', true, 'skipped', 'lock_contention',
            'supplier_id', p_supplier_id, 'parents_processed', 0, 'variants_processed', 0);
    END IF;

    PERFORM set_config('app.write_source', 'pipeline', true);
    PERFORM set_config('app.bulk_import_mode', p_bulk_mode::text, true);

    SELECT organization_id INTO v_org_id FROM suppliers WHERE id = p_supplier_id;

    SELECT parent_key_source, variant_name_template, sku_prefix
      INTO v_parent_key_source, v_name_template, v_sku_prefix
      FROM supplier_settings WHERE supplier_id = p_supplier_id;

    IF v_parent_key_source IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error', 'supplier_settings.parent_key_source ausente para o fornecedor '||p_supplier_id);
    END IF;
    v_name_template := COALESCE(v_name_template, '{product_name}');

    -- Pre-build integer column lists for safe casting
    SELECT COALESCE(array_agg(column_name), '{}') INTO v_int_cols_products
      FROM information_schema.columns
     WHERE table_schema = 'public' AND table_name = 'products'
       AND data_type IN ('integer', 'smallint', 'bigint');

    SELECT COALESCE(array_agg(column_name), '{}') INTO v_int_cols_variants
      FROM information_schema.columns
     WHERE table_schema = 'public' AND table_name = 'product_variants'
       AND data_type IN ('integer', 'smallint', 'bigint');

    -- BUG-3b: contar apenas linhas elegíveis (pending/processing)
    SELECT COUNT(DISTINCT raw_data->>v_parent_key_source)
      INTO v_pending_count
      FROM supplier_products_raw
     WHERE supplier_id = p_supplier_id
       AND status = ANY(v_eligible_statuses)
       AND NULLIF(raw_data->>v_parent_key_source, '') IS NOT NULL;

    IF v_pending_count > 0 THEN
        INSERT INTO supplier_import_batches (id, supplier_id, started_at, status)
        VALUES (v_batch_id, p_supplier_id, v_started, 'processing');
        v_batch_open := true;
    ELSE
        RETURN jsonb_build_object(
            'success', true, 'supplier_id', p_supplier_id,
            'batch_id', NULL, 'parents_processed', 0, 'variants_processed', 0,
            'message', 'Nenhuma linha pendente encontrada');
    END IF;

    -- BUG-3b: selecionar apenas linhas elegíveis
    FOR v_parent IN
        SELECT DISTINCT raw_data->>v_parent_key_source AS pkey
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id
           AND status = ANY(v_eligible_statuses)
           AND NULLIF(raw_data->>v_parent_key_source, '') IS NOT NULL
         LIMIT p_batch_size
    LOOP
      BEGIN
        SELECT id INTO v_product_id
          FROM products
         WHERE supplier_id = p_supplier_id AND supplier_reference = v_parent.pkey;

        IF v_product_id IS NULL THEN
            INSERT INTO products (organization_id, supplier_id, supplier_reference, sku, name,
                                  active, is_active, sync_status, created_at, updated_at)
            VALUES (v_org_id, p_supplier_id, v_parent.pkey,
                    COALESCE(v_sku_prefix, '') || v_parent.pkey,
                    'Produto ' || v_parent.pkey, true, true, 'processing', now(), now())
            RETURNING id INTO v_product_id;
        END IF;

        SELECT COALESCE(locked_fields, '{}'::text[]) INTO v_locked
          FROM products WHERE id = v_product_id;

        SELECT raw_data INTO v_prep
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id
           AND status = ANY(v_eligible_statuses)
           AND raw_data->>v_parent_key_source = v_parent.pkey
         ORDER BY imported_at DESC NULLS LAST LIMIT 1;

        v_parts := ARRAY[]::text[];
        FOR v_map IN
            SELECT * FROM supplier_field_mappings
             WHERE supplier_id = p_supplier_id AND target_table = 'products' AND is_active = true
             ORDER BY priority
        LOOP
            CONTINUE WHEN v_map.target_field = ANY(v_locked);
            v_val := CASE WHEN v_map.source_path IS NOT NULL
                          THEN v_prep #>> string_to_array(v_map.source_path, '.')
                          ELSE v_prep ->> v_map.source_field END;
            CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
            v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                       v_map.source_unit, v_map.target_unit, p_supplier_id);
            IF v_tv IS NOT NULL THEN
                IF v_map.target_field = ANY(v_int_cols_products) THEN
                    v_parts := array_append(v_parts, format('%I = ROUND(%L::numeric)', v_map.target_field, v_tv));
                ELSE
                    v_parts := array_append(v_parts, format('%I = %L', v_map.target_field, v_tv));
                END IF;
            END IF;
        END LOOP;

        IF array_length(v_parts, 1) > 0 THEN
            EXECUTE format(
              'UPDATE products SET %s, updated_at=now(), sync_status=''synced'', last_sync_at=now(), last_sync_supplier_id=%L WHERE id=%L',
              array_to_string(v_parts, ', '), p_supplier_id, v_product_id);
        END IF;

        UPDATE products
           SET dimensions_display = fn_format_dimensions_display(length_cm, width_cm, height_cm)
         WHERE id = v_product_id AND length_cm IS NOT NULL
           AND NOT ('dimensions_display' = ANY(v_locked));

        -- BUG-3b: FOR loop também filtra apenas elegíveis
        FOR v_row IN
            SELECT * FROM supplier_products_raw
             WHERE supplier_id = p_supplier_id
               AND status = ANY(v_eligible_statuses)
               AND raw_data->>v_parent_key_source = v_parent.pkey
             FOR UPDATE SKIP LOCKED
        LOOP
          BEGIN
            v_vfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id = p_supplier_id AND target_table = 'product_variants' AND is_active = true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path, '.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_vfields := v_vfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            v_name := replace(v_name_template, '{product_name}',
                              COALESCE((SELECT name FROM products WHERE id = v_product_id), ''));
            v_name := replace(v_name, '{color_name}',  COALESCE(v_vfields->>'color_name', ''));
            v_name := replace(v_name, '{size_code}',   COALESCE(v_vfields->>'size_code', ''));
            v_name := replace(v_name, '{capacity_ml}', COALESCE(v_vfields->>'capacity_ml', ''));
            v_name := regexp_replace(v_name, '\s*\|\s*\|\s*', ' | ', 'g');
            v_name := btrim(regexp_replace(v_name, '\s*[|]\s*$', ''));
            v_attrs := jsonb_build_object(
                'codigo_cor', COALESCE(v_vfields->>'color_code', ''),
                'cor',        COALESCE(v_vfields->>'color_name', '')
            );

            v_sup_sku := NULLIF(v_row.supplier_sku, '');
            v_variant_id := NULL;
            IF v_sup_sku IS NOT NULL THEN
                SELECT id INTO v_variant_id FROM product_variants
                 WHERE product_id = v_product_id AND supplier_sku = v_sup_sku;
            END IF;

            IF v_variant_id IS NULL THEN
                v_sku := COALESCE(v_vfields->>'sku', v_sup_sku, v_row.supplier_reference);
                INSERT INTO product_variants (product_id, sku, supplier_sku, name,
                                              color_code, color_name, color_hex, attributes, is_active, created_at, updated_at)
                VALUES (v_product_id, v_sku, v_sup_sku, v_name,
                        v_vfields->>'color_code', v_vfields->>'color_name', v_vfields->>'color_hex',
                        v_attrs, true, now(), now())
                ON CONFLICT (sku) DO UPDATE SET
                    supplier_sku = EXCLUDED.supplier_sku, name = EXCLUDED.name, color_code = EXCLUDED.color_code,
                    color_name = EXCLUDED.color_name, color_hex = EXCLUDED.color_hex, attributes = EXCLUDED.attributes,
                    updated_at = now()
                RETURNING id INTO v_variant_id;
            ELSE
                UPDATE product_variants SET
                    name = v_name, color_code = v_vfields->>'color_code', color_name = v_vfields->>'color_name',
                    color_hex = v_vfields->>'color_hex', attributes = v_attrs, updated_at = now()
                WHERE id = v_variant_id;
            END IF;

            v_parts := ARRAY[]::text[];
            FOR v_k, v_v IN
                SELECT key, value FROM jsonb_each_text(
                    v_vfields - 'sku' - 'supplier_sku' - 'color_code' - 'color_name' - 'color_hex')
            LOOP
                IF v_k = ANY(v_int_cols_variants) THEN
                    v_parts := array_append(v_parts, format('%I = ROUND(%L::numeric)', v_k, v_v));
                ELSE
                    v_parts := array_append(v_parts, format('%I = %L', v_k, v_v));
                END IF;
            END LOOP;
            IF array_length(v_parts, 1) > 0 THEN
                EXECUTE format('UPDATE product_variants SET %s, updated_at=now() WHERE id=%L',
                               array_to_string(v_parts, ', '), v_variant_id);
            END IF;

            v_ssfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id = p_supplier_id AND target_table = 'variant_supplier_sources' AND is_active = true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path, '.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val) = '';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_ssfields := v_ssfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            IF v_ssfields <> '{}'::jsonb THEN
                SELECT id INTO v_vss_id FROM variant_supplier_sources
                 WHERE variant_id = v_variant_id AND supplier_id = p_supplier_id;
                IF v_vss_id IS NULL THEN
                    INSERT INTO variant_supplier_sources (organization_id, variant_id, supplier_id, supplier_sku,
                                                          cost_price, quantity, source, is_preferred, is_active, updated_at)
                    VALUES (v_org_id, v_variant_id, p_supplier_id, v_sup_sku,
                            NULLIF(v_ssfields->>'cost_price', '')::numeric,
                            COALESCE(ROUND(NULLIF(v_ssfields->>'quantity', '')::numeric), 0)::integer,
                            'raw_v2', true, true, now());
                ELSE
                    UPDATE variant_supplier_sources SET
                        cost_price = COALESCE(NULLIF(v_ssfields->>'cost_price', '')::numeric, cost_price),
                        quantity   = COALESCE(ROUND(NULLIF(v_ssfields->>'quantity', '')::numeric)::integer, quantity),
                        source     = 'raw_v2',
                        updated_at = now()
                    WHERE id = v_vss_id;
                END IF;
            END IF;

            UPDATE supplier_products_raw
               SET status = 'processed'::supplier_raw_status, processed_at = now(),
                   product_id = v_product_id, variant_id = v_variant_id,
                   import_batch_id = CASE WHEN v_batch_open THEN v_batch_id ELSE NULL END,
                   process_errors = NULL
             WHERE id = v_row.id;
            v_variants := v_variants + 1;

          EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || jsonb_build_object('raw_id', v_row.id, 'stage', 'variant', 'error', SQLERRM);
            v_verr := v_verr + 1;
            UPDATE supplier_products_raw
               SET status = 'failed'::supplier_raw_status,
                   process_errors = jsonb_build_object('error', SQLERRM, 'stage', 'variant', 'timestamp', now())
             WHERE id = v_row.id;
          END;
        END LOOP;

        v_parents := v_parents + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_object('parent_key', v_parent.pkey, 'stage', 'parent', 'error', SQLERRM);
        v_perr := v_perr + 1;
        UPDATE supplier_products_raw
           SET status = 'failed'::supplier_raw_status,
               process_errors = jsonb_build_object('error', SQLERRM, 'stage', 'parent', 'timestamp', now())
         WHERE supplier_id = p_supplier_id
           AND status = ANY(v_eligible_statuses)
           AND raw_data->>v_parent_key_source = v_parent.pkey;
      END;
    END LOOP;

    IF v_batch_open THEN
        UPDATE supplier_import_batches
           SET finished_at = now(), status = 'completed',
               products_imported = v_parents, variants_imported = v_variants,
               products_errors = v_perr, variants_errors = v_verr, error_log = v_errors
         WHERE id = v_batch_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true, 'supplier_id', p_supplier_id, 'bulk_mode', p_bulk_mode,
        'batch_id', CASE WHEN v_batch_open THEN v_batch_id ELSE NULL END,
        'parents_processed', v_parents, 'variants_processed', v_variants,
        'products_errors', v_perr, 'variants_errors', v_verr, 'errors', v_errors);
END;
$function$;

