-- >>> BEGIN 20260605012204_fix_spr_content_hash_sha256.sql >>>
CREATE OR REPLACE FUNCTION public.fn_spr_before_write()
RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $fn$
DECLARE v_clean jsonb;
BEGIN
  IF NEW.raw_data ? '_source' AND COALESCE(NEW.source_channel,'') IN ('','n8n','legacy') THEN
    NEW.source_channel := NEW.raw_data->>'_source';
  END IF;
  IF NEW.raw_data ? '_imported_at' AND NEW.imported_at IS NULL THEN
    BEGIN NEW.imported_at := (NEW.raw_data->>'_imported_at')::timestamptz;
    EXCEPTION WHEN others THEN NULL; END;
  END IF;

  v_clean := NEW.raw_data - '_source' - '_api_fields_count' - '_imported_at';
  NEW.raw_data     := v_clean;
  NEW.content_hash := encode(digest(v_clean::text, 'sha256'), 'hex');  -- era md5(): agora alinhado ao DEFAULT e aos 16.508 registros existentes (todos sha256)

  IF TG_OP = 'INSERT' THEN
    NEW.imported_at := COALESCE(NEW.imported_at, now());
    IF NEW.process_errors IS NOT NULL AND NEW.last_error IS NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;
  ELSE
    NEW.updated_at := now();

    IF NEW.process_errors IS DISTINCT FROM OLD.process_errors
       AND NEW.process_errors IS NOT NULL THEN
      NEW.last_error := NEW.process_errors;
      NEW.attempts   := COALESCE(OLD.attempts, 0) + 1;
      IF NEW.status <> 'processed'::supplier_raw_status THEN
        NEW.status := CASE WHEN NEW.attempts >= 5
                           THEN 'quarantined'::supplier_raw_status
                           ELSE 'failed'::supplier_raw_status END;
      END IF;
    END IF;

    IF NEW.status = 'processed'::supplier_raw_status
       AND NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed_at := COALESCE(NEW.processed_at, now());
    END IF;
  END IF;

  RETURN NEW;
END $fn$;

COMMENT ON COLUMN public.supplier_products_raw.content_hash IS
  'sha256(raw_data limpo, hex) — SSOT de dedup/deteccao de mudanca. Mantido por fn_spr_before_write (trigger trg_spr_before_write).';
-- <<< END 20260605012204_fix_spr_content_hash_sha256.sql <<<

-- >>> BEGIN 20260605012231_fix_spr_before_write_search_path.sql >>>
ALTER FUNCTION public.fn_spr_before_write()
  SET search_path TO 'public', 'extensions';
-- <<< END 20260605012231_fix_spr_before_write_search_path.sql <<<

-- >>> BEGIN 20260605012421_spr_p1_security_close_bronze_to_anon.sql >>>
-- 1) Blindar o gateway: security_invoker=false EXPLICITO (nao depender do default do Postgres)
ALTER VIEW public.somarcas_catalogo_publico SET (security_invoker = false);

COMMENT ON VIEW public.somarcas_catalogo_publico IS
  'Gateway publico (anon) do catalogo So Marcas. security_invoker=false POR DESIGN: roda como owner e expoe apenas colunas publicas (precos COM impostos, disponivel booleano), nunca custo sem impostos/ipi/ncm/estoque numerico. O lint security_definer_view e esperado e intencional aqui.';

-- 2) Enxugar grants do anon na VIEW: deixar apenas SELECT
REVOKE ALL ON public.somarcas_catalogo_publico FROM anon;
GRANT SELECT ON public.somarcas_catalogo_publico TO anon;

-- 3) Fechar a bronze ao anon: remover policy legada + revogar TODOS os privilegios
DROP POLICY IF EXISTS spr_select_anon_somarcas ON public.supplier_products_raw;
REVOKE ALL ON public.supplier_products_raw FROM anon;

-- 4) Enxugar privilegios excessivos do authenticated na bronze (manter SELECT, governado por spr_select_admin)
REVOKE DELETE, TRUNCATE, TRIGGER, REFERENCES, INSERT, UPDATE ON public.supplier_products_raw FROM authenticated;
-- <<< END 20260605012421_spr_p1_security_close_bronze_to_anon.sql <<<

-- >>> BEGIN 20260605012555_harden_spr_grants_and_fix_somarcas_view_filter.sql >>>
-- 1) Remover privilegios perigosos (TRUNCATE ignora RLS; DELETE/TRIGGER sem uso para anon/authenticated)
REVOKE DELETE, TRIGGER, TRUNCATE ON public.supplier_products_raw FROM anon;
REVOKE DELETE, TRIGGER, TRUNCATE ON public.supplier_products_raw FROM authenticated;

-- 2) Corrigir filtro da view publica (estava 'true', dados usam 'sim' => view retornava 0 linhas)
--    Mantidas as MESMAS colunas/ordem para o CREATE OR REPLACE aceitar.
CREATE OR REPLACE VIEW public.somarcas_catalogo_publico AS
SELECT id,
    raw_data ->> 'codigo'                            AS codigo,
    raw_data ->> 'titulo'                            AS titulo,
    raw_data ->> 'descricao'                         AS descricao,
    raw_data ->> 'url_foto'                          AS url_foto,
    raw_data -> 'matriz_de_fotos_adicionais'         AS fotos_adicionais,
    raw_data -> 'matriz_de_categorias'               AS categorias,
    raw_data -> 'produtos_similares'                 AS produtos_similares,
    raw_data ->> 'dimensoes_do_produto'              AS dimensoes_produto,
    raw_data ->> 'dimensoes_da_embalagem'            AS dimensoes_embalagem,
    raw_data ->> 'peso_da_embalagem'                 AS peso_embalagem,
    raw_data ->> 'embalagem_do_produto'              AS embalagem,
    raw_data ->> 'garantia_do_produto'               AS garantia,
    raw_data ->> 'tipo_gravacao'                     AS tipo_gravacao,
    raw_data ->> 'quantidade_minima_sugerida'        AS quantidade_minima,
    raw_data ->> 'preco_com_gravacao_com_impostos'   AS preco_com_gravacao,
    raw_data ->> 'preco_sem_gravacao_com_impostos'   AS preco_sem_gravacao,
    COALESCE((raw_data ->> 'estoque')::numeric, 0::numeric) > 0::numeric AS disponivel,
    raw_data ->> 'data_ultima_atualizacao'           AS atualizado_em,
    variant_id,
    product_id
FROM supplier_products_raw r
WHERE supplier_id = '841cd690-210a-422a-908c-7676828db272'::uuid
  AND COALESCE(lower(raw_data ->> 'produto_ativo'), 'sim') NOT IN ('nao','não','false','0','f','inativo','no');

COMMENT ON VIEW public.somarcas_catalogo_publico IS
  'Catalogo publico So Marcas (role anon). So vitrine + precos COM impostos; estoque vira boolean disponivel. NUNCA expor precos sem impostos/ipi/ncm/estoque numerico. Filtro corrigido 2026-06: produto_ativo usa valor sim.';

-- 3) Garantir leitura da VIEW pelo anon (idempotente)
GRANT SELECT ON public.somarcas_catalogo_publico TO anon;
-- <<< END 20260605012555_harden_spr_grants_and_fix_somarcas_view_filter.sql <<<

-- >>> BEGIN 20260605012821_spr_indexes_images_queue_and_event_idempotency.sql >>>
-- Worker de imagens: 11.641 linhas pending sem indice -> seq scan de 57MB a cada poll
CREATE INDEX IF NOT EXISTS idx_spr_images_pending
  ON public.supplier_products_raw (supplier_id, imported_at)
  WHERE images_status <> 'processed'::supplier_raw_status;

-- Idempotencia de ingestao por evento (vazio hoje pois source_event_id e 100% NULL;
-- protege contra reentrega/duplicacao quando o n8n passar a popular)
CREATE UNIQUE INDEX IF NOT EXISTS uq_spr_source_event
