-- >>> BEGIN 20260605110500_sync_active_with_is_active_in_fn_promote_padronizacao.sql >>>
-- fn_promote_padronizacao: o INSERT de produto novo grava `active` e `is_active`
-- em lockstep (ambos = COALESCE(s.is_active,true)), mas o UPDATE de produto ja
-- existente so sincronizava `is_active`, deixando `active` defasado quando o
-- fornecedor alterna o status. Como as duas colunas representam o mesmo conceito
-- (compat legada), o UPDATE passa a manter `active` em lockstep com `is_active`,
-- respeitando o mesmo lock 'is_active'. Forward fix (sem editar a migration
-- byte-exata 20260605101258); so adiciona uma coluna ao SET.
CREATE OR REPLACE FUNCTION public.fn_promote_padronizacao(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  s         public.produtos_padronizacao%ROWTYPE;
  v_pid     uuid;
  v_org     uuid;
  v_locked  text[];
  v_is_new  boolean := false;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  PERFORM set_config('app.write_source', 'pipeline', true);

  SELECT id, locked_fields INTO v_pid, v_locked
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, active, is_active, product_type)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name), COALESCE(s.name,'Produto '||s.supplier_reference),
            COALESCE(s.is_active, true), COALESCE(s.is_active, true), 'product')
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  UPDATE public.products p SET
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(s.name, p.name) END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description, p.description) END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description, p.short_description) END,
    cost_price         = CASE WHEN 'cost_price'         = ANY(v_locked) THEN p.cost_price         ELSE COALESCE(s.cost_price, p.cost_price) END,
    suggested_price    = CASE WHEN 'suggested_price'    = ANY(v_locked) THEN p.suggested_price    ELSE COALESCE(s.suggested_price, p.suggested_price) END,
    stock_quantity     = CASE WHEN 'stock_quantity'     = ANY(v_locked) THEN p.stock_quantity     ELSE COALESCE(s.stock_quantity, p.stock_quantity) END,
    primary_image_url  = CASE WHEN 'primary_image_url'  = ANY(v_locked) THEN p.primary_image_url  ELSE COALESCE(s.primary_image_url, p.primary_image_url) END,
    images             = CASE WHEN 'images'             = ANY(v_locked) THEN p.images             ELSE COALESCE(s.images, p.images) END,
    ncm_code           = CASE WHEN 'ncm_code'           = ANY(v_locked) THEN p.ncm_code           ELSE COALESCE(s.ncm_code, p.ncm_code) END,
    weight_g           = CASE WHEN 'weight_g'           = ANY(v_locked) THEN p.weight_g           ELSE COALESCE(s.weight_g, p.weight_g) END,
    height_cm          = CASE WHEN 'height_cm'          = ANY(v_locked) THEN p.height_cm          ELSE COALESCE(s.height_cm, p.height_cm) END,
    width_cm           = CASE WHEN 'width_cm'           = ANY(v_locked) THEN p.width_cm           ELSE COALESCE(s.width_cm, p.width_cm) END,
    length_cm          = CASE WHEN 'length_cm'          = ANY(v_locked) THEN p.length_cm          ELSE COALESCE(s.length_cm, p.length_cm) END,
    dimensions_display = CASE WHEN 'dimensions_display' = ANY(v_locked) THEN p.dimensions_display ELSE COALESCE(s.dimensions_display, p.dimensions_display) END,
    box_length_cm      = CASE WHEN 'box_length_cm'      = ANY(v_locked) THEN p.box_length_cm      ELSE COALESCE(s.box_length_cm, p.box_length_cm) END,
    box_width_cm       = CASE WHEN 'box_width_cm'       = ANY(v_locked) THEN p.box_width_cm       ELSE COALESCE(s.box_width_cm, p.box_width_cm) END,
    box_height_cm      = CASE WHEN 'box_height_cm'      = ANY(v_locked) THEN p.box_height_cm      ELSE COALESCE(s.box_height_cm, p.box_height_cm) END,
    box_weight_kg      = CASE WHEN 'box_weight_kg'      = ANY(v_locked) THEN p.box_weight_kg      ELSE COALESCE(s.box_weight_kg, p.box_weight_kg) END,
    box_volume_cm3     = CASE WHEN 'box_volume_cm3'     = ANY(v_locked) THEN p.box_volume_cm3     ELSE COALESCE(s.box_volume_cm3, p.box_volume_cm3) END,
    box_quantity       = CASE WHEN 'box_quantity'       = ANY(v_locked) THEN p.box_quantity       ELSE COALESCE(s.box_quantity, p.box_quantity) END,
    box_inner_quantity = CASE WHEN 'box_inner_quantity' = ANY(v_locked) THEN p.box_inner_quantity ELSE COALESCE(s.box_inner_quantity, p.box_inner_quantity) END,
    brand              = CASE WHEN 'brand'              = ANY(v_locked) THEN p.brand              ELSE COALESCE(s.brand, p.brand) END,
    packing_type       = CASE WHEN 'packing_type'       = ANY(v_locked) THEN p.packing_type       ELSE COALESCE(s.packing_type, p.packing_type) END,
    repacking_type     = CASE WHEN 'repacking_type'     = ANY(v_locked) THEN p.repacking_type     ELSE COALESCE(s.repacking_type, p.repacking_type) END,
    capacities         = CASE WHEN 'capacities'         = ANY(v_locked) THEN p.capacities         ELSE COALESCE(s.capacities, p.capacities) END,
    capacity_ml        = CASE WHEN 'capacity_ml'        = ANY(v_locked) THEN p.capacity_ml        ELSE COALESCE(s.capacity_ml, p.capacity_ml) END,
    min_quantity       = CASE WHEN 'min_quantity'       = ANY(v_locked) THEN p.min_quantity       ELSE COALESCE(s.min_quantity, p.min_quantity) END,
    warranty_months    = CASE WHEN 'warranty_months'    = ANY(v_locked) THEN p.warranty_months    ELSE COALESCE(s.warranty_months, p.warranty_months) END,
    ipi_rate           = CASE WHEN 'ipi_rate'           = ANY(v_locked) THEN p.ipi_rate           ELSE COALESCE(s.ipi_rate, p.ipi_rate) END,
    engraving_type     = CASE WHEN 'engraving_type'     = ANY(v_locked) THEN p.engraving_type     ELSE COALESCE(s.engraving_type, p.engraving_type) END,
    colors             = CASE WHEN 'colors'             = ANY(v_locked) THEN p.colors             ELSE COALESCE(s.colors, p.colors) END,
    is_active          = CASE WHEN 'is_active'          = ANY(v_locked) THEN p.is_active          ELSE COALESCE(s.is_active, p.is_active) END,
    active             = CASE WHEN 'is_active'          = ANY(v_locked) THEN p.active             ELSE COALESCE(s.is_active, p.active) END,
    last_sync_at          = now(),
    last_sync_supplier_id = s.supplier_id,
    supplier_updated_at   = now()
  WHERE p.id = v_pid;

  UPDATE public.produtos_padronizacao
     SET status='promoted', promoted_at=now(), product_id=v_pid
   WHERE id = p_id;

  IF s.raw_id IS NOT NULL THEN
    UPDATE public.supplier_products_raw
       SET status='processed', processed_at=now(), product_id=v_pid
     WHERE id = s.raw_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'product_id', v_pid, 'created', v_is_new,
                            'locked_preserved', v_locked);
END;
$function$;

-- <<< END 20260605110500_sync_active_with_is_active_in_fn_promote_padronizacao.sql <<<

-- >>> BEGIN 20260605120000_spr2_state_integrity_and_wiring.sql >>>
-- ============================================================================
-- supplier_products_raw — Refactor v2 (Fase 1/5): Integridade do estado
-- ----------------------------------------------------------------------------
-- Contexto: o motor (fn_process_raw_v2) gravava process_errors no handler de
-- exceção mas NUNCA refletia isso no status (ficava 'processed'/'pending') e
-- nunca contava a tentativa. Resultado medido: 499 linhas status='processed'
-- COM process_errors (estado mentiroso) e as colunas attempts/last_error como
-- scaffolding de uma máquina de retry que nunca foi ligada.
--
-- Esta fase:
--   1. Liga a contagem de tentativas + estado verdadeiro (failed/quarantined)
--      DENTRO do trigger BEFORE WRITE — sem reescrever o motor. Sempre que o
--      pipeline grava um novo process_errors, o trigger conta a tentativa,
--      guarda last_error e marca failed (ou quarantined a partir de 5 falhas).
--   2. Remove a atribuição de images_processed (vira coluna gerada na Fase 2).
--   3. Reconcilia as 499 linhas inconsistentes -> failed (verdade).
--   4. Trava o invariante com CHECK: nunca mais processed + process_errors.
-- ============================================================================

-- 1) Trigger consolidado BEFORE INSERT/UPDATE — agora com wiring de retry
CREATE OR REPLACE FUNCTION public.fn_spr_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_clean jsonb;
BEGIN
  IF NEW.raw_data ? '_source' AND COALESCE(NEW.source_channel,'') IN ('','n8n','legacy') THEN
    NEW.source_channel := NEW.raw_data->>'_source';
  END IF;
  IF NEW.raw_data ? '_imported_at' AND NEW.imported_at IS NULL THEN
    BEGIN NEW.imported_at := (NEW.raw_data->>'_imported_at')::timestamptz;
    EXCEPTION WHEN others THEN NULL; END;
  END IF;

  v_clean := NEW.raw_data - '_source' - '_api_fields_count' - '_imported_at';
  NEW.raw_data     := v_clean;
  NEW.content_hash := md5(v_clean::text);

  IF TG_OP = 'INSERT' THEN
    NEW.imported_at := COALESCE(NEW.imported_at, now());
    IF NEW.process_errors IS NOT NULL AND NEW.last_error IS NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;
  ELSE
    NEW.updated_at := now();

    -- Quando o pipeline registra um NOVO erro, refletir o estado de forma
    -- verdadeira: contar a tentativa, guardar o ultimo erro e marcar
    -- failed (ou quarantined a partir de 5 tentativas, poison-pill).
    IF NEW.process_errors IS DISTINCT FROM OLD.process_errors
       AND NEW.process_errors IS NOT NULL THEN
      NEW.last_error := NEW.process_errors;
      NEW.attempts   := COALESCE(OLD.attempts, 0) + 1;
      IF NEW.status <> 'processed'::supplier_raw_status THEN
        NEW.status := CASE WHEN NEW.attempts >= 5
                           THEN 'quarantined'::supplier_raw_status
                           ELSE 'failed'::supplier_raw_status END;
      END IF;
    END IF;

    IF NEW.status = 'processed'::supplier_raw_status
       AND NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed_at := COALESCE(NEW.processed_at, now());
    END IF;
  END IF;

  -- images_processed deixa de ser sincronizada aqui; vira coluna GERADA (Fase 2).

  RETURN NEW;
END $function$;

-- 2) Reconciliar as 499 linhas "processed com erro" -> estado verdadeiro.
--    São escritas na silver que falharam; voltam para a fila como 'failed'
--    (o motor reprocessa; se falhar 5x, o trigger as coloca em quarantined).
UPDATE public.supplier_products_raw
   SET status   = 'failed'::supplier_raw_status,
       attempts = GREATEST(attempts, 1)
 WHERE status = 'processed'::supplier_raw_status
   AND process_errors IS NOT NULL;

-- 3) Invariante: jamais 'processed' carregando erro de processamento.
ALTER TABLE public.supplier_products_raw
  ADD CONSTRAINT chk_spr_no_processed_with_errors
  CHECK (NOT (status = 'processed'::supplier_raw_status AND process_errors IS NOT NULL));

-- <<< END 20260605120000_spr2_state_integrity_and_wiring.sql <<<

-- >>> BEGIN 20260605120100_spr2_images_generated_drop_claimed.sql >>>
-- ============================================================================
-- supplier_products_raw — Refactor v2 (Fase 2/5): Colunas derivadas e mortas
-- ----------------------------------------------------------------------------
--   * images_processed: hoje é espelho perfeito de images_status (drift=0),
--     mantido por trigger — mesmo anti-padrão já eliminado com `processed`.
--     Vira coluna GERADA (zero trigger, drift impossível por construção).
--   * claimed_at: 100% NULL. O motor faz claim via advisory lock +
--     FOR UPDATE SKIP LOCKED; a coluna nunca foi usada por nenhuma função,
--     view ou código de app (só aparecia nos tipos gerados). Removida.
--   * Timestamps de ciclo de vida passam a NOT NULL (nunca são nulos).
-- Pré-requisito: Fase 1 (o trigger não atribui mais images_processed).
-- ============================================================================

-- 1) images_processed: boolean comum -> coluna gerada espelhando o enum
ALTER TABLE public.supplier_products_raw DROP COLUMN images_processed;
ALTER TABLE public.supplier_products_raw
  ADD COLUMN images_processed boolean
  GENERATED ALWAYS AS (images_status = 'processed'::supplier_raw_status) STORED;

COMMENT ON COLUMN public.supplier_products_raw.images_processed IS
  'Derivada (GENERATED) de images_status. SSOT = images_status; nunca escrever direto.';

-- 2) claimed_at: coluna morta (claim é via advisory lock + SKIP LOCKED)
ALTER TABLE public.supplier_products_raw DROP COLUMN claimed_at;

-- 3) Timestamps sempre presentes -> NOT NULL (com backfill defensivo)
UPDATE public.supplier_products_raw
   SET imported_at = COALESCE(imported_at, created_at, now())
 WHERE imported_at IS NULL;
UPDATE public.supplier_products_raw
   SET created_at = COALESCE(created_at, imported_at, now())
 WHERE created_at IS NULL;
UPDATE public.supplier_products_raw
   SET updated_at = COALESCE(updated_at, created_at, now())
 WHERE updated_at IS NULL;

ALTER TABLE public.supplier_products_raw
  ALTER COLUMN imported_at SET NOT NULL,
  ALTER COLUMN created_at  SET NOT NULL,
  ALTER COLUMN updated_at  SET NOT NULL;

COMMENT ON COLUMN public.supplier_products_raw.attempts IS
  'Nº de tentativas de processamento. Incrementada pelo trigger fn_spr_before_write a cada novo erro.';
COMMENT ON COLUMN public.supplier_products_raw.last_error IS
  'Último process_errors observado (mantido pelo trigger). Histórico de falha da linha.';

-- <<< END 20260605120100_spr2_images_generated_drop_claimed.sql <<<

-- >>> BEGIN 20260605120200_spr2_motor_quarantine_terminal.sql >>>
-- ============================================================================
-- supplier_products_raw — Refactor v2 (Fase 3/5): Quarentena terminal no motor
-- ----------------------------------------------------------------------------
-- A fila do motor (fn_process_raw_v2) seleciona `status <> 'processed'`, ou
-- seja, reprocessa indefinidamente também linhas 'failed' E 'quarantined'.
-- Com a Fase 1, uma linha que falha 5x recebe status='quarantined' (poison
-- pill). Para que a quarentena seja TERMINAL, o motor deve excluí-la da fila.
--
-- Em vez de reescrever ~200 linhas de plpgsql (risco de divergência), fazemos
-- a substituição EXATA do predicado direto sobre a definição corrente da
-- função, preservando todo o restante byte a byte.
--   `status <> 'processed'`  ->  `status NOT IN ('processed','quarantined')`
-- ============================================================================

DO $migrate$
DECLARE
  v_def    text;
  v_before text := 'status <> ''processed''::supplier_raw_status';
  v_after  text := 'status NOT IN (''processed''::supplier_raw_status, ''quarantined''::supplier_raw_status)';
  v_count  int;
BEGIN
  v_def := pg_get_functiondef('public.fn_process_raw_v2(uuid, integer, boolean)'::regprocedure);

  -- Quantos predicados existem hoje (sanity check)
  v_count := (length(v_def) - length(replace(v_def, v_before, ''))) / length(v_before);
  IF v_count < 1 THEN
    RAISE EXCEPTION 'Predicado de fila não encontrado em fn_process_raw_v2 (achados=%); abortando para não corromper o motor.', v_count;
  END IF;
  RAISE NOTICE 'fn_process_raw_v2: substituindo % ocorrência(s) do predicado de fila.', v_count;

  v_def := replace(v_def, v_before, v_after);
  EXECUTE v_def;
END
$migrate$;

-- <<< END 20260605120200_spr2_motor_quarantine_terminal.sql <<<

-- >>> BEGIN 20260605120300_spr2_history_old_version_and_index_cleanup.sql >>>
-- ============================================================================
-- supplier_products_raw — Refactor v2 (Fase 4/5): Histórico temporal + índices
-- ----------------------------------------------------------------------------
--   * Histórico: hoje a trigger grava em TODO INSERT, gerando _history 1:1 com
--     o bronze (16.508 linhas, 32 MB) sem nenhuma versão real capturada. Passa
--     a registrar apenas a versão SUPERSEDIDA (OLD) quando o content_hash muda.
--     A própria linha bronze é a v1; _history guarda só o que foi substituído
--     (padrão temporal correto, sem duplicar a v1 e sem write-amplification).
--   * idx_spr_reference: 1 MB, ~15 scans. Lookups por supplier_reference já
--     vêm escopados por supplier_id (cobertos por uq_supplier_product_raw).
--   * idx_spr_hist_ref: sinalizado como índice não utilizado pelo advisor.
-- ============================================================================

-- 1) Histórico append-only passa a capturar a versão antiga em UPDATE
CREATE OR REPLACE FUNCTION public.fn_spr_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Captura apenas versões SUPERSEDIDAS (OLD) quando o conteúdo muda.
  -- O INSERT inicial não é duplicado: a própria linha bronze é a v1.
  IF NEW.content_hash IS DISTINCT FROM OLD.content_hash THEN
    INSERT INTO public.supplier_products_raw_history
      (raw_id, supplier_id, supplier_reference, content_hash, raw_data)
    VALUES (OLD.id, OLD.supplier_id, OLD.supplier_reference, OLD.content_hash, OLD.raw_data);
  END IF;
  RETURN NULL;
END;
$function$;

-- Trigger só em UPDATE (o INSERT deixa de duplicar a v1 no histórico)
DROP TRIGGER IF EXISTS trg_spr_history ON public.supplier_products_raw;
CREATE TRIGGER trg_spr_history
  AFTER UPDATE ON public.supplier_products_raw
  FOR EACH ROW EXECUTE FUNCTION public.fn_spr_history();

-- 2) Índices de baixo/zero valor
DROP INDEX IF EXISTS public.idx_spr_reference;
DROP INDEX IF EXISTS public.idx_spr_hist_ref;

-- <<< END 20260605120300_spr2_history_old_version_and_index_cleanup.sql <<<

-- >>> BEGIN 20260605120400_spr2_autovacuum_tuning.sql >>>
-- ============================================================================
-- supplier_products_raw — Refactor v2 (Fase 5/5): Stats e autovacuum
-- ----------------------------------------------------------------------------
-- O planner superestimava ~20% (reltuples ~19.837 vs real 16.508). Dado o
-- churn de status/imagens, deixamos o autoanalyze/autovacuum mais agressivos
-- nesta tabela quente e atualizamos as estatísticas agora.
-- (fillfactor=90 já foi definido no refactor anterior.)
-- ============================================================================

ALTER TABLE public.supplier_products_raw SET (
  autovacuum_analyze_scale_factor = 0.02,
  autovacuum_vacuum_scale_factor  = 0.05
);

ANALYZE public.supplier_products_raw;

-- <<< END 20260605120400_spr2_autovacuum_tuning.sql <<<

-- >>> BEGIN 20260605130000_spr2_fix_motor_quarantine_terminal.sql >>>
-- ============================================================================
-- supplier_products_raw — HOTFIX: Fase 3 (Motor quarentena terminal)
-- ----------------------------------------------------------------------------
-- A Fase 3 (20260605120200) foi aplicada via execute_sql mas não registrada
-- na tabela de migrations, e o predicado do motor NÃO foi substituído:
-- fn_process_raw_v2 continuava com status <> 'processed' (5 ocorrências),
-- incluindo linhas quarentenadas na fila → poison-pill da Fase 1 anulado.
--
-- Este hotfix re-aplica a substituição exata e é registrado corretamente.
-- Verificado por teste E2E com rollback: 5 erros → quarantined; motor exclui.
-- ============================================================================

DO $migrate$
DECLARE
  v_def    text;
  v_before text := 'status <> ''processed''::supplier_raw_status';
  v_after  text := 'status NOT IN (''processed''::supplier_raw_status, ''quarantined''::supplier_raw_status)';
  v_count  int;
BEGIN
  v_def := pg_get_functiondef('public.fn_process_raw_v2(uuid, integer, boolean)'::regprocedure);

  v_count := (length(v_def) - length(replace(v_def, v_before, ''))) / length(v_before);
  IF v_count < 1 THEN
    RAISE NOTICE 'Predicado antigo não encontrado (achados=%) — já aplicado anteriormente. Noop.', v_count;
    RETURN;
  END IF;
  RAISE NOTICE 'fn_process_raw_v2: substituindo % ocorrência(s) do predicado de fila.', v_count;

  v_def := replace(v_def, v_before, v_after);
  EXECUTE v_def;
END
$migrate$;

-- <<< END 20260605130000_spr2_fix_motor_quarantine_terminal.sql <<<

-- >>> BEGIN 20260605130100_spr2_fix_idx_unprocessed_predicate.sql >>>
-- ============================================================================
-- supplier_products_raw — HOTFIX: idx_spr_unprocessed predicado
-- ----------------------------------------------------------------------------
-- O predicado do índice era `status <> 'processed'` (inclui 'quarantined'),
-- mas o motor agora usa `status NOT IN ('processed','quarantined')`.
-- O PostgreSQL pode usar o índice mesmo assim (predicado da query implica o
-- do índice), mas visita linhas quarentenadas desnecessariamente antes de
-- descartá-las. Alinhar os predicados elimina esse overhead latente.
-- ============================================================================

DROP INDEX IF EXISTS public.idx_spr_unprocessed;

CREATE INDEX idx_spr_unprocessed
  ON public.supplier_products_raw (supplier_id, imported_at)
  WHERE status NOT IN ('processed'::supplier_raw_status, 'quarantined'::supplier_raw_status);

-- <<< END 20260605130100_spr2_fix_idx_unprocessed_predicate.sql <<<

-- >>> BEGIN 20260605140000_fix_purge_history_security_and_history_indexes.sql >>>
-- Correções detectadas na auditoria exaustiva pós-refactor:
--
-- 1) fn_purge_spr_history: criada com SECURITY DEFINER mas sem REVOKE do grant
--    padrão PUBLIC/anon → qualquer usuário anônimo podia chamar via REST API
--    (GET /rest/v1/rpc/fn_purge_spr_history?p_keep_days=1) e apagar todo o
--    histórico. Restrita a service_role + postgres.
--
-- 2) supplier_products_raw_history: FK supplier_id sem índice (advisor
--    unindexed_foreign_keys) e captured_at sem índice (penaliza fn_purge_spr_history
--    que filtra WHERE captured_at < ...).

-- 1) Revoga execução pública de fn_purge_spr_history
REVOKE EXECUTE ON FUNCTION public.fn_purge_spr_history(integer) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_purge_spr_history(integer) FROM anon;
REVOKE EXECUTE ON FUNCTION public.fn_purge_spr_history(integer) FROM authenticated;
GRANT  EXECUTE ON FUNCTION public.fn_purge_spr_history(integer) TO service_role;

-- 2) Índice no FK supplier_id (JOIN frequente com suppliers)
CREATE INDEX IF NOT EXISTS idx_spr_hist_supplier
  ON public.supplier_products_raw_history (supplier_id);

-- 3) Índice em captured_at para que fn_purge_spr_history e queries de auditoria
--    não façam seq scan em tabela de crescimento ilimitado
CREATE INDEX IF NOT EXISTS idx_spr_hist_captured_at
  ON public.supplier_products_raw_history (captured_at);

-- <<< END 20260605140000_fix_purge_history_security_and_history_indexes.sql <<<

-- >>> BEGIN 20260605141000_fix_spr_before_write_search_path.sql >>>
-- fn_spr_before_write usa encode(digest(...),'sha256') do pgcrypto, mas a extensão
-- pgcrypto está no schema 'extensions' (padrão Supabase). Com SET search_path TO 'public'
-- a função não enxerga digest() → falha em qualquer UPDATE na tabela.
--
-- Todos os 16.509 content_hash existentes já são sha256 (64 chars); mudar para md5
-- tornaria todos os hashes incomparáveis → qualquer UPDATE dispararia history desnecessário.
-- Solução: incluir 'extensions' no search_path (read-only, só contém funções de extensão).

ALTER FUNCTION public.fn_spr_before_write()
  SET search_path TO 'public', 'extensions';

-- <<< END 20260605141000_fix_spr_before_write_search_path.sql <<<

