-- >>> BEGIN 20260605155900_fix_images_status_consistency.sql >>>

-- ════════════════════════════════════════════════════════════════
-- Fix: images_status consistency — raw rows that point to products
-- which already have images in product_images should be marked as
-- images_status='processed'. The image pipeline ran but forgot to
-- update the flag. Safe backfill: only touches rows where
-- status='processed' AND images_status='pending' AND product has images.
-- ════════════════════════════════════════════════════════════════

UPDATE public.supplier_products_raw spr
SET images_status = 'processed'
WHERE spr.status = 'processed'
  AND spr.images_status = 'pending'
  AND spr.product_id IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM public.product_images pi
    WHERE pi.product_id = spr.product_id
  );

-- <<< END 20260605155900_fix_images_status_consistency.sql <<<

-- >>> BEGIN 20260605160000_silver_unify_01_fn_standardize_supplier.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 1/4
-- Orquestrador Bronze → Silver (de-para) em lote, por fornecedor.
-- ════════════════════════════════════════════════════════════════
-- Espelha fn_promote_supplier (Silver → Gold), fechando o par simétrico
-- do pipeline de 3 fases:
--   Bronze  : supplier_products_raw (status='pending')
--   Silver  : produtos_padronizacao(+_variantes)  ← ESTA função
--   Gold    : products / product_variants / variant_supplier_sources
--
-- Ordem obrigatória: variantes ANTES do pai. fn_standardize_parent escolhe
-- a raw representante a partir de produtos_padronizacao_variantes, logo as
-- variantes precisam já existir no staging quando o pai é padronizado.
--
-- Idempotente: as funções-folha (fn_standardize_variant / _raw) usam UPSERT.
-- Concorrência: advisory xact lock por fornecedor evita execuções sobrepostas
-- do cron processarem o mesmo fornecedor duas vezes.
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_standardize_supplier(
    p_supplier_id uuid,
    p_limit       integer DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_raw         RECORD;
  v_par         RECORD;
  v_vres        jsonb;
  v_pres        jsonb;
  v_variants    integer := 0;
  v_parents     integer := 0;
  v_erros       integer := 0;
  v_err_amostra jsonb   := '[]'::jsonb;
  v_touched     text[]  := ARRAY[]::text[];
  v_t0          timestamptz := clock_timestamp();
BEGIN
  -- Segurança: bloqueia chamada direta por não-admin (cron roda sem auth.uid()).
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;

  -- Evita execuções concorrentes para o mesmo fornecedor (cron sobreposto).
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_standardize_supplier:'||p_supplier_id::text)::bigint) THEN
    RETURN jsonb_build_object('success', true, 'skipped', 'lock_ocupado',
                              'supplier_id', p_supplier_id);
  END IF;

  PERFORM set_config('app.write_source', 'pipeline', true);

  -- ── 1) Bronze → Silver (variantes): cada raw pendente do fornecedor ──
  FOR v_raw IN
      SELECT id, supplier_reference
      FROM public.supplier_products_raw
      WHERE supplier_id = p_supplier_id
        AND status = 'pending'
      ORDER BY imported_at NULLS LAST
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      v_vres := public.fn_standardize_variant(v_raw.id);
      IF NOT COALESCE((v_vres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'variante_falhou:%', COALESCE(v_vres->>'error', 'desconhecido');
      END IF;
      v_variants := v_variants + 1;
      v_touched  := array_append(v_touched, COALESCE(v_vres->>'parent', ''));
    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra
          || jsonb_build_object('raw_id', v_raw.id, 'stage', 'variant', 'erro', SQLERRM);
      END IF;
    END;
  END LOOP;

  -- ── 2) Bronze → Silver (produto pai): cada parent distinto tocado ──
  FOR v_par IN
      SELECT DISTINCT parent_reference
      FROM public.produtos_padronizacao_variantes
      WHERE supplier_id = p_supplier_id
        AND parent_reference = ANY(v_touched)
        AND NULLIF(parent_reference, '') IS NOT NULL
  LOOP
    BEGIN
      v_pres := public.fn_standardize_parent(p_supplier_id, v_par.parent_reference);
      IF NOT COALESCE((v_pres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'pai_falhou:%', COALESCE(v_pres->>'error', 'desconhecido');
      END IF;
      v_parents := v_parents + 1;
    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra
          || jsonb_build_object('parent', v_par.parent_reference, 'stage', 'parent', 'erro', SQLERRM);
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true, 'supplier_id', p_supplier_id,
    'variantes_padronizadas', v_variants,
    'pais_padronizados', v_parents,
    'erros', v_erros, 'amostra_erros', v_err_amostra,
    'segundos', round(extract(epoch FROM clock_timestamp() - v_t0)::numeric, 1));
END;
$function$;

COMMENT ON FUNCTION public.fn_standardize_supplier(uuid, integer) IS
  'Pipeline Medallion (Fase 1→2): Bronze→Silver de-para em lote por fornecedor. '
  'Padroniza variantes (fn_standardize_variant) e depois os pais (fn_standardize_parent). '
  'Par simétrico de fn_promote_supplier (Fase 2→3). Idempotente; advisory lock por fornecedor.';

-- <<< END 20260605160000_silver_unify_01_fn_standardize_supplier.sql <<<

-- >>> BEGIN 20260605160100_silver_unify_02_rewire_process_pending_batches.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 2/4
-- Religa o cron de ingestão para o pipeline de 3 fases.
-- ════════════════════════════════════════════════════════════════
-- ANTES (atalho que VIOLAVA as 3 fases — Bronze→Gold direto, só SPOT):
--   process_pending_batches() → fn_process_raw_v2(SPOT, 1000, true)
--
-- DEPOIS (Medallion completo, todos os fornecedores auto_sync):
--   process_pending_batches()
--     └─ por fornecedor com raw 'pending':
--          fn_standardize_supplier(...)  -- Fase 1→2  Bronze → Silver (de-para)
--          fn_promote_supplier(...)      -- Fase 2→3  Silver → Gold
--
-- O cron 'process-pending-products' (*/5 * * * *) chama esta função;
-- a assinatura e o tipo de retorno são preservados (sem mudança no job).
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.process_pending_batches()
RETURNS TABLE(batch_id uuid, products_processed integer, status text)
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_sup  RECORD;
  v_std  jsonb;
  v_prom jsonb;
BEGIN
  FOR v_sup IN
      SELECT ss.supplier_id
      FROM public.supplier_settings ss
      WHERE COALESCE(ss.auto_sync_enabled, false) = true
        AND EXISTS (
          SELECT 1 FROM public.supplier_products_raw r
          WHERE r.supplier_id = ss.supplier_id AND r.status = 'pending'
        )
  LOOP
      -- Fase 1→2: Bronze → Silver (de-para)
      v_std  := public.fn_standardize_supplier(v_sup.supplier_id, 1000);
      -- Fase 2→3: Silver → Gold (promoção soberana: produto + variantes + sources)
      v_prom := public.fn_promote_supplier(v_sup.supplier_id, NULL);

      batch_id           := NULL::uuid;
      products_processed := COALESCE((v_prom->>'pais_promovidos')::integer, 0);
      status := CASE
                  WHEN COALESCE((v_std->>'erros')::int, 0) = 0
                   AND COALESCE((v_prom->>'erros')::int, 0) = 0 THEN 'SUCCESS'
                  ELSE 'PARTIAL'
                END;
      RETURN NEXT;
  END LOOP;
  RETURN;
END;
$function$;

COMMENT ON FUNCTION public.process_pending_batches() IS
  'Cron de ingestão (*/5). Pipeline Medallion 3 fases por fornecedor auto_sync: '
  'fn_standardize_supplier (Bronze→Silver) + fn_promote_supplier (Silver→Gold). '
  'Substitui o atalho fn_process_raw_v2 (Bronze→Gold direto). 2026-06-05.';

-- <<< END 20260605160100_silver_unify_02_rewire_process_pending_batches.sql <<<

-- >>> BEGIN 20260605160200_silver_unify_03_redirect_direct_to_gold.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 3/4
-- Neutraliza os atalhos Bronze→Gold (violavam as 3 fases).
-- ════════════════════════════════════════════════════════════════
-- Chamadores verificados ao vivo:
--   fn_process_raw_v2            ← só fn_dryrun_raw_v2 (ferramenta dry-run)
--   process_supplier_product     ← só process_supplier_products_batch
--   process_supplier_products_batch ← nenhum chamador externo
-- Assinaturas preservadas (CREATE OR REPLACE) para não quebrar nada.
-- ════════════════════════════════════════════════════════════════

-- (1) Motor v2: redireciona para o pipeline de 3 fases (deixa de gravar Gold direto)
CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(
    p_supplier_id uuid,
    p_batch_size  integer DEFAULT 100,
    p_bulk_mode   boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE v_std jsonb; v_prom jsonb;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;
  -- REDIRECIONADO 2026-06-05: não grava mais Bronze→Gold direto.
  v_std  := public.fn_standardize_supplier(p_supplier_id, p_batch_size);  -- Bronze→Silver
  v_prom := public.fn_promote_supplier(p_supplier_id, NULL);              -- Silver→Gold
  RETURN jsonb_build_object(
    'success', true, 'redirected', true,
    'pipeline', 'fn_standardize_supplier + fn_promote_supplier',
    'supplier_id', p_supplier_id,
    'parents_processed',  COALESCE((v_prom->>'pais_promovidos')::int, 0),
    'variants_processed', COALESCE((v_prom->>'variantes_promovidas')::int, 0),
    'standardize', v_std, 'promote', v_prom);
END;
$function$;

COMMENT ON FUNCTION public.fn_process_raw_v2(uuid, integer, boolean) IS
  'DEPRECATED/REDIRECIONADA 2026-06-05: delega ao pipeline Medallion de 3 fases '
  '(fn_standardize_supplier + fn_promote_supplier). Não grava mais Bronze->Gold direto.';

-- (2) Writer ad-hoc Bronze→Gold: neutralizado (sem escrita no Gold)
CREATE OR REPLACE FUNCTION public.process_supplier_product(
    p_supplier_id uuid,
    p_raw_data jsonb,
    p_supplier_reference text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- DEPRECATED 2026-06-05: gravava Bronze->Gold direto (pulava a Silver). Neutralizada.
  RETURN jsonb_build_object(
    'success', false, 'deprecated', true,
    'error', 'process_supplier_product descontinuada: use o pipeline Medallion '
             '(supplier_products_raw -> fn_standardize_supplier -> fn_promote_supplier)',
    'supplier_id', p_supplier_id, 'supplier_reference', p_supplier_reference);
END;
$function$;

COMMENT ON FUNCTION public.process_supplier_product(uuid, jsonb, text) IS
  'DEPRECATED 2026-06-05: writer Bronze->Gold direto neutralizado. Candidata a DROP em follow-up.';

-- (3) Batch legado: redireciona para o pipeline de 3 fases (preserva o shape de retorno)
CREATE OR REPLACE FUNCTION public.process_supplier_products_batch(
    p_supplier_id uuid,
    p_limit integer DEFAULT 100
)
RETURNS TABLE(staging_id uuid, supplier_reference text, success boolean,
              product_id uuid, variants_created integer, error_message text,
              processed_at timestamp with time zone)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE v_std jsonb; v_prom jsonb;
BEGIN
  -- REDIRECIONADO 2026-06-05: não usa mais process_supplier_product (Bronze->Gold direto).
  v_std  := public.fn_standardize_supplier(p_supplier_id, p_limit);  -- Bronze→Silver
  v_prom := public.fn_promote_supplier(p_supplier_id, NULL);         -- Silver→Gold

  staging_id         := NULL::uuid;
  supplier_reference := NULL::text;
  success            := COALESCE((v_prom->>'success')::boolean, false)
                        AND COALESCE((v_std->>'erros')::int, 0) = 0;
  product_id         := NULL::uuid;
  variants_created   := COALESCE((v_prom->>'variantes_promovidas')::integer, 0);
  error_message      := CASE WHEN success THEN NULL
                             ELSE 'erros no pipeline; ver fn_standardize_supplier/fn_promote_supplier' END;
  processed_at       := now();
  RETURN NEXT;
END;
$function$;

COMMENT ON FUNCTION public.process_supplier_products_batch(uuid, integer) IS
  'DEPRECATED/REDIRECIONADA 2026-06-05: delega ao pipeline Medallion 3 fases. Candidata a DROP em follow-up.';

-- <<< END 20260605160200_silver_unify_03_redirect_direct_to_gold.sql <<<

-- >>> BEGIN 20260605160300_silver_unify_04_deprecate_legacy_silver.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 4/4
-- Aposenta o Silver LEGADO (medallion 001) — sem dropar.
-- ════════════════════════════════════════════════════════════════
-- Verificado ao vivo: 12 funções legadas SEM chamadores; tabelas silver_*
-- SEM views/MVs dependentes. Substituídas pela Silver de-para oficial
-- (produtos_padronizacao + _variantes via fn_standardize_supplier /
-- fn_promote_supplier). Mantidas para auditoria; candidatas a DROP em follow-up.
-- COMMENT é não-disruptivo (apenas metadados).
-- ════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_msg_fn text := 'DEPRECATED 2026-06-05: Silver legado (medallion 001). '
                || 'Substituido pelo pipeline de-para oficial (produtos_padronizacao via '
                || 'fn_standardize_supplier + fn_promote_supplier). Sem chamadores. Candidato a DROP em follow-up.';
  v_msg_tb text := 'DEPRECATED 2026-06-05: tabela do Silver legado (medallion 001). '
                || 'Fonte canonica da Silver passou a ser produtos_padronizacao(+_variantes). '
                || 'Mantida para auditoria; candidata a DROP em follow-up.';
BEGIN
  -- Funções legadas (Bronze→Silver hardcoded e Silver→Gold legado)
  EXECUTE format('COMMENT ON FUNCTION public.fn_spot_to_silver(uuid) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_xbz_to_silver(uuid) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_asia_to_silver(uuid) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_sm_to_silver(uuid) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_spot_batch_to_silver(integer) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_xbz_batch_to_silver(integer) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_asia_batch_to_silver(integer) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_sm_batch_to_silver(integer) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_silver_to_gold(uuid) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_silver_batch_to_gold(text, integer) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_bronze_to_silver_all(integer) IS %L', v_msg_fn);
  EXECUTE format('COMMENT ON FUNCTION public.fn_normalize_silver_all() IS %L', v_msg_fn);

  -- Tabelas do Silver legado
  EXECUTE format('COMMENT ON TABLE public.silver_products IS %L', v_msg_tb);
  EXECUTE format('COMMENT ON TABLE public.silver_variants IS %L', v_msg_tb);
  EXECUTE format('COMMENT ON TABLE public.silver_print_areas IS %L', v_msg_tb);
  EXECUTE format('COMMENT ON TABLE public.silver_images_queue IS %L', v_msg_tb);
END $$;

-- Documenta a Silver oficial (fonte canônica)
COMMENT ON TABLE public.produtos_padronizacao IS
  'SILVER oficial (Medallion). Bronze->Silver via fn_standardize_supplier (de-para supplier_field_mappings + fn_apply_transform); Silver->Gold via fn_promote_supplier. Fonte canonica de padronizacao de produtos.';
COMMENT ON TABLE public.produtos_padronizacao_variantes IS
  'SILVER oficial (Medallion) — variantes. Staging raw_id->pad_id->variant_id. Bronze->Silver via fn_standardize_variant; Silver->Gold via fn_promote_variants_of_parent.';

-- <<< END 20260605160300_silver_unify_04_deprecate_legacy_silver.sql <<<

-- >>> BEGIN 20260605160400_silver_unify_05_promote_marks_raw_processed.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 5 (correção de integridade 3-fases)
-- fn_promote_variants_of_parent passa a marcar a RAW como 'processed'
-- quando a variante chega ao Gold.
-- ════════════════════════════════════════════════════════════════
-- PORQUÊ: no modelo de 3 fases, cada raw (1 SKU = 1 raw nos fornecedores
-- atuais) só está "concluída" quando sua variante é promovida ao Gold.
-- fn_promote_padronizacao só marca a raw REPRESENTANTE do grupo-pai; as
-- demais raws (uma por variante) ficavam 'pending' e seriam reprocessadas
-- indefinidamente pelo cron (a fila nunca drenava). O motor antigo
-- (fn_process_raw_v2) marcava cada raw individualmente — esta função
-- restaura essa garantia dentro do pipeline Silver.
--
-- Mudança cirúrgica: + UPDATE supplier_products_raw no laço de promoção.
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_promote_variants_of_parent(
    p_supplier_id uuid,
    p_parent_reference text
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_pid uuid; v_org uuid; pv RECORD; v_vid uuid; v_count int := 0; v_attrs jsonb;
  v_existing_pid uuid;
BEGIN
  PERFORM set_config('app.write_source','pipeline',true);
  SELECT id, organization_id INTO v_pid, v_org FROM public.products
  WHERE supplier_id=p_supplier_id AND supplier_reference=p_parent_reference;
  IF v_pid IS NULL THEN RETURN jsonb_build_object('success',false,'error','produto_pai_nao_promovido','parent',p_parent_reference); END IF;

  FOR pv IN
    SELECT * FROM public.produtos_padronizacao_variantes
    WHERE supplier_id=p_supplier_id AND parent_reference=p_parent_reference AND status='standardized'
  LOOP
    v_attrs := jsonb_strip_nulls(jsonb_build_object('cor', pv.color_name, 'codigo_cor', pv.color_code, 'hex', pv.color_hex));

    -- idempotência por sku GLOBAL (sku é UNIQUE em product_variants); fallback (product_id, supplier_sku)
    SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants WHERE sku = pv.sku;
    IF v_vid IS NULL THEN
      SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants
      WHERE product_id=v_pid AND supplier_sku=pv.supplier_sku;
    END IF;

    IF v_vid IS NULL THEN
      INSERT INTO public.product_variants (product_id, sku, supplier_sku, name, attributes, color_name, color_code, color_hex, color_id, stock_quantity, is_active, last_sync_at, last_sync_supplier_id)
      VALUES (v_pid, pv.sku, pv.supplier_sku, COALESCE(pv.color_name, pv.sku), v_attrs,
              pv.color_name, pv.color_code, pv.color_hex, pv.color_id,
              COALESCE(pv.stock_quantity,0), COALESCE(pv.is_active,true), now(), p_supplier_id)
      ON CONFLICT (sku) DO UPDATE SET
        supplier_sku = EXCLUDED.supplier_sku,
        attributes   = COALESCE(public.product_variants.attributes,'{}'::jsonb) || EXCLUDED.attributes,
        color_name   = COALESCE(EXCLUDED.color_name, public.product_variants.color_name),
        color_code   = COALESCE(EXCLUDED.color_code, public.product_variants.color_code),
        color_hex    = COALESCE(EXCLUDED.color_hex, public.product_variants.color_hex),
        color_id     = COALESCE(EXCLUDED.color_id, public.product_variants.color_id),
        stock_quantity = COALESCE(EXCLUDED.stock_quantity, public.product_variants.stock_quantity),
        last_sync_at = now(), last_sync_supplier_id = EXCLUDED.last_sync_supplier_id
      RETURNING id INTO v_vid;
    ELSE
      UPDATE public.product_variants SET
        attributes = COALESCE(attributes,'{}'::jsonb) || v_attrs,
        color_name=COALESCE(pv.color_name,color_name), color_code=COALESCE(pv.color_code,color_code),
        color_hex=COALESCE(pv.color_hex,color_hex), color_id=COALESCE(pv.color_id,color_id),
        stock_quantity=COALESCE(pv.stock_quantity,stock_quantity), last_sync_at=now(), last_sync_supplier_id=p_supplier_id
      WHERE id=v_vid;
    END IF;

    IF pv.cost_price IS NOT NULL THEN
      INSERT INTO public.variant_supplier_sources (organization_id, variant_id, supplier_id, cost_price, supplier_sku, supplier_color_code, supplier_color_name, is_active, source, last_synced_at)
      VALUES (v_org, v_vid, p_supplier_id, pv.cost_price, pv.supplier_sku, pv.color_code, pv.color_name, true, 'silver', now())
      ON CONFLICT (variant_id, supplier_id) DO UPDATE SET
        cost_price          = EXCLUDED.cost_price,
        supplier_sku        = EXCLUDED.supplier_sku,
        supplier_color_code = EXCLUDED.supplier_color_code,
        supplier_color_name = EXCLUDED.supplier_color_name,
        is_active           = EXCLUDED.is_active,
        source              = EXCLUDED.source,
        last_synced_at      = EXCLUDED.last_synced_at;
    END IF;

    UPDATE public.produtos_padronizacao_variantes SET status='promoted', variant_id=v_vid, updated_at=now() WHERE id=pv.id;

    -- 3-fases: a raw desta variante está concluída ao chegar no Gold.
    IF pv.raw_id IS NOT NULL THEN
      UPDATE public.supplier_products_raw
         SET status='processed', processed_at=now(), product_id=v_pid, variant_id=v_vid
       WHERE id=pv.raw_id AND status <> 'processed';
    END IF;

    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('success',true,'product_id',v_pid,'variantes_promovidas',v_count);
END;
$function$;

-- <<< END 20260605160400_silver_unify_05_promote_marks_raw_processed.sql <<<

-- >>> BEGIN 20260605160500_silver_unify_06_lockdown_standardize_supplier_grants.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 6 (segurança)
-- Tranca a execução de fn_standardize_supplier (SECURITY DEFINER).
-- ════════════════════════════════════════════════════════════════
-- Advisor: anon_/authenticated_security_definer_function_executable.
-- fn_standardize_supplier é SECURITY DEFINER (bypassa RLS) e nasceu com
-- EXECUTE para PUBLIC. O guard interno usa auth.uid() IS NOT NULL, que NÃO
-- barra o papel `anon` (uid NULL). Replicamos a ACL do motor fn_process_raw_v2:
-- somente postgres + service_role (o cron roda como service_role/postgres).
-- ════════════════════════════════════════════════════════════════

REVOKE ALL ON FUNCTION public.fn_standardize_supplier(uuid, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_standardize_supplier(uuid, integer) FROM anon;
REVOKE ALL ON FUNCTION public.fn_standardize_supplier(uuid, integer) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.fn_standardize_supplier(uuid, integer) TO postgres;
GRANT EXECUTE ON FUNCTION public.fn_standardize_supplier(uuid, integer) TO service_role;

-- <<< END 20260605160500_silver_unify_06_lockdown_standardize_supplier_grants.sql <<<

-- >>> BEGIN 20260605161000_fix_security_rls_and_search_paths.sql >>>

-- ════════════════════════════════════════════════════════════════
-- Security fixes — resolves 4 ERROR + 5 WARN advisors:
--   ERROR: RLS disabled on produtos_padronizacao_variantes
--   ERROR: RLS disabled on _backup_produtos_padronizacao_20260604
--   WARN (×5): mutable search_path on utility functions
-- ════════════════════════════════════════════════════════════════

-- ── 1. RLS on produtos_padronizacao_variantes ────────────────
ALTER TABLE public.produtos_padronizacao_variantes ENABLE ROW LEVEL SECURITY;

CREATE POLICY pad_var_authenticated_read
  ON public.produtos_padronizacao_variantes
  FOR SELECT TO authenticated
  USING (true);

CREATE POLICY pad_var_service_all
  ON public.produtos_padronizacao_variantes
  FOR ALL TO service_role
  USING (true) WITH CHECK (true);

-- ── 2. RLS on backup table (admin/service only) ──────────────
ALTER TABLE public._backup_produtos_padronizacao_20260604 ENABLE ROW LEVEL SECURITY;

CREATE POLICY backup_pad_service_only
  ON public._backup_produtos_padronizacao_20260604
  FOR ALL TO service_role
  USING (true) WITH CHECK (true);

-- ── 3. Fix mutable search_path — fn_log_price_change ────────
CREATE OR REPLACE FUNCTION public.fn_log_price_change()
RETURNS trigger LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  RETURN NEW;
END;
$function$;

-- ── 4. Fix mutable search_path — fn_safe_int ────────────────
CREATE OR REPLACE FUNCTION public.fn_safe_int(p text)
RETURNS integer LANGUAGE plpgsql IMMUTABLE
SET search_path TO 'public'
AS $function$
DECLARE v numeric;
BEGIN
  IF p IS NULL OR TRIM(p)='' THEN RETURN NULL; END IF;
  v := replace(TRIM(p), ',', '.')::numeric;
  RETURN trunc(v)::integer;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END;
$function$;

-- ── 5. Fix mutable search_path — fn_safe_num ────────────────
CREATE OR REPLACE FUNCTION public.fn_safe_num(p text)
RETURNS numeric LANGUAGE plpgsql IMMUTABLE
SET search_path TO 'public'
AS $function$
BEGIN
  IF p IS NULL OR TRIM(p)='' THEN RETURN NULL; END IF;
  RETURN replace(TRIM(p), ',', '.')::numeric;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END;
$function$;

-- ── 6. Fix mutable search_path — fn_derive_parent_ref ───────
CREATE OR REPLACE FUNCTION public.fn_derive_parent_ref(
  p_supplier_id uuid, p_variant_ref text, p_raw jsonb
)
RETURNS text LANGUAGE plpgsql IMMUTABLE
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_variant_ref IS NULL OR TRIM(p_variant_ref) = '' THEN
    RETURN NULL;
  END IF;

  -- Spot: referência-pai explícita no raw
  IF p_supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0' THEN
    RETURN COALESCE(NULLIF(TRIM(p_raw->>'ProdReference'), ''), p_variant_ref);
  END IF;

  -- XBZ: família explícita (CodigoAmigavel) — autoritativa da API
  IF p_supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900' THEN
    RETURN COALESCE(NULLIF(TRIM(p_raw->>'CodigoAmigavel'), ''), regexp_replace(p_variant_ref, '-[^-]*$', ''));
  END IF;

  -- Asia: reconstrução heurística do pai (referencia do pai perdida na ingestão)
  IF p_supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118' THEN
    IF position('-' IN p_variant_ref) > 0 THEN
      RETURN regexp_replace(p_variant_ref, '-[^-]*$', '');
    ELSE
      RETURN p_variant_ref || 'P';
    END IF;
  END IF;

  -- Só Marcas: 1:1 — o código é o produto inteiro (hífen NÃO separa cor)
  IF p_supplier_id = '841cd690-210a-422a-908c-7676828db272' THEN
    RETURN p_variant_ref;
  END IF;

  -- demais: parte antes do ÚLTIMO hífen; sem hífen = é o próprio pai
  IF position('-' IN p_variant_ref) > 0 THEN
    RETURN regexp_replace(p_variant_ref, '-[^-]*$', '');
  END IF;
  RETURN p_variant_ref;
END;
$function$;

-- ── 7. Fix mutable search_path — fn_extract_color_from_title
CREATE OR REPLACE FUNCTION public.fn_extract_color_from_title(p_titulo text)
RETURNS text LANGUAGE plpgsql IMMUTABLE
SET search_path TO 'public'
AS $function$
DECLARE
  v_tok text;
  v_up  text;
BEGIN
  IF p_titulo IS NULL OR TRIM(p_titulo)='' THEN RETURN NULL; END IF;
  v_up := UPPER(p_titulo);

  SELECT m[1] INTO v_tok FROM regexp_matches(v_up,
    '\y(PRET[AO]|BRANC[AO]|AZUL|VERMELH[AO]|VERDE|CINZA|AMAREL[AO]|ROSA|ROX[AO]|LARANJA|BEGE|MARROM|DOURAD[AO]|PRATEAD[AO]|PRATA|NATURAL|BAMBU|MADEIRA|INOX|VINHO|CAQUI|NUDE|TURQUESA|LIL[AÁ]S|FUM[EÊ]|TRANSPARENTE|GRAFITE|CHUMBO|CORAL|MOSTARDA)\y'
  ) m LIMIT 1;

  IF v_tok IS NULL THEN RETURN NULL; END IF;

  RETURN CASE
    WHEN v_tok LIKE 'PRET%'    THEN 'Preto'
    WHEN v_tok LIKE 'BRANC%'   THEN 'Branco'
    WHEN v_tok LIKE 'VERMELH%' THEN 'Vermelho'
    WHEN v_tok LIKE 'AMAREL%'  THEN 'Amarelo'
    WHEN v_tok LIKE 'ROX%'     THEN 'Roxo'
    WHEN v_tok LIKE 'DOURAD%'  THEN 'Dourado'
    WHEN v_tok LIKE 'PRATEAD%' THEN 'Prata'
    WHEN v_tok='AZUL'          THEN 'Azul'
    WHEN v_tok='VERDE'         THEN 'Verde'
    WHEN v_tok='CINZA'         THEN 'Cinza'
    WHEN v_tok='ROSA'          THEN 'Rosa'
    WHEN v_tok='LARANJA'       THEN 'Laranja'
    WHEN v_tok='BEGE'          THEN 'Bege'
    WHEN v_tok='MARROM'        THEN 'Marrom'
    WHEN v_tok='PRATA'         THEN 'Prata'
    WHEN v_tok='NATURAL'       THEN 'Natural'
    WHEN v_tok='BAMBU'         THEN 'Bambu'
    WHEN v_tok='MADEIRA'       THEN 'Madeira'
    WHEN v_tok='INOX'          THEN 'Inox'
    WHEN v_tok='VINHO'         THEN 'Vinho'
    WHEN v_tok='CAQUI'         THEN 'Caqui'
    WHEN v_tok='NUDE'          THEN 'Nude'
    WHEN v_tok='TURQUESA'      THEN 'Turquesa'
    WHEN v_tok LIKE 'LIL%'     THEN 'Lilás'
    WHEN v_tok LIKE 'FUM%'     THEN 'Fumê'
    WHEN v_tok='TRANSPARENTE'  THEN 'Transparente'
    WHEN v_tok='GRAFITE'       THEN 'Grafite'
    WHEN v_tok='CHUMBO'        THEN 'Chumbo'
    WHEN v_tok='CORAL'         THEN 'Coral'
    WHEN v_tok='MOSTARDA'      THEN 'Mostarda'
    ELSE initcap(v_tok)
  END;
END;
$function$;

