-- >>> BEGIN 20260605170050_grant_table_privileges_rls_hardened_tables.sql >>>
-- =============================================================================
-- GRANTs de nivel de tabela para as tabelas endurecidas em 20260605100708.
-- =============================================================================
-- O Postgres checa privilegios de TABELA antes das policies RLS. As tabelas
-- abaixo foram criadas DEPOIS das migrations "GRANT ... ON ALL TABLES" amplas,
-- entao aqueles grants nao as alcancam, e nao ha default privileges/GRANT
-- posterior para elas no repo. Resultado num replay limpo: "permission denied"
-- apesar das policies (authenticated SELECT / service_role ALL).
--
-- Esta migration concede explicitamente os privilegios que as policies ja
-- assumem. Apenas ADITIVO e idempotente: na prod (onde os grants ja existem via
-- default privileges) e no-op; num replay do repo, fecha o gap. Nada e revogado,
-- entao o hardening de 20260605100708 (que removeu escrita de authenticated e
-- acesso de anon) permanece intacto. anon nao recebe nada aqui de proposito.

-- mcp_sessions: contrato pos-hardening = service_role apenas.
GRANT ALL ON TABLE public.mcp_sessions TO service_role;

-- produtos_padronizacao (silver): authenticated le; service_role escreve.
GRANT SELECT ON TABLE public.produtos_padronizacao TO authenticated;
GRANT ALL    ON TABLE public.produtos_padronizacao TO service_role;

-- product_physical: authenticated le; service_role escreve.
GRANT SELECT ON TABLE public.product_physical TO authenticated;
GRANT ALL    ON TABLE public.product_physical TO service_role;

-- supplier_price_tiers: authenticated le; service_role escreve.
GRANT SELECT ON TABLE public.supplier_price_tiers TO authenticated;
GRANT ALL    ON TABLE public.supplier_price_tiers TO service_role;

-- <<< END 20260605170050_grant_table_privileges_rls_hardened_tables.sql <<<

-- >>> BEGIN 20260605170100_fix_fn_promote_padronizacao_clear_process_errors.sql >>>
-- fn_promote_padronizacao: limpar process_errors ao marcar o raw como processed.
-- A CHECK chk_spr_no_processed_with_errors (20260605001811) proibe status
-- 'processed' com process_errors preenchido. Esta funcao marcava o raw como
-- 'processed' SEM limpar process_errors; para uma linha raw que falhou antes
-- (carga de erro residual) e depois e re-padronizada/promovida (o caminho
-- dry-run re-standardiza raw independente do status), a promocao abortava no
-- UPDATE final do raw por violar a constraint.
-- Forward fix sobre 20260605110500 (sem editar a migration anterior): adiciona
-- process_errors = NULL ao SET, igual ao que o motor raw v2 ja faz.
CREATE OR REPLACE FUNCTION public.fn_promote_padronizacao(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  s         public.produtos_padronizacao%ROWTYPE;
  v_pid     uuid;
  v_org     uuid;
  v_locked  text[];
  v_is_new  boolean := false;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  PERFORM set_config('app.write_source', 'pipeline', true);

  SELECT id, locked_fields INTO v_pid, v_locked
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, active, is_active, product_type)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name), COALESCE(s.name,'Produto '||s.supplier_reference),
            COALESCE(s.is_active, true), COALESCE(s.is_active, true), 'product')
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  UPDATE public.products p SET
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(s.name, p.name) END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description, p.description) END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description, p.short_description) END,
    cost_price         = CASE WHEN 'cost_price'         = ANY(v_locked) THEN p.cost_price         ELSE COALESCE(s.cost_price, p.cost_price) END,
    suggested_price    = CASE WHEN 'suggested_price'    = ANY(v_locked) THEN p.suggested_price    ELSE COALESCE(s.suggested_price, p.suggested_price) END,
    stock_quantity     = CASE WHEN 'stock_quantity'     = ANY(v_locked) THEN p.stock_quantity     ELSE COALESCE(s.stock_quantity, p.stock_quantity) END,
    primary_image_url  = CASE WHEN 'primary_image_url'  = ANY(v_locked) THEN p.primary_image_url  ELSE COALESCE(s.primary_image_url, p.primary_image_url) END,
    images             = CASE WHEN 'images'             = ANY(v_locked) THEN p.images             ELSE COALESCE(s.images, p.images) END,
    ncm_code           = CASE WHEN 'ncm_code'           = ANY(v_locked) THEN p.ncm_code           ELSE COALESCE(s.ncm_code, p.ncm_code) END,
    weight_g           = CASE WHEN 'weight_g'           = ANY(v_locked) THEN p.weight_g           ELSE COALESCE(s.weight_g, p.weight_g) END,
    height_cm          = CASE WHEN 'height_cm'          = ANY(v_locked) THEN p.height_cm          ELSE COALESCE(s.height_cm, p.height_cm) END,
    width_cm           = CASE WHEN 'width_cm'           = ANY(v_locked) THEN p.width_cm           ELSE COALESCE(s.width_cm, p.width_cm) END,
    length_cm          = CASE WHEN 'length_cm'          = ANY(v_locked) THEN p.length_cm          ELSE COALESCE(s.length_cm, p.length_cm) END,
    dimensions_display = CASE WHEN 'dimensions_display' = ANY(v_locked) THEN p.dimensions_display ELSE COALESCE(s.dimensions_display, p.dimensions_display) END,
    box_length_cm      = CASE WHEN 'box_length_cm'      = ANY(v_locked) THEN p.box_length_cm      ELSE COALESCE(s.box_length_cm, p.box_length_cm) END,
    box_width_cm       = CASE WHEN 'box_width_cm'       = ANY(v_locked) THEN p.box_width_cm       ELSE COALESCE(s.box_width_cm, p.box_width_cm) END,
    box_height_cm      = CASE WHEN 'box_height_cm'      = ANY(v_locked) THEN p.box_height_cm      ELSE COALESCE(s.box_height_cm, p.box_height_cm) END,
    box_weight_kg      = CASE WHEN 'box_weight_kg'      = ANY(v_locked) THEN p.box_weight_kg      ELSE COALESCE(s.box_weight_kg, p.box_weight_kg) END,
    box_volume_cm3     = CASE WHEN 'box_volume_cm3'     = ANY(v_locked) THEN p.box_volume_cm3     ELSE COALESCE(s.box_volume_cm3, p.box_volume_cm3) END,
    box_quantity       = CASE WHEN 'box_quantity'       = ANY(v_locked) THEN p.box_quantity       ELSE COALESCE(s.box_quantity, p.box_quantity) END,
    box_inner_quantity = CASE WHEN 'box_inner_quantity' = ANY(v_locked) THEN p.box_inner_quantity ELSE COALESCE(s.box_inner_quantity, p.box_inner_quantity) END,
    brand              = CASE WHEN 'brand'              = ANY(v_locked) THEN p.brand              ELSE COALESCE(s.brand, p.brand) END,
    packing_type       = CASE WHEN 'packing_type'       = ANY(v_locked) THEN p.packing_type       ELSE COALESCE(s.packing_type, p.packing_type) END,
    repacking_type     = CASE WHEN 'repacking_type'     = ANY(v_locked) THEN p.repacking_type     ELSE COALESCE(s.repacking_type, p.repacking_type) END,
    capacities         = CASE WHEN 'capacities'         = ANY(v_locked) THEN p.capacities         ELSE COALESCE(s.capacities, p.capacities) END,
    capacity_ml        = CASE WHEN 'capacity_ml'        = ANY(v_locked) THEN p.capacity_ml        ELSE COALESCE(s.capacity_ml, p.capacity_ml) END,
    min_quantity       = CASE WHEN 'min_quantity'       = ANY(v_locked) THEN p.min_quantity       ELSE COALESCE(s.min_quantity, p.min_quantity) END,
    warranty_months    = CASE WHEN 'warranty_months'    = ANY(v_locked) THEN p.warranty_months    ELSE COALESCE(s.warranty_months, p.warranty_months) END,
    ipi_rate           = CASE WHEN 'ipi_rate'           = ANY(v_locked) THEN p.ipi_rate           ELSE COALESCE(s.ipi_rate, p.ipi_rate) END,
    engraving_type     = CASE WHEN 'engraving_type'     = ANY(v_locked) THEN p.engraving_type     ELSE COALESCE(s.engraving_type, p.engraving_type) END,
    colors             = CASE WHEN 'colors'             = ANY(v_locked) THEN p.colors             ELSE COALESCE(s.colors, p.colors) END,
    is_active          = CASE WHEN 'is_active'          = ANY(v_locked) THEN p.is_active          ELSE COALESCE(s.is_active, p.is_active) END,
    active             = CASE WHEN 'is_active'          = ANY(v_locked) THEN p.active             ELSE COALESCE(s.is_active, p.active) END,
    last_sync_at          = now(),
    last_sync_supplier_id = s.supplier_id,
    supplier_updated_at   = now()
  WHERE p.id = v_pid;

  UPDATE public.produtos_padronizacao
     SET status='promoted', promoted_at=now(), product_id=v_pid
   WHERE id = p_id;

  IF s.raw_id IS NOT NULL THEN
    UPDATE public.supplier_products_raw
       SET status='processed', processed_at=now(), product_id=v_pid, process_errors=NULL
     WHERE id = s.raw_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'product_id', v_pid, 'created', v_is_new,
                            'locked_preserved', v_locked);
END;
$function$;

-- <<< END 20260605170100_fix_fn_promote_padronizacao_clear_process_errors.sql <<<

-- >>> BEGIN 20260605210000_silver_unify_07_adapt_staging_chain_to_silver.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 7
-- Adapta a cadeia legada "staging" para Bronze → Silver (de-para).
-- ════════════════════════════════════════════════════════════════
-- Descoberto em auditoria exaustiva do pg_proc (2026-06-05): havia uma
-- cadeia legada de ingestão que gravava Bronze → Gold DIRETO (pulava a Silver)
-- e NÃO estava deprecada nem adaptada:
--   fn_process_staging_batch → fn_process_all_staged_products → fn_process_staged_product → products
-- Estava DORMENTE (raiz órfã: 0 chamadores; ramo de variantes referenciava
-- fn_process_all_staged_variants, que NÃO EXISTE; fila de raws vazia), mas era
-- uma mina latente que violava a regra das 3 fases.
--
-- Decisão (usuário): ADAPTAR para a nova arquitetura Bronze → Prata, não dropar.
-- As 3 funções viram wrappers finos sobre o pipeline canônico (produtos_padronizacao*).
-- Promoção Silver → Gold continua a cargo do cron oficial (process_pending_batches
-- → fn_promote_supplier). Idempotente; sem escrita Gold direta.
-- ════════════════════════════════════════════════════════════════

-- 1) Folha: 1 raw → Silver (variante + pai)
CREATE OR REPLACE FUNCTION public.fn_process_staged_product(p_staging_id uuid)
RETURNS jsonb LANGUAGE plpgsql SET search_path TO 'public','extensions'
AS $function$
DECLARE r record; v_vres jsonb; v_pres jsonb; v_parent text;
BEGIN
  SELECT supplier_id, supplier_reference, raw_data INTO r
  FROM public.supplier_products_raw WHERE id = p_staging_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado', 'id', p_staging_id);
  END IF;
  -- ADAPTADO 2026-06-05: Bronze→Silver (de-para), não mais Bronze→Gold direto.
  v_vres   := public.fn_standardize_variant(p_staging_id);
  v_parent := COALESCE(NULLIF(v_vres->>'parent',''),
                       public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data));
  v_pres   := public.fn_standardize_parent(r.supplier_id, v_parent);
  RETURN jsonb_build_object('success', COALESCE((v_pres->>'success')::boolean, false),
    'adapted', 'bronze->silver', 'staging_id', p_staging_id, 'variant', v_vres, 'parent', v_pres);
END;
$function$;
COMMENT ON FUNCTION public.fn_process_staged_product(uuid) IS
  'ADAPTADO 2026-06-05: Bronze->Silver via fn_standardize_variant + fn_standardize_parent. Nao grava mais Bronze->Gold direto.';

-- 2) Batch por fornecedor → Silver
CREATE OR REPLACE FUNCTION public.fn_process_all_staged_products(p_supplier_id uuid DEFAULT NULL, p_limit integer DEFAULT 100)
RETURNS jsonb LANGUAGE plpgsql SET search_path TO 'public','extensions'
AS $function$
DECLARE v jsonb;
BEGIN
  IF p_supplier_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'supplier_id_obrigatorio');
  END IF;
  v := public.fn_standardize_supplier(p_supplier_id, p_limit);   -- Bronze→Silver
  RETURN jsonb_build_object('success', true, 'adapted', 'bronze->silver', 'standardize', v);
END;
$function$;
COMMENT ON FUNCTION public.fn_process_all_staged_products(uuid, integer) IS
  'ADAPTADO 2026-06-05: delega a fn_standardize_supplier (Bronze->Silver de-para).';

-- 3) Raiz da cadeia → Silver (promoção a Gold = cron oficial)
CREATE OR REPLACE FUNCTION public.fn_process_staging_batch(p_batch_id uuid DEFAULT NULL, p_supplier_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SET search_path TO 'public','extensions'
AS $function$
DECLARE v_std jsonb;
BEGIN
  IF p_supplier_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'supplier_id_obrigatorio');
  END IF;
  -- ADAPTADO 2026-06-05: Bronze→Silver via pipeline canônico (antes: staging→Gold direto +
  -- ramo de variantes inexistente). Promoção Silver→Gold = cron oficial (process_pending_batches).
  v_std := public.fn_standardize_supplier(p_supplier_id, NULL);
  RETURN jsonb_build_object('success', true, 'adapted', 'bronze->silver',
    'batch_id', p_batch_id, 'supplier_id', p_supplier_id, 'standardize', v_std);
END;
$function$;
COMMENT ON FUNCTION public.fn_process_staging_batch(uuid, uuid) IS
  'ADAPTADO 2026-06-05: delega a fn_standardize_supplier (Bronze->Silver). Promocao a Gold pelo cron oficial.';

-- <<< END 20260605210000_silver_unify_07_adapt_staging_chain_to_silver.sql <<<

-- >>> BEGIN 20260606110000_fase8_01_dimensions_into_promotion_retire_bronze_trigger.sql >>>
-- ════════════════════════════════════════════════════════════════
-- MEDALLION — Fase 8 / Item 1: Dimensões na promoção + aposenta trigger Bronze
-- ════════════════════════════════════════════════════════════════
-- O trigger AFTER `trg_auto_sync_product_dimensions` em supplier_products_raw
-- (→ fn_sync_single_product_dimensions) era o parser de dimensões do SPOT
-- (CombinedSizes → length/width/height/diameter/shape). Não era redundante: o
-- de-para do SPOT tem length_cm/width_cm INATIVOS de propósito. Era, porém, um
-- caminho Bronze→Gold paralelo (fora das 3 fases).
--
-- Item 1: relocar a MESMA lógica (mesma função, zero risco de paridade) para a
-- fase de promoção (Silver→Gold) dentro de fn_promote_padronizacao, e então
-- DROPAR o trigger Bronze.
--
-- NOTA: o corpo de fn_promote_padronizacao é reproduzido na íntegra (estado
-- pós-#679) + 1 chamada a fn_sync_single_product_dimensions no bloco da raw.
-- Aplicado via MCP (MCP-first, ADR 0006); ver o arquivo de migração aplicado
-- para o corpo completo. Aqui registramos o delta essencial e a remoção do trigger.
-- ════════════════════════════════════════════════════════════════

-- (corpo completo de fn_promote_padronizacao aplicado via MCP — delta abaixo)
-- + dentro do bloco `IF s.raw_id IS NOT NULL THEN ... END IF;`:
--     PERFORM public.fn_sync_single_product_dimensions(
--               v_pid, (SELECT raw_data FROM public.supplier_products_raw WHERE id = s.raw_id));

DROP TRIGGER IF EXISTS trg_auto_sync_product_dimensions ON public.supplier_products_raw;

COMMENT ON FUNCTION public.fn_trigger_auto_sync_dimensions() IS
  'DEPRECATED 2026-06-06 (Fase 8): trigger Bronze aposentado. Dimensoes estruturadas agora na promocao (fn_promote_padronizacao -> fn_sync_single_product_dimensions).';

-- <<< END 20260606110000_fase8_01_dimensions_into_promotion_retire_bronze_trigger.sql <<<

-- >>> BEGIN 20260606110100_fase8_02_document_xbz_stock_fastpath.sql >>>
-- MEDALLION — Fase 8 / Item 2: documenta o fast-path de estoque XBZ como canônico.
-- fn_import_stock_xbz lê supplier_products_raw.stock_data e atualiza a camada canônica de
-- sourcing (variant_supplier_sources) + rollup em products. Alinhado ao ADR 0007 §4.
-- Mantido como fast-path de alta frequência (cron xbz-stock-sync */15). Não é violação de fase.
COMMENT ON FUNCTION public.fn_import_stock_xbz(text) IS
  'CANONICO 2026-06-06 (Fase 8): fast-path de estoque XBZ. Le supplier_products_raw.stock_data e atualiza variant_supplier_sources (fonte-da-verdade de estoque, ADR 0007) + rollup em products. NAO e violacao Bronze->Gold (escreve na camada de sourcing canonica). Cron xbz-stock-sync */15.';

-- <<< END 20260606110100_fase8_02_document_xbz_stock_fastpath.sql <<<

-- >>> BEGIN 20260606110200_fase8_03_pipeline_category_classification_cron.sql >>>
-- MEDALLION — Fase 8 / Item 3: Categorias integradas ao pipeline (fill-only).
-- Problema: o pipeline novo (Bronze→Silver→Gold) não atribuía category_id; o legado
-- fn_*_to_silver (deprecado) fazia isso. Produtos novos ficariam sem categoria.
-- Solução: agendar fn_backfill_product_categories (fill-only: só preenche category_id NULL
-- via fn_master_classify_product, classificação por nome) como passo recorrente do pipeline.
-- Zero regressão (nunca sobrescreve categoria existente). Backlog histórico limpo na aplicação.
DO $$ BEGIN
  PERFORM cron.unschedule('pipeline-classify-categories');
EXCEPTION WHEN OTHERS THEN NULL; END $$;

SELECT cron.schedule(
  'pipeline-classify-categories',
  '*/10 * * * *',
  $cron$ SELECT public.fn_backfill_product_categories(300, false); $cron$
);

