-- >>> BEGIN 20260611120300_v2_04_promote_display_name_category_chain.sql >>>
-- V2-04 — Promoção Silver→Gold com display-case e cadeia de categoria completa.
-- (a) fn_classify_category_residual: dicionário ILIKE de alta precisão derivado da
--     análise dos produtos sem categoria (lookup por slug — sem UUIDs hardcoded).
-- (b) fn_promote_category_fallback: classify (melhor confiança) → residual.
-- (c) fn_promote_padronizacao: Gold name ← fn_display_product_name(s.name);
--     categoria: De→Para → fallback (fill-only, nunca em campo lockado);
--     guards NULLIF('[]') em tags/materials (anti-Bug6 na promoção).
-- (d) trigger_limpar_nome_produto: Gold SPOT recebe display-case (era UPPERCASE).
-- locked_fields continua respeitado em TODOS os campos na promoção.

CREATE OR REPLACE FUNCTION public.fn_classify_category_residual(p_name text)
RETURNS uuid
LANGUAGE plpgsql STABLE
SET search_path TO 'public'
AS $function$
DECLARE
  n text := lower(COALESCE(p_name,''));
  v_id uuid;
BEGIN
  IF n = '' THEN RETURN NULL; END IF;

  IF n ~ 'caixa de som|caixa som|speaker' THEN
    SELECT id INTO v_id FROM categories WHERE slug='caixa-de-som' LIMIT 1; RETURN v_id;
  END IF;

  IF n ~ 'mouse ?pad' THEN
    IF n ~ 'ergon[ôo]mico' THEN SELECT id INTO v_id FROM categories WHERE slug='mouse_pad_espuma_ergonomico' LIMIT 1; END IF;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='mouse_pad' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  IF n ~ 'churrasqueira|churrasco' THEN
    IF n ~ '\mkit\M' THEN SELECT id INTO v_id FROM categories WHERE slug='kit_churrasco' LIMIT 1; END IF;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='churrasco' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  IF n ~ '\mkit\M' AND n ~ 'drink|coquetel' THEN
    SELECT id INTO v_id FROM categories WHERE slug='kit-drink' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ '\mkit\M' AND n ~ 'executivo' THEN
    SELECT id INTO v_id FROM categories WHERE slug='kit_executivo' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'talher' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bar_e_cozinha' LIMIT 1; RETURN v_id;
  END IF;

  IF n ~ 'umidificador|aromatizador' THEN
    SELECT id INTO v_id FROM categories WHERE slug='ferramentas-utilidades' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'frasqueira' THEN
    SELECT id INTO v_id FROM categories WHERE slug='frasqueiras' LIMIT 1; RETURN v_id;
  END IF;

  IF n ~ 'bebedouro|comedouro' AND n ~ '\mpet|cachorro|gato' THEN
    SELECT id INTO v_id FROM categories WHERE slug='brinquedos_pet' LIMIT 1; RETURN v_id;
  END IF;

  IF n ~ 'chap[ée]u' THEN
    IF n ~ 'ecoflex' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_ecoflex' LIMIT 1;
    ELSIF n ~ 'juta' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_juta' LIMIT 1;
    ELSIF n ~ 'palha' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_palha' LIMIT 1;
    ELSIF n ~ 'bucket' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu-bucket' LIMIT 1;
    END IF;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='chapeus' OR name='Chapéus' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  IF n ~ 'caderno|caderneta|bloco de anota' THEN
    SELECT id INTO v_id FROM categories WHERE slug='cadernetas-cadernos' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE name ILIKE 'caderno%' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  IF n ~ 'marmita' THEN
    SELECT id INTO v_id FROM categories WHERE name ILIKE 'marmit%' OR slug ILIKE 'marmit%' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='bar_e_cozinha' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  IF n ~ '\mmala\M' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsas_de_viagem' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'bolsa t[ée]rmica' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsa_termica' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ '\mbolsa\M' AND n ~ 'esport|viagem|mochila' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsas_de_viagem' LIMIT 1; RETURN v_id;
  END IF;

  IF n ~ 'brinquedo' AND n ~ '\mpet\M|cachorro|gato' THEN
    SELECT id INTO v_id FROM categories WHERE slug='brinquedos_pet' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'antiestresse|anti-estresse|anti estresse|apert[áa]vel|brinquedo' THEN
    SELECT id INTO v_id FROM categories WHERE slug='jogos_e_brinquedos' LIMIT 1; RETURN v_id;
  END IF;

  IF n ~ 'pasta|escrit[óo]rio|porta document' THEN
    SELECT id INTO v_id FROM categories WHERE slug ILIKE 'escritorio%' OR name ILIKE 'escritório%' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='acessorios' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_promote_category_fallback(p_name text)
RETURNS uuid
LANGUAGE plpgsql STABLE
SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  BEGIN
    SELECT c.category_id INTO v_id
    FROM public.classify_xbz_category(p_name) c
    ORDER BY CASE c.confidence WHEN 'alta' THEN 1 WHEN 'média' THEN 2 ELSE 3 END
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_id := NULL;
  END;
  IF v_id IS NULL THEN
    v_id := public.fn_classify_category_residual(p_name);
  END IF;
  RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_promote_padronizacao(p_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  s        public.produtos_padronizacao%ROWTYPE;
  v_pid    uuid;
  v_org    uuid;
  v_locked text[];
  v_is_new boolean := false;
  v_cat_id   uuid    := NULL;
  v_cat_src  text;
  v_cat_l1   text;
  v_existing_cat uuid := NULL;
  v_min_qty  integer := NULL;
  v_display_name text;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  PERFORM set_config('app.write_source',     'pipeline', true);
  PERFORM set_config('app.bulk_import_mode', 'true',     true);

  v_display_name := public.fn_display_product_name(s.name);

  SELECT id, locked_fields, category_id INTO v_pid, v_locked, v_existing_cat
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, active, is_active, product_type)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name),
            COALESCE(v_display_name, s.name, 'Produto ' || s.supplier_reference),
            true, true, 'product')  -- REGRA: produto SEMPRE nasce ativo; desativação requer aprovação
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  -- Categoria nível 1: De→Para
  IF s.raw_id IS NOT NULL AND NOT ('category_id' = ANY(v_locked)) THEN
    BEGIN
      SELECT sfm.source_field INTO v_cat_src
      FROM public.supplier_field_mappings sfm
      WHERE sfm.supplier_id = s.supplier_id AND sfm.target_field = 'categories'
      LIMIT 1;
      IF v_cat_src IS NOT NULL THEN
        SELECT split_part(COALESCE(spr.raw_data ->> v_cat_src, ''), '|', 1)
        INTO v_cat_l1
        FROM public.supplier_products_raw spr WHERE spr.id = s.raw_id;
        IF v_cat_l1 IS NOT NULL AND TRIM(v_cat_l1) <> '' THEN
          SELECT scm.category_id INTO v_cat_id
          FROM public.supplier_categories sc
          JOIN public.supplier_category_mappings scm ON scm.supplier_category_id = sc.id
          WHERE sc.supplier_id = s.supplier_id AND TRIM(sc.supplier_code) = TRIM(v_cat_l1)
          LIMIT 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  -- Categoria nível 2: classify (melhor confiança) → residual (fill-only)
  IF v_cat_id IS NULL AND v_existing_cat IS NULL AND NOT ('category_id' = ANY(v_locked)) THEN
    v_cat_id := public.fn_promote_category_fallback(s.name);
  END IF;

  IF s.min_quantity IS NOT NULL THEN
    SELECT GREATEST(
        s.min_quantity,
        COALESCE(c.min_order_quantity, 1)
    )
    INTO v_min_qty
    FROM public.categories c
    WHERE c.id = COALESCE(v_cat_id,
        (SELECT category_id FROM public.products WHERE id = v_pid));
    v_min_qty := COALESCE(v_min_qty, s.min_quantity);
  END IF;

  UPDATE public.products p SET
    sku                = COALESCE(p.sku, s.supplier_reference, s.name),
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(v_display_name, s.name, p.name)           END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description,        p.description)        END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description,  p.short_description)  END,
    cost_price         = CASE WHEN 'cost_price'         = ANY(v_locked) THEN p.cost_price         ELSE COALESCE(NULLIF(s.cost_price,      0), p.cost_price)      END,
    suggested_price    = CASE WHEN 'suggested_price'    = ANY(v_locked) THEN p.suggested_price    ELSE COALESCE(NULLIF(s.suggested_price, 0), p.suggested_price) END,
    stock_quantity     = CASE WHEN 'stock_quantity'     = ANY(v_locked) THEN p.stock_quantity     ELSE COALESCE(s.stock_quantity,     p.stock_quantity)     END,
    min_quantity       = CASE WHEN 'min_quantity'       = ANY(v_locked) THEN p.min_quantity
                              WHEN v_min_qty IS NOT NULL                THEN v_min_qty
                              ELSE COALESCE(s.min_quantity, p.min_quantity)              END,
    primary_image_url  = CASE
      WHEN 'primary_image_url' = ANY(v_locked)              THEN p.primary_image_url
      WHEN p.primary_image_url LIKE '%imagedelivery%'       THEN p.primary_image_url
      ELSE COALESCE(s.primary_image_url, p.primary_image_url)
    END,
    images             = CASE WHEN 'images'             = ANY(v_locked) THEN p.images             ELSE COALESCE(s.images,             p.images)             END,
    ncm_code           = CASE WHEN 'ncm_code'           = ANY(v_locked) THEN p.ncm_code           ELSE COALESCE(NULLIF(s.ncm_code,'00000000'), p.ncm_code)           END,
    weight_g           = CASE WHEN 'weight_g'           = ANY(v_locked) THEN p.weight_g           ELSE COALESCE(NULLIF(s.weight_g,   0), p.weight_g)   END,
    height_cm          = CASE WHEN 'height_cm'          = ANY(v_locked) THEN p.height_cm          ELSE COALESCE(NULLIF(s.height_cm,  0), p.height_cm)  END,
    width_cm           = CASE WHEN 'width_cm'           = ANY(v_locked) THEN p.width_cm           ELSE COALESCE(NULLIF(s.width_cm,   0), p.width_cm)   END,
    length_cm          = CASE WHEN 'length_cm'          = ANY(v_locked) THEN p.length_cm          ELSE COALESCE(NULLIF(s.length_cm,  0), p.length_cm)  END,
    dimensions_display = CASE WHEN 'dimensions_display' = ANY(v_locked) THEN p.dimensions_display ELSE COALESCE(s.dimensions_display, p.dimensions_display) END,
    box_length_cm      = CASE WHEN 'box_length_cm'      = ANY(v_locked) THEN p.box_length_cm      ELSE COALESCE(s.box_length_cm,      p.box_length_cm)      END,
    box_width_cm       = CASE WHEN 'box_width_cm'       = ANY(v_locked) THEN p.box_width_cm       ELSE COALESCE(s.box_width_cm,       p.box_width_cm)       END,
    box_height_cm      = CASE WHEN 'box_height_cm'      = ANY(v_locked) THEN p.box_height_cm      ELSE COALESCE(s.box_height_cm,      p.box_height_cm)      END,
    box_weight_kg      = CASE WHEN 'box_weight_kg'      = ANY(v_locked) THEN p.box_weight_kg      ELSE COALESCE(s.box_weight_kg,      p.box_weight_kg)      END,
    box_volume_cm3     = CASE WHEN 'box_volume_cm3'     = ANY(v_locked) THEN p.box_volume_cm3     ELSE COALESCE(s.box_volume_cm3,     p.box_volume_cm3)     END,
    box_quantity       = CASE WHEN 'box_quantity'       = ANY(v_locked) THEN p.box_quantity       ELSE COALESCE(s.box_quantity,       p.box_quantity)       END,
    box_inner_quantity = CASE WHEN 'box_inner_quantity' = ANY(v_locked) THEN p.box_inner_quantity ELSE COALESCE(s.box_inner_quantity, p.box_inner_quantity) END,
    brand              = CASE WHEN 'brand'              = ANY(v_locked) THEN p.brand              ELSE COALESCE(s.brand,              p.brand)              END,
    packing_type       = CASE WHEN 'packing_type'       = ANY(v_locked) THEN p.packing_type       ELSE COALESCE(s.packing_type,       p.packing_type)       END,
    repacking_type     = CASE WHEN 'repacking_type'     = ANY(v_locked) THEN p.repacking_type     ELSE COALESCE(s.repacking_type,     p.repacking_type)     END,
    capacities         = CASE WHEN 'capacities'         = ANY(v_locked) THEN p.capacities         ELSE COALESCE(s.capacities,         p.capacities)         END,
    capacity_ml        = CASE WHEN 'capacity_ml'        = ANY(v_locked) THEN p.capacity_ml        ELSE COALESCE(NULLIF(s.capacity_ml, 0), p.capacity_ml) END,
    ipi_rate           = CASE WHEN 'ipi_rate'           = ANY(v_locked) THEN p.ipi_rate           ELSE COALESCE(s.ipi_rate,           p.ipi_rate)           END,
    engraving_type     = CASE WHEN 'engraving_type'     = ANY(v_locked) THEN p.engraving_type     ELSE COALESCE(s.engraving_type,     p.engraving_type)     END,
    colors             = CASE WHEN 'colors'             = ANY(v_locked) THEN p.colors             ELSE COALESCE(s.colors,             p.colors)             END,
    combined_sizes         = CASE WHEN 'combined_sizes'         = ANY(v_locked) THEN p.combined_sizes         ELSE COALESCE(s.combined_sizes,         p.combined_sizes)         END,
    box_image              = CASE WHEN 'box_image'              = ANY(v_locked) THEN p.box_image              ELSE COALESCE(s.box_image,              p.box_image)              END,
    is_textil              = CASE WHEN 'is_textil'              = ANY(v_locked) THEN p.is_textil              ELSE COALESCE(s.is_textil,              p.is_textil)              END,
    is_stockout            = CASE WHEN 'is_stockout'            = ANY(v_locked) THEN p.is_stockout            ELSE COALESCE(s.is_stockout,            p.is_stockout)            END,
    is_online_exclusive    = CASE WHEN 'is_online_exclusive'    = ANY(v_locked) THEN p.is_online_exclusive    ELSE COALESCE(s.is_online_exclusive,    p.is_online_exclusive)    END,
    is_new                 = CASE WHEN 'is_new'                 = ANY(v_locked) THEN p.is_new                 ELSE COALESCE(s.is_new,                 p.is_new)                 END,
    has_colors             = CASE WHEN 'has_colors'             = ANY(v_locked) THEN p.has_colors             ELSE COALESCE(s.has_colors,             p.has_colors)             END,
    has_sizes              = CASE WHEN 'has_sizes'              = ANY(v_locked) THEN p.has_sizes              ELSE COALESCE(s.has_sizes,              p.has_sizes)              END,
    allows_personalization = CASE WHEN 'allows_personalization' = ANY(v_locked) THEN p.allows_personalization ELSE COALESCE(s.allows_personalization, p.allows_personalization) END,
    tags                   = CASE WHEN 'tags'                   = ANY(v_locked) THEN p.tags                   ELSE COALESCE(NULLIF(s.tags,'[]'::jsonb),      p.tags)      END,
    materials              = CASE WHEN 'materials'              = ANY(v_locked) THEN p.materials              ELSE COALESCE(NULLIF(s.materials,'[]'::jsonb), p.materials) END,
    meta_keywords          = CASE WHEN 'meta_keywords'          = ANY(v_locked) THEN p.meta_keywords          ELSE COALESCE(s.meta_keywords,          p.meta_keywords)          END,
    category_id            = CASE
      WHEN 'category_id' = ANY(v_locked) THEN p.category_id
      WHEN v_cat_id IS NOT NULL           THEN v_cat_id
      ELSE                                     p.category_id
    END,
    origin_country        = CASE WHEN 'origin_country'        = ANY(v_locked) THEN p.origin_country        ELSE COALESCE(s.origin_country,        p.origin_country)        END,
    supplier_type         = CASE WHEN 'supplier_type'         = ANY(v_locked) THEN p.supplier_type         ELSE COALESCE(s.supplier_type,         p.supplier_type)         END,
    supplier_type_code    = CASE WHEN 'supplier_type_code'    = ANY(v_locked) THEN p.supplier_type_code    ELSE COALESCE(s.supplier_type_code,    p.supplier_type_code)    END,
    supplier_subtype      = CASE WHEN 'supplier_subtype'      = ANY(v_locked) THEN p.supplier_subtype      ELSE COALESCE(s.supplier_subtype,      p.supplier_subtype)      END,
    supplier_subtype_code = CASE WHEN 'supplier_subtype_code' = ANY(v_locked) THEN p.supplier_subtype_code ELSE COALESCE(s.supplier_subtype_code, p.supplier_subtype_code) END,
    is_seasonal           = CASE WHEN 'is_seasonal'           = ANY(v_locked) THEN p.is_seasonal           ELSE COALESCE(s.is_seasonal,           p.is_seasonal)           END,
    pvc_free              = CASE WHEN 'pvc_free'              = ANY(v_locked) THEN p.pvc_free              ELSE COALESCE(s.pvc_free,              p.pvc_free)              END,
    last_sync_at          = now(),
    last_sync_supplier_id = s.supplier_id,
    supplier_updated_at   = now()
  WHERE p.id = v_pid;

  UPDATE public.produtos_padronizacao
     SET status='promoted', promoted_at=now(), product_id=v_pid
   WHERE id = p_id;

  IF s.raw_id IS NOT NULL THEN
    UPDATE public.supplier_products_raw
       SET status='processed', processed_at=now(), product_id=v_pid, process_errors=NULL
     WHERE id = s.raw_id;
    PERFORM public.fn_sync_single_product_dimensions(
              v_pid, (SELECT raw_data FROM public.supplier_products_raw WHERE id = s.raw_id));
  END IF;

  RETURN jsonb_build_object(
    'success',          true,
    'product_id',       v_pid,
    'created',          v_is_new,
    'locked_preserved', v_locked,
    'min_quantity_final', v_min_qty,
    'display_name',     v_display_name,
    'category_depara',  CASE WHEN v_cat_id IS NOT NULL
                             THEN jsonb_build_object('category_id', v_cat_id, 'l1_raw', v_cat_l1)
                             ELSE 'null'::jsonb END
  );
END;
$function$;

-- (d) Trigger Gold: SPOT recebe display-case (era UPPERCASE completo)
CREATE OR REPLACE FUNCTION public.trigger_limpar_nome_produto()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
    v_spot_supplier_id UUID := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
    v_result text;
BEGIN
    IF NEW.supplier_id = v_spot_supplier_id THEN
        v_result := public.fn_display_product_name(NEW.name);
        IF v_result IS NOT NULL AND v_result <> '' THEN
            NEW.name := v_result;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;

-- <<< END 20260611120300_v2_04_promote_display_name_category_chain.sql <<<

-- >>> BEGIN 20260611120400_fase9_05_restore_main_ingestion_cron.sql >>>
-- CRÍTICO (Fase 9): restaura o cron PRINCIPAL de ingestão (process-pending-products),
-- que havia sido removido entre sessões. Sem ele, raws ficam 'pending' indefinidamente
-- (900 acumuladas foram encontradas paradas em 2026-06-11). Detectado pela validação
-- consolidada (esperado 4 crons ativos, encontrado 3).
DO $$ BEGIN
  PERFORM cron.unschedule('process-pending-products');
EXCEPTION WHEN OTHERS THEN NULL; END $$;

SELECT cron.schedule(
  'process-pending-products',
  '*/5 * * * *',
  $cron$ SELECT * FROM process_pending_batches(); $cron$
);

-- <<< END 20260611120400_fase9_05_restore_main_ingestion_cron.sql <<<

-- >>> BEGIN 20260611120400_v2_05_monitoring_coverage.sql >>>
-- V2-05 — Monitoramento de cobertura do pipeline (anti-decay).
-- Motivação: as melhorias V1 decaíram silenciosamente porque eram UPDATEs
-- retroativos sem guarda. Agora as funções corrigem na FONTE e este monitor
-- detecta qualquer drift: view ao vivo + snapshot diário + checagem de regressão.

CREATE OR REPLACE VIEW public.vw_medallion_coverage AS
SELECT
  s.name AS fornecedor,
  'silver' AS camada,
  COUNT(*) AS produtos,
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(pp.ncm_code),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS ncm_pct,
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(pp.materials,'[]'::jsonb))>0 THEN 1 ELSE 0 END)/COUNT(*),1) AS materials_pct,
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(pp.tags,'[]'::jsonb))>0 THEN 1 ELSE 0 END)/COUNT(*),1) AS tags_pct,
  ROUND(100.0*SUM(CASE WHEN COALESCE(array_length(pp.meta_keywords,1),0)>0 THEN 1 ELSE 0 END)/COUNT(*),1) AS meta_pct,
  ROUND(100.0*SUM(CASE WHEN pp.ipi_rate IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS ipi_pct,
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(pp.description),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS description_pct,
  NULL::numeric AS category_pct,
  NULL::numeric AS display_name_pct
FROM public.produtos_padronizacao pp JOIN public.suppliers s ON s.id=pp.supplier_id
GROUP BY s.name
UNION ALL
SELECT
  s.name, 'gold', COUNT(*),
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(p.ncm_code),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(p.materials,'[]'::jsonb))>0
                        OR EXISTS (SELECT 1 FROM public.product_materials pm WHERE pm.product_id=p.id) THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(p.tags,'[]'::jsonb))>0 THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN COALESCE(array_length(p.meta_keywords,1),0)>0 THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN p.ipi_rate IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(p.description),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN p.category_id IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN p.name IS NULL OR p.name <> public.fn_normalize_product_name(p.name) OR p.name !~ '[A-Za-zÀ-ú]{4,}' THEN 1 ELSE 0 END)/COUNT(*),1)
FROM public.products p JOIN public.suppliers s ON s.id=p.supplier_id
GROUP BY s.name;

CREATE TABLE IF NOT EXISTS public.medallion_coverage_snapshots (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  captured_at timestamptz NOT NULL DEFAULT now(),
  fornecedor text NOT NULL,
  camada text NOT NULL,
  produtos int NOT NULL,
  ncm_pct numeric, materials_pct numeric, tags_pct numeric, meta_pct numeric,
  ipi_pct numeric, description_pct numeric, category_pct numeric, display_name_pct numeric
);
CREATE INDEX IF NOT EXISTS idx_mcs_captured ON public.medallion_coverage_snapshots (captured_at);

ALTER TABLE public.medallion_coverage_snapshots ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  CREATE POLICY mcs_admin_read ON public.medallion_coverage_snapshots
    FOR SELECT TO authenticated USING (true);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE OR REPLACE FUNCTION public.fn_snapshot_medallion_coverage()
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  INSERT INTO public.medallion_coverage_snapshots
    (fornecedor, camada, produtos, ncm_pct, materials_pct, tags_pct, meta_pct, ipi_pct, description_pct, category_pct, display_name_pct)
  SELECT fornecedor, camada, produtos, ncm_pct, materials_pct, tags_pct, meta_pct, ipi_pct, description_pct, category_pct, display_name_pct
  FROM public.vw_medallion_coverage;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_check_coverage_regression()
RETURNS TABLE (fornecedor text, camada text, metrica text, maximo_7d numeric, atual numeric, queda_pp numeric)
LANGUAGE sql STABLE
SET search_path TO 'public'
AS $function$
  WITH hist AS (
    SELECT fornecedor, camada,
           MAX(ncm_pct) ncm, MAX(materials_pct) mat, MAX(tags_pct) tags, MAX(meta_pct) meta,
           MAX(ipi_pct) ipi, MAX(description_pct) descr, MAX(category_pct) cat, MAX(display_name_pct) disp
    FROM public.medallion_coverage_snapshots
    WHERE captured_at > now() - interval '7 days'
    GROUP BY fornecedor, camada
  ), atual AS (
    SELECT * FROM public.vw_medallion_coverage
  ), unioned AS (
    SELECT a.fornecedor, a.camada, m.metrica, m.maximo, m.val
    FROM atual a JOIN hist h ON h.fornecedor=a.fornecedor AND h.camada=a.camada
    CROSS JOIN LATERAL (VALUES
      ('ncm', h.ncm, a.ncm_pct), ('materials', h.mat, a.materials_pct),
      ('tags', h.tags, a.tags_pct), ('meta', h.meta, a.meta_pct),
      ('ipi', h.ipi, a.ipi_pct), ('description', h.descr, a.description_pct),
      ('category', h.cat, a.category_pct), ('display_name', h.disp, a.display_name_pct)
    ) m(metrica, maximo, val)
  )
  SELECT fornecedor, camada, metrica, maximo, val, ROUND(maximo - val, 1)
  FROM unioned
  WHERE maximo IS NOT NULL AND val IS NOT NULL AND maximo - val > 2.0
  ORDER BY (maximo - val) DESC;
$function$;

DO $$ BEGIN
  PERFORM cron.schedule('medallion-coverage-daily', '37 3 * * *',
    'SELECT public.fn_snapshot_medallion_coverage()');
EXCEPTION WHEN OTHERS THEN NULL; END $$;

-- <<< END 20260611120400_v2_05_monitoring_coverage.sql <<<

-- >>> BEGIN 20260611120500_v2_06_retroactive_convergence.sql >>>
-- V2-06 — Convergência retroativa (idempotente; todos os passos são fill-only).
-- Já executada em produção em 2026-06-11; mantida como migration para
-- reprodutibilidade em outros ambientes. Re-execução não altera dados corretos.

-- (1) Mapping XBZ IpiTaxa → ipi_rate (91.3% de cobertura no raw; estava sem mapping)
INSERT INTO supplier_field_mappings (supplier_id, source_field, target_table, target_field, transform_type, priority, is_active)
SELECT s.id, 'IpiTaxa', 'products', 'ipi_rate', 'cast_decimal', 28, TRUE
FROM suppliers s WHERE s.name='XBZ Brindes'
  AND NOT EXISTS (SELECT 1 FROM supplier_field_mappings m
                  WHERE m.supplier_id=s.id AND m.target_field='ipi_rate' AND m.target_table='products');

-- (2) IPI ← raw XBZ direto
UPDATE produtos_padronizacao pp
SET ipi_rate = public.fn_safe_num(r.raw_data->>'IpiTaxa'), updated_at = now()
FROM supplier_products_raw r
WHERE r.id = pp.raw_id AND pp.ipi_rate IS NULL
  AND public.fn_safe_num(r.raw_data->>'IpiTaxa') IS NOT NULL;

-- (3) IPI ← ncm_codes
UPDATE produtos_padronizacao pp
SET ipi_rate = nc.ipi_rate, updated_at = now()
FROM ncm_codes nc
WHERE pp.ipi_rate IS NULL AND nc.code = pp.ncm_code AND nc.is_active AND nc.ipi_rate IS NOT NULL;

-- (4) IPI ← moda inequívoca dos irmãos de mesmo NCM
WITH moda AS (
  SELECT ncm_code, MIN(ipi_rate) AS ipi FROM produtos_padronizacao
  WHERE ipi_rate IS NOT NULL AND ncm_code IS NOT NULL
  GROUP BY ncm_code HAVING COUNT(DISTINCT ipi_rate)=1
)
UPDATE produtos_padronizacao pp SET ipi_rate=m.ipi, updated_at=now()
FROM moda m WHERE pp.ipi_rate IS NULL AND pp.ncm_code=m.ncm_code;

-- (5) NCM ← prefixo de nome inequívoco (2 primeiras palavras, mesmo fornecedor)
WITH alvo AS (
  SELECT id, supplier_id,
         (SELECT string_agg(w,' ') FROM (
            SELECT w FROM regexp_split_to_table(UPPER(name),'\s+') WITH ORDINALITY t(w,o) WHERE o<=2 ORDER BY o) z) AS prefix
  FROM produtos_padronizacao WHERE ncm_code IS NULL AND name IS NOT NULL
), mapa AS (
  SELECT a.id, MIN(x.ncm_code) AS ncm
  FROM alvo a
  JOIN produtos_padronizacao x ON x.supplier_id=a.supplier_id AND x.ncm_code IS NOT NULL
       AND UPPER(x.name) LIKE a.prefix || '%'
  WHERE LENGTH(a.prefix) >= 5
  GROUP BY a.id HAVING COUNT(DISTINCT x.ncm_code) = 1
)
UPDATE produtos_padronizacao pp SET ncm_code = m.ncm, updated_at = now()
FROM mapa m WHERE pp.id = m.id;

-- (6) Conteúdo (tags/materials/meta/description) via fn_enrich_padronizacao
SELECT COUNT(*) FROM (
  SELECT public.fn_enrich_padronizacao(pp.id)
  FROM produtos_padronizacao pp
  WHERE jsonb_array_length(COALESCE(pp.tags,'[]'::jsonb))=0
     OR jsonb_array_length(COALESCE(pp.materials,'[]'::jsonb))=0
     OR COALESCE(array_length(pp.meta_keywords,1),0)=0
     OR NULLIF(TRIM(COALESCE(pp.description,'')),'') IS NULL
) t;

-- (7) Gold: nomes ALLCAPS-máquina → display-case
--     Auditoria prévia: 100% dos nomes lockados eram byte-idênticos à forma
--     máquina (UPPER) — zero conteúdo humano em risco; a transformação preserva
--     o conteúdo e muda apenas a caixa. Locks continuam respeitados no pipeline.
SELECT set_config('app.write_source','pipeline', true);
SELECT set_config('app.bulk_import_mode','true', true);
UPDATE products p
SET name = public.fn_display_product_name(p.name), updated_at = now()
WHERE p.name IS NOT NULL
  AND p.name = public.fn_normalize_product_name(p.name)
  AND p.name ~ '[A-Za-zÀ-ú]{4,}'
  AND public.fn_display_product_name(p.name) IS DISTINCT FROM p.name;

-- (8) Gold: enriquecimento fill-only a partir da Silver (locks respeitados por coluna)
UPDATE products p SET
  tags = CASE WHEN 'tags'=ANY(COALESCE(p.locked_fields,'{}')) THEN p.tags
              ELSE COALESCE(NULLIF(p.tags,'[]'::jsonb), NULLIF(pp.tags,'[]'::jsonb), p.tags) END,
  materials = CASE WHEN 'materials'=ANY(COALESCE(p.locked_fields,'{}')) THEN p.materials
              ELSE COALESCE(NULLIF(p.materials,'[]'::jsonb), NULLIF(pp.materials,'[]'::jsonb), p.materials) END,
  meta_keywords = CASE WHEN 'meta_keywords'=ANY(COALESCE(p.locked_fields,'{}')) THEN p.meta_keywords
              WHEN COALESCE(array_length(p.meta_keywords,1),0)=0 THEN COALESCE(pp.meta_keywords, p.meta_keywords)
              ELSE p.meta_keywords END,
  ipi_rate = CASE WHEN 'ipi_rate'=ANY(COALESCE(p.locked_fields,'{}')) THEN p.ipi_rate
              ELSE COALESCE(p.ipi_rate, pp.ipi_rate) END,
  ncm_code = CASE WHEN 'ncm_code'=ANY(COALESCE(p.locked_fields,'{}')) THEN p.ncm_code
              ELSE COALESCE(NULLIF(TRIM(p.ncm_code),''), NULLIF(pp.ncm_code,'00000000')) END,
  description = CASE WHEN 'description'=ANY(COALESCE(p.locked_fields,'{}')) THEN p.description
              ELSE COALESCE(NULLIF(TRIM(p.description),''), pp.description) END,
  updated_at = now()
FROM produtos_padronizacao pp
WHERE pp.product_id = p.id
  AND ( (jsonb_array_length(COALESCE(p.tags,'[]'::jsonb))=0 AND jsonb_array_length(COALESCE(pp.tags,'[]'::jsonb))>0)
     OR (jsonb_array_length(COALESCE(p.materials,'[]'::jsonb))=0 AND jsonb_array_length(COALESCE(pp.materials,'[]'::jsonb))>0)
     OR (COALESCE(array_length(p.meta_keywords,1),0)=0 AND COALESCE(array_length(pp.meta_keywords,1),0)>0)
     OR (p.ipi_rate IS NULL AND pp.ipi_rate IS NOT NULL)
     OR (NULLIF(TRIM(p.ncm_code),'') IS NULL AND pp.ncm_code IS NOT NULL)
     OR (NULLIF(TRIM(p.description),'') IS NULL AND pp.description IS NOT NULL) );

-- (9) Gold: categorias via cadeia (classify melhor confiança → residual), fill-only
WITH alvo AS (
  SELECT p.id, public.fn_promote_category_fallback(p.name) AS cat
  FROM products p
  WHERE p.category_id IS NULL AND NOT ('category_id' = ANY(COALESCE(p.locked_fields,'{}')))
)
UPDATE products p SET category_id = a.cat, updated_at = now()
FROM alvo a WHERE p.id = a.id AND a.cat IS NOT NULL;

-- (10) Higiene: NCM com pontos remanescente + dedup de variantes Silver
UPDATE produtos_padronizacao SET ncm_code = public.fn_normalize_ncm(ncm_code), updated_at=now()
WHERE ncm_code LIKE '%.%';

WITH ranked AS (
  SELECT id, ROW_NUMBER() OVER (
    PARTITION BY supplier_id, supplier_sku
    ORDER BY (variant_id IS NOT NULL) DESC, updated_at DESC, created_at DESC
  ) rn
  FROM produtos_padronizacao_variantes
  WHERE supplier_sku IN (
    SELECT supplier_sku FROM produtos_padronizacao_variantes
    WHERE supplier_sku IS NOT NULL GROUP BY supplier_id, supplier_sku HAVING COUNT(*)>1)
)
DELETE FROM produtos_padronizacao_variantes WHERE id IN (SELECT id FROM ranked WHERE rn > 1);

-- (11) Snapshot baseline do monitoramento
SELECT public.fn_snapshot_medallion_coverage();

-- <<< END 20260611120500_v2_06_retroactive_convergence.sql <<<

-- >>> BEGIN 20260611121000_fn_promote_supplier_sweep_orphan_variants.sql >>>
-- ════════════════════════════════════════════════════════════════
-- fn_promote_supplier: sweep de variantes órfãs no Silver.
-- ════════════════════════════════════════════════════════════════
-- GAP: o orquestrador Silver→Gold iterava SOMENTE pais com
-- status='standardized'. Variantes re-padronizadas (backfill, fix de
-- de-para, re-sync parcial) cujo pai continua 'promoted' ficavam
-- presas em 'standardized' para sempre — nenhum caminho as promovia
-- (o cron só acorda com raw 'pending', e o loop de pais as ignora).
--
-- Correção: após o loop de pais, um SWEEP promove variantes
-- 'standardized' cujo produto-pai JÁ EXISTE no Gold, via
-- fn_promote_variants_of_parent (idempotente). Retorno ganha o campo
-- 'variantes_orfas_promovidas'; demais campos preservados.
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_promote_supplier(
    p_supplier_id uuid,
    p_limit       integer DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_par RECORD;
  v_prom jsonb; v_vres jsonb;
  v_pais int := 0; v_novos int := 0; v_var int := 0; v_erros int := 0;
  v_orfas int := 0;
  v_t0 timestamptz := clock_timestamp();
  v_err_amostra jsonb := '[]'::jsonb;
  v_created boolean; v_vcount int;
BEGIN
  PERFORM set_config('app.write_source','pipeline', true);

  FOR v_par IN
    SELECT id, supplier_reference
    FROM public.produtos_padronizacao
    WHERE supplier_id = p_supplier_id AND status = 'standardized'
    ORDER BY supplier_reference
    LIMIT p_limit
  LOOP
    BEGIN
      v_prom := public.fn_promote_padronizacao(v_par.id);
      IF NOT COALESCE((v_prom->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'pai_falhou:%', COALESCE(v_prom->>'error','desconhecido');
      END IF;
      v_created := COALESCE((v_prom->>'created')::boolean, false);

      v_vres := public.fn_promote_variants_of_parent(p_supplier_id, v_par.supplier_reference);
      IF NOT COALESCE((v_vres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'variantes_falharam:%', COALESCE(v_vres->>'error','desconhecido');
      END IF;
      v_vcount := COALESCE((v_vres->>'variantes_promovidas')::int, 0);

      v_pais := v_pais + 1;
      IF v_created THEN v_novos := v_novos + 1; END IF;
      v_var := v_var + v_vcount;

    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra || jsonb_build_object('ref', v_par.supplier_reference, 'erro', SQLERRM);
      END IF;
      BEGIN
        UPDATE public.supplier_products_raw r
           SET process_errors = jsonb_build_object(
                 'stage','promote','parent', v_par.supplier_reference,
                 'erro', SQLERRM, 'at', now())
         WHERE r.supplier_id = p_supplier_id
           AND r.status IN ('pending','failed')
           AND r.id IN (
             SELECT pv.raw_id FROM public.produtos_padronizacao_variantes pv
              WHERE pv.supplier_id = p_supplier_id
                AND pv.parent_reference = v_par.supplier_reference
                AND pv.raw_id IS NOT NULL
             UNION
             SELECT pp.raw_id FROM public.produtos_padronizacao pp
              WHERE pp.id = v_par.id AND pp.raw_id IS NOT NULL);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END;
  END LOOP;

  -- SWEEP 2026-06-11: variantes 'standardized' órfãs (pai já no Gold).
  -- Cobre backfills e re-padronizações fora do fluxo raw 'pending'.
  FOR v_par IN
    SELECT DISTINCT pv.parent_reference AS supplier_reference
    FROM public.produtos_padronizacao_variantes pv
    JOIN public.products p
      ON p.supplier_id = pv.supplier_id
     AND p.supplier_reference = pv.parent_reference
    WHERE pv.supplier_id = p_supplier_id
      AND pv.status = 'standardized'
      AND NULLIF(pv.parent_reference, '') IS NOT NULL
  LOOP
    BEGIN
      v_vres := public.fn_promote_variants_of_parent(p_supplier_id, v_par.supplier_reference);
      IF NOT COALESCE((v_vres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'sweep_falhou:%', COALESCE(v_vres->>'error','desconhecido');
      END IF;
      v_orfas := v_orfas + COALESCE((v_vres->>'variantes_promovidas')::int, 0);
    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra
          || jsonb_build_object('ref', v_par.supplier_reference, 'stage', 'sweep', 'erro', SQLERRM);
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'supplier_id', p_supplier_id,
    'pais_promovidos', v_pais, 'pais_novos', v_novos, 'variantes_promovidas', v_var,
    'variantes_orfas_promovidas', v_orfas,
    'erros', v_erros, 'amostra_erros', v_err_amostra,
    'segundos', round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1));
END $function$;

COMMENT ON FUNCTION public.fn_promote_supplier(uuid, integer) IS
  'Orquestrador Silver->Gold por fornecedor. Promove pais standardized (atomico pai+variantes) e, '
  'desde 2026-06-11, faz sweep de variantes standardized orfas cujo pai ja esta no Gold '
  '(backfills/re-padronizacoes). NULL-safe, idempotente.';

-- <<< END 20260611121000_fn_promote_supplier_sweep_orphan_variants.sql <<<

-- >>> BEGIN 20260611123000_pipeline_hardening_validation_clamps.sql >>>
-- ════════════════════════════════════════════════════════════════
-- HARDENING DA PADRONIZAÇÃO — achados da simulação massiva 2026-06-11
-- ════════════════════════════════════════════════════════════════
-- ACHADO #4 (sucesso falso / pai pendente eterno):
--   fn_standardize_raw deixava o pai com status='pending' quando os
--   mappings não produziam campos, retornando success=true. O pai
--   nunca era promovido nem rejeitado; os raws do grupo ficavam
--   'pending' para sempre, invisíveis ao monitoramento.
--   FIX: pós-UPDATE, name NULL ⇒ status 'rejected' + validation_errors
--   explicando; senão 'standardized'. Retorno success=false quando
--   rejected (fn_standardize_supplier passa a contabilizar e amostrar).
--   Além disso, fallback genérico de name (nome/Name/titulo/...) quando
--   o de-para não produz name — fornecedores novos funcionam no modo
--   genérico completo (variante + pai) sem mapping cadastrado.
--
-- ACHADO #5 (overflow numérico na promoção):
--   cost 1e99 passava pela padronização (Silver numeric ilimitado) e
--   estourava em products.cost_price numeric(10,2) na promoção,
--   prendendo o pai em 'standardized' com retry eterno.
--   FIX: clamp de domínio na padronização. Pai: custo/sugerido fora de
--   (0, 99999999.99] ⇒ descartado + validation_error. Variante: custo e
--   tiers fora de (0, 999999.9999] (teto do VSS numeric(10,4)) ⇒ NULL.
--   Max real hoje: 826.42 — folga de 3+ ordens de magnitude.
--
-- ACHADO #6 (estoque negativo atravessava ao Gold):
--   Só o branch XBZ clampava GREATEST(0,stock). SPOT -50 chegou a
--   product_variants.stock_quantity na simulação.
--   FIX: clamp universal v_stock := GREATEST(0, v_stock) pós-branches
--   em fn_standardize_variant (o pai já clampava).
-- ════════════════════════════════════════════════════════════════

-- ── (1) fn_standardize_raw: fallback name + clamp money + rejected explícito ──
CREATE OR REPLACE FUNCTION public.fn_standardize_raw(p_raw_id uuid, p_override_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r          public.supplier_products_raw%ROWTYPE;
  m          RECORD;
  v_val      text; v_tx text; v_path text;
  v_assigns  jsonb := '{}'::jsonb;
  v_errs     jsonb := '[]'::jsonb;
  v_ncm text; v_ncm_raw text;
  v_pad_id uuid; v_ref text;
  v_status public.produtos_padronizacao_status;
  v_final_name text;
  v_money numeric;
  v_cols text[] := ARRAY[
    'name','description','short_description','cost_price','suggested_price','stock_quantity',
    'primary_image_url','images','ncm_code','weight_g','height_cm','width_cm','length_cm',
    'dimensions_display','box_length_cm','box_width_cm','box_height_cm','box_weight_kg',
    'box_volume_cm3','box_quantity','box_inner_quantity','brand','packing_type','repacking_type',
    'capacities','capacity_ml','min_quantity','ipi_rate','engraving_type','is_active',
    'product_type','origin_country','combined_sizes','box_image',
    'is_textil','is_stockout','is_online_exclusive','is_new','has_colors','has_sizes',
    'allows_personalization','tags','materials','meta_keywords'
  ];
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado'); END IF;
  v_ref := COALESCE(NULLIF(TRIM(p_override_reference),''), r.supplier_reference);

  FOR m IN
    SELECT source_field, source_path, target_field, transform_type, transform_config, source_unit, target_unit
    FROM public.supplier_field_mappings
    WHERE supplier_id=r.supplier_id AND target_table='products' AND is_active=TRUE AND target_field=ANY(v_cols)
    ORDER BY priority NULLS LAST
  LOOP
    BEGIN
      IF m.source_path IS NOT NULL AND m.source_path <> '' THEN
        v_path := regexp_replace(m.source_path, E'^\\$\\.?', '');
        v_val  := r.raw_data #>> string_to_array(v_path, '.');
      ELSE
        v_val := r.raw_data ->> m.source_field;
      END IF;

      IF v_val IS NULL THEN CONTINUE; END IF;

      v_tx := public.fn_apply_transform(
        v_val, m.transform_type, m.transform_config,
        m.source_unit, m.target_unit,
        r.supplier_id
      );

      v_assigns := v_assigns || jsonb_build_object(m.target_field, v_tx);
    EXCEPTION WHEN OTHERS THEN
      v_errs := v_errs || jsonb_build_object('field', m.target_field, 'error', SQLERRM);
    END;
  END LOOP;

  -- FALLBACK genérico de name (2026-06-11): de-para não produziu name ⇒
  -- tenta chaves convencionais. Fornecedor novo roda no modo genérico.
  IF NULLIF(TRIM(v_assigns->>'name'),'') IS NULL THEN
    v_val := COALESCE(
      NULLIF(TRIM(r.raw_data->>'nome'),''),
      NULLIF(TRIM(r.raw_data->>'Nome'),''),
      NULLIF(TRIM(r.raw_data->>'name'),''),
      NULLIF(TRIM(r.raw_data->>'Name'),''),
      NULLIF(TRIM(r.raw_data->>'titulo'),''),
      NULLIF(TRIM(r.raw_data->>'Titulo'),''));
    IF v_val IS NOT NULL THEN
      v_assigns := v_assigns || jsonb_build_object('name', v_val);
    END IF;
  END IF;

  -- CLAMP money (2026-06-11): fora de (0, 99999999.99] não entra na Silver
  -- (products.cost_price é numeric(10,2); evita overflow na promoção).
  FOREACH v_val IN ARRAY ARRAY['cost_price','suggested_price'] LOOP
    IF v_assigns ? v_val THEN
      v_money := public.fn_safe_num(v_assigns->>v_val);
      IF v_money IS NOT NULL AND (v_money < 0 OR v_money > 99999999.99) THEN
        v_assigns := v_assigns - v_val;
        v_errs := v_errs || jsonb_build_object('field', v_val, 'error',
          'valor_fora_do_dominio: '||v_money::text);
      END IF;
    END IF;
  END LOOP;

  -- NCM: normaliza; inválido (placeholder/formatos quebrados) é removido
  v_ncm_raw := COALESCE(v_assigns->>'ncm_code', r.raw_data->>'Ncm', r.raw_data->>'ncm');
  IF v_ncm_raw IS NOT NULL THEN
    v_ncm := public.fn_normalize_ncm(v_ncm_raw);
    IF v_ncm IS NOT NULL THEN
      v_assigns := v_assigns || jsonb_build_object('ncm_code', v_ncm);
    ELSE
      v_assigns := v_assigns - 'ncm_code';
    END IF;
  END IF;

  SELECT id INTO v_pad_id FROM public.produtos_padronizacao
  WHERE supplier_id = r.supplier_id AND supplier_reference = v_ref;

  IF v_pad_id IS NULL THEN
    INSERT INTO public.produtos_padronizacao
      (supplier_id, supplier_reference, raw_id, status)
    VALUES (r.supplier_id, v_ref, r.id, 'pending')
    RETURNING id INTO v_pad_id;
  END IF;

  -- BRAND PERMANENTE: sempre nome do supplier na Silver
  v_assigns := v_assigns || jsonb_build_object(
    'brand', public.fn_brand_from_supplier(r.supplier_id)
  );

  -- Clamp: stock negativo → 0
  IF (v_assigns->>'stock_quantity') IS NOT NULL
    AND public.fn_safe_num(v_assigns->>'stock_quantity') IS NOT NULL
    AND public.fn_safe_num(v_assigns->>'stock_quantity') < 0 THEN
    v_assigns := v_assigns || jsonb_build_object('stock_quantity', 0);
  END IF;

  UPDATE public.produtos_padronizacao
  SET
    name               = COALESCE(public.fn_normalize_product_name(v_assigns->>'name'), name),
    description        = COALESCE((v_assigns->>'description')::text,                                   description),
    short_description  = COALESCE((v_assigns->>'short_description')::text,                             short_description),
    cost_price         = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'cost_price'),      0),        cost_price),
    suggested_price    = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'suggested_price'), 0),        suggested_price),
    stock_quantity     = COALESCE(public.fn_safe_int(v_assigns->>'stock_quantity'),                     stock_quantity),
    primary_image_url  = COALESCE((v_assigns->>'primary_image_url')::text,                             primary_image_url),
    images             = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'images'),                       images),
    ncm_code           = COALESCE((v_assigns->>'ncm_code')::text,                                      ncm_code),
    weight_g           = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'weight_g'),  0),              weight_g),
    height_cm          = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'height_cm'), 0),              height_cm),
    width_cm           = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'width_cm'),  0),              width_cm),
    length_cm          = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'length_cm'), 0),              length_cm),
    dimensions_display = COALESCE((v_assigns->>'dimensions_display')::text,                            dimensions_display),
    box_length_cm      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_length_cm'), 0),          box_length_cm),
    box_width_cm       = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_width_cm'),  0),          box_width_cm),
    box_height_cm      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_height_cm'), 0),          box_height_cm),
    box_weight_kg      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_weight_kg'), 0),          box_weight_kg),
    box_volume_cm3     = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_volume_cm3'),0),          box_volume_cm3),
    box_quantity       = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'box_quantity'), 0),           box_quantity),
    box_inner_quantity = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'box_inner_quantity'), 0),     box_inner_quantity),
    brand              = COALESCE((v_assigns->>'brand')::text,                                          brand),
    packing_type       = COALESCE((v_assigns->>'packing_type')::text,                                   packing_type),
    repacking_type     = COALESCE((v_assigns->>'repacking_type')::text,                                 repacking_type),
    capacities         = COALESCE((v_assigns->>'capacities')::text,                                     capacities),
    capacity_ml        = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'capacity_ml'), 0),            capacity_ml),
    min_quantity       = COALESCE(public.fn_safe_int(v_assigns->>'min_quantity'),                       min_quantity),
    ipi_rate           = COALESCE(public.fn_safe_num(v_assigns->>'ipi_rate'),                           ipi_rate),
    engraving_type     = COALESCE((v_assigns->>'engraving_type')::text,                                 engraving_type),
    is_active          = COALESCE(public.fn_safe_bool(v_assigns->>'is_active'),                         is_active),
    product_type       = COALESCE((v_assigns->>'product_type')::text,                                   product_type),
    origin_country     = COALESCE((v_assigns->>'origin_country')::text,                                 origin_country),
    combined_sizes     = COALESCE((v_assigns->>'combined_sizes')::text,                                 combined_sizes),
    box_image          = COALESCE((v_assigns->>'box_image')::text,                                      box_image),
    is_textil              = COALESCE(public.fn_safe_bool(v_assigns->>'is_textil'),              is_textil),
    is_stockout            = COALESCE(public.fn_safe_bool(v_assigns->>'is_stockout'),            is_stockout),
    is_online_exclusive    = COALESCE(public.fn_safe_bool(v_assigns->>'is_online_exclusive'),    is_online_exclusive),
    is_new                 = COALESCE(public.fn_safe_bool(v_assigns->>'is_new'),                 is_new),
    has_colors             = COALESCE(public.fn_safe_bool(v_assigns->>'has_colors'),             has_colors),
    has_sizes              = COALESCE(public.fn_safe_bool(v_assigns->>'has_sizes'),              has_sizes),
    allows_personalization = COALESCE(public.fn_safe_bool(v_assigns->>'allows_personalization'), allows_personalization),
    tags               = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'tags'),                         tags),
    materials          = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'materials'),                    materials),
    meta_keywords      = COALESCE(public.fn_safe_text_arr(v_assigns->>'meta_keywords'),                 meta_keywords),
    raw_id             = r.id,
    updated_at         = now()
  WHERE id = v_pad_id
  RETURNING name INTO v_final_name;

  -- STATUS EXPLÍCITO (2026-06-11): name resolvido ⇒ standardized;
  -- sem name ⇒ rejected COM motivo. 'pending' deixa de existir
  -- pós-padronização (era invisível e nunca promovia).
  IF v_final_name IS NOT NULL AND TRIM(v_final_name) <> '' THEN
    v_status := 'standardized';
  ELSE
    v_status := 'rejected';
    v_errs := v_errs || jsonb_build_object('field','name','error',
      'name_ausente: nenhum mapping/fallback produziu nome');
  END IF;

  UPDATE public.produtos_padronizacao
  SET status            = v_status,
      standardized_at   = CASE WHEN v_status='standardized' THEN now() ELSE standardized_at END,
      validation_errors = CASE WHEN jsonb_array_length(v_errs) > 0 THEN v_errs ELSE NULL END
  WHERE id = v_pad_id;

  -- Enriquecimento canônico (só preenche NULLs): ipi/ncm/materials/tags/meta/description
  PERFORM public.fn_enrich_padronizacao(v_pad_id);

  RETURN jsonb_build_object(
    'success', v_status = 'standardized', 'pad_id', v_pad_id,
    'status', v_status, 'fields_set', v_assigns,
    'errors', v_errs
  );
END;
$function$;

COMMENT ON FUNCTION public.fn_standardize_raw(uuid, text) IS
  'Bronze->Silver (produto/pai) via de-para supplier_field_mappings + fallback generico de name. '
  '2026-06-11: clamp money (0,1e8]; sem name => rejected + validation_errors + success=false '
  '(antes ficava pending invisivel com success=true).';

-- ── (2) fn_standardize_variant: clamps universais de estoque e custo ──
-- (corpo idêntico ao de 20260611120000 + clamps pós-branches)

CREATE OR REPLACE FUNCTION public.fn_standardize_variant(p_raw_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r             public.supplier_products_raw%ROWTYPE;
  v_parent      text; v_code text; v_apiid text; v_cname text; v_chex text;
  v_col         RECORD;
  v_sku         text; v_supplier_sku text; v_stock integer; v_cost numeric; v_var_id uuid;
  v_fname       text; v_fcode text; v_fhex text; v_canonical_id uuid;
  v_cp1 numeric; v_cp2 numeric; v_cp3 numeric; v_cp4 numeric; v_cp5 numeric;
  v_mq1 int;    v_mq2 int;    v_mq3 int;    v_mq4 int;    v_mq5 int;
  v_nq1 int;    v_nq2 int;    v_nq3 int;
  v_nd1 date;   v_nd2 date;   v_nd3 date;
  v_mult        int;
  v_thumb       text;
  v_images      jsonb;
  v_videos      jsonb;
  v_cap_ml      int;
  v_SPOT        uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ         uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA        uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM          uuid := '841cd690-210a-422a-908c-7676828db272';
  m             RECORD; v_val text; v_tx text;
  v_pv_assigns  jsonb := '{}'::jsonb;
  v_vss_assigns jsonb := '{}'::jsonb;
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','raw_nao_encontrado'); END IF;
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  IF r.supplier_id = v_SPOT THEN
    FOR m IN SELECT sfm.source_field,sfm.target_field,sfm.target_table,sfm.transform_type,sfm.transform_config,sfm.source_unit,sfm.target_unit
             FROM public.supplier_field_mappings sfm
             WHERE sfm.supplier_id=v_SPOT AND sfm.target_table IN('product_variants','variant_supplier_sources')
               AND sfm.is_active=TRUE AND sfm.target_field NOT IN('color_id','size_id','web_sku','length_cm','width_cm')
             ORDER BY sfm.target_table,sfm.priority NULLS LAST LOOP
      v_val:=CASE WHEN m.transform_config->>'source_blob'='stock_data' THEN r.stock_data->>m.source_field ELSE r.raw_data->>m.source_field END;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';
      BEGIN v_tx:=public.fn_apply_transform(v_val,m.transform_type,m.transform_config,m.source_unit,m.target_unit,v_SPOT);
      EXCEPTION WHEN OTHERS THEN v_tx:=v_val; END;
      CONTINUE WHEN v_tx IS NULL;
      IF m.target_table='product_variants' THEN v_pv_assigns:=v_pv_assigns||jsonb_build_object(m.target_field,v_tx);
      ELSE v_vss_assigns:=v_vss_assigns||jsonb_build_object(m.target_field,v_tx); END IF;
    END LOOP;
    v_supplier_sku:=v_pv_assigns->>'supplier_sku'; v_code:=v_pv_assigns->>'color_code';
    v_cname:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_name'),''),r.raw_data->>'ColorDesc1');
    v_chex:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_hex'),''),r.raw_data->>'ColorHex1');
    v_thumb:=COALESCE(v_pv_assigns->>'selected_thumbnail',v_vss_assigns->>'supplier_thumbnail');
    v_sku:=r.supplier_reference;
    BEGIN v_images:=COALESCE(CASE WHEN v_pv_assigns?'images' THEN(v_pv_assigns->>'images')::jsonb END,CASE WHEN v_vss_assigns?'supplier_images' THEN(v_vss_assigns->>'supplier_images')::jsonb END,'[]'::jsonb); EXCEPTION WHEN OTHERS THEN v_images:='[]'::jsonb; END;
    BEGIN v_videos:=CASE WHEN v_vss_assigns?'supplier_videos' THEN(v_vss_assigns->>'supplier_videos')::jsonb END; EXCEPTION WHEN OTHERS THEN v_videos:=NULL; END;
    v_stock:=public.fn_safe_int(COALESCE(v_vss_assigns->>'quantity',v_vss_assigns->>'stock_main_warehouse',r.stock_data->>'Quantity',r.raw_data->>'StockQuantity'));
    v_cost:=public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price',r.raw_data->>'Price1'));
    v_cp1:=public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price_1',r.raw_data->>'Price1'));
    v_cp2:=public.fn_safe_num(v_vss_assigns->>'cost_price_2'); v_cp3:=public.fn_safe_num(v_vss_assigns->>'cost_price_3');
    v_cp4:=public.fn_safe_num(v_vss_assigns->>'cost_price_4'); v_cp5:=public.fn_safe_num(v_vss_assigns->>'cost_price_5');
    v_mq1:=public.fn_safe_int(v_vss_assigns->>'min_qty_1'); v_mq2:=public.fn_safe_int(v_vss_assigns->>'min_qty_2');
    v_mq3:=public.fn_safe_int(v_vss_assigns->>'min_qty_3'); v_mq4:=public.fn_safe_int(v_vss_assigns->>'min_qty_4'); v_mq5:=public.fn_safe_int(v_vss_assigns->>'min_qty_5');
    v_mult:=public.fn_safe_int(COALESCE(v_vss_assigns->>'sale_multiplier',r.raw_data->>'Multiplier'));
    v_nq1:=public.fn_safe_int(v_vss_assigns->>'next_quantity_1'); v_nq2:=public.fn_safe_int(v_vss_assigns->>'next_quantity_2'); v_nq3:=public.fn_safe_int(v_vss_assigns->>'next_quantity_3');
    v_nd1:=CASE WHEN v_vss_assigns->>'next_date_1'~'^\d{4}-\d{2}-\d{2}' THEN LEFT(v_vss_assigns->>'next_date_1',10)::date END;
    v_nd2:=CASE WHEN v_vss_assigns->>'next_date_2'~'^\d{4}-\d{2}-\d{2}' THEN LEFT(v_vss_assigns->>'next_date_2',10)::date END;
    v_nd3:=CASE WHEN v_vss_assigns->>'next_date_3'~'^\d{4}-\d{2}-\d{2}' THEN LEFT(v_vss_assigns->>'next_date_3',10)::date END;

  ELSIF r.supplier_id = v_SM THEN
    FOR m IN SELECT sfm.source_field,sfm.target_field,sfm.target_table,sfm.transform_type,sfm.transform_config,sfm.source_unit,sfm.target_unit
             FROM public.supplier_field_mappings sfm
             WHERE sfm.supplier_id=v_SM AND sfm.target_table IN('product_variants','variant_supplier_sources') AND sfm.is_active=TRUE
             ORDER BY sfm.target_table,sfm.priority NULLS LAST LOOP
      v_val:=CASE WHEN m.transform_config->>'source_blob'='stock_data' THEN r.stock_data->>m.source_field ELSE r.raw_data->>m.source_field END;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';
      BEGIN v_tx:=public.fn_apply_transform(v_val,m.transform_type,m.transform_config,m.source_unit,m.target_unit,v_SM); EXCEPTION WHEN OTHERS THEN v_tx:=v_val; END;
      CONTINUE WHEN v_tx IS NULL;
      IF m.target_table='product_variants' THEN v_pv_assigns:=v_pv_assigns||jsonb_build_object(m.target_field,v_tx);
      ELSE v_vss_assigns:=v_vss_assigns||jsonb_build_object(m.target_field,v_tx); END IF;
    END LOOP;
    v_cname:=public.fn_extract_color_from_title(r.raw_data->>'titulo');
    v_chex:=(SELECT split_part(item,'|',2) FROM unnest(string_to_array(r.raw_data->>'produtos_similares',';')) item WHERE split_part(item,'|',1)=r.supplier_reference AND split_part(item,'|',2)~*'^#[0-9a-f]{6}$' LIMIT 1);
    v_supplier_sku:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'supplier_sku'),''),r.supplier_reference);
    v_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(COALESCE(v_pv_assigns->>'stock_quantity',r.raw_data->>'estoque'));
    v_cost:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price',r.raw_data->>'preco_sem_gravacao_sem_impostos'));
    v_cp1:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_1',r.raw_data->>'preco_sem_gravacao_sem_impostos'));
    v_cp2:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_2',r.raw_data->>'preco_com_gravacao_sem_impostos'));
    v_cp3:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_3',r.raw_data->>'preco_sem_gravacao_com_impostos'));
    v_cp4:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_4',r.raw_data->>'preco_com_gravacao_com_impostos'));
    v_mq1:=public.fn_safe_int(COALESCE(v_pv_assigns->>'min_qty_1',r.raw_data->>'quantidade_minima_sugerida'));
    v_thumb:=NULLIF(TRIM(COALESCE(v_pv_assigns->>'supplier_thumbnail',r.raw_data->>'url_foto')),'');
    BEGIN v_images:=CASE WHEN v_pv_assigns?'supplier_images' THEN(v_pv_assigns->>'supplier_images')::jsonb ELSE NULL END; EXCEPTION WHEN OTHERS THEN v_images:=NULL; END;

  ELSIF r.supplier_id = v_XBZ THEN
    v_apiid        := r.raw_data->>'CorWebPrincipalId';
    v_cname        := r.raw_data->>'CorWebPrincipal';
    v_supplier_sku := r.raw_data->>'CodigoComposto';
    v_stock        := GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel'),0));
    v_cost         := public.fn_safe_num(r.raw_data->>'PrecoVenda');
    v_sku          := 'XBZ-'||r.supplier_reference;
    v_mult         := CASE WHEN public.fn_safe_int(r.raw_data->>'Multiplos')>0 THEN public.fn_safe_int(r.raw_data->>'Multiplos') ELSE NULL END;
    v_mq1          := CASE WHEN public.fn_safe_int(r.raw_data->>'VendaMinima')>0 THEN public.fn_safe_int(r.raw_data->>'VendaMinima') ELSE NULL END;
    v_cap_ml := CASE
        WHEN r.raw_data->>'Nome' IS NOT NULL
         AND r.raw_data->>'Nome' !~* '(127v|220v|led|lampada|lâmpada|pisca)'
        THEN public.extract_capacity_ml(r.raw_data->>'Nome')
        ELSE NULL
    END;
    v_thumb := CASE
        WHEN r.raw_data->>'ImageLink' LIKE 'https://%' OR r.raw_data->>'ImageLink' LIKE 'http://%' THEN r.raw_data->>'ImageLink'
        WHEN r.raw_data->>'ImageLink' LIKE 'hhttps://%' THEN SUBSTRING(r.raw_data->>'ImageLink' FROM 2)
        WHEN r.raw_data->>'ImageLink' LIKE 'htt%brindes.com.br%' THEN 'https://cdn.xbzbrindes.com.br'||SUBSTRING(r.raw_data->>'ImageLink' FROM POSITION('brindes.com.br' IN r.raw_data->>'ImageLink')+14)
        ELSE NULL END;
    BEGIN v_images:=CASE WHEN r.site_data->'imagens' IS NOT NULL AND jsonb_array_length(r.site_data->'imagens')>0 THEN r.site_data->'imagens' ELSE NULL END; EXCEPTION WHEN OTHERS THEN v_images:=NULL; END;
    BEGIN v_videos:=CASE WHEN (r.site_data->'video'->>'indicador')::boolean=true AND r.site_data->'video'->>'embed_id' IS NOT NULL
        THEN jsonb_build_array(jsonb_build_object('embed_id',r.site_data->'video'->>'embed_id','embed_url',r.site_data->'video'->>'embed_url','watch_url',r.site_data->'video'->>'watch_url','plataforma','youtube','indicador',true))
        ELSE NULL END; EXCEPTION WHEN OTHERS THEN v_videos:=NULL; END;
    v_nd1:=CASE WHEN r.raw_data->>'ReposicaoDataPrevista' IS NOT NULL AND LEFT(r.raw_data->>'ReposicaoDataPrevista',4)!='0001' THEN LEFT(r.raw_data->>'ReposicaoDataPrevista',10)::date ELSE NULL END;
    v_nq1:=CASE WHEN r.raw_data->>'QuantidadeDisponivelEstoquePrincipal' IS NOT NULL AND GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel'),0))>GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivelEstoquePrincipal'),0)) THEN GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel'),0)-GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivelEstoquePrincipal'),0))) ELSE NULL END;

  ELSIF r.supplier_id = v_ASIA THEN
    v_cname:=r.raw_data->>'var_cor_nome'; v_chex:=r.raw_data->>'var_cor_hex';
    v_supplier_sku:=COALESCE(r.raw_data->>'var_referencia',r.supplier_reference);
    v_stock:=public.fn_safe_int(COALESCE(r.stock_data->>'qtd_estoque',r.raw_data->>'var_estoque'));
    v_cost:=public.fn_safe_num(r.raw_data->>'preco'); v_sku:='ASIA-'||r.supplier_reference;
    v_nd1:=CASE WHEN COALESCE(r.stock_data->'previsao_entrega'->0->>'data',r.raw_data->'previsao_entrega'->0->>'data')~'^\d{4}-\d{2}-\d{2}' THEN LEFT(COALESCE(r.stock_data->'previsao_entrega'->0->>'data',r.raw_data->'previsao_entrega'->0->>'data'),10)::date END;
    v_nq1:=public.fn_safe_int(COALESCE(r.stock_data->'previsao_entrega'->0->>'quantidade',r.raw_data->'previsao_entrega'->0->>'quantidade'));
  ELSE
    v_cname:=r.raw_data->>'cor'; v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque'); v_cost:=public.fn_safe_num(r.raw_data->>'preco_base'); v_sku:=r.supplier_reference;
  END IF;

  -- CLAMPS universais (2026-06-11, achados #5/#6 da simulação):
  -- estoque negativo não existe no domínio; custo fora de (0, 999999.9999]
  -- (teto do VSS numeric(10,4)) é lixo de feed e não entra na Silver.
  v_stock := GREATEST(0, v_stock);
  IF v_cost  IS NOT NULL AND (v_cost  < 0 OR v_cost  > 999999.9999) THEN v_cost  := NULL; END IF;
  IF v_cp1   IS NOT NULL AND (v_cp1   < 0 OR v_cp1   > 999999.9999) THEN v_cp1   := NULL; END IF;
  IF v_cp2   IS NOT NULL AND (v_cp2   < 0 OR v_cp2   > 999999.9999) THEN v_cp2   := NULL; END IF;
  IF v_cp3   IS NOT NULL AND (v_cp3   < 0 OR v_cp3   > 999999.9999) THEN v_cp3   := NULL; END IF;
  IF v_cp4   IS NOT NULL AND (v_cp4   < 0 OR v_cp4   > 999999.9999) THEN v_cp4   := NULL; END IF;
  IF v_cp5   IS NOT NULL AND (v_cp5   < 0 OR v_cp5   > 999999.9999) THEN v_cp5   := NULL; END IF;

  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id,v_code,v_apiid,v_cname,v_chex);
  -- FIX 2026-06-11: as 3 atribuições abaixo estavam na MESMA linha de um
  -- comentário `--` (patch 2026-06-09) e nunca executavam; color_code e
  -- color_hex saíam NULL. Agora em linhas próprias.
  v_fname:=public.fn_normalize_product_name(COALESCE(v_col.color_name,v_cname));
  v_fcode:=COALESCE(v_col.color_code,v_code);
  v_fhex:=COALESCE(v_col.color_hex,v_chex);
  -- SPOT CANONICAL CODE GUARD (pipeline-proof 2026-06-09):
  -- Preserva código 3-dígitos da API (ex: '103') quando fn_match_supplier_color
  -- retorna código legado 2-dígitos via fallback de nome (ex: '03').
  IF r.supplier_id = v_SPOT AND v_code IS NOT NULL
     AND length(v_code) = 3 AND COALESCE(length(v_fcode), 0) < 3 THEN
    v_fcode := v_code;
  END IF;
  v_canonical_id:=public.fn_match_canonical_color(v_fname,v_fhex);

  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id,supplier_id,parent_reference,variant_reference,sku,supplier_sku,color_name,color_code,color_hex,color_id,
    stock_quantity,cost_price,is_active,status,capacity_ml,
    cost_price_1,cost_price_2,cost_price_3,cost_price_4,cost_price_5,
    min_qty_1,min_qty_2,min_qty_3,min_qty_4,min_qty_5,
    next_quantity_1,next_quantity_2,next_quantity_3,next_date_1,next_date_2,next_date_3,
    sale_multiplier,supplier_thumbnail,supplier_images,supplier_videos
  ) VALUES (
    r.id,r.supplier_id,v_parent,r.supplier_reference,v_sku,v_supplier_sku,v_fname,v_fcode,v_fhex,v_canonical_id,
    v_stock,v_cost,true,'standardized'::public.produtos_padronizacao_status,v_cap_ml,
    v_cp1,v_cp2,v_cp3,v_cp4,v_cp5,
    v_mq1,v_mq2,v_mq3,v_mq4,v_mq5,
    v_nq1,v_nq2,v_nq3,v_nd1,v_nd2,v_nd3,
    v_mult,v_thumb,v_images,v_videos
  )
  ON CONFLICT (supplier_id,variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id,parent_reference=EXCLUDED.parent_reference,sku=EXCLUDED.sku,supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name,color_code=EXCLUDED.color_code,color_hex=EXCLUDED.color_hex,
    color_id=COALESCE(EXCLUDED.color_id,pv.color_id),
    stock_quantity=EXCLUDED.stock_quantity,cost_price=EXCLUDED.cost_price,is_active=EXCLUDED.is_active,status=EXCLUDED.status,
    capacity_ml=COALESCE(EXCLUDED.capacity_ml, pv.capacity_ml),
    cost_price_1=EXCLUDED.cost_price_1,cost_price_2=EXCLUDED.cost_price_2,cost_price_3=EXCLUDED.cost_price_3,
    cost_price_4=EXCLUDED.cost_price_4,cost_price_5=EXCLUDED.cost_price_5,
    min_qty_1=EXCLUDED.min_qty_1,min_qty_2=EXCLUDED.min_qty_2,min_qty_3=EXCLUDED.min_qty_3,
    min_qty_4=EXCLUDED.min_qty_4,min_qty_5=EXCLUDED.min_qty_5,
    next_quantity_1=EXCLUDED.next_quantity_1,next_quantity_2=EXCLUDED.next_quantity_2,next_quantity_3=EXCLUDED.next_quantity_3,
    next_date_1=EXCLUDED.next_date_1,next_date_2=EXCLUDED.next_date_2,next_date_3=EXCLUDED.next_date_3,
    sale_multiplier=EXCLUDED.sale_multiplier,
    supplier_thumbnail=EXCLUDED.supplier_thumbnail,supplier_images=EXCLUDED.supplier_images,supplier_videos=EXCLUDED.supplier_videos,
    updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object(
    'success',true,'variante_id',v_var_id,'parent',v_parent,'cor',v_fname,
    'capacity_ml',v_cap_ml,'thumbnail',v_thumb IS NOT NULL,
    'images_count',CASE WHEN v_images IS NOT NULL THEN jsonb_array_length(v_images) ELSE 0 END,
    'has_video',v_videos IS NOT NULL,'cost_price',v_cost,'sale_multiplier',v_mult,'min_qty_1',v_mq1,
    'next_date_1',v_nd1,'next_quantity_1',v_nq1
  );
END;
$function$;

COMMENT ON FUNCTION public.fn_standardize_variant(uuid) IS
  'Bronze->Silver (variante). De-para p/ SPOT e SM; hardcoded XBZ/Asia; fallback generico. '
  '2026-06-11: clamps universais GREATEST(0,stock) e custo (0,999999.9999] (achados #5/#6).';

-- ── (3) fn_standardize_variant: ELSE genérico vira leitor de-para (Fase 6) ──
-- Fornecedores sem branch dedicado (ex.: 88 Brindes) liam apenas chaves fixas
-- (cor/estoque/preco_base) e ignoravam seus supplier_field_mappings — 40
-- variantes do 88B sem custo/thumbnail. Injeção idempotente no fonte vivo
-- (aborta se o anchor não for encontrado byte a byte; no-op se já aplicado).
DO $$
DECLARE
  v_src text;
  v_old text := E'  ELSE\n'
    || E'    v_cname:=r.raw_data->>''cor''; v_supplier_sku:=r.supplier_reference;\n'
    || E'    v_stock:=public.fn_safe_int(r.raw_data->>''estoque''); v_cost:=public.fn_safe_num(r.raw_data->>''preco_base''); v_sku:=r.supplier_reference;\n'
    || E'  END IF;';
  v_new text := E'  ELSE\n'
    || E'    -- DE-PARA genérico (2026-06-11, Fase 6): fornecedores sem branch dedicado\n'
    || E'    -- leem supplier_field_mappings (product_variants/VSS) como SPOT/SM,\n'
    || E'    -- com fallback nas chaves convencionais do feed.\n'
    || E'    FOR m IN SELECT sfm.source_field,sfm.target_field,sfm.target_table,sfm.transform_type,sfm.transform_config,sfm.source_unit,sfm.target_unit\n'
    || E'             FROM public.supplier_field_mappings sfm\n'
    || E'             WHERE sfm.supplier_id=r.supplier_id AND sfm.target_table IN(''product_variants'',''variant_supplier_sources'') AND sfm.is_active=TRUE\n'
    || E'             ORDER BY sfm.target_table,sfm.priority NULLS LAST LOOP\n'
    || E'      v_val:=CASE WHEN m.transform_config->>''source_blob''=''stock_data'' THEN r.stock_data->>m.source_field ELSE r.raw_data->>m.source_field END;\n'
    || E'      CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='''';\n'
    || E'      BEGIN v_tx:=public.fn_apply_transform(v_val,m.transform_type,m.transform_config,m.source_unit,m.target_unit,r.supplier_id); EXCEPTION WHEN OTHERS THEN v_tx:=v_val; END;\n'
    || E'      CONTINUE WHEN v_tx IS NULL;\n'
    || E'      IF m.target_table=''product_variants'' THEN v_pv_assigns:=v_pv_assigns||jsonb_build_object(m.target_field,v_tx);\n'
    || E'      ELSE v_vss_assigns:=v_vss_assigns||jsonb_build_object(m.target_field,v_tx); END IF;\n'
    || E'    END LOOP;\n'
    || E'    v_cname:=COALESCE(NULLIF(TRIM(v_pv_assigns->>''color_name''),''''),r.raw_data->>''cor'');\n'
    || E'    v_chex:=NULLIF(TRIM(v_pv_assigns->>''color_hex''),'''');\n'
    || E'    v_supplier_sku:=COALESCE(NULLIF(TRIM(v_pv_assigns->>''supplier_sku''),''''),NULLIF(TRIM(r.raw_data->>''sku_fornecedor''),''''),r.supplier_reference);\n'
    || E'    v_sku:=COALESCE(NULLIF(TRIM(v_pv_assigns->>''sku''),''''),r.supplier_reference);\n'
    || E'    v_stock:=public.fn_safe_int(COALESCE(v_pv_assigns->>''stock_quantity'',v_vss_assigns->>''quantity'',r.raw_data->>''estoque''));\n'
    || E'    v_cost:=public.fn_safe_num(COALESCE(v_vss_assigns->>''cost_price'',v_pv_assigns->>''cost_price'',r.raw_data->>''preco_custo'',r.raw_data->>''preco_base'',r.raw_data->>''preco''));\n'
    || E'    v_cp1:=v_cost;\n'
    || E'    v_thumb:=NULLIF(TRIM(COALESCE(v_pv_assigns->>''supplier_thumbnail'',v_vss_assigns->>''supplier_thumbnail'',r.raw_data->>''imagem_principal'',r.raw_data->>''url_foto'')),'''');\n'
    || E'  END IF;';
BEGIN
  SELECT pg_get_functiondef(oid) INTO v_src
  FROM pg_proc WHERE proname='fn_standardize_variant' AND pronamespace='public'::regnamespace;
  IF v_src LIKE '%DE-PARA genérico (2026-06-11%' THEN
    RAISE NOTICE 'else de-para já aplicado — no-op'; RETURN;
  END IF;
  IF position(v_old IN v_src) = 0 THEN
    RAISE EXCEPTION 'bloco ELSE não encontrado byte a byte — abortando';
  END IF;
  v_src := replace(v_src, v_old, v_new);
  EXECUTE v_src;
END $$;

-- ── (4) fn_standardize_supplier: erro do pai com status + detalhe ──
-- 'pai_falhou:desconhecido' virava ruído; agora amostra o status real
-- (ex.: rejected) e o primeiro erro de validação.
DO $$
DECLARE v_src text;
BEGIN
  SELECT pg_get_functiondef(oid) INTO v_src
  FROM pg_proc WHERE proname='fn_standardize_supplier' AND pronamespace='public'::regnamespace;
  IF v_src LIKE '%pai_falhou_status%' THEN RAISE NOTICE 'no-op'; RETURN; END IF;
  v_src := replace(v_src,
    $old$RAISE EXCEPTION 'pai_falhou:%', COALESCE(v_pres->>'error', 'desconhecido');$old$,
    $new$RAISE EXCEPTION 'pai_falhou_status_%: %', COALESCE(v_pres->>'status','?'),
          COALESCE(v_pres->>'error', v_pres->'errors'->0->>'error', 'sem_detalhe');$new$);
  EXECUTE v_src;
END $$;

-- <<< END 20260611123000_pipeline_hardening_validation_clamps.sql <<<

-- >>> BEGIN 20260611124000_fn_dryrun_standardize_supplier_real_rollback.sql >>>
-- ════════════════════════════════════════════════════════════════
-- fn_dryrun_standardize_supplier: dry-run DE VERDADE (rollback).
-- ════════════════════════════════════════════════════════════════
-- A versão anterior tinha nome de dry-run mas ESCREVIA no Silver
-- (rodava fn_standardize_variant/parent reais, sem reverter, e sem
-- filtrar por status — re-padronizava o catálogo inteiro ao ser
-- chamada "só para ver").
--
-- Agora: executa o pipeline B→S real dentro de um bloco
-- BEGIN/EXCEPTION (subtransação), coleta o preview (contagens e
-- amostra do que mudaria) e dispara exceção sentinela para REVERTER
-- tudo, devolvendo o preview pelo PG_EXCEPTION_DETAIL. Zero efeito
-- colateral, qualquer que seja o resultado.
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_dryrun_standardize_supplier(
    p_supplier_id uuid,
    p_limit       integer DEFAULT 50
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_preview jsonb;
  v_detail  text;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;

  BEGIN
    PERFORM set_config('app.write_source', 'pipeline', true);

    -- Executa o caminho REAL (Bronze→Silver) sobre os pending do fornecedor
    v_preview := jsonb_build_object(
      'standardize', public.fn_standardize_supplier(p_supplier_id, p_limit));

    -- Estado que o Silver TERIA após a execução
    v_preview := v_preview || jsonb_build_object(
      'silver_depois', jsonb_build_object(
        'pais_standardized', (SELECT COUNT(*) FROM public.produtos_padronizacao
           WHERE supplier_id=p_supplier_id AND status='standardized'),
        'pais_rejected', (SELECT COUNT(*) FROM public.produtos_padronizacao
           WHERE supplier_id=p_supplier_id AND status='rejected'),
        'variantes_standardized', (SELECT COUNT(*) FROM public.produtos_padronizacao_variantes
           WHERE supplier_id=p_supplier_id AND status='standardized'),
        'amostra_rejeitados', (SELECT jsonb_agg(jsonb_build_object(
             'ref', p.supplier_reference, 'erros', p.validation_errors))
           FROM (SELECT supplier_reference, validation_errors
                 FROM public.produtos_padronizacao
                 WHERE supplier_id=p_supplier_id AND status='rejected'
                 ORDER BY updated_at DESC LIMIT 5) p)));

    -- Sentinela: aborta a subtransação levando o preview no DETAIL.
    RAISE EXCEPTION 'DRYRUN_ROLLBACK' USING DETAIL = v_preview::text;

  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM = 'DRYRUN_ROLLBACK' THEN
      GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
      RETURN jsonb_build_object(
        'success', true, 'dry_run', true, 'reverted', true,
        'supplier_id', p_supplier_id, 'preview', v_detail::jsonb);
    END IF;
    RETURN jsonb_build_object(
      'success', false, 'dry_run', true, 'reverted', true,
      'supplier_id', p_supplier_id, 'error', SQLERRM);
  END;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) FROM anon;
REVOKE ALL ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) TO postgres;
GRANT EXECUTE ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) TO service_role;

COMMENT ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) IS
  'Dry-run REAL do Bronze->Silver: executa fn_standardize_supplier numa subtransação, '
  'coleta preview (contagens + amostra de rejeitados) e REVERTE tudo via exceção sentinela. '
  '2026-06-11: antes escrevia no Silver apesar do nome.';

-- <<< END 20260611124000_fn_dryrun_standardize_supplier_real_rollback.sql <<<

-- >>> BEGIN 20260611125000_lockdown_pipeline_function_acls.sql >>>
-- ════════════════════════════════════════════════════════════════
-- LOCKDOWN de ACLs das funções do pipeline (advisors 2026-06-11).
-- ════════════════════════════════════════════════════════════════
-- Achado #7 da auditoria: regressões e brechas de EXECUTE em
-- SECURITY DEFINER do pipeline:
--   • fn_standardize_kit_component / fn_promote_kit_component_padronizacao:
--     executáveis por PUBLIC e anon (!) — qualquer visitante podia
--     disparar padronização/promoção de kits.
--   • fn_standardize_supplier: lockdown de 20260605160500 REGREDIU
--     (authenticated=X voltou, provavelmente via default privileges em
--     re-deploy posterior).
--   • fn_pipeline_promote_tick / fn_dryrun_raw_v2 / fn_sm_site_promote:
--     authenticated podia executar (são jobs de cron/ferramentas internas).
-- Contrato: pipeline executável APENAS por postgres + service_role.
-- (Os guards internos de admin continuam como defesa em profundidade.)
-- ════════════════════════════════════════════════════════════════

DO $$
DECLARE
  fn record;
BEGIN
  FOR fn IN
    SELECT format('%I.%I(%s)', n.nspname, p.proname,
                  pg_get_function_identity_arguments(p.oid)) AS sig
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname IN (
        'fn_standardize_supplier',
        'fn_pipeline_promote_tick',
        'fn_dryrun_raw_v2',
        'fn_dryrun_standardize_supplier',
        'fn_standardize_kit_component',
        'fn_promote_kit_component_padronizacao',
        'fn_sm_site_promote')
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', fn.sig);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon', fn.sig);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated', fn.sig);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO postgres', fn.sig);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', fn.sig);
  END LOOP;
END $$;

-- search_path fixo na função apontada pelo advisor (mutable)
ALTER FUNCTION public.fn_sm_site_promote(integer) SET search_path TO 'public', 'extensions';

-- <<< END 20260611125000_lockdown_pipeline_function_acls.sql <<<

-- >>> BEGIN 20260611150000_medallion_front_public_contract_hardening.sql >>>
-- ============================================================================
-- 20260611150000_medallion_front_public_contract_hardening.sql
-- ----------------------------------------------------------------------------
-- Consolida (idempotente) as correcoes M1-M6 aplicadas AO VIVO em
-- doufsxqlfjyuvxuezpln em 2026-06-11 (MCP execute_sql), durante a integracao
-- front-end <-> arquitetura Medallion (Bronze / Prata / Ouro).
--
-- Esta versao foi registrada em supabase_migrations.schema_migrations como
-- MARCADOR (statements referenciam este arquivo homonimo, padrao ja usado no
-- repo), portanto `db push` nao tenta reaplicar. O arquivo e seguro para
-- replay: guards to_regclass + no-op quando ja aplicado.
--
--  M1  v_products_public               + filtro is_active = true (fecha vazamento de 19 inativos/fantasmas)
--  M2  v_variant_sale_prices_public    reescrita SECURITY DEFINER nas tabelas-base (anon: 42501 -> 18.359 rows)
--  M3  v_products_min_price            agrega PRECO DE VENDA (antes expunha CUSTO como min_price e quebrava p/ anon)
--  M4  v_print_area_techniques_public  DEFINER + is_active (anon: 0 -> 21.319 rows)
--  M5  P0  mcp_sessions                fecha leitura/escrita anon (vazava cookie de sessao do portal So Marcas)
--  M6  Bronze/Silver/staging           REVOKE escrita de anon (defense-in-depth; RLS ja bloqueava)
--
-- Validacao: suite T01-T18 como role anon = 18/18 OK + E2E PostgREST com a
-- publishable key de producao. Detalhes: docs/INTEGRACAO_MEDALLION_FRONT.md
-- ============================================================================

-- ----------------------------------------------------------------------------
-- M1 - v_products_public: injeta is_active = true preservando o restante da
-- view (158 colunas). Patch cirurgico sobre pg_get_viewdef; em producao o
-- filtro ja existe => no-op.
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  v_def text;
BEGIN
  IF to_regclass('public.v_products_public') IS NULL THEN
    RAISE NOTICE 'M1: v_products_public nao existe - pulando';
    RETURN;
  END IF;

  SELECT pg_get_viewdef('public.v_products_public'::regclass, true) INTO v_def;

  -- a unica ocorrencia possivel de "is_active = true" nesta view (FROM products
  -- sem joins) e o proprio filtro do WHERE; a projecao apenas lista a coluna.
  IF v_def ~* 'is_active\s*=\s*true' THEN
    RAISE NOTICE 'M1: filtro is_active ja presente em v_products_public - no-op';
    RETURN;
  END IF;

  IF v_def !~* 'is_deleted\s+IS\s+NOT\s+TRUE' THEN
    RAISE EXCEPTION 'M1: marcador WHERE (is_deleted IS NOT TRUE) nao encontrado em v_products_public - revisar manualmente';
  END IF;

  v_def := regexp_replace(v_def, '(is_deleted\s+IS\s+NOT\s+TRUE)', '\1 AND is_active = true', 'i');
  EXECUTE 'CREATE OR REPLACE VIEW public.v_products_public AS ' || v_def;
  RAISE NOTICE 'M1: filtro is_active = true aplicado em v_products_public';
END $$;

-- ----------------------------------------------------------------------------
-- M2 - v_variant_sale_prices_public: reescrita SECURITY DEFINER direto nas
-- tabelas-base. Causa raiz do 42501 anterior: a versao antiga (invoker)
-- delegava para vw_variant_sale_prices, que le suppliers.default_markup_percent
-- sem grant para anon. Tornar a interna DEFINER vazaria custo (anon tem grant
-- nela); a solucao correta e esta view publica calcular o PRECO DE VENDA
-- diretamente, expondo apenas sku/cor/faixas/precos finais (custo nunca sai).
-- Cadeia de markup: variante -> produto -> categoria -> supplier default -> 115%.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_variant_sale_prices_public AS
SELECT pv.id AS variant_id,
    pv.product_id,
    pv.sku,
    pv.color_name,
    vss.min_qty_1,
    round(vss.cost_price_1 * (1::numeric + COALESCE(mc_var.markup_percent, mc_prod.markup_percent, mc_cat.markup_percent, s.default_markup_percent, 115.0) / 100::numeric), 2) AS sale_price_1,
    vss.min_qty_2,
    round(vss.cost_price_2 * (1::numeric + COALESCE(mc_var.markup_percent, mc_prod.markup_percent, mc_cat.markup_percent, s.default_markup_percent, 115.0) / 100::numeric), 2) AS sale_price_2,
    vss.min_qty_3,
    round(vss.cost_price_3 * (1::numeric + COALESCE(mc_var.markup_percent, mc_prod.markup_percent, mc_cat.markup_percent, s.default_markup_percent, 115.0) / 100::numeric), 2) AS sale_price_3,
    vss.min_qty_4,
    round(vss.cost_price_4 * (1::numeric + COALESCE(mc_var.markup_percent, mc_prod.markup_percent, mc_cat.markup_percent, s.default_markup_percent, 115.0) / 100::numeric), 2) AS sale_price_4,
    vss.min_qty_5,
    round(vss.cost_price_5 * (1::numeric + COALESCE(mc_var.markup_percent, mc_prod.markup_percent, mc_cat.markup_percent, s.default_markup_percent, 115.0) / 100::numeric), 2) AS sale_price_5
   FROM public.product_variants pv
     JOIN public.products p ON p.id = pv.product_id AND p.is_active = true AND p.is_deleted IS NOT TRUE
     JOIN public.variant_supplier_sources vss ON vss.variant_id = pv.id AND vss.is_preferred = true
     LEFT JOIN public.suppliers s ON s.id = vss.supplier_id
     LEFT JOIN public.markup_configurations mc_var ON mc_var.variant_id = pv.id AND mc_var.is_active = true
     LEFT JOIN public.markup_configurations mc_prod ON mc_prod.product_id = pv.product_id AND mc_prod.variant_id IS NULL AND mc_prod.category_id IS NULL AND mc_prod.is_active = true
     LEFT JOIN public.markup_configurations mc_cat ON mc_cat.category_id = (( SELECT products.category_id
           FROM public.products
          WHERE products.id = pv.product_id)) AND mc_cat.product_id IS NULL AND mc_cat.variant_id IS NULL AND mc_cat.is_active = true
  WHERE pv.is_active = true;

ALTER VIEW public.v_variant_sale_prices_public SET (security_invoker = false);
GRANT SELECT ON public.v_variant_sale_prices_public TO anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- M3 - v_products_min_price: recriada SOBRE o contrato publico (M2 + view de
-- catalogo). A versao anterior tinha DUPLO defeito: (a) expunha
-- min(vss.cost_price_1) -- CUSTO -- como min_price publico; (b) quebrava para
-- anon com "permission denied for function user_belongs_to_org". Agora agrega
-- PRECO DE VENDA e herda os filtros de catalogo ativo das views publicas.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_products_min_price AS
SELECT vp.product_id,
    p.name,
    p.sku,
    min(vp.sale_price_1) AS min_price,
    max(vp.sale_price_1) AS max_price,
    count(DISTINCT vp.variant_id) AS variants_count
   FROM public.v_variant_sale_prices_public vp
     JOIN public.v_products_public p ON p.id = vp.product_id
  GROUP BY vp.product_id, p.name, p.sku;

ALTER VIEW public.v_products_min_price SET (security_invoker = false);
GRANT SELECT ON public.v_products_min_price TO anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- M4 - v_print_area_techniques_public: a tabela-base print_area_techniques e
-- RLS auth-only (anon = 0 rows). A view publica passa a ser DEFINER com filtro
-- is_active = true, expondo apenas geometria/ordem das areas de gravacao
-- (nada sensivel). anon: 0 -> 21.319 rows.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_print_area_techniques_public AS
SELECT id,
    product_id,
    tabela_preco_id,
    location_code,
    location_name,
    max_width,
    max_height,
    is_curved,
    shape,
    technique_order,
    location_order,
    is_active,
    created_at,
    updated_at
   FROM public.print_area_techniques
  WHERE is_active = true;

ALTER VIEW public.v_print_area_techniques_public SET (security_invoker = false);
GRANT SELECT ON public.v_print_area_techniques_public TO anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- M5 - P0 SEGURANCA - mcp_sessions: as policies mcp_sessions_anon_read /
-- mcp_sessions_anon_write + grants permitiam que QUALQUER visitante lesse (e
-- escrevesse) o cookie de sessao do portal So Marcas via publishable key.
-- Provado por E2E PostgREST antes do fix; depois: 42501. Acesso passa a ser
-- exclusivo de service_role (policy mcp_sessions_service_all preexistente).
-- ----------------------------------------------------------------------------
DO $$
BEGIN
  IF to_regclass('public.mcp_sessions') IS NULL THEN
    RAISE NOTICE 'M5: mcp_sessions nao existe - pulando';
    RETURN;
  END IF;
  EXECUTE 'DROP POLICY IF EXISTS mcp_sessions_anon_read ON public.mcp_sessions';
  EXECUTE 'DROP POLICY IF EXISTS mcp_sessions_anon_write ON public.mcp_sessions';
  EXECUTE 'REVOKE ALL ON public.mcp_sessions FROM anon';
  EXECUTE 'GRANT ALL ON public.mcp_sessions TO service_role';
  RAISE NOTICE 'M5: mcp_sessions fechado para anon (somente service_role)';
END $$;

-- ----------------------------------------------------------------------------
-- M6 - Defense-in-depth Bronze/Silver/staging: revoga ESCRITA de anon. RLS ja
-- bloqueava (nenhuma policy de escrita anon), mas grants de escrita orfaos sao
-- foot-gun. SELECT e mantido deliberadamente (RLS retorna 0 rows; grants de
-- leitura historicamente concedidos para o n8n nao sao mexidos aqui).
-- Guards to_regclass: licao do P1 documentado no MIGRATIONS_SYNC_LOG
-- (REVOKE em tabela production-only aborta replay em DB fresh).
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'supplier_products_raw',
    'produtos_padronizacao_variantes',
    'cf_sm_legacy',
    'sm_upload_mapping',
    'xbz_gallery_staging'
  ] LOOP
    IF to_regclass('public.' || t) IS NOT NULL THEN
      EXECUTE format('REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.%I FROM anon', t);
      RAISE NOTICE 'M6: escrita anon revogada em public.%', t;
    ELSE
      RAISE NOTICE 'M6: public.% nao existe - pulando', t;
    END IF;
  END LOOP;
END $$;

-- <<< END 20260611150000_medallion_front_public_contract_hardening.sql <<<

-- >>> BEGIN 20260611160000_medallion_front_v2_prices_props_compositions_kitmedia_goldhygiene.sql >>>
-- ============================================================================
-- Migration: 20260611160000_medallion_front_v2_prices_props_compositions_kitmedia_goldhygiene
-- Contexto : Integração FRONT ↔ Medallion (Bronze→Prata→Ouro), rodada v2.
--            Continuação de 20260611150000_medallion_front_public_contract_hardening.
-- SSOT      : doufsxqlfjyuvxuezpln (PG17, sa-east-1)
-- Idempotente: CREATE OR REPLACE / REVOKE / GRANT / loop to_regclass.
--
-- O que esta migração versiona (todas já aplicadas ao vivo e validadas — suíte anon 24/24):
--   F2  views públicas DEFINER: v_product_properties_public, v_product_compositions_public,
--       v_kit_component_media_public (+ GRANT SELECT na matview de composições).
--   F3  Higiene Gold: revoga escrita anon órfã em 32 tabelas de catálogo (RLS já bloqueava;
--       isto remove o foot-gun de grant — defense-in-depth).
--   F5  NULLIF de custo-zero no VSS (degrada p/ "sob consulta", nunca R$0,00).
--
-- NOTA sobre F1 (backfill de preço — NÃO incluído como DDL, é data-fix pontual):
--   1.921 variantes preferidas tinham vss.cost_price (singular) preenchido pelo motor,
--   mas vss.cost_price_1 (coluna lida pela view pública de preço) ficou NULL.
--   Correção aplicada: UPDATE variant_supplier_sources SET cost_price_1 = cost_price
--     WHERE is_preferred AND cost_price_1 IS NULL AND cost_price >= 0.10
--     (com SET app.write_source='pipeline' p/ não acionar captura de locked_fields).
--   Resultado: produtos sem preço de variante 1.256 → 349 (os 349 são ASIA site-only,
--   sem Bronze, irrecuperáveis sem novo fetch). Resíduo legítimo "sob consulta": 2.
--   Como é correção de DADOS (não de schema), é reaplicável manualmente mas não faz
--   parte do DDL versionado.
--
-- NOTA sobre REFRESH de matviews: NÃO incluído. O cron job 47
--   (refresh-all-materialized-views, */30) já cobre mv_product_cards e
--   mv_product_compositions com CONCURRENTLY. Infra completa.
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- F2.a — v_product_properties_public
-- Expõe propriedades técnicas/descritivas (ECO_FRIENDLY, BLUETOOTH, capacidade,
-- gravação, fichas) APENAS de produtos ativos. Projeção controlada: NÃO expõe
-- raw_value, property_definition_id nem created/updated. Conteúdo auditado:
-- zero custo/markup (as "suspeitas" %cost% eram a palavra PT "COSTAS/COSTURA").
-- DEFINER pois a tabela-base product_properties é RLS authenticated-only.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_product_properties_public AS
SELECT pp.id,
       pp.product_id,
       pp.property_code,
       pp.property_value,
       pp.source
FROM public.product_properties pp
JOIN public.products p
  ON p.id = pp.product_id
 AND p.is_active = true
 AND p.is_deleted IS NOT TRUE;

ALTER VIEW public.v_product_properties_public SET (security_invoker = false);
GRANT SELECT ON public.v_product_properties_public TO anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- F2.b — v_product_compositions_public
-- Composição de materiais por produto (nome + % de cada material). Mesmo nível
-- de sensibilidade de public.materials_complete (já público). Lê a matview real
-- analytics.mv_product_compositions, filtrando por produto ativo.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_product_compositions_public AS
SELECT mpc.product_id,
       mpc.product_name,
       mpc.total_materials,
       mpc.total_percentage,
       mpc.materials_detail
FROM analytics.mv_product_compositions mpc
JOIN public.products p
  ON p.id = mpc.product_id
 AND p.is_active = true
 AND p.is_deleted IS NOT TRUE;

ALTER VIEW public.v_product_compositions_public SET (security_invoker = false);
GRANT SELECT ON public.v_product_compositions_public TO anon, authenticated, service_role;

-- View trivial cross-schema (public→analytics) é inlineável: o planner aplica
-- permissões do invoker de forma errática mesmo com DEFINER. Conceder SELECT na
-- matview ao anon torna o acesso robusto. Conteúdo = nível-público (materials_complete).
-- anon continua negado de acessar analytics.mv_product_compositions por outras vias
-- (nenhum outro grant), apenas através desta view.
GRANT SELECT ON analytics.mv_product_compositions TO anon;

-- ----------------------------------------------------------------------------
-- F2.c — v_kit_component_media_public
-- Satisfaz a entrada de whitelist "kit_component_media" (que nunca existiu como
-- objeto). A mídia de componente de kit já está embutida em product_kit_components
-- (colunas images + primary_image_url). Esta view expõe essa mídia p/ kits de
-- produtos ativos. (Tabela component_media existe mas está vazia e é auth-only;
-- quando populada, o front pode migrar p/ ela.)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_kit_component_media_public AS
SELECT pkc.id AS kit_component_id,
       pkc.kit_product_id,
       pkc.component_product_id,
       pkc.component_code,
       pkc.component_name,
       pkc.primary_image_url,
       pkc.images,
       pkc.display_order
FROM public.product_kit_components pkc
JOIN public.products p
  ON p.id = pkc.kit_product_id
 AND p.is_active = true
 AND p.is_deleted IS NOT TRUE
WHERE pkc.primary_image_url IS NOT NULL OR pkc.images IS NOT NULL;

ALTER VIEW public.v_kit_component_media_public SET (security_invoker = false);
GRANT SELECT ON public.v_kit_component_media_public TO anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- F5 — NULLIF de custo-zero no VSS
-- Zero é inválido p/ custo de produto físico (mesmo princípio dos campos físicos).
-- cost_price_N = 0 fazia min_price = 0×markup = R$0,00 no catálogo, em vez de
-- degradar p/ "sob consulta" (NULL). Aplicado com write_source=pipeline.
-- ----------------------------------------------------------------------------
SET LOCAL app.write_source = 'pipeline';
UPDATE public.variant_supplier_sources
SET cost_price_1 = NULLIF(cost_price_1, 0),
    cost_price_2 = NULLIF(cost_price_2, 0),
    cost_price_3 = NULLIF(cost_price_3, 0),
    cost_price_4 = NULLIF(cost_price_4, 0),
    cost_price_5 = NULLIF(cost_price_5, 0),
    cost_price   = NULLIF(cost_price, 0)
WHERE cost_price_1 = 0 OR cost_price_2 = 0 OR cost_price_3 = 0
   OR cost_price_4 = 0 OR cost_price_5 = 0 OR cost_price = 0;

COMMIT;

-- ----------------------------------------------------------------------------
-- F3 — Higiene Gold (FORA de transação: REVOKE/GRANT persistem por si;
-- evita qualquer risco de rollback parcial). Remove escrita anon órfã em 32
-- tabelas de catálogo. A RLS já bloqueava anon (condições is_org_owner_or_admin /
-- auth.uid()), mas os grants de escrita eram foot-gun. SELECT preservado.
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  t text;
  alvos text[] := ARRAY[
    'products','product_variants','product_images','product_videos','product_kit_components',
    'product_materials','product_tags','product_category_assignments','product_relationships',
    'product_properties','categories','category_attributes','tags','collections','collection_products',
    'material_types','material_groups','material_variations','supplier_materials',
    'color_variations','color_groups','color_equivalences','variation_types','variation_values',
    'variant_supplier_sources','tabela_preco_gravacao_oficial','tabela_preco_gravacao_oficial_faixa',
    'tecnicas_gravacao','ramo_atividade','ramo_atividade_filho','produto_ramo_atividade',
    'supplier_attribute_definitions','price_history','print_area_techniques'
  ];
BEGIN
  FOREACH t IN ARRAY alvos LOOP
    IF to_regclass('public.'||t) IS NOT NULL THEN
      EXECUTE format(
        'REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.%I FROM anon', t);
    END IF;
  END LOOP;
END $$;

-- ============================================================================
-- FIM — pós-condições esperadas (validadas como role anon):
--   * v_product_properties_public      ~34.209 linhas (7.176 produtos)
--   * v_product_compositions_public    ~7.520 linhas
--   * v_kit_component_media_public     ~3.419 linhas (962 kits)
--   * 0 tabelas de catálogo com escrita anon
--   * 0 produtos com min_price = 0 (custo-zero → "sob consulta")
--   * Bronze/Prata invisíveis, mcp_sessions negado, custo/preço sugerido nunca expostos
-- ============================================================================

