-- >>> BEGIN 20260611164038_fix_asia_promote_circumference_cm.sql >>>
-- Corrige fn_asia_site_promote_to_gold para propagar circumference_cm
-- tanto para product_physical quanto para products.circumference_cm.
CREATE OR REPLACE FUNCTION public.fn_asia_site_promote_to_gold(
  p_limit    integer DEFAULT NULL::integer,
  p_only_new boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_ASIA     uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_linked   int  := 0;
  v_phys     int  := 0;
  v_scalars  int  := 0;
  v_promoted int  := 0;
  v_zombies  int  := 0;
BEGIN

  -- ── STEP -1: Limpar produtos-zombie com supplier_reference IS NULL
  WITH zombie_candidates AS (
    SELECT p.id AS zombie_id
    FROM products p
    WHERE p.supplier_id = v_ASIA
      AND (p.supplier_reference IS NULL OR p.supplier_reference = '')
      AND p.is_active = false
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_active=true)
      AND NOT EXISTS (SELECT 1 FROM product_videos pv WHERE pv.product_id=p.id AND pv.is_active=true)
      AND EXISTS (
        SELECT 1 FROM products p2
        WHERE p2.supplier_id = v_ASIA
          AND p2.is_active = true
          AND p2.supplier_reference IS NOT NULL
          AND lower(trim(p2.name)) = lower(trim(p.name))
      )
  )
  DELETE FROM product_variants pv2
  USING zombie_candidates zc
  WHERE pv2.product_id = zc.zombie_id;

  WITH zombie_products AS (
    SELECT p.id AS zombie_id
    FROM products p
    WHERE p.supplier_id = v_ASIA
      AND (p.supplier_reference IS NULL OR p.supplier_reference = '')
      AND p.is_active = false
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_active=true)
      AND NOT EXISTS (SELECT 1 FROM product_videos pv WHERE pv.product_id=p.id AND pv.is_active=true)
      AND EXISTS (
        SELECT 1 FROM products p2
        WHERE p2.supplier_id = v_ASIA AND p2.is_active = true
          AND p2.supplier_reference IS NOT NULL
          AND lower(trim(p2.name)) = lower(trim(p.name))
      )
  )
  DELETE FROM products p3 USING zombie_products zp WHERE p3.id = zp.zombie_id;
  GET DIAGNOSTICS v_zombies = ROW_COUNT;

  -- ── STEP 0: Vincular product_id via Silver principal
  WITH lnk AS (
    SELECT s.id, p.product_id
    FROM public.produtos_site_padronizacao s
    JOIN public.produtos_padronizacao p
      ON p.supplier_id = s.supplier_id
     AND p.supplier_reference = s.supplier_reference
    WHERE s.supplier_id = v_ASIA
      AND p.product_id IS NOT NULL
      AND s.product_id IS NULL
      AND s.status <> 'rejected'
  )
  UPDATE public.produtos_site_padronizacao t
     SET product_id = lnk.product_id, updated_at = now()
    FROM lnk WHERE t.id = lnk.id;
  GET DIAGNOSTICS v_linked = ROW_COUNT;

  CREATE TEMP TABLE _asia_site_scope ON COMMIT DROP AS
    SELECT s.* FROM public.produtos_site_padronizacao s
    WHERE s.supplier_id = v_ASIA
      AND s.product_id IS NOT NULL
      AND s.status = CASE WHEN p_only_new
                          THEN 'standardized'::public.produtos_padronizacao_status
                          ELSE s.status END
      AND s.status <> 'rejected'
    LIMIT COALESCE(p_limit, 1000000000);

  IF NOT EXISTS (SELECT 1 FROM _asia_site_scope) THEN
    RETURN jsonb_build_object(
      'linked', v_linked, 'note', 'nada_novo', 'zombies_removidos', v_zombies
    );
  END IF;

  -- (e) product_physical: peso + dimensoes (incluindo circumference_cm)
  INSERT INTO public.product_physical (
    product_id, weight_g, height_cm, width_cm, length_cm, circumference_cm
  )
  SELECT
    product_id,
    weight_g::numeric,
    height_cm,
    width_cm,
    depth_cm,
    circumference_cm
  FROM _asia_site_scope
  WHERE weight_g IS NOT NULL OR height_cm IS NOT NULL
     OR width_cm IS NOT NULL  OR depth_cm IS NOT NULL
     OR circumference_cm IS NOT NULL
  ON CONFLICT (product_id) DO UPDATE SET
    weight_g         = COALESCE(public.product_physical.weight_g,         EXCLUDED.weight_g),
    height_cm        = COALESCE(public.product_physical.height_cm,        EXCLUDED.height_cm),
    width_cm         = COALESCE(public.product_physical.width_cm,         EXCLUDED.width_cm),
    length_cm        = COALESCE(public.product_physical.length_cm,        EXCLUDED.length_cm),
    circumference_cm = COALESCE(public.product_physical.circumference_cm, EXCLUDED.circumference_cm),
    updated_at = now();
  GET DIAGNOSTICS v_phys = ROW_COUNT;

  -- (f) products: propagar circumference_cm diretamente na tabela Gold
  -- (fill-only — não sobrescreve valor já preenchido manualmente)
  UPDATE public.products p SET
    circumference_cm = COALESCE(p.circumference_cm, s.circumference_cm),
    updated_at       = now()
  FROM _asia_site_scope s
  WHERE p.id = s.product_id
    AND s.circumference_cm IS NOT NULL
    AND p.circumference_cm IS NULL;

  -- (h) products: fill-only escalares WP-exclusive
  UPDATE public.products p SET
    brand                  = COALESCE(p.brand,                  s.brand),
    min_order_quantity     = COALESCE(p.min_order_quantity,     s.moq),
    min_quantity           = COALESCE(p.min_quantity,           s.min_quantity),
    requires_minimum_order = COALESCE(p.requires_minimum_order,
                               CASE WHEN s.moq IS NOT NULL THEN (s.moq > 1) ELSE NULL END),
    sale_price             = COALESCE(p.sale_price,             s.sale_price),
    is_on_sale             = COALESCE(p.is_on_sale,             s.is_on_sale),
    suggested_price        = COALESCE(p.suggested_price,        s.regular_price),
    updated_at             = now()
  FROM _asia_site_scope s
  WHERE p.id = s.product_id
    AND (s.brand IS NOT NULL OR s.moq IS NOT NULL
      OR s.sale_price IS NOT NULL OR s.regular_price IS NOT NULL
      OR s.is_on_sale IS NOT NULL);
  GET DIAGNOSTICS v_scalars = ROW_COUNT;

  -- Marcar promovidas
  UPDATE public.produtos_site_padronizacao t
     SET status      = 'promoted'::public.produtos_padronizacao_status,
         promoted_at = now(),
         updated_at  = now()
   WHERE t.id IN (SELECT id FROM _asia_site_scope);
  GET DIAGNOSTICS v_promoted = ROW_COUNT;

  RETURN jsonb_build_object(
    'linked',            v_linked,
    'physical',          v_phys,
    'scalars',           v_scalars,
    'promoted',          v_promoted,
    'zombies_removidos', v_zombies
  );
END;
$function$;

-- <<< END 20260611164038_fix_asia_promote_circumference_cm.sql <<<

-- >>> BEGIN 20260611165827_80349d44-21b7-4867-9b98-4af61abab2bd.sql >>>
CREATE OR REPLACE FUNCTION public.handle_password_reset_request()
RETURNS TRIGGER AS $$
BEGIN
  -- Tenta encontrar o user_id correspondente ao email na auth.users
  SELECT id INTO NEW.user_id 
  FROM auth.users 
  WHERE email = NEW.email 
  LIMIT 1;
  
  -- Se não encontrar o usuário, podemos opcionalmente impedir a criação
  -- ou deixar o gestor decidir. Aqui vamos permitir para não dar erro de UI,
  -- mas o gestor verá que não há user_id associado.
  
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Remove o gatilho se já existir para evitar erros
DROP TRIGGER IF EXISTS tr_handle_password_reset_request ON public.password_reset_requests;

-- Cria o gatilho
CREATE TRIGGER tr_handle_password_reset_request
BEFORE INSERT ON public.password_reset_requests
FOR EACH ROW
EXECUTE FUNCTION public.handle_password_reset_request();

-- Garante que o papel anon e authenticated possam inserir
GRANT INSERT ON public.password_reset_requests TO anon, authenticated;
GRANT SELECT ON public.password_reset_requests TO authenticated;
GRANT ALL ON public.password_reset_requests TO service_role;

-- <<< END 20260611165827_80349d44-21b7-4867-9b98-4af61abab2bd.sql <<<

-- >>> BEGIN 20260611183000_p2_realtime_01_device_login_notifications_e_publication.sql >>>
-- p2_realtime_01: cria device_login_notifications e completa a publication realtime
--
-- Contexto (auditoria integração frontend↔medallion 2026-06-11):
--   1. A edge function detect-new-device INSERE em public.device_login_notifications
--      e o hook usePushNotifications ASSINA INSERTs dessa tabela — mas a tabela
--      nunca existiu no SSOT doufsxqlfjyuvxuezpln (escrita e subscription mortas).
--   2. useWorkspaceNotifications/notificationService assinam postgres_changes de
--      workspace_notifications e usePushNotifications assina login_attempts, mas
--      nenhuma das duas estava na publication supabase_realtime (eventos nunca
--      entregues; UI dependia só de refetch).
--
-- Segurança:
--   - RLS select-own para authenticated (realtime respeita RLS: cada usuário só
--     recebe eventos das próprias linhas; login_attempts mantém a policy
--     existente can_view_audit_logs — eventos só chegam a admin/dev).
--   - Escrita exclusiva da service_role (edge function); nenhuma policy de
--     INSERT/UPDATE/DELETE para clientes.
--   - Não toca nas tabelas sensíveis verificadas por check_hardening_status
--     (discount_approval_requests, kit_variants, kit_comments ficam fora da
--     publication — invariante realtime_isolation_ok preservada).

CREATE TABLE IF NOT EXISTS public.device_login_notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users (id) ON DELETE CASCADE,
  device_id text,
  ip_address text,
  user_agent text,
  location text,
  email_sent boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.device_login_notifications IS
  'Notificações de login em novo dispositivo/IP. Escrita: edge detect-new-device (service_role). Leitura: dono via RLS. Consumida em realtime por usePushNotifications.';

CREATE INDEX IF NOT EXISTS idx_device_login_notifications_user_created
  ON public.device_login_notifications (user_id, created_at DESC);

ALTER TABLE public.device_login_notifications ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can read own device login notifications"
  ON public.device_login_notifications;
CREATE POLICY "Users can read own device login notifications"
  ON public.device_login_notifications
  FOR SELECT TO authenticated
  USING (user_id = (SELECT auth.uid()));

REVOKE ALL ON public.device_login_notifications FROM PUBLIC;
REVOKE ALL ON public.device_login_notifications FROM anon;
GRANT SELECT ON public.device_login_notifications TO authenticated;
GRANT ALL ON public.device_login_notifications TO service_role;

-- Publication realtime (idempotente — ALTER PUBLICATION falha se a tabela já estiver lá)
DO $$
DECLARE
  _tbl text;
BEGIN
  FOREACH _tbl IN ARRAY ARRAY['device_login_notifications', 'workspace_notifications', 'login_attempts']
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM pg_publication_rel pr
      JOIN pg_class c ON c.oid = pr.prrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE pr.prpubid = (SELECT oid FROM pg_publication WHERE pubname = 'supabase_realtime')
        AND n.nspname = 'public'
        AND c.relname = _tbl
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', _tbl);
    END IF;
  END LOOP;
END;
$$;

-- <<< END 20260611183000_p2_realtime_01_device_login_notifications_e_publication.sql <<<

-- >>> BEGIN 20260611183100_p2_acl_01_restore_admin_rpcs_frontend.sql >>>
-- p2_acl_01: restaura EXECUTE de RPCs admin consumidas diretamente pelo frontend
--
-- Contexto (auditoria integração frontend↔medallion 2026-06-11): os lockdowns de
-- ACL deixaram 4 RPCs chamadas pela UI admin sem EXECUTE para authenticated,
-- quebrando silenciosamente (42501):
--
--   - check_hardening_status()        → HardeningHealthCard
--   - check_telemetry_regression()    → useRegressionGuardrail / useOptimizationQueue
--   - lookup_request_id(text)         → useAppHealth (drill-down de request_id)
--   - execute_role_migration_batch()  → useRoleMigration
--
-- Todas têm checagem de autorização INTERNA (admin/dev via user_roles/has_role),
-- portanto reexpor a authenticated é seguro: não-admins recebem exceção da
-- própria função, não acesso.
--
-- NÃO reexpostas (decisão deliberada):
--   - repair_ownership_orphans: o teste de segurança do frontend
--     (src/utils/security-audit.ts) EXIGE permission denied para authenticated;
--     a execução real é via edge function ownership-repair (service_role).
--   - sync_external_connections_from_credentials: SECURITY DEFINER sem checagem
--     de chamador — ganha wrapper admin-gated em migration própria (183200).

-- check_hardening_status lê storage.buckets e cron.job; como SECURITY INVOKER,
-- authenticated falharia ao tocar cron.* mesmo sendo admin. Vira DEFINER com a
-- checagem interna de admin já existente + search_path travado (todas as
-- referências do corpo são schema-qualificadas; verificado em 2026-06-11).
ALTER FUNCTION public.check_hardening_status() SECURITY DEFINER;
ALTER FUNCTION public.check_hardening_status() SET search_path = '';
REVOKE ALL ON FUNCTION public.check_hardening_status() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.check_hardening_status() FROM anon;
GRANT EXECUTE ON FUNCTION public.check_hardening_status() TO authenticated;
GRANT EXECUTE ON FUNCTION public.check_hardening_status() TO service_role;

REVOKE ALL ON FUNCTION public.check_telemetry_regression() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.check_telemetry_regression() FROM anon;
GRANT EXECUTE ON FUNCTION public.check_telemetry_regression() TO authenticated;
GRANT EXECUTE ON FUNCTION public.check_telemetry_regression() TO service_role;

REVOKE ALL ON FUNCTION public.lookup_request_id(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.lookup_request_id(text) FROM anon;
GRANT EXECUTE ON FUNCTION public.lookup_request_id(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.lookup_request_id(text) TO service_role;

REVOKE ALL ON FUNCTION public.execute_role_migration_batch(text, text, jsonb, boolean) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.execute_role_migration_batch(text, text, jsonb, boolean) FROM anon;
GRANT EXECUTE ON FUNCTION public.execute_role_migration_batch(text, text, jsonb, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.execute_role_migration_batch(text, text, jsonb, boolean) TO service_role;

