-- >>> BEGIN 20260615230501_product_images_format_canonical_guard.sql >>>
-- ============================================================================
-- product_images :: blindagem do campo `format`  (Migration 1/5)
-- ----------------------------------------------------------------------------
-- Contexto: o campo `format` convivia com casing inconsistente (JPEG/jpg/PNG).
-- Um job de ingestão autoritativo já normaliza valores em runtime; esta migration
-- adiciona a GUARDA de escrita + o INVARIANTE de minúsculo, sem enumerar formatos
-- (não quebra avif/jxl futuros nem o job vivo).
-- Idempotente.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_normalize_image_format()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NEW.format IS NOT NULL THEN
    NEW.format := lower(btrim(NEW.format));
    -- canonicaliza a variação mais comum
    IF NEW.format = 'jpg'  THEN NEW.format := 'jpeg'; END IF;
    -- remove eventual prefixo mime ("image/png" -> "png")
    IF position('/' in NEW.format) > 0 THEN
      NEW.format := split_part(NEW.format, '/', 2);
    END IF;
    IF NEW.format = '' THEN NEW.format := NULL; END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_normalize_image_format ON public.product_images;
CREATE TRIGGER trg_normalize_image_format
  BEFORE INSERT OR UPDATE OF format ON public.product_images
  FOR EACH ROW EXECUTE FUNCTION public.fn_normalize_image_format();

-- CHECK do invariante (lowercase alfanumérico). NOT VALID + VALIDATE = online.
ALTER TABLE public.product_images
  DROP CONSTRAINT IF EXISTS chk_product_images_format_lc;
ALTER TABLE public.product_images
  ADD CONSTRAINT chk_product_images_format_lc
  CHECK (format IS NULL OR format ~ '^[a-z0-9]+$') NOT VALID;
ALTER TABLE public.product_images
  VALIDATE CONSTRAINT chk_product_images_format_lc;

-- <<< END 20260615230501_product_images_format_canonical_guard.sql <<<

-- >>> BEGIN 20260615230502_product_images_assert_secure_select_rls.sql >>>
-- ============================================================================
-- product_images :: re-afirmar baseline seguro de leitura (RLS)  (Migration 2/5)
-- ----------------------------------------------------------------------------
-- O ambiente (Lovable/jobs) já removeu a policy permissiva `*_anon_select USING(true)`
-- que permitia ao papel anônimo ler imagens inativas. Esta migration é DEFENSIVA e
-- idempotente: neutraliza a policy permissiva caso ela ressurja e fixa
-- `product_images_select` na forma canônica segura.
--   - anônimo: vê apenas is_active = true
--   - autenticado: vê tudo
--   - escrita (INSERT/UPDATE/DELETE): restrita a org owner/admin (policies já existentes)
-- ============================================================================

DROP POLICY IF EXISTS product_images_anon_select ON public.product_images;

DROP POLICY IF EXISTS product_images_select ON public.product_images;
CREATE POLICY product_images_select ON public.product_images
  FOR SELECT
  TO public
  USING ((is_active = true) OR ((SELECT auth.uid()) IS NOT NULL));

-- <<< END 20260615230502_product_images_assert_secure_select_rls.sql <<<

-- >>> BEGIN 20260615230503_product_images_sync_image_type_code.sql >>>
-- ============================================================================
-- product_images :: coerência image_type (texto) <-> image_type_id (FK)  (Migration 3/5)
-- ----------------------------------------------------------------------------
-- O classificador (fn_auto_classify_product_image) define ambos no INSERT, mas um
-- UPDATE que altere SOMENTE image_type_id deixaria o texto defasado (drift).
-- Este guard mantém image_type derivado da FK (fonte da verdade), alinhado ao
-- COALESCE(it.code, pi.image_type) usado pela view v_product_images_cdn.
-- Drift medido na introdução = 0; guard é preventivo. Dispara só em UPDATE OF image_type_id.
-- Idempotente.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_sync_image_type_code()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
DECLARE
  v_code text;
BEGIN
  IF NEW.image_type_id IS NOT NULL THEN
    SELECT code INTO v_code FROM image_types WHERE id = NEW.image_type_id;
    IF v_code IS NOT NULL THEN
      NEW.image_type := v_code;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_image_type_code ON public.product_images;
CREATE TRIGGER trg_sync_image_type_code
  BEFORE UPDATE OF image_type_id ON public.product_images
  FOR EACH ROW EXECUTE FUNCTION public.fn_sync_image_type_code();

-- <<< END 20260615230503_product_images_sync_image_type_code.sql <<<

-- >>> BEGIN 20260615230504_product_images_observability_and_resync.sql >>>
-- ============================================================================
-- product_images :: observabilidade de qualidade + resync set-based  (Migration 4/5)
-- ----------------------------------------------------------------------------
-- (1) View de monitoramento dos gaps de metadados por fornecedor.
-- (2) fn_resync_product_media(): recomputa, em UMA passada set-based, os campos
--     desnormalizados de `products` (images, og_image_url, primary_image_url,
--     primary_image_fallback_url, set_image_url). Replica a lógica de
--     fn_sync_product_images_to_products + fn_sync_set_image_url. Uso: cargas em
--     massa podem desabilitar os triggers AFTER por-linha e chamar isto 1x no fim,
--     eliminando a amplificação de escrita (N updates em products -> 1).
-- NOTA: a versão DETERMINÍSTICA final está na migration 20260615230505.
-- ============================================================================

-- (1) Observabilidade -------------------------------------------------------
CREATE OR REPLACE VIEW public.v_product_images_quality_gap
WITH (security_invoker = true) AS
SELECT
  source_supplier,
  count(*)                                                         AS total,
  count(*) FILTER (WHERE is_active)                                AS ativas,
  count(*) FILTER (WHERE width_px IS NULL OR height_px IS NULL)    AS sem_dimensoes,
  count(*) FILTER (WHERE format IS NULL)                           AS sem_format,
  count(*) FILTER (WHERE file_size_bytes IS NULL)                  AS sem_file_size,
  count(*) FILTER (WHERE alt_text IS NULL)                         AS sem_alt,
  round(100.0 * count(*) FILTER (WHERE width_px IS NULL)
        / nullif(count(*), 0), 2)                                  AS pct_sem_dimensoes
FROM public.product_images
GROUP BY source_supplier;

-- (2) Resync set-based (versão inicial; substituída pela determinística) -----
CREATE OR REPLACE FUNCTION public.fn_resync_product_media(p_product_ids uuid[] DEFAULT NULL)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_count integer;
BEGIN
  WITH targets AS (
    SELECT p.id FROM products p
    WHERE p_product_ids IS NULL OR p.id = ANY(p_product_ids)
  ),
  agg AS (
    SELECT t.id AS product_id,
      COALESCE((
        SELECT jsonb_agg(url_cdn ORDER BY
          CASE WHEN image_type='main' AND is_primary THEN 0
               WHEN image_type='main' THEN 1
               WHEN image_type IN ('gallery','product') THEN 2
               WHEN image_type='ambient' THEN 3
               WHEN image_type='set' THEN 4
               WHEN image_type='logo' THEN 5 ELSE 9 END,
          is_primary DESC, display_order ASC NULLS LAST)
          FILTER (WHERE image_type NOT IN ('box','pouch','location','area','component'))
        FROM product_images WHERE product_id=t.id AND is_active), '[]'::jsonb) AS images,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active
          AND image_type NOT IN ('box','pouch','location','area','component')
        ORDER BY CASE WHEN is_og_image THEN 0
                      WHEN image_type='main' AND is_primary THEN 1
                      WHEN image_type='main' THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' THEN 5 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST LIMIT 1) AS og_url,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active
          AND image_type NOT IN ('box','pouch','location','area','component')
        ORDER BY CASE WHEN image_type='main' AND is_primary THEN 0
                      WHEN image_type='main' THEN 1
                      WHEN image_type IN ('gallery','product') AND is_primary THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' AND is_primary THEN 5
                      WHEN image_type='set' THEN 6
                      WHEN image_type='logo' THEN 7 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST LIMIT 1) AS primary_url,
      ( SELECT url_original FROM product_images
        WHERE product_id=t.id AND is_active AND url_original IS NOT NULL AND url_original<>''
        ORDER BY CASE WHEN image_type='main' AND is_primary THEN 0
                      WHEN image_type='main' THEN 1
                      WHEN image_type IN ('gallery','product') AND is_primary THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' AND is_primary THEN 5
                      WHEN image_type='set' THEN 6
                      WHEN image_type='logo' THEN 7 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST LIMIT 1) AS fallback_url,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active AND image_type='set'
        ORDER BY display_order ASC, created_at ASC LIMIT 1) AS set_url
    FROM targets t
  )
  UPDATE products p SET
    images                     = agg.images,
    og_image_url               = agg.og_url,
    primary_image_url          = agg.primary_url,
    primary_image_fallback_url = agg.fallback_url,
    set_image_url              = agg.set_url
  FROM agg WHERE p.id = agg.product_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_resync_product_media(uuid[]) FROM anon, authenticated;

-- <<< END 20260615230504_product_images_observability_and_resync.sql <<<

-- >>> BEGIN 20260615230505_product_images_resync_deterministic.sql >>>
-- ============================================================================
-- product_images :: fn_resync_product_media DETERMINÍSTICA e IDEMPOTENTE  (Migration 4/5b)
-- ----------------------------------------------------------------------------
-- O trigger original é não-determinístico em empates de (prioridade, is_primary,
-- display_order). Esta versão adiciona desempate estável (created_at, cloudflare_image_id)
-- em TODAS as ordenações e um guard `IS DISTINCT FROM` que só escreve quando há
-- mudança real -> execuções repetidas são no-op (idempotência verificada: run1=1,
-- run2=0, run3=0). A 1a execução por produto pode normalizar a ordem de empates
-- (cosmético, mesmo conjunto de URLs).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_resync_product_media(p_product_ids uuid[] DEFAULT NULL)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_count integer;
BEGIN
  WITH targets AS (
    SELECT p.id FROM products p
    WHERE p_product_ids IS NULL OR p.id = ANY(p_product_ids)
  ),
  agg AS (
    SELECT t.id AS product_id,
      COALESCE((
        SELECT jsonb_agg(url_cdn ORDER BY
          CASE WHEN image_type='main' AND is_primary THEN 0
               WHEN image_type='main' THEN 1
               WHEN image_type IN ('gallery','product') THEN 2
               WHEN image_type='ambient' THEN 3
               WHEN image_type='set' THEN 4
               WHEN image_type='logo' THEN 5 ELSE 9 END,
          is_primary DESC, display_order ASC NULLS LAST,
          created_at ASC, cloudflare_image_id ASC)
          FILTER (WHERE image_type NOT IN ('box','pouch','location','area','component'))
        FROM product_images WHERE product_id=t.id AND is_active), '[]'::jsonb) AS images,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active
          AND image_type NOT IN ('box','pouch','location','area','component')
        ORDER BY CASE WHEN is_og_image THEN 0
                      WHEN image_type='main' AND is_primary THEN 1
                      WHEN image_type='main' THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' THEN 5 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST,
                 created_at ASC, cloudflare_image_id ASC LIMIT 1) AS og_url,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active
          AND image_type NOT IN ('box','pouch','location','area','component')
        ORDER BY CASE WHEN image_type='main' AND is_primary THEN 0
                      WHEN image_type='main' THEN 1
                      WHEN image_type IN ('gallery','product') AND is_primary THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' AND is_primary THEN 5
                      WHEN image_type='set' THEN 6
                      WHEN image_type='logo' THEN 7 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST,
                 created_at ASC, cloudflare_image_id ASC LIMIT 1) AS primary_url,
      ( SELECT url_original FROM product_images
        WHERE product_id=t.id AND is_active AND url_original IS NOT NULL AND url_original<>''
        ORDER BY CASE WHEN image_type='main' AND is_primary THEN 0
                      WHEN image_type='main' THEN 1
                      WHEN image_type IN ('gallery','product') AND is_primary THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' AND is_primary THEN 5
                      WHEN image_type='set' THEN 6
                      WHEN image_type='logo' THEN 7 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST,
                 created_at ASC, cloudflare_image_id ASC LIMIT 1) AS fallback_url,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active AND image_type='set'
        ORDER BY display_order ASC, created_at ASC, cloudflare_image_id ASC LIMIT 1) AS set_url
    FROM targets t
  )
  UPDATE products p SET
    images                     = agg.images,
    og_image_url               = agg.og_url,
    primary_image_url          = agg.primary_url,
    primary_image_fallback_url = agg.fallback_url,
    set_image_url              = agg.set_url
  FROM agg
  WHERE p.id = agg.product_id
    AND ( p.images                     IS DISTINCT FROM agg.images
       OR p.og_image_url               IS DISTINCT FROM agg.og_url
       OR p.primary_image_url          IS DISTINCT FROM agg.primary_url
       OR p.primary_image_fallback_url IS DISTINCT FROM agg.fallback_url
       OR p.set_image_url              IS DISTINCT FROM agg.set_url );

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION public.fn_resync_product_media(uuid[]) FROM anon, authenticated;

-- <<< END 20260615230505_product_images_resync_deterministic.sql <<<

-- >>> BEGIN 20260615230506_product_images_schema_documentation.sql >>>
-- ============================================================================
-- product_images :: documentação do schema (COMMENTs)  (Migration 5/5)
-- Schema auto-documentado — visível no Studio, em \d+ e em ferramentas de catálogo.
-- ============================================================================

COMMENT ON TABLE public.product_images IS
'Tabela-fato de mídia do catálogo (camada Gold). 1 linha = 1 imagem física de produto hospedada no Cloudflare Images. É a fonte da verdade de imagens; os campos desnormalizados em products (images, primary_image_url, og_image_url, set_image_url, primary_image_fallback_url) são MANTIDOS pelos triggers desta tabela. RLS ativo (leitura pública só de ativas; escrita restrita a org owner/admin).';

COMMENT ON COLUMN public.product_images.cloudflare_image_id IS 'ID da imagem no Cloudflare Images (chave natural, UNIQUE).';
COMMENT ON COLUMN public.product_images.url_cdn          IS 'URL pública servida ao site (CF Images / imagedelivery.net).';
COMMENT ON COLUMN public.product_images.url_original     IS 'URL no CDN do fornecedor; usada como fallback (primary_image_fallback_url) quando o CF falha.';
COMMENT ON COLUMN public.product_images.image_type       IS 'Rótulo textual do tipo (derivado de image_type_id pela FK; mantido em sincronia pelo trigger trg_sync_image_type_code).';
COMMENT ON COLUMN public.product_images.image_type_id    IS 'FK -> image_types. Fonte da verdade da classificação; o classificador heurístico (fn_auto_classify_product_image) o define no INSERT a partir do nome do arquivo.';
COMMENT ON COLUMN public.product_images.is_primary       IS 'Imagem principal do produto. Invariante: no máximo 1 por produto (garantido por fn_ensure_single_primary_image).';
COMMENT ON COLUMN public.product_images.is_og_image      IS 'Imagem usada como Open Graph (compartilhamento social).';
COMMENT ON COLUMN public.product_images.applies_to_color IS 'Sinal semântico: imagem pertence a uma cor específica (preferir sobre supplier_code).';
COMMENT ON COLUMN public.product_images.display_order    IS 'Ordem de exibição na galeria (asc).';
COMMENT ON COLUMN public.product_images.format           IS 'Formato canônico em minúsculo (jpeg/png/webp/gif/avif...). Normalizado por fn_normalize_image_format; invariante lowercase garantido por chk_product_images_format_lc.';
COMMENT ON COLUMN public.product_images.source_supplier  IS 'Fornecedor de origem normalizado (SPOT/XBZ/ASIA/SOMARCAS/88BRINDES). Normalizado por fn_normalize_source_supplier (stricker->SPOT).';
COMMENT ON COLUMN public.product_images.width_px         IS 'Largura em px. GAP CONHECIDO: ~99,9% nulo — backfill pendente via pipeline assíncrono (pg_net/pg_cron + CF Images API).';
COMMENT ON COLUMN public.product_images.height_px        IS 'Altura em px. Ver nota em width_px.';
COMMENT ON COLUMN public.product_images.file_size_bytes  IS 'Tamanho do arquivo. GAP CONHECIDO: 100% nulo — backfill pendente.';
COMMENT ON COLUMN public.product_images.organization_id  IS 'FK -> organizations (multi-tenant; single-tenant na prática).';

COMMENT ON VIEW public.v_product_images_quality_gap IS
'Observabilidade: gaps de metadados (dimensões/format/size/alt) agregados por fornecedor. security_invoker=on.';

COMMENT ON FUNCTION public.fn_resync_product_media(uuid[]) IS
'Recomputa, de forma set-based, determinística e idempotente, os campos de mídia desnormalizados em products para os product_ids dados (ou todos se NULL). Use após cargas em massa com triggers AFTER desabilitados para eliminar amplificação de escrita. Só escreve linhas que mudam.';

COMMENT ON FUNCTION public.fn_normalize_image_format() IS
'Trigger BEFORE: normaliza product_images.format para minúsculo canônico (jpg->jpeg, remove prefixo mime).';

COMMENT ON FUNCTION public.fn_sync_image_type_code() IS
'Trigger BEFORE UPDATE OF image_type_id: mantém image_type (texto) coerente com a FK image_type_id.';

-- <<< END 20260615230506_product_images_schema_documentation.sql <<<

-- >>> BEGIN 20260615232601_product_images_format_normalize_robust.sql >>>
-- ============================================================================
-- product_images :: fn_normalize_image_format ROBUSTA (fail-open)  (fix do gap M1)
-- ----------------------------------------------------------------------------
-- GAP descoberto em teste adversarial: a versão anterior usava btrim() (só remove
-- espaços), então um `format` com tab/newline/CR/';'/espaço interno
-- (ex.: "image/jpeg; charset=utf-8") sobrevivia à normalização e era REJEITADO
-- pelo CHECK chk_product_images_format_lc -> a LINHA INTEIRA falhava (regressão
-- capaz de quebrar a ingestão por um campo meramente cosmético).
--
-- Correção: normaliza extraindo a 1a sequência [a-z0-9] (após remover prefixo mime),
-- garantindo que a saída SEMPRE satisfaz o CHECK. Nunca derruba a linha por format.
-- Verificado: JPEG\n->jpeg, \tpng ->png, JPEG;charset->jpeg, ///->NULL, JPG->jpeg.
--
-- LIMITAÇÃO CONHECIDA (pré-existente, não coberta aqui): a coluna é varchar(20) e a
-- coerção de tipo ocorre ANTES do trigger; um format com > 20 chars é rejeitado por
-- "value too long" independentemente da normalização. Baixo risco (o pipeline grava
-- tokens curtos: jpeg/png/webp). Mudar o tipo exigiria recriar a view
-- v_product_images_cdn que referencia format.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_normalize_image_format()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
DECLARE
  v text;
BEGIN
  IF NEW.format IS NOT NULL THEN
    v := lower(NEW.format);
    v := regexp_replace(v, '^.*/', '');     -- remove prefixo mime (até a última '/')
    v := substring(v from '[a-z0-9]+');     -- 1a sequência alfanumérica (ou NULL)
    IF v = 'jpg' THEN v := 'jpeg'; END IF;  -- canonicaliza
    NEW.format := v;                        -- NULL se nada alfanumérico (fail-open)
  END IF;
  RETURN NEW;
END;
$$;

-- <<< END 20260615232601_product_images_format_normalize_robust.sql <<<

-- >>> BEGIN 20260615232602_grant_anon_execute_is_org_owner_or_admin.sql >>>
-- ============================================================================
-- FIX SEV-1 (descoberto em teste adversarial de RLS)
-- ----------------------------------------------------------------------------
-- A policy de SELECT de product_images foi alterada pelo ambiente para
--   USING (is_active OR is_org_owner_or_admin(organization_id))
-- mas o papel `anon` NÃO tinha EXECUTE em is_org_owner_or_admin. Ao avaliar a RLS
-- sobre qualquer linha inativa, o anônimo recebia:
--   ERROR: permission denied for function is_org_owner_or_admin
-- e a query inteira falhava -> imagens quebravam no site público (RLS é security-qual,
-- avaliada antes do filtro da aplicação; basta 1 inativa no escopo).
--
-- is_org_owner_or_admin é SECURITY DEFINER e usa auth.uid(); para anon (uid nulo)
-- retorna false sem vazamento. Conceder EXECUTE ao anon corrige o erro e preserva a
-- intenção: anônimo vê só imagens ativas; inativas só para owner/admin da organização.
-- Fix estável: independe da expressão exata da policy (resiste à churn do ambiente).
-- Verificado: anon lê 73187 ativas, 0 inativas visíveis, escrita bloqueada.
-- ============================================================================

GRANT EXECUTE ON FUNCTION public.is_org_owner_or_admin(uuid) TO anon;

-- <<< END 20260615232602_grant_anon_execute_is_org_owner_or_admin.sql <<<

-- >>> BEGIN 20260615232603_product_images_sync_image_type_code_close_drift.sql >>>
-- ============================================================================
-- FIX (gap M3 descoberto em teste adversarial)
-- ----------------------------------------------------------------------------
-- O guard trg_sync_image_type_code disparava só em UPDATE OF image_type_id, então
-- um UPDATE direto da coluna texto `image_type` (sem mexer no id) criava DRIFT
-- (texto != image_types.code do id). Isso afeta a ordenação em
-- fn_sync_product_images_to_products e fn_resync_product_media (ordenam por texto).
-- Como image_type_id é NOT NULL + FK (fonte da verdade), o invariante é "texto
-- espelha a FK". O trigger agora dispara também em UPDATE OF image_type, re-derivando
-- o texto do id em qualquer caminho. Verificado: update texto->'XXXX' é revertido p/ code da FK.
-- ============================================================================

DROP TRIGGER IF EXISTS trg_sync_image_type_code ON public.product_images;
CREATE TRIGGER trg_sync_image_type_code
  BEFORE UPDATE OF image_type_id, image_type ON public.product_images
  FOR EACH ROW EXECUTE FUNCTION public.fn_sync_image_type_code();

-- <<< END 20260615232603_product_images_sync_image_type_code_close_drift.sql <<<

-- >>> BEGIN 20260615232604_product_images_resync_lockdown_execute.sql >>>
-- ============================================================================
-- FIX (gap M4 descoberto em teste adversarial)
-- ----------------------------------------------------------------------------
-- REVOKE ... FROM anon,authenticated não bastou porque toda FUNCTION recebe EXECUTE
-- para PUBLIC por padrão. fn_resync_product_media é SECURITY DEFINER e escreve em
-- products (com argumento NULL recomputa a tabela inteira), então permanecia
-- acessível a anon/authenticated via PUBLIC -> risco de escrita/DoS.
-- Correção: revogar de PUBLIC (e explicitamente de anon/authenticated) e conceder
-- somente a service_role. Verificado: anon=false, authenticated=false, service_role=true.
-- ============================================================================

REVOKE ALL ON FUNCTION public.fn_resync_product_media(uuid[]) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_resync_product_media(uuid[]) FROM anon;
REVOKE ALL ON FUNCTION public.fn_resync_product_media(uuid[]) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.fn_resync_product_media(uuid[]) TO service_role;

-- <<< END 20260615232604_product_images_resync_lockdown_execute.sql <<<

-- >>> BEGIN 20260615232605_product_images_quality_gap_view_lockdown.sql >>>
-- ============================================================================
-- FIX (advisor lint 0026 pg_graphql_anon_table_exposed, descoberto em teste)
-- ----------------------------------------------------------------------------
-- A view de monitoramento v_product_images_quality_gap estava legível por anon
-- (exposta no GraphQL/PostgREST). É telemetria operacional interna (gaps por
-- fornecedor) -> não deve ser anon-readable. Least-privilege: revoga de
-- PUBLIC/anon/authenticated; concede só a service_role.
-- Verificado: anon=false, authenticated=false, service_role=true.
-- ============================================================================

REVOKE ALL ON public.v_product_images_quality_gap FROM PUBLIC;
REVOKE ALL ON public.v_product_images_quality_gap FROM anon;
REVOKE ALL ON public.v_product_images_quality_gap FROM authenticated;
GRANT SELECT ON public.v_product_images_quality_gap TO service_role;

-- <<< END 20260615232605_product_images_quality_gap_view_lockdown.sql <<<

-- >>> BEGIN 20260615235001_product_images_fix_sync_image_type_comment.sql >>>
-- ============================================================================
-- Ajuste de documentação (review CodeRabbit, PR #781): o COMMENT de
-- fn_sync_image_type_code ficou desatualizado após a migration ..._close_drift
-- expandir o trigger para disparar também em UPDATE OF image_type. Reescreve o
-- COMMENT refletindo ambos os caminhos (image_type_id e image_type).
-- ============================================================================

COMMENT ON FUNCTION public.fn_sync_image_type_code() IS
'Trigger BEFORE UPDATE OF image_type_id, image_type: mantém image_type (texto) coerente com a FK image_type_id (fonte da verdade), cobrindo também updates parciais só da coluna texto (fix de drift).';

-- <<< END 20260615235001_product_images_fix_sync_image_type_comment.sql <<<

-- >>> BEGIN 20260615235501_product_images_sync_image_type_bidirectional.sql >>>
-- ============================================================================
-- FIX (review Codex P2 #1, regressão real introduzida no guard close_drift)
-- ----------------------------------------------------------------------------
-- O guard anterior, ao disparar em UPDATE OF image_type, REVERTIA o texto a partir
-- da FK. Mas a UI do admin (useProductImageGallery.updateExternalImageMeta, ~L184)
-- altera o TIPO setando apenas image_type (texto), sem image_type_id — então o save
-- "tinha sucesso" mas não mudava a classificação (perda silenciosa).
--
-- Correção: torna fn_sync_image_type_code BIDIRECIONAL, honrando a intenção:
--   - image_type_id mudou           -> texto segue o id (FK explícita vence)
--   - apenas image_type (texto) mudou -> mapeia o texto de volta p/ o id (adota o
--     novo tipo). Texto sem code válido é revertido p/ a FK atual (sem drift, sem
--     aceitar tipo inexistente).
-- Verificado: texto->'logo' adota (texto+id=logo); texto->'XXXX' reverte; id->set propaga.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_sync_image_type_code()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
DECLARE
  v_code text;
  v_id   uuid;
BEGIN
  IF NEW.image_type_id IS DISTINCT FROM OLD.image_type_id THEN
    SELECT code INTO v_code FROM image_types WHERE id = NEW.image_type_id;
    IF v_code IS NOT NULL THEN
      NEW.image_type := v_code;
    END IF;
  ELSIF NEW.image_type IS DISTINCT FROM OLD.image_type THEN
    SELECT id INTO v_id FROM image_types WHERE code = NEW.image_type;
    IF v_id IS NOT NULL THEN
      NEW.image_type_id := v_id;
    ELSE
      SELECT code INTO v_code FROM image_types WHERE id = NEW.image_type_id;
      IF v_code IS NOT NULL THEN
        NEW.image_type := v_code;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- <<< END 20260615235501_product_images_sync_image_type_bidirectional.sql <<<

-- >>> BEGIN 20260615235502_product_images_portability_defensive_guards.sql >>>
-- ============================================================================
-- FIX (review Codex P2 #2 e #4): robustez/portabilidade dos migrations.
-- ----------------------------------------------------------------------------
-- #2: products.primary_image_fallback_url existe em prod (escrito pelo trigger de
--     sync), porém é "coluna fantasma" não criada por migration commitada -> em
--     rebuild fresco a partir dos migrations, fn_resync_product_media falharia com
--     "column does not exist". Garante a coluna de forma idempotente.
-- #4: VALIDATE CONSTRAINT do format (migration ..._format_canonical_guard) aborta se
--     houver valores legados (JPEG/jpg/mime) num DB construído do zero com dados
--     pré-existentes. Backfill canônico (no-op em prod, já 100% canônico) deixa o
--     estado consistente.
-- Idempotente e seguro (no-op em produção).
--
-- NOTA #3/#5 (Codex): NÃO aplicáveis a este schema — cloudflare_image_id é
-- UNIQUE + NOT NULL (desempate já determinístico) e url_cdn é NOT NULL com 0 linhas
-- vazias (sem risco de blank em primary_image_url).
-- ============================================================================

ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS primary_image_fallback_url text;

UPDATE public.product_images
SET format = CASE
      WHEN substring(regexp_replace(lower(format), '^.*/', '') from '[a-z0-9]+') = 'jpg'
        THEN 'jpeg'
      ELSE substring(regexp_replace(lower(format), '^.*/', '') from '[a-z0-9]+')
    END
WHERE format IS NOT NULL AND format !~ '^[a-z0-9]+$';

-- <<< END 20260615235502_product_images_portability_defensive_guards.sql <<<

-- >>> BEGIN 20260615_001_drop_ai_provider_quotas_zombie.sql >>>
-- ============================================================
-- Migration: drop_ai_provider_quotas_zombie
-- Date: 2026-06-15
-- Author: cleanup audit
-- ============================================================
-- Context:
--   ai_provider_quotas was designed for per-provider spending
--   caps (monthly_limit_usd / monthly_limit_tokens), but was
--   never wired into any Edge Function or Postgres function.
--   All 5 rows have NULL limits. The actual quota system uses
--   ai_usage_quotas (keyed by app_role), not this table.
--
-- Evidence:
--   - monthly_limit_usd = NULL for all 5 rows
--   - monthly_limit_tokens = NULL for all 5 rows
--   - current_period_usage_usd = 0 (never incremented)
--   - pg_stat seq_scan = 4 (only index warm-up reads)
--   - n_tup_ins = 0 after initial seed (never written to)
--   - Zero references in supabase/functions/**
--   - Zero references in public Postgres functions
--   - Zero views or materialized views reference it
--   - No child FK tables reference it
--
-- Safety checks (all PASS before applying):
--   1. No views reference ai_provider_quotas
--   2. No edge functions reference ai_provider_quotas
--   3. No postgres functions reference ai_provider_quotas
--   4. No child FK tables point to ai_provider_quotas
--   5. tg_ai_providers_set_updated_at() survives (shared trigger fn)
--   6. ai_function_routing, ai_models, ai_providers keep their triggers
--   7. ai_usage_quotas, ai_usage_logs, ai_routing_decisions, ai_usage_events
--      are NOT dropped (all have active code references)
-- ============================================================

-- DROP TABLE (CASCADE handles the trigger + index + FK + RLS policies automatically)
DROP TABLE IF EXISTS public.ai_provider_quotas CASCADE;

-- Reload PostgREST schema cache so the table disappears from the API immediately
NOTIFY pgrst, 'reload schema';

-- <<< END 20260615_001_drop_ai_provider_quotas_zombie.sql <<<

-- >>> BEGIN 20260615_002_fix_ai_quota_and_cache_bugs.sql >>>
-- ============================================================
-- Migration: fix_ai_quota_and_cache_bugs
-- Date: 2026-06-15
-- Bugs fixed:
--   BUG-QUOTA-001 [CRITICAL] — check_ai_quota() type mismatch app_role vs text
--   BUG-CACHE-001 [HIGH]     — ai_insights_cache view alias for dashboard_insights_cache
--   BUG-CACHE-002 [MEDIUM]   — dashboard_insights_cache missing tokens_input/tokens_output
-- ============================================================
-- Discovered during exhaustive post-DROP test battery (47 assertions).
-- None caused by DROP ai_provider_quotas — all pre-existing bugs.
-- ============================================================

-- ============================================================
-- FIX BUG-QUOTA-001: check_ai_quota() — app_role vs text type mismatch
-- Root cause: ai_usage_quotas.role is app_role enum, v_role is text.
--             WHERE role = v_role fails with: operator does not exist app_role=text
-- Fix: cast role::text for comparison (safe: role enum values are valid text)
-- Impact: Quota system was completely non-functional. All AI calls
--         that went through the quota check path were failing.
-- ============================================================

CREATE OR REPLACE FUNCTION public.check_ai_quota(_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
  v_limit int;
  v_unlimited boolean;
  v_used int;
BEGIN
  v_role := public._get_user_primary_role(_user_id);

  -- FIX: role::text = v_role (was: role = v_role → operator does not exist: app_role=text)
  SELECT monthly_limit, is_unlimited INTO v_limit, v_unlimited
  FROM public.ai_usage_quotas WHERE role::text = v_role;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'allowed', true, 'used', 0, 'limit', -1, 'remaining', -1,
      'unlimited', true, 'reason', 'no_quota_for_role'
    );
  END IF;

  SELECT count(*)::int INTO v_used
  FROM public.ai_usage_logs
  WHERE user_id = _user_id
    AND created_at >= date_trunc('month', now())
    AND status != 'error';

  IF v_unlimited THEN
    RETURN jsonb_build_object(
      'allowed', true, 'used', v_used, 'limit', -1, 'remaining', -1, 'unlimited', true
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_used < v_limit,
    'used', v_used,
    'limit', v_limit,
    'remaining', greatest(0, v_limit - v_used),
    'unlimited', false
  );
END;
$function$;

-- ============================================================
-- FIX BUG-CACHE-002: Add missing columns tokens_input/tokens_output
-- Root cause: dashboard_insights_cache was missing these columns
--             that market-intelligence-insights/index.ts writes via upsert.
-- Impact: Cache writes would fail silently, causing every AI call
--         to skip the cache and always hit the AI API (2-3x cost overhead).
-- ============================================================

ALTER TABLE public.dashboard_insights_cache
  ADD COLUMN IF NOT EXISTS tokens_input integer,
  ADD COLUMN IF NOT EXISTS tokens_output integer;

-- ============================================================
-- FIX BUG-CACHE-001: Create ai_insights_cache view → dashboard_insights_cache
-- Root cause: Table was renamed from ai_insights_cache to dashboard_insights_cache
--             (or the edge fn was written against the wrong name), but
--             market-intelligence-insights/index.ts still uses .from("ai_insights_cache").
-- Fix: Create a security_invoker view so existing edge fn code works without
--      redeploy, while RLS from dashboard_insights_cache is inherited.
-- Impact: Cache was completely broken — reads and writes all failed silently.
-- ============================================================

CREATE OR REPLACE VIEW public.ai_insights_cache
  WITH (security_invoker = true)
AS
SELECT
  id,
  user_id,
  function_name,
  cache_key,
  payload,
  model,
  tokens_input,
  tokens_output,
  duration_ms,
  created_at,
  expires_at
FROM public.dashboard_insights_cache;

-- Grants for PostgREST access
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_insights_cache TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.ai_insights_cache TO service_role;
GRANT SELECT ON public.ai_insights_cache TO anon;

-- Reload schema cache
NOTIFY pgrst, 'reload schema';

-- <<< END 20260615_002_fix_ai_quota_and_cache_bugs.sql <<<

-- >>> BEGIN 20260615_fix_asia_product_names_cleanup.sql >>>
-- ============================================================
-- Migration: fix_asia_product_names_cleanup
-- Autor: Pipeline de qualidade de dados
-- Data: 2026-06-15
-- 
-- Problema: 297 produtos da Asia Import no Gold têm o formato:
--   "Copo térmico – 11,3xø8,5cm (AxøD)"
-- onde o sufixo "– dims" foi adicionado artificialmente por
-- uma migração histórica, e o campo name foi travado com
-- locked_fields para impedir o pipeline de corrigir.
--
-- Solução: 
--   1. Restaurar o nome limpo (pré-"–") usando o Silver como fonte
--   2. Remover 'name' do locked_fields para pipeline manter
--
-- Escopo: SOMENTE Padrão B (297 produtos com " – " artificial)
-- Padrão A (66 produtos com dims do nome da API) = intocado
-- ============================================================

DO $$
DECLARE
  v_rows  integer;
  v_t0    timestamptz := clock_timestamp();
BEGIN
  -- Configurar como pipeline para não re-travar locked_fields
  -- via trigger fn_products_capture_manual_edits
  PERFORM set_config('app.write_source',     'pipeline', true);
  PERFORM set_config('app.bulk_import_mode', 'true',     true);

  UPDATE public.products p
  SET
    -- Nome limpo = fn_display_product_name(Silver.name)
    -- Garantido igual ao que o pipeline usaria (idempotente)
    name          = public.fn_display_product_name(pp.name),
    -- Desbloquear 'name' para o pipeline manter no futuro
    locked_fields = array_remove(p.locked_fields, 'name'),
    updated_at    = now()
  FROM public.produtos_padronizacao pp
  WHERE pp.supplier_id    = p.supplier_id
    AND pp.supplier_reference = p.supplier_reference
    -- Apenas Asia Import
    AND p.supplier_id     = 'd2734e23-d633-4819-bb15-e51aa44e2118'
    -- Apenas produtos ativos
    AND p.is_active       = true
    -- Apenas Padrão B: sufixo artificial " – dims"
    AND p.name LIKE '% – %'
    AND p.name ~ '\d+[,.]?\d*\s*[xXøØ]'
    -- Garantia de que o Silver tem nome válido
    AND NULLIF(TRIM(pp.name), '') IS NOT NULL;

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  RAISE NOTICE '[fix_asia_product_names_cleanup] % produtos corrigidos em % ms',
    v_rows,
    ROUND(EXTRACT(EPOCH FROM clock_timestamp() - v_t0) * 1000)::int;

  IF v_rows < 280 OR v_rows > 310 THEN
    RAISE EXCEPTION 'Contagem fora do esperado (280-310): % linhas atualizadas. Abortando.', v_rows;
  END IF;
END;
$$;

-- ============================================================
-- Validação pós-migration
-- ============================================================
DO $$
DECLARE
  v_remaining integer;
  v_unlocked  integer;
BEGIN
  -- Contar produtos que AINDA têm o padrão " – dims" após o fix
  SELECT COUNT(*) INTO v_remaining
  FROM products
  WHERE supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
    AND is_active   = true
    AND name LIKE '% – %'
    AND name ~ '\d+[,.]?\d*\s*[xXøØ]';

  -- Contar produtos que têm 'name' desbloqueado
  SELECT COUNT(*) INTO v_unlocked
  FROM products
  WHERE supplier_id   = 'd2734e23-d633-4819-bb15-e51aa44e2118'
    AND is_active     = true
    AND NOT ('name' = ANY(locked_fields));

  RAISE NOTICE '[VALIDAÇÃO] Restantes com padrão B: % (esperado: 0)', v_remaining;
  RAISE NOTICE '[VALIDAÇÃO] Produtos com name desbloqueado: %', v_unlocked;

  IF v_remaining > 0 THEN
    RAISE EXCEPTION 'FALHA: ainda restam % produtos com padrão B após o fix.', v_remaining;
  END IF;
END;
$$;

-- <<< END 20260615_fix_asia_product_names_cleanup.sql <<<

-- >>> BEGIN 20260616003120_product_images_audit_matview_e1.sql >>>
-- ============================================================================
-- E1: mv_product_images_audit — visão audit completa, 7 dimensões de qualidade
-- Score 0-100, prioridade_correcao, gap_* flags por linha.
-- pg_cron refresh a cada 6h (job 'refresh-mv-product-images-audit').
-- ============================================================================

DROP MATERIALIZED VIEW IF EXISTS public.mv_product_images_audit;

CREATE MATERIALIZED VIEW public.mv_product_images_audit AS
SELECT
  pi.id,
  pi.product_id,
  pi.cloudflare_image_id,
  pi.source_supplier,
  pi.organization_id,
  pi.created_at,
  pi.updated_at,
  it.code                  AS image_type_code,
  it.category              AS image_type_category,
  it.subcategory           AS image_type_subcategory,
  it.is_color_specific,
  it.show_in_gallery,
  it.show_in_simulator,
  it.is_primary_candidate,
  it.display_priority,
  pi.is_active,
  pi.is_primary,
  pi.is_og_image,
  pi.display_order,
  pi.url_cdn,
  pi.url_original,
  pi.filename,
  pi.format,
  pi.width_px,
  pi.height_px,
  pi.file_size_bytes,
  pi.color_id,
  pi.variant_id,
  pi.applies_to_color,
  pi.supplier_code,
  pi.alt_text,
  length(pi.alt_text)      AS alt_length,
  pi.title_text,
  pi.caption,
  -- ─── GAP FLAGS (true = falta algo) ────────────────────────────────────────
  (pi.format IS NULL)                                                              AS gap_format,
  (pi.width_px IS NULL OR pi.height_px IS NULL)                                   AS gap_dimensoes,
  (pi.file_size_bytes IS NULL)                                                     AS gap_file_size,
  (pi.url_original IS NULL
    AND pi.is_active = true
    AND NOT (pi.source_supplier = 'SPOT' AND it.code IN ('component','location','area'))) AS gap_url_original,
  -- applies_to_color (boolean do registro) — não is_color_specific da FK
  (pi.applies_to_color = true
    AND pi.color_id IS NULL
    AND pi.is_active = true)                                                       AS gap_color_id,
  (pi.alt_text IS NULL OR length(pi.alt_text) < 20)                               AS gap_alt_quality,
  (pi.image_type IS DISTINCT FROM it.code)                                        AS gap_image_type_drift,
  -- ─── SCORE DE COMPLETUDE (0-100, média de 7 dimensões) ────────────────────
  ROUND(100.0 * (
    (pi.format IS NOT NULL)::int +
    (pi.width_px IS NOT NULL AND pi.height_px IS NOT NULL)::int +
    (pi.file_size_bytes IS NOT NULL)::int +
    (pi.url_original IS NOT NULL OR (pi.source_supplier = 'SPOT' AND it.code IN ('component','location','area')))::int +
    (pi.color_id IS NOT NULL OR pi.applies_to_color IS NOT TRUE)::int +
    (pi.alt_text IS NOT NULL AND length(pi.alt_text) >= 20)::int +
    (pi.image_type = it.code OR pi.image_type IS NULL)::int
  ) / 7.0, 1)                                                                     AS score_completude,
  -- ─── PRIORIDADE DE CORREÇÃO ────────────────────────────────────────────────
  CASE
    WHEN pi.is_active = false                                                    THEN 'I-inativa'
    WHEN pi.is_primary AND (pi.width_px IS NULL OR pi.height_px IS NULL) AND pi.format IS NULL THEN 'P0-primary-multi-gap'
    WHEN pi.is_primary AND (pi.width_px IS NULL OR pi.height_px IS NULL)        THEN 'P0-primary-sem-dim'
    WHEN pi.format IS NULL AND (pi.width_px IS NULL OR pi.height_px IS NULL)    THEN 'P1-sem-format-dim'
    WHEN (pi.width_px IS NULL OR pi.height_px IS NULL)                          THEN 'P2-sem-dimensoes'
    WHEN pi.format IS NULL                                                       THEN 'P3-sem-format'
    WHEN pi.url_original IS NULL
      AND pi.is_active
      AND NOT (pi.source_supplier = 'SPOT' AND it.code IN ('component','location','area')) THEN 'P4-sem-url-original'
    WHEN pi.applies_to_color = true AND pi.color_id IS NULL AND pi.is_active    THEN 'P5-sem-color-id'
    WHEN (pi.alt_text IS NULL OR length(pi.alt_text) < 20)                      THEN 'P6-alt-curto'
    ELSE 'OK'
  END                                                                              AS prioridade_correcao
FROM public.product_images pi
JOIN public.image_types it ON it.id = pi.image_type_id
WITH DATA;

-- ─── ÍNDICES ──────────────────────────────────────────────────────────────────
CREATE UNIQUE INDEX uq_mv_product_images_audit_id
  ON public.mv_product_images_audit (id);

CREATE INDEX idx_mv_pia_supplier_prioridade
  ON public.mv_product_images_audit (source_supplier, prioridade_correcao);

CREATE INDEX idx_mv_pia_score
  ON public.mv_product_images_audit (score_completude);

CREATE INDEX idx_mv_pia_gaps_format_dim
  ON public.mv_product_images_audit (gap_format, gap_dimensoes)
  WHERE gap_format OR gap_dimensoes;

CREATE INDEX idx_mv_pia_product_pendente
  ON public.mv_product_images_audit (product_id)
  WHERE prioridade_correcao NOT IN ('I-inativa','OK');

CREATE INDEX idx_mv_pia_prioridade
  ON public.mv_product_images_audit (prioridade_correcao);

-- ─── PERMISSÕES ───────────────────────────────────────────────────────────────
REVOKE ALL ON public.mv_product_images_audit FROM anon, authenticated;
GRANT SELECT ON public.mv_product_images_audit TO service_role;

COMMENT ON MATERIALIZED VIEW public.mv_product_images_audit IS
'Auditoria completa de product_images: 7 dimensões de qualidade, score 0-100, gap flags,
prioridade_correcao. Refresh a cada 6h via pg_cron (job refresh-mv-product-images-audit).
Não exposto a anon/authenticated.';

-- ─── PG_CRON: refresh automático a cada 6h ────────────────────────────────────
SELECT cron.unschedule(jobname)
FROM cron.job WHERE jobname = 'refresh-mv-product-images-audit';

SELECT cron.schedule(
  'refresh-mv-product-images-audit',
  '0 */6 * * *',
  $$REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_product_images_audit$$
);

-- <<< END 20260616003120_product_images_audit_matview_e1.sql <<<

-- >>> BEGIN 20260616003235_product_images_format_backfill_l1_e2.sql >>>
-- ============================================================================
-- E2-L1: Backfill format via regex em url_original (20.116 imagens)
-- jpg → jpeg (normalização canônica), webp → webp, etc.
-- O trigger trg_normalize_image_format (BEFORE UPDATE OF format) reprocessa
-- o valor mas já enviamos a forma canônica → no-op seguro.
-- ============================================================================
UPDATE public.product_images
SET format = CASE
  WHEN lower(substring(url_original from '\.([a-zA-Z0-9]+)(\?.*)?$')) = 'jpg'  THEN 'jpeg'
  WHEN lower(substring(url_original from '\.([a-zA-Z0-9]+)(\?.*)?$')) = 'jpeg' THEN 'jpeg'
  WHEN lower(substring(url_original from '\.([a-zA-Z0-9]+)(\?.*)?$')) = 'png'  THEN 'png'
  WHEN lower(substring(url_original from '\.([a-zA-Z0-9]+)(\?.*)?$')) = 'webp' THEN 'webp'
  WHEN lower(substring(url_original from '\.([a-zA-Z0-9]+)(\?.*)?$')) = 'gif'  THEN 'gif'
  WHEN lower(substring(url_original from '\.([a-zA-Z0-9]+)(\?.*)?$')) = 'avif' THEN 'avif'
  ELSE lower(substring(url_original from '\.([a-zA-Z0-9]+)(\?.*)?$'))
END
WHERE format IS NULL
  AND url_original IS NOT NULL AND url_original <> ''
  AND url_original ~ '\.[a-zA-Z0-9]{2,5}(\?.*)?$'
  AND lower(substring(url_original from '\.([a-zA-Z0-9]+)(\?.*)?$'))
      IN ('jpg','jpeg','png','webp','gif','avif','bmp','tiff','svg');

-- <<< END 20260616003235_product_images_format_backfill_l1_e2.sql <<<

-- >>> BEGIN 20260616003422_product_images_format_backfill_l2_e2.sql >>>
-- ============================================================================
-- E2-L2: Backfill format para imagens SPOT sem url_original + XBZ orfão
-- ----------------------------------------------------------------------------
-- L2a: spot-pa-* = PNG confirmado via CF Images API (amostra de 8 imagens)
--       tipos: location=7755, component=3025, area=1167 → 11.947 imagens
-- L2b: xbz-p-05054 = ausente no Cloudflare (batch_check: missing)
--       → inativar para não servir URL quebrada
-- ============================================================================

-- L2a: SPOT print-area images são sempre PNG
UPDATE public.product_images
SET format = 'png'
WHERE format IS NULL
  AND source_supplier = 'SPOT'
  AND cloudflare_image_id LIKE 'spot-pa-%';

-- L2b: XBZ image ausente no CF → inativar
UPDATE public.product_images
SET is_active = false
WHERE cloudflare_image_id = 'xbz-p-05054';

-- <<< END 20260616003422_product_images_format_backfill_l2_e2.sql <<<

-- >>> BEGIN 20260616003458_product_images_dimensions_asia_bulk_e3.sql >>>
-- ============================================================================
-- E3-ASIA: Bulk backfill 768×768 para todas as imagens ASIA sem dimensões.
-- Invariante verificado via query: 60 imagens com dimensões = ALL 768×768.
-- 0 exceções em amostra completa. Safe para bulk update sem checar CF API.
-- ============================================================================
UPDATE public.product_images
SET
  width_px  = 768,
  height_px = 768
WHERE source_supplier = 'ASIA'
  AND (width_px IS NULL OR height_px IS NULL);

-- E3-E4 restante (67.152 imagens non-ASIA): backfill assíncrono via
-- Edge Function 'backfill-image-dimensions' (pg_cron job #125, a cada 5min).
-- A função parseia headers de imagem (Range: bytes=0-32767) para extrair
-- width/height/file_size de JPEG/PNG/WebP. Não bloqueante para este migration.

-- <<< END 20260616003458_product_images_dimensions_asia_bulk_e3.sql <<<

-- >>> BEGIN 20260616003837_product_images_e5_spot_url_original_gap.sql >>>
-- ============================================================================
-- E5: Gap url_original SPOT intencional — documentação + view atualizada
-- ----------------------------------------------------------------------------
-- SPOT tipos component/location/area (spot-pa-*) são carregados diretamente
-- no Cloudflare Images sem CDN intermediário do fornecedor. url_original=NULL
-- é por design para esses 11.947 registros. Não tente backfill.
-- ============================================================================

COMMENT ON COLUMN public.product_images.url_original IS
'URL no CDN do fornecedor; usada como fallback (primary_image_fallback_url) quando o CF falha.
GAP ESTRUTURAL SPOT: imagens dos tipos component/location/area (spot-pa-*) são carregadas
diretamente no Cloudflare sem CDN intermediário, logo url_original=NULL é por design.
Não tente backfill para esses 11.947 registros. Para demais fornecedores e tipos,
url_original NULL é um gap real passível de correção.';

-- Recriar view com distinção de gap real vs estrutural
DROP VIEW IF EXISTS public.v_product_images_quality_gap;

CREATE VIEW public.v_product_images_quality_gap
WITH (security_invoker = true) AS
SELECT
  pi.source_supplier,
  it.code                                                                     AS image_type,
  count(*)                                                                    AS total,
  count(*) FILTER (WHERE pi.is_active)                                       AS ativas,
  count(*) FILTER (WHERE pi.width_px IS NULL OR pi.height_px IS NULL)        AS sem_dimensoes,
  count(*) FILTER (WHERE pi.format IS NULL)                                   AS sem_format,
  count(*) FILTER (WHERE pi.file_size_bytes IS NULL)                          AS sem_file_size,
  count(*) FILTER (WHERE pi.alt_text IS NULL)                                 AS sem_alt,
  -- gap REAL de url_original (exclui tipos sem URL por design)
  count(*) FILTER (
    WHERE pi.url_original IS NULL
      AND pi.is_active
      AND it.code NOT IN ('component','location','area')
  )                                                                            AS gap_url_original_real,
  -- gap ESTRUTURAL (SPOT print-area, intencional)
  count(*) FILTER (
    WHERE pi.url_original IS NULL
      AND it.code IN ('component','location','area')
  )                                                                            AS gap_url_original_estrutural,
  round(100.0 * count(*) FILTER (WHERE pi.width_px IS NULL OR pi.height_px IS NULL)
        / nullif(count(*), 0), 2)                                             AS pct_sem_dimensoes,
  round(100.0 * count(*) FILTER (WHERE pi.format IS NULL)
        / nullif(count(*), 0), 2)                                             AS pct_sem_format
FROM public.product_images pi
JOIN public.image_types it ON it.id = pi.image_type_id
GROUP BY pi.source_supplier, it.code;

REVOKE ALL ON public.v_product_images_quality_gap FROM anon, authenticated;
GRANT SELECT ON public.v_product_images_quality_gap TO service_role;

COMMENT ON VIEW public.v_product_images_quality_gap IS
'Observabilidade de gaps por fornecedor/tipo. gap_url_original_real=corrigível;
gap_url_original_estrutural=SPOT print-area, intencional (spot-pa-*).
Acesso: service_role only.';

-- <<< END 20260616003837_product_images_e5_spot_url_original_gap.sql <<<

-- >>> BEGIN 20260616004001_product_images_color_id_backfill_l1_e6.sql >>>
-- ============================================================================
-- E6-L1: Preencher color_id via variant_id → product_variants.color_id
-- Afeta imagens com applies_to_color=true, color_id IS NULL, variant_id SET.
-- JOIN seguro: product_images.variant_id FK → product_variants.id.
-- ============================================================================
UPDATE public.product_images pi
SET color_id = pv.color_id
FROM public.product_variants pv
WHERE pv.id = pi.variant_id
  AND pi.color_id IS NULL
  AND pi.applies_to_color = true
  AND pi.is_active = true
  AND pv.color_id IS NOT NULL;

-- <<< END 20260616004001_product_images_color_id_backfill_l1_e6.sql <<<

-- >>> BEGIN 20260616004106_product_images_color_id_backfill_l2_e6.sql >>>
-- ============================================================================
-- E6-L2: color_id via produto mono-variante → match inequívoco de color_id
-- Para imagens sem variant_id mas em produtos com exatamente 1 cor distinta.
-- GAP RESIDUAL: ~550 imagens multi-variante com supplier_code=nome_fornecedor
-- (XBZ/SPOT) — sem discriminador de cor válido. Requer re-importação.
-- ============================================================================
WITH mono_variant AS (
  SELECT product_id, MAX(color_id::text)::uuid AS color_id
  FROM public.product_variants
  WHERE color_id IS NOT NULL
  GROUP BY product_id
  HAVING COUNT(DISTINCT color_id) = 1
)
UPDATE public.product_images pi
SET color_id = mv.color_id
FROM mono_variant mv
WHERE mv.product_id = pi.product_id
  AND pi.applies_to_color = true
  AND pi.color_id IS NULL
  AND pi.is_active = true
  AND pi.variant_id IS NULL;

COMMENT ON COLUMN public.product_images.color_id IS
'FK → color_variations. Identifica a variante de cor desta imagem.
GAP RESIDUAL E6: ~550 imagens (XBZ product, SPOT gallery/logo) têm applies_to_color=true
mas supplier_code contém o nome do fornecedor (XBZ/SPOT) em vez do código de cor real.
Correção requer re-importação com supplier_code correto ou ligação via variant_id.
Não use supplier_code para inferir color_id neste caso.';

-- <<< END 20260616004106_product_images_color_id_backfill_l2_e6.sql <<<

-- >>> BEGIN 20260616004217_product_images_alt_text_quality_e7.sql >>>
-- ============================================================================
-- E7: Resetar alt_text curto (<20 chars) ou NULL → trigger auto-regenera
-- ----------------------------------------------------------------------------
-- O trigger trg_product_images_seo_autofill (BEFORE INSERT OR UPDATE) chama
-- generate_image_alt_text() quando alt_text IS NULL ou TRIM=''. Resultado
-- garantido ≥35 chars ("produto - tipo - Brinde Promocional").
-- Texto anterior preservado em caption para auditoria antes do reset.
-- ============================================================================
UPDATE public.product_images
SET
  caption  = COALESCE(NULLIF(trim(caption), ''), alt_text),  -- preserva texto anterior
  alt_text = NULL                           -- trigger BEFORE UPDATE regenera
WHERE (alt_text IS NULL OR (length(trim(alt_text)) < 20))
  AND is_active = true;

-- <<< END 20260616004217_product_images_alt_text_quality_e7.sql <<<

-- >>> BEGIN 20260616004305_product_images_drop_unused_indexes_e8.sql >>>
-- ============================================================================
-- E8: Drop de 3 índices não utilizados / redundantes em product_images
-- Economia: ~3.2 MB de storage + menor overhead em INSERT/UPDATE/DELETE.
-- ----------------------------------------------------------------------------
-- idx_product_images_og:              0 scans — nenhum query filtra is_og_image
-- idx_product_images_organization_id: 44 scans — single-tenant, cardinalidade ~1
-- idx_product_images_type:            67 scans — coberto por
--   idx_product_images_product_type_active (product_id, image_type, display_order
--   WHERE is_active=true), que é mais seletivo e usado em hot paths
-- ============================================================================

DROP INDEX IF EXISTS public.idx_product_images_og;
DROP INDEX IF EXISTS public.idx_product_images_organization_id;
DROP INDEX IF EXISTS public.idx_product_images_type;

-- <<< END 20260616004305_product_images_drop_unused_indexes_e8.sql <<<

-- >>> BEGIN 20260616004355_product_images_image_type_dropblockers_e9.sql >>>
-- ============================================================================
-- E9: vw_image_type_dropblockers — catálogo de objetos que bloqueiam
-- DROP COLUMN image_type de product_images.
-- Pré-requisito para migração gradual de image_type (texto) → image_type_id (FK).
-- Resultado: 52 funções + 14 triggers = 66 objetos mapeados.
-- ============================================================================

DROP VIEW IF EXISTS public.vw_image_type_dropblockers;

CREATE VIEW public.vw_image_type_dropblockers
WITH (security_invoker = true) AS
WITH
fn_refs AS (
  SELECT
    p.proname  AS object_name,
    'function' AS object_type,
    n.nspname  AS schema_name,
    'Referencia image_type no corpo da função' AS blocker_reason
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND p.prosrc ILIKE '%image_type%'
),
trg_refs AS (
  SELECT
    t.tgname   AS object_name,
    'trigger'  AS object_type,
    'public'   AS schema_name,
    'Trigger em product_images — pode ler/escrever image_type' AS blocker_reason
  FROM pg_trigger t
  JOIN pg_class c ON c.oid = t.tgrelid
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE c.relname = 'product_images'
    AND n.nspname = 'public'
    AND NOT t.tgisinternal
),
view_refs AS (
  SELECT
    c.relname  AS object_name,
    CASE c.relkind WHEN 'v' THEN 'view' ELSE 'matview' END AS object_type,
    n.nspname  AS schema_name,
    'View/MatView com dependência em product_images.image_type' AS blocker_reason
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  JOIN pg_depend d ON d.objid = c.oid
  JOIN pg_class dep_class ON dep_class.oid = d.refobjid
  JOIN pg_attribute a ON a.attrelid = d.refobjid AND a.attnum = d.refobjsubid AND a.attname = 'image_type'
  WHERE dep_class.relname = 'product_images'
    AND c.relkind IN ('v', 'm')
    AND n.nspname = 'public'
)
SELECT object_type, schema_name, object_name, blocker_reason
FROM fn_refs
UNION ALL
SELECT object_type, schema_name, object_name, blocker_reason
FROM trg_refs
UNION ALL
SELECT object_type, schema_name, object_name, blocker_reason
FROM view_refs
ORDER BY object_type, object_name;

REVOKE ALL ON public.vw_image_type_dropblockers FROM anon, authenticated;
GRANT SELECT ON public.vw_image_type_dropblockers TO service_role;

COMMENT ON VIEW public.vw_image_type_dropblockers IS
'Catálogo de todos os objetos que impedem DROP COLUMN image_type de product_images.
Use para planejar a migração gradual de image_type (texto) para image_type_id (FK).
Atualizado automaticamente via CREATE OR REPLACE VIEW (sem estado).
Acesso: service_role only.';

-- <<< END 20260616004355_product_images_image_type_dropblockers_e9.sql <<<

-- >>> BEGIN 20260616004438_product_images_88brindes_purge_e10.sql >>>
-- ============================================================================
-- E10: Purge 88BRINDES — Chapéu ecoflex (produto_ativo=false)
-- ----------------------------------------------------------------------------
-- 88BRINDES foi fornecedor piloto descontinuado. 1 produto importado
-- (Chapéu ecoflex, is_active=false). Das 14 imagens: 13 já inativas, 1 ativa.
-- Ação: inativar a última imagem ativa + desmarcar is_primary.
-- Não deletar: preservar trilha de auditoria.
-- Triggers AFTER UPDATE sincronizam products.primary_image_url et al.
-- ============================================================================

UPDATE public.product_images
SET
  is_active  = false,
  is_primary = false
WHERE source_supplier = '88BRINDES'
  AND is_active = true;

DO $$
DECLARE
  v_active_remaining int;
BEGIN
  SELECT COUNT(*) INTO v_active_remaining
    FROM public.product_images
   WHERE source_supplier = '88BRINDES' AND is_active = true;
  RAISE NOTICE 'E10: Purge 88BRINDES concluído. Imagens ativas restantes: %', v_active_remaining;
END $$;

COMMENT ON TABLE public.product_images IS
'Tabela-fato de mídia do catálogo (camada Gold). 1 linha = 1 imagem física de produto
hospedada no Cloudflare Images. É a fonte da verdade de imagens; os campos
desnormalizados em products (images, primary_image_url, og_image_url, set_image_url,
primary_image_fallback_url) são MANTIDOS pelos triggers desta tabela.
RLS ativo (leitura pública só de ativas; escrita restrita a org owner/admin).
Fornecedores ativos: SPOT, XBZ, SOMARCAS, ASIA.
88BRINDES: piloto descontinuado (14 imagens inativas, produto Chapéu ecoflex arquivado).';

-- <<< END 20260616004438_product_images_88brindes_purge_e10.sql <<<

-- >>> BEGIN 20260616005001_product_images_sync_image_type_case_insensitive.sql >>>
-- ============================================================================
-- REFINAÇÃO (gap fino encontrado em re-validação adversarial)
-- ----------------------------------------------------------------------------
-- No caminho bidirecional de fn_sync_image_type_code, um image_type em case
-- diferente (ex.: 'MAIN', 'Logo') não casava com image_types.code (todos lowercase)
-- e era silenciosamente revertido para a FK — mesma classe de "perda silenciosa"
-- que o Codex apontou, para integrações não-UI que enviem case diferente.
-- Correção: lookup case-insensitive + canonicalização para o code real (lowercase).
-- Seguro: os 18 codes de image_types são lowercase e sem colisão case-insensitive.
-- Verificado: 'MAIN'->'main' (adota), 'LoGo'->'logo', 'XXXX'->reverte p/ FK.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_sync_image_type_code()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
DECLARE
  v_code text;
  v_id   uuid;
BEGIN
  IF NEW.image_type_id IS DISTINCT FROM OLD.image_type_id THEN
    SELECT code INTO v_code FROM image_types WHERE id = NEW.image_type_id;
    IF v_code IS NOT NULL THEN
      NEW.image_type := v_code;
    END IF;
  ELSIF NEW.image_type IS DISTINCT FROM OLD.image_type THEN
    SELECT id, code INTO v_id, v_code FROM image_types WHERE lower(code) = lower(NEW.image_type);
    IF v_id IS NOT NULL THEN
      NEW.image_type_id := v_id;
      NEW.image_type    := v_code;   -- canonicaliza ('MAIN' -> 'main')
    ELSE
      SELECT code INTO v_code FROM image_types WHERE id = NEW.image_type_id;
      IF v_code IS NOT NULL THEN
        NEW.image_type := v_code;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- <<< END 20260616005001_product_images_sync_image_type_case_insensitive.sql <<<

-- >>> BEGIN 20260616171501_product_images_cf_sync_observability.sql >>>
-- BLOCO 1/6 — Observabilidade de sincronizacao Cloudflare Images
-- Aditivo e idempotente. Nao remove/renomeia nada (CLAUDE.md REGRA #2 respeitada).
-- Aplicado em prod (doufsxqlfjyuvxuezpln) via MCP em 2026-06-16; este arquivo espelha o estado.

ALTER TABLE public.product_images
  ADD COLUMN IF NOT EXISTS cf_sync_status    text        NOT NULL DEFAULT 'pending',
  ADD COLUMN IF NOT EXISTS cf_uploaded_at    timestamptz,
  ADD COLUMN IF NOT EXISTS cf_verified_at    timestamptz,
  ADD COLUMN IF NOT EXISTS cf_check_attempts smallint    NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS cf_last_error     text;

-- Coluna derivada (nao exige backfill nem trigger): classifica a convencao do ID.
ALTER TABLE public.product_images
  ADD COLUMN IF NOT EXISTS cf_id_scheme text GENERATED ALWAYS AS (
    CASE
      WHEN cloudflare_image_id ~ '^xbz_site_' THEN 'hash_legacy'
      WHEN cloudflare_image_id ~ '-dup-' OR cloudflare_image_id ~ '-leg-'
           OR cloudflare_image_id ~ '--ref' OR cloudflare_image_id ~ '-legacy$' THEN 'synthetic'
      WHEN cloudflare_image_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-' THEN 'uuid'
      WHEN cloudflare_image_id ~ '-(main|gal-[0-9]+)$' THEN 'main_gal'
      WHEN cloudflare_image_id ~ '-d[0-9]+$' THEN 'detail_dn'
      WHEN cloudflare_image_id ~ '-[0-9]{4,}-[0-9]{9,}$' OR cloudflare_image_id ~ 'd[0-9]+-[0-9]{9,}$' THEN 'slug_ts'
      WHEN cloudflare_image_id ~ '_[0-9]' THEN 'legacy_cor'
      ELSE 'seq'
    END
  ) STORED;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                 WHERE conname='chk_pi_cf_sync_status' AND conrelid='public.product_images'::regclass) THEN
    ALTER TABLE public.product_images
      ADD CONSTRAINT chk_pi_cf_sync_status
      CHECK (cf_sync_status IN ('pending','uploading','uploaded','verified','missing','failed','orphaned'));
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_pi_cf_sync_status
  ON public.product_images (cf_sync_status) WHERE cf_sync_status <> 'verified';

COMMENT ON COLUMN public.product_images.cf_sync_status    IS 'Estado do objeto no Cloudflare Images: pending|uploading|uploaded|verified|missing|failed|orphaned';
COMMENT ON COLUMN public.product_images.cf_uploaded_at    IS 'Timestamp do upload concluido no Cloudflare (campo uploaded da API CF)';
COMMENT ON COLUMN public.product_images.cf_verified_at    IS 'Ultima verificacao de existencia no CF (cf_images_check/batch_check)';
COMMENT ON COLUMN public.product_images.cf_check_attempts IS 'Numero de tentativas de verificacao/upload no CF';
COMMENT ON COLUMN public.product_images.cf_last_error     IS 'Ultima mensagem de erro de upload/verificacao no CF';
COMMENT ON COLUMN public.product_images.cf_id_scheme      IS 'Convencao do cloudflare_image_id (derivada): legacy_cor|detail_dn|main_gal|slug_ts|synthetic|hash_legacy|uuid|seq';

-- <<< END 20260616171501_product_images_cf_sync_observability.sql <<<

-- >>> BEGIN 20260616171502_product_images_content_dedup_canonical.sql >>>
-- BLOCO 2/6 — Deduplicacao por conteudo + canonicalizacao
-- Aditivo e idempotente. Aplicado em prod via MCP em 2026-06-16.

ALTER TABLE public.product_images
  ADD COLUMN IF NOT EXISTS content_hash       text,
  ADD COLUMN IF NOT EXISTS canonical_image_id uuid,
  ADD COLUMN IF NOT EXISTS is_shared          boolean NOT NULL DEFAULT false;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                 WHERE conname='product_images_canonical_image_id_fkey' AND conrelid='public.product_images'::regclass) THEN
    ALTER TABLE public.product_images
      ADD CONSTRAINT product_images_canonical_image_id_fkey
      FOREIGN KEY (canonical_image_id) REFERENCES public.product_images(id) ON DELETE SET NULL;
  END IF;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                 WHERE conname='chk_pi_canonical_not_self' AND conrelid='public.product_images'::regclass) THEN
    ALTER TABLE public.product_images
      ADD CONSTRAINT chk_pi_canonical_not_self CHECK (canonical_image_id IS NULL OR canonical_image_id <> id);
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_pi_content_hash ON public.product_images (content_hash) WHERE content_hash IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_pi_canonical    ON public.product_images (canonical_image_id) WHERE canonical_image_id IS NOT NULL;

COMMENT ON COLUMN public.product_images.content_hash       IS 'Hash do binario (sha256) ou etag R2/CF para deduplicacao de conteudo';
COMMENT ON COLUMN public.product_images.canonical_image_id IS 'Aponta para a linha canonica quando esta e alias/duplicata (substitui o hack -dup-)';
COMMENT ON COLUMN public.product_images.is_shared          IS 'TRUE quando a imagem fisica e compartilhada por multiplos produtos';

-- <<< END 20260616171502_product_images_content_dedup_canonical.sql <<<

-- >>> BEGIN 20260616171503_product_images_r2_origin_lineage.sql >>>
