-- Auditoria do módulo Estoque (2026-06-17) — fix de CAUSA-RAIZ p/ "Estoque Futuro" fantasma.
--
-- Sintoma: o cron diário fn_purge_expired_restock_dates(false) (06:00 UTC) roda e
-- SUCEDE, mas 336 entradas com next_date vencida reapareceram ~16h depois. Causa:
-- os syncs de fornecedor (XBZ/SPOT/Asia) reinjetam datas já passadas do feed ao
-- longo do dia. O purge diário é band-aid; a correção é uma trigger BEFORE leve e
-- PURA que sanitiza TODA escrita, em qualquer caminho de ingestão (centralizada).
create or replace function public.trg_fn_sanitize_restock_dates()
returns trigger
language plpgsql
set search_path to 'public'
as $$
begin
  -- (1) Anula janelas com data já vencida (< hoje). Mantém datas de hoje/futuro.
  if NEW.next_date_1 is not null and NEW.next_date_1 < current_date then NEW.next_date_1 := null; NEW.next_quantity_1 := null; end if;
  if NEW.next_date_2 is not null and NEW.next_date_2 < current_date then NEW.next_date_2 := null; NEW.next_quantity_2 := null; end if;
  if NEW.next_date_3 is not null and NEW.next_date_3 < current_date then NEW.next_date_3 := null; NEW.next_quantity_3 := null; end if;
  if NEW.next_date_4 is not null and NEW.next_date_4 < current_date then NEW.next_date_4 := null; NEW.next_quantity_4 := null; end if;
  if NEW.next_date_5 is not null and NEW.next_date_5 < current_date then NEW.next_date_5 := null; NEW.next_quantity_5 := null; end if;
  if NEW.next_date_6 is not null and NEW.next_date_6 < current_date then NEW.next_date_6 := null; NEW.next_quantity_6 := null; end if;
  -- (2) Pares incoerentes: quantidade futura sem data não é reposição rastreável.
  if NEW.next_date_1 is null and NEW.next_quantity_1 is not null then NEW.next_quantity_1 := null; end if;
  if NEW.next_date_2 is null and NEW.next_quantity_2 is not null then NEW.next_quantity_2 := null; end if;
  if NEW.next_date_3 is null and NEW.next_quantity_3 is not null then NEW.next_quantity_3 := null; end if;
  if NEW.next_date_4 is null and NEW.next_quantity_4 is not null then NEW.next_quantity_4 := null; end if;
  if NEW.next_date_5 is null and NEW.next_quantity_5 is not null then NEW.next_quantity_5 := null; end if;
  if NEW.next_date_6 is null and NEW.next_quantity_6 is not null then NEW.next_quantity_6 := null; end if;
  return NEW;
end;
$$;

comment on function public.trg_fn_sanitize_restock_dates() is
  'BEFORE INS/UPD em product_variants e variant_supplier_sources: anula janelas de reposição com data vencida (<hoje) e quantidades órfãs (sem data). Impede reinjeção de "estoque futuro" fantasma via feeds de fornecedor entre rodadas do cron de purge. Auditoria Estoque 2026-06-17.';

drop trigger if exists trg_zz_sanitize_restock_dates on public.variant_supplier_sources;
create trigger trg_zz_sanitize_restock_dates
  before insert or update on public.variant_supplier_sources
  for each row execute function public.trg_fn_sanitize_restock_dates();

drop trigger if exists trg_zz_sanitize_restock_dates on public.product_variants;
create trigger trg_zz_sanitize_restock_dates
  before insert or update on public.product_variants
  for each row execute function public.trg_fn_sanitize_restock_dates();

-- <<< END 20260617230500_estoque_sanitize_restock_dates_trigger.sql <<<

-- >>> BEGIN 20260617232000_estoque_orphan_active_variants_view.sql >>>
-- Auditoria do módulo Estoque (2026-06-17) — observabilidade NÃO destrutiva.
-- Variantes is_active=true cujo produto-pai está deletado/inativo. São invisíveis
-- no dashboard (v_products_public exclui o pai), mas o estado diverge. As que estão
-- sob produto apenas INATIVO (reversível) são preservadas de propósito p/ reativação;
-- as sob produto DELETADO (terminal) foram desativadas na auditoria (19 linhas).
create or replace view public.vw_orphan_active_variants
with (security_invoker = true) as
select
  v.id           as variant_id,
  v.sku          as variant_sku,
  v.color_name,
  v.product_id,
  p.sku          as product_sku,
  p.name         as product_name,
  p.is_deleted   as product_is_deleted,
  p.is_active    as product_is_active,
  coalesce(v.stock_quantity,0) as variant_stock,
  case when p.is_deleted is true then 'under_deleted_product'
       else 'under_inactive_product' end as reason
from public.product_variants v
join public.products p on p.id = v.product_id
where v.is_active is true and (p.is_deleted is true or p.is_active is not true);

comment on view public.vw_orphan_active_variants is
  'Observabilidade (read-only): variantes ativas sob produto deletado/inativo (invisíveis no dashboard). reason=under_deleted_product são candidatas a desativação; under_inactive_product são preservadas p/ reativação. Auditoria Estoque 2026-06-17.';

grant select on public.vw_orphan_active_variants to authenticated;

-- <<< END 20260617232000_estoque_orphan_active_variants_view.sql <<<

-- >>> BEGIN 20260617234500_estoque_outlier_view_severity_fix.sql >>>
-- Follow-up de revisão (CodeRabbit/Cubic P2): severidade do outlier view passa a
-- usar GREATEST(atual, futuro) — linhas admitidas pela janela de FUTURO já não
-- ficam subclassificadas. Espelha o que foi aplicado em produção.
create or replace view public.vw_stock_quantity_outliers
with (security_invoker = true) as
select
  vss.id            as source_id,
  vss.variant_id,
  pv.product_id,
  p.sku             as product_sku,
  p.name            as product_name,
  vss.supplier_id,
  vsp.name          as supplier_name,
  vss.quantity      as current_quantity,
  greatest(coalesce(vss.next_quantity_1,0), coalesce(vss.next_quantity_2,0), coalesce(vss.next_quantity_3,0),
           coalesce(vss.next_quantity_4,0), coalesce(vss.next_quantity_5,0), coalesce(vss.next_quantity_6,0)) as max_future_quantity,
  vss.updated_at,
  case
    when greatest(coalesce(vss.quantity,0), coalesce(vss.next_quantity_1,0), coalesce(vss.next_quantity_2,0), coalesce(vss.next_quantity_3,0),
                  coalesce(vss.next_quantity_4,0), coalesce(vss.next_quantity_5,0), coalesce(vss.next_quantity_6,0)) >= 1000000 then 'extreme'
    when greatest(coalesce(vss.quantity,0), coalesce(vss.next_quantity_1,0), coalesce(vss.next_quantity_2,0), coalesce(vss.next_quantity_3,0),
                  coalesce(vss.next_quantity_4,0), coalesce(vss.next_quantity_5,0), coalesce(vss.next_quantity_6,0)) >= 100000 then 'high'
    else 'elevated'
  end as severity
from variant_supplier_sources vss
join product_variants pv on pv.id = vss.variant_id
join products p on p.id = pv.product_id
left join v_suppliers_public vsp on vsp.id = vss.supplier_id
where vss.is_active and (
  vss.quantity >= 50000
  or greatest(coalesce(vss.next_quantity_1,0), coalesce(vss.next_quantity_2,0), coalesce(vss.next_quantity_3,0),
              coalesce(vss.next_quantity_4,0), coalesce(vss.next_quantity_5,0), coalesce(vss.next_quantity_6,0)) >= 50000
);

comment on view public.vw_stock_quantity_outliers is
  'Observabilidade (read-only): linhas de vss com quantidade atual OU futura implausivelmente alta (>=50k). Severidade = GREATEST(atual, futuro). NÃO altera dados. Auditoria Estoque 2026-06-17.';

-- Backfill único (item revisão P2): em ambientes já populados, o trigger BEFORE só
-- saneia escritas futuras. Aqui limpamos datas vencidas/qty órfã pré-existentes.
-- Idempotente; em DB recriado é no-op (sem dados).
do $$
declare tbl text; col_d text; col_q text; i int;
begin
  foreach tbl in array array['variant_supplier_sources','product_variants'] loop
    for i in 1..6 loop
      col_d := format('next_date_%s', i); col_q := format('next_quantity_%s', i);
      execute format('update public.%I set %I = null where %I is not null and %I < current_date', tbl, col_d, col_d, col_d);
      execute format('update public.%I set %I = null where %I is not null and %I is null', tbl, col_q, col_q, col_d);
    end loop;
  end loop;
end $$;

-- <<< END 20260617234500_estoque_outlier_view_severity_fix.sql <<<

