-- >>> BEGIN 20260618000000_cart_items_quantity_positive_check.sql >>>
-- Integridade do módulo Carrinhos: garante quantity >= 1 em seller_cart_items.
--
-- Contexto: a UI (SortableCartItem / tabela) e o hook useSellerCarts já clampam
-- quantidade para >= 1, mas o banco precisa ser a última linha de defesa contra
-- qualquer caminho que escape a UI (RPC futura, importação em massa, restore,
-- bug de regressão). Sem este CHECK, uma quantidade 0/negativa produziria
-- subtotais zerados/negativos silenciosos no carrinho e no orçamento gerado.
--
-- Idempotente: clampa linhas legadas inválidas antes de aplicar e só adiciona o
-- CHECK se ele ainda não existir.

-- 1) Sanea linhas legadas eventualmente <= 0 (clamp para 1, preserva o item)
UPDATE public.seller_cart_items
SET quantity = 1
WHERE quantity IS NULL OR quantity < 1;

-- 2) Adiciona o CHECK apenas se ainda não existir
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.seller_cart_items'::regclass
      AND conname = 'seller_cart_items_quantity_positive'
  ) THEN
    ALTER TABLE public.seller_cart_items
      ADD CONSTRAINT seller_cart_items_quantity_positive CHECK (quantity >= 1);
  END IF;
END $$;

-- <<< END 20260618000000_cart_items_quantity_positive_check.sql <<<

-- >>> BEGIN 20260618000001_create_rpc_get_catalog_bestseller_page.sql >>>
-- Auditoria do módulo Catálogo (2026-06-18) — Frente 5: ordenação server-side de "+ Vendidos".
--
-- Problema: fetchCatalogPage mapeia os sorts best-seller-* para `name ASC` no servidor;
-- o cliente reordenava SÓ a janela carregada (~2000 de ~7150 ativos), então campeões de
-- venda alfabeticamente tardios nunca chegavam ao topo.
--
-- Correção: RPC que ordena o conjunto GLOBAL de ativos por turnover (mv_product_intelligence)
-- ou por vendas promo (soma de quote_items.quantity) e devolve as próprias linhas de
-- v_products_public (mesmas colunas/grants), com paginação. Tie-break (name, id) espelha
-- byNameThenId() do front, garantindo consistência cliente/servidor.
--
-- Aditiva e reversível: DROP FUNCTION public.get_catalog_bestseller_page(text,int,int);

DROP FUNCTION IF EXISTS public.get_catalog_bestseller_ids(text,int,int);

CREATE OR REPLACE FUNCTION public.get_catalog_bestseller_page(
  p_sort text DEFAULT 'best-seller-supplier',
  p_limit int DEFAULT 500,
  p_offset int DEFAULT 0
)
RETURNS SETOF public.v_products_public
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public
AS $fn$
  SELECT v.*
  FROM public.v_products_public v
  LEFT JOIN mv_product_intelligence mi ON mi.product_id = v.id
  LEFT JOIN (
    SELECT qi.product_id AS pid, sum(COALESCE(qi.quantity,1)) AS promo_qty
    FROM quote_items qi WHERE qi.product_id IS NOT NULL GROUP BY qi.product_id
  ) qs ON qs.pid = v.id
  WHERE v.active = true
  ORDER BY
    CASE WHEN p_sort = 'best-seller-promo'    THEN COALESCE(qs.promo_qty, 0) END DESC NULLS LAST,
    CASE WHEN p_sort = 'best-seller-supplier' THEN COALESCE(mi.turnover_score, 0) END DESC NULLS LAST,
    v.name ASC, v.id ASC
  LIMIT GREATEST(p_limit,0) OFFSET GREATEST(p_offset,0);
$fn$;

COMMENT ON FUNCTION public.get_catalog_bestseller_page(text,int,int) IS
  'Auditoria catálogo 2026-06-18: página ordenada server-side para sorts best-seller-* (turnover/promo) sobre TODOS os ativos. Retorna linhas de v_products_public. Tie-break name,id espelha byNameThenId() do front. Consumida por fetchCatalogPage com fallback gracioso.';

GRANT EXECUTE ON FUNCTION public.get_catalog_bestseller_page(text,int,int) TO anon, authenticated;

-- <<< END 20260618000001_create_rpc_get_catalog_bestseller_page.sql <<<

-- >>> BEGIN 20260618000001_link_unlinked_content_hash_dupes.sql >>>
-- Migration: link_unlinked_content_hash_dupes_20260618
-- Purpose: Link duplicate images by content_hash into canonical groups (flat chains)
-- Result: 2,485 dependents linked across 1,621 groups

BEGIN;

-- Link images that share content_hash but have no canonical assignment yet.
-- The oldest image (by created_at) in each group becomes the canonical root.
WITH groups AS (
  SELECT
    content_hash,
    MIN(id ORDER BY created_at ASC, id ASC) AS root_id,
    array_agg(id ORDER BY created_at ASC, id ASC) AS all_ids
  FROM public.product_images
  WHERE content_hash IS NOT NULL
    AND deleted_at IS NULL
    AND canonical_image_id IS NULL
  GROUP BY content_hash
  HAVING COUNT(*) > 1
),
deps AS (
  SELECT g.root_id, pi.id AS dep_id
  FROM groups g
  JOIN public.product_images pi ON pi.content_hash = g.content_hash
    AND pi.deleted_at IS NULL
    AND pi.canonical_image_id IS NULL
    AND pi.id <> g.root_id
)
UPDATE public.product_images pi
SET
  canonical_image_id = d.root_id,
  is_shared = true,
  last_modified_source = 'migration',
  updated_at = now()
FROM deps d
WHERE pi.id = d.dep_id;

COMMIT;

-- <<< END 20260618000001_link_unlinked_content_hash_dupes.sql <<<

