-- >>> BEGIN 20260618000007_enhance_drift_dashboard_v2.sql >>>
-- Migration: enhance_drift_dashboard_v2_20260618
-- Purpose: Rebuild v_cf_drift_dashboard with 21 metrics including canonical dedup stats
-- Adds: pi_canonical_deps, pi_canonical_roots, pi_has_blurhash, pi_has_content_hash,
--       pi_null_format, pi_shared_no_canonical, pct_deduplicated, pct_blurhash, pct_content_hash

BEGIN;

DROP VIEW IF EXISTS public.v_cf_drift_dashboard;

CREATE VIEW public.v_cf_drift_dashboard
WITH (security_invoker = true)
AS
WITH stats AS (
  SELECT
    (SELECT COUNT(*) FROM cf_recon.cf_image)                                                   AS recon_total,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL)                       AS pi_active_total,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND cf_sync_status='verified')   AS pi_verified,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND cf_sync_status='orphaned')   AS pi_orphaned,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND cf_sync_status='missing')    AS pi_missing,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NOT NULL)                   AS pi_soft_deleted,
    (SELECT COUNT(*) FROM cf_recon.cf_image c
     WHERE NOT EXISTS (SELECT 1 FROM public.product_images p
       WHERE p.cloudflare_image_id = c.image_id AND p.deleted_at IS NULL))                     AS cf_orphans_not_in_pi,
    (SELECT COUNT(*) FROM public.product_images p
     WHERE p.deleted_at IS NULL AND p.cf_sync_status='verified'
       AND NOT EXISTS (SELECT 1 FROM cf_recon.cf_image c WHERE c.image_id = p.cloudflare_image_id)) AS pi_verified_no_recon,
    (SELECT COUNT(*) FROM public.image_backfill_queue WHERE status='pending')                  AS backfill_queue_pending,
    (SELECT COUNT(*) FROM public.image_backfill_queue WHERE status='skipped')                  AS backfill_queue_skipped,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND canonical_image_id IS NOT NULL) AS pi_canonical_deps,
    (SELECT COUNT(DISTINCT canonical_image_id) FROM public.product_images WHERE deleted_at IS NULL AND canonical_image_id IS NOT NULL) AS pi_canonical_roots,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND blurhash IS NOT NULL)         AS pi_has_blurhash,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND content_hash IS NOT NULL)     AS pi_has_content_hash,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND format IS NULL)               AS pi_null_format,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND is_shared = true AND canonical_image_id IS NULL) AS pi_shared_no_canonical
), computed AS (
  SELECT
    *,
    ROUND(pi_verified::numeric / NULLIF(pi_active_total, 0) * 100, 2)      AS pct_verified_active,
    ROUND(cf_orphans_not_in_pi::numeric / NULLIF(recon_total, 0) * 100, 2) AS pct_cf_orphans,
    ROUND(pi_has_blurhash::numeric / NULLIF(pi_active_total, 0) * 100, 2)  AS pct_blurhash,
    ROUND(pi_has_content_hash::numeric / NULLIF(pi_active_total, 0) * 100, 2) AS pct_content_hash,
    ROUND(pi_canonical_deps::numeric / NULLIF(pi_active_total, 0) * 100, 2) AS pct_deduplicated
  FROM stats
)
SELECT * FROM computed;

REVOKE SELECT ON public.v_cf_drift_dashboard FROM anon, authenticated;
GRANT SELECT ON public.v_cf_drift_dashboard TO service_role;

COMMIT;

-- <<< END 20260618000007_enhance_drift_dashboard_v2.sql <<<

-- >>> BEGIN 20260618000008_autolink_trigger_and_reconcile_fn.sql >>>
-- Migration: link_residual_groups_and_autolink_trigger_20260618
-- Purpose: Auto-link trigger for future canonical dedup + reconcile_cf_image_status function
-- Creates:
--   fn_autolink_canonical_on_content_hash() — BEFORE UPDATE trigger function
--   trg_autolink_canonical_on_content_hash — fires on UPDATE OF content_hash
--   reconcile_cf_image_status(p_cf_id, p_exists) — edge function callable reconciler

BEGIN;

-- Auto-link trigger function: links image to canonical group when content_hash is first populated
CREATE OR REPLACE FUNCTION public.fn_autolink_canonical_on_content_hash()
RETURNS TRIGGER LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE
  v_root_id uuid;
BEGIN
  -- Only act when content_hash is being set for the first time
  IF NEW.content_hash IS NULL OR (OLD.content_hash IS NOT NULL AND OLD.content_hash = NEW.content_hash) THEN
    RETURN NEW;
  END IF;
  -- Do not override an existing canonical assignment
  IF NEW.canonical_image_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Find the oldest root in the group (is_shared=false, canonical_image_id=NULL)
  SELECT id INTO v_root_id
  FROM public.product_images
  WHERE content_hash = NEW.content_hash
    AND deleted_at IS NULL
    AND canonical_image_id IS NULL
    AND id <> NEW.id
    AND is_shared = false
  ORDER BY created_at ASC, id ASC
  LIMIT 1;

  IF v_root_id IS NOT NULL THEN
    NEW.canonical_image_id := v_root_id;
    NEW.is_shared := true;
  ELSE
    -- Fallback: inherit root from existing dependent in same group
    SELECT pi2.canonical_image_id INTO v_root_id
    FROM public.product_images pi2
    WHERE pi2.content_hash = NEW.content_hash
      AND pi2.deleted_at IS NULL
      AND pi2.canonical_image_id IS NOT NULL
      AND pi2.id <> NEW.id
    LIMIT 1;

    IF v_root_id IS NOT NULL THEN
      NEW.canonical_image_id := v_root_id;
      NEW.is_shared := true;
    END IF;
    -- If only member → remain as root
  END IF;

  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_autolink_canonical_on_content_hash() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_autolink_canonical_on_content_hash() TO service_role;

DROP TRIGGER IF EXISTS trg_autolink_canonical_on_content_hash ON public.product_images;
CREATE TRIGGER trg_autolink_canonical_on_content_hash
  BEFORE UPDATE OF content_hash
  ON public.product_images
  FOR EACH ROW
  WHEN (NEW.content_hash IS NOT NULL AND (OLD.content_hash IS NULL OR OLD.content_hash <> NEW.content_hash))
  EXECUTE FUNCTION public.fn_autolink_canonical_on_content_hash();

-- Reconcile function: called by edge function after CF verification check
CREATE OR REPLACE FUNCTION public.reconcile_cf_image_status(p_cf_id text, p_exists boolean)
RETURNS TABLE(action text, rows_affected integer)
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE
  v_now timestamptz := now();
  v_rows int := 0;
BEGIN
  IF p_exists THEN
    UPDATE public.product_images
    SET
      cf_sync_status      = 'verified',
      cf_verified_at      = COALESCE(cf_verified_at, v_now),
      cf_last_checked_at  = v_now,
      cf_last_error       = NULL,
      last_modified_source = 'edge_function',
      updated_at          = v_now
    WHERE cloudflare_image_id = p_cf_id
      AND deleted_at IS NULL
      AND cf_sync_status <> 'verified';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    RETURN QUERY SELECT 'mark_verified'::text, v_rows;
  ELSE
    UPDATE public.product_images
    SET
      cf_sync_status      = 'missing',
      cf_check_attempts   = cf_check_attempts + 1,
      cf_last_checked_at  = v_now,
      cf_last_error       = COALESCE(cf_last_error, '') || ' | ' || v_now::text || ' recon: not_found_in_cloudflare',
      last_modified_source = 'edge_function',
      updated_at          = v_now
    WHERE cloudflare_image_id = p_cf_id
      AND deleted_at IS NULL
      AND cf_sync_status = 'verified';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    RETURN QUERY SELECT 'mark_missing'::text, v_rows;
  END IF;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.reconcile_cf_image_status(text, boolean) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.reconcile_cf_image_status(text, boolean) TO service_role;

COMMIT;

-- <<< END 20260618000008_autolink_trigger_and_reconcile_fn.sql <<<

-- >>> BEGIN 20260618000009_health_check_function.sql >>>
-- Migration: create_health_check_function_20260618
-- Purpose: 15-invariant health check for product_images integrity
-- Function: public.fn_product_images_health_check()
-- Checks: C01–C15 covering CF equivalence, canonical dedup, soft-delete, CDN URLs, sync

BEGIN;

CREATE OR REPLACE FUNCTION public.fn_product_images_health_check()
RETURNS TABLE(check_name text, status text, value bigint, threshold bigint, details text)
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
BEGIN
  -- C01: All active images verified in CF
  RETURN QUERY SELECT
    'c01_all_active_verified'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images not verified in CF'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND cf_sync_status <> 'verified';

  -- C02: Zero CF orphans (CF has image not in product_images)
  RETURN QUERY SELECT
    'c02_zero_cf_orphans'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'CF images not in product_images'::text
  FROM cf_recon.cf_image c
  WHERE NOT EXISTS (SELECT 1 FROM public.product_images p
    WHERE p.cloudflare_image_id = c.image_id AND p.deleted_at IS NULL);

  -- C03: cf_recon count matches active product_images count (±5 tolerance)
  RETURN QUERY SELECT
    'c03_recon_pi_sync'::text,
    CASE WHEN ABS(c.recon_total - c.pi_total) <= 5 THEN 'OK' ELSE 'WARN' END,
    ABS(c.recon_total - c.pi_total), 5::bigint,
    'Difference between cf_recon.cf_image and active product_images'::text
  FROM (SELECT
    (SELECT COUNT(*) FROM cf_recon.cf_image) AS recon_total,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL) AS pi_total
  ) c;

  -- C04: No duplicate cloudflare_image_id among active images
  RETURN QUERY SELECT
    'c04_no_duplicate_cf_id'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Duplicate cloudflare_image_id in active images'::text
  FROM (SELECT cloudflare_image_id
    FROM public.product_images WHERE deleted_at IS NULL
    GROUP BY cloudflare_image_id HAVING COUNT(*) > 1) dup;

  -- C05: Soft-deleted images always have a reason
  RETURN QUERY SELECT
    'c05_soft_delete_has_reason'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Soft-deleted images without deleted_reason'::text
  FROM public.product_images
  WHERE deleted_at IS NOT NULL AND (deleted_reason IS NULL OR deleted_reason = '');

  -- C06: No is_active=true on soft-deleted rows
  RETURN QUERY SELECT
    'c06_no_active_deleted'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active=true but soft-deleted images'::text
  FROM public.product_images
  WHERE deleted_at IS NOT NULL AND is_active = true;

  -- C07: Canonical chains are flat (no A→B→C, only A→B)
  RETURN QUERY SELECT
    'c07_canonical_chains_flat'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical pointing to non-root (chain detected)'::text
  FROM public.product_images pi_child
  JOIN public.product_images pi_root ON pi_root.id = pi_child.canonical_image_id
  WHERE pi_child.canonical_image_id IS NOT NULL AND pi_root.canonical_image_id IS NOT NULL;

  -- C08: No canonical cycles (A→B, B→A)
  RETURN QUERY SELECT
    'c08_no_canonical_cycles'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical cycles detected (A→B, B→A)'::text
  FROM public.product_images a
  JOIN public.product_images b ON b.id = a.canonical_image_id AND b.canonical_image_id = a.id;

  -- C09: is_shared=true always has canonical_image_id
  RETURN QUERY SELECT
    'c09_shared_has_canonical'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'is_shared=true without canonical_image_id'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND is_shared = true AND canonical_image_id IS NULL;

  -- C10: All active images have valid CDN URLs
  RETURN QUERY SELECT
    'c10_valid_cdn_urls'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with invalid url_cdn'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND (url_cdn IS NULL OR url_cdn NOT LIKE 'https://imagedelivery.net/%');

  -- C11: No NULL format on active images
  RETURN QUERY SELECT
    'c11_no_null_format'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with NULL format'::text
  FROM public.product_images WHERE deleted_at IS NULL AND format IS NULL;

  -- C12: Alt-text coverage (all active images have meaningful alt text ≥10 chars)
  RETURN QUERY SELECT
    'c12_alt_text_coverage'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with missing/short alt_text'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND (alt_text IS NULL OR LENGTH(alt_text) < 10);

  -- C13: Canonical pointers do not target soft-deleted images
  RETURN QUERY SELECT
    'c13_canonical_not_deleted'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical pointing to soft-deleted image'::text
  FROM public.product_images pi
  WHERE pi.canonical_image_id IS NOT NULL
    AND EXISTS (SELECT 1 FROM public.product_images root
      WHERE root.id = pi.canonical_image_id AND root.deleted_at IS NOT NULL);

  -- C14: No NULL display_order on active images
  RETURN QUERY SELECT
    'c14_display_order_not_null'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with NULL display_order'::text
  FROM public.product_images WHERE deleted_at IS NULL AND display_order IS NULL;

  -- C15: products.primary_image_url in sync with product_images (±5 tolerance)
  RETURN QUERY SELECT
    'c15_primary_image_url_sync'::text,
    CASE WHEN COUNT(*) <= 5 THEN 'OK' ELSE 'WARN' END,
    COUNT(*), 5::bigint,
    'Products where primary_image_url diverges from product_images primary'::text
  FROM public.products p
  JOIN public.product_images pi ON pi.product_id = p.id
    AND pi.is_primary = true AND pi.is_active = true AND pi.deleted_at IS NULL
  WHERE p.is_active = true AND (p.is_deleted IS NULL OR p.is_deleted = false)
    AND p.primary_image_url IS NOT NULL AND p.primary_image_url <> pi.url_cdn;

END;
$$;

REVOKE ALL ON FUNCTION public.fn_product_images_health_check() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_product_images_health_check() TO service_role;

COMMIT;

-- <<< END 20260618000009_health_check_function.sql <<<

-- >>> BEGIN 20260618000010_flatten_canonical_chains.sql >>>
-- Migration: flatten_canonical_chains_20260618 + fix_shared_null_after_flatten_20260618
-- Purpose: Flatten any A→B→C canonical chains to A→C (all deps point directly to root)
-- Then fix CTE artefact where final_root_id resolved to NULL for true roots
-- Result: 65 chains flattened; 65 CTE artefacts corrected via 3-step fix

BEGIN;

-- Step 1: Flatten chains — update deps that point to a non-root to point to the true root
UPDATE public.product_images pi_dep
SET
  canonical_image_id  = pi_root.id,
  last_modified_source = 'migration',
  updated_at          = now()
FROM public.product_images pi_mid
JOIN public.product_images pi_root ON pi_root.id = pi_mid.canonical_image_id
WHERE pi_dep.canonical_image_id = pi_mid.id
  AND pi_mid.canonical_image_id IS NOT NULL  -- pi_mid is itself a dep, not a root
  AND pi_root.canonical_image_id IS NULL     -- pi_root is a true root
  AND pi_dep.deleted_at IS NULL;

-- Step 2 (CTE artefact fix — 3 sub-steps):

-- 2a: Relink is_shared=true / canonical=NULL to root via content_hash (where root exists)
WITH fixable AS (
  SELECT pi.id, g.root_id
  FROM public.product_images pi
  JOIN (
    SELECT content_hash, MIN(id ORDER BY created_at ASC, id ASC) AS root_id
    FROM public.product_images
    WHERE content_hash IS NOT NULL
      AND deleted_at IS NULL
      AND is_shared = false
      AND canonical_image_id IS NULL
    GROUP BY content_hash
  ) g ON g.content_hash = pi.content_hash
  WHERE pi.deleted_at IS NULL
    AND pi.is_shared = true
    AND pi.canonical_image_id IS NULL
    AND pi.id <> g.root_id
)
UPDATE public.product_images pi
SET
  canonical_image_id  = f.root_id,
  last_modified_source = 'migration',
  updated_at          = now()
FROM fixable f
WHERE pi.id = f.id;

-- 2b: For content_hash groups where ALL members lost their canonical (all zeroed by CTE bug),
--     elect the oldest as root and relink the rest
WITH orphan_groups AS (
  SELECT content_hash
  FROM public.product_images
  WHERE deleted_at IS NULL
    AND is_shared = true
    AND canonical_image_id IS NULL
    AND content_hash IS NOT NULL
  GROUP BY content_hash
),
roots AS (
  SELECT DISTINCT ON (og.content_hash) pi.id AS root_id, og.content_hash
  FROM orphan_groups og
  JOIN public.product_images pi ON pi.content_hash = og.content_hash AND pi.deleted_at IS NULL
  ORDER BY og.content_hash, pi.created_at ASC, pi.id ASC
)
-- Promote oldest member to non-shared root
UPDATE public.product_images pi
SET
  is_shared           = false,
  canonical_image_id  = NULL,
  last_modified_source = 'migration',
  updated_at          = now()
FROM roots r
WHERE pi.id = r.root_id;

-- 2c: Relink remaining is_shared=true / canonical=NULL to the newly elected roots
WITH newly_fixed AS (
  SELECT pi.id, g.root_id
  FROM public.product_images pi
  JOIN (
    SELECT content_hash, id AS root_id
    FROM public.product_images
    WHERE deleted_at IS NULL
      AND is_shared = false
      AND canonical_image_id IS NULL
      AND content_hash IS NOT NULL
  ) g ON g.content_hash = pi.content_hash
  WHERE pi.deleted_at IS NULL
    AND pi.is_shared = true
    AND pi.canonical_image_id IS NULL
    AND pi.id <> g.root_id
)
UPDATE public.product_images pi
SET
  canonical_image_id  = f.root_id,
  last_modified_source = 'migration',
  updated_at          = now()
FROM newly_fixed f
WHERE pi.id = f.id;

COMMIT;

-- <<< END 20260618000010_flatten_canonical_chains.sql <<<

-- >>> BEGIN 20260618120000_cart_items_quantity_upper_bound_check.sql >>>
-- Integridade do módulo Carrinhos: completa o invariante de quantidade em
-- seller_cart_items para 1 <= quantity <= 999999.
--
-- Contexto: a migration 20260618000000 adicionou o piso (quantity >= 1), mas
-- não havia TETO no banco. O hook useSellerCarts clampa a edição direta em
-- 999999, porém os caminhos de MESCLAGEM (add/move/duplicate) somavam
-- `existing + qty`. Sem teto no banco, somas repetidas poderiam crescer sem
-- limite e, no extremo, estourar o range de int4 — produzindo subtotais
-- absurdos no carrinho e no orçamento gerado. O cliente passou a clampar o
-- teto; este CHECK é a última linha de defesa para qualquer caminho que escape
-- à UI (RPC futura, importação em massa, restore, regressão).
--
-- Idempotente: clampa linhas legadas > 999999 antes de aplicar e só adiciona o
-- CHECK se ele ainda não existir. Mantido como constraint separada do piso para
-- não precisar derrubar/recriar a constraint já existente.

-- 1) Sanea linhas legadas eventualmente acima do teto (clamp para 999999)
--    LOCK elimina a janela de corrida: sem ele um INSERT/UPDATE concorrente
--    poderia escrever quantity > 999999 entre o UPDATE abaixo e o ADD CONSTRAINT.
LOCK TABLE public.seller_cart_items IN SHARE ROW EXCLUSIVE MODE;

UPDATE public.seller_cart_items
SET quantity = 999999
WHERE quantity > 999999;

-- 2) Adiciona o CHECK de teto apenas se ainda não existir
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.seller_cart_items'::regclass
      AND conname = 'seller_cart_items_quantity_max'
  ) THEN
    ALTER TABLE public.seller_cart_items
      ADD CONSTRAINT seller_cart_items_quantity_max CHECK (quantity <= 999999);
  END IF;
END $$;

-- <<< END 20260618120000_cart_items_quantity_upper_bound_check.sql <<<

-- >>> BEGIN 20260618130000_cart_concurrency_advisory_locks.sql >>>
-- Hardening de concorrencia nos triggers de carrinhos (seller_carts / seller_cart_items).
-- Auditoria exaustiva encontrou dois triggers fazendo read-modify-write SEM lock; sob
-- READ COMMITTED, dois INSERTs concorrentes liam o mesmo estado e violavam invariantes:
--   1) assign_cart_item_sort_order: dois itens recebiam o MESMO sort_order (empate de ordem;
--      nao ha unique em (cart_id, sort_order) que barre).
--   2) enforce_seller_cart_limit: o teto de 3 carrinhos por vendedor podia ser furado (4+),
--      pois o trigger e o UNICO gate (sem exclusion/check de cap).
-- Correcao: advisory lock TRANSACIONAL por chave (cart_id / seller_id), liberado no commit,
-- serializando apenas operacoes concorrentes do MESMO carrinho/vendedor (contencao minima).
-- Namespaces distintos: 415263 (sort_order) e 415264 (limite).

CREATE OR REPLACE FUNCTION public.assign_cart_item_sort_order()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  IF (TG_OP = 'INSERT' AND NEW.sort_order IS NULL)
     OR (TG_OP = 'UPDATE' AND NEW.cart_id <> OLD.cart_id) THEN
    PERFORM pg_advisory_xact_lock(415263, hashtext(NEW.cart_id::text));
    SELECT COALESCE(MAX(sort_order), -1) + 1
      INTO NEW.sort_order
      FROM public.seller_cart_items
     WHERE cart_id = NEW.cart_id
       AND id <> NEW.id;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_seller_cart_limit()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(415264, hashtext(NEW.seller_id::text));
  IF (SELECT count(*) FROM public.seller_carts WHERE seller_id = NEW.seller_id) >= 3 THEN
    RAISE EXCEPTION 'Limite de 3 carrinhos por vendedor atingido' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$;

