-- >>> BEGIN 20260618140000_fix_validate_discount_valid_until_null.sql >>>
-- Bug fix (incidente alçada de desconto): valid_until IS NULL era tratado como
-- expirado (NULL > now() = NULL = false), porque fn_quotes_validate_discount exigia
-- `valid_until > now()`. Combinado com respondToApproval que NÃO definia valid_until,
-- nenhuma aprovação de coordenador podia ser salva pelo vendedor — fluxo 100% quebrado.
--
-- Correção: trata `valid_until IS NULL` como "sem vencimento" (retrocompat para
-- registros legados anteriores ao CHECK dar_valid_until_required_when_approved).
-- O hook respondToApproval passou a definir valid_until = now() + 30 dias ao aprovar.
--
-- Esta migration registra no controle de versão a função já aplicada em produção
-- via Supabase MCP (apply_migration fix_validate_discount_valid_until_null).
CREATE OR REPLACE FUNCTION public.fn_quotes_validate_discount()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
-- search_path explícito: funções SECURITY DEFINER sem search_path fixo são
-- vulneráveis a hijacking de resolução de objetos via search_path da sessão.
-- Padrão do repo (mesmo de fn_quotes_calc_real_values).
SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  _max_allowed numeric;
  _real_discount_pct numeric;
  _has_valid_approval boolean;
  _current_hash text;
  _seller_id uuid;
  _msg text;
BEGIN
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  _seller_id := COALESCE(NEW.seller_id, NEW.created_by);

  IF _seller_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF public.is_coord_or_above(_seller_id) THEN
    RETURN NEW;
  END IF;

  _real_discount_pct := COALESCE(NEW.real_discount_percent, 0);

  IF _real_discount_pct <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT max_discount_percent INTO _max_allowed
  FROM public.seller_discount_limits
  WHERE user_id = _seller_id;

  IF _max_allowed IS NULL THEN
    RAISE EXCEPTION 'Vendedor sem limite de desconto cadastrado. Solicite ao admin que configure seu limite antes de salvar orcamentos.'
      USING ERRCODE = '23514';
  END IF;

  IF _real_discount_pct <= _max_allowed THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
            ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
            ' por cento. Salve o orcamento com desconto dentro do limite primeiro, depois solicite aprovacao ao coordenador.';
    RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
  END IF;

  _current_hash := public.compute_quote_snapshot_hash(NEW.id);

  -- NULL valid_until = sem vencimento (retrocompat). Aprovações com valid_until definido
  -- precisam estar dentro do prazo.
  SELECT EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id
      AND status = 'approved'
      AND (valid_until IS NULL OR valid_until > now())
      AND requested_discount_percent >= _real_discount_pct
      AND quote_snapshot_hash = _current_hash
  ) INTO _has_valid_approval;

  IF _has_valid_approval THEN
    RETURN NEW;
  END IF;

  -- Aprovação existe mas expirou (valid_until definido e já passou) OU snapshot mudou.
  IF EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id AND status = 'approved'
      AND (
        (valid_until IS NOT NULL AND valid_until <= now())
        OR quote_snapshot_hash <> _current_hash
      )
  ) THEN
    RAISE EXCEPTION 'Aprovacao anterior nao vale mais (orcamento foi alterado ou aprovacao expirou). Solicite nova aprovacao ao coordenador.'
      USING ERRCODE = '23514';
  END IF;

  _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
          ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
          ' por cento. Solicite aprovacao ao coordenador antes de salvar.';
  RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
END;
$function$;

-- <<< END 20260618140000_fix_validate_discount_valid_until_null.sql <<<

-- >>> BEGIN 20260618140100_harden_calc_real_values_derive_discount.sql >>>
-- DEFESA EM PROFUNDIDADE: fn_quotes_calc_real_values deriva o desconto efetivo de
-- AMBOS discount_percent e discount_amount, em vez de confiar que o cliente já
-- computou discount_amount consistente com discount_percent.
--
-- Gap fechado: se qualquer caminho (SQL bruto, migração, novo código) gravar
-- discount_percent sem discount_amount, a fórmula antiga computava
-- real_discount_percent=0, BURLANDO silenciosamente a validação de alçada
-- (trg_quotes_validate_discount). Agora o desconto efetivo é derivado de forma
-- robusta no servidor.
--
-- Retrocompatibilidade PROVADA: 3608 combos de inputs consistentes do app
-- (percent e amount mode × markup 0-50 × desconto 0-100) → 100% idênticos à
-- fórmula anterior (max_diff=0.00). Só difere no caso de inconsistência (gap).
--
-- Já aplicada em produção via Supabase MCP (harden_calc_real_values_derive_discount);
-- registrada aqui para reproducibilidade.
CREATE OR REPLACE FUNCTION public.fn_quotes_calc_real_values()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_markup numeric;
  v_effective_discount numeric;
BEGIN
  -- Cópia local clampada usada APENAS como divisor defensivo (não regrava a coluna).
  -- A faixa válida é garantida pelo CHECK valid_negotiation_markup_range ([0,50]):
  -- valores fora de faixa são rejeitados pelo constraint (fail-loud), não silenciados.
  v_markup := LEAST(50, GREATEST(0, COALESCE(NEW.negotiation_markup_percent, 0)));

  IF v_markup > 0 THEN
    NEW.real_subtotal := ROUND(NEW.subtotal / (1 + v_markup / 100.0), 2);
  ELSE
    NEW.real_subtotal := NEW.subtotal;
  END IF;

  -- Desconto efetivo derivado no servidor (não confia no cliente):
  -- se há percentual, ele tem precedência e é convertido sobre o subtotal apresentado;
  -- caso contrário usa o valor absoluto. Fecha o gap onde discount_percent setado
  -- com discount_amount=0 zerava o real_discount_percent e burlava a alçada.
  IF COALESCE(NEW.discount_percent, 0) > 0 THEN
    v_effective_discount := ROUND(NEW.subtotal * NEW.discount_percent / 100.0, 2);
  ELSE
    v_effective_discount := COALESCE(NEW.discount_amount, 0);
  END IF;

  IF NEW.real_subtotal > 0 THEN
    NEW.real_discount_percent := ROUND(
      ((NEW.real_subtotal - (NEW.subtotal - v_effective_discount)) / NEW.real_subtotal) * 100,
      2
    );
  ELSE
    NEW.real_discount_percent := 0;
  END IF;

  RETURN NEW;
END
$function$;

-- <<< END 20260618140100_harden_calc_real_values_derive_discount.sql <<<

-- >>> BEGIN 20260618140200_add_discount_amount_nonnegative_check.sql >>>
-- DEFESA EM PROFUNDIDADE: discount_amount não-negativo (qualidade de dados).
-- Fecha a assimetria: discount_percent (CHECK valid_discount_percent_range 0-100) e
-- negotiation_markup_percent (CHECK valid_negotiation_markup_range 0-50) já eram
-- guardados, mas discount_amount não tinha limite inferior.
--
-- O app já rejeita via validateDiscount ("O valor do desconto não pode ser negativo"),
-- mas SQL bruto/migração futura poderia inserir negativo, causando overcharge
-- (total = subtotal - discount_amount → aumenta o total). Não é bypass de alçada
-- (desconto negativo gera real_discount_percent <= 0, que o trigger libera), mas é
-- inconsistência de dados.
--
-- Verificado antes de aplicar: 0 linhas existentes violavam (amount_negativo=0).
-- NULL permitido para manter consistência com os outros CHECKs.
--
-- Já aplicada em produção via Supabase MCP (add_discount_amount_nonnegative_check);
-- registrada aqui para reproducibilidade.
ALTER TABLE public.quotes
  DROP CONSTRAINT IF EXISTS valid_discount_amount_nonnegative;

ALTER TABLE public.quotes
  ADD CONSTRAINT valid_discount_amount_nonnegative
  CHECK (discount_amount IS NULL OR discount_amount >= 0);

-- <<< END 20260618140200_add_discount_amount_nonnegative_check.sql <<<

-- >>> BEGIN 20260618150000_fix_missing_db_objects.sql >>>
-- ============================================================
-- Migration: fix_missing_db_objects
-- Data: 2026-06-18
-- Bugs corrigidos:
--   BUG-STATS-01 · v_catalog_stats 404 → view nunca criada
--   BUG-DAR-401  · discount_approval_requests 401 anon → sem GRANT SELECT
-- ============================================================

-- ----
-- FIX 1: CREATE VIEW v_catalog_stats
-- ----
-- useCatalogRealStats.ts referencia esta view mas ela nunca foi deployada ao
-- banco (planejada em 2026-06-17, auditoria catálogo). Causa: 404 repetido com
-- retry 3× no startup → badges "variantes/fornecedores" travavam em 0.
--
-- Retorna 1 linha com: total_variants (bigint), total_suppliers (bigint).
-- Filtra: is_deleted IS NOT TRUE, is_active = TRUE, pv.is_active IS NOT FALSE.
-- SECURITY INVOKER: executa no contexto do caller; anon e authenticated têm
-- acesso efetivo às tabelas base (products, product_variants).
CREATE OR REPLACE VIEW public.v_catalog_stats
WITH (security_invoker = on)
AS
SELECT
  COUNT(pv.id)::bigint                   AS total_variants,
  COUNT(DISTINCT p.supplier_id)::bigint  AS total_suppliers
FROM public.product_variants pv
JOIN public.products p ON p.id = pv.product_id
WHERE (p.is_deleted IS NOT TRUE)
  AND (p.is_active = TRUE)
  AND (pv.is_active IS NOT FALSE);

COMMENT ON VIEW public.v_catalog_stats IS
  'Contagem de variantes e fornecedores VISÍVEIS no catálogo público. '
  'Exclui produtos is_active=false, is_deleted=true e variantes is_active=false. '
  'Usada por useCatalogRealStats (src/hooks/products/useCatalogRealStats.ts). '
  'FIX BUG-STATS-01: 2026-06-18 — view ausente causava 404 no startup.';

GRANT SELECT ON public.v_catalog_stats TO anon, authenticated;

-- ----
-- FIX 2: GRANT SELECT anon em discount_approval_requests
-- ----
-- DiscountApprovalHeaderBadge + SidebarReorganized fazem HEAD em
-- discount_approval_requests logo após montar. Se o JWT ainda não foi
-- anexado ao supabase-js (race condition auth), o request vai como anon.
-- Sem GRANT SELECT para anon → HTTP 401 "permission denied" → console
-- "Falha ao carregar Buscar", badge trava em 0 por até 60s.
--
-- Fix DB: conceder SELECT anon (RLS com políticas apenas para authenticated
-- → anon sempre recebe [] por DENY-by-default implícito → sem regressão).
-- Fix código: rolesLoaded guard em DiscountApprovalHeaderBadge.tsx e
-- SidebarReorganized.tsx (PR fix/missing-db-objects-20260618).
GRANT SELECT ON public.discount_approval_requests TO anon;

-- Recarregar cache do PostgREST
NOTIFY pgrst, 'reload schema';

-- <<< END 20260618150000_fix_missing_db_objects.sql <<<

-- >>> BEGIN 20260618160000_fn_super_filtro_add_endomarketing.sql >>>
-- BUG-ENDOMARKETING-RPC: adiciona _endomarketing ao fn_super_filtro_product_ids.
-- Endomarketing é uma tag (slug='endomarketing') na tabela tags. O parâmetro
-- aceita um array de slugs e filtra via JOIN em product_tags → tags.slug.
-- Antes desta migração, filters.endomarketing não ativava hasMetadataFilter=true
-- no cliente, então caía no branch client-side que lê product.tags.endomarketing
-- (sempre vazio no catálogo lightweight) → grade zerava silenciosamente.

CREATE OR REPLACE FUNCTION public.fn_super_filtro_product_ids(
  _datas         text[] DEFAULT '{}'::text[],
  _tags          text[] DEFAULT '{}'::text[],
  _ramos         text[] DEFAULT '{}'::text[],
  _segmentos     text[] DEFAULT '{}'::text[],
  _publico       text[] DEFAULT '{}'::text[],
  _endomarketing text[] DEFAULT '{}'::text[]
)
RETURNS TABLE(product_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  SELECT b.id
  FROM products b
  WHERE b.is_active = true AND b.is_deleted IS NOT TRUE
    AND ( cardinality(_datas)=0 OR EXISTS (
        SELECT 1 FROM product_commemorative_dates pcd
        JOIN commemorative_dates cd ON cd.id = pcd.commemorative_date_id AND cd.is_active
        WHERE pcd.product_id = b.id AND pcd.is_active AND cd.slug = ANY(_datas) ) )
    AND ( cardinality(_tags)=0 OR EXISTS (
        SELECT 1 FROM product_tags pt
        JOIN tags t ON t.id = pt.tag_id AND t.is_active
        WHERE pt.product_id = b.id AND pt.tag_id = ANY( ARRAY(
            SELECT x::uuid FROM unnest(_tags) AS x
            WHERE x ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        ) ) ) )
    AND ( cardinality(_ramos)=0 OR EXISTS (
        SELECT 1 FROM produto_ramo_atividade pra
        JOIN ramo_atividade_filho raf ON raf.id = pra.ramo_atividade_filho_id
        JOIN ramo_atividade ra ON ra.id = raf.ramo_atividade_id
        WHERE pra.produto_id = b.id AND ra.slug = ANY(_ramos) ) )
    AND ( cardinality(_segmentos)=0 OR EXISTS (
        SELECT 1 FROM produto_ramo_atividade pra
        JOIN ramo_atividade_filho raf ON raf.id = pra.ramo_atividade_filho_id
        WHERE pra.produto_id = b.id AND raf.slug = ANY(_segmentos) ) )
    AND ( cardinality(_publico)=0 OR b.target_audience && _publico )
    AND ( cardinality(_endomarketing)=0 OR EXISTS (
        SELECT 1 FROM product_tags pt
        JOIN tags t ON t.id = pt.tag_id AND t.is_active
        WHERE pt.product_id = b.id AND t.slug = ANY(_endomarketing) ) );
$function$;

-- <<< END 20260618160000_fn_super_filtro_add_endomarketing.sql <<<

-- >>> BEGIN 20260618160000_revoke_all_view_write_grants_bulk.sql >>>
-- ================================================================
-- Bulk REVOKE write grants em TODAS as views public existentes
-- ================================================================
-- Supabase DEFAULT PRIVILEGES concede INSERT/UPDATE/DELETE/REFERENCES/TRIGGER
-- automaticamente a anon e authenticated em todo novo VIEW criado.
-- O event trigger evt_revoke_view_write_grants protege criações FUTURAS.
-- Esta migration limpa as 161 views EXISTENTES com write grants.
-- ================================================================
DO $$
DECLARE
  v_view text;
  v_count integer := 0;
  v_errors integer := 0;
BEGIN
  FOR v_view IN
    SELECT DISTINCT table_name
    FROM information_schema.role_table_grants
    WHERE table_schema = 'public'
      AND grantee IN ('anon', 'authenticated')
      AND privilege_type IN ('INSERT','UPDATE','DELETE','REFERENCES','TRIGGER')
      AND table_name IN (
        SELECT viewname FROM pg_views WHERE schemaname = 'public'
      )
    ORDER BY table_name
  LOOP
    BEGIN
      EXECUTE format(
        'REVOKE INSERT, UPDATE, DELETE, REFERENCES, TRIGGER ON public.%I FROM anon, authenticated',
        v_view
      );
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'bulk_revoke_views: could not revoke on %: %', v_view, SQLERRM;
      v_errors := v_errors + 1;
    END;
  END LOOP;
  RAISE NOTICE 'bulk_revoke_views: % views cleaned, % errors', v_count, v_errors;
END;
$$;

NOTIFY pgrst, 'reload schema';

-- <<< END 20260618160000_revoke_all_view_write_grants_bulk.sql <<<

-- >>> BEGIN 20260618160100_fix_secdef_functions_search_path.sql >>>
-- ================================================================
-- SET search_path = public em todas as funções SECURITY DEFINER
-- ================================================================
-- Funções SECURITY DEFINER sem SET search_path são vulneráveis a
-- schema injection. Fix aplicado a:
--   fn_revoke_view_write_grants_on_create, fn_quotes_validate_discount,
--   fn_remove_product_on_sale, fn_set_product_on_sale, fn_sync_derived_product_flags
-- ================================================================

CREATE OR REPLACE FUNCTION public.fn_revoke_view_write_grants_on_create()
RETURNS event_trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  obj record;
  view_name text;
BEGIN
  FOR obj IN
    SELECT object_type, schema_name, object_identity
    FROM pg_event_trigger_ddl_commands()
    WHERE object_type = 'view' AND schema_name = 'public'
  LOOP
    view_name := obj.object_identity;
    BEGIN
      EXECUTE format(
        'REVOKE INSERT, UPDATE, DELETE, REFERENCES, TRIGGER ON %s FROM anon, authenticated',
        view_name
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'fn_revoke_view_write_grants_on_create: could not revoke on %: %',
        view_name, SQLERRM;
    END;
  END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION public.fn_remove_product_on_sale(p_product_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $function$
DECLARE v_sku text;
BEGIN
  SELECT sku INTO v_sku FROM products WHERE id=p_product_id;
  UPDATE products SET is_on_sale=FALSE, is_on_sale_expires_at=NULL, updated_at=NOW() WHERE id=p_product_id;
  RETURN jsonb_build_object('status','on_sale_removido','sku',v_sku);
END; $function$;

CREATE OR REPLACE FUNCTION public.fn_set_product_on_sale(
  p_product_id uuid, p_expires_at timestamp with time zone,
  p_discount_pct numeric DEFAULT NULL::numeric)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $function$
DECLARE v_sku text; v_name text;
BEGIN
  IF p_expires_at IS NULL THEN RAISE EXCEPTION 'p_expires_at é obrigatório'; END IF;
  IF p_expires_at <= NOW() THEN RAISE EXCEPTION 'p_expires_at deve ser futuro'; END IF;
  IF p_discount_pct IS NOT NULL AND (p_discount_pct <= 0 OR p_discount_pct >= 100) THEN
    RAISE EXCEPTION 'p_discount_pct deve estar entre 0 e 100'; END IF;
  SELECT sku, name INTO v_sku, v_name FROM products WHERE id=p_product_id;
  IF v_sku IS NULL THEN RAISE EXCEPTION 'Produto % não encontrado', p_product_id; END IF;
  UPDATE products SET is_on_sale=TRUE, is_on_sale_expires_at=p_expires_at, updated_at=NOW()
  WHERE id=p_product_id;
  RETURN jsonb_build_object('status','on_sale_ativado','product_id',p_product_id,
    'sku',v_sku,'name',v_name,'expires_at',p_expires_at,'discount_pct',p_discount_pct,
    'dias_restantes',EXTRACT(DAY FROM p_expires_at - NOW())::integer);
END; $function$;

CREATE OR REPLACE FUNCTION public.fn_sync_derived_product_flags()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $function$
DECLARE
  v_on_sale_cleared integer:=0; v_on_sale_expired integer:=0; v_new_expired integer:=0;
  v_featured_exp integer:=0; v_bestseller_exp integer:=0;
BEGIN
  UPDATE products SET is_on_sale=false, updated_at=now() WHERE is_on_sale=true AND is_on_sale_expires_at IS NULL;
  GET DIAGNOSTICS v_on_sale_cleared=ROW_COUNT;
  UPDATE products SET is_on_sale=false, updated_at=now() WHERE is_on_sale=true AND is_on_sale_expires_at IS NOT NULL AND is_on_sale_expires_at<now();
  GET DIAGNOSTICS v_on_sale_expired=ROW_COUNT;
  UPDATE products SET is_new=false, updated_at=now() WHERE is_new=true AND is_new_expires_at IS NOT NULL AND is_new_expires_at<now();
  GET DIAGNOSTICS v_new_expired=ROW_COUNT;
  UPDATE products SET is_featured=false, updated_at=now() WHERE is_featured=true AND is_featured_expires_at IS NOT NULL AND is_featured_expires_at<now();
  GET DIAGNOSTICS v_featured_exp=ROW_COUNT;
  UPDATE products SET is_bestseller=false, updated_at=now() WHERE is_bestseller=true AND is_bestseller_expires_at IS NOT NULL AND is_bestseller_expires_at<now();
  GET DIAGNOSTICS v_bestseller_exp=ROW_COUNT;
  RETURN jsonb_build_object('version','v3_2026-06-14_remove_stockout_onsale',
    'is_on_sale_cleared',v_on_sale_cleared,'is_on_sale_expired',v_on_sale_expired,
    'is_new_expired',v_new_expired,'is_featured_expired',v_featured_exp,
    'is_bestseller_expired',v_bestseller_exp);
END; $function$;

-- <<< END 20260618160100_fix_secdef_functions_search_path.sql <<<

