-- >>> BEGIN 20260618204424_get_catalog_bestseller_page_v2.sql >>>
-- DRIFT MIGRATION (2026-06-19 audit GAP-4)
-- Função criada diretamente no banco em 2026-06-18 sem arquivo correspondente.
-- Este arquivo codifica o estado atual para rastreamento e reprodutibilidade.
--
-- get_catalog_bestseller_page v2:
--   • Remove hard cap de 2000 (v1 usava LEAST(..., 2000))
--   • best-seller-supplier: ORDER BY turnover_score DESC (mv_product_intelligence)
--   • best-seller-promo: ORDER BY sum(quote_items.quantity) DESC (vendas reais)
--   • Fallback graceful: name ASC para p_sort inválido
--   • GREATEST(p_limit, 0) previne LIMIT negativo
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.get_catalog_bestseller_page(
  p_sort   text    DEFAULT 'best-seller-supplier',
  p_limit  integer DEFAULT 500,
  p_offset integer DEFAULT 0
)
RETURNS SETOF public.v_products_public
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = 'public'
AS $function$
DECLARE
  -- Remove hard cap de 2000; aceita qualquer limit >= 0; default 500.
  v_limit  integer := GREATEST(COALESCE(p_limit, 500), 0);
  v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
  v_sql    text;
BEGIN
  IF p_sort = 'best-seller-supplier' THEN
    v_sql := '
      SELECT vp.*
      FROM public.v_products_public vp
      LEFT JOIN public.mv_product_intelligence mi ON mi.product_id = vp.id
      WHERE vp.active = true
      ORDER BY COALESCE(mi.turnover_score, 0) DESC NULLS LAST, vp.name ASC, vp.id ASC
      LIMIT ' || v_limit || ' OFFSET ' || v_offset;

  ELSIF p_sort = 'best-seller-promo' THEN
    -- Sort por quote_items (vendas reais em orçamentos aprovados/pendentes/enviados)
    v_sql := '
      SELECT vp.*
      FROM public.v_products_public vp
      LEFT JOIN (
        SELECT product_id AS pid, sum(COALESCE(quantity, 1)) AS promo_qty
        FROM public.quote_items
        WHERE product_id IS NOT NULL
        GROUP BY product_id
      ) qs ON qs.pid = vp.id
      WHERE vp.active = true
      ORDER BY
        COALESCE(qs.promo_qty, 0) DESC NULLS LAST,
        COALESCE(vp.is_bestseller, false) DESC,
        vp.name ASC, vp.id ASC
      LIMIT ' || v_limit || ' OFFSET ' || v_offset;

  ELSE
    -- Fallback graceful: name ASC para p_sort inválido ou NULL
    v_sql := '
      SELECT vp.*
      FROM public.v_products_public vp
      WHERE vp.active = true
      ORDER BY vp.name ASC, vp.id ASC
      LIMIT ' || v_limit || ' OFFSET ' || v_offset;
  END IF;

  RETURN QUERY EXECUTE v_sql;
END;
$function$;

COMMENT ON FUNCTION public.get_catalog_bestseller_page(text,integer,integer) IS
  'Sort server-side de v_products_public para best-seller-supplier (turnover_score) e
   best-seller-promo (quote_items). v2 2026-06-18: sem hard cap de 2000.
   Tie-break name ASC, id ASC. STABLE, SECURITY DEFINER, search_path=public.';

GRANT EXECUTE ON FUNCTION public.get_catalog_bestseller_page(text,integer,integer)
  TO anon, authenticated;

-- <<< END 20260618204424_get_catalog_bestseller_page_v2.sql <<<

-- >>> BEGIN 20260618204628_get_promo_sales_ranking.sql >>>
-- DRIFT MIGRATION (2026-06-19 audit GAP-4)
-- get_promo_sales_ranking: nova função para ranking de vendas em orçamentos.
-- Criada diretamente no banco em 2026-06-18 sem arquivo correspondente.
-- Usada pelo sort best-seller-promo como alternativa mais precisa ao is_bestseller.
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.get_promo_sales_ranking()
RETURNS TABLE(product_id uuid, total_qty bigint)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = 'public'
AS $function$
  SELECT
    qi.product_id,
    COALESCE(SUM(qi.quantity), 0)::bigint AS total_qty
  FROM quote_items qi
  JOIN quotes q ON q.id = qi.quote_id
  WHERE qi.product_id IS NOT NULL
    AND q.status IN ('approved', 'pending', 'sent', 'viewed', 'accepted')
  GROUP BY qi.product_id
  ORDER BY total_qty DESC;
$function$;

COMMENT ON FUNCTION public.get_promo_sales_ranking() IS
  'Ranking de produtos por volume em orçamentos não-rascunho.
   Audit-10-10 2026-06-18. Drift codificado em 2026-06-19.';

GRANT EXECUTE ON FUNCTION public.get_promo_sales_ranking()
  TO anon, authenticated;

-- <<< END 20260618204628_get_promo_sales_ranking.sql <<<

-- >>> BEGIN 20260618205528_mv_product_leaf_category_level_first.sql >>>
-- DRIFT MIGRATION (2026-06-19 audit GAP-4)
-- mv_product_leaf_category v2: algoritmo level-first (categoria mais profunda primeiro).
--
-- MUDANÇA vs v1:
--   v1 (original): ORDER BY is_primary DESC, level DESC
--   v2 (este):     ORDER BY level DESC, is_primary DESC
--
-- Impacto:
--   • 4782 produtos (63%) sem mudança
--   • 2792 produtos (37%) agora exibem categoria mais específica
--   • 0 produtos ficam em categoria menos específica (zero regressões)
--   • avg_level: 2.60 → 3.25 (+0.65 níveis)
--
-- Justificativa:
--   O objetivo de leaf_category_id é mostrar o produto na subcategoria mais
--   específica possível para melhor experiência de navegação. O critério
--   is_primary deve ser tie-break, não prioridade absoluta. Com is_primary
--   como primeiro critério, 2792 produtos de nível 4 eram exibidos no nível
--   2 simplesmente porque o assignment de nível 2 era o primário.
-- --------------------------------------------------------------------------

DROP MATERIALIZED VIEW IF EXISTS public.mv_product_leaf_category CASCADE;

CREATE MATERIALIZED VIEW public.mv_product_leaf_category AS
  SELECT DISTINCT ON (pca.product_id)
    pca.product_id,
    c.id          AS leaf_category_id,
    c.name        AS leaf_category_name,
    c.level       AS leaf_category_level,
    c.parent_id   AS leaf_category_parent_id,
    c.slug        AS leaf_category_slug,
    -- leaf_category_id_safe: restrito ao branch do main_category_id
    CASE
      WHEN p.main_category_id IS NULL          THEN c.id
      WHEN c.id = p.main_category_id           THEN c.id
      WHEN EXISTS (
        SELECT 1 FROM category_ancestors ca
        WHERE ca.descendant_id = c.id
          AND ca.ancestor_id   = p.main_category_id
      )                                        THEN c.id
      ELSE NULL
    END AS leaf_category_id_safe
  FROM product_category_assignments pca
  JOIN categories c  ON c.id  = pca.category_id
  LEFT JOIN products p ON p.id = pca.product_id
  ORDER BY
    pca.product_id,
    c.level           DESC NULLS LAST,   -- v2: profundidade PRIMEIRO (era is_primary)
    pca.is_primary    DESC NULLS LAST,   -- tie-break: primário antes de não-primário
    pca.display_order ASC,
    c.name            ASC
WITH DATA;

-- Índices
CREATE UNIQUE INDEX idx_mv_product_leaf_category_product_id
  ON public.mv_product_leaf_category (product_id);

CREATE INDEX idx_mv_product_leaf_category_leaf_id
  ON public.mv_product_leaf_category (leaf_category_id);

-- <<< END 20260618205528_mv_product_leaf_category_level_first.sql <<<

