-- Onda 7 (corrigida) — RLS WITH CHECK em password_reset_requests + frontend_telemetry

-- 1) password_reset_requests
DO $$
DECLARE pol record;
BEGIN
  FOR pol IN
    SELECT policyname FROM pg_policies
     WHERE schemaname='public' AND tablename='password_reset_requests' AND cmd='INSERT'
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.password_reset_requests', pol.policyname);
  END LOOP;
END $$;

CREATE POLICY "prr_insert_validated"
  ON public.password_reset_requests
  FOR INSERT
  TO anon, authenticated
  WITH CHECK (
    email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
    AND length(email) <= 320
    AND NOT EXISTS (
      SELECT 1 FROM public.password_reset_requests prr
       WHERE lower(prr.email) = lower(password_reset_requests.email)
         AND prr.requested_at > now() - interval '60 seconds'
    )
  );

-- 2) frontend_telemetry
DO $$
DECLARE pol record;
BEGIN
  FOR pol IN
    SELECT policyname FROM pg_policies
     WHERE schemaname='public' AND tablename='frontend_telemetry' AND cmd='INSERT'
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.frontend_telemetry', pol.policyname);
  END LOOP;
END $$;

CREATE POLICY "ft_insert_validated"
  ON public.frontend_telemetry
  FOR INSERT
  TO anon, authenticated
  WITH CHECK (
    event_type IN ('page_view','web_vital','error','perf','interaction')
    AND length(coalesce(metadata::text, '')) < 8000
  );

-- <<< END 20260619160500_062cd222-4cdd-4fe5-a2f4-2a24d0bdc023.sql <<<

-- >>> BEGIN 20260619200000_add_keyset_pagination_indexes.sql >>>
-- Keyset pagination indexes for stockFetcher.ts (fetchPaginatedFromBridge).
--
-- Pattern:  SELECT ... FROM <table> WHERE is_active = true AND id > $lastId
--           ORDER BY id ASC LIMIT 1000;
--
-- Without a partial index, PostgreSQL performs a full sequential scan filtered
-- by is_active and then sorts by id — O(N) for every page. With a partial index
-- on (id ASC) WHERE is_active = true, the planner uses a forward index scan
-- starting exactly at lastId, stopping after 1000 rows: O(page_size) per page.
--
-- Tables covered (all three have `is_active = true` filter in stockFetcher):
--   1. products              — filtered via v_products_public view (active alias)
--   2. product_variants      — is_active = true
--   3. variant_supplier_sources — is_active = true
--
-- categories / suppliers / product_images / mv_stock_velocity are fetched
-- without an is_active filter; their primary key already serves the keyset
-- ORDER BY id scan, so no extra index is needed.

-- 1. products: keyset scan WHERE is_active = true ORDER BY id
CREATE INDEX IF NOT EXISTS idx_products_keyset_active
  ON public.products (id ASC)
  WHERE is_active = true;

-- 2. product_variants: keyset scan WHERE is_active = true ORDER BY id
CREATE INDEX IF NOT EXISTS idx_product_variants_keyset_active
  ON public.product_variants (id ASC)
  WHERE is_active = true;

-- 3. variant_supplier_sources: keyset scan WHERE is_active = true ORDER BY id
CREATE INDEX IF NOT EXISTS idx_variant_supplier_sources_keyset_active
  ON public.variant_supplier_sources (id ASC)
  WHERE is_active = true;

-- <<< END 20260619200000_add_keyset_pagination_indexes.sql <<<

-- >>> BEGIN 20260619210000_fix_cron_connections_auto_test_canonical_url.sql >>>
-- ============================================================
-- MIGRAÇÃO CORRETIVA: fix_cron_connections_auto_test_canonical_url
-- DATA:   2026-06-19
-- MOTIVO: Drift entre o histórico de migrations e o estado vivo do banco.
--
--   A última migration que tocou o cron 'connections-auto-test'
--   (20260602020000_fix_hardcoded_api_key_cron) recria o job com a URL
--   HARDCODED do projeto PROIBIDO (Lovable Cloud) 'pqpdolkaeqlyzpdpbizo'.
--   A produção já foi corrigida para o projeto canônico Gold
--   'doufsxqlfjyuvxuezpln' (SSOT — ver CLAUDE.md REGRA #1), mas um replay
--   limpo das migrations (branch novo / DR rebuild) reintroduziria a URL
--   proibida — o cron passaria a chamar a edge function no projeto errado.
--
--   Esta migration faz o histórico convergir para o estado canônico que já
--   está em produção. É idempotente e NÃO altera o comportamento em prod
--   (recria o job com a forma idêntica à que já existe).
--
-- VERIFICAÇÃO (live DB doufsxqlfjyuvxuezpln, 2026-06-19, read-only):
--   • Nenhuma função hardcoda 'pqpdolkaeqlyzpdpbizo' (scan pg_get_functiondef).
--   • Nenhum cron job referencia o ref proibido.
--   • public.get_edge_functions_base_url() resolve para a URL canônica.
--   • cron 'connections-auto-test' (jobid 48) JÁ usa a URL canônica.
--   Portanto este é o único ponto de drift remanescente (apenas no histórico).
-- ============================================================

-- Unschedule idempotente: remove pelo jobid resolvido a partir do nome.
-- Se o job não existir, o SELECT retorna conjunto vazio (no-op, sem erro) —
-- diferente de cron.unschedule('<nome>'), que lança exceção se ausente.
SELECT cron.unschedule(jobid)
FROM cron.job
WHERE jobname = 'connections-auto-test';

-- Recria o job com a URL CANÔNICA e secret resolvido via
-- get_edge_function_secret() — forma idêntica à já presente em produção.
SELECT cron.schedule(
    'connections-auto-test',
    '*/15 * * * *',
    $$
    SELECT net.http_post(
        url := 'https://doufsxqlfjyuvxuezpln.supabase.co/functions/v1/connections-auto-test',
        headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'x-cron-secret', public.get_edge_function_secret('CRON_SECRET')
        ),
        body := '{"trigger":"cron"}'::jsonb,
        timeout_milliseconds := 30000
    ) AS request_id;
    $$
);

-- <<< END 20260619210000_fix_cron_connections_auto_test_canonical_url.sql <<<

-- >>> BEGIN 20260620000000_fix_recent_restocks_and_metrics.sql >>>
-- ============================================================================
-- BUG-DB-1: fn_get_recent_restocks + fn_get_stock_notification_counts
--   Ambas as funções usavam `restock_detected=true` (campo legado) em vez de
--   `restock_zero_to_positive=true` (campo canônico). Resultado: 24 produtos
--   faltando no sino "Chegou" e no contador de restocks por período.
--
-- BUG-DB-4: fn_get_reposicao_metrics
--   O bloco SELECT que calcula v_ativas (variantes zeradas com previsão) e
--   v_aguardando (todas as variantes com previsão futura) só verificava o
--   slot next_date_1, ignorando next_date_2 … next_date_6. O dado correto
--   deve checar qualquer um dos 6 slots, igual a vw_product_availability.
--
-- Índice afetado: idx_sds_cenario_a ficará órfão após BUG-DB-1 ser corrigido
-- (não referenciado por nenhuma função). Mantido por ora para queries ad-hoc;
-- pode ser removido em migração futura após confirmar que não é usado.
-- ============================================================================

-- ─── 1. fn_get_recent_restocks (BUG-DB-1) ───────────────────────────────────
-- Substitui restock_detected por restock_zero_to_positive.
-- Remove redundância COALESCE(stock_open,0)=0 que restock_zero_to_positive já implica.
-- Mantém assinatura (p_limit int, p_since date) idêntica para compatibilidade.

DROP FUNCTION IF EXISTS public.fn_get_recent_restocks(integer, date);

CREATE OR REPLACE FUNCTION public.fn_get_recent_restocks(
  p_limit int DEFAULT 30,
  p_since date DEFAULT NULL
)
RETURNS TABLE(product_id uuid, product_name text, product_sku text, image_url text,
              stock_quantity int, supplier_id uuid, supplier_name text, last_restock_date date)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  WITH cenario_a AS (
    SELECT sds.product_id, max(sds.summary_date) AS last_restock_date
    FROM stock_daily_summary sds
    WHERE sds.restock_zero_to_positive = true
      AND COALESCE(sds.stock_close, 0) > 0
      AND sds.summary_date >= GREATEST(
        COALESCE(p_since, (CURRENT_DATE - INTERVAL '30 days')::date),
        (CURRENT_DATE - INTERVAL '30 days')::date
      )
    GROUP BY sds.product_id
  )
  SELECT p.id, p.name::text, p.sku::text, p.primary_image_url::text, p.stock_quantity,
         p.supplier_id, s.name::text, ca.last_restock_date
  FROM cenario_a ca
  JOIN products p ON p.id = ca.product_id
  LEFT JOIN suppliers s ON s.id = p.supplier_id
  WHERE p.is_active = true AND p.stock_quantity > 0
  ORDER BY ca.last_restock_date DESC, p.stock_quantity DESC, p.id
  LIMIT GREATEST(p_limit, 0);
$$;

-- ─── 2. fn_get_stock_notification_counts (BUG-DB-1) ─────────────────────────
-- O sub-count de 'restocks' usava a mesma lógica legada. Atualizado para
-- restock_zero_to_positive = true, alinhando com fn_get_recent_restocks.

DROP FUNCTION IF EXISTS public.fn_get_stock_notification_counts(date);

CREATE OR REPLACE FUNCTION public.fn_get_stock_notification_counts(p_since date DEFAULT NULL)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT jsonb_build_object(
    'stockout', (
      SELECT count(*) FROM products
      WHERE is_active AND is_stockout
        AND (p_since IS NULL OR last_stock_update_at >= p_since::timestamptz)
    ),
    'low_stock', (
      SELECT count(*) FROM products p LEFT JOIN suppliers s ON s.id = p.supplier_id
      WHERE p.is_active AND p.is_stockout = false AND p.stock_quantity > 0
        AND p.stock_quantity <= COALESCE(s.low_stock_threshold, 10)
        AND (p_since IS NULL OR p.last_stock_update_at >= p_since::timestamptz)
    ),
    'novelties', (
      SELECT count(DISTINCT pn.product_id)
      FROM product_novelties pn JOIN products p ON p.id = pn.product_id
      WHERE pn.is_active AND (pn.expires_at IS NULL OR pn.expires_at > now())
        AND p.is_active AND p.is_stockout = false AND p.sale_price > 0
        AND p.primary_image_url IS NOT NULL AND p.primary_image_url <> ''
        AND (p_since IS NULL OR pn.detected_at >= p_since::timestamptz)
    ),
    'restocks', (
      SELECT count(*) FROM (
        SELECT sds.product_id
        FROM stock_daily_summary sds
        JOIN products p ON p.id = sds.product_id
        WHERE sds.restock_zero_to_positive = true
          AND COALESCE(sds.stock_close, 0) > 0
          AND sds.summary_date >= GREATEST(
            COALESCE(p_since, (CURRENT_DATE - INTERVAL '30 days')::date),
            (CURRENT_DATE - INTERVAL '30 days')::date
          )
          AND p.is_active AND p.stock_quantity > 0
        GROUP BY sds.product_id
      ) r
    )
  );
$$;

-- ─── 3. fn_get_reposicao_metrics (BUG-DB-4) ─────────────────────────────────
-- v_ativas/v_aguardando agora checam todos os 6 slots next_date_1…next_date_6,
-- igual à lógica de vw_product_availability. Versão bump: v4_stable_20260620.

CREATE OR REPLACE FUNCTION public.fn_get_reposicao_metrics()
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_today          date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_hoje           int;
  v_7d             int;
  v_15d            int;
  v_30d            int;
  v_top_supplier   text;
  v_top_count      int;
  v_ativas         int;
  v_aguardando     int;
  v_pct_ativas     numeric;
  v_total_vars     int;
  v_data_min       date;
  v_dias_hist      int;
BEGIN
  SELECT
    COUNT(DISTINCT CASE WHEN sd.summary_date = v_today        THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 7   THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 15  THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 30  THEN sd.product_id END),
    MIN(sd.summary_date),
    (v_today - MIN(sd.summary_date))
  INTO v_hoje, v_7d, v_15d, v_30d, v_data_min, v_dias_hist
  FROM stock_daily_summary sd
  JOIN products p ON p.id = sd.product_id
  WHERE sd.restock_zero_to_positive = true
    AND sd.summary_date >= v_today - 30
    AND sd.stock_close > 0
    AND p.is_active = true;

  SELECT s.name, COUNT(DISTINCT sd.product_id)
  INTO v_top_supplier, v_top_count
  FROM stock_daily_summary sd
  JOIN suppliers s ON s.id = sd.supplier_id
  JOIN products p ON p.id = sd.product_id
  WHERE sd.restock_zero_to_positive = true
    AND sd.summary_date >= v_today - 7
    AND sd.stock_close > 0
    AND p.is_active = true
  GROUP BY s.name
  ORDER BY COUNT(DISTINCT sd.product_id) DESC
  LIMIT 1;

  SELECT COUNT(*) INTO v_total_vars
  FROM product_variants WHERE is_active = true;

  -- BUG-DB-4 fix: verifica todos os 6 slots de data futura, não só next_date_1
  SELECT
    COUNT(*) FILTER (
      WHERE pv.stock_quantity = 0
        AND (
          (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today) OR
          (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > v_today) OR
          (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > v_today) OR
          (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > v_today) OR
          (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > v_today) OR
          (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > v_today)
        )
    ),
    COUNT(*) FILTER (
      WHERE (
        (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today) OR
        (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > v_today) OR
        (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > v_today) OR
        (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > v_today) OR
        (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > v_today) OR
        (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > v_today)
      )
    )
  INTO v_ativas, v_aguardando
  FROM product_variants pv
  WHERE pv.is_active = true;

  v_pct_ativas := ROUND(100.0 * v_ativas / NULLIF(v_total_vars, 0), 1);

  RETURN jsonb_build_object(
    'dias_historico_real',   v_dias_hist,
    'data_inicio_historico', v_data_min,
    'aviso_historico',
      CASE WHEN v_dias_hist < 30
           THEN 'Histórico incompleto: ' || v_dias_hist::text || ' dias disponíveis (meta: 30)'
           ELSE 'OK'
      END,
    'repostos_hoje',        v_hoje,
    'repostos_7d',          v_7d,
    'repostos_15d',         v_15d,
    'repostos_30d',         v_30d,
    '7d_igual_15d_aviso',   (v_7d = v_15d AND v_dias_hist < 15),
    'top_supplier_nome',    v_top_supplier,
    'top_supplier_count',   v_top_count,
    'variacoes_ativas_zero_com_previsao',   v_ativas,
    'variacoes_aguardando_lote',            v_aguardando,
    'pct_variacoes_com_reposicao',          v_pct_ativas,
    'gerado_em',   now(),
    'versao',      'v4_stable_20260620'
  );
END;
$$;

-- ─── 4. ACL hardening ────────────────────────────────────────────────────────
REVOKE EXECUTE ON FUNCTION public.fn_get_recent_restocks(integer, date) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_get_recent_restocks(integer, date) FROM anon;
GRANT  EXECUTE ON FUNCTION public.fn_get_recent_restocks(integer, date) TO authenticated;

REVOKE EXECUTE ON FUNCTION public.fn_get_stock_notification_counts(date) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_get_stock_notification_counts(date) FROM anon;
GRANT  EXECUTE ON FUNCTION public.fn_get_stock_notification_counts(date) TO authenticated;

REVOKE EXECUTE ON FUNCTION public.fn_get_reposicao_metrics() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_get_reposicao_metrics() FROM anon;
GRANT  EXECUTE ON FUNCTION public.fn_get_reposicao_metrics() TO authenticated;

-- Reload PostgREST schema cache
NOTIFY pgrst, 'reload schema';

-- <<< END 20260620000000_fix_recent_restocks_and_metrics.sql <<<

-- >>> BEGIN 20260620000001_fix_c07_new_chain_violations.sql >>>
-- Migration: fix_c07_new_chain_violations_20260620
-- Purpose: Repair 2 new C07 chain violations (depth-2 canonical chains) discovered 2026-06-20.
--
-- Root cause: On 2026-06-19 ~11:45 UTC, a "claude" session set canonical_image_id on two rows
-- pointing to intermediate nodes. Later that same day (20:34 and 21:50 UTC), separate migrations
-- made those intermediate nodes into deps (linked to their true roots). This created depth-2
-- chains: orphan-dep → intermediate-dep → root.
--
-- Fix: Re-point each orphan-dep directly to its canonical root (skip the intermediate).
--
-- Chain 1 (hash 7c2c81a56e80b1dd...):
--   45c83c45 → d39af6e6 → 254dea34 (ROOT)
--   Fix: 45c83c45 → 254dea34
--
-- Chain 2 (hash 6c2644f5380d97c9...):
--   918192cc → c9d485ea → 2238f75c (ROOT)
--   Fix: 918192cc → 2238f75c

BEGIN;

-- Chain 1: re-point 45c83c45 directly to root 254dea34
UPDATE public.product_images
SET
  canonical_image_id = '254dea34-123d-45ca-9a93-1901c81bc4ef',
  last_modified_source = 'migration',
  updated_at = NOW()
WHERE id = '45c83c45-fbc5-45b2-bed2-0f8a7f32b48a'
  AND canonical_image_id = 'd39af6e6-2b2a-418b-a139-0acda20cb6af'
  AND is_shared = true;

-- Chain 2: re-point 918192cc directly to root 2238f75c
UPDATE public.product_images
SET
  canonical_image_id = '2238f75c-800f-4d18-a499-bddd253824fc',
  last_modified_source = 'migration',
  updated_at = NOW()
WHERE id = '918192cc-6714-452d-9886-f1eb5edc2988'
  AND canonical_image_id = 'c9d485ea-4d41-4873-8ce6-990d1e0f793b'
  AND is_shared = true;

-- Self-test: C07 must be 0 after repair
DO $$
DECLARE
  chain_count int;
  c07_status  text;
  c07_value   int;
BEGIN
  -- Count remaining chain violations directly
  SELECT COUNT(*) INTO chain_count
  FROM public.product_images pi
  JOIN public.product_images root ON root.id = pi.canonical_image_id
  WHERE pi.is_shared = true
    AND pi.canonical_image_id IS NOT NULL
    AND root.canonical_image_id IS NOT NULL;  -- root is itself a dep → chain

  IF chain_count <> 0 THEN
    RAISE EXCEPTION 'C07 still has % chain violation(s) after migration', chain_count;
  END IF;

  -- Verify via health check function
  SELECT status::text, value::int
  INTO c07_status, c07_value
  FROM fn_product_images_health_check()
  WHERE check_name = 'c07_canonical_chains_flat';

  IF c07_status <> 'OK' THEN
    RAISE EXCEPTION 'C07 health check still FAIL: value=%, expected OK', c07_value;
  END IF;

  RAISE NOTICE 'C07 repair verified: % chain violations remain (expected 0)', chain_count;
END;
$$;

COMMIT;

-- <<< END 20260620000001_fix_c07_new_chain_violations.sql <<<

-- >>> BEGIN 20260620000001_mockup_client_logo_rotation_cols.sql >>>
-- Adds missing top-level columns to generated_mockups and tightens storage security.
--
-- Bugs fixed:
--   BUG-CLIENT-ID  : client_id / client_name were never persisted at the row level —
--                    they lived only inside area_config JSONB, making CRM linkage
--                    and server-side filtering impossible.
--   BUG-MISSING-COLS: logo_rotation / logo_scale had no dedicated columns; reads fell
--                    back to area_config which breaks for rows inserted before that JSONB
--                    key existed.
--   BUG-STORAGE-SEC: mockup-assets bucket had no file-size or MIME-type enforcement.
--   BUG-MISSING-IDX : no index on client_id or approval_status — full scans on admin
--                    dashboards that filter by those columns.
--
-- All ALTER TABLE clauses are guarded with IF NOT EXISTS so the migration is idempotent.

DO $$
BEGIN
  -- client_id: stored as text (no FK) to avoid cascade issues when CRM clients are deleted.
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'generated_mockups' AND column_name = 'client_id'
  ) THEN
    ALTER TABLE public.generated_mockups ADD COLUMN client_id TEXT;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'generated_mockups' AND column_name = 'client_name'
  ) THEN
    ALTER TABLE public.generated_mockups ADD COLUMN client_name TEXT;
  END IF;

  -- logo_rotation in degrees (−360 … 360). NUMERIC to allow sub-degree precision.
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'generated_mockups' AND column_name = 'logo_rotation'
  ) THEN
    ALTER TABLE public.generated_mockups ADD COLUMN logo_rotation NUMERIC DEFAULT 0;
  END IF;

  -- logo_scale as percentage (0 … 200).
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'generated_mockups' AND column_name = 'logo_scale'
  ) THEN
    ALTER TABLE public.generated_mockups ADD COLUMN logo_scale NUMERIC DEFAULT 100;
  END IF;
END $$;

-- Backfill client_name from area_config JSONB for existing rows that already have it.
-- Runs only where client_name is still NULL so the UPDATE is safe to re-run.
UPDATE public.generated_mockups
SET client_name = (area_config ->> 'clientName')
WHERE client_name IS NULL
  AND area_config ? 'clientName'
  AND (area_config ->> 'clientName') IS NOT NULL
  AND (area_config ->> 'clientName') <> '';

-- Backfill logo_rotation / logo_scale from area_config for older rows.
-- NOTE: `ADD COLUMN ... DEFAULT <const>` above already filled every existing row with
-- 0/100, so these columns are never NULL. A `WHERE logo_rotation IS NULL` clause would
-- therefore match nothing and silently leave older rows clobbered at the default while
-- their real values still sit in area_config. Backfill wherever the JSONB carries the
-- authoritative value instead, falling back to the current (default) column value.
UPDATE public.generated_mockups
SET
  logo_rotation = COALESCE((area_config ->> 'logoRotation')::numeric, logo_rotation),
  logo_scale    = COALESCE((area_config ->> 'logoScale')::numeric, logo_scale)
WHERE area_config IS NOT NULL
  AND (area_config ? 'logoRotation' OR area_config ? 'logoScale');

-- Index on client_id speeds up admin queries like "all mockups for client X".
CREATE INDEX IF NOT EXISTS idx_generated_mockups_client_id
  ON public.generated_mockups (client_id)
  WHERE client_id IS NOT NULL;

-- Index on approval_status for approval-workflow dashboard queries.
CREATE INDEX IF NOT EXISTS idx_generated_mockups_approval_status
  ON public.generated_mockups (approval_status)
  WHERE approval_status IS NOT NULL;

-- Index on product_id for product-level mockup history views.
CREATE INDEX IF NOT EXISTS idx_generated_mockups_product_id
  ON public.generated_mockups (product_id)
  WHERE product_id IS NOT NULL;

-- Storage bucket: enforce 10 MB limit and restrict to image MIME types.
-- Prevents malicious actors from uploading arbitrary file types (e.g. scripts, executables)
-- and prevents accidental storage-cost blowouts from huge uploads.
UPDATE storage.buckets
SET
  file_size_limit   = 10485760,   -- 10 MB in bytes
  allowed_mime_types = ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/gif']
WHERE id = 'mockup-assets';

-- <<< END 20260620000001_mockup_client_logo_rotation_cols.sql <<<

-- >>> BEGIN 20260620110923_security_advisors_remediation_rls_initplan.sql >>>
-- ============================================================
-- MIGRAÇÃO CORRETIVA: security_advisors_remediation_rls_initplan
-- DATA:   2026-06-20
-- ORIGEM: Auditoria exaustiva (200 commits) — análise dos advisors
--         Supabase do projeto SSOT canônico doufsxqlfjyuvxuezpln
--         (ver CLAUDE.md REGRA #1).
--
-- Esta migration espelha EXATAMENTE o que já foi aplicado em produção
-- via apply_migration (schema_migrations version 20260620110923). É
-- IDEMPOTENTE — um replay limpo (branch novo / DR rebuild) reaplica sem
-- efeito colateral.
--
-- ESCOPO (apenas correções SEGURAS e behavior-preserving):
--
--   1. public.category_ancestors  [ERROR 0013 rls_disabled_in_public]
--      Tabela VIVA do catálogo (closure de categorias, ~1k linhas,
--      repopulada pelo cron 'refresh-category-ancestors' via TRUNCATE+INSERT
--      rodando como owner/postgres). Estava com RLS DESABILITADO e GRANTs
--      de INSERT/UPDATE/DELETE para o papel `anon` → qualquer visitante
--      não autenticado podia corromper a árvore de categorias pela Data API.
--      O frontend NUNCA lê esta tabela diretamente (apenas via funções/
--      views SECURITY DEFINER, que rodam como owner e ignoram RLS).
--      Correção: ENABLE RLS + policy de SELECT público (taxonomia é
--      pública e inofensiva) + REVOKE de escrita para anon/authenticated.
--
--   2. Tabelas de backup esquecidas em public.*  [ERROR 0013]
--      _backup_stock_daily_summary_20260618, _bkp_kit_dims_20260619,
--      _bkp_orphan_active_variants_20260619 — snapshots datados que
--      vazaram para o schema exposto. RLS desabilitado; dois deles com
--      DML anônimo aberto. Nada na aplicação os lê. Correção: ENABLE RLS
--      (sem policy = invisíveis na Data API) + REVOKE ALL anon/authenticated.
--      OBS: candidatos a DROP em manutenção futura.
--
--   3. auth_rls_initplan  [PERF 0003] — product_views, quote_history
--      Policies user-facing reavaliavam auth.uid() por linha. Reescrita
--      para (SELECT auth.uid()) — mesmo resultado, avaliado uma vez.
--      100% behavior-preserving.
--
-- NÃO incluído de propósito (ver docs/AUDITORIA_200_COMMITS_2026-06-20.md):
--   • 78 security_definer_view (ERROR 0010): são as views *_public do
--     Medallion (Gold), expostas ao anon por DESIGN. Trocar para
--     security_invoker quebraria o catálogo público.
--   • 168 unused_index / 131 unindexed_foreign_keys: quase todos falso-
--     positivo. Tabelas-alvo minúsculas (2–15 linhas → seqscan é ótimo) ou
--     já cobertas por índices parciais/compostos (product_images já tem
--     índice em product_id, variant_id, color_id, image_type_id,
--     canonical_image_id). Criar índices novos só adicionaria write-
--     amplification numa tabela quente de 146 MB sem ganho de leitura.
--   • 53 function_search_path_mutable / 264+46 secdef RPC executáveis /
--     exposição GraphQL: hardening em lote, requer revisão por-objeto.
-- ============================================================

-- 1) category_ancestors — fechar DML anônimo
ALTER TABLE public.category_ancestors ENABLE ROW LEVEL SECURITY;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.category_ancestors FROM anon, authenticated;
DROP POLICY IF EXISTS category_ancestors_public_read ON public.category_ancestors;
CREATE POLICY category_ancestors_public_read
  ON public.category_ancestors FOR SELECT TO anon, authenticated USING (true);

-- 2) Tabelas de backup esquecidas em public.* — remover da Data API
ALTER TABLE public._backup_stock_daily_summary_20260618   ENABLE ROW LEVEL SECURITY;
ALTER TABLE public._bkp_kit_dims_20260619                 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public._bkp_orphan_active_variants_20260619   ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public._backup_stock_daily_summary_20260618 FROM anon, authenticated;
REVOKE ALL ON public._bkp_kit_dims_20260619               FROM anon, authenticated;
REVOKE ALL ON public._bkp_orphan_active_variants_20260619 FROM anon, authenticated;

-- 3) auth_rls_initplan — product_views (envolver auth.uid())
ALTER POLICY "Users can read own views" ON public.product_views
  USING (seller_id = (SELECT auth.uid()));
ALTER POLICY "Admins can read all views" ON public.product_views
  USING (has_role((SELECT auth.uid()), 'admin'::app_role));

-- 3) auth_rls_initplan — quote_history (envolver auth.uid())
ALTER POLICY "Sellers and coord view quote_history" ON public.quote_history
  USING (
    is_coord_or_above((SELECT auth.uid()))
    OR EXISTS (
      SELECT 1 FROM public.quotes q
      WHERE q.id = quote_history.quote_id
        AND (q.seller_id = (SELECT auth.uid())
             OR q.created_by = (SELECT auth.uid())
             OR q.assigned_to = (SELECT auth.uid()))
    )
  );
ALTER POLICY "Sellers and coord create quote_history" ON public.quote_history
  WITH CHECK (
    user_id = (SELECT auth.uid())
    AND (
      is_coord_or_above((SELECT auth.uid()))
      OR EXISTS (
        SELECT 1 FROM public.quotes q
        WHERE q.id = quote_history.quote_id
          AND (q.seller_id = (SELECT auth.uid())
               OR q.created_by = (SELECT auth.uid())
               OR q.assigned_to = (SELECT auth.uid()))
      )
    )
  );

-- <<< END 20260620110923_security_advisors_remediation_rls_initplan.sql <<<

-- >>> BEGIN 20260620120000_fix_create_update_quote_transactional_contact_id_clearable.sql >>>
-- Migration: fix_create_update_quote_transactional_contact_id_clearable
-- Data: 2026-06-20
-- Supersedes: 20260619110000 (applied only fn_create_quote_v3 — wrong function for BUG-D)
--
-- DESCOBERTA CRÍTICA:
--   quoteService.createQuote() chama create_quote_transactional(_quote, _items)
--   quoteService.updateQuote() chama update_quote_transactional(_quote_id, _quote_patch, _items)
--   A migration 20260619110000 corrigiu fn_create_quote_v3 (não usada pelo frontend)
--   e update_quote_transactional — mas a migration nunca foi aplicada em produção
--   devido a gap de timestamp (ficou atrás de migrations já aplicadas).
--
-- BUGS CORRIGIDOS NESTA MIGRATION:
--
-- BUG-D (CRÍTICO — create_quote_transactional):
--   contact_id estava completamente ausente do INSERT de quotes.
--   buildInsertPayload envia contact_id mas a coluna nunca era gravada.
--   → Toda criação de orçamento perdia silenciosamente a associação CRM.
--
-- BUG-A (CRÍTICO — update_quote_transactional):
--   contact_id estava completamente ausente do UPDATE de quotes.
--   buildUpdatePayload envia contact_id mas a coluna nunca era atualizada.
--   → Toda edição de orçamento descartava silenciosamente a associação CRM.
--
-- BUG-C (ALTO — update_quote_transactional):
--   notes, internal_notes e valid_until usavam COALESCE(_patch->>'field', existing).
--   buildUpdatePayload envia null para campos esvaziados; COALESCE(null, existing)
--   preserva o valor antigo — impossível limpar esses campos uma vez preenchidos.
--   Fix: CASE WHEN _quote_patch ? 'field' THEN value ELSE existing END.
--   O operador ? verifica presença da chave no JSONB (não o valor).

-- ════════════════════════════════════════════════════════════════════════════════
-- 1. Corrige create_quote_transactional: adiciona contact_id no INSERT
-- ════════════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.create_quote_transactional(_quote jsonb, _items jsonb)
RETURNS quotes
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  _new_quote    public.quotes;
  _new_quote_id uuid;
  _item         jsonb;
  _pers         jsonb;
  _new_item_id  uuid;
  _actor_id     uuid;
BEGIN
  -- ── 1. Cria o orçamento (quote_number preenchido pelo trigger generate_quote_number) ──
  INSERT INTO public.quotes (
    quote_number, client_id, contact_id, client_name, client_email, client_phone, client_company,
    seller_id, organization_id, status,
    subtotal, discount_percent, discount_amount, total, negotiation_markup_percent,
    payment_method, payment_terms, delivery_time, shipping_type, shipping_cost,
    notes, internal_notes, valid_until
  )
  VALUES (
    coalesce(_quote->>'quote_number', ''),
    nullif(_quote->>'client_id', '')::uuid,
    nullif(_quote->>'contact_id', '')::uuid,
    coalesce(_quote->>'client_name', ''),
    _quote->>'client_email',
    _quote->>'client_phone',
    _quote->>'client_company',
    nullif(_quote->>'seller_id', '')::uuid,
    nullif(_quote->>'organization_id', '')::uuid,
    coalesce(_quote->>'status', 'draft'),
    coalesce((_quote->>'subtotal')::numeric, 0),
    coalesce((_quote->>'discount_percent')::numeric, 0),
    coalesce((_quote->>'discount_amount')::numeric, 0),
    coalesce((_quote->>'total')::numeric, 0),
    coalesce((_quote->>'negotiation_markup_percent')::numeric, 0),
    _quote->>'payment_method',
    _quote->>'payment_terms',
    _quote->>'delivery_time',
    _quote->>'shipping_type',
    coalesce((_quote->>'shipping_cost')::numeric, 0),
    _quote->>'notes',
    _quote->>'internal_notes',
    nullif(_quote->>'valid_until', '')::date
  )
  RETURNING * INTO _new_quote;

  _new_quote_id := _new_quote.id;

  -- ── 2. Insere itens ─────────────────────────────────────────────────────────
  FOR _item IN SELECT value FROM jsonb_array_elements(coalesce(_items, '[]'::jsonb)) LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    VALUES (
      _new_quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    RETURNING id INTO _new_item_id;

    -- ── 3. Insere personalizações do item ──────────────────────────────────────
    FOR _pers IN SELECT value FROM jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      VALUES (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    END LOOP;
  END LOOP;

  -- ── 4. Relê a linha final (quote_number + totais recalculados pelos triggers) ──
  SELECT * INTO _new_quote FROM public.quotes WHERE id = _new_quote_id;

  -- ── 5. Audit trail ────────────────────────────────────────────────────────────
  _actor_id := coalesce(auth.uid(), nullif(_quote->>'seller_id', '')::uuid);
  IF _actor_id IS NOT NULL THEN
    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      _new_quote_id,
      _actor_id,
      'created',
      format('Orçamento %s criado com %s item(s) via RPC',
             _new_quote.quote_number,
             (SELECT count(*) FROM public.quote_items WHERE quote_id = _new_quote_id)),
      jsonb_build_object(
        'status',    _new_quote.status,
        'subtotal',  _new_quote.subtotal,
        'total',     _new_quote.total,
        'markup',    _new_quote.negotiation_markup_percent,
        'n_items',   (SELECT count(*) FROM public.quote_items WHERE quote_id = _new_quote_id)
      )
    );
  END IF;

  RETURN _new_quote;
END;
$function$;

-- ════════════════════════════════════════════════════════════════════════════════
-- 2. Corrige update_quote_transactional: adiciona contact_id + fix clearable fields
-- ════════════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.update_quote_transactional(
  _quote_id        uuid,
  _quote_patch     jsonb,
  _items           jsonb,
  _expected_version integer DEFAULT NULL::integer
)
RETURNS quotes
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  _updated_quote   public.quotes;
  _current_version integer;
  _prev_status     text;
  _prev_total      numeric;
  _item            jsonb;
  _pers            jsonb;
  _new_item_id     uuid;
  _actor_id        uuid;
  _action          text;
  _desc            text;
BEGIN
  -- ── 0. Captura estado anterior (para diff do audit trail e validação de versão) ──
  SELECT version, status, total
  INTO _current_version, _prev_status, _prev_total
  FROM public.quotes WHERE id = _quote_id;

  -- ── Optimistic locking ────────────────────────────────────────────────────────
  IF _expected_version IS NOT NULL THEN
    IF _current_version IS NULL THEN
      RAISE EXCEPTION 'Orçamento não encontrado: %', _quote_id
        USING errcode = 'no_data_found';
    END IF;
    IF _current_version <> _expected_version THEN
      RAISE EXCEPTION
        'Conflito de versão: orçamento foi modificado por outro usuário (versão atual: %, versão esperada: %). Recarregue e tente novamente.',
        _current_version, _expected_version
        USING errcode = '40001';
    END IF;
  END IF;

  -- ── 1. Atualiza o orçamento ─────────────────────────────────────────────────
  UPDATE public.quotes
  SET
    client_id                  = coalesce(nullif(_quote_patch->>'client_id', ''), client_id::text)::uuid,
    -- BUG-A FIX: contact_id com ? para permitir limpeza (CASE em vez de COALESCE)
    contact_id                 = CASE WHEN _quote_patch ? 'contact_id'
                                      THEN nullif(_quote_patch->>'contact_id', '')::uuid
                                      ELSE contact_id END,
    client_name                = coalesce(nullif(_quote_patch->>'client_name', ''), client_name),
    client_email               = coalesce(_quote_patch->>'client_email',     client_email),
    client_phone               = coalesce(_quote_patch->>'client_phone',     client_phone),
    client_company             = coalesce(_quote_patch->>'client_company',   client_company),
    status                     = coalesce(_quote_patch->>'status',           status),
    shipping_type              = coalesce(_quote_patch->>'shipping_type',    shipping_type),
    shipping_cost              = coalesce((_quote_patch->>'shipping_cost')::numeric,            shipping_cost),
    payment_method             = coalesce(_quote_patch->>'payment_method',   payment_method),
    payment_terms              = coalesce(_quote_patch->>'payment_terms',    payment_terms),
    delivery_time              = coalesce(_quote_patch->>'delivery_time',    delivery_time),
    -- BUG-C FIX: campos anuláveis usam ? para detectar presença da chave no JSONB
    notes                      = CASE WHEN _quote_patch ? 'notes'
                                      THEN _quote_patch->>'notes'
                                      ELSE notes END,
    internal_notes             = CASE WHEN _quote_patch ? 'internal_notes'
                                      THEN _quote_patch->>'internal_notes'
                                      ELSE internal_notes END,
    discount_percent           = coalesce((_quote_patch->>'discount_percent')::numeric,         discount_percent),
    discount_amount            = coalesce((_quote_patch->>'discount_amount')::numeric,          discount_amount),
    subtotal                   = coalesce((_quote_patch->>'subtotal')::numeric,                 subtotal),
    total                      = coalesce((_quote_patch->>'total')::numeric,                    total),
    negotiation_markup_percent = coalesce((_quote_patch->>'negotiation_markup_percent')::numeric, negotiation_markup_percent),
    -- BUG-C FIX: valid_until pode ser limpo para NULL via ? operator
    valid_until                = CASE WHEN _quote_patch ? 'valid_until'
                                      THEN nullif(_quote_patch->>'valid_until', '')::date
                                      ELSE valid_until END,
    updated_at                 = now()
  WHERE id = _quote_id
  RETURNING * INTO _updated_quote;

  IF _updated_quote IS NULL THEN
    RAISE EXCEPTION 'Orçamento não encontrado: %', _quote_id
      USING errcode = 'no_data_found';
  END IF;

  -- ── 2. Remove itens/personalizações existentes ───────────────────────────────
  DELETE FROM public.quote_item_personalizations
  WHERE quote_item_id IN (
    SELECT id FROM public.quote_items WHERE quote_id = _quote_id
  );
  DELETE FROM public.quote_items WHERE quote_id = _quote_id;

  -- ── 3. Reinsere itens ─────────────────────────────────────────────────────────
  FOR _item IN SELECT value FROM jsonb_array_elements(coalesce(_items, '[]'::jsonb)) LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    VALUES (
      _quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    RETURNING id INTO _new_item_id;

    -- ── 4. Reinsere personalizações ───────────────────────────────────────────
    FOR _pers IN SELECT value FROM jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      VALUES (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    END LOOP;
  END LOOP;

  -- ── 5. Audit trail ────────────────────────────────────────────────────────────
  _actor_id := coalesce(auth.uid(), _updated_quote.seller_id);
  IF _actor_id IS NOT NULL THEN
    IF _prev_status IS DISTINCT FROM _updated_quote.status THEN
      _action := 'status_changed';
      _desc   := format('Status alterado de "%s" para "%s" no %s',
                        _prev_status, _updated_quote.status, _updated_quote.quote_number);
    ELSE
      _action := 'updated';
      _desc   := format('Orçamento %s editado (total: R$ %s)',
                        _updated_quote.quote_number,
                        _updated_quote.total);
    END IF;

    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      _quote_id,
      _actor_id,
      _action,
      _desc,
      jsonb_build_object(
        'prev_status',          _prev_status,
        'new_status',           _updated_quote.status,
        'prev_total',           _prev_total,
        'new_total',            _updated_quote.total,
        'markup',               _updated_quote.negotiation_markup_percent,
        'n_items',              (SELECT count(*) FROM public.quote_items WHERE quote_id = _quote_id),
        'optimistic_lock_used', (_expected_version IS NOT NULL)
      )
    );
  END IF;

  RETURN _updated_quote;
END;
$function$;

-- <<< END 20260620120000_fix_create_update_quote_transactional_contact_id_clearable.sql <<<

-- >>> BEGIN 20260620140000_fix_rpc_add_client_cnpj.sql >>>
-- Migration: fix_rpc_add_client_cnpj
-- Date: 2026-06-20
--
-- GAP: create_quote_transactional (fixed in 20260620120000) omitted client_cnpj
-- from the INSERT column list. buildInsertPayload sends client_cnpj but the RPC
-- silently ignores it — CNPJ data lost on every quote creation.
-- Also: update_quote_transactional never updated client_cnpj even when the patch
-- includes it.
--
-- This migration:
--   1. Adds client_cnpj to the INSERT in create_quote_transactional
--   2. Adds client_cnpj to the UPDATE SET in update_quote_transactional

-- ════════════════════════════════════════════════════════════════════════════════
-- 1. create_quote_transactional — adds client_cnpj to INSERT
-- ════════════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.create_quote_transactional(_quote jsonb, _items jsonb)
RETURNS quotes
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  _new_quote    public.quotes;
  _new_quote_id uuid;
  _item         jsonb;
  _pers         jsonb;
  _new_item_id  uuid;
  _actor_id     uuid;
BEGIN
  INSERT INTO public.quotes (
    quote_number, client_id, contact_id,
    client_name, client_email, client_phone, client_company, client_cnpj,
    seller_id, organization_id, status,
    subtotal, discount_percent, discount_amount, total, negotiation_markup_percent,
    payment_method, payment_terms, delivery_time, shipping_type, shipping_cost,
    notes, internal_notes, valid_until
  )
  VALUES (
    coalesce(_quote->>'quote_number', ''),
    nullif(_quote->>'client_id', '')::uuid,
    nullif(_quote->>'contact_id', '')::uuid,
    coalesce(_quote->>'client_name', ''),
    _quote->>'client_email',
    _quote->>'client_phone',
    _quote->>'client_company',
    nullif(_quote->>'client_cnpj', ''),
    nullif(_quote->>'seller_id', '')::uuid,
    nullif(_quote->>'organization_id', '')::uuid,
    coalesce(_quote->>'status', 'draft'),
    coalesce((_quote->>'subtotal')::numeric, 0),
    coalesce((_quote->>'discount_percent')::numeric, 0),
    coalesce((_quote->>'discount_amount')::numeric, 0),
    coalesce((_quote->>'total')::numeric, 0),
    coalesce((_quote->>'negotiation_markup_percent')::numeric, 0),
    _quote->>'payment_method',
    _quote->>'payment_terms',
    _quote->>'delivery_time',
    _quote->>'shipping_type',
    coalesce((_quote->>'shipping_cost')::numeric, 0),
    _quote->>'notes',
    _quote->>'internal_notes',
    nullif(_quote->>'valid_until', '')::date
  )
  RETURNING * INTO _new_quote;

  _new_quote_id := _new_quote.id;

  FOR _item IN SELECT value FROM jsonb_array_elements(coalesce(_items, '[]'::jsonb)) LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    VALUES (
      _new_quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    RETURNING id INTO _new_item_id;

    FOR _pers IN SELECT value FROM jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      VALUES (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    END LOOP;
  END LOOP;

  SELECT * INTO _new_quote FROM public.quotes WHERE id = _new_quote_id;

  _actor_id := coalesce(auth.uid(), nullif(_quote->>'seller_id', '')::uuid);
  IF _actor_id IS NOT NULL THEN
    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      _new_quote_id,
      _actor_id,
      'created',
      format('Orçamento %s criado com %s item(s) via RPC',
             _new_quote.quote_number,
             (SELECT count(*) FROM public.quote_items WHERE quote_id = _new_quote_id)),
      jsonb_build_object(
        'status',  _new_quote.status,
        'subtotal',_new_quote.subtotal,
        'total',   _new_quote.total,
        'markup',  _new_quote.negotiation_markup_percent,
        'n_items', (SELECT count(*) FROM public.quote_items WHERE quote_id = _new_quote_id)
      )
    );
  END IF;

  RETURN _new_quote;
END;
$function$;

-- ════════════════════════════════════════════════════════════════════════════════
-- 2. update_quote_transactional — adds client_cnpj to UPDATE SET
-- ════════════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.update_quote_transactional(
  _quote_id        uuid,
  _quote_patch     jsonb,
  _items           jsonb,
  _expected_version integer DEFAULT NULL::integer
)
RETURNS quotes
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  _updated_quote   public.quotes;
  _current_version integer;
  _prev_status     text;
  _prev_total      numeric;
  _item            jsonb;
  _pers            jsonb;
  _new_item_id     uuid;
  _actor_id        uuid;
  _action          text;
  _desc            text;
BEGIN
  SELECT version, status, total
  INTO _current_version, _prev_status, _prev_total
  FROM public.quotes WHERE id = _quote_id;

  IF _expected_version IS NOT NULL THEN
    IF _current_version IS NULL THEN
      RAISE EXCEPTION 'Orçamento não encontrado: %', _quote_id
        USING errcode = 'no_data_found';
    END IF;
    IF _current_version <> _expected_version THEN
      RAISE EXCEPTION
        'Conflito de versão: orçamento foi modificado por outro usuário (versão atual: %, versão esperada: %). Recarregue e tente novamente.',
        _current_version, _expected_version
        USING errcode = '40001';
    END IF;
  END IF;

  UPDATE public.quotes
  SET
    client_id                  = coalesce(nullif(_quote_patch->>'client_id', ''), client_id::text)::uuid,
    contact_id                 = CASE WHEN _quote_patch ? 'contact_id'
                                      THEN nullif(_quote_patch->>'contact_id', '')::uuid
                                      ELSE contact_id END,
    client_name                = coalesce(nullif(_quote_patch->>'client_name', ''), client_name),
    client_email               = coalesce(_quote_patch->>'client_email',   client_email),
    client_phone               = coalesce(_quote_patch->>'client_phone',   client_phone),
    client_company             = coalesce(_quote_patch->>'client_company', client_company),
    client_cnpj                = coalesce(_quote_patch->>'client_cnpj',   client_cnpj),
    status                     = coalesce(_quote_patch->>'status',           status),
    shipping_type              = coalesce(_quote_patch->>'shipping_type',    shipping_type),
    shipping_cost              = coalesce((_quote_patch->>'shipping_cost')::numeric,              shipping_cost),
    payment_method             = coalesce(_quote_patch->>'payment_method',   payment_method),
    payment_terms              = coalesce(_quote_patch->>'payment_terms',    payment_terms),
    delivery_time              = coalesce(_quote_patch->>'delivery_time',    delivery_time),
    notes                      = CASE WHEN _quote_patch ? 'notes'
                                      THEN _quote_patch->>'notes'
                                      ELSE notes END,
    internal_notes             = CASE WHEN _quote_patch ? 'internal_notes'
                                      THEN _quote_patch->>'internal_notes'
                                      ELSE internal_notes END,
    discount_percent           = coalesce((_quote_patch->>'discount_percent')::numeric,           discount_percent),
    discount_amount            = coalesce((_quote_patch->>'discount_amount')::numeric,            discount_amount),
    subtotal                   = coalesce((_quote_patch->>'subtotal')::numeric,                   subtotal),
    total                      = coalesce((_quote_patch->>'total')::numeric,                      total),
    negotiation_markup_percent = coalesce((_quote_patch->>'negotiation_markup_percent')::numeric, negotiation_markup_percent),
    valid_until                = CASE WHEN _quote_patch ? 'valid_until'
                                      THEN nullif(_quote_patch->>'valid_until', '')::date
                                      ELSE valid_until END,
    updated_at                 = now()
  WHERE id = _quote_id
  RETURNING * INTO _updated_quote;

  IF _updated_quote IS NULL THEN
    RAISE EXCEPTION 'Orçamento não encontrado: %', _quote_id
      USING errcode = 'no_data_found';
  END IF;

  DELETE FROM public.quote_item_personalizations
  WHERE quote_item_id IN (
    SELECT id FROM public.quote_items WHERE quote_id = _quote_id
  );
  DELETE FROM public.quote_items WHERE quote_id = _quote_id;

  FOR _item IN SELECT value FROM jsonb_array_elements(coalesce(_items, '[]'::jsonb)) LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    VALUES (
      _quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    RETURNING id INTO _new_item_id;

    FOR _pers IN SELECT value FROM jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      VALUES (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    END LOOP;
  END LOOP;

  _actor_id := coalesce(auth.uid(), _updated_quote.seller_id);
  IF _actor_id IS NOT NULL THEN
    IF _prev_status IS DISTINCT FROM _updated_quote.status THEN
      _action := 'status_changed';
      _desc   := format('Status alterado de "%s" para "%s" no %s',
                        _prev_status, _updated_quote.status, _updated_quote.quote_number);
    ELSE
      _action := 'updated';
      _desc   := format('Orçamento %s editado (total: R$ %s)',
                        _updated_quote.quote_number,
                        _updated_quote.total);
    END IF;

    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      _quote_id,
      _actor_id,
      _action,
      _desc,
      jsonb_build_object(
        'prev_status',          _prev_status,
        'new_status',           _updated_quote.status,
        'prev_total',           _prev_total,
        'new_total',            _updated_quote.total,
        'markup',               _updated_quote.negotiation_markup_percent,
        'n_items',              (SELECT count(*) FROM public.quote_items WHERE quote_id = _quote_id),
        'optimistic_lock_used', (_expected_version IS NOT NULL)
      )
    );
  END IF;

  RETURN _updated_quote;
END;
$function$;

-- <<< END 20260620140000_fix_rpc_add_client_cnpj.sql <<<

-- >>> BEGIN 20260620150000_faxina_tier1_archive_orphan_tables.sql >>>
-- FAXINA DB — Tier 1: archive provably-dead tables (reversible: ALTER TABLE ... SET SCHEMA)
--
-- Applied to production (doufsxqlfjyuvxuezpln) on 2026-06-20 via Supabase MCP apply_migration.
-- This file mirrors the applied migration so repo == database.
--
-- Selection evidence (ALL must hold) per archived table:
--   * 0 inbound foreign keys, 0 dependent views, not a partition child
--   * 0 live rows, 0 writes over the full DB lifetime (pg_stat never reset), < 250 scans
--   * 0 references in any function body (pg_proc.prosrc), cron command, or RLS policy
--   * 0 references in the repo (src/ + supabase/functions/ + tests/ + e2e/) as string literals
--   * not a member of the supabase_realtime publication
-- Backups: dated operational snapshots that were living in the public schema.
--
-- The block is idempotent: it skips tables not present in public or already present in archive.
-- Rollback: scripts/faxina-rollback-tier1.sql (or: ALTER TABLE archive.<name> SET SCHEMA public).

create schema if not exists archive;

create table if not exists archive._cleanup_manifest (
  id            bigint generated always as identity primary key,
  moved_at      timestamptz not null default now(),
  object_type   text not null,
  object_name   text not null,
  from_schema   text not null default 'public',
  to_schema     text not null default 'archive',
  rows_at_move  bigint,
  reason        text,
  evidence      jsonb,
  session       text
);
comment on table archive._cleanup_manifest is
  'Audit log of the database faxina (cleanup). One row per object moved public->archive, with evidence, enabling precise one-command rollback.';

do $$
declare
  t text; v_rows bigint;
  -- IMPORTANT: notification_preferences, product_target_audiences and user_favorites are
  -- intentionally NOT in this list — they are NOT orphans:
  --   * notification_preferences  -> read by the live SECURITY DEFINER fn is_dnd_active()
  --     (20260620180000), called by the send-notification edge fn (runtime DND check).
  --   * product_target_audiences  -> indexed by 20260620150000_fix_catalog_critical_bugs.sql.
  --   * user_favorites            -> policy recreated by 20260620160000_fix_favorites_bugs_all.sql.
  -- Archiving them aborted clean replay (`supabase db reset`/preview/DR) at the CREATE
  -- INDEX/POLICY steps and broke DND at runtime. See 20260620190000_heal_faxina_live_tables.
  orphans text[] := array[
    'sm_worker_partitions','conversation_delivery_status',
    'magic_up_comments','push_subscriptions','user_allowed_ips','user_filter_presets',
    'magic_up_public_shares','product_search_logs','comparison_reactions','notification_templates',
    'order_item_personalizations','favorite_item_reactions','system_changelog','category_relationships',
    'seo_audit_log','supplier_field_priority','collection_item_reactions','attribute_equivalences',
    'search_queries'
  ];
  backups text[] := array[
    '_backup_stock_daily_summary_20260618','_bkp_kit_dims_20260619','_bkp_orphan_active_variants_20260619'
  ];
begin
  foreach t in array orphans loop
    if not exists (select 1 from information_schema.tables where table_schema='public' and table_name=t) then
      raise notice 'SKIP % (not in public)', t; continue; end if;
    if exists (select 1 from information_schema.tables where table_schema='archive' and table_name=t) then
      raise notice 'SKIP % (name collision in archive)', t; continue; end if;
    execute format('select count(*) from public.%I', t) into v_rows;
    execute format('alter table public.%I set schema archive', t);
    insert into archive._cleanup_manifest(object_type,object_name,rows_at_move,reason,evidence,session)
    values ('table',t,v_rows,'orphan: zero refs in db+repo, 0 rows, 0 writes lifetime',
            jsonb_build_object('phase','tier1_orphan'),'claude-faxina-2026-06-20');
    raise notice 'ARCHIVED public.% -> archive.% (% rows)', t,t,v_rows;
  end loop;

  foreach t in array backups loop
    if not exists (select 1 from information_schema.tables where table_schema='public' and table_name=t) then
      raise notice 'SKIP % (not in public)', t; continue; end if;
    if exists (select 1 from information_schema.tables where table_schema='archive' and table_name=t) then
      raise notice 'SKIP % (name collision in archive)', t; continue; end if;
    execute format('select count(*) from public.%I', t) into v_rows;
    execute format('alter table public.%I set schema archive', t);
    insert into archive._cleanup_manifest(object_type,object_name,rows_at_move,reason,evidence,session)
    values ('table',t,v_rows,'dated operational backup snapshot living in public',
            jsonb_build_object('phase','tier1_backup'),'claude-faxina-2026-06-20');
    raise notice 'ARCHIVED public.% -> archive.% (% rows)', t,t,v_rows;
  end loop;
end $$;

-- <<< END 20260620150000_faxina_tier1_archive_orphan_tables.sql <<<

-- >>> BEGIN 20260620150000_fix_catalog_critical_bugs.sql >>>
-- ============================================================
-- Catalog Critical Bug Fixes — 2026-06-20
-- ============================================================

-- FIX #1 (CRITICAL): fn_autolink_canonical_on_content_hash
-- Bug: fallback path could set canonical_image_id = NEW.id
-- (self-reference) when orphaned dependents point back to
-- the current row. Violates chk_pi_canonical_not_self,
-- causing ~30+ errors/min in postgres logs and 400 responses
-- from the hash-product-images edge function batch pipeline.
-- Fix: add AND pi2.canonical_image_id <> NEW.id guard in fallback.
CREATE OR REPLACE FUNCTION public.fn_autolink_canonical_on_content_hash()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_root_id               uuid;
  v_existing_canonical_hash text;
  v_old_group_root        uuid;
  v_elected_dep_root      uuid;
BEGIN
  IF NEW.content_hash IS NULL OR (OLD.content_hash IS NOT NULL AND OLD.content_hash = NEW.content_hash) THEN
    RETURN NEW;
  END IF;

  IF NEW.canonical_image_id IS NOT NULL THEN
    IF OLD.content_hash IS NOT NULL AND OLD.content_hash IS DISTINCT FROM NEW.content_hash THEN
      NEW.canonical_image_id := NULL;
      NEW.is_shared := false;
    ELSE
      SELECT content_hash INTO v_existing_canonical_hash
      FROM public.product_images
      WHERE id = NEW.canonical_image_id;
      IF v_existing_canonical_hash IS NOT DISTINCT FROM NEW.content_hash THEN
        RETURN NEW;
      END IF;
      NEW.canonical_image_id := NULL;
      NEW.is_shared := false;
    END IF;
  END IF;

  SELECT id INTO v_root_id
  FROM public.product_images
  WHERE content_hash = NEW.content_hash
    AND deleted_at IS NULL
    AND canonical_image_id IS NULL
    AND id <> NEW.id
    AND is_shared = false
  ORDER BY created_at ASC, id ASC
  LIMIT 1;

  IF v_root_id IS NOT NULL THEN
    NEW.canonical_image_id := v_root_id;
    NEW.is_shared := true;
  ELSE
    -- GUARD: exclude rows whose canonical_image_id = NEW.id to prevent
    -- self-reference (chk_pi_canonical_not_self violation).
    -- This edge case fires when this row was previously the root, its
    -- content_hash was cleared to NULL, and orphaned dependents still point to it.
    SELECT pi2.canonical_image_id INTO v_root_id
    FROM public.product_images pi2
    WHERE pi2.content_hash = NEW.content_hash
      AND pi2.deleted_at IS NULL
      AND pi2.canonical_image_id IS NOT NULL
      AND pi2.id <> NEW.id
      AND pi2.canonical_image_id <> NEW.id
    LIMIT 1;

    IF v_root_id IS NOT NULL THEN
      NEW.canonical_image_id := v_root_id;
      NEW.is_shared := true;
    END IF;
    -- If only member (or all dependents point back to NEW.id as orphans):
    -- remain as standalone root (canonical_image_id stays NULL)
  END IF;

  -- GAP-C5 / GAP-C5b: former deps need re-grouping when this row changes hash
  IF OLD.canonical_image_id IS NULL AND OLD.content_hash IS NOT NULL THEN
    SELECT id INTO v_old_group_root
    FROM public.product_images
    WHERE content_hash = OLD.content_hash
      AND deleted_at IS NULL
      AND canonical_image_id IS NULL
      AND id <> NEW.id
    ORDER BY created_at ASC, id ASC
    LIMIT 1;

    IF v_old_group_root IS NOT NULL THEN
      UPDATE public.product_images
      SET canonical_image_id = v_old_group_root,
          is_shared           = true,
          updated_at          = now()
      WHERE canonical_image_id = NEW.id
        AND id <> NEW.id
        AND deleted_at IS NULL;
    ELSE
      SELECT id INTO v_elected_dep_root
      FROM public.product_images
      WHERE canonical_image_id = NEW.id
        AND id <> NEW.id
        AND deleted_at IS NULL
      ORDER BY created_at ASC, id ASC
      LIMIT 1;

      IF v_elected_dep_root IS NOT NULL THEN
        UPDATE public.product_images
        SET canonical_image_id = NULL,
            is_shared           = false,
            updated_at          = now()
        WHERE id = v_elected_dep_root;

        UPDATE public.product_images
        SET canonical_image_id = v_elected_dep_root,
            is_shared           = true,
            updated_at          = now()
        WHERE canonical_image_id = NEW.id
          AND id <> NEW.id
          AND id <> v_elected_dep_root
          AND deleted_at IS NULL;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

-- FIX #2: Add ASIA_INGESTION_CRON_SECRET to vault secret allowlist
-- Bug: asia-ingestion edge function calls get_edge_function_secret
-- with 'ASIA_INGESTION_CRON_SECRET' which was absent from the allowlist,
-- causing "Nome de secret nao autorizado" errors and blocking ASIA catalog sync.
CREATE OR REPLACE FUNCTION public.get_edge_function_secret(_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'vault', 'public', 'pg_temp'
AS $function$
DECLARE
  _secret text;
BEGIN
  IF _name NOT IN (
    'WEBHOOK_DISPATCHER_SECRET',
    'CONNECTIONS_AUTO_TEST_SECRET',
    'CRON_SECRET',
    'HASH_PRODUCT_IMAGES_CRON_SECRET',
    'GENERATE_BLURHASHES_CRON_SECRET',
    'BACKFILL_DIM_CRON_SECRET',
    'ASIA_INGESTION_CRON_SECRET'
  ) THEN
    RAISE EXCEPTION 'Nome de secret nao autorizado: %', _name USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT decrypted_secret INTO _secret
  FROM vault.decrypted_secrets
  WHERE name = _name
  LIMIT 1;

  IF _secret IS NULL THEN
    RAISE EXCEPTION 'Secret % nao encontrado no vault', _name USING ERRCODE = 'no_data_found';
  END IF;

  RETURN _secret;
END;
$function$;

-- FIX #3: Make admin_audit_log.user_id nullable
-- Bug: service-role cron jobs and edge functions call audit functions
-- without a user context (auth.uid() returns NULL), violating NOT NULL
-- and dropping audit records. NULL now means system/service-role actor.
ALTER TABLE public.admin_audit_log
  ALTER COLUMN user_id DROP NOT NULL;

COMMENT ON COLUMN public.admin_audit_log.user_id IS
  'NULL = system/service-role actor (cron, edge function, trigger). Use source column to identify.';

-- FIX #4: Add RLS policy for supplier_customization_raw
-- Bug: RLS enabled but 0 policies blocked all authenticated access.
-- Service_role (used by cron/imports) bypasses RLS; admins need SELECT.
CREATE POLICY "Admins can read supplier customization raw"
  ON public.supplier_customization_raw
  FOR SELECT
  TO authenticated
  USING (
    public.has_role(auth.uid(), 'admin'::public.app_role)
    OR public.is_dev(auth.uid())
  );

-- FIX #5: Add missing FK indexes for catalog performance
-- These missing indexes cause full table scans during FK constraint
-- evaluation and in RLS policy checks (especially product_images.organization_id
-- which is checked on every product image fetch).

-- product_faqs.product_id → products
CREATE INDEX IF NOT EXISTS idx_product_faqs_product_id
  ON public.product_faqs (product_id);

-- product_faqs.category_id → categories
CREATE INDEX IF NOT EXISTS idx_product_faqs_category_id
  ON public.product_faqs (category_id);

-- product_group_members.product_group_id → product_groups
CREATE INDEX IF NOT EXISTS idx_product_group_members_group_id
  ON public.product_group_members (product_group_id);

-- product_images.organization_id → organizations (critical for RLS policy eval)
CREATE INDEX IF NOT EXISTS idx_product_images_organization_id
  ON public.product_images (organization_id);

-- product_kit_components.padronizacao_id → kit_component_padronizacao
CREATE INDEX IF NOT EXISTS idx_product_kit_components_padronizacao_id
  ON public.product_kit_components (padronizacao_id);

-- product_target_audiences.category_id → categories
CREATE INDEX IF NOT EXISTS idx_product_target_audiences_category_id
  ON public.product_target_audiences (category_id);

-- supplier_products_raw.import_batch_id → supplier_import_batches
CREATE INDEX IF NOT EXISTS idx_supplier_products_raw_import_batch_id
  ON public.supplier_products_raw (import_batch_id);

-- <<< END 20260620150000_fix_catalog_critical_bugs.sql <<<

-- >>> BEGIN 20260620150500_faxina_tier1b_revoke_archived_grants.sql >>>
-- FAXINA DB — Tier 1b: harden the archive/backup schemas (remove from API attack surface)
--
-- Applied to production (doufsxqlfjyuvxuezpln) on 2026-06-20 via Supabase MCP.
-- Rationale: ALTER TABLE ... SET SCHEMA archive does NOT revoke the anon/authenticated
-- privileges, so the security advisor still reports ~150 GraphQL/REST exposure findings
-- on the archive (128) and backup (23) schemas. Archived/backup objects must not be
-- reachable by the public API roles. service_role / postgres keep full access, so crons
-- and edge functions (which use the service role) are unaffected. Live app uses only
-- the public schema, so this cannot break runtime behaviour.
--
-- Idempotent: REVOKE is naturally repeatable. We also flip DEFAULT PRIVILEGES so future
-- objects archived into these schemas are not auto-granted to the API roles.

revoke all privileges on all tables    in schema archive from anon, authenticated;
revoke all privileges on all sequences in schema archive from anon, authenticated;
revoke all privileges on all functions in schema archive from anon, authenticated;
revoke usage on schema archive from anon, authenticated;

revoke all privileges on all tables    in schema backup from anon, authenticated;
revoke all privileges on all sequences in schema backup from anon, authenticated;
revoke usage on schema backup from anon, authenticated;

-- Prevent future re-exposure when more objects are archived.
alter default privileges in schema archive revoke all on tables from anon, authenticated;
alter default privileges in schema archive revoke all on sequences from anon, authenticated;
alter default privileges in schema backup  revoke all on tables from anon, authenticated;

-- <<< END 20260620150500_faxina_tier1b_revoke_archived_grants.sql <<<

-- >>> BEGIN 20260620160000_comparador_hardening.sql >>>
-- Comparador de Produtos — hardening de banco (constraints + RPC)
-- Data: 2026-06-20
--
-- Contexto: auditoria exaustiva do módulo "Comparador de Produtos". Três defeitos
-- de schema impediam funcionalidades de funcionarem corretamente. Todas as
-- alterações são aditivas e idempotentes; verificadas contra dados de produção
-- (user_preferences vazia, 1 slot "current", sem duplicatas).

-- 1) user_preferences.comparison_weights: o hook useComparisonWeights salva via
--    upsert(onConflict: 'user_id'), mas a tabela só tinha PRIMARY KEY (id) — sem
--    constraint UNIQUE em user_id, o ON CONFLICT não tinha alvo e TODO save de
--    pesos falhava ("no unique or exclusion constraint matching the ON CONFLICT").
--    O modelo é 1 linha por usuário; adiciona a UNIQUE que faltava.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.user_preferences'::regclass
      AND conname = 'user_preferences_user_id_key'
  ) THEN
    ALTER TABLE public.user_preferences
      ADD CONSTRAINT user_preferences_user_id_key UNIQUE (user_id);
  END IF;
END $$;

-- 2) user_comparisons: o sync cross-device grava um único slot "current" por
--    usuário (client_name='current', share_token IS NULL). Sem unicidade, uma
--    corrida entre abas/dispositivos criava slots duplicados, e o maybeSingle()
--    subsequente passava a lançar — travando o sync. Garante um slot por usuário.
CREATE UNIQUE INDEX IF NOT EXISTS uniq_user_current_comparison
  ON public.user_comparisons (user_id)
  WHERE client_name = 'current' AND share_token IS NULL;

-- 3) get_user_recent_comparisons: não deve expor o slot interno "current" (ele
--    vazava na lista "Recentes" como um item intitulado "current"). Filtra o slot.
CREATE OR REPLACE FUNCTION public.get_user_recent_comparisons(p_limit integer DEFAULT 5)
 RETURNS TABLE(
   id uuid,
   name text,
   client_name text,
   items jsonb,
   item_count integer,
   updated_at timestamp with time zone
 )
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT uc.id, uc.name, uc.client_name, uc.items,
         jsonb_array_length(uc.items) AS item_count, uc.updated_at
  FROM public.user_comparisons uc
  WHERE uc.user_id = auth.uid()
    AND NOT (uc.client_name = 'current' AND uc.share_token IS NULL)
  ORDER BY uc.updated_at DESC
  LIMIT p_limit;
$function$;

-- <<< END 20260620160000_comparador_hardening.sql <<<

-- >>> BEGIN 20260620160000_faxina_tier3_archive_dead_views.sql >>>
-- FAXINA DB — Tier 3: archive provably-dead VIEWS (reversible: ALTER VIEW ... SET SCHEMA)
--
-- Applied to production (doufsxqlfjyuvxuezpln) on 2026-06-20 via Supabase MCP. Mirrors DB state.
-- Archived 113 views (public views 171 -> 58).
--
-- Gates (recomputed at run time): 0 dependent views, 0 refs in function bodies, 0 refs in cron
-- commands, 0 refs in RLS policies, 0 refs anywhere in the repo (.ts/.tsx/.js/.mjs across
-- src/edge/tests/e2e/scripts), and never a *_public view (those are intentionally PostgREST-exposed).
-- Idempotent + manifest-logged. Rollback: scripts/faxina-rollback.sql.

do $$
declare
  r record; n int := 0;
  v_keep text[] := array[
    'v_products_public','v_suppliers_public','v_print_area_techniques_public','v_products_without_video',
    'v_products_without_videos','v_kit_component_complete','materials_complete','v_product_images_cdn',
    'v_product_videos_cdn','v_media_stats','v_products_with_tags','v_products_min_price','v_products_without_images',
    'v_products_missing_primary_image','v_kit_with_components','vw_sitemap_products','vw_sitemap_categories',
    'v_commemorative_dates_calendar','v_commemorative_dates_with_colors','v_variants_with_commemorative_dates',
    'vw_product_commemorative_dates','v_n8n_sync_summary','v_n8n_sync_errors','v_n8n_sync_success_recent',
    'v_variant_sale_prices_public','v_price_history_safe','v_products_with_techniques','v_products_with_stock',
    'v_product_print_areas_complete','v_product_attributes_formatted','v_kit_component_print_areas',
    'v_customization_price_summary','v_variant_pricing_complete','v_technique_stats','v_techniques_stricker_mapping',
    'vw_medallion_coverage','v_pipeline_progress','v_super_filtro_options','v_catalog_stats',
    'v_kill_switch_hits_summary','v_smoke_tests_latest_run','v_smoke_tests_trend','v_ai_function_routing_effective'
  ];
begin
  for r in
    with v as (
      select c.oid, c.relname from pg_class c join pg_namespace nsp on nsp.oid=c.relnamespace
      where nsp.nspname='public' and c.relkind='v'
    )
    select v.relname from v
    where (select count(distinct rw.ev_class) from pg_depend d join pg_rewrite rw on rw.oid=d.objid where d.refobjid=v.oid and rw.ev_class<>v.oid)=0
      and (select count(*) from pg_proc p join pg_namespace n2 on n2.oid=p.pronamespace where n2.nspname='public' and p.prosrc ~ ('\m'||v.relname||'\M'))=0
      and (select count(*) from cron.job j where j.command ~ ('\m'||v.relname||'\M'))=0
      and (select count(*) from pg_policies pp where (coalesce(pp.qual,'')||' '||coalesce(pp.with_check,'')) ~ ('\m'||v.relname||'\M'))=0
      and v.relname <> all(v_keep)
      and v.relname not like '%\_public'
    order by v.relname
  loop
    if exists (select 1 from information_schema.tables where table_schema='archive' and table_name=r.relname) then
      raise notice 'SKIP view % (collision in archive)', r.relname; continue; end if;
    execute format('alter view public.%I set schema archive', r.relname);
    insert into archive._cleanup_manifest(object_type,object_name,reason,evidence,session)
    values ('view', r.relname,
            'dead view: 0 dependents, 0 refs in functions/crons/policies/repo, not *_public',
            jsonb_build_object('phase','tier3_view'),'claude-faxina-2026-06-20');
    n := n + 1;
    raise notice 'ARCHIVED view public.% -> archive.%', r.relname, r.relname;
  end loop;
  raise notice 'Tier-3 archived % views', n;
end $$;

-- <<< END 20260620160000_faxina_tier3_archive_dead_views.sql <<<

-- >>> BEGIN 20260620160000_fix_favorites_bugs_all.sql >>>
-- ================================================================
-- fix_favorites_bugs_all
-- BUG-DB-1: restore_favorite_from_trash data loss on conflict
-- BUG-DB-2: purge_favorite_trash_old TOO_MANY_ROWS crash
-- BUG-DB-3: Missing expires_at / original_id indexes on trash
-- BUG-DB-4: user_favorites INSERT policy allows anon role
-- BUG-DB-5/6: move_favorites_to_trash double-inserts to trash
-- NEW:       get_favorite_list_counts RPC (efficient GROUP BY)
-- ================================================================

-- BUG-DB-1: restore_favorite_from_trash
-- Old bug: ON CONFLICT DO NOTHING left v_item_id = NULL
-- but DELETE FROM trash still executed → item lost from trash, not in favorite_items
CREATE OR REPLACE FUNCTION public.restore_favorite_from_trash(
  _trash_id uuid,
  _user_id  uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_trash        public.favorite_items_trash%ROWTYPE;
  v_list         public.favorite_lists%ROWTYPE;
  v_item_id      uuid;
  v_list_changed bool := false;
BEGIN
  -- Fetch trash row (must belong to requesting user)
  SELECT * INTO v_trash
    FROM public.favorite_items_trash
   WHERE id = _trash_id AND user_id = _user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  -- Resolve target list: prefer original, fall back to default
  SELECT * INTO v_list
    FROM public.favorite_lists
   WHERE id = v_trash.list_id
     AND user_id = _user_id
     AND is_archived = false;

  IF NOT FOUND THEN
    SELECT * INTO v_list
      FROM public.favorite_lists
     WHERE user_id = _user_id AND is_default = true
     LIMIT 1;
    v_list_changed := true;
  END IF;

  IF v_list.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no_target_list');
  END IF;

  -- Re-insert the item; skip if it already exists
  INSERT INTO public.favorite_items (
    list_id, user_id, product_id, variant_id, variant_info,
    note, price_at_save, position, added_at
  ) VALUES (
    v_list.id, _user_id, v_trash.product_id, v_trash.variant_id, v_trash.variant_info,
    v_trash.note, v_trash.price_at_save, v_trash.position, v_trash.added_at
  )
  ON CONFLICT (list_id, product_id, variant_id) DO NOTHING
  RETURNING id INTO v_item_id;

  -- BUG-DB-1 FIX: if the item already existed (conflict), fetch its id.
  -- Without this the old code deleted from trash even though nothing was restored.
  IF v_item_id IS NULL THEN
    SELECT id INTO v_item_id
      FROM public.favorite_items
     WHERE list_id    = v_list.id
       AND product_id = v_trash.product_id
       AND (
             (variant_id = v_trash.variant_id)
             OR (variant_id IS NULL AND v_trash.variant_id IS NULL)
           );
  END IF;

  -- Only remove from trash after confirming the item is in favorite_items
  DELETE FROM public.favorite_items_trash WHERE id = _trash_id;

  RETURN jsonb_build_object(
    'ok',                    true,
    'list_id',               v_list.id,
    'item_id',               v_item_id,
    'original_list_changed', v_list_changed
  );
END;
$$;

-- BUG-DB-2: purge_favorite_trash_old crashed with TOO_MANY_ROWS
-- when more than one expired row existed because of "RETURNING 1 INTO v_count"
CREATE OR REPLACE FUNCTION public.purge_favorite_trash_old()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_count integer := 0;
BEGIN
  DELETE FROM public.favorite_items_trash
  WHERE expires_at < now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

-- BUG-DB-3: Add indexes that were missing on favorite_items_trash
-- (a) Speeds up scheduled TTL cleanup queries
CREATE INDEX IF NOT EXISTS idx_fit_expires_at
  ON public.favorite_items_trash(expires_at)
  WHERE expires_at IS NOT NULL;

-- (b) Speeds up undo-toast lookup by original_id (used in removeItem onSuccess)
CREATE INDEX IF NOT EXISTS idx_fit_user_original
  ON public.favorite_items_trash(user_id, original_id)
  WHERE original_id IS NOT NULL;

-- BUG-DB-4: user_favorites INSERT policy was using {public} role (includes anon)
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_policies
     WHERE schemaname = 'public'
       AND tablename  = 'user_favorites'
       AND policyname = 'users_create_own_favorites'
  ) THEN
    EXECUTE 'DROP POLICY users_create_own_favorites ON public.user_favorites';
  END IF;
END
$$;
CREATE POLICY users_create_own_favorites
  ON public.user_favorites
  FOR INSERT
  TO authenticated
  WITH CHECK (user_id = auth.uid());

-- BUG-DB-5/6: Simplify move_favorites_to_trash - let trigger handle trash insertion
-- Old version did CTE delete (triggering soft-delete) + explicit insert = double entries
CREATE OR REPLACE FUNCTION public.move_favorites_to_trash(_item_ids uuid[])
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_count integer := 0;
BEGIN
  IF _item_ids IS NULL OR array_length(_item_ids, 1) IS NULL THEN
    RETURN 0;
  END IF;
  -- Deleting rows fires trg_fi_soft_delete → fn_favorite_items_soft_delete → trash
  DELETE FROM public.favorite_items
   WHERE id = ANY(_item_ids)
     AND user_id = auth.uid();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
EXCEPTION WHEN OTHERS THEN
  RETURN 0;
END;
$$;

-- NEW: efficient item count per list — replaces full-table-scan in JS (BUG-FE-4)
CREATE OR REPLACE FUNCTION public.get_favorite_list_counts(_user_id uuid)
RETURNS TABLE(list_id uuid, item_count bigint)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT fi.list_id, COUNT(*)::bigint AS item_count
    FROM public.favorite_items fi
   WHERE fi.user_id = _user_id
   GROUP BY fi.list_id;
$$;

GRANT EXECUTE ON FUNCTION public.get_favorite_list_counts(uuid) TO authenticated;

-- <<< END 20260620160000_fix_favorites_bugs_all.sql <<<

-- >>> BEGIN 20260620160000_fix_update_quote_client_cnpj_clearable.sql >>>
-- Migration: fix_update_quote_client_cnpj_clearable
-- Date: 2026-06-20
--
-- BUG: In update_quote_transactional (20260620140000), client_cnpj was added with:
--   client_cnpj = coalesce(_quote_patch->>'client_cnpj', client_cnpj)
--
-- buildUpdatePayload sends client_cnpj: quote.client_cnpj || null.
-- When the user changes to a client without a CNPJ, buildUpdatePayload sends
-- { ..., "client_cnpj": null }. COALESCE(null, old_cnpj) preserves the old value,
-- so the quote permanently retains the previous client's CNPJ.
--
-- Fix: use the same ? CASE WHEN pattern used for contact_id, notes, and valid_until.
-- The ? operator detects key presence in JSONB regardless of whether its value is null.

CREATE OR REPLACE FUNCTION public.update_quote_transactional(
  _quote_id        uuid,
  _quote_patch     jsonb,
  _items           jsonb,
  _expected_version integer DEFAULT NULL::integer
)
RETURNS quotes
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  _updated_quote   public.quotes;
  _current_version integer;
  _prev_status     text;
  _prev_total      numeric;
  _item            jsonb;
  _pers            jsonb;
  _new_item_id     uuid;
  _actor_id        uuid;
  _action          text;
  _desc            text;
BEGIN
  SELECT version, status, total
  INTO _current_version, _prev_status, _prev_total
  FROM public.quotes WHERE id = _quote_id;

  IF _expected_version IS NOT NULL THEN
    IF _current_version IS NULL THEN
      RAISE EXCEPTION 'Orçamento não encontrado: %', _quote_id
        USING errcode = 'no_data_found';
    END IF;
    IF _current_version <> _expected_version THEN
      RAISE EXCEPTION
        'Conflito de versão: orçamento foi modificado por outro usuário (versão atual: %, versão esperada: %). Recarregue e tente novamente.',
        _current_version, _expected_version
        USING errcode = '40001';
    END IF;
  END IF;

  UPDATE public.quotes
  SET
    client_id                  = coalesce(nullif(_quote_patch->>'client_id', ''), client_id::text)::uuid,
    contact_id                 = CASE WHEN _quote_patch ? 'contact_id'
                                      THEN nullif(_quote_patch->>'contact_id', '')::uuid
                                      ELSE contact_id END,
    client_name                = coalesce(nullif(_quote_patch->>'client_name', ''), client_name),
    client_email               = coalesce(_quote_patch->>'client_email',   client_email),
    client_phone               = coalesce(_quote_patch->>'client_phone',   client_phone),
    client_company             = coalesce(_quote_patch->>'client_company', client_company),
    -- BUG-FIX: COALESCE cannot clear client_cnpj when patch contains null.
    -- Use ? CASE WHEN so that {"client_cnpj": null} clears the field.
    client_cnpj                = CASE WHEN _quote_patch ? 'client_cnpj'
                                      THEN nullif(_quote_patch->>'client_cnpj', '')
                                      ELSE client_cnpj END,
    status                     = coalesce(_quote_patch->>'status',           status),
    shipping_type              = coalesce(_quote_patch->>'shipping_type',    shipping_type),
    shipping_cost              = coalesce((_quote_patch->>'shipping_cost')::numeric,              shipping_cost),
    payment_method             = coalesce(_quote_patch->>'payment_method',   payment_method),
    payment_terms              = coalesce(_quote_patch->>'payment_terms',    payment_terms),
    delivery_time              = coalesce(_quote_patch->>'delivery_time',    delivery_time),
    notes                      = CASE WHEN _quote_patch ? 'notes'
                                      THEN _quote_patch->>'notes'
                                      ELSE notes END,
    internal_notes             = CASE WHEN _quote_patch ? 'internal_notes'
                                      THEN _quote_patch->>'internal_notes'
                                      ELSE internal_notes END,
    discount_percent           = coalesce((_quote_patch->>'discount_percent')::numeric,           discount_percent),
    discount_amount            = coalesce((_quote_patch->>'discount_amount')::numeric,            discount_amount),
    subtotal                   = coalesce((_quote_patch->>'subtotal')::numeric,                   subtotal),
    total                      = coalesce((_quote_patch->>'total')::numeric,                      total),
    negotiation_markup_percent = coalesce((_quote_patch->>'negotiation_markup_percent')::numeric, negotiation_markup_percent),
    valid_until                = CASE WHEN _quote_patch ? 'valid_until'
                                      THEN nullif(_quote_patch->>'valid_until', '')::date
                                      ELSE valid_until END,
    updated_at                 = now()
  WHERE id = _quote_id
  RETURNING * INTO _updated_quote;

  IF _updated_quote IS NULL THEN
    RAISE EXCEPTION 'Orçamento não encontrado: %', _quote_id
      USING errcode = 'no_data_found';
  END IF;

  DELETE FROM public.quote_item_personalizations
  WHERE quote_item_id IN (
    SELECT id FROM public.quote_items WHERE quote_id = _quote_id
  );
  DELETE FROM public.quote_items WHERE quote_id = _quote_id;

  FOR _item IN SELECT value FROM jsonb_array_elements(coalesce(_items, '[]'::jsonb)) LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    VALUES (
      _quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    RETURNING id INTO _new_item_id;

    FOR _pers IN SELECT value FROM jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      VALUES (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    END LOOP;
  END LOOP;

  _actor_id := coalesce(auth.uid(), _updated_quote.seller_id);
  IF _actor_id IS NOT NULL THEN
    IF _prev_status IS DISTINCT FROM _updated_quote.status THEN
      _action := 'status_changed';
      _desc   := format('Status alterado de "%s" para "%s" no %s',
                        _prev_status, _updated_quote.status, _updated_quote.quote_number);
    ELSE
      _action := 'updated';
      _desc   := format('Orçamento %s editado (total: R$ %s)',
                        _updated_quote.quote_number,
                        _updated_quote.total);
    END IF;

    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      _quote_id,
      _actor_id,
      _action,
      _desc,
      jsonb_build_object(
        'prev_status',          _prev_status,
        'new_status',           _updated_quote.status,
        'prev_total',           _prev_total,
        'new_total',            _updated_quote.total,
        'markup',               _updated_quote.negotiation_markup_percent,
        'n_items',              (SELECT count(*) FROM public.quote_items WHERE quote_id = _quote_id),
        'optimistic_lock_used', (_expected_version IS NOT NULL)
      )
    );
  END IF;

  RETURN _updated_quote;
END;
$function$;

-- <<< END 20260620160000_fix_update_quote_client_cnpj_clearable.sql <<<

-- >>> BEGIN 20260620160500_faxina_tier3_archive_dead_functions.sql >>>
-- FAXINA DB — Tier 3: archive provably-dead FUNCTIONS (reversible: ALTER FUNCTION ... SET SCHEMA)
--
-- Applied to production (doufsxqlfjyuvxuezpln) on 2026-06-20 via Supabase MCP. Mirrors DB state.
-- Archived 11 functions (public functions 1170 -> 1159).
--
-- Narrow, high-confidence set only: explicitly __deprecated__-dated + debug/test/dryrun helpers.
-- Re-verifies at run time: 0 structural deps (pg_depend: triggers/policies/views/defaults),
-- 0 refs in other function bodies, 0 cron refs; repo-gated separately (0 .rpc()/string refs in code).
-- NOTE: ~570 further functions are DB-side-dead but are reachable via frontend .rpc(); they require
-- a per-batch repo .rpc() gate before archiving (see docs/FAXINA_DB_2026-06-20_TIER3.md). Not touched here.
-- Idempotent + manifest-logged. Rollback: scripts/faxina-rollback.sql.

do $$
declare
  r record; n int := 0;
  fn_names text[] := array[
    'fn_silver_to_gold__deprecated_20260606','fn_silver_batch_to_gold__deprecated_20260606',
    'debug_automations','debug_link_material','fn_test_dimension_parsers','fn_test_guc_visibility',
    'test_classify_batch','fn_dryrun_raw_v2','fn_dryrun_standardize_supplier',
    'fn_ingest_asia_hg_batch_debug','fn_ingest_asia_hg_debug_sample'
  ];
begin
  for r in
    select p.oid, p.proname, pg_get_function_identity_arguments(p.oid) as args
    from pg_proc p join pg_namespace nsp on nsp.oid=p.pronamespace
    where nsp.nspname='public' and p.proname = any(fn_names)
  loop
    if (select count(*) from pg_depend d where d.refobjid=r.oid and d.deptype in ('n','a') and d.classid <> 'pg_proc'::regclass) > 0 then
      raise notice 'SKIP fn % (structural deps)', r.proname; continue; end if;
    if (select count(*) from pg_proc p2 join pg_namespace n2 on n2.oid=p2.pronamespace where n2.nspname='public' and p2.oid<>r.oid and p2.prosrc ~ ('\m'||r.proname||'\M')) > 0 then
      raise notice 'SKIP fn % (fn-body ref)', r.proname; continue; end if;
    if (select count(*) from cron.job j where j.command ~ ('\m'||r.proname||'\M')) > 0 then
      raise notice 'SKIP fn % (cron ref)', r.proname; continue; end if;
    if exists (select 1 from pg_proc p3 join pg_namespace n3 on n3.oid=p3.pronamespace where n3.nspname='archive' and p3.proname=r.proname) then
      raise notice 'SKIP fn % (collision in archive)', r.proname; continue; end if;
    execute format('alter function public.%I(%s) set schema archive', r.proname, r.args);
    insert into archive._cleanup_manifest(object_type,object_name,reason,evidence,session)
    values ('function', r.proname||'('||r.args||')',
            'dead fn: deprecated/debug/test, 0 db refs (deps/fnbody/cron) + 0 repo refs',
            jsonb_build_object('phase','tier3_function'),'claude-faxina-2026-06-20');
    n := n + 1;
    raise notice 'ARCHIVED function public.%(%)', r.proname, r.args;
  end loop;
  raise notice 'Tier-3 archived % functions', n;
end $$;

-- <<< END 20260620160500_faxina_tier3_archive_dead_functions.sql <<<

-- >>> BEGIN 20260620170000_faxina_tier3c_archive_safe_utility_functions.sql >>>
-- FAXINA DB — Tier 3c: archive only the unambiguously-safe dead functions.
--
-- Applied to production (doufsxqlfjyuvxuezpln) on 2026-06-20 via Supabase MCP. Mirrors DB state.
-- Archived 17 functions (public functions 1159 -> 1142).
--
-- Method: combined STATIC analysis (no FK/trigger/policy/view/default deps, no cron refs, no other
-- function-body refs, non-dynamic/feature/versioned families) with 12 days of RUNTIME call data from
-- pg_stat_statements (0 real calls), then INDIVIDUALLY reviewed the survivors. Only pure stateless
-- converters/formatters, DETACHED duplicate updated_at trigger functions, and dev diagnostics were kept.
-- Each is re-gated at run time (skips on ANY dependency/trigger/caller). Reversible: scripts/faxina-rollback.sql.
--
-- NOTE: ~314 further functions are statically "dead" but could NOT be proven safe automatically because
-- (a) pg_stat_statements is at capacity (4985/5000) and evicts moderate-frequency calls, and
-- (b) the codebase uses dynamic dispatch (.rpc(var), classify_* registry, pipeline dynamic SQL).
-- See docs/FAXINA_DB_2026-06-20_TIER3C.md for the safe path to finish them.

do $$
declare r record; n int := 0;
  fns text[] := array[
    'cm_to_mm','mm_to_cm','g_to_kg','kg_to_g','l_to_ml','ml_to_l','m_to_cm',
    'fn_circumference_to_diameter','fn_hex_to_rgb','convert_string_to_unit',
    'fn_format_capacity_display','fn_format_dimensions_display',
    'tg_set_updated_at','trigger_set_updated_at','fn_cor_updated_at',
    'fn_index_usage_report','fn_assert_public_contract'
  ];
begin
  for r in
    select p.oid, p.proname, pg_get_function_identity_arguments(p.oid) as args
    from pg_proc p join pg_namespace nsp on nsp.oid=p.pronamespace
    where nsp.nspname='public' and p.proname = any(fns)
  loop
    if (select count(*) from pg_depend d where d.refobjid=r.oid and d.deptype in ('n','a') and d.classid <> 'pg_proc'::regclass) > 0 then
      raise notice 'SKIP % (structural deps)', r.proname; continue; end if;
    if (select count(*) from pg_trigger t where t.tgfoid=r.oid and not t.tgisinternal) > 0 then
      raise notice 'SKIP % (attached trigger)', r.proname; continue; end if;
    if (select count(*) from cron.job j where j.command ~ ('\m'||r.proname||'\M')) > 0 then
      raise notice 'SKIP % (cron ref)', r.proname; continue; end if;
    if (select count(*) from pg_proc p2 join pg_namespace n2 on n2.oid=p2.pronamespace where n2.nspname='public' and p2.oid<>r.oid and p2.prosrc ~ ('\m'||r.proname||'\M')) > 0 then
      raise notice 'SKIP % (fn-body ref)', r.proname; continue; end if;
    if exists (select 1 from pg_proc p3 join pg_namespace n3 on n3.oid=p3.pronamespace where n3.nspname='archive' and p3.proname=r.proname) then
      raise notice 'SKIP % (archive collision)', r.proname; continue; end if;
    execute format('alter function public.%I(%s) set schema archive', r.proname, r.args);
    insert into archive._cleanup_manifest(object_type,object_name,reason,evidence,session)
    values ('function', r.proname||'('||r.args||')',
            'Tier 3c: pure utility / detached trigger / diagnostic; static-dead + 0 calls in 12d pgss; individually reviewed',
            jsonb_build_object('phase','tier3c_function'),'claude-faxina-2026-06-20');
    n := n + 1;
    raise notice 'ARCHIVED %()', r.proname;
  end loop;
  raise notice 'Tier-3c archived % functions', n;
end $$;

