-- >>> BEGIN 20260620170000_fix_favorites_gaps_11_12.sql >>>
-- =============================================================================
-- GAP-11: Block addItem to archived list (DB trigger)
-- GAP-12: Atomic position assignment for createList (replace race-prone MAX+1)
-- =============================================================================

-- ---------------------------------------------------------------------------
-- GAP-11: Prevent inserting favorite_items into an archived list
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_favorite_items_no_archived_list()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _archived boolean;
BEGIN
  SELECT is_archived INTO _archived
  FROM favorite_lists
  WHERE id = NEW.list_id;

  IF _archived IS TRUE THEN
    RAISE EXCEPTION 'cannot_add_to_archived_list'
      USING HINT = 'The target favorite list is archived. Unarchive it first.',
            ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_fi_no_archived_list ON favorite_items;
CREATE TRIGGER trg_fi_no_archived_list
  BEFORE INSERT OR UPDATE OF list_id ON favorite_items
  FOR EACH ROW
  EXECUTE FUNCTION fn_favorite_items_no_archived_list();

-- ---------------------------------------------------------------------------
-- GAP-12: Atomic position assignment — use a sequence per list
--   Previous approach: JS sends MAX(position)+1 → race on concurrent inserts.
--   New approach: DB trigger assigns position atomically when position IS NULL.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_favorite_items_assign_position()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.position IS NULL THEN
    SELECT COALESCE(MAX(position), -1) + 1
      INTO NEW.position
      FROM favorite_items
     WHERE list_id = NEW.list_id;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_fi_assign_position ON favorite_items;
CREATE TRIGGER trg_fi_assign_position
  BEFORE INSERT ON favorite_items
  FOR EACH ROW
  EXECUTE FUNCTION fn_favorite_items_assign_position();

-- Revoke public execute so only service-role / postgres can call directly
REVOKE EXECUTE ON FUNCTION public.fn_favorite_items_no_archived_list() FROM anon, authenticated, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_favorite_items_assign_position() FROM anon, authenticated, PUBLIC;

-- <<< END 20260620170000_fix_favorites_gaps_11_12.sql <<<

-- >>> BEGIN 20260620170000_fix_update_quote_contact_fields_clearable.sql >>>
-- Migration: fix_update_quote_contact_fields_clearable
-- Date: 2026-06-20
--
-- BUG: In update_quote_transactional (20260620160000), client_email, client_phone
-- and client_company used COALESCE:
--   client_email = coalesce(_quote_patch->>'client_email', client_email)
--
-- buildUpdatePayload sends { client_email: null } when the user clears the field.
-- COALESCE(null, old_email) preserves the old value, making these fields
-- permanently sticky once set — impossible to clear without a direct DB UPDATE.
--
-- Fix: use the same CASE WHEN ? pattern used for contact_id, notes, valid_until
-- and client_cnpj. The ? operator checks key PRESENCE in JSONB regardless of
-- whether its value is null, so {"client_email": null} correctly clears the field.
--
-- Applies a full CREATE OR REPLACE of update_quote_transactional to carry forward
-- all fixes from 20260620160000 with only the three lines changed.

CREATE OR REPLACE FUNCTION public.update_quote_transactional(
  _quote_id        uuid,
  _quote_patch     jsonb,
  _items           jsonb,
  _expected_version integer DEFAULT NULL::integer
)
RETURNS quotes
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  _updated_quote   public.quotes;
  _current_version integer;
  _prev_status     text;
  _prev_total      numeric;
  _item            jsonb;
  _pers            jsonb;
  _new_item_id     uuid;
  _actor_id        uuid;
  _action          text;
  _desc            text;
BEGIN
  SELECT version, status, total
  INTO _current_version, _prev_status, _prev_total
  FROM public.quotes WHERE id = _quote_id;

  IF _expected_version IS NOT NULL THEN
    IF _current_version IS NULL THEN
      RAISE EXCEPTION 'Orçamento não encontrado: %', _quote_id
        USING errcode = 'no_data_found';
    END IF;
    IF _current_version <> _expected_version THEN
      RAISE EXCEPTION
        'Conflito de versão: orçamento foi modificado por outro usuário (versão atual: %, versão esperada: %). Recarregue e tente novamente.',
        _current_version, _expected_version
        USING errcode = '40001';
    END IF;
  END IF;

  UPDATE public.quotes
  SET
    client_id                  = coalesce(nullif(_quote_patch->>'client_id', ''), client_id::text)::uuid,
    contact_id                 = CASE WHEN _quote_patch ? 'contact_id'
                                      THEN nullif(_quote_patch->>'contact_id', '')::uuid
                                      ELSE contact_id END,
    client_name                = coalesce(nullif(_quote_patch->>'client_name', ''), client_name),
    -- BUG-FIX: COALESCE cannot clear these fields when patch contains null.
    -- Use ? CASE WHEN so that {"client_email": null} clears the field.
    client_email               = CASE WHEN _quote_patch ? 'client_email'
                                      THEN nullif(_quote_patch->>'client_email', '')
                                      ELSE client_email END,
    client_phone               = CASE WHEN _quote_patch ? 'client_phone'
                                      THEN nullif(_quote_patch->>'client_phone', '')
                                      ELSE client_phone END,
    client_company             = CASE WHEN _quote_patch ? 'client_company'
                                      THEN nullif(_quote_patch->>'client_company', '')
                                      ELSE client_company END,
    client_cnpj                = CASE WHEN _quote_patch ? 'client_cnpj'
                                      THEN nullif(_quote_patch->>'client_cnpj', '')
                                      ELSE client_cnpj END,
    status                     = coalesce(_quote_patch->>'status',           status),
    shipping_type              = coalesce(_quote_patch->>'shipping_type',    shipping_type),
    shipping_cost              = coalesce((_quote_patch->>'shipping_cost')::numeric,              shipping_cost),
    payment_method             = coalesce(_quote_patch->>'payment_method',   payment_method),
    payment_terms              = coalesce(_quote_patch->>'payment_terms',    payment_terms),
    delivery_time              = coalesce(_quote_patch->>'delivery_time',    delivery_time),
    notes                      = CASE WHEN _quote_patch ? 'notes'
                                      THEN _quote_patch->>'notes'
                                      ELSE notes END,
    internal_notes             = CASE WHEN _quote_patch ? 'internal_notes'
                                      THEN _quote_patch->>'internal_notes'
                                      ELSE internal_notes END,
    discount_percent           = coalesce((_quote_patch->>'discount_percent')::numeric,           discount_percent),
    discount_amount            = coalesce((_quote_patch->>'discount_amount')::numeric,            discount_amount),
    subtotal                   = coalesce((_quote_patch->>'subtotal')::numeric,                   subtotal),
    total                      = coalesce((_quote_patch->>'total')::numeric,                      total),
    negotiation_markup_percent = coalesce((_quote_patch->>'negotiation_markup_percent')::numeric, negotiation_markup_percent),
    valid_until                = CASE WHEN _quote_patch ? 'valid_until'
                                      THEN nullif(_quote_patch->>'valid_until', '')::date
                                      ELSE valid_until END,
    updated_at                 = now()
  WHERE id = _quote_id
  RETURNING * INTO _updated_quote;

  IF _updated_quote IS NULL THEN
    RAISE EXCEPTION 'Orçamento não encontrado: %', _quote_id
      USING errcode = 'no_data_found';
  END IF;

  DELETE FROM public.quote_item_personalizations
  WHERE quote_item_id IN (
    SELECT id FROM public.quote_items WHERE quote_id = _quote_id
  );
  DELETE FROM public.quote_items WHERE quote_id = _quote_id;

  FOR _item IN SELECT value FROM jsonb_array_elements(coalesce(_items, '[]'::jsonb)) LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    VALUES (
      _quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    RETURNING id INTO _new_item_id;

    FOR _pers IN SELECT value FROM jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      VALUES (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    END LOOP;
  END LOOP;

  _actor_id := coalesce(auth.uid(), _updated_quote.seller_id);
  IF _actor_id IS NOT NULL THEN
    IF _prev_status IS DISTINCT FROM _updated_quote.status THEN
      _action := 'status_changed';
      _desc   := format('Status alterado de "%s" para "%s" no %s',
                        _prev_status, _updated_quote.status, _updated_quote.quote_number);
    ELSE
      _action := 'updated';
      _desc   := format('Orçamento %s editado (total: R$ %s)',
                        _updated_quote.quote_number,
                        _updated_quote.total);
    END IF;

    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      _quote_id,
      _actor_id,
      _action,
      _desc,
      jsonb_build_object(
        'prev_status',          _prev_status,
        'new_status',           _updated_quote.status,
        'prev_total',           _prev_total,
        'new_total',            _updated_quote.total,
        'markup',               _updated_quote.negotiation_markup_percent,
        'n_items',              (SELECT count(*) FROM public.quote_items WHERE quote_id = _quote_id),
        'optimistic_lock_used', (_expected_version IS NOT NULL)
      )
    );
  END IF;

  RETURN _updated_quote;
END;
$function$;

-- <<< END 20260620170000_fix_update_quote_contact_fields_clearable.sql <<<

-- >>> BEGIN 20260620170500_faxina_harden_function_search_path.sql >>>
-- FAXINA DB — Security hardening: pin search_path on mutable-search_path functions.
--
-- Applied to production (doufsxqlfjyuvxuezpln) on 2026-06-20 via Supabase MCP. Mirrors DB state.
-- Pinned 47 functions -> clears the advisor "function_search_path_mutable" findings (49 -> 0 for the safe set).
--
-- Scope (conservative, behaviour-preserving): public functions (plpgsql/sql), SECURITY INVOKER, with NO
-- search_path set, whose bodies reference NO other schema (net/vault/cron/auth/storage/graphql/pgmq/realtime).
-- For these, pinning to 'public, extensions, pg_temp' cannot change name resolution. SECURITY DEFINER
-- functions already had search_path pinned and were intentionally left untouched.
-- Reversible: ALTER FUNCTION <f>(<args>) RESET search_path.

do $$
declare r record; n int := 0;
begin
  for r in
    select p.proname, pg_get_function_identity_arguments(p.oid) as args
    from pg_proc p
    join pg_namespace nsp on nsp.oid=p.pronamespace
    join pg_language  l  on l.oid=p.prolang
    where nsp.nspname='public' and p.prokind='f' and p.prosecdef = false
      and l.lanname in ('plpgsql','sql')
      and not exists (select 1 from unnest(coalesce(p.proconfig,'{}'::text[])) c where c like 'search_path=%')
      and p.prosrc !~* '(net\.|vault\.|cron\.|auth\.|storage\.|graphql|pgmq|realtime|supabase_)'
  loop
    execute format('alter function public.%I(%s) set search_path = public, extensions, pg_temp', r.proname, r.args);
    n := n + 1;
  end loop;
  raise notice 'Pinned search_path on % public-scoped SECURITY INVOKER functions', n;
end $$;

-- <<< END 20260620170500_faxina_harden_function_search_path.sql <<<

-- >>> BEGIN 20260620180000_fix_security_definer_search_path.sql >>>
-- Fix BUG-RLS-01: SECURITY DEFINER functions in migration 004 lack SET search_path = public.
-- Without this, a malicious schema earlier in search_path can intercept table/function lookups
-- executed with elevated privileges, creating a privilege-escalation vector.

CREATE OR REPLACE FUNCTION is_dnd_active(p_user_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_prefs RECORD;
  v_now   TIME;
  v_day   INT;
BEGIN
  SELECT * INTO v_prefs
  FROM notification_preferences
  WHERE user_id = p_user_id;

  IF NOT FOUND OR NOT v_prefs.dnd_enabled THEN
    RETURN false;
  END IF;

  v_now := CURRENT_TIME;
  v_day := EXTRACT(DOW FROM NOW());

  IF v_prefs.dnd_days IS NOT NULL AND v_day = ANY(v_prefs.dnd_days) THEN
    RETURN true;
  END IF;

  IF v_prefs.dnd_start_time IS NOT NULL AND v_prefs.dnd_end_time IS NOT NULL THEN
    IF v_prefs.dnd_start_time < v_prefs.dnd_end_time THEN
      RETURN v_now >= v_prefs.dnd_start_time OR v_now <= v_prefs.dnd_end_time;
    ELSE
      RETURN v_now >= v_prefs.dnd_start_time AND v_now <= v_prefs.dnd_end_time;
    END IF;
  END IF;

  RETURN false;
END;
$$;

CREATE OR REPLACE FUNCTION mark_notification_read(p_notification_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE notifications
  SET is_read    = true,
      read_at    = NOW(),
      updated_at = NOW()
  WHERE id      = p_notification_id
    AND user_id = auth.uid();
END;
$$;

CREATE OR REPLACE FUNCTION mark_all_notifications_read()
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE notifications
  SET is_read    = true,
      read_at    = NOW(),
      updated_at = NOW()
  WHERE user_id  = auth.uid()
    AND NOT is_read;
END;
$$;

CREATE OR REPLACE FUNCTION get_unread_count()
RETURNS INT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN (
    SELECT COUNT(*)::INT
    FROM notifications
    WHERE user_id  = auth.uid()
      AND NOT is_read
  );
END;
$$;

CREATE OR REPLACE FUNCTION cleanup_old_notifications()
RETURNS INT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_deleted INT;
BEGIN
  WITH deleted AS (
    DELETE FROM notifications
    WHERE created_at < NOW() - INTERVAL '90 days'
      AND is_read = true
    RETURNING 1
  )
  SELECT COUNT(*)::INT INTO v_deleted FROM deleted;

  RETURN v_deleted;
END;
$$;

-- Restrict direct invocation to service_role only
REVOKE EXECUTE ON FUNCTION cleanup_old_notifications() FROM anon, authenticated;

-- <<< END 20260620180000_fix_security_definer_search_path.sql <<<

-- >>> BEGIN 20260620190000_faxina_tier1c_archive_orphan_tables.sql >>>
-- FAXINA DB — Tier 1c: archive further provably-dead tables (reversible: ALTER TABLE ... SET SCHEMA).
--
-- Applied to production (doufsxqlfjyuvxuezpln) on 2026-06-20 via Supabase MCP. DETERMINISTIC mirror:
-- moves the EXACT tables archived in production, guarded by "only if still in public" (idempotent),
-- so a shadow DB / `supabase db reset` reproduces production exactly (no schema drift).
-- NOTE: analytics_events was a candidate but is intentionally NOT here — the runtime gate preserved it
-- in production (it received writes; live telemetry).
--
-- Evidence (computed at archive time): 0 refs in db (view/fn/cron/policy/inbound-FK) and repo,
-- 0 rows, 0 writes lifetime, not in realtime. Rollback: scripts/faxina-rollback.sql.
create schema if not exists archive;
do $$
declare
  t text; v_rows bigint; moved int := 0;
  tables text[] := array[
    'attribute_definitions','attribute_groups','category_target_audiences',
    'company_email_patterns','target_audiences'
  ];
begin
  foreach t in array tables loop
    if not exists (select 1 from information_schema.tables where table_schema='public' and table_name=t) then
      raise notice 'SKIP % (not in public)', t; continue; end if;
    if exists (select 1 from information_schema.tables where table_schema='archive' and table_name=t) then
      raise notice 'SKIP % (collision in archive)', t; continue; end if;
    execute format('select count(*) from public.%I', t) into v_rows;
    execute format('alter table public.%I set schema archive', t);
    insert into archive._cleanup_manifest(object_type,object_name,rows_at_move,reason,evidence,session)
    values ('table', t, v_rows,
            'tier1c orphan (deterministic mirror): 0 refs db+repo, 0 rows, 0 writes lifetime, not realtime',
            jsonb_build_object('phase','tier1c_orphan'), 'claude-faxina-2026-06-20');
    moved := moved + 1; raise notice 'ARCHIVED public.% -> archive (% rows)', t, v_rows;
  end loop;
  raise notice 'Tier1c mirror archived % tables', moved;
end $$;
NOTIFY pgrst, 'reload schema';

-- <<< END 20260620190000_faxina_tier1c_archive_orphan_tables.sql <<<

-- >>> BEGIN 20260620190000_faxina_tier3b_b1_archive_dead_fns_views.sql >>>
-- Faxina Tier 3b · batch 1 — arquiva (reversível) funções/views comprovadamente mortas.
--
-- Continuação de:
--   20260620160500_faxina_tier3_archive_dead_functions.sql (Tier 3 — 113 views + 11 funções)
-- Metodologia (5 gates, todos obrigatórios):
--   1. DB-orphan: 0 refs em prosrc de outras funções, defs de views/matviews, cron.job,
--      pg_policies (qual/with_check), defaults (pg_attrdef), constraints, índices, triggers.
--   2. code-absent: 0 ocorrências como string em src/ supabase/functions/ tests/ e2e/ scripts/
--      (apenas migrations/types.ts/*.md ignorados). Usuário confirmou: SEM consumidores externos
--      ao repositório, logo code-absent = prova completa de não-uso.
--   3. perfil de resíduo inequívoco: versionado-superado (_v10/_v11 com _v12 vivo),
--      classify_* legado (superado por fn_backfill_product_categories), helpers de ingestão
--      Asia "legacy"/"wp_to_canonical" (superados pelo edge fn asia-ingestion + crons atuais),
--      e views internas órfãs (NUNCA *_public — reservadas à exposição PostgREST).
--   4. sem overloads vivos (cada nome tem 1 overload, todos cobertos pelo gate 1).
--   5. reversível: ALTER ... SET SCHEMA archive (sem DROP) + log em archive._cleanup_manifest.
--
-- Rollback: scripts/faxina-rollback.sql  (ou ALTER ... SET SCHEMA public objeto-a-objeto).
-- Excluídos por evidência ao vivo: fn_spot_reconcile_variant_to_legacy (db_refs=1),
--   seed_discount_test_users (usado em tests/integration/discountApprovalFlow.test.ts),
--   generate_order_number_v5 e fn_simular_combo_gravacao base (mantidos por precaução — revisão).
do $$
declare
  v_fns text[] := array[
    'fn_simular_combo_gravacao_v10','fn_simular_combo_gravacao_v11',
    'classify_headphone','classify_powerbank','classify_speaker',
    'fn_asia_legacy_dispatch_batch','fn_asia_legacy_harvest_batch','fn_asia_wp_to_canonical'
  ];
  v_views text[] := array['v_audit_paradoxos_gravacao','v_product_videos_ready','vw_color_mapping'];
  r record; vname text; n_fn int := 0; n_vw int := 0; leftover int;
begin
  if not exists (select 1 from pg_namespace where nspname='archive') then
    raise exception 'ABORT: schema archive inexistente';
  end if;

  -- FUNÇÕES: move toda sobrecarga de cada nome alvo
  for r in
    select p.oid, p.proname, pg_get_function_identity_arguments(p.oid) as args
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.prokind='f' and p.proname = any(v_fns)
  loop
    if exists (select 1 from pg_trigger t where t.tgfoid=r.oid and not t.tgisinternal) then
      raise exception 'ABORT: %(%) é trigger-bound', r.proname, r.args;
    end if;
    execute format('alter function public.%I(%s) set schema archive', r.proname, r.args);
    insert into archive._cleanup_manifest(object_type,object_name,from_schema,to_schema,reason,evidence,session)
    select 'function', r.proname||'('||r.args||')','public','archive',
           'Tier3b-b1: DB-orphan + code-absent; resíduo versionado/legacy/classify',
           jsonb_build_object('args', r.args),
           'claude-faxina-2026-06-20'
    where not exists (
      select 1 from archive._cleanup_manifest m
      where m.session='claude-faxina-2026-06-20' and m.object_type='function'
        and m.object_name = r.proname||'('||r.args||')'
    );
    n_fn := n_fn + 1;
  end loop;

  -- VIEWS
  foreach vname in array v_views loop
    if exists (select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
               where n.nspname='public' and c.relname=vname and c.relkind='v') then
      execute format('alter view public.%I set schema archive', vname);
      insert into archive._cleanup_manifest(object_type,object_name,from_schema,to_schema,reason,evidence,session)
      select 'view', vname,'public','archive',
             'Tier3b-b1: view DB-orphan + code-absent; não é *_public',
             jsonb_build_object('kind','orphan_internal_view'),
             'claude-faxina-2026-06-20'
      where not exists (
        select 1 from archive._cleanup_manifest m
        where m.session='claude-faxina-2026-06-20' and m.object_type='view' and m.object_name=vname
      );
      n_vw := n_vw + 1;
    end if;
  end loop;

  -- INTEGRIDADE pós-move: nenhum alvo permanece no public
  select count(*) into leftover from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.prokind='f' and p.proname = any(v_fns);
  if leftover <> 0 then raise exception 'ABORT: % funções-alvo ainda no public', leftover; end if;
  select count(*) into leftover from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public' and c.relkind='v' and c.relname = any(v_views);
  if leftover <> 0 then raise exception 'ABORT: % views-alvo ainda no public', leftover; end if;

  raise notice 'Tier3b-b1 OK: % funções, % views arquivadas', n_fn, n_vw;
end $$;

-- <<< END 20260620190000_faxina_tier3b_b1_archive_dead_fns_views.sql <<<

-- >>> BEGIN 20260620190000_heal_faxina_live_tables.sql >>>
-- HEAL: reverse the part of the faxina (20260620150000_faxina_tier1) that archived three
-- LIVE tables, and re-run the backfills/objects affected. Idempotent and safe on a fresh DB
-- (the orphans list no longer archives these, so no `archive.<t>` copy exists and every
-- block below is a no-op).
--
-- Why these three were not orphans:
--   * notification_preferences  — read by is_dnd_active() (SECURITY DEFINER, 20260620180000),
--     called by the send-notification edge fn. With the table in `archive`, the DND check
--     throws "relation notification_preferences does not exist" at runtime.
--   * product_target_audiences  — indexed by 20260620150000_fix_catalog_critical_bugs.sql.
--   * user_favorites            — policy recreated by 20260620160000_fix_favorites_bugs_all.sql.

-- 1) Move the tables back to public if a prior faxina run archived them, and restore the
--    API-role grants that tier1b revoked while they sat in `archive`. RLS still governs
--    row access; service_role/postgres (crons, edge fns, SECURITY DEFINER) are unaffected.
do $$
declare t text;
begin
  foreach t in array array['notification_preferences','product_target_audiences','user_favorites'] loop
    if exists (select 1 from information_schema.tables where table_schema = 'archive' and table_name = t)
       and not exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = t) then
      execute format('alter table archive.%I set schema public', t);
      -- product_target_audiences is reference data (read-only for the API roles); the two
      -- user-scoped tables keep full DML behind RLS.
      if t = 'product_target_audiences' then
        execute 'grant select on public.product_target_audiences to authenticated';
      else
        execute format('grant select, insert, update, delete on public.%I to authenticated', t);
      end if;
      delete from archive._cleanup_manifest where object_name = t and to_schema = 'archive';
      raise notice 'HEAL: restored public.% from archive', t;
    end if;
  end loop;
end $$;

-- 2) Re-assert the objects the sibling migrations create on these tables, in case the
--    original CREATE was skipped/failed on an environment where the table was archived.
do $$
begin
  if exists (select 1 from information_schema.tables
             where table_schema = 'public' and table_name = 'product_target_audiences') then
    execute 'create index if not exists idx_product_target_audiences_category_id '
         || 'on public.product_target_audiences (category_id)';
  end if;

  if exists (select 1 from information_schema.tables
             where table_schema = 'public' and table_name = 'user_favorites')
     and not exists (select 1 from pg_policies
             where schemaname = 'public' and tablename = 'user_favorites'
               and policyname = 'users_create_own_favorites') then
    execute 'create policy users_create_own_favorites on public.user_favorites '
         || 'for insert to authenticated with check (user_id = auth.uid())';
  end if;
end $$;

-- 3) Re-backfill generated_mockups.logo_rotation / logo_scale from area_config. The original
--    20260620000001 migration added the columns with DEFAULT 0/100, so its `WHERE ... IS NULL`
--    backfill matched nothing and clobbered older rows to the default while the real values
--    still live in area_config.
update public.generated_mockups
set
  logo_rotation = coalesce((area_config ->> 'logoRotation')::numeric, logo_rotation),
  logo_scale    = coalesce((area_config ->> 'logoScale')::numeric, logo_scale)
where area_config is not null
  and (area_config ? 'logoRotation' or area_config ? 'logoScale');

-- <<< END 20260620190000_heal_faxina_live_tables.sql <<<

-- >>> BEGIN 20260620190000_reposicao_revoke_anon_grants.sql >>>
-- ============================================================================
-- Reposição — fecha brecha de exposição a `anon` (regressão de BUG-SEC-1)
--
-- CONTEXTO
--   A migração `fix_reposicao_rpcs` (2026-06-19) já havia revogado EXECUTE de
--   `anon` em fn_get_reposicao_listing e fn_get_replenishment_stats. Porém o
--   estado VIVO do banco voltou a conceder acesso a `anon`: a recriação
--   posterior das funções reaplicou o GRANT padrão do Supabase
--   (ALTER DEFAULT PRIVILEGES … TO anon) e o REVOKE não foi re-executado.
--
--   O Security Advisor do Supabase (lint `anon_security_definer_function_executable`)
--   e a auditoria do módulo confirmaram que ambas as RPCs SECURITY DEFINER
--   estavam chamáveis por usuários ANÔNIMOS via /rest/v1/rpc/<fn>, vazando
--   catálogo, preço de venda e fornecedor sem autenticação.
--
--   A view `vw_product_availability` estava com SELECT liberado para `anon`
--   (RLS não se aplica a views; a view roda como owner — SECURITY DEFINER —
--   e contorna a RLS de product_variants), expondo estoque e datas de
--   reposição por variante.
--
-- SEGURANÇA DA MUDANÇA
--   A rota /reposicao é montada sob ProtectedRoute (somente autenticados) e o
--   restante do módulo (sino "Chegou" → fn_get_recent_restocks) já opera apenas
--   com `authenticated`. Logo, remover `anon`/`PUBLIC` não quebra nenhum fluxo.
--
--   REVOKE/GRANT são idempotentes — reaplicar esta migração é seguro.
-- ============================================================================

-- ─── 1. fn_get_reposicao_listing ───────────────────────────────────────────
