(_challenge_id uuid)','step_up_token_revoke(_token_id uuid)','store_user_token_revocation(_user_id uuid)','sync_order_payment_status()','toggle_user_step_up(_user_id uuid, _enabled boolean)','track_voice_command(_transcript text)','trg_auto_revoke_mcp_on_role_loss()','trg_sync_external_connections()','trg_update_is_thermal()','trg_validate_allowed_techniques()','trigger_auto_classify_product()','trigger_gerar_nome_variante()','trigger_mark_for_processing()','trim_connection_test_history()','unblock_ip(_ip text)','update_app_settings_timestamp()','update_categories_updated_at()','update_image_after_sync(p_image_id uuid, p_cloudflare_image_id character varying, p_url_cdn text, p_file_size_bytes bigint, p_width_px integer, p_height_px integer, p_format character varying)','update_notebook_tables_timestamp()','update_print_area_images_updated_at()','update_product_images_timestamp()','update_product_videos_timestamp()','update_step_up_user_settings(_settings jsonb, _user_id uuid)','update_video_after_sync(p_video_id uuid, p_cloudflare_video_id character varying, p_url_stream text, p_url_hls text, p_url_dash text, p_url_thumbnail text, p_duration_seconds integer, p_width_px integer, p_height_px integer)','update_video_from_cloudflare(p_cloudflare_video_id character varying, p_status character varying, p_duration_seconds integer, p_width_px integer, p_height_px integer, p_thumbnail_url text, p_error_message text)','validate_edge_functions_base_url(_environment text)','validate_ip_access_control()','validate_product_total_percentage(p_product_id uuid)','validate_secret_rotation_action_type()','vault_delete_secret(p_name text)','vault_get_secret(p_name text)','vault_list_secret_names()','vault_set_secret(p_name text, p_value text, p_description text)','verify_step_up_password(_challenge_id uuid, _password_attempt text)','verify_user_step_up_required(_action step_up_action, _user_id uuid)','voice_command_audit()'];
begin
  create schema if not exists archive;
  foreach sig in array sigs loop
    fn_name := split_part(sig, '(', 1);
    fn_args := (regexp_match(sig, '^[^(]*\((.*)\)$'))[1];
    if exists (
         select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
         where n.nspname='public' and p.proname=fn_name and pg_get_function_identity_arguments(p.oid)=fn_args
       ) and not exists (
         select 1 from pg_proc ap join pg_namespace an on an.oid=ap.pronamespace
         where an.nspname='archive' and ap.proname=fn_name and pg_get_function_identity_arguments(ap.oid)=fn_args
       ) then
      execute format('alter function public.%I(%s) set schema archive', fn_name, fn_args);
      insert into archive._cleanup_manifest(object_type,object_name,reason,evidence,session)
      values ('function', sig, 'tier3b dead fn (deterministic mirror): 0 db refs + 0 repo refs',
              jsonb_build_object('phase','tier3b_function'), 'claude-faxina-2026-06-20');
      moved := moved + 1;
    end if;
  end loop;
  raise notice 'Tier3b mirror archived % functions', moved;
end $$;
NOTIFY pgrst, 'reload schema';

-- <<< END 20260620190500_faxina_tier3b_archive_dead_functions_bulk.sql <<<

-- >>> BEGIN 20260620191000_faxina_tier1d_archive_orphan_tables.sql >>>
-- FAXINA DB — Tier 1d: archive tables freed after the Tier-3b function purge (reversible).
--
-- Applied to production (doufsxqlfjyuvxuezpln) on 2026-06-20 via Supabase MCP. DETERMINISTIC mirror:
-- moves the EXACT tables archived in production, guarded by "only if still in public" (idempotent),
-- so a shadow DB / `supabase db reset` reproduces production exactly (no schema drift).
-- (Other Tier-1d candidates were preserved in production because a live view/function still references
-- them; they are intentionally NOT listed here.)
--
-- Evidence (computed at archive time): 0 refs in db (view/fn/cron/policy/inbound-FK) and repo,
-- 0 writes lifetime, not realtime/partition. Rollback: scripts/faxina-rollback.sql.
create schema if not exists archive;
do $$
declare
  t text; v_rows bigint; moved int := 0;
  tables text[] := array[
    'category_accessory_categories','classify_functions_registry','edge_function_invocations',
    'enrichment_log','magic_up_reactions','quote_drafts','supplier_customization_options_raw'
  ];
begin
  foreach t in array tables loop
    if not exists (select 1 from information_schema.tables where table_schema='public' and table_name=t) then
      raise notice 'SKIP % (not in public)', t; continue; end if;
    if exists (select 1 from information_schema.tables where table_schema='archive' and table_name=t) then
      raise notice 'SKIP % (collision in archive)', t; continue; end if;
    execute format('select count(*) from public.%I', t) into v_rows;
    execute format('alter table public.%I set schema archive', t);
    insert into archive._cleanup_manifest(object_type,object_name,rows_at_move,reason,evidence,session)
    values ('table', t, v_rows,
            'tier1d orphan (deterministic mirror): freed after fn purge; 0 refs db+repo, 0 writes lifetime, not realtime/partition',
            jsonb_build_object('phase','tier1d_orphan'), 'claude-faxina-2026-06-20');
    moved := moved + 1; raise notice 'ARCHIVED public.% -> archive (% rows)', t, v_rows;
  end loop;
  raise notice 'Tier1d mirror archived % tables', moved;
end $$;
NOTIFY pgrst, 'reload schema';

-- <<< END 20260620191000_faxina_tier1d_archive_orphan_tables.sql <<<

-- >>> BEGIN 20260620191500_faxina_tier3b_b2_archive_legacy_supplier_fns.sql >>>
-- Faxina Tier 3b · batch 2 — arquiva (reversível) helpers legados de ingestão/fornecedor.
-- Gates: DB-orphan (0 refs em prosrc/views/crons/policies/defaults/constraints/índices/triggers)
--        + code-absent (sem consumidores externos, confirmado) + corpo confirmado legado/wrapper órfão.
-- Sucessores vivos preservados: fn_expire_novelties_with_stats, fn_process_asia_stock_pending,
--   fn_spot_stock_fast_sync, fn_apply_auto_tag_rules, edge fn asia-ingestion, materials-api.
-- Mecânica: ALTER FUNCTION ... SET SCHEMA archive (sem DROP). Reversão: scripts/faxina-rollback.sql.
do $$
declare
  v_fns text[] := array[
    'fn_ingest_asia_api_batch','fn_ingest_asia_product','fn_classify_spot_image','fn_spot_process_batch',
    'comparar_precos_spot','fn_resolve_supplier','fn_color_link_all_suppliers','fn_tag_product_complete',
    'fn_import_product_properties','extract_xbz_image_metadata','fn_get_asia_api_key','fn_get_asia_secret_key',
    'fn_get_cf_credentials','fn_extract_color_from_name','fn_extract_material_from_name','fn_recomendar_tecnica',
    'fn_list_deactivation_requests','create_material_with_equivalence','fn_expire_novelties'
  ];
  r record; n_fn int := 0; leftover int;
begin
  for r in
    select p.oid, p.proname, pg_get_function_identity_arguments(p.oid) as args
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.prokind='f' and p.proname = any(v_fns)
  loop
    if exists (select 1 from pg_trigger t where t.tgfoid=r.oid and not t.tgisinternal) then
      raise exception 'ABORT: %(%) é trigger-bound', r.proname, r.args;
    end if;
    execute format('alter function public.%I(%s) set schema archive', r.proname, r.args);
    insert into archive._cleanup_manifest(object_type,object_name,from_schema,to_schema,reason,evidence,session)
    select 'function', r.proname||'('||r.args||')','public','archive',
           'Tier3b-b2: DB-orphan + code-absent; helper legado ingestão/fornecedor (sucessor vivo no pipeline)',
           jsonb_build_object('args', r.args),
           'claude-faxina-2026-06-20'
    where not exists (select 1 from archive._cleanup_manifest m
                      where m.session='claude-faxina-2026-06-20' and m.object_type='function'
                        and m.object_name = r.proname||'('||r.args||')');
    n_fn := n_fn + 1;
  end loop;
  select count(*) into leftover from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.prokind='f' and p.proname = any(v_fns);
  if leftover <> 0 then raise exception 'ABORT: % funções-alvo ainda no public', leftover; end if;
  raise notice 'Tier3b-b2 OK: % funções arquivadas', n_fn;
end $$;

-- <<< END 20260620191500_faxina_tier3b_b2_archive_legacy_supplier_fns.sql <<<

-- >>> BEGIN 20260620200001_fix_super_filtro_drop_old_5param_overload.sql >>>
-- BUG-SF-RPC-ARITY: remove old 5-param overload of fn_super_filtro_product_ids.
-- The 6-param version (with _endomarketing) was added in 20260618160000_fn_super_filtro_add_endomarketing.sql.
-- Without dropping the old signature, Postgres kept both overloads and the client
-- (useProductsByMetadata) was calling the 6-param version unambiguously, but the
-- old 5-param ghost caused planning overhead and risk of ambiguous resolution.
-- Safe to drop: no caller uses 5 params — the TS client always sends all 6.

DROP FUNCTION IF EXISTS public.fn_super_filtro_product_ids(
  text[], text[], text[], text[], text[]
);

-- <<< END 20260620200001_fix_super_filtro_drop_old_5param_overload.sql <<<

-- >>> BEGIN 20260620200002_fix_super_filtro_pcd_index.sql >>>
-- BUG-SF-IDX-PCD: partial index on product_commemorative_dates for active rows.
-- fn_super_filtro_product_ids filters pcd.is_active = true via EXISTS subquery.
-- Without this index, every call with a datas filter did a full scan of ~34k rows.
-- Partial index shrinks working set to only active links, matching the WHERE clause exactly.

CREATE INDEX IF NOT EXISTS idx_pcd_product_id_active
  ON public.product_commemorative_dates (product_id)
  WHERE is_active = true;

-- <<< END 20260620200002_fix_super_filtro_pcd_index.sql <<<

-- >>> BEGIN 20260620200003_fix_super_filtro_variant_color_index.sql >>>
-- BUG-SF-IDX-VARIANTS: compound partial index on product_variants for color filtering.
-- useColorEnrichment and useProductsByColor filter: is_active=true AND color_id IN (...) AND product_id IN (...).
-- Without this index, each color enrichment batch (up to 80 products × N color_ids) did full scans.
-- (color_id, product_id) covers both the IN-list predicates and enables index-only scans
-- when only product_id is needed after filtering by color_id.

CREATE INDEX IF NOT EXISTS idx_variants_color_id_active
  ON public.product_variants (color_id, product_id)
  WHERE is_active = true;

-- <<< END 20260620200003_fix_super_filtro_variant_color_index.sql <<<

-- >>> BEGIN 20260621000000_fix_favorite_position_race.sql >>>
-- GAP-12 follow-up: make per-list favorite position assignment truly atomic.
--
-- The original fn_favorite_items_assign_position (20260620170000) still did a plain
-- `SELECT COALESCE(MAX(position), -1) + 1` inside a BEFORE INSERT trigger and called it
-- "atomic", but it is not: under READ COMMITTED two concurrent inserts to the same list
-- both read the same MAX (neither sees the other's uncommitted row) and assign duplicate
-- positions, and there is no UNIQUE(list_id, position) to reject the collision — producing
-- nondeterministic ordering and breaking drag-reorder index math.
--
-- Fix: lock the parent favorite_lists row first, so concurrent inserts to the same list
-- serialize on that row instead of racing on MAX(position). CREATE OR REPLACE heals prod
-- and replay alike.

CREATE OR REPLACE FUNCTION public.fn_favorite_items_assign_position()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.position IS NULL THEN
    -- Serialize concurrent inserts to the same list by locking the parent list row.
    PERFORM 1 FROM favorite_lists WHERE id = NEW.list_id FOR UPDATE;
    SELECT COALESCE(MAX(position), -1) + 1
      INTO NEW.position
      FROM favorite_items
     WHERE list_id = NEW.list_id;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_favorite_items_assign_position() FROM anon, authenticated, PUBLIC;

-- <<< END 20260621000000_fix_favorite_position_race.sql <<<

-- >>> BEGIN 20260621000000_fix_favorites_security_position.sql >>>
-- Migration: fix_favorites_security_position
-- 2026-06-21
--
-- 1. SECURITY FIX: get_favorite_list_counts must verify caller is the requested user.
--    Previous version allowed any authenticated user to read another user's list counts
--    by passing an arbitrary _user_id (SECURITY DEFINER with no auth.uid() guard).
--
-- 2. POSITION: Add atomic position assignment trigger for favorite_lists table.
--    favorite_items already has trg_fi_assign_position; favorite_lists lacked one,
--    leaving position = client-supplied value (race between concurrent create calls).

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. Secure get_favorite_list_counts
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_favorite_list_counts(_user_id uuid)
RETURNS TABLE(list_id uuid, item_count bigint)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  -- Caller must be _user_id. Prevents horizontal privilege escalation where
  -- any authenticated user could query another user's list counts.
  SELECT fi.list_id, COUNT(*)::bigint AS item_count
    FROM public.favorite_items fi
   WHERE fi.user_id = _user_id
     AND _user_id = auth.uid()
   GROUP BY fi.list_id;
$$;

GRANT EXECUTE ON FUNCTION public.get_favorite_list_counts(uuid) TO authenticated;

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. Atomic position for favorite_lists
-- ─────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_favorite_lists_assign_position()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_max int;
BEGIN
  -- Assign position = current max + 1 for this user, ignoring client-supplied value
  SELECT COALESCE(MAX(position), -1) + 1
    INTO v_max
    FROM public.favorite_lists
   WHERE user_id = NEW.user_id;
  NEW.position := v_max;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_fl_assign_position ON public.favorite_lists;
CREATE TRIGGER trg_fl_assign_position
  BEFORE INSERT ON public.favorite_lists
  FOR EACH ROW EXECUTE FUNCTION public.fn_favorite_lists_assign_position();

-- <<< END 20260621000000_fix_favorites_security_position.sql <<<

-- >>> BEGIN 20260621000001_seller_carts_compound_indexes.sql >>>
-- Composite indexes for seller_carts queries
-- The main query is: WHERE seller_id = ? ORDER BY updated_at DESC
-- The current single-column index on seller_id forces a sort step after filtering.
-- A compound (seller_id, updated_at DESC) index satisfies both clauses in one scan.
CREATE INDEX IF NOT EXISTS idx_seller_carts_seller_updated
  ON public.seller_carts(seller_id, updated_at DESC);

-- Composite index for seller_cart_items nested sort
-- PostgREST query: WHERE cart_id = ? ORDER BY sort_order ASC
-- A compound (cart_id, sort_order) index avoids a sort after the cart_id filter.
CREATE INDEX IF NOT EXISTS idx_seller_cart_items_cart_sort
  ON public.seller_cart_items(cart_id, sort_order ASC);

-- <<< END 20260621000001_seller_carts_compound_indexes.sql <<<

-- >>> BEGIN 20260621100000_faxina_restore_ai_function_routing_and_view.sql >>>
-- FAXINA ROLLBACK: restore ai_function_routing to public + recreate v_ai_function_routing_effective
-- Reason: ai_function_routing was incorrectly moved to archive schema.
-- The table is actively used by the ai-router edge function via the view.
-- The view v_ai_function_routing_effective was also missing (dropped by tier3 migration).

-- Step 1: restore the table
ALTER TABLE archive.ai_function_routing SET SCHEMA public;

-- Step 2: recreate the view
CREATE OR REPLACE VIEW public.v_ai_function_routing_effective AS
SELECT
  r.id                        AS routing_id,
  r.function_name,
  r.is_active,
  r.required_capabilities,
  r.request_overrides,
  r.primary_model_id,
  pm.model_id                 AS primary_model,
  pm.capabilities             AS primary_capabilities,
  pm.provider_id              AS primary_provider_id,
  pp.slug                     AS primary_provider_slug,
  pm.is_active                AS primary_active,
  pp.is_active                AS primary_provider_active,
  COALESCE(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'model_id',        fm.id,
          'model',           fm.model_id,
          'provider_slug',   fp.slug,
          'capabilities',    fm.capabilities,
          'cost_input',      fm.cost_input_per_1m,
          'cost_output',     fm.cost_output_per_1m,
          'model_active',    fm.is_active,
          'provider_active', fp.is_active,
          'order_index',     ord.idx
        )
        ORDER BY ord.idx
      )
      FROM unnest(r.fallback_model_ids) WITH ORDINALITY AS ord(fallback_model_id, idx)
      JOIN public.ai_models fm ON fm.id = ord.fallback_model_id
      JOIN public.ai_providers fp ON fp.id = fm.provider_id
    ),
    '[]'::jsonb
  )                           AS fallbacks
FROM public.ai_function_routing r
JOIN public.ai_models pm ON pm.id = r.primary_model_id
JOIN public.ai_providers pp ON pp.id = pm.provider_id;

-- Step 3: restore grants
GRANT SELECT ON public.v_ai_function_routing_effective TO authenticated;
GRANT SELECT ON public.v_ai_function_routing_effective TO service_role;

-- Step 4: restore table grants
REVOKE ALL ON public.ai_function_routing FROM anon;
GRANT SELECT ON public.ai_function_routing TO authenticated;
GRANT ALL   ON public.ai_function_routing TO service_role;

-- <<< END 20260621100000_faxina_restore_ai_function_routing_and_view.sql <<<

