-- >>> BEGIN 20260621203000_harden_create_quote_transactional_resolve_org_seller.sql >>>
-- APLICADO 2026-06-21 (via Supabase MCP execute_sql no projeto doufsxqlfjyuvxuezpln).
-- Este arquivo DOCUMENTA uma migração já aplicada em produção (convenção do time:
-- aplicar via execute_sql/apply_migration e versionar o .sql com header "APLICADO").
--
-- CONTEXTO / BUG
--   Sintoma em produção: ao finalizar "Novo Orçamento" o sistema exibia
--   "Erro ao criar orçamento" e não gerava preview nem PDF.
--   Causa-raiz: o front-end enviava organization_id de uma org FANTASMA
--   (35c6a2a6-…, seed de preview-snapshot inexistente em public.organizations).
--   A policy RLS de INSERT em public.quotes (org_members_create_quotes) exige
--   user_is_org_member(organization_id); com org inválida/nula o INSERT era
--   bloqueado ("new row violates row-level security policy for table quotes"),
--   e todo o fluxo a jusante (preview + PDF, que são client-side e só ocorrem
--   após a criação) ficava inacessível.
--
-- CORREÇÃO (defesa em profundidade, independente do estado do client)
--   create_quote_transactional passa a resolver, no servidor, a partir de auth.uid():
--     • organization_id: usa o enviado SE o usuário for membro; senão faz fallback
--       para a organização mais antiga do usuário em public.user_organizations.
--     • seller_id: default = auth.uid() quando ausente.
--     • created_by: passa a ser preenchido (antes nunca era setado).
--   Mantida como SECURITY INVOKER (RLS continua valendo). Se nenhuma org puder ser
--   resolvida, levanta 23502 com mensagem clara em vez de violar a RLS silenciosamente.
--
-- VALIDAÇÃO
--   Testado E2E sob role=authenticated (RLS ativa) com a org omitida E com a org
--   fantasma 35c6a2a6-…: em ambos resolveu para 5db5aee1-… e criou orçamento + itens.
--   23/23 fn_run_smoke_tests() PASS. Zero linhas de teste vazadas (rollback).

CREATE OR REPLACE FUNCTION public.create_quote_transactional(_quote jsonb, _items jsonb)
 RETURNS quotes
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  _new_quote    public.quotes;
  _new_quote_id uuid;
  _item         jsonb;
  _pers         jsonb;
  _new_item_id  uuid;
  _actor_id     uuid;
  _uid          uuid := auth.uid();
  _org_id       uuid := nullif(_quote->>'organization_id', '')::uuid;
  _seller_id    uuid := nullif(_quote->>'seller_id', '')::uuid;
BEGIN
  -- Resolução server-side de organização/vendedor (independe do estado do client)
  IF _uid IS NOT NULL THEN
    IF _org_id IS NULL OR NOT public.user_is_org_member(_org_id) THEN
      SELECT uo.organization_id INTO _org_id
      FROM public.user_organizations uo
      WHERE uo.user_id = _uid
      ORDER BY uo.created_at ASC, uo.organization_id ASC
      LIMIT 1;
    END IF;
    IF _seller_id IS NULL THEN
      _seller_id := _uid;
    END IF;
  END IF;

  IF _org_id IS NULL THEN
    RAISE EXCEPTION 'Não foi possível determinar a organização do orçamento: usuário sem organização vinculada.'
      USING ERRCODE = '23502';
  END IF;

  INSERT INTO public.quotes (
    quote_number, client_id, contact_id,
    client_name, client_email, client_phone, client_company, client_cnpj,
    seller_id, created_by, organization_id, status,
    subtotal, discount_percent, discount_amount, total, negotiation_markup_percent,
    payment_method, payment_terms, delivery_time, shipping_type, shipping_cost,
    notes, internal_notes, valid_until
  )
  VALUES (
    coalesce(_quote->>'quote_number', ''),
    nullif(_quote->>'client_id', '')::uuid,
    nullif(_quote->>'contact_id', '')::uuid,
    coalesce(_quote->>'client_name', ''),
    _quote->>'client_email',
    _quote->>'client_phone',
    _quote->>'client_company',
    nullif(_quote->>'client_cnpj', ''),
    _seller_id,
    coalesce(_uid, _seller_id),
    _org_id,
    coalesce(_quote->>'status', 'draft'),
    coalesce((_quote->>'subtotal')::numeric, 0),
    coalesce((_quote->>'discount_percent')::numeric, 0),
    coalesce((_quote->>'discount_amount')::numeric, 0),
    coalesce((_quote->>'total')::numeric, 0),
    coalesce((_quote->>'negotiation_markup_percent')::numeric, 0),
    _quote->>'payment_method',
    _quote->>'payment_terms',
    _quote->>'delivery_time',
    _quote->>'shipping_type',
    coalesce((_quote->>'shipping_cost')::numeric, 0),
    _quote->>'notes',
    _quote->>'internal_notes',
    nullif(_quote->>'valid_until', '')::date
  )
  RETURNING * INTO _new_quote;

  _new_quote_id := _new_quote.id;

  FOR _item IN SELECT value FROM jsonb_array_elements(coalesce(_items, '[]'::jsonb)) LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    VALUES (
      _new_quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    RETURNING id INTO _new_item_id;

    FOR _pers IN SELECT value FROM jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      VALUES (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    END LOOP;
  END LOOP;

  SELECT * INTO _new_quote FROM public.quotes WHERE id = _new_quote_id;

  _actor_id := coalesce(_uid, _seller_id);
  IF _actor_id IS NOT NULL THEN
    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      _new_quote_id,
      _actor_id,
      'created',
      format('Orçamento %s criado com %s item(s) via RPC',
             _new_quote.quote_number,
             (SELECT count(*) FROM public.quote_items WHERE quote_id = _new_quote_id)),
      jsonb_build_object(
        'status',  _new_quote.status,
        'subtotal',_new_quote.subtotal,
        'total',   _new_quote.total,
        'markup',  _new_quote.negotiation_markup_percent,
        'n_items', (SELECT count(*) FROM public.quote_items WHERE quote_id = _new_quote_id)
      )
    );
  END IF;

  RETURN _new_quote;
END;
$function$;

-- <<< END 20260621203000_harden_create_quote_transactional_resolve_org_seller.sql <<<

-- >>> BEGIN 20260621210000_faxina_complete_archive_restore_11_tables_APLICADO.sql >>>
-- APLICADO via MCP (apply_migration) em 2026-06-21 — reconciliação de estado.
--
-- CONTEXTO / ROOT CAUSE:
-- A migration 20260621100100_faxina_restore_active_tables_from_archive pretendia mover 15
-- tabelas de archive -> public, mas foi aplicada apenas PARCIALMENTE: somente 4 chegaram em
-- public (user_onboarding, navigation_analytics, secret_rotation_log, user_ip_allowlist).
-- As 11 restantes ficaram presas em archive, produzindo PGRST205 (HTTP 404 "Could not find
-- the table public.<x> in the schema cache") em todo .from() do app/edge-functions que as
-- referencia. O sintoma observado em produção foi expert_conversations na QuoteViewPage.
--
-- POR QUE SET SCHEMA É SEGURO:
-- ALTER TABLE ... SET SCHEMA muda apenas pg_class.relnamespace; o OID é preservado, então
-- policies (RLS), constraints, FKs e GRANTS (ACL em relacl) viajam junto e permanecem válidos.
-- Verificado antes de aplicar: authenticated mantém DML completo nas tabelas de feature
-- (expert_*, kit_collaborators, sales_goals, etc.), webhook_request_nonces fica SELECT-only,
-- anon sem acesso, service_role ALL. A policy de expert_messages referencia expert_conversations
-- por OID, portanto passou a resolver para public.expert_conversations automaticamente.
-- Ordem parent-first respeita a FK optimization_queue_runs.queue_id -> optimization_queue.
-- Bloco idempotente: move apenas o que está em archive e ainda não existe em public.

DO $$
DECLARE
  t text;
  ordered text[] := ARRAY[
    'optimization_queue',        -- pai antes do filho (FK)
    'optimization_queue_runs',
    'expert_conversations',      -- antes de expert_messages (policy referencia por OID)
    'expert_messages',
    'geo_allowed_countries',
    'kit_collaborators',
    'sales_goals',
    'saved_trends_views',
    'simulator_wizard_drafts',
    'video_variant_links',
    'webhook_request_nonces'
  ];
BEGIN
  FOREACH t IN ARRAY ordered LOOP
    IF EXISTS (
      SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='archive' AND c.relname=t AND c.relkind='r'
    ) AND NOT EXISTS (
      SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relname=t
    ) THEN
      EXECUTE format('ALTER TABLE archive.%I SET SCHEMA public', t);
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
      EXECUTE format('REVOKE ALL ON public.%I FROM anon', t);
      EXECUTE format('GRANT ALL ON public.%I TO service_role', t);
    END IF;
  END LOOP;
END $$;

NOTIFY pgrst, 'reload schema';

-- NOTA DE FOLLOW-UP (não aplicado aqui — requer decisão do arquiteto):
-- public.kit_collaborators.kit_id tem FK para archive.custom_kits (que permaneceu em archive).
-- A FK cross-schema é válida e não quebra, mas a feature kit-builder depende de custom_kits;
-- avaliar incluir custom_kits (e tabelas relacionadas) num próximo restore.

-- <<< END 20260621210000_faxina_complete_archive_restore_11_tables_APLICADO.sql <<<

-- >>> BEGIN 20260621210000_onboarding_auto_assign_org_canonica.sql >>>
-- APLICADO 2026-06-21 (Supabase MCP execute_sql, projeto doufsxqlfjyuvxuezpln).
-- Documenta migração JÁ APLICADA em produção (convenção: aplicar + versionar com header APLICADO).
--
-- BUG / GAP: nenhum mecanismo de onboarding vinculava novos usuários a uma organização.
--   handle_new_user (auth.users) cria apenas o profile; fn_grant_default_role_on_profile
--   concede apenas user_roles. O antigo trigger auto_assign (apontado para org fantasma)
--   foi removido. Resultado: todo novo usuário ficaria SEM linha em user_organizations,
--   que é a tabela consultada pela RLS de quotes (user_is_org_member) -> não conseguiria
--   criar orçamento (e o fallback do RPC retornaria 23502).
--
-- CORREÇÃO: trigger AFTER INSERT em profiles que vincula o novo perfil à organização
--   canônica (5db5aee1) em AMBAS as tabelas de membership. Idempotente; guarded contra
--   preview-snapshots sem a org.
CREATE OR REPLACE FUNCTION public.fn_auto_assign_org_on_profile()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  _org constant uuid := '5db5aee1-064b-4ef4-9193-345dcd8274ea'; -- unica org real (Promo Brindes)
BEGIN
  IF EXISTS (SELECT 1 FROM public.organizations WHERE id = _org) THEN
    INSERT INTO public.user_organizations (organization_id, user_id)
    VALUES (_org, NEW.id) ON CONFLICT (organization_id, user_id) DO NOTHING;
    INSERT INTO public.organization_members (organization_id, user_id)
    VALUES (_org, NEW.id) ON CONFLICT (organization_id, user_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS trg_auto_assign_org ON public.profiles;
CREATE TRIGGER trg_auto_assign_org
  AFTER INSERT ON public.profiles
  FOR EACH ROW EXECUTE FUNCTION public.fn_auto_assign_org_on_profile();

-- HIGIENE: remove vinculos de membership orfaos (usuarios deletados de auth.users e profiles).
-- Seguro: so remove quem nao existe nem em auth.users nem em profiles. Idempotente.
WITH orf AS (
  SELECT uo.user_id FROM public.user_organizations uo
  WHERE NOT EXISTS (SELECT 1 FROM auth.users au WHERE au.id=uo.user_id)
    AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=uo.user_id)
  UNION
  SELECT om.user_id FROM public.organization_members om
  WHERE NOT EXISTS (SELECT 1 FROM auth.users au WHERE au.id=om.user_id)
    AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=om.user_id)
),
d1 AS (DELETE FROM public.user_organizations uo USING orf WHERE uo.user_id=orf.user_id RETURNING 1),
d2 AS (DELETE FROM public.organization_members om USING orf WHERE om.user_id=orf.user_id RETURNING 1)
SELECT (SELECT count(*) FROM d1) AS removidos_uo, (SELECT count(*) FROM d2) AS removidos_om;

-- <<< END 20260621210000_onboarding_auto_assign_org_canonica.sql <<<

-- >>> BEGIN 20260621211000_rename_org_canonica_promo_brindes.sql >>>
-- APLICADO 2026-06-21 (Supabase MCP execute_sql, projeto doufsxqlfjyuvxuezpln).
-- A migracao 20260527143139 tentou renomear a org para "Promo Brindes" mas mirava o id
-- fantasma (35c6a2a6) inexistente -> UPDATE 0 linhas. Aqui alinhamos o registro REAL
-- (5db5aee1) ao FIXED_ORG do front-end (name/slug). Idempotente.
UPDATE public.organizations
SET name = 'Promo Brindes', slug = 'promo-brindes'
WHERE id = '5db5aee1-064b-4ef4-9193-345dcd8274ea';

