-- ─── PERFORMANCE INDEXES ─────────────────────────────────────────
-- FIX-04: Índices de performance ausentes
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE INDEX IF NOT EXISTS idx_quotes_client_id
  ON public.quotes USING btree (client_id)
  WHERE client_id IS NOT NULL;

