-- >>> BEGIN 20260623000002_products_name_m2_fix_medallion_coverage.sql >>>
-- M2: FIX vw_medallion_coverage.display_name_pct
-- BUG: comparava name com fn_normalize_product_name()=UPPER() => 100% falso positivo
-- FIX: predicado de qualidade real
-- NAO altera fn_normalize_product_name (UPPERCASE intencional para product_variants)
CREATE OR REPLACE VIEW public.vw_medallion_coverage AS
 SELECT s.name AS fornecedor, 'silver'::text AS camada, count(*) AS produtos,
    round(((100.0*(sum(CASE WHEN (NULLIF(TRIM(BOTH FROM pp.ncm_code),''::text) IS NOT NULL) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS ncm_pct,
    round(((100.0*(sum(CASE WHEN (jsonb_array_length(COALESCE(pp.materials,'[]'::jsonb))>0) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS materials_pct,
    round(((100.0*(sum(CASE WHEN (jsonb_array_length(COALESCE(pp.tags,'[]'::jsonb))>0) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS tags_pct,
    round(((100.0*(sum(CASE WHEN (COALESCE(array_length(pp.meta_keywords,1),0)>0) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS meta_pct,
    round(((100.0*(sum(CASE WHEN (pp.ipi_rate IS NOT NULL) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS ipi_pct,
    round(((100.0*(sum(CASE WHEN (NULLIF(TRIM(BOTH FROM pp.description),''::text) IS NOT NULL) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS description_pct,
    NULL::numeric AS category_pct, NULL::numeric AS display_name_pct
   FROM (produtos_padronizacao pp JOIN suppliers s ON ((s.id=pp.supplier_id))) GROUP BY s.name
UNION ALL
 SELECT s.name AS fornecedor, 'gold'::text AS camada, count(*) AS produtos,
    round(((100.0*(sum(CASE WHEN (NULLIF(TRIM(BOTH FROM p.ncm_code),''::text) IS NOT NULL) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS ncm_pct,
    round(((100.0*(sum(CASE WHEN ((jsonb_array_length(COALESCE(p.materials,'[]'::jsonb))>0) OR (EXISTS (SELECT 1 FROM product_materials pm WHERE (pm.product_id=p.id)))) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS materials_pct,
    round(((100.0*(sum(CASE WHEN (jsonb_array_length(COALESCE(p.tags,'[]'::jsonb))>0) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS tags_pct,
    round(((100.0*(sum(CASE WHEN (COALESCE(array_length(p.meta_keywords,1),0)>0) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS meta_pct,
    round(((100.0*(sum(CASE WHEN (p.ipi_rate IS NOT NULL) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS ipi_pct,
    round(((100.0*(sum(CASE WHEN (NULLIF(TRIM(BOTH FROM p.description),''::text) IS NOT NULL) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS description_pct,
    round(((100.0*(sum(CASE WHEN (p.category_id IS NOT NULL) THEN 1 ELSE 0 END))::numeric)/(count(*))::numeric),1) AS category_pct,
    round(((100.0*(sum(CASE WHEN (p.name IS NULL OR length(TRIM(p.name))=0 OR p.name LIKE '%  %' OR p.name ~ E'[\\t\\n\\r]' OR length(p.name)>200 OR p.name!~'[A-Za-z0-9]') THEN 1 ELSE 0 END))::numeric)/(NULLIF(count(*),0))::numeric),1) AS display_name_pct
   FROM (products p JOIN suppliers s ON ((s.id=p.supplier_id))) GROUP BY s.name;

-- <<< END 20260623000002_products_name_m2_fix_medallion_coverage.sql <<<

-- >>> BEGIN 20260623000003_products_name_m3_seo_guard.sql >>>
-- M3: Guard performance trg_products_seo_autofill
-- Early return quando name nao mudou e slug/meta ja existem
-- Elimina generate_product_slug em UPDATEs sem mudanca de name
CREATE OR REPLACE FUNCTION public.trg_products_seo_autofill()
 RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public'
AS $function$
DECLARE v_category_name TEXT;
BEGIN
  -- GUARD DE PERFORMANCE (M3 2026-06-23)
  IF TG_OP='UPDATE' AND OLD.name IS NOT DISTINCT FROM NEW.name
     AND NEW.slug IS NOT NULL AND NEW.meta_title IS NOT NULL AND NEW.meta_description IS NOT NULL
  THEN
    IF NEW.og_image_url IS NULL AND NEW.primary_image_url IS NOT NULL THEN
      NEW.og_image_url := NEW.primary_image_url;
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;
  IF NEW.main_category_id IS NOT NULL THEN SELECT name INTO v_category_name FROM categories WHERE id=NEW.main_category_id;
  ELSIF NEW.category_id IS NOT NULL THEN SELECT name INTO v_category_name FROM categories WHERE id=NEW.category_id;
  END IF;
  IF (NEW.slug IS NULL OR LENGTH(TRIM(COALESCE(NEW.slug,'')))=0) AND NEW.name IS NOT NULL THEN
    NEW.slug := generate_product_slug(NEW.name, NEW.id);
  END IF;
  IF (NEW.meta_title IS NULL OR LENGTH(TRIM(COALESCE(NEW.meta_title,'')))=0) AND NEW.name IS NOT NULL THEN
    NEW.meta_title := generate_product_meta_title(NEW.name, v_category_name);
  END IF;
  IF (NEW.meta_description IS NULL OR LENGTH(TRIM(COALESCE(NEW.meta_description,'')))=0) AND NEW.name IS NOT NULL THEN
    NEW.meta_description := generate_product_meta_description(NEW.name,NEW.short_description,NEW.description,COALESCE(NEW.allows_personalization,false));
  END IF;
  IF (NEW.meta_keywords IS NULL OR COALESCE(array_length(NEW.meta_keywords,1),0)=0) AND NEW.name IS NOT NULL THEN
    NEW.meta_keywords := extract_keywords(COALESCE(NEW.name,'')||' '||COALESCE(NEW.short_description,'')||' '||COALESCE(v_category_name,'')||' '||COALESCE(NEW.brand,'')||' brinde promocional brinde corporativo brinde personalizado',15);
  END IF;
  IF NEW.og_title IS NULL AND NEW.meta_title IS NOT NULL THEN NEW.og_title := NEW.meta_title; END IF;
  IF NEW.og_description IS NULL AND NEW.meta_description IS NOT NULL THEN NEW.og_description := NEW.meta_description; END IF;
  IF NEW.og_image_url IS NULL AND NEW.primary_image_url IS NOT NULL THEN NEW.og_image_url := NEW.primary_image_url; END IF;
  IF NEW.canonical_url IS NULL AND NEW.slug IS NOT NULL THEN NEW.canonical_url := '/produto/' || NEW.slug; END IF;
  IF TG_OP='UPDATE' THEN NEW.updated_at := now(); END IF;
  RETURN NEW;
END;
$function$;

-- <<< END 20260623000003_products_name_m3_seo_guard.sql <<<

-- >>> BEGIN 20260623000004_products_name_m4_slug_optimize.sql >>>
-- M4: Otimizar generate_product_slug - eliminar loop N+1
-- Antes: ate 18527 queries. Agora: maximo 2 queries via UUID hex suffix.
CREATE OR REPLACE FUNCTION public.generate_product_slug(p_name text, p_product_id uuid DEFAULT NULL)
 RETURNS text LANGUAGE plpgsql SET search_path TO 'public'
AS $function$
DECLARE
  v_base_slug  text;
  v_final_slug text;
  v_hex_suffix text;
  v_counter    integer := 0;
BEGIN
  IF p_name IS NULL OR LENGTH(TRIM(p_name))=0 THEN RETURN NULL; END IF;
  v_base_slug  := slugify(p_name);
  v_final_slug := v_base_slug;
  IF NOT EXISTS(SELECT 1 FROM products WHERE slug=v_final_slug AND is_deleted=false AND (p_product_id IS NULL OR id<>p_product_id)) THEN
    RETURN v_final_slug;
  END IF;
  IF p_product_id IS NOT NULL THEN
    v_hex_suffix := LEFT(REPLACE(p_product_id::text,'-',''),8);
    v_final_slug := v_base_slug||'-'||v_hex_suffix;
    IF NOT EXISTS(SELECT 1 FROM products WHERE slug=v_final_slug AND is_deleted=false AND id<>p_product_id) THEN
      RETURN v_final_slug;
    END IF;
    RETURN v_base_slug||'-'||REPLACE(p_product_id::text,'-','');
  END IF;
  WHILE v_counter<999 LOOP
    v_counter    := v_counter+1;
    v_final_slug := v_base_slug||'-'||v_counter;
    IF NOT EXISTS(SELECT 1 FROM products WHERE slug=v_final_slug AND is_deleted=false AND (p_product_id IS NULL OR id<>p_product_id)) THEN
      RETURN v_final_slug;
    END IF;
  END LOOP;
  RETURN v_base_slug||'-'||EXTRACT(EPOCH FROM NOW())::bigint;
END;
$function$;

-- <<< END 20260623000004_products_name_m4_slug_optimize.sql <<<

-- >>> BEGIN 20260623000005_products_name_m5_quality_score.sql >>>
-- M5: fn_product_name_quality_score - score 0-100 de qualidade de products.name
CREATE OR REPLACE FUNCTION public.fn_product_name_quality_score(p_name text)
 RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path TO 'public'
AS $function$
DECLARE v_score integer:=100; v_issues text[]:='{}';
BEGIN
  IF p_name IS NULL OR length(TRIM(p_name))=0 THEN
    RETURN jsonb_build_object('score',0,'issues',ARRAY['name_null_or_empty'],'grade','F'); END IF;
  IF p_name LIKE '%  %' THEN v_score:=v_score-25; v_issues:=array_append(v_issues,'double_spaces'); END IF;
  IF p_name<>TRIM(p_name) THEN v_score:=v_score-15; v_issues:=array_append(v_issues,'leading_trailing_spaces'); END IF;
  IF p_name~E'[\\t\\n\\r]' THEN v_score:=v_score-25; v_issues:=array_append(v_issues,'contains_tabs_newlines'); END IF;
  IF length(p_name)>150 THEN v_score:=v_score-20; v_issues:=array_append(v_issues,'too_long_over_150');
  ELSIF length(p_name)>100 THEN v_score:=v_score-10; v_issues:=array_append(v_issues,'long_100_to_150'); END IF;
  IF length(TRIM(p_name))<8 THEN v_score:=v_score-15; v_issues:=array_append(v_issues,'too_short_under_8'); END IF;
  IF p_name=UPPER(p_name) AND p_name~'[A-Za-z]{3,}' THEN v_score:=v_score-15; v_issues:=array_append(v_issues,'all_uppercase_variant_style'); END IF;
  IF p_name!~'[A-Za-z0-9]' THEN v_score:=v_score-10; v_issues:=array_append(v_issues,'no_alphanumeric'); END IF;
  IF p_name~U&'[\\2018\\2019]' THEN v_score:=v_score-5; v_issues:=array_append(v_issues,'curly_quotes'); END IF;
  v_score:=GREATEST(0,LEAST(100,v_score));
  RETURN jsonb_build_object('score',v_score,'issues',v_issues,'length',length(p_name),'grade',
    CASE WHEN v_score>=90 THEN 'A' WHEN v_score>=75 THEN 'B' WHEN v_score>=60 THEN 'C' WHEN v_score>=40 THEN 'D' ELSE 'F' END);
END;
$function$;
COMMENT ON FUNCTION public.fn_product_name_quality_score(text) IS 'Score 0-100 de qualidade de products.name. IMMUTABLE. NAO usar para product_variants.name.';

-- <<< END 20260623000005_products_name_m5_quality_score.sql <<<

-- >>> BEGIN 20260623000006_products_name_m6_audit_view.sql >>>
-- M6: v_products_name_audit - view de auditoria de qualidade de products.name
CREATE OR REPLACE VIEW public.v_products_name_audit AS
WITH quality AS (
  SELECT p.id AS product_id, p.sku, p.name, s.name AS supplier_name, p.is_active, p.slug,
    length(p.name) AS name_len, 'name'=ANY(COALESCE(p.locked_fields,'{}')) AS name_is_locked,
    fn_product_name_quality_score(p.name) AS quality_json
  FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
)
SELECT product_id, sku, name, supplier_name, is_active, slug, name_len, name_is_locked,
  (quality_json->>'score')::integer AS quality_score, quality_json->>'grade' AS quality_grade,
  quality_json->'issues' AS issues,
  (quality_json->'issues')?'double_spaces' AS has_double_spaces,
  (quality_json->'issues')?'leading_trailing_spaces' AS has_leading_trailing_spaces,
  (quality_json->'issues')?'contains_tabs_newlines' AS has_tabs_newlines,
  (quality_json->'issues')?'too_long_over_150' AS is_too_long,
  (quality_json->'issues')?'long_100_to_150' AS is_moderately_long,
  (quality_json->'issues')?'too_short_under_8' AS is_too_short,
  (quality_json->'issues')?'all_uppercase_variant_style' AS is_all_uppercase,
  (quality_json->'issues')?'no_alphanumeric' AS has_no_alphanumeric,
  (quality_json->'issues')?'curly_quotes' AS has_curly_quotes,
  (SELECT COUNT(*) FROM products p2 WHERE p2.name=quality.name AND p2.id<>quality.product_id) AS duplicate_name_count
FROM quality WHERE (quality_json->'issues')<>'[]'::jsonb
ORDER BY (quality_json->>'score')::integer ASC, is_active DESC, name_len DESC;
COMMENT ON VIEW public.v_products_name_audit IS 'Auditoria qualidade products.name. Criado M6 2026-06-23.';

-- <<< END 20260623000006_products_name_m6_audit_view.sql <<<

-- >>> BEGIN 20260623000007_products_name_m7_curly_quotes.sql >>>
-- M7: Substituir curly quotes (U+2019/U+2018) por apostrofe ASCII em 4 produtos XBZ
-- Executado com app.write_source=pipeline para nao bloquear name em locked_fields
SELECT set_config('app.write_source','pipeline',true);
UPDATE public.products
SET name = REPLACE(REPLACE(name, U&'\2019', ''''), U&'\2018', '''')
WHERE name ~ U&'[\2018\2019]';
SELECT set_config('app.write_source','ui',true);

-- <<< END 20260623000007_products_name_m7_curly_quotes.sql <<<

