-- >>> BEGIN 20260623111612_9ccac68e-356c-4f1c-96f5-a4399f651f1e.sql >>>
CREATE OR REPLACE FUNCTION public.enforce_seller_cart_limit()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(415264, hashtext(NEW.seller_id::text));
  IF (SELECT count(*) FROM public.seller_carts WHERE seller_id = NEW.seller_id) >= 10 THEN
    RAISE EXCEPTION 'Limite de 10 carrinhos por vendedor atingido' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$;
-- <<< END 20260623111612_9ccac68e-356c-4f1c-96f5-a4399f651f1e.sql <<<

-- >>> BEGIN 20260623120000_fix_get_top_collected_products_security_definer.sql >>>
-- =============================================================================
-- FIX: get_top_collected_products → SECURITY DEFINER
-- =============================================================================
-- ROOT CAUSE: função era SECURITY INVOKER e acessa archive.collection_items.
-- authenticated NÃO tem USAGE no schema archive → PostgreSQL retorna
-- "permission denied for schema archive" → PostgREST traduz para HTTP 403.
-- Mesmo bug que afetou get_collections_weekly_count (fix 2026-06-21).
--
-- FIX: SECURITY DEFINER + SET search_path = public, archive
-- A função executa com permissões do owner (postgres), que tem acesso total
-- ao schema archive. RLS de archive.collection_items ainda se aplica.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.get_top_collected_products(
  _days integer DEFAULT 7,
  _limit integer DEFAULT 6
)
RETURNS TABLE(product_id text, col_count bigint)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, archive
AS $$
  SELECT ci.product_id, COUNT(*)::bigint AS col_count
  FROM archive.collection_items ci
  WHERE ci.created_at >= (now() - make_interval(days => GREATEST(_days, 1)))
  GROUP BY ci.product_id
  ORDER BY col_count DESC, MAX(ci.created_at) DESC
  LIMIT GREATEST(_limit, 1);
$$;

-- Re-confirm grants (idempotente)
GRANT EXECUTE ON FUNCTION public.get_top_collected_products(integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_top_collected_products(integer, integer) TO anon;
GRANT EXECUTE ON FUNCTION public.get_top_collected_products(integer, integer) TO service_role;

NOTIFY pgrst, 'reload schema';

-- <<< END 20260623120000_fix_get_top_collected_products_security_definer.sql <<<

-- >>> BEGIN 20260623120000_harden_get_favorite_list_counts_revoke_anon.sql >>>
-- Hardening: garante anon SEM EXECUTE em get_favorite_list_counts de forma deterministica.
-- Contexto: a funcao consta na whitelist de fn_auto_revoke_secdef_public_execute, entao aquele
-- event trigger NAO a revoga. Um (re)CREATE pela migration canonica 20260622200000 (DROP+CREATE+GRANT,
-- sem REVOKE) pode deixar anon=EXECUTE via default privileges do schema public. Esta migration tem
-- timestamp superior e revoga explicitamente, garantindo least-privilege como ULTIMA palavra em
-- qualquer `supabase db push`. Idempotente + guard de existencia (segura isolada).
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'get_favorite_list_counts'
      AND pg_get_function_identity_arguments(p.oid) = '_user_id uuid'
  ) THEN
    REVOKE EXECUTE ON FUNCTION public.get_favorite_list_counts(uuid) FROM PUBLIC;
    REVOKE EXECUTE ON FUNCTION public.get_favorite_list_counts(uuid) FROM anon;
    GRANT  EXECUTE ON FUNCTION public.get_favorite_list_counts(uuid) TO authenticated;
  END IF;
END $$;
NOTIFY pgrst, 'reload schema';

-- <<< END 20260623120000_harden_get_favorite_list_counts_revoke_anon.sql <<<

-- >>> BEGIN 20260623121000_fix_archive_access_security_definer_batch.sql >>>
-- =============================================================================
-- FIX: 3 funções SECURITY INVOKER que acessam schema archive → SECURITY DEFINER
-- =============================================================================
-- PADRÃO: authenticated não tem USAGE no schema archive.
-- Funções SECURITY INVOKER que acessam archive falham com permission denied.
-- FIX: SECURITY DEFINER + SET search_path = public, archive.
-- =============================================================================

-- 1. registrar_entrada_estoque (escreve em archive.stock_movements)
CREATE OR REPLACE FUNCTION public.registrar_entrada_estoque(
  p_variant_sku character varying,
  p_quantity integer,
  p_unit_cost numeric DEFAULT NULL,
  p_supplier_name character varying DEFAULT NULL,
  p_document_number character varying DEFAULT NULL,
  p_notes text DEFAULT NULL,
  p_user_id uuid DEFAULT NULL
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, archive
AS $function$
DECLARE
    v_variant_id UUID;
    v_stock_before INTEGER;
    v_stock_after INTEGER;
    v_movement_id UUID;
BEGIN
    IF p_quantity <= 0 THEN
        RETURN json_build_object('success', false, 'error', 'Quantidade deve ser maior que zero');
    END IF;
    SELECT id INTO v_variant_id FROM product_variants WHERE sku = p_variant_sku;
    IF v_variant_id IS NULL THEN
        RETURN json_build_object('success', false, 'error', format('Variante não encontrada: %s', p_variant_sku));
    END IF;
    SELECT COALESCE(stock_quantity, 0) INTO v_stock_before FROM product_variants WHERE id = v_variant_id;
    v_stock_after := v_stock_before + p_quantity;
    INSERT INTO archive.stock_movements (id, variant_id, movement_type, quantity, stock_before, stock_after, unit_cost, reference_type, reference_number, notes, created_by, created_at)
    VALUES (gen_random_uuid(), v_variant_id, 'ENTRADA', p_quantity, v_stock_before, v_stock_after, p_unit_cost,
            CASE WHEN p_document_number IS NOT NULL THEN 'NF' ELSE NULL END, p_document_number,
            COALESCE(p_notes, format('Entrada de %s unidades - Fornecedor: %s', p_quantity, COALESCE(p_supplier_name, 'N/A'))),
            p_user_id, NOW())
    RETURNING id INTO v_movement_id;
    UPDATE product_variants SET stock_quantity = v_stock_after, updated_at = NOW() WHERE id = v_variant_id;
    RETURN json_build_object('success', true, 'movement_id', v_movement_id, 'variant_id', v_variant_id, 'sku', p_variant_sku,
                             'quantity_added', p_quantity, 'stock_before', v_stock_before, 'stock_after', v_stock_after, 'movement_type', 'ENTRADA');
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$function$;

-- 2. registrar_saida_estoque (escreve em archive.stock_movements)
CREATE OR REPLACE FUNCTION public.registrar_saida_estoque(
  p_variant_sku character varying,
  p_quantity integer,
  p_movement_type character varying DEFAULT 'VENDA',
  p_document_number character varying DEFAULT NULL,
  p_notes text DEFAULT NULL,
  p_user_id uuid DEFAULT NULL,
  p_allow_negative boolean DEFAULT false
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, archive
AS $function$
DECLARE
    v_variant_id UUID;
    v_stock_before INTEGER;
    v_stock_after INTEGER;
    v_movement_id UUID;
BEGIN
    IF p_quantity <= 0 THEN
        RETURN json_build_object('success', false, 'error', 'Quantidade deve ser maior que zero');
    END IF;
    IF p_movement_type NOT IN ('VENDA', 'RESERVA', 'AJUSTE', 'PERDA', 'DEVOLUCAO_FORNECEDOR') THEN
        RETURN json_build_object('success', false, 'error', format('Tipo de movimento inválido: %s', p_movement_type));
    END IF;
    SELECT id INTO v_variant_id FROM product_variants WHERE sku = p_variant_sku;
    IF v_variant_id IS NULL THEN
        RETURN json_build_object('success', false, 'error', format('Variante não encontrada: %s', p_variant_sku));
    END IF;
    SELECT COALESCE(stock_quantity, 0) INTO v_stock_before FROM product_variants WHERE id = v_variant_id;
    IF v_stock_before < p_quantity AND NOT p_allow_negative THEN
        RETURN json_build_object('success', false, 'error', 'Estoque insuficiente', 'stock_available', v_stock_before, 'quantity_requested', p_quantity);
    END IF;
    v_stock_after := v_stock_before - p_quantity;
    INSERT INTO archive.stock_movements (id, variant_id, movement_type, quantity, stock_before, stock_after, reference_type, reference_number, notes, created_by, created_at)
    VALUES (gen_random_uuid(), v_variant_id, 'SAIDA', -p_quantity, v_stock_before, v_stock_after, p_movement_type, p_document_number,
            COALESCE(p_notes, format('Saída de %s unidades - Tipo: %s', p_quantity, p_movement_type)), p_user_id, NOW())
    RETURNING id INTO v_movement_id;
    UPDATE product_variants SET stock_quantity = v_stock_after, updated_at = NOW() WHERE id = v_variant_id;
    RETURN json_build_object('success', true, 'movement_id', v_movement_id, 'variant_id', v_variant_id, 'sku', p_variant_sku,
                             'quantity_removed', p_quantity, 'stock_before', v_stock_before, 'stock_after', v_stock_after, 'movement_type', p_movement_type);
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$function$;

-- 3. restore_collection_item_from_trash (escreve em archive.collection_items)
CREATE OR REPLACE FUNCTION public.restore_collection_item_from_trash(_item_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, archive
AS $function$
DECLARE v_row record;
BEGIN
  SELECT * INTO v_row FROM public.collection_items_trash WHERE id = _item_id AND user_id = auth.uid();
  IF NOT FOUND THEN RETURN false; END IF;

  INSERT INTO archive.collection_items (id, collection_id, product_id, color_name, color_hex, thumbnail_url, notes, price_at_save, sort_order)
  VALUES (
    COALESCE(v_row.original_id, gen_random_uuid()),
    v_row.collection_id,
    v_row.product_id,
    v_row.color_name,
    v_row.color_hex,
    v_row.thumbnail_url,
    v_row.notes,
    v_row.price_at_save,
    v_row.sort_order
  );

  DELETE FROM public.collection_items_trash WHERE id = _item_id;
  RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$;

NOTIFY pgrst, 'reload schema';

-- <<< END 20260623121000_fix_archive_access_security_definer_batch.sql <<<

-- >>> BEGIN 20260623122000_fix_security_definer_missing_search_path.sql >>>
-- =============================================================================
-- FIX: 3 funções SECURITY DEFINER sem SET search_path → adicionar search_path
-- =============================================================================
-- VULNERABILIDADE: SECURITY DEFINER sem search_path explícito permite
-- schema injection. FIX: adicionar SET search_path = public.
-- Funções afetadas: fn_quotes_validate_discount, fn_rebuild_color_swatches,
-- notify_quote_status_change (todas acessam apenas public).
-- =============================================================================

CREATE OR REPLACE FUNCTION public.fn_quotes_validate_discount()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  _max_allowed numeric;
  _real_discount_pct numeric;
  _has_valid_approval boolean;
  _current_hash text;
  _seller_id uuid;
  _msg text;
BEGIN
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  _seller_id := COALESCE(NEW.seller_id, NEW.created_by);

  IF _seller_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF public.is_coord_or_above(_seller_id) THEN
    RETURN NEW;
  END IF;

  _real_discount_pct := COALESCE(NEW.real_discount_percent, 0);

  IF _real_discount_pct <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT max_discount_percent INTO _max_allowed
  FROM public.seller_discount_limits
  WHERE user_id = _seller_id;

  IF _max_allowed IS NULL THEN
    RAISE EXCEPTION 'Vendedor sem limite de desconto cadastrado. Solicite ao admin que configure seu limite antes de salvar orcamentos.'
      USING ERRCODE = '23514';
  END IF;

  IF _real_discount_pct <= _max_allowed THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF COALESCE(NEW.status, 'draft') = 'pending_approval' THEN
      RETURN NEW;
    END IF;
    _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
            ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
            ' por cento. Para solicitar aprovacao, use o botao "Solicitar aprovacao ao coordenador"' ||
            ' que cria o orcamento em status pendente.';
    RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
  END IF;

  _current_hash := public.compute_quote_snapshot_hash(NEW.id);

  SELECT EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id
      AND status = 'approved'
      AND (valid_until IS NULL OR valid_until > now())
      AND requested_discount_percent >= _real_discount_pct
      AND quote_snapshot_hash = _current_hash
  ) INTO _has_valid_approval;

  IF _has_valid_approval THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id AND status = 'approved'
      AND (
        (valid_until IS NOT NULL AND valid_until <= now())
        OR quote_snapshot_hash <> _current_hash
      )
  ) THEN
    RAISE EXCEPTION 'Aprovacao anterior nao vale mais (orcamento foi alterado ou aprovacao expirou). Solicite nova aprovacao ao coordenador.'
      USING ERRCODE = '23514';
  END IF;

  IF COALESCE(NEW.status, 'draft') = 'pending_approval' THEN
    RETURN NEW;
  END IF;

  _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
          ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
          ' por cento. Solicite aprovacao ao coordenador antes de salvar.';
  RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_rebuild_color_swatches(p_product_id uuid)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $function$
  SELECT COALESCE(
    jsonb_agg(
      swatch
      ORDER BY (swatch->>'stock_quantity')::int DESC, swatch->>'color_name' ASC
    ),
    '[]'::jsonb
  )
  FROM (
    SELECT DISTINCT ON (agg.color_id)
      jsonb_build_object(
        'variant_id',     agg.lead_variant_id,
        'sku',            agg.lead_sku,
        'color_id',       agg.color_id,
        'color_name',     agg.color_name,
        'color_hex',      agg.color_hex,
        'stock_quantity', agg.total_stock,
        'is_in_stock',    agg.total_stock > 0,
        'image_url',      COALESCE(
          (SELECT pi.url_cdn FROM product_images pi
           WHERE pi.product_id=p_product_id AND pi.variant_id=agg.lead_variant_id
             AND pi.is_active=true AND pi.image_type IN ('main','gallery','product')
           ORDER BY pi.is_primary DESC, pi.display_order ASC NULLS LAST LIMIT 1),
          (SELECT pi.url_cdn FROM product_images pi
           WHERE pi.product_id=p_product_id AND pi.color_id=agg.color_id
             AND pi.variant_id IS NULL AND pi.is_active=true
             AND pi.image_type IN ('main','gallery','product')
           ORDER BY pi.is_primary DESC, pi.display_order ASC NULLS LAST LIMIT 1),
          (SELECT pi.url_cdn FROM product_images pi
           WHERE pi.product_id=p_product_id AND pi.color_id=agg.color_id
             AND pi.variant_id IS NOT NULL AND pi.is_active=true
             AND pi.image_type IN ('main','gallery','product')
           ORDER BY pi.is_primary DESC, pi.display_order ASC NULLS LAST LIMIT 1),
          agg.lead_images_first,
          (SELECT p.primary_image_url FROM products p WHERE p.id = p_product_id)
        )
      ) AS swatch
    FROM (
      SELECT pv2.color_id,
        COALESCE(pv2.color_name, cv.name) AS color_name,
        COALESCE(pv2.color_hex, cv.hex_code) AS color_hex,
        SUM(COALESCE(pv2.stock_quantity, 0)) AS total_stock,
        (ARRAY_AGG(pv2.id   ORDER BY COALESCE(pv2.stock_quantity,0) DESC, pv2.sku ASC))[1] AS lead_variant_id,
        (ARRAY_AGG(pv2.sku  ORDER BY COALESCE(pv2.stock_quantity,0) DESC, pv2.sku ASC))[1] AS lead_sku,
        (ARRAY_AGG(pv2.images->>0 ORDER BY COALESCE(pv2.stock_quantity,0) DESC, pv2.sku ASC))[1] AS lead_images_first
      FROM product_variants pv2
      LEFT JOIN color_variations cv ON cv.id = pv2.color_id
      WHERE pv2.product_id = p_product_id AND pv2.is_active = true AND pv2.color_id IS NOT NULL
      GROUP BY pv2.color_id, COALESCE(pv2.color_name, cv.name), COALESCE(pv2.color_hex, cv.hex_code)
    ) agg
    ORDER BY agg.color_id, agg.total_stock DESC
  ) sub;
$function$;

CREATE OR REPLACE FUNCTION public.notify_quote_status_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  notif_title TEXT;
  notif_message TEXT;
  notif_type TEXT;
  notif_category TEXT := 'quotes';
  notif_url TEXT := '/orcamentos';
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;

  CASE NEW.status
    WHEN 'approved' THEN
      notif_title   := '✅ Orçamento aprovado!';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' foi aprovado!';
      notif_type    := 'success';
    WHEN 'rejected' THEN
      notif_title   := '❌ Orçamento recusado';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' foi recusado.';
      notif_type    := 'warning';
    WHEN 'sent' THEN
      notif_title   := '📤 Orçamento enviado';
      notif_message := 'O orçamento ' || NEW.quote_number || ' foi marcado como enviado.';
      notif_type    := 'info';
    WHEN 'expired' THEN
      notif_title   := '⏰ Orçamento expirado';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' expirou.';
      notif_type    := 'warning';
    WHEN 'pending_approval' THEN
      notif_title   := '⏳ Orçamento aguardando aprovação';
      notif_message := 'O orçamento ' || NEW.quote_number || ' foi submetido para aprovação de desconto.';
      notif_type    := 'info';
    WHEN 'converted' THEN
      notif_title   := '🎉 Orçamento convertido em pedido!';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' foi convertido em pedido.';
      notif_type    := 'success';
      notif_url     := '/pedidos';
    WHEN 'cancelled' THEN
      notif_title   := '🚫 Orçamento cancelado';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' foi cancelado.';
      notif_type    := 'warning';
    ELSE
      RETURN NEW;
  END CASE;

  IF NEW.seller_id IS NOT NULL THEN
    INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url)
    VALUES (NEW.seller_id, notif_title, notif_message, notif_type, notif_category, notif_url);
  END IF;

  RETURN NEW;
END;
$function$;

NOTIFY pgrst, 'reload schema';

-- <<< END 20260623122000_fix_security_definer_missing_search_path.sql <<<

