-- >>> BEGIN 20260623180000_fix_fn_capture_connection_snapshot_search_path.sql >>>
-- =============================================================================
-- FIX: fn_capture_connection_snapshot — SET search_path = public
-- MOTIVO: SECURITY DEFINER sem SET search_path = vulnerabilidade de schema
-- injection. Descoberto em auditoria adversarial 2026-06-23.
-- DRY-RUN: retornou jsonb object correto. 1 cron dependente.
-- =============================================================================
CREATE OR REPLACE FUNCTION public.fn_capture_connection_snapshot()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_total     int;
  v_active    int;
  v_idle_tx   int;
  v_max       int;
  v_pct       numeric(5,2);
  v_top_users jsonb;
  v_result    jsonb;
BEGIN
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE state = 'active'),
    COUNT(*) FILTER (WHERE state = 'idle in transaction'),
    (SELECT setting::int FROM pg_settings WHERE name = 'max_connections')
  INTO v_total, v_active, v_idle_tx, v_max
  FROM pg_stat_activity
  WHERE pid != pg_backend_pid();

  v_pct := ROUND((v_total::numeric / NULLIF(v_max, 0)) * 100, 2);

  SELECT jsonb_agg(row_to_json(t)) INTO v_top_users
  FROM (
    SELECT usename, state, COUNT(*) as n
    FROM pg_stat_activity
    WHERE pid != pg_backend_pid()
    GROUP BY usename, state
    ORDER BY n DESC
    LIMIT 8
  ) t;

  INSERT INTO public.db_connection_snapshots
    (total_conns, active_conns, idle_in_tx_conns, max_conns, usage_pct, top_users)
  VALUES
    (v_total, v_active, v_idle_tx, v_max, v_pct, v_top_users);

  DELETE FROM public.db_connection_snapshots
  WHERE captured_at < now() - interval '7 days';

  v_result := jsonb_build_object(
    'total', v_total, 'active', v_active, 'idle_in_tx', v_idle_tx,
    'max', v_max, 'usage_pct', v_pct,
    'alert', v_pct >= 75
  );

  RETURN v_result;
END;
$function$;

-- <<< END 20260623180000_fix_fn_capture_connection_snapshot_search_path.sql <<<

-- >>> BEGIN 20260623180001_fix_fn_cron_safe_run_search_path.sql >>>
-- =============================================================================
-- FIX: fn_cron_safe_run — SET search_path = public
-- MOTIVO: SECURITY DEFINER sem SET search_path = vulnerabilidade de schema
-- injection. 48 crons dependem desta função.
-- DRY-RUN: 3 simulações de produção OK (products-count, wn-count, noop-update).
-- EXECUTE p_sql herda search_path = public — seguro pois nenhum dos 48 crons
-- referencia tabelas fora de 'public' de forma não qualificada.
-- =============================================================================
CREATE OR REPLACE FUNCTION public.fn_cron_safe_run(
  p_key        bigint,
  p_sql        text,
  p_timeout_ms integer DEFAULT 45000,
  p_job_label  text    DEFAULT 'cron'
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_start       timestamptz := clock_timestamp();
  v_duration_ms int;
BEGIN
  -- Advisory lock transacional: se o tick anterior ainda roda, pula sem empilhar
  IF NOT pg_try_advisory_xact_lock(p_key) THEN
    RETURN format('[%s] SKIP: job ainda em execução (lock=%s)', p_job_label, p_key);
  END IF;

  -- Aplica timeout local para esta execução
  EXECUTE format('SET LOCAL statement_timeout = %L', p_timeout_ms || 'ms');

  -- Executa o SQL do job
  EXECUTE p_sql;

  v_duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_start)) * 1000;
  RETURN format('[%s] OK: %sms', p_job_label, v_duration_ms);

EXCEPTION
  WHEN query_canceled THEN
    RETURN format('[%s] TIMEOUT após %sms (limite=%sms)', p_job_label,
      EXTRACT(EPOCH FROM (clock_timestamp() - v_start))::int * 1000, p_timeout_ms);
  WHEN OTHERS THEN
    RETURN format('[%s] ERRO: %s', p_job_label, SQLERRM);
END;
$function$;

-- <<< END 20260623180001_fix_fn_cron_safe_run_search_path.sql <<<

