-- >>> BEGIN 20260626000001_fix_discount_approval_audit_actor_id_fk.sql >>>
-- =============================================================
-- MIGRATION: fix_discount_approval_audit_actor_id_fk
-- Data: 2026-06-26
-- Autor: Claude (Dev Senior)
--
-- BUG REPORTADO:
--   GET /rest/v1/discount_approval_audit?select=...actor:actor_id(full_name,email)...
--   retornava HTTP 400 Bad Request em loop infinito no frontend.
--
-- ROOT CAUSE:
--   O componente DiscountApprovalAuditTrail.tsx usa o join embedded
--   PostgREST "actor:actor_id(full_name,email)" para buscar nome/email
--   do ator de cada evento de auditoria.
--
--   O PostgREST resolve joins embedded EXCLUSIVAMENTE via Foreign Keys.
--   A coluna actor_id em discount_approval_audit NÃO tinha nenhuma FK
--   declarada → PostgREST não conseguia inferir a tabela-alvo do join
--   → retornava HTTP 400 "Bad Request" (query inválida/irresolvível).
--
-- EVIDÊNCIA DO TRIGGER:
--   fn_audit_discount_approval popula actor_id com:
--     - NEW.seller_id (INSERT) → FK de discount_approval_requests → profiles(user_id)
--     - NEW.admin_id  (UPDATE) → FK de discount_approval_requests → profiles(user_id)
--   Portanto actor_id sempre armazena um valor de profiles.user_id (= auth.users.id).
--
-- FIX APLICADO:
--   1. FK: discount_approval_audit.actor_id → profiles(user_id) ON DELETE SET NULL
--      Permite ao PostgREST resolver "actor:actor_id(full_name,email)"
--      fazendo JOIN em profiles WHERE profiles.user_id = actor_id.
--
--   2. Índice parcial em actor_id (WHERE actor_id IS NOT NULL):
--      Evita Sequential Scan em discount_approval_audit durante
--      operações de CASCADE em profiles.
--
-- ANTI-REGRESSION: Lovable bot must not remove this FK or index.
-- fix_version: dar_audit_actor_fk_v1
-- =============================================================

-- 1. FK: resolve o join PostgREST actor:actor_id(full_name,email)
ALTER TABLE public.discount_approval_audit
  ADD CONSTRAINT discount_approval_audit_actor_id_fkey
  FOREIGN KEY (actor_id)
  REFERENCES public.profiles(user_id)
  ON DELETE SET NULL;

-- 2. Índice suporte: evita seq scan em cascatas de UPDATE/DELETE em profiles
CREATE INDEX IF NOT EXISTS idx_discount_approval_audit_actor_id
  ON public.discount_approval_audit(actor_id)
  WHERE actor_id IS NOT NULL;

-- 3. Reload schema cache do PostgREST para reconhecer a nova FK imediatamente
NOTIFY pgrst, 'reload schema';

-- <<< END 20260626000001_fix_discount_approval_audit_actor_id_fk.sql <<<

-- >>> BEGIN 20260626120000_add_ordem_exibicao_tabela_preco_gravacao_oficial.sql >>>
-- 20260626120000_add_ordem_exibicao_tabela_preco_gravacao_oficial.sql
--
-- Fix: PostgREST 400 (Bad Request) on
--   GET /rest/v1/tabela_preco_gravacao_oficial?select=*&order=ordem_exibicao.asc&offset=0&limit=200
--
-- ROOT CAUSE
--   The frontend reads this table through the bridge alias 'tecnica_gravacao'
--   (src/lib/db/postgrest.ts -> BRIDGE_ALIASES: tecnica_gravacao -> tabela_preco_gravacao_oficial)
--   in two call sites that ORDER BY ordem_exibicao:
--     - src/hooks/tecnicas/useTecnicasList.ts::fetchTecnicasExterno   (orderBy ordem_exibicao, limit 200)  <- request in the console log
--     - src/lib/external-db/techniques.ts::fetchPromobrindTechniques  (orderBy ordem_exibicao, limit 100)
--   ordem_exibicao existed ONLY on the sibling catalog table tecnicas_gravacao, so Postgres raised
--   42703 (undefined_column) and PostgREST returned HTTP 400.
--
-- FIX
--   Add ordem_exibicao to tabela_preco_gravacao_oficial, mirroring tecnicas_gravacao.ordem_exibicao
--   (integer DEFAULT 99). Backfill a deterministic display order by codigo_tabela so ORDER BY is
--   stable across paginated requests. Purely additive; regression-proof against the recurring
--   reintroduction of .order('ordem_exibicao') by the Lovable bot.
--
-- Idempotent (guarded by pg_attribute existence check). Applied to production 2026-06-26.

DO $mig$
DECLARE
  v_exists boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM pg_attribute
    WHERE attrelid = 'public.tabela_preco_gravacao_oficial'::regclass
      AND attname = 'ordem_exibicao'
      AND NOT attisdropped
  ) INTO v_exists;

  IF NOT v_exists THEN
    ALTER TABLE public.tabela_preco_gravacao_oficial
      ADD COLUMN ordem_exibicao integer NOT NULL DEFAULT 99;

    WITH ranked AS (
      SELECT id, row_number() OVER (ORDER BY codigo_tabela, id) AS rn
      FROM public.tabela_preco_gravacao_oficial
    )
    UPDATE public.tabela_preco_gravacao_oficial t
    SET ordem_exibicao = r.rn
    FROM ranked r
    WHERE r.id = t.id;

    COMMENT ON COLUMN public.tabela_preco_gravacao_oficial.ordem_exibicao IS
      'ANTI-REGRESSION (fix 2026-06-26): display order for the technique-list UI. Frontend reads this table via bridge alias tecnica_gravacao (dbInvoke BRIDGE_ALIASES) and ORDERs BY ordem_exibicao; column previously existed only on tecnicas_gravacao, causing PostgREST 400 (42703). Mirrors tecnicas_gravacao.ordem_exibicao (integer default 99). DO NOT DROP.';
  END IF;
END
$mig$;

-- Critical: refresh PostgREST schema cache so the new column is queryable immediately.
NOTIFY pgrst, 'reload schema';

-- <<< END 20260626120000_add_ordem_exibicao_tabela_preco_gravacao_oficial.sql <<<

-- >>> BEGIN 20260626123517_enforce_dar_valid_until_future_on_approval.sql >>>
-- Melhoria M5: bloqueia aprovar com valid_until no passado, SOMENTE na transição -> approved.
-- Decisão de engenharia (provada via dry-run com ~110 cenários): NÃO usar CHECK persistente,
-- pois aprovações vencem naturalmente (fn_quotes_validate_discount já ignora valid_until <= now());
-- um CHECK persistente quebraria o vencimento natural de uma aprovação válida.
CREATE OR REPLACE FUNCTION public.fn_dar_check_valid_until_future()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $fn$
BEGIN
  -- fix_version=20260626_m5 | ANTI-REGRESSAO: manter como trigger de TRANSICAO, jamais CHECK persistente.
  IF NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved' THEN
    IF NEW.valid_until IS NOT NULL AND NEW.valid_until::date < CURRENT_DATE THEN
      RAISE EXCEPTION 'valid_until nao pode estar no passado ao aprovar (recebido: %, hoje: %)', NEW.valid_until, CURRENT_DATE
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$fn$;

DROP TRIGGER IF EXISTS trg_dar_check_valid_until_future ON public.discount_approval_requests;
CREATE TRIGGER trg_dar_check_valid_until_future
  BEFORE UPDATE ON public.discount_approval_requests
  FOR EACH ROW EXECUTE FUNCTION public.fn_dar_check_valid_until_future();

COMMENT ON FUNCTION public.fn_dar_check_valid_until_future() IS
  'fix_version=20260626_m5: bloqueia aprovacao com valid_until no passado SOMENTE na transicao -> approved. NUNCA converter para CHECK persistente (quebraria vencimento natural). Migration: enforce_dar_valid_until_future_on_approval.';

-- <<< END 20260626123517_enforce_dar_valid_until_future_on_approval.sql <<<

-- >>> BEGIN 20260626123656_forbid_dar_reopen_to_pending.sql >>>
-- Melhoria M6: máquina de estados — uma vez fora de 'pending', a solicitação não retorna.
-- App nunca reabre (decisões: approved/rejected; expired reservado). Para re-decidir, cria-se
-- nova solicitação (consistente com M4: nasce pending). Elimina o ponto cego de auditoria do
-- re-open: a transição simplesmente deixa de existir. Provado via dry-run (210 cenários).
CREATE OR REPLACE FUNCTION public.fn_dar_forbid_reopen()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $fn$
BEGIN
  -- fix_version=20260626_m6 | ANTI-REGRESSAO: manter o bloqueio terminal->pending.
  IF NEW.status = 'pending' AND OLD.status IS DISTINCT FROM 'pending' THEN
    RAISE EXCEPTION 'discount_approval_requests nao pode retornar para pending a partir de % (re-open proibido; crie nova solicitacao)', OLD.status
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$fn$;

DROP TRIGGER IF EXISTS trg_dar_forbid_reopen ON public.discount_approval_requests;
CREATE TRIGGER trg_dar_forbid_reopen
  BEFORE UPDATE ON public.discount_approval_requests
  FOR EACH ROW EXECUTE FUNCTION public.fn_dar_forbid_reopen();

COMMENT ON FUNCTION public.fn_dar_forbid_reopen() IS
  'fix_version=20260626_m6: proibe terminal->pending (re-open). Para re-decidir crie nova solicitacao. Migration: forbid_dar_reopen_to_pending.';

-- <<< END 20260626123656_forbid_dar_reopen_to_pending.sql <<<

-- >>> BEGIN 20260626124225_add_is_primary_color_equivalences_resolution.sql >>>
-- ============================================================================
-- MELHORIA 1/3 — Resolucao deterministica de cor de fornecedor -> variacao Ouro
-- Camada: PRATA (color_equivalences). Resolve mapeamento ambiguo (1 cor->N variacoes)
-- ANTI-REGRESSAO (Lovable bot): NAO remover a coluna is_primary nem o indice
--   uq_color_equivalences_one_primary. Eles garantem 1 primaria ativa por cor.
-- fix_version: 2026-06-26_color_isprimary
-- ============================================================================

ALTER TABLE color_equivalences
  ADD COLUMN IF NOT EXISTS is_primary boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN color_equivalences.is_primary IS
  'Equivalencia primaria/canonica desta supplier_color. Backfill por precedencia: '
  'match_quality(exact>close>approximate) > confidence_score DESC > internal_code num ASC > id. '
  'Garantido <=1 ativa por supplier_color via uq_color_equivalences_one_primary. '
  'fix_version 2026-06-26 - NAO REMOVER (anti-regressao).';

WITH ranked AS (
  SELECT ce.id,
    ROW_NUMBER() OVER (
      PARTITION BY ce.supplier_color_id
      ORDER BY
        (CASE ce.match_quality WHEN 'exact' THEN 1 WHEN 'close' THEN 2
                               WHEN 'approximate' THEN 3 ELSE 4 END) ASC,
        ce.confidence_score DESC NULLS LAST,
        COALESCE(NULLIF(split_part(cv.internal_code,'.',1),'')::int, 9999) ASC,
        COALESCE(NULLIF(split_part(cv.internal_code,'.',2),'')::int, 9999) ASC,
        ce.id ASC
    ) AS rn
  FROM color_equivalences ce
  JOIN color_variations cv ON cv.id = ce.promo_variation_id
  WHERE ce.is_active
)
UPDATE color_equivalences ce
SET is_primary = true
FROM ranked r
WHERE ce.id = r.id AND r.rn = 1;

CREATE UNIQUE INDEX IF NOT EXISTS uq_color_equivalences_one_primary
  ON color_equivalences (supplier_color_id)
  WHERE (is_primary AND is_active);

COMMENT ON INDEX uq_color_equivalences_one_primary IS
  'Garante <=1 equivalencia primaria ATIVA por supplier_color. fix_version 2026-06-26. NAO REMOVER.';

NOTIFY pgrst, 'reload schema';

-- <<< END 20260626124225_add_is_primary_color_equivalences_resolution.sql <<<

-- >>> BEGIN 20260626124627_sync_color_variations_dual_fk_and_notnull.sql >>>
-- ============================================================================
-- MELHORIA 2/3 — Elimina debito da dupla FK em color_variations (camada OURO)
-- group_id (legado, NOT NULL) e color_group_id (canonico) sao espelhados por
-- trigger BEFORE: preenche o que falta, propaga update de coluna unica e BLOQUEIA
-- divergencia genuina. color_group_id passa a NOT NULL.
-- ANTI-REGRESSAO (Lovable bot): NAO remover fn_sync_color_variation_group nem o
--   trigger trg_sync_color_variation_group; NAO reverter color_group_id p/ NULLABLE.
-- fix_version: 2026-06-26_color_dualfk_sync
-- ============================================================================

CREATE OR REPLACE FUNCTION fn_sync_color_variation_group()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public           -- anti-regressao: NAO remover search_path
AS $fn$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.color_group_id IS DISTINCT FROM OLD.color_group_id
       AND NEW.group_id IS NOT DISTINCT FROM OLD.group_id THEN
      NEW.group_id := NEW.color_group_id;           -- canonico mudou -> espelha legado
    ELSIF NEW.group_id IS DISTINCT FROM OLD.group_id
       AND NEW.color_group_id IS NOT DISTINCT FROM OLD.color_group_id THEN
      NEW.color_group_id := NEW.group_id;           -- legado mudou -> espelha canonico
    END IF;
  END IF;
  IF NEW.color_group_id IS NULL AND NEW.group_id IS NOT NULL THEN
    NEW.color_group_id := NEW.group_id;
  ELSIF NEW.group_id IS NULL AND NEW.color_group_id IS NOT NULL THEN
    NEW.group_id := NEW.color_group_id;
  ELSIF NEW.group_id IS NOT NULL AND NEW.color_group_id IS NOT NULL
        AND NEW.group_id <> NEW.color_group_id THEN
    RAISE EXCEPTION 'color_variations: group_id(%) <> color_group_id(%) — divergencia bloqueada (fn_sync_color_variation_group)',
      NEW.group_id, NEW.color_group_id;
  END IF;
  RETURN NEW;
END;
$fn$;

COMMENT ON FUNCTION fn_sync_color_variation_group() IS
  'Mantem group_id (legado) e color_group_id (canonico) sempre identicos em color_variations. '
  'fix_version 2026-06-26 - anti-regressao, NAO REMOVER.';

DROP TRIGGER IF EXISTS trg_sync_color_variation_group ON color_variations;
CREATE TRIGGER trg_sync_color_variation_group
  BEFORE INSERT OR UPDATE OF group_id, color_group_id ON color_variations
  FOR EACH ROW EXECUTE FUNCTION fn_sync_color_variation_group();

ALTER TABLE color_variations ALTER COLUMN color_group_id SET NOT NULL;

NOTIFY pgrst, 'reload schema';

-- <<< END 20260626124627_sync_color_variations_dual_fk_and_notnull.sql <<<

