-- >>> BEGIN 20260626130000_backfill_ordem_exibicao_curated_order_tpgo.sql >>>
-- Migration: backfill ordem_exibicao on tabela_preco_gravacao_oficial to CURATED catalog order
-- Date: 2026-06-26
-- Supersedes the initial alphabetical backfill from
--   20260626120000_add_ordem_exibicao_tabela_preco_gravacao_oficial.sql
--
-- Context: ordem_exibicao drives the technique-list UI (read via the 'tecnica_gravacao' bridge alias,
-- ORDER BY ordem_exibicao in useTecnicasList / fetchPromobrindTechniques). The initial backfill ordered
-- rows purely alphabetically by codigo_tabela, which ignored the curated display order already defined in
-- tecnicas_gravacao.ordem_exibicao (16 techniques, distinct values 10..100 with deliberate gaps).
-- This migration re-backfills every row to honor the parent technique's curated order
-- (joined via grupo_tecnica = tecnicas_gravacao.codigo), then codigo_tabela within each group.
-- Deterministic and idempotent: the WHERE ... IS DISTINCT FROM guard makes a re-run a no-op.

WITH ranked AS (
  SELECT t.id,
         row_number() OVER (ORDER BY g.ordem_exibicao, t.codigo_tabela, t.id) AS new_ord
  FROM public.tabela_preco_gravacao_oficial t
  JOIN public.tecnicas_gravacao g ON g.codigo::text = t.grupo_tecnica::text
)
UPDATE public.tabela_preco_gravacao_oficial t
SET ordem_exibicao = ranked.new_ord
FROM ranked
WHERE ranked.id = t.id
  AND t.ordem_exibicao IS DISTINCT FROM ranked.new_ord;

COMMENT ON COLUMN public.tabela_preco_gravacao_oficial.ordem_exibicao IS
'ANTI-REGRESSION (fix 2026-06-26): display order for the technique-list UI. Frontend reads this table via bridge alias tecnica_gravacao (dbInvoke BRIDGE_ALIASES) and ORDERs BY ordem_exibicao; column previously existed only on tecnicas_gravacao, causing PostgREST 400 (42703). NOT NULL DEFAULT 99 (intentionally STRICTER than tecnicas_gravacao.ordem_exibicao which is nullable - prevents ordering surprises). Values backfilled to honor the CURATED order: parent technique tecnicas_gravacao.ordem_exibicao (joined via grupo_tecnica=tecnicas_gravacao.codigo), then codigo_tabela within group. DO NOT DROP.';

-- <<< END 20260626130000_backfill_ordem_exibicao_curated_order_tpgo.sql <<<

-- >>> BEGIN 20260626142027_ensure_single_primary_color_equivalence_selfheal.sql >>>
-- ============================================================================
-- MELHORIA 4 — Auto-cura da equivalencia primaria (camada PRATA, color_equivalences)
-- Fecha o gap: ao desativar/rebaixar/excluir a primaria de uma supplier_color que
-- ainda tem equivalencias ativas, uma nova primaria e eleita pela MESMA precedencia
-- do backfill. Invariante: (>=1 ativa) => exatamente 1 primaria ativa.
-- Design robusto: BEFORE per-row (inativa nunca e primaria, so toca NEW -> sem erro
-- "tuple already modified") + AFTER FOR EACH STATEMENT (eleicao 1x no fim) + guarda
-- pg_trigger_depth() anti-recursao. Reassignment de primaria deve ser atomico/set-based.
-- ANTI-REGRESSAO (Lovable bot): NAO remover estas funcoes/triggers nem o search_path.
-- fix_version: 2026-06-26_color_primary_selfheal
-- ============================================================================

CREATE OR REPLACE FUNCTION fn_color_equiv_clear_primary_on_inactive()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $fn$
BEGIN
  IF NOT NEW.is_active THEN NEW.is_primary := false; END IF;
  RETURN NEW;
END;$fn$;
COMMENT ON FUNCTION fn_color_equiv_clear_primary_on_inactive() IS
  'Garante que equivalencia inativa nunca seja is_primary. fix_version 2026-06-26 - anti-regressao, NAO REMOVER.';

DROP TRIGGER IF EXISTS trg_color_equiv_clear_primary_on_inactive ON color_equivalences;
CREATE TRIGGER trg_color_equiv_clear_primary_on_inactive
  BEFORE INSERT OR UPDATE OF is_primary, is_active ON color_equivalences
  FOR EACH ROW EXECUTE FUNCTION fn_color_equiv_clear_primary_on_inactive();

CREATE OR REPLACE FUNCTION fn_color_equiv_ensure_primary_stmt()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $fn$
DECLARE r record; v_best uuid;
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;  -- anti-recursao
  FOR r IN
    SELECT supplier_color_id AS sc FROM color_equivalences GROUP BY supplier_color_id
    HAVING count(*) FILTER (WHERE is_active) > 0
       AND count(*) FILTER (WHERE is_active AND is_primary) = 0
  LOOP
    SELECT ce.id INTO v_best
    FROM color_equivalences ce JOIN color_variations cv ON cv.id = ce.promo_variation_id
    WHERE ce.supplier_color_id = r.sc AND ce.is_active
    ORDER BY (CASE ce.match_quality WHEN 'exact' THEN 1 WHEN 'close' THEN 2
                                    WHEN 'approximate' THEN 3 ELSE 4 END),
             ce.confidence_score DESC NULLS LAST,
             COALESCE(NULLIF(split_part(cv.internal_code,'.',1),'')::int, 9999),
             COALESCE(NULLIF(split_part(cv.internal_code,'.',2),'')::int, 9999),
             ce.id
    LIMIT 1;
    IF v_best IS NOT NULL THEN
      UPDATE color_equivalences SET is_primary = true WHERE id = v_best;
    END IF;
  END LOOP;
  RETURN NULL;
END;$fn$;
COMMENT ON FUNCTION fn_color_equiv_ensure_primary_stmt() IS
  'Elege a equivalencia primaria (mesma precedencia do backfill) para supplier_colors com >=1 ativa e 0 primaria. fix_version 2026-06-26 - anti-regressao, NAO REMOVER.';

DROP TRIGGER IF EXISTS trg_color_equiv_ensure_primary_stmt ON color_equivalences;
CREATE TRIGGER trg_color_equiv_ensure_primary_stmt
  AFTER INSERT OR DELETE OR UPDATE OF is_primary, is_active, supplier_color_id ON color_equivalences
  FOR EACH STATEMENT EXECUTE FUNCTION fn_color_equiv_ensure_primary_stmt();

-- Reconciliacao defensiva idempotente
UPDATE color_equivalences SET is_primary = false WHERE is_primary AND NOT is_active;
DO $rec$
DECLARE r record; v_best uuid;
BEGIN
  FOR r IN SELECT supplier_color_id AS sc FROM color_equivalences GROUP BY supplier_color_id
           HAVING count(*) FILTER (WHERE is_active)>0 AND count(*) FILTER (WHERE is_active AND is_primary)=0
  LOOP
    SELECT ce.id INTO v_best FROM color_equivalences ce JOIN color_variations cv ON cv.id=ce.promo_variation_id
      WHERE ce.supplier_color_id=r.sc AND ce.is_active
      ORDER BY (CASE ce.match_quality WHEN 'exact' THEN 1 WHEN 'close' THEN 2 WHEN 'approximate' THEN 3 ELSE 4 END),
               ce.confidence_score DESC NULLS LAST,
               COALESCE(NULLIF(split_part(cv.internal_code,'.',1),'')::int,9999),
               COALESCE(NULLIF(split_part(cv.internal_code,'.',2),'')::int,9999), ce.id LIMIT 1;
    IF v_best IS NOT NULL THEN UPDATE color_equivalences SET is_primary=true WHERE id=v_best; END IF;
  END LOOP;
END $rec$;

-- <<< END 20260626142027_ensure_single_primary_color_equivalence_selfheal.sql <<<

-- >>> BEGIN 20260626152341_harden_product_variants_stock_nonneg.sql >>>
-- Guardas de integridade de estoque em product_variants (estoque negativo é sem sentido em catálogo B2B).
-- stock_quantity: lido pela vitrine; CHECK alcançável (nenhum trigger sobrescreve estoque de variante ATIVA;
--   fn_enforce_inactive_variant_zero_stock só zera inativos).
-- next_quantity_1..6: quantidades de reposição futura; CHECK alcançável quando pareadas com next_date futura
--   (trg_fn_sanitize_restock_dates anula órfãos e janelas passadas).
-- next_entry_quantity NÃO recebe CHECK: é derivado (:= next_quantity_1) por fn_sync_product_variants_next_entry,
--   portanto guardar next_quantity_1 já o cobre — evita constraint redundante que poderia travar UPDATEs.
-- Verificado empiricamente: 0 violações em 18.580 variantes; dry-run adversarial 7/7 OK.
ALTER TABLE public.product_variants
  ADD CONSTRAINT chk_pv_stock_quantity_nonneg CHECK (stock_quantity >= 0),
  ADD CONSTRAINT chk_pv_next_quantities_nonneg CHECK (
    next_quantity_1 >= 0 AND next_quantity_2 >= 0 AND next_quantity_3 >= 0
    AND next_quantity_4 >= 0 AND next_quantity_5 >= 0 AND next_quantity_6 >= 0);

-- <<< END 20260626152341_harden_product_variants_stock_nonneg.sql <<<

-- >>> BEGIN 20260626152810_harden_discount_approval_requests_grants.sql >>>
-- Defesa-em-profundidade na própria tabela discount_approval_requests (dado interno vendedor/admin).
-- As 4 RLS policies são TO authenticated => anon já não enxerga linhas; aqui removemos o grant
-- residual de tabela do anon (default do Supabase) e REFERENCES/TRIGGER do authenticated, ficando
-- consistente com o hardening já feito em quotes, quote_approval_tokens e discount_approval_audit (M2).
-- authenticated MANTÉM SELECT/INSERT/UPDATE/DELETE (gateados por RLS); service_role MANTÉM ALL.
-- Obs.: TRIGGER/REFERENCES são privilégios de CRIAR trigger/FK — revogá-los NÃO afeta triggers já
-- existentes (auditoria/notify/M1-M6 seguem disparando normalmente).
REVOKE ALL ON public.discount_approval_requests FROM anon;
REVOKE REFERENCES, TRIGGER ON public.discount_approval_requests FROM authenticated;

-- <<< END 20260626152810_harden_discount_approval_requests_grants.sql <<<

